test "archive scope admits only canonical cwd beneath the exact root boundary" {
    const parsed = maru.session.agent_session_archive.Parsed{
        .provider = .codex,
        .session_id = @constCast("session"),
        .title = @constCast("title"),
        .summary = @constCast("summary"),
        .cwd = @constCast("/workspace/project/src"),
        .cwd_canonical = true,
        .model = @constCast("model"),
        .message_count = 1,
        .verified_user = true,
    };
    const record = agent_session_archive_backend.Record{
        .parsed = parsed,
        .source_path = @constCast("/source.jsonl"),
        .mtime_ns = 0,
        .inode = 0,
        .device = 0,
    };
    try std.testing.expect(agent_dock.agentSessionArchiveWithinRoot(record, "/workspace/project"));
    try std.testing.expect(!agent_dock.agentSessionArchiveWithinRoot(record, "/workspace/project-old"));
    var unresolved = record;
    unresolved.parsed.cwd_canonical = false;
    try std.testing.expect(!agent_dock.agentSessionArchiveWithinRoot(unresolved, "/workspace/project"));
}

// 방향 토글은 표시 계층에만 있다. 스캔 순서와 정렬 키는 건드리지 않으므로 `SortOrder`가 두 label과
// 왕복 하나만 책임진다 — 이게 깨지면 버튼을 눌러도 같은 방향으로 되돌아온다.
test "정렬 방향 토글은 두 상태를 왕복한다" {
    const SortOrder = chrome.components.session_dock.types.SortOrder;
    try std.testing.expectEqual(SortOrder.oldest_first, SortOrder.newest_first.toggled());
    try std.testing.expectEqual(SortOrder.newest_first, SortOrder.oldest_first.toggled());
    // 라벨은 **키가 옳게 골라졌는가**를 본다 — 원문 문자열로 비교하면 언어 설정에 묶여, 이 테스트의
    // 주 검증(왕복)이 표시 언어 때문에 깨진다.
    try std.testing.expectEqualStrings(maru.i18n.t(.sd_sort_newest), SortOrder.newest_first.label());
    try std.testing.expectEqualStrings(maru.i18n.t(.sd_sort_oldest), SortOrder.oldest_first.label());
}

// 점진 발행은 빈 화면을 피하려는 것이므로, 보여 줄 목록이 이미 있으면 켜지 않는다. 특히 이전 스캔이
// 부분만 받고 취소된 뒤 재진입하는 경우 — 여기서 점진 경로를 타면 화면의 목록이 첫 부분 발행(12개)으로
// 덮여 **줄었다가 다시 차오른다**.
test "점진 발행은 보여 줄 목록이 하나도 없을 때만 요청한다" {
    try std.testing.expect(agent_dock.shouldRequestArchiveProgress(0));
    try std.testing.expect(!agent_dock.shouldRequestArchiveProgress(1));
    // 취소로 남은 부분 목록도 "보여 줄 목록"이다.
    try std.testing.expect(!agent_dock.shouldRequestArchiveProgress(12));
}

test "archive snapshot replacement preserves selection only for the exact source identity" {
    const base = maru.session.agent_session_archive.Parsed{
        .provider = .codex,
        .session_id = @constCast("selected"),
        .title = @constCast("title"),
        .summary = @constCast("summary"),
        .cwd = @constCast("/workspace/project"),
        .cwd_canonical = true,
        .model = @constCast("model"),
        .message_count = 1,
        .verified_user = true,
    };
    const selected = agent_session_archive_backend.Record{
        .parsed = base,
        .source_path = @constCast("/archive/selected.jsonl"),
        .mtime_ns = 0,
        .inode = 7,
        .device = 11,
    };
    var replacement = [_]agent_session_archive_backend.Record{
        .{ .parsed = .{ .provider = .claude, .session_id = @constCast("other"), .title = @constCast("title"), .summary = @constCast("summary"), .cwd = @constCast("/workspace/project"), .cwd_canonical = true, .model = @constCast("model"), .message_count = 1, .verified_user = true }, .source_path = @constCast("/archive/other.jsonl"), .mtime_ns = 0, .inode = 8, .device = 11 },
        selected,
    };
    try std.testing.expectEqual(@as(?usize, 1), agent_dock.archiveSnapshotSelectionIndex(&selected, &replacement));
    replacement[1].inode = 9;
    try std.testing.expect(agent_dock.archiveSnapshotSelectionIndex(&selected, &replacement) == null);
}

test "archive scroll identity rejects same path or mtime when the exact source identity changed" {
    const record = agent_session_archive_backend.Record{
        .parsed = .{ .provider = .claude, .session_id = @constCast("session-a"), .title = @constCast("title"), .summary = @constCast("summary"), .cwd = @constCast("/workspace/project"), .cwd_canonical = true, .model = @constCast("model"), .message_count = 1, .verified_user = true },
        .source_path = @constCast("/archive/current.jsonl"),
        .mtime_ns = 42,
        .inode = 7,
        .device = 11,
    };
    const identity = agent_dock.ArchiveScrollIdentity.fromRecord(&record);
    try std.testing.expect(identity.eqlRecord(&record));
    var changed = record;
    changed.mtime_ns = 99;
    try std.testing.expect(identity.eqlRecord(&changed));
    changed.inode = 8;
    try std.testing.expect(!identity.eqlRecord(&changed));
    changed = record;
    changed.parsed.session_id = @constCast("session-b");
    try std.testing.expect(!identity.eqlRecord(&changed));
}

// 걸린 그룹은 host만 구할 수 있다 — 가상화 창 밖일 수 있어서다. 골든은 이 산술을 못 본다(Lab이
// props를 손으로 채운다). 그래서 여기 단위 판정자를 둔다.
test "sticky group is the last one at or above the offset, with the next one as its pusher" {
    // group(20) card(50) card(50) group(20) card(50), gap 10 → tops = 0, 30, 90, 150, 180.
    const entries = [_]agent_session_archive_view.Entry{
        .{ .group = 0 }, .{ .card = 0 }, .{ .card = 1 }, .{ .group = 1 }, .{ .card = 2 },
    };
    const items = agent_dock.ArchiveScrollItems{ .entries = &entries, .group_h_px = 20, .card_h_px = 50, .gap_px = 10 };

    // 첫 그룹에 닿기 전은 없다 — 첫 그룹의 top이 0이라 offset 0부터 이미 걸려 있다.
    const at_top = agent_dock.archiveStickyGroupFor(items, 0).?;
    try std.testing.expectEqual(@as(usize, 0), at_top.index);
    try std.testing.expectEqual(@as(u32, 0), at_top.top_px);
    try std.testing.expectEqual(@as(?u32, 150), at_top.next_top_px);

    // 두 번째 그룹 직전까지는 여전히 첫 그룹이 걸려 있다.
    const before_second = agent_dock.archiveStickyGroupFor(items, 149).?;
    try std.testing.expectEqual(@as(usize, 0), before_second.index);

    // top과 정확히 같은 offset부터 두 번째 그룹으로 넘어간다. 마지막이므로 밀어내는 것이 없다.
    const second = agent_dock.archiveStickyGroupFor(items, 150).?;
    try std.testing.expectEqual(@as(usize, 3), second.index);
    try std.testing.expectEqual(@as(u32, 150), second.top_px);
    try std.testing.expectEqual(@as(?u32, null), second.next_top_px);

    // 그룹이 하나도 없으면 고정할 것이 없다.
    const cards_only = [_]agent_session_archive_view.Entry{ .{ .card = 0 }, .{ .card = 1 } };
    try std.testing.expect(agent_dock.archiveStickyGroupFor(.{ .entries = &cards_only, .group_h_px = 20, .card_h_px = 50, .gap_px = 10 }, 40) == null);

    // 첫 항목이 카드면 그 위에는 그룹이 없다 — offset이 첫 그룹 top보다 작으면 null이다.
    const card_first = [_]agent_session_archive_view.Entry{ .{ .card = 0 }, .{ .group = 0 }, .{ .card = 1 } };
    const late = agent_dock.ArchiveScrollItems{ .entries = &card_first, .group_h_px = 20, .card_h_px = 50, .gap_px = 10 };
    try std.testing.expect(agent_dock.archiveStickyGroupFor(late, 59) == null);
    try std.testing.expectEqual(@as(usize, 1), agent_dock.archiveStickyGroupFor(late, 60).?.index);
}

test "archive scroll anchor restores only the exact materialized card after reorder" {
    const records = [_]agent_session_archive_backend.Record{
        .{ .parsed = .{ .provider = .codex, .session_id = @constCast("anchored"), .title = @constCast("title"), .summary = @constCast("summary"), .cwd = @constCast("/workspace/a"), .cwd_canonical = true, .model = @constCast("model"), .message_count = 1, .verified_user = true }, .source_path = @constCast("/archive/a.jsonl"), .mtime_ns = 1, .inode = 7, .device = 11 },
        .{ .parsed = .{ .provider = .codex, .session_id = @constCast("other"), .title = @constCast("title"), .summary = @constCast("summary"), .cwd = @constCast("/workspace/b"), .cwd_canonical = true, .model = @constCast("model"), .message_count = 1, .verified_user = true }, .source_path = @constCast("/archive/b.jsonl"), .mtime_ns = 1, .inode = 8, .device = 11 },
    };
    const old_entries = [_]agent_session_archive_view.Entry{ .{ .group = 0 }, .{ .card = 0 }, .{ .card = 1 } };
    const old_items = agent_dock.ArchiveScrollItems{ .entries = &old_entries, .group_h_px = 20, .card_h_px = 50, .gap_px = 10 };
    const anchor = agent_dock.archiveScrollAnchorFor(&records, .{
        .content_height_px = 140,
        .max_offset_px = 80,
        .offset_y_px = 45,
        .first_index = 1,
        .first_origin_y_px = -15,
        .end_exclusive = 3,
    }, old_items).?;
    try std.testing.expectEqual(@as(u32, 15), anchor.intra_card_y_px);

    // 그룹 헤더가 뷰포트 위쪽 경계를 차지하면 anchor가 없다. 헤더는 세션 신원을 대신할 수 없어
    // 그것으로 복원하면 "어느 세션을 보고 있었는가"가 아니라 "어느 그룹 근처였는가"로 바뀐다.
    try std.testing.expect(agent_dock.archiveScrollAnchorFor(&records, .{
        .content_height_px = 140,
        .max_offset_px = 80,
        .offset_y_px = 5,
        .first_index = 0,
        .first_origin_y_px = -5,
        .end_exclusive = 3,
    }, old_items) == null);

    // 경계에 정확히 맞닿은 카드(원점 0)는 유효한 anchor다 — 그 지점이 사용자가 보고 있던 곳이다.
    // 변위가 0이라는 것이 "anchor가 없다"는 뜻은 아니다.
    const flush = agent_dock.archiveScrollAnchorFor(&records, .{
        .content_height_px = 140,
        .max_offset_px = 80,
        .offset_y_px = 30,
        .first_index = 1,
        .first_origin_y_px = 0,
        .end_exclusive = 3,
    }, old_items).?;
    try std.testing.expectEqual(@as(u32, 0), flush.intra_card_y_px);

    // 창의 **첫** 항목만 후보다. 두 번째 카드는 경계 아래에 있으므로, 첫 항목이 그룹 헤더라 건너뛰면
    // anchor는 없다(위 케이스). 아래처럼 첫 항목이 카드면 그 카드가 잡히고 다음 카드는 무시된다.
    const first_wins = agent_dock.archiveScrollAnchorFor(&records, .{
        .content_height_px = 140,
        .max_offset_px = 80,
        .offset_y_px = 45,
        .first_index = 1,
        .first_origin_y_px = -15,
        .end_exclusive = 3,
    }, old_items).?;
    try std.testing.expectEqual(@as(u32, 15), first_wins.intra_card_y_px);
    try std.testing.expect(first_wins.identity.eqlRecord(&records[0]));

    const reordered = [_]agent_session_archive_view.Entry{ .{ .group = 0 }, .{ .card = 1 }, .{ .card = 0 } };
    try std.testing.expectEqual(@as(?u32, 105), agent_dock.archiveScrollAnchorOffsetFor(&records, anchor, .{ .entries = &reordered, .group_h_px = 20, .card_h_px = 50, .gap_px = 10 }, 300));
    const collapsed = [_]agent_session_archive_view.Entry{.{ .group = 0 }};
    try std.testing.expect(agent_dock.archiveScrollAnchorOffsetFor(&records, anchor, .{ .entries = &collapsed, .group_h_px = 20, .card_h_px = 50, .gap_px = 10 }, 300) == null);
}

test "archive scope refresh detects same-pane cwd changes but ignores repeated observations" {
    try std.testing.expect(agent_dock.agentSessionArchiveObservedCwdChanged(null, "/workspace/a"));
    try std.testing.expect(!agent_dock.agentSessionArchiveObservedCwdChanged("/workspace/a", "/workspace/a"));
    try std.testing.expect(agent_dock.agentSessionArchiveObservedCwdChanged("/workspace/a", "/workspace/b"));
}

// 범위 칩(`현재 작업공간`·`현재 프로젝트`)의 cwd도 **소스 컨트롤·탐색기·사이드바와 같은 축**을 써야 한다.
// 예전에는 이 자리만 관측(OSC 7)을 직독해, 셸이 OSC 7을 안 보내는 Term에서 두 칩이 죽었다 — 셸 통합이 없는
// bash/fish는 상시, 이 도크에서 `이어하기`로 연 Term은 수명 내내 그랬다.
//
// **증상이 눈에 안 보인다는 점이 중요하다.** `scopeNode`는 `enabled`를 paint가 아니라 `action`에만 싣고
// (`build.zig`), hit-test는 `if (!action.enabled) return false`로 그냥 무시한다(`interaction.zig`). 즉 칩은
// 평소와 똑같이 보이는데 **눌러도 아무 일이 없다.** 그래서 published props의 `workspace_scope_enabled`까지
// 끝까지 확인한다 — 중간 상태(cwd를 안다)만 보면 "보이는데 안 눌리는" 그 상태를 놓친다.
test "아카이브 범위 칩: OSC 7이 없어도 커널 폴백으로 눌리는 칩이 된다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const a = std.testing.allocator;
    const session = try initSmokeSessionSized(a);
    defer a.destroy(session);
    defer session.deinit();

    const term = tab_ops.activeTab(session).activeTerm();
    try std.testing.expectEqual(@as(usize, 0), term.rt.observation.cwd.items.len); // 전제: OSC 7 미수신

    // 축이 답을 주는 환경인지 먼저 확인한다(권한 없음·죽은 pid면 판정할 것이 없다).
    var buf: [std.fs.max_path_bytes]u8 = undefined;
    const axis_cwd = git_ops.termCwd(session, term, &buf) orelse return error.SkipZigTest;

    agent_dock.requestAgentSessionArchiveScopeRoots(session, null);

    // 관측된 cwd가 축과 **같은 값**으로 선다. 예전에는 여기가 null이라 아래 루트들이 비워졌다.
    const observed = session.agent_session_archive_scope_observed_cwd orelse return error.ScopeCwdMissing;
    try std.testing.expectEqualStrings(axis_cwd, observed);
    try std.testing.expect(session.agent_session_archive_project_scope_loading); // job이 나갔다

    // backend가 canonicalize를 끝낼 때까지 결과만 소비한다(이 루프에 filesystem I/O는 없다).
    var attempts: usize = 0;
    while (session.agent_session_archive_workspace_root == null and attempts < 2_000) : (attempts += 1) {
        agent_dock.updateAgentSessionArchiveProjectScope(session);
        if (session.agent_session_archive_workspace_root == null)
            std.Io.sleep(session.io, std.Io.Duration.fromMilliseconds(1), .awake) catch {};
    }
    try std.testing.expect(session.agent_session_archive_workspace_root != null);

    // **렌더러가 실제로 읽는 값까지 본다.** 위 필드는 내부 상태이고, 칩이 눌리는지를 정하는 것은 published
    // props의 `workspace_scope_enabled`다(`agentSessionDockProps`가 그 필드에서 파생한다). 둘 사이에 게이트가
    // 하나라도 끼면 "루트는 섰는데 칩은 여전히 죽어 있는" 상태가 되므로 끝까지 확인한다.
    const props = agent_dock.agentSessionDockProps(
        session,
        .{ .x = 0, .y = 0, .w = 400, .h = 600 },
        .{ .content_height_px = 0, .max_offset_px = 0, .offset_y_px = 0, .first_index = 0, .first_origin_y_px = 0, .end_exclusive = 0 },
        &.{},
    );
    try std.testing.expect(props.workspace_scope_enabled);
}

test "archive relative age uses the worker mtime without filesystem access" {
    // 기대값이 한국어 문장이다 — 재는 것은 **어느 시간 단위를 고르는가**이고 그것은 문장으로 봐야
    // 드러난다(키 비교는 보간 결과를 다시 만들어 동어반복이 된다). 언어를 고정한다.
    const lang_before = maru.i18n.lang();
    defer maru.i18n.setLang(lang_before);
    maru.i18n.setLang(.ko);

    var buf: [32]u8 = undefined;
    try std.testing.expectEqualStrings("방금", agent_dock.formatAgentSessionArchiveRelativeAge(100, 200, &buf));
    try std.testing.expectEqualStrings("5분 전", agent_dock.formatAgentSessionArchiveRelativeAge(5 * 60 * std.time.ns_per_s, 0, &buf));
    try std.testing.expectEqualStrings("2시간 전", agent_dock.formatAgentSessionArchiveRelativeAge(2 * 60 * 60 * std.time.ns_per_s, 0, &buf));
}

// 세로 탭 사이드바의 기본 논리 폭(pt). backing 픽셀 폭은 scale을 곱해 구한다(refreshCellMetrics에서).
// 터미널 surface는 이 폭만큼 오른쪽으로 그려지고, 왼쪽 strip이 사이드바다("surface→rect" 첫 적용). 사용자가
// 우측 경계를 드래그해 바꾸면 `AppSession.sidebar_width_pt`(현재 폭, pt)가 [min,max]로 갱신된다 — pt로 들어
// DPI 변경(refreshCellMetrics)에도 살아남는다.
const default_sidebar_width_pt: u32 = 180;

// 사이드바 상단 헤더(검색바 + 사이드바 접기·view options·새 워크스페이스 아이콘) 높이 = cell 높이 × 3.0(아이콘 줄 +
// 검색 줄 + 패딩). 0이면 헤더 없음(하위호환). slot_height와 같은 단일 출처(cell 메트릭)에서 파생한다.
const sidebar_header_height_ratio_milli: u32 = 3000;
// 헤더 아이콘을 셀보다 크게 굽는 배율은 chrome 크기 토큰(`chrome.ui.icon`)이 소유한다 — 같은 1.7이
// 렌더러 quad(.m)에도 있어, 여기에 또 상수를 두면 세 곳이 어긋날 수 있다.
const header_icon_scale = chrome.ui.icon;

pub fn headerIconRasterExtentPx(cell_extent_px: u32) u32 {
    return header_icon_scale.cellRasterExtentPx(cell_extent_px);
}
// 사이드바 접힘 시 좌상단 펼치기 버튼이 신호등 오른쪽에서 비울 가로 여백(논리 pt). 신호등은 좌상단 ~70pt를 차지한다.
pub const traffic_light_clearance_pt: u32 = 72;
// 접힘 시 ◧ 펼치기 토글을 알림 종에서 오른쪽으로 띄우는 칸 수 — 펼침 헤더의 아이콘 간격(3칸)과 같게 둬 종↔◧이
// 같은 리듬으로 보인다(접힘에도 알림 아이콘 유지, 사용자 피드백). ◧ col = collapsedBellCol() + 이 값(종이 ◧ 왼쪽).
const collapsed_bell_gap_cells: u32 = 3;
// 접힘 시 상단 타이틀바 띠의 최소 높이(논리 pt) — 신호등 세로 높이(~28pt)를 가려야 터미널/탭이 신호등을 침범 안 함.
// 펼침은 한 줄(터미널이 사이드바 우측이라 신호등 아래가 아님)이지만, 접힘은 터미널이 전폭이라 신호등 높이를 확보한다.
const collapsed_titlebar_min_pt: u32 = 30;
// 펼침 시 상단 타이틀바 띠의 최소 높이(논리 pt). 한 줄(cell_height ~17pt)만 띠로 두면 네이티브 macOS 타이틀바
// (~28pt)보다 낮아 상단 드래그 영역이 좁게 느껴진다(사용자 피드백). 네이티브 높이를 바닥으로 잡아 드래그 영역을 맞춘다.
const titlebar_strip_min_pt: u32 = 28;

// 창 바닥 상태표시줄 높이(논리 pt, SB1). VSCode(22px)·Zed와 같은 급이고, 상단 타이틀바 띠(28pt)보다 낮게 둬
// 상/하단 chrome의 위계를 유지한다. **터미널 폰트에서 파생하지 않는다** — 도크 view bar가 그렇게 했다가
// 폰트를 키우면 같은 아이콘 줄이 오르내리는 회귀가 났고(실측 53px↔80px) 폰트 독립 pt로 옮겼다. 상태바는
// 창 전폭 chrome이라 같은 이유가 더 강하게 적용된다.
/// 소스 컨트롤 목록이 한 프레임에 다룰 수 있는 행 수. **스크롤 상한·렌더·hit-test가 같은 값을 써야**
/// 그리지 못하는 행이 스크롤 범위에 들어가지 않는다(SV3a 적대적 검증).
pub const scm_row_capacity: usize = 128;

/// 히스토리 첫 화면이 읽는 커밋 수. `더 보기`가 이만큼씩 늘린다.
///
/// 200인 이유: 한 화면이 20행 남짓이라 열 번을 스크롤해도 남고, `git log`가 그 정도는 밀리초 단위로
/// 낸다. 무제한으로 두면 오래된 저장소에서 수십 MB가 한 번에 온다.
pub const scm_log_limit_initial: u32 = 200;
// **치수는 중립 잎이 소유한다**(`maru.status_bar_metrics`). 여기 있던 동안 Windows 가 볼 수 없었고,
// 베끼면 "바 높이" 가 두 곳이 되어 한쪽만 고칠 때 두 OS 의 작업영역이 갈린다(그 파일 헤더가 근거).
const status_bar_metrics = maru.status_bar_metrics;
const status_bar_height_pt: u32 = status_bar_metrics.height_pt;
/// 상태바 좌/우 가장자리 안쪽 여백·항목 간격(논리 pt). 높이와 같은 이유로 폰트 독립이다.
const status_bar_edge_pad_pt: u32 = status_bar_metrics.edge_pad_pt;
const status_bar_gap_pt: u32 = status_bar_metrics.gap_pt;
/// 상태바 **상단 경계선** 두께(논리 pt). 배경 띠 **안쪽 맨 위**에 그으므로 `dock_layout`이 깎아 둔
/// 높이는 그대로다 — 선을 추가한다고 작업영역이 줄지 않는다.
const status_bar_border_pt: u32 = status_bar_metrics.border_pt;
/// 호버 배경이 항목 좌우로 넓어지는 여백(논리 pt, 한쪽). 글자에 딱 붙은 배경은 답답해 보인다.
/// **항목 간격(gap)보다 두 배 이상 작아야** 이웃 호버끼리 겹치지 않는다(4×2 < 12).
const status_bar_item_pad_pt: u32 = status_bar_metrics.item_pad_pt;
/// 상태바 텍스트 위아래 여백(논리 pt, 한쪽). 바 높이가 이 값으로 텍스트 행에서 파생된다 — 아래 참고.
const status_bar_v_pad_pt: u32 = status_bar_metrics.v_pad_pt;
/// 상태바 좌측 항목 상한. 지금은 브랜치·경로 둘이고, 늘릴 때 이 값과 우선순위 순서를 함께 본다.
const max_status_bar_left_items: usize = 2;
/// 상태바 우측 항목 상한.
// blocked·running·알림 + 편집기 **넷**(커서 위치·저하·읽기 전용·줄바꿈) + 리소스. 편집기 넷은
// 활성 pane이 편집기일 때만 실리므로 평소에는 넷만 쓴다.
// 편집기 커서 위치가 더해지며 **여덟**이 됐다(2026-08-21). 안 올리면 마지막 후보(리소스)가 폭과
// **무관하게** 사라진다 — 실측으로 2,500px가 남은 채로 빠졌고, 그것은 `status-bar.md` §3이 정한
// 폭 규칙이 아니라 배열 상한이라 화면만 봐서는 "폭이 모자랐나 보다"로 읽힌다(그 문서가 금지한
// 조용한 절단이다). **후보 원장에서 되짚어** 다음 항목이 붙을 때 이 값을 잊지 못하게 한다.
const max_status_bar_right_items: usize = chrome.components.status_bar.right_candidates.len;

// 런타임 폰트 크기 조절(⌘+/⌘-/⌘0). step = ⌘+/⌘- 한 번에 1pt(Ghostty 기본과 동일). 클램프 범위는 보수적으로
// [6, 72]pt — appearance resolver는 [1,512]를 허용하지만 6pt 미만은 글자가 안 읽히고 72pt 초과는 grid가
// 1~2칸으로 무너져 런타임 UX로는 부적절하다(config 파일로는 그 밖 값도 가능, 단축키·세팅 GUI 슬라이더가 이 범위).
// theme.font_size_min/max(세팅 슬라이더 range)와 **같은 값** — 단축키·GUI가 한 범위를 공유한다(drift 시 둘 다 갱신).
pub const font_size_min: f32 = 6.0;
pub const font_size_max: f32 = 72.0;
// ⌘+/⌘- 한 번에 바꾸는 폰트 크기 보폭(pt). Terminal.app·iTerm2·Ghostty처럼 **고정 1pt** — 설정 항목으로 두지
// 않는다(보폭값은 화면에 즉각 반영이 안 보여 슬라이더로 노출하면 혼란만 준다). ⌘0 reset은 보폭과 무관하게
// base_font_size로 복귀.
const font_size_step: f32 = 1.0;

// fade(자동 흐려짐) — 스크롤(view_offset 변화) 후 visible_ms 동안 full, 이어 fade_ms 동안 idle(faint)로
// 흐려진다. 숨기지 않고 faint로만 남겨(위치·잡을 곳을 잃지 않게) macOS overlay 관례를 따른다.
pub const scrollbar_visible_ms: u32 = 1667; // 옛 30Hz 50틱과 같은 약 1.67s full 유지
pub const scrollbar_fade_ms: u32 = 450; // 옛 30Hz 14틱과 같은 약 0.45s 동안 full→faint
pub const scrollbar_alpha_full: u8 = 0xFF; // 활성/hover/드래그

/// 상태바 리소스 표본 주기. 에이전트 폴링(0.5s)보다 **느리게** 둔다 — 메모리·CPU는 초 단위로 움직이고,
/// 더 자주 재도 사람이 못 읽는다(docs/status-bar.md §6 "비용과 게이트").
const resource_poll_interval_ms: u32 = 1000;
/// 한 Term 트리에서 가져올 표본 상한. 폭주 방어 — fork 폭탄이나 깊은 트리가 tick을 붙잡지 않게 한다.
const max_resource_samples_per_term: usize = 48;
/// 리소스 팝오버가 띄우는 최대 행 수(= 최대 Term 수). 라벨은 공유 버퍼(`context_menu_items_buf`)를 쓰므로
/// 그 크기를 넘으면 버퍼 밖에 쓴다 — 아래 comptime이 그걸 막는다. 넘치는 탭은 무거운 순 상위만 보인다.
const max_resource_rows: usize = 12;
/// 한 행 문자열의 바이트 상한. `탭 › 팬`(UTF-8, 한 글자 최대 3바이트) + 고정 폭 숫자 + 구분자.
const resource_row_max_bytes: usize = 256;
/// 행에서 **이름이 쓸 수 있는 표시 칸**. 숫자 열은 고정 폭이라(§4.1) 이름만 예산을 먹는다. 넘치면 EAW 절단.
const resource_row_name_cols: u32 = 28;
/// 팝오버 앞머리의 **고를 수 없는** 줄 수: ⓪ 제목+합계 ① 열 이름. 레퍼런스 화면이 그 둘을 가졌고,
/// 없으면 우클릭 메뉴 한 줄과 구별되지 않는다(사용자 지적). 선택·클릭·강조가 이 줄들을 건너뛴다.
pub const resource_header_rows: usize = 2;
/// 팝오버 **꼬리**의 고를 수 없는 줄 수: 세션 호스트 한 줄 + 앱 자신 한 줄. 탭 행과 섞지 않는다 —
/// 무거운 순 정렬에 넣으면 값에 따라 떠다니고 행 상한에 걸려 사라지는데, 둘 다 "항상 있으면 항상 보여야"
/// 하는 종류다(§4.1). 클릭 대상도 없다(점프할 탭이 없다) — 그래서 머리글과 같이 **선택 불가**다.
///
/// ⚠️ 이 상수는 **버퍼 크기**이지 그때그때의 꼬리 수가 아니다. 실제로 서는 꼬리는 0·1·2 전부 가능하므로
/// (앱 표본 실패·host 미연결) `showWithFooters`에는 **센 값**을 넘긴다 — 상수를 넘기면 살아 있는 탭 행이
/// 선택 불가가 된다(`resource_usage.partitionPinned`가 그 산술을 소유하고 테스트가 단언한다).
const resource_footer_rows: usize = 2;
/// 앱 자신 행의 그룹 키. Term surface_id와 절대 겹치지 않아야 해서 최대값을 센티넬로 쓴다 — id는 1부터
/// 증가하며 재사용하지 않으므로(session-local) 이 값에 도달하지 않는다.
const resource_app_key: u64 = std.math.maxInt(u64);
/// 세션 호스트 데몬 행의 그룹 키. 앱 키 바로 아래를 쓴다(같은 이유로 surface_id와 안 겹친다).
const resource_host_key: u64 = std.math.maxInt(u64) - 1;
/// 한 번에 셀 host 데몬 수. 보통 1이고, **업그레이드 중에만** 구/신 host가 잠깐 함께 산다
/// (docs/session-host-upgrade.md §5). 여유를 조금 두되 상한을 둔다 — 이 배열은 Term 표본과 같은
/// 고정 버퍼를 나눠 쓰므로 무한정 가져가면 탭 표본이 밀린다. 여럿이면 한 행에 **합계**로 나온다.
const max_resource_host_samples: usize = 4;
/// 팝오버 꼬리에 붙는 고정 행의 키 — **여기 적힌 순서가 화면 순서**다(세션 호스트 → 앱). 표본을 얻은
/// 순서로 두면 같은 화면이 실행마다 위아래가 바뀐다.
const resource_pinned_keys = [_]u64{ resource_host_key, resource_app_key };
comptime {
    if (resource_pinned_keys.len != resource_footer_rows)
        @compileError("pinned resource keys must match resource_footer_rows");
}
/// 에이전트 팝오버가 띄우는 최대 행 수. 리소스와 같은 공유 라벨 버퍼(`context_menu_items_buf`)를 쓰므로
/// 같은 급의 상한과 comptime 가드를 둔다. 넘치면 정렬 순 상위만 보인다.
const max_agent_rows: usize = 12;
/// 에이전트 팝오버 앞머리의 **고를 수 없는** 줄 수: ⓪ 제목+개수 ① 열 이름. 리소스 팝오버(§4.2)와 같은 형태다 —
/// 없으면 우클릭 메뉴 한 줄과 구별되지 않는다.
pub const agent_header_rows: usize = 2;
/// 에이전트 행에서 **이름이 쓸 수 있는 표시 칸**. "마지막 활동" 열이 고정 폭이라 이름만 예산을 먹는다.
const agent_row_name_cols: u32 = 24;
/// "마지막 활동" 열의 머리글 문자열. 폭의 **단일 출처**다 — 아래 `agentAgeCols()`가 이걸로부터 나온다.
fn agentAgeHeader() []const u8 {
    return maru.i18n.t(.app_last_activity);
}
/// 값 열 폭(표시 칸) = **머리글 폭**. 값을 이 폭 안에서 오른쪽 정렬하면 값과 열 이름과 제목의 개수가
/// 모두 **같은 칸에서 끝난다**. 상수를 따로 박으면(예전 8) 머리글(11칸)보다 좁아 열이 어긋난다 —
/// 리소스 팝오버가 `formatHeader`로 푼 것과 같은 문제이고, 여기서는 폭을 머리글에서 파생시켜 푼다.
/// **상수가 아니라 함수다.** 폭이 머리글에서 나오는데 그 머리글이 이제 언어를 따르므로, 값을 한 번
/// 계산해 박으면 언어가 바뀔 때 열이 어긋난다(계약 §6.1 — 폭을 상수로 박지 않는다).
fn agentAgeCols() u32 {
    return chrome.components.overlay_input.displayCols(agentAgeHeader());
}

/// 앱 자신 행 라벨. **"모든 창 공유"를 이름에 박는다** — 창이 여럿이면 각 창이 같은 값을 보여주므로,
/// 두 창의 숫자를 더하면 이중으로 잡힌다는 사실이 화면에서 드러나야 한다(§4.1의 남는 결함).
fn resourceAppLabel() []const u8 {
    return maru.i18n.t(.app_shared_all_windows);
}

fn resourceHostLabel() []const u8 {
    return maru.i18n.t(.app_session_host_shared);
}

/// `bytes`를 표시 칸 `max_cols` 안으로 줄여 `buf`에 쓴다(EAW 기준 — 한글 한 자 2칸). 넘치면 끝에 `…`.
/// `overlay_input.truncateToCols`는 arena를 받는데 여기는 tick 경로라 할당을 피한다 — 같은 규칙을 버퍼에 쓴다.
fn truncateColsInto(buf: []u8, bytes: []const u8, max_cols: u32) []const u8 {
    if (chrome.components.overlay_input.displayCols(bytes) <= max_cols) {
        const n = @min(bytes.len, buf.len);
        @memcpy(buf[0..n], bytes[0..n]);
        return buf[0..n];
    }
    if (max_cols == 0) return buf[0..0];
    const budget = max_cols - 1; // `…` 1칸
    const view = std.unicode.Utf8View.init(bytes) catch return buf[0..0];
    var it = view.iterator();
    var cols: u32 = 0;
    var end: usize = 0;
    while (it.nextCodepoint()) |cp| {
        const w = @max(1, maru.terminal.width.cellWidth(cp));
        if (cols + w > budget) break;
        cols += w;
        end = it.i;
    }
    const n = @min(end, buf.len -| 3);
    @memcpy(buf[0..n], bytes[0..n]);
    const ell = "\u{2026}";
    if (n + ell.len <= buf.len) {
        @memcpy(buf[n..][0..ell.len], ell);
        return buf[0 .. n + ell.len];
    }
    return buf[0..n];
}

/// `src`를 `dst`에 담기는 만큼만 복사하고 쓴 바이트 수를 돌려준다(고정 버퍼 조립용 — 넘치면 자른다).
fn copyClamped(dst: []u8, src: []const u8) usize {
    const n = @min(dst.len, src.len);
    @memcpy(dst[0..n], src[0..n]);
    return n;
}
/// 팝오버가 **열려 있는 동안**의 표본 주기. 닫힘(1초)보다 당긴다 — 열어 두고 보는데 값이 안 변하면 멈춘 줄 안다.
/// 더 당기지 않는 이유: CPU%는 차분이라 창이 짧을수록 값이 튀고, 사람이 못 읽는 속도로 재면 syscall만 는다.
const resource_open_poll_interval_ms: u32 = 500;

/// 단조 시계(ms). CPU%는 차분이라 **tick 개수가 아니라 벽시계**로 재야 한다 — 프레임 루프가 흔들리면
/// `ticks/hz`가 실제 경과와 어긋나고, 하필 머신이 바쁠 때(= 사용자가 CPU%를 보는 때) 틀린다.
/// Zig 0.16은 `std.time.Timer`·`nanoTimestamp`가 없다(src/session/control_bridge.zig `monotonicMs`와 같은 관례).
fn monotonicMs() u64 {
    var ts: std.c.timespec = undefined;
    _ = std.c.clock_gettime(.MONOTONIC, &ts);
    return @as(u64, @intCast(ts.sec)) * 1000 + @as(u64, @intCast(ts.nsec)) / std.time.ns_per_ms;
}
/// codex 후보를 **몇 개까지 열어** 신원을 확인할지. 서브에이전트가 같은 계층에 섞이므로(실측 최근 40개 중 32개)
/// 하나만 보면 못 찾는다. 20이면 그 밀도보다 작아 서브에이전트를 대량으로 돌린 직후 사용자 세션이 후보 밖으로
/// 밀렸다(code-review max) — 관측된 밀도(80%)에 여유를 둬 48로 잡는다. 매핑이 잡히면 mtime이 바뀔 때만 다시
/// 훑으므로 이 상한이 상시 비용은 아니다.
const codex_candidate_probe_limit: usize = 48;
/// 같은 cwd에서 이미 매핑된 형제 Term 파일을 몇 개까지 모을지(충돌 회피용). 한 워크스페이스에서 이보다 많은
/// 에이전트를 같은 디렉터리에 돌리는 경우는 실질적으로 없고, 넘으면 그 이상은 그냥 충돌 회피 대상에서 빠진다.
const transcript_sibling_scan_limit: usize = 8;
/// 세션 기록이 Term의 마지막 출력보다 이만큼 넘게 과거면 그 Term이 쓴 기록으로 보지 않는다. 에이전트는 출력 직전·직후에
/// 기록을 쓰므로 정상 세션의 간격은 초 단위다 — 넉넉히 잡아도 "방금 띄운 에이전트가 몇 분 전 세션을 무는" 것은 막힌다.
const transcript_staleness_grace_ns: i96 = 60 * std.time.ns_per_s;
/// codex `session_meta`(첫 레코드)를 찾는 데 읽는 앞부분 크기.
const codex_head_bytes: usize = 64 * 1024;
// synchronized output(DECSET 2026) ESU-유실 복구 deadline. BSU(2026h) 후 ESU(2026l)가
// 영영 안 오면(앱 크래시·SSH 끊김·버그) frame 투영이 무한정 막혀 화면이 freeze되므로, 이 한도를 넘는 hold는
// sync를 강제 해제하고 투영한다. 베이스: ESU-유실 안전장치(Ghostty termio sync_reset_ms=1000·xterm.js
// SYNCHRONIZED_OUTPUT_TIMEOUT_MS=1000과 같은 1초 timeout) — 정상 ESU 흐름엔 영향 없다.
const sync_timeout_ms: u32 = 1000;

fn ticksForMsAtRate(ms: u32, hz: u32) u32 {
    const safe_hz = @max(1, hz);
    const ticks = (@as(u64, ms) * @as(u64, safe_hz) + 500) / 1000;
    return @max(1, @as(u32, @intCast(ticks)));
}

fn clampFrameRateHz(hz: u32) u32 {
    return @min(config_mod.theme.render_frame_rate_max, @max(config_mod.theme.render_frame_rate_min, hz));
}

pub const default_scrollbar_visible_ticks: u32 = ticksForMsAtRate(scrollbar_visible_ms, config_mod.theme.render_frame_rate_default);
pub const default_scrollbar_fade_ticks: u32 = ticksForMsAtRate(scrollbar_fade_ms, config_mod.theme.render_frame_rate_default);

/// 탐색기 스크롤바 치수(SV2b). 옛 `components/file_tree_scrollbar.zig`가 들고 있던 값을 그대로 옮겼다 —
/// 그 모듈은 기능이 전부 `chrome/ui/scroll_area.zig`에 있어 이 슬라이스에서 지웠다.
pub const dock_list_scrollbar_width_px: u32 = 8;
/// 막대 폭 + 이 값 = **거터**이고, 거터가 곧 잡는 폭이다(`ScrollbarGeometry.hit_w`). 막대는 그 안에
/// 가운데로 뜬다.
///
/// 예전엔 3이라 거터가 11px, 2× 화면에서 5.5pt였고 실제로 잡히는 것은 막대 8px(4pt ≈ 1mm)뿐이었다 —
/// 보이는 띠를 정확히 찍어야만 집혔다. 8로 올려 거터를 16px(8pt)로 만들고 그 전체를 잡게 했다. 막대
/// 자체는 8px 그대로라 **보이는 굵기는 안 변한다**(얇은 띠는 의도한 디자인이다).
///
/// 안쪽으로 더 넓히지 않는 이유: 거터는 컨테이너가 상시 비워 두는 자리라 뺏을 콘텐츠가 없지만, 그
/// 너머는 목록 행이다. 탐색기는 스크롤바를 행보다 **먼저** 판정하므로(`file_panel.zig`) 더 넓히면 행
/// 클릭을 가져간다.
pub const dock_list_scrollbar_inset_px: u32 = 8;
pub const dock_list_scrollbar_min_thumb_px: u32 = 24;

/// 탐색기가 내는 tree의 노드 id. `scrollArea`가 track/thumb을 **자기 preorder 안에서** 내므로
/// root(=scrollArea) 하나에 둘이 딸린다.
pub const dock_list_scroll_ids = struct {
    pub const area: chrome.ui.tree.UiId = 0x4654_0001;
    pub const track: chrome.ui.tree.UiId = 0x4654_0002;
    pub const thumb: chrome.ui.tree.UiId = 0x4654_0003;
};
/// track과 thumb이 함께 선언하는 drag payload. tree는 이 값의 의미를 모른다.
pub const dock_list_scroll_drag_payload: u64 = 1;
/// scrollArea 자신 + track + thumb. 자식이 없으므로 이보다 커질 수 없다.
pub const dock_list_scroll_max_entries: usize = 3;

pub const sidebar_scroll_max_entries: usize = 3;

pub const overlay_scroll_max_entries: usize = 3;
pub const overlay_scrollbar_width_px: u32 = dock_list_scrollbar_width_px;
pub const overlay_scrollbar_inset_px: u32 = dock_list_scrollbar_inset_px;

/// 이번 tick에 활성 surface frame을 (재)투영할지 결정한다 — 순수 함수라 게이트 규칙을 헤드리스로 고정한다.
/// 베이스/결정(docs/io-render-threading.md): synchronized output(DECSET 2026)은 **라이브 화면**이 half-drawn
/// 상태로 tearing되는 것만 막는다(BSU~ESU 사이 투영 보류, ESU 누락 freeze는 sync_timeout으로 강제 해제 — Ghostty
/// sync_reset_ms·xterm.js와 같은 1초). 그런데 사용자의 **스크롤백 탐색(view_offset 변화)은 라이브 출력 배칭과
/// 무관**하므로 sync hold가 막으면 안 된다 — 위로 스크롤한 채 라이브 sync-output TUI를 rapid 스크롤하면(scroll-lock으로
/// 스크롤 상태 유지) 스크롤 리페인트가 sync에 막혀 viewport가 stale로 멈추던 버그를 수정한다. 또 스크롤은 reader에
/// 위임(scroll→enqueueCoreCommand)이라 view_offset 적용이 build의 락-읽기보다 늦는 race에서 metal_dirty가 누락될 수
/// 있으므로, view_offset 변화는 metal_dirty와 무관하게 투영을 강제하는 안전판이 된다(변화 없으면 idle skip 보존).
///
/// 셋째 안전판(sync_esu_count edge): 직전 투영 이후 리더가 ESU(프레임 완성)를 처리했으면 hold를 해제하고 투영한다.
/// per-tick 폴링이 sync_output을 샘플하는 순간 이미 다음 BSU가 시작돼 있으면(flush 창<tick), 메인은 완성 프레임(ESU)을
/// 못 보고 계속 막는 MISS가 생긴다 — Ghostty는 리더가 ESU에서 렌더를 트리거해 이를 피하지만, maru는 tick 폴링이라
/// ESU 누적 카운트를 edge로 소비해 같은 효과를 낸다(MARU_DEBUG 계측 실측: 연속 프레임 워크로드에서 sync 막힘의 약
/// 절반이 이 MISS였다). view_offset과 동형 트레이드오프: esu_advanced 투영 시점이 다음 BSU 직후면 그 프레임 하단이
/// half-drawn으로 한 번 보일 수 있으나 다음 ESU에서 교정되고, timeout(1초) stall보다 명백히 낫다.
///
/// 알려진 트레이드오프/범위(코드리뷰 검토): (1) 부분 스크롤(0<view_offset<rows)이면 합성 뷰포트 하단은 여전히
/// 라이브 활성 화면이라, sync 중 스크롤 투영이 그 하단 행을 half-drawn으로 한 프레임 보일 수 있다 — 그러나 스크롤이
/// 멈추면(view_offset 안정) sync가 다시 막아 사라지고, "얼어붙은 viewport"(고치려는 버그)보다 명백히 낫다(스크롤 중엔
/// 갱신을 기대하는 게 정상). 완전 스크롤(view_offset>=rows)이면 라이브 행이 안 보여 tearing도 없다. (2) view_offset은
/// 활성 surface만 본다 — 비활성 split이 sync hold 중 프로그램적으로 스크롤되면 이 게이트가 강제 투영하진 못한다(활성이
/// dirty해질 때까지). 기존 게이트도 활성 한정이라 회귀가 아닌 선존 범위 한계(드문 경로).
/// §6c host-backed 검색: host가 돌려준 매치 span을 **지금 화면에** 그려도 되는지. host는 자기 core의 현재
/// view_offset 기준으로 span을 계산하는데(runtime_manager.findOp), scroll=true 요청이 그 직전에 host 화면을
/// 옮겼으면 client는 그 스크롤을 아직 delta로 못 받았다 — 두 좌표계가 다른 상태로 합성하면 엉뚱한 줄이
/// 하이라이트된다(사용자에겐 "이전 하이라이트가 남는" 증상). 그래서 두 view_offset이 같을 때만 적용한다.
/// `host_voff`가 null이면 앱보다 오래 사는 구 host 데몬이라 대조할 근거가 없다 — 종전 동작(즉시 적용)으로 둔다.
fn remoteFindSpansApplicable(host_voff: ?u64, client_voff: usize) bool {
    const v = host_voff orelse return true;
    return v == client_voff;
}

fn shouldProjectFrame(
    metal_dirty: bool,
    sync_active: bool,
    sync_hold_ticks: u32,
    sync_timeout: u32,
    view_offset: usize,
    last_rendered_view_offset: usize,
    esu_advanced: bool,
    force_reproject: bool,
) bool {
    const view_scrolled = view_offset != last_rendered_view_offset;
    // esu_advanced(직전 투영 이후 리더가 ESU=프레임 완성 처리)는 호출자가 계산해 넘긴다 — 게이트 해제와
    // freeze-timeout(sync_hold_ticks) 리셋이 같은 값을 써야 하기 때문(호출부 참조, code-review [3]).
    // force_reproject: 사이드바 전용 투영이 atlas를 repack한 뒤 GPU 정합을 위해 sync hold를 우회해 강제 full
    // 투영해야 하는 경우(code-review [0]) — view_offset/esu와 동형의 강제 항.
    const sync_blocks = sync_active and sync_hold_ticks < sync_timeout and !view_scrolled and !esu_advanced and !force_reproject;
    return (metal_dirty or view_scrolled or esu_advanced or force_reproject) and !sync_blocks;
}

test "tab_ops.plausibleSurfaceSize: clamp 하한은 저장하지 않고 정상 grid는 통과시킨다" {
    const floor = terminal.clampGridSize(.{ .cols = 0, .rows = 0 });
    // 기하를 몰라 하한에 걸린 값 — 저장하면 다음 실행이 그 크기로 복원돼 스스로를 재생산한다.
    try std.testing.expect(tab_ops.plausibleSurfaceSize(floor) == null);
    try std.testing.expect(tab_ops.plausibleSurfaceSize(.{ .cols = 0, .rows = 0 }) == null);
    try std.testing.expect(tab_ops.plausibleSurfaceSize(.{ .cols = 80, .rows = 0 }) == null);
    try std.testing.expect(tab_ops.plausibleSurfaceSize(.{ .cols = 0, .rows = 24 }) == null);
    // 하한과 정확히 같을 때만 버린다 — 진짜로 작은 창의 정상 grid는 살린다.
    try std.testing.expectEqual(
        terminal.Size{ .cols = floor.cols, .rows = floor.rows + 1 },
        tab_ops.plausibleSurfaceSize(.{ .cols = floor.cols, .rows = floor.rows + 1 }).?,
    );
    try std.testing.expectEqual(
        terminal.Size{ .cols = 135, .rows = 74 },
        tab_ops.plausibleSurfaceSize(.{ .cols = 135, .rows = 74 }).?,
    );
}

test "복원 왕복: 하한 grid를 저장하지 않으면 다음 복원이 하한으로 재접속하지 않는다" {
    // 실측 회귀: workspace.v1에 `cols=2 rows=1`이 박혀 재시작을 넘어 살아남았고, 다음 복원이 그 크기로
    // 재접속해 스스로를 재생산했다. 저장 직전 필터가 그 고리를 끊는지 왕복으로 고정한다.
    const floor = terminal.clampGridSize(.{ .cols = 0, .rows = 0 });
    const persisted = tab_ops.plausibleSurfaceSize(floor) orelse terminal.Size.default;
    try std.testing.expectEqual(terminal.Size.default, persisted);
    const restored = pane_ops.restoreSurfaceSize(.{ .cols = persisted.cols, .rows = persisted.rows });
    try std.testing.expect(!(restored.cols == floor.cols and restored.rows == floor.rows));
}

// 복원 시 저장된 cwd를 spawn에 쓸지 결정한다(R6 "없는 cwd graceful"). 존재하는 절대-경로 디렉터리일 때만 그
// cwd를, 아니면(빈값·상대경로·없음·파일·권한 없음) null을 돌려준다 — null이면 기본 cwd로 spawn해 surface를 잃지
// 않는다. cwd 자식 chdir 실패는 _exit(126)이라(pty/macos childExec), 미리 확인 안 하면 복원된 셸이 즉시 죽어
// 다음 tick에 reap된다. workspace-restore.md "실패 처리": 한 surface가 어긋나도 나머지(와 그 surface)를 살린다.
pub fn usableRestoreCwd(cwd: []const u8) ?[]const u8 {
    // 잘 형성된 **절대 경로**만 spawn cwd로 넘긴다(빈값·상대경로·과도 길이는 거른다 — 상대경로를 넘기면 자식이
    // 앱 cwd 기준으로 chdir해 예측 불가). 존재·디렉터리 여부는 더 이상 여기서 추측하지 않는다: childExec가 chdir
    // 실패 시 $HOME으로 graceful 폴백하므로(없는 cwd·TOCTOU·파일 경로를 단일 권위로 처리), 여기선 형식만 본다.
    // 이전의 후행-슬래시 access 존재 검사는 검사~spawn 사이 dir이 사라지는 TOCTOU에 취약한 밴드라 제거했다.
    if (cwd.len == 0 or cwd.len >= std.fs.max_path_bytes or !std.fs.path.isAbsolute(cwd)) return null;
    return cwd;
}

// maru의 launch cwd가 `/`인지 한 번 판정한다(init이 launch_cwd_is_root에 캐시 → homeForRootCwd가 소비). getcwd
// 실패 시 false(home 승격 안 함 — 상속 그대로). maru는 자기 cwd를 안 바꿔 시작 시 한 번이면 충분(per-surface getcwd 제거).
fn detectLaunchCwdIsRoot(io: std.Io) bool {
    var cwd_buf: [std.fs.max_path_bytes]u8 = undefined;
    const n = std.process.currentPath(io, &cwd_buf) catch return false;
    return std.mem.eql(u8, cwd_buf[0..n], "/");
}

/// 사이드바 경로줄(카드 폴더줄)용 **순수 cwd 문자열**(owned). $HOME 접두는 "~"로 축약한다(예: /Users/x/p → ~/p).
/// cwd가 비면 "". 폴더 아이콘 prefix는 호출부(buildSidebarTitleFrame)가 브랜치줄 octocat과 같은 패턴으로 붙인다 —
/// 이 함수는 경로만 파생해, copy-path·click-to-open 등 다른 소비자가 PUA 글리프 없는 깨끗한 경로를 쓸 수 있다.
/// 파생값(영속 안 함) — 매 프레임 빌드라 owned 슬라이스를 호출부가 바로 해제한다.
/// 이 프로세스의 hostname — OSC 7 authority가 "우리"를 가리키는지 판정하는 기준값이다. 조회 실패면 빈
/// 문자열이고, 그때 `hostIsLocal`은 보수적으로 원격을 택한다(docs/ssh-integration.md §9.2).
///
/// **캐시하지 않는다. hostname은 프로세스 수명 동안 바뀌기 때문이다.** macOS는 DHCP 도메인·Wi-Fi 전환·슬립
/// 복귀로 접미를 갈고(`box.local` ↔ `box.lan`), 네트워크 구성 전에는 실패하거나 `localhost`를 답한다. 옛
/// 구현은 첫 조회를 프로세스 수명 내내 굳혔는데, 그러면 그 뒤 이름이 바뀌는 순간 기준값이 낡아 **로컬
/// 세션이 통째로 원격으로 오판된다** — `hostIsLocal`은 양쪽이 다 FQDN이면 완전 일치만 로컬로 인정하므로
/// (동명 사내 서버 차단 규율) 접미 하나만 달라도 다른 호스트가 된다. 그 상태에서는 폴더줄에 `host:` 접두가
/// 붙고 §9.4의 안전장치가 전부 발동해 cwd 상속·링크 감지·git 저장소 조회가 함께 꺼진다(사용자 보고
/// 2026-08-13). "시작할 때 자리 잡았는지"만 보는 보정으로는 **시작 뒤에 바뀌는 경우**를 못 막는다.
///
/// **매 호출 조회해도 비용은 잡히지 않는다**: `gethostname`은 실측 382ns/call(macOS, `sysctl` 경로)이다.
/// 사이드바 rebuild가 Term당 여러 번 여기에 닿지만(카드 한 줄을 만드는 데만 `termGitBranch`→`termCwd`와
/// `sidebarHasCwd`→`termCwdForDisplay`→`termCwd`로 네 번쯤), Term 20개·60fps에 그 곱수를 얹어도 초당
/// 2ms 안쪽이다. 캐시가 사던 유일한 값이 그 syscall 절약이므로 정확성과 맞바꿀 이유가 없다.
///
/// **버퍼는 호출자가 준다.** 전역 버퍼로 두면 매 호출이 그것을 덮는데 반환 타입은 평범한 getter처럼 보여,
/// 두 번째 소비처가 값을 잠깐 들고 있다가 조용히 뒤바뀐 이름을 읽는다(캐시가 있던 동안에는 슬라이스가
/// 프로세스 수명 내내 고정이라 안전했던 패턴이다 — 코드 리뷰 지적). 같은 파일의 `termCwd(self, term, buf)`가
/// 쓰는 관행을 따라 out-buffer로 두면 그 제약이 주석이 아니라 시그니처가 된다. 조회 실패면 빈 문자열이고,
/// 그때 `hostIsLocal`은 보수적으로 원격을 택한다(§9.2).
pub fn localHostname(buf: *[std.posix.HOST_NAME_MAX]u8) []const u8 {
    return std.posix.gethostname(buf) catch "";
}

/// 이 Term이 보고한 cwd가 **원격**인가 — 표시(폴더줄·상태바)와 안전(cwd 상속·경로 resolve·git 조회)이 공유하는
/// 단일 판정이다. 재구현하지 말 것: 판정이 갈리면 폴더줄엔 원격이라 적히는데 새 탭은 그 경로로 로컬 spawn을
/// 시도하는 식으로 어긋난다.
///
/// 관측이 없거나(`unavailable`) cwd가 비면 **로컬로 본다** — "값이 없음"을 원격으로 승격하면 셸 통합이 없는
/// 로컬 세션이 통째로 원격 취급돼 cwd 상속이 꺼진다. 원격 판정의 근거는 오직 authority다(§9.2).
pub fn termCwdIsRemote(term: *const Term) bool {
    var host_buf: [std.posix.HOST_NAME_MAX]u8 = undefined; // 이름은 여기서만 살아 있으면 된다(비교에 바로 쓴다)
    if (term.rt.observation.availability == .unavailable) return false;
    // **`maru ssh` 가 알려 준 목적지도 근거다**(A). OSC 5379 로 온 dest 가 있으면 그 pane 은 원격이다 —
    // 원격 셸에 OSC 7 보고자가 없어도 그렇다. 예전에는 authority 하나만 봐서, 보고자를 안 깐 사용자의
    // 원격 pane 이 **로컬로 판정됐다**: 화면의 절대 경로가 로컬 파일로 열리고(§9.4 가 닫아 둔 길),
    // 새 탭이 로컬 경로를 물려받았다.
    //
    // **cwd 가 비어도 원격이다.** 그 상태는 「원격인데 경로를 아직 모른다」이지 「로컬」이 아니다 —
    // ssh 진입이 stale 로컬 값을 버리므로(B) 그 구간이 실제로 생긴다. 아래 `cwd` 검사보다 **먼저**
    // 두어야 그 구간이 로컬로 새지 않는다.
    if (term.rt.observation.ssh_remote_dest_present) return true;
    if (term.rt.observation.cwd.items.len == 0) return false;
    return !terminal.TerminalCore.hostIsLocal(term.rt.observation.cwd_host.items, localHostname(&host_buf));
}

/// 그 Term에 적용할 링크 감지 스코프 — config 프리셋에서 시작하되 **원격 cwd 세션에서는 파일 경로 스코프를 끈다**.
///
/// 파일 경로 링크는 상대경로를 cwd 기준으로 resolve하고 `access(F_OK)`로 존재를 검증한 뒤 여는데, 그 resolve도
/// 존재 검증도 **로컬 파일시스템**에서 일어난다. 원격 cwd를 그대로 쓰면 로컬에 같은 경로가 있을 때 **엉뚱한 로컬
/// 파일이 조용히 열린다** — 같은 사용자가 로컬과 원격에 같은 프로젝트를 두는 흔한 배치에서 그대로 재현된다
/// (적대적 검증에서 발견). 웹·스킴 링크는 어차피 로컬 브라우저로 여는 것이 맞으므로 남긴다.
///
/// hover 밑줄과 클릭이 **같은 함수**를 봐야 "밑줄 보이는 곳 = 열리는 곳" 불변식이 유지된다. 단일 출처는
/// docs/ssh-integration.md §9.4.
///
/// **여기서 observation을 refresh하지 말 것.** 두 호출자(urlAt·hover)는 이미 `lockCore`를 쥔 채 이 함수를 부르고,
/// `refreshTermObservation`은 backend가 같은 core를 다시 lock하므로 재진입 데드락이 된다. 그래서 관측 캐시를 그대로
/// 읽으며, 그 값은 최대 한 observer 주기(100ms)만큼 뒤처질 수 있다 — ssh를 막 드나든 직후의 좁은 창에서 판정이
/// 한 틱 늦는다. 그 대가로 얻는 것이 락 안전이고, 늦어도 다음 틱에 수렴한다.
pub fn linkScopesForTerm(self: *const AppSession, term: *const Term) terminal.LinkScopes {
    var scopes = settings_ops.linkScopesFromConfig(self);
    if (!termCwdIsRemote(term)) return scopes;
    scopes.absolute_path = false;
    scopes.home_path = false;
    scopes.dot_relative = false;
    scopes.bare_relative = false;
    return scopes;
}

/// `linkScopesForTerm` 의 **surface 판**. host-backed 경로는 `Term` 이 아니라 `Surface` 만 손에 쥐는데,
/// 원격 cwd 차단(§9.4)은 Term 의 관측값으로 판정하므로 그 짝을 찾아 같은 규칙을 태운다.
///
/// **직접 `linkScopesFromConfig` 를 부르면 안 된다.** 예전에 host-backed 링크 경로 둘이 그렇게 해서,
/// `cwd_host` wire 가 붙는 순간 §9.4 의 파일 경로 차단이 **그 모드에서만** 빠진 채로 남았다
/// (ssh-integration.md §9.6 이 그 일을 미리 예고해 두었다). 못 찾으면 설정 그대로 — 그 경우는
/// 「Term 이 없다」이지 「원격이 아니다」가 아니지만, 없는 Term 의 관측값을 지어낼 수는 없다.
pub fn linkScopesForSurfaceId(self: *const AppSession, surface_id: u64) terminal.LinkScopes {
    for (self.tabs.items) |tab| {
        for (tab.panes.items) |pane| {
            for (pane.terms.items) |term| {
                if (term.surfaceId() == surface_id) return linkScopesForTerm(self, term);
            }
        }
    }
    return settings_ops.linkScopesFromConfig(self);
}

/// 원격 경로 앞에 붙일 **호스트 이름**. OSC 7 authority 가 있으면 그것이고, 없으면 `maru ssh` 가 알려 준
/// 목적지에서 뽑는다(A).
///
/// **`user@host` 에서 `host` 만 쓴다** — 폴더줄은 좁고, 사용자 이름은 「어느 기계인가」를 말하지 않는다.
/// 포트(`host:2222`)가 붙어 오면 그대로 둔다: 잘라 내면 서로 다른 두 목적지가 같은 이름으로 보인다.
/// 둘 다 없으면 빈 문자열이고, 그때는 호출자가 애초에 원격으로 판정하지 않는다.
fn termDisplayHost(term: *const Term) []const u8 {
    const authority = term.rt.observation.cwd_host.items;
    if (authority.len > 0) return authority;
    const dest = term.rt.observation.ssh_remote_dest.items;
    if (dest.len == 0) return "";
    return if (std.mem.lastIndexOfScalar(u8, dest, '@')) |at| dest[at + 1 ..] else dest;
}

pub fn sidebarCwdPath(self: *AppSession, term: *Term) ![]const u8 {
    // cwd 해석은 **소스 컨트롤 뷰·파일 탐색기와 같은 지점**을 쓴다(docs/editor-surface-dock.md §3.5의 2단 규칙).
    // 예전에는 여기만 관측(OSC 7)을 직접 읽어, OSC 7이 없는 Term에서 같은 화면의 두 뷰가 서로 다른 답을 냈다.
    const allocator = self.allocator;
    var cwd_buf: [std.fs.max_path_bytes]u8 = undefined;
    const cwd = git_ops.termCwdForDisplay(self, term, &cwd_buf) orelse return allocator.dupe(u8, "");
    if (cwd.len == 0) return allocator.dupe(u8, "");
    // 원격 cwd는 `<host>:<path>`로 그리고 `~` 축약을 **하지 않는다**. 축약하면 원격 $HOME을 로컬 것으로 계산해
    // 남의 홈을 자기 홈처럼 보여 주고(로컬 $HOME과 우연히 겹치면 조용히 틀린다), host가 없으면 사용자가 그 경로를
    // 로컬에서 열려다 실패한다. `host:path`는 scp/rsync 관례라 원격임이 즉시 읽힌다.
    if (termCwdIsRemote(term))
        return std.fmt.allocPrint(allocator, "{s}:{s}", .{ termDisplayHost(term), cwd });
    const home: []const u8 = if (std.c.getenv("HOME")) |h| std.mem.span(h) else "";
    // $HOME 정확 경계(home 자체 또는 home/ 하위)일 때만 "~"로 — "/Users/xyz"가 "/Users/x"로 잘못 잡히지 않게.
    if (home.len > 0 and std.mem.startsWith(u8, cwd, home) and (cwd.len == home.len or cwd[home.len] == '/'))
        return std.fmt.allocPrint(allocator, "~{s}", .{cwd[home.len..]});
    return allocator.dupe(u8, cwd);
}

// 순수 레이아웃 기하(layout_math.PaddingPx·gridFromBacking·gridFromRectPx·ptToPx)는 session/layout_math.zig로 이동(b1).
// 호출은 layout_math.X로 위임 — 다른 OS 어댑터도 같은 grid·환산을 재사용한다(이식 기여).

test "workspace_ops.effectiveWindowBlur: opacity 게이트 — 불투명이면 0, 투명일 때만 반경" {
    // 블러 0이면 opacity 무관하게 0.
    try std.testing.expectEqual(@as(u32, 0), workspace_ops.effectiveWindowBlur(0, 0.5));
    try std.testing.expectEqual(@as(u32, 0), workspace_ops.effectiveWindowBlur(0, 1.0));
    // 블러>0이어도 불투명(opacity>=1)이면 0(뒤가 안 비침).
    try std.testing.expectEqual(@as(u32, 0), workspace_ops.effectiveWindowBlur(20, 1.0));
    try std.testing.expectEqual(@as(u32, 0), workspace_ops.effectiveWindowBlur(20, 1.5)); // 1 초과도 불투명 취급
    // 블러>0 + 투명(opacity<1)이면 그 반경 그대로.
    try std.testing.expectEqual(@as(u32, 20), workspace_ops.effectiveWindowBlur(20, 0.8));
    try std.testing.expectEqual(@as(u32, 1), workspace_ops.effectiveWindowBlur(1, 0.0));
    try std.testing.expectEqual(@as(u32, 100), workspace_ops.effectiveWindowBlur(100, 0.99));
}

/// color.Rgb를 불투명(A=0xFF) 0xAARRGGBB로 packing한다(사이드바 strip/활성 밴드 셀 배경 색용). 셀
/// 배경은 A=0xFF여야 셰이더가 그 색으로 칠한다(A=0이면 "배경 없음").
/// rgb + alpha를 GpuQuad/cell 색 워드(0xAARRGGBB)로 패킹. 색 패킹의 단일 출처 — packOpaqueRgb·스크롤바 fade가 공유.
pub fn packRgbAlpha(rgb: maru.color.Rgb, alpha: u8) u32 {
    return (@as(u32, alpha) << 24) | (@as(u32, rgb.r) << 16) | (@as(u32, rgb.g) << 8) | rgb.b;
}

pub fn packOpaqueRgb(rgb: maru.color.Rgb) u32 {
    return packRgbAlpha(rgb, 0xFF);
}

/// sentinel-UV(아틀라스 없음 — u/v=-1로 셰이더가 글리프 샘플 대신 배경만 칠함) chrome 셀 1개. pane 탭 바
/// 배경·활성 탭 하이라이트가 공유하는 보일러플레이트(16개 필드)를 한 곳에 모은다. origin_x + col*cw,
/// origin_y(row 0)에 width칸을 bg로 채운다. 순수 함수.
pub fn sentinelBgCell(col: u16, width: u16, bg: u32, origin_x: u32, origin_y: u32) metal_frame.NativeMetalCell {
    return .{
        .row = 0,
        .col = col,
        .width = width,
        .codepoint = ' ',
        .slot_id = 0,
        .atlas_x_px = 0,
        .atlas_y_px = 0,
        .atlas_width_px = 0,
        .atlas_height_px = 0,
        .u0 = -1.0,
        .v0 = -1.0,
        .u1 = -1.0,
        .v1 = -1.0,
        .foreground = 0,
        .background = bg,
        .origin_x = origin_x,
        .origin_y = origin_y,
    };
}

/// pane 탭 바 배경 셀 1개(sentinel-UV, 배경만). bar rect 좌상단 origin에서 폭(cols)만큼 채운다 — 터미널 셀
/// 스트림에 넣으면 maru_fill_cell_quad가 origin_x + col*cw, origin_y + row*ch(row 0)에 그려 바를 칠한다. 폭이
/// term 폭과 같은 cols(floor)라 아래 터미널과 가로 정렬된다. 셀 폭/바 폭·높이 0이면 null. 순수 함수.
fn paneBarBgCell(bar: maru.session.SplitRect, cell_width_px: u32, bg: u32) ?metal_frame.NativeMetalCell {
    if (cell_width_px == 0 or bar.w == 0 or bar.h == 0) return null;
    const cols_u32 = @min(bar.w / cell_width_px, @as(u32, std.math.maxInt(u16)));
    if (cols_u32 == 0) return null;
    return sentinelBgCell(0, @intCast(cols_u32), bg, bar.x, bar.y);
}

// putUtf8/appendPaletteRow(레거시 팝업 텍스트 레이아웃)는 제거했다 — 팝업이 chrome 컴포넌트로 이주(C1b)해
// rasterizeOverlayCells의 placeText(EAW-폭)를 find와 공유한다. 코드포인트당 1칸 깔던 putUtf8이 한글을 자르던 원인.

// pointInRect·layout_math.PaneDropZone·halfRect·paneDropZone는 session/layout_math.zig로 이동(b1, 순수 hit-test/drop-zone).

/// 탭 드래그 중 드롭 타겟(④b 하이라이트·④ 커밋 공유 판정). `pane`은 마우스가 올라간 대상 pane, `zone`이 null이면
/// 그 pane 탭 바(드롭 시 Term 이동, PR-E2), set이면 본문 절반(그 방향으로 새 split, ④).
pub const DropTarget = struct { pane: *Pane, zone: ?layout_math.PaneDropZone };

/// 0xAARRGGBB 색을 alpha로 **premultiply**한다(rgb를 alpha/255로 곱하고 alpha를 A로). 렌더러가 premultiplied-
/// alpha over로 블렌딩하므로(maru_metal_shader), 반투명 하이라이트는 이렇게 미리 곱해 넘겨야 색이 안 뜬다. 순수.
fn premultipliedRgba(rgb: u32, alpha: u8) u32 {
    const a: u32 = alpha;
    const r = (((rgb >> 16) & 0xFF) * a) / 255;
    const g = (((rgb >> 8) & 0xFF) * a) / 255;
    const b = ((rgb & 0xFF) * a) / 255;
    return (a << 24) | (r << 16) | (g << 8) | b;
}

/// base(0xAARRGGBB)의 RGB를 tint_rgb(0xRRGGBB) 쪽으로 alpha/255만큼 lerp한다(base의 알파 보존). 사이드바 밴드에
/// per-tab 배경 tint를 섞어, tui 기본 테마의 불투명 활성/호버 밴드가 tint quad를 덮어도 활성 슬롯에서 색이 보이게 한다.
pub fn blendRgb(base: u32, tint_rgb: u32, alpha: u8) u32 {
    const a: u32 = alpha;
    const inv: u32 = 255 - a;
    const r = ((((base >> 16) & 0xFF) * inv) + (((tint_rgb >> 16) & 0xFF) * a)) / 255;
    const g = ((((base >> 8) & 0xFF) * inv) + (((tint_rgb >> 8) & 0xFF) * a)) / 255;
    const b = (((base & 0xFF) * inv) + ((tint_rgb & 0xFF) * a)) / 255;
    return (base & 0xFF00_0000) | (r << 16) | (g << 8) | b;
}

/// Term(가로 탭) 표시 라벨 — 사용자 rename(surface.custom_name)이 있으면 그것, 없으면 자동 제목.
/// 자동 제목은 **라이브 OSC 0/2 창 제목**(없으면 cwd basename)을 반영해 사이드바·탭바가 현재 실행 중인 프로그램
/// (Claude Code 등 OSC 제목을 설정하는 TUI)의 제목을 실시간 보인다. 단 그 값(`core.windowTitle()` 반환 슬라이스 =
/// core.title/cwd)은 reader 스레드가 OSC 0/2/7로 free+realloc하므로 렌더 스레드가 직접 읽으면 use-after-free다 —
/// `syncAutoTitles`가 매 tick core_mutex 하에 owned 복사본(`term.auto_title`)으로 캐시하고, termLabel은 그 캐시만
/// 읽는다(io-render-threading PR3). 캐시가 비면(첫 sync 전·빈 제목) 정적 `surface.title`로 폴백. 베이스: Ghostty 탭
/// 제목도 OSC 제목 우선·없으면 cwd basename(동작 비교).
/// 사이드바 워크스페이스 라벨·pane 탭바가 공유하는 단일 해석(app.pickLabel). 반환은 borrowed(custom_name=세션 소유,
/// auto_title=메인 스레드 소유 캐시, surface.title=정적) — 모두 reader 스레드가 안 건드려 렌더 중 안정. 호출자가 즉시 복사.
/// 저장하지 않은 편집이 있는 편집기 제목 앞에 붙는 표식(U+25CB WHITE CIRCLE).
///
/// **running 표식과 그리는 층이 다르다.** `●`는 `tabTitleRunningMarker`가 떼어 **셀로** 그리고
/// (`appendPaneTabTitles`가 `tabTitleBody`로 본문만 measured에 보낸다), 이 `○`는 **본문에 남아**
/// 제목과 함께 measured로 그려진다. 층을 나누지 않는 이유: 셀 층은 에이전트 색으로 다시 칠해지는
/// 자리라(`recolorAgentFlagCells`) dirty가 거기 끼면 색 규칙이 둘이 된다. 대신 좁은 탭에서
/// 말줄임될 때 **표식이 이름과 함께 잘린다** — 그 대가는 §5.2가 2차원 reveal과 함께 볼 자리다.
///
/// **글자 하나다** — 탭 폭은 칸으로 세므로(`paneTabWidth`) 여러 칸을 먹는 표식은 좁은 탭에서
/// 이름을 통째로 밀어낸다.
///
/// **`agent_running_flag`(`●` U+25CF)와 다른 글자여야 한다.** 처음에 같은 `●`를 골랐다가
/// 적대적 검증(2026-08-26)이 잡았다 — 사용자는 *"에이전트가 도는 중"*과 *"저장 안 됨"*을
/// 구분할 수 없게 된다. 같은 탭 바에 같은 자리(앞)로 붙으므로 **모양이 겹치면 뜻이 겹친다.**
/// 속이 빈 원은 "아직 안 채워짐 = 저장 안 됨"으로 읽히고, VSCode도 dirty에 빈 점을 쓴다.
pub const editor_dirty_marker = "\u{25CB}";

pub fn termLabel(term: *const Term) []const u8 {
    // 파일 Term은 **파일 이름**이 라벨이다. 패널 종류 라벨("Markdown")을 쓰면 파일을 세 개 열어도 탭이 전부
    // "Markdown"이라 어느 탭이 무엇인지 알 수 없다(diff를 열면서 드러났다 — 사용자 지적). 사용자 rename이 있으면
    // 그게 우선인 것은 다른 경로와 같다.
    if (term.file_entry) |entry| {
        return app.pickLabel(term.surface.custom_name, std.fs.path.basename(entry.path));
    }
    // 4e-1 web Term: 자동 제목(OSC)이 없으니 kind 파생 라벨("Browser"/"Markdown")을 auto로 쓴다 — 사용자 rename
    // (custom_name)이 있으면 그게 우선(pickLabel 단일 해석). terminal 경로는 `if` 아래로 **byte-identical**.
    if (term.kind == .web) return app.pickLabel(term.surface.custom_name, term.webPanelLabel());
    // N1 편집기 Term도 자동 제목(OSC)이 없다 — **파일 이름**이 auto 라벨이다. 아래 terminal 경로로
    // 흘리면 sentinel `surface.title`을 읽게 되는데, 그건 빈 core라 유효한 라벨이 아니다(적대적
    // 검증에서 collector가 이 경로로 `Invalid free`까지 갔다).
    if (term.kind == .editor) {
        const auto_name: []const u8 = if (term.rt.editor_path) |p|
            std.fs.path.basename(p)
        else
            maru.i18n.t(.app_editor);
        return app.pickLabel(term.surface.custom_name, auto_name);
    }
    const auto = if (term.auto_title.items.len > 0) term.auto_title.items else term.surface.title;
    return app.pickLabel(term.surface.custom_name, auto);
}

/// 워크스페이스(사이드바 탭) 표시 라벨 — 탭 custom_name 우선, 없으면 활성 Term 라벨로 폴백(워크스페이스는 자동
/// 제목 출처가 없어 활성 Term을 대표로 빌린다 — 기존 동작과 동일하되 사용자 rename이 우선한다).
pub fn workspaceLabel(tab: *Tab) []const u8 {
    return app.pickLabel(tab.custom_name, termLabel(tab.activeTerm()));
}

/// 데스크톱 알림 제목에 붙일 **위치 라벨** — 알림이 온 워크스페이스(탭)와 Term(surface/pane)을 `탭 › 팬`으로 조립한다
/// (사용자 요청: 배너엔 앱 아이콘만 떠 소스 구분이 안 되니 어느 탭·어느 팬에서 왔는지 제목에서 바로 식별). 단일 출처는
/// 여기다 — OSC 9/777 drain 경로가 모든 발신 surface에 공통으로 사용한다.
/// workspaceLabel(탭)과 termLabel(Term)이 **같으면**(단일 Term 탭·custom_name 없음 등 workspaceLabel이 그 Term 라벨로
/// 폴백) 중복이라 **하나만** 쓴다 — 단일 워크스페이스·단일 Term 사용자는 예전 제목과 동일하게 보인다. `›`(U+203A)는
/// 계층(탭⊃팬) 구분, `·`(U+00B7)는 상위 구분자로 알림 전체에서 일관되게 쓴다. 두 라벨은 borrowed(auto_title=메인
/// 스레드 캐시·custom_name=세션 소유·surface.title=정적, reader 미접근)라 즉시 buf로 복사한다 — 반환 슬라이스는
/// buf(호출자 스택) 또는 borrowed pane 라벨을 가리켜 호출자의 즉시 소비(allocPrint/dupe)까지 유효(수명 의존 없음).
/// buf가 모자라면(NoSpaceLeft) 팬 라벨만 돌려준다(알림 제목은 어차피 OS가 말줄임 — 위치보다 팬이 더 구체적).
/// 호출자 스택 버퍼 크기 단일 출처(모든 OSC drain 경로가 같은 상한을 쓰게) — 512는 대다수 라벨을 담고도 남으며,
/// 넘치면 위 fallback으로 팬 라벨만 담긴다.
pub const notification_location_buf_len = 512;
pub fn notificationLocation(buf: []u8, tab: *Tab, term: *const Term) []const u8 {
    const tab_label = workspaceLabel(tab);
    const pane_label = termLabel(term);
    if (std.mem.eql(u8, tab_label, pane_label)) return pane_label;
    return std.fmt.bufPrint(buf, "{s} › {s}", .{ tab_label, pane_label }) catch pane_label;
}

/// pane 탭 바 컬럼 분할 메트릭(중립 `tabbar.Metrics`)을 만든다(옛 BarMetrics.init). 렌더(buildPaneTabBarDrawList·활성
/// 밴드)와 hit-test(chrome `tabbar.tabIndex/inCloseZone/inPlusZone`)가 같은 메트릭을 공유해 "보이는 탭/✕/+ == 클릭되는
/// 것". coretext의 paneTabAreaCols/paneTabWidth(렌더가 쓰는 같은 공식)로 바를 [탭 영역 | "+" zone]으로 나눈다. cell·바·
/// 탭 폭이 0이면(초소형 바) null을 줘 호출자가 탭 처리를 건너뛴다. hit-test 수학은 chrome tabbar로 이전(C3b) — platform은
/// 메트릭 빌드 + 활성 밴드 단일 셀(tabbarHighlightCell)만(밴드가 한 칸이라 chrome view→cell round-trip이 무의미; 리뷰 §3).
pub fn barMetrics(bar: maru.session.SplitRect, cell_width_px: u32, term_count: usize, tab_width_fixed: u16, scroll_cols: u32) ?chrome.components.tabbar.Metrics {
    if (cell_width_px == 0 or bar.w == 0 or term_count == 0) return null;
    const cols = @min(bar.w / cell_width_px, @as(u32, std.math.maxInt(u16)));
    if (cols == 0) return null;
    // 탭 레이아웃 단일 소스(§6) — buildPaneTabBarDrawList(렌더)와 같은 tabLayout이라 보이는 탭/‹›/+ == 클릭.
    // scroll_cols는 tabLayout이 [0,max] clamp한 eff_scroll로 정규화(#1: stale 방지). hit-test·렌더가 같은 eff를 쓴다.
    const layout = coretext_frame_builder.tabLayout(@intCast(cols), term_count, tab_width_fixed, scroll_cols);
    if (layout.tab_w == 0) return null;
    return .{ .bar_x = bar.x, .bar_y = bar.y, .bar_w = bar.w, .bar_h = bar.h, .cell_width_px = cell_width_px, .cols = cols, .tab_cols = layout.tab_cols, .tab_w = layout.tab_w, .scroll_cols = layout.eff_scroll, .has_scroll = layout.has_scroll, .tab_count = @intCast(term_count) };
}

/// 활성 Term 탭 세그먼트를 강조 배경 셀로 칠한다(옛 BarMetrics.highlightCell). chrome tabbar hit-test와 **같은
/// tabbar.segOf 셀 경계**(start_col/end_col)라 활성 밴드가 제목 glyph·클릭·✕와 정확히 정렬된다(§6 단일 소스).
/// overflow(탭 영역 밖, end_col<=start_col)면 null.
fn tabbarHighlightCell(m: chrome.components.tabbar.Metrics, tab_index: usize, bg: u32) ?metal_frame.NativeMetalCell {
    const seg = m.segOf(tab_index);
    if (seg.end_col <= seg.start_col) return null; // overflow(탭 영역 밖, 안 보이는) 탭
    return sentinelBgCell(@intCast(seg.start_col), @intCast(seg.end_col - seg.start_col), bg, m.bar_x, m.bar_y);
}

// (paneInDirection은 위 주석대로 session core로 이동 — Model.paneInDirection)

// tab_ops.adjustActiveForMove·rotateMove·tab_ops.reselectAfterClose·wheelDeltaToLines는 session core로 추출됐다 — 위 file-scope
// alias(input_math.*)로 bare 이름 그대로 호출한다. 정의·단위 테스트는 src/session/input_math.zig.

// synchronized output(DECSET 2026) 게이트 진단 logger. MARU_DEBUG일 때 tick마다 sync hold/투영 결정
// (활성 sync·hold tick·grid/chrome 투영·ESU 누적·view_offset)을 구조화 한 줄씩 찍어, 폴링 렌더 루프가
// 라이브 프레임을 언제 붙잡고 언제 flush하는지 실환경에서 관측한다(shouldProjectFrame 게이트의 각 안전판—
// 스크롤·ESU edge·timeout—이 실제로 발동하는지). 같은 도메인 데이터를 테스트·후속 trace writer도 이 자리에서
// drain한다(관측 가능성 원칙). 게이트는 diag.zig 단일 출처.
const sync_diag = std.log.scoped(.sync);
// 프레임 타이밍 진단 logger. MARU_DEBUG일 때 tick의 wall-clock 소요를 단계별(pre/titles/drain/mid/project)로
// 분해해, sync 스피너/blink cadence가 tick 카운트에 묶여 있어 무거운 tick이 실효 tick rate를 떨어뜨리는(탭 전환
// CoreText reshape=project vs SSH firehose·lock 경합=titles/drain) 지배 요인을 데이터로 가른다. 60Hz 노이즈를
// 줄이려 느린 tick(총>frametime_slow_ns)은 즉시 한 줄, 약 1초 창마다 실효 rate·mean/max·단계 비중을 요약한다.
// 게이트는 diag.zig 단일 출처(관측 가능성 원칙, sync_diag와 동형).
const frametime_diag = std.log.scoped(.frametime);
// 느린 tick 즉시 로그 임계 — 8ms(60Hz 프레임 16.6ms의 절반). 이보다 오래 걸린 tick은 다음 NSTimer 발사를 밀어 rate를 떨군다.
const frametime_slow_ns: i128 = 8 * std.time.ns_per_ms;
// 레이아웃 resize 진단 logger. 표시 grid는 항상 맞춰지지만 runtime(PTY winsize·원격 host) 전달이 거부되면 그
// Term의 자식 프로세스만 옛 winsize를 믿는다 — "이 pane의 TUI만 어긋난다"의 원인을 남긴다. 카운터
// (`resize_delivery_failures`)와 같은 도메인 데이터를 헤드리스 테스트가 읽는다(관측 가능성 원칙).
// 게이트는 diag.zig 단일 출처.
const resize_diag = std.log.scoped(.resize);
pub const diag_gate = @import("diag.zig");

fn nsToMs(ns: i128) f64 {
    return @as(f64, @floatFromInt(ns)) / @as(f64, @floatFromInt(std.time.ns_per_ms));
}

fn nsPct(part: i128, whole: i128) f64 {
    if (whole <= 0) return 0;
    return @as(f64, @floatFromInt(part)) * 100.0 / @as(f64, @floatFromInt(whole));
}

// app_host_abi.zig가 이 파일을 import하므로 EventKind는 여기서 정의하고 거기서 re-export한다
// (순환 import 회피). FrameSummary.last_event_kind가 이 값을 그대로 싣는다.
pub const EventKind = enum(u32) {
    none = 0,
    frame_tick = 1,
    key_down = 2,
    resize = 3,
    close_requested = 4,
    app_should_terminate = 5,
};

pub const CommandKind = enum(u32) {
    controlled_smoke = 0,
    interactive_shell = 1,
    // quick은 같은 대화형 셸을 쓰지만 workspace manifest에 아직 저장하지 않으므로 lifecycle을 구분한다.
    quick_interactive_shell = 2,
};

/// AS4-c fixture가 실제로 paint되어 pointer 입력에 쓰이는 capability만 읽기 위해 쓰는
/// 내부 target vocabulary다. provider source, action payload, 세션 제목/ID/경로는 이
/// 경계를 절대 통과하지 않는다.
pub const AgentSessionArchiveSmokeProbeTarget = enum(u32) {
    session_dock_card = 1,
    archive_resume = 2,
    archive_reveal_log = 3,
    archive_focus_live = 4,
    dock_agent_sessions = 5,
    dock_launcher = 6,
    archive_refresh = 7,
    /// Fixture-only read-only raw rect for the already expanded card crossing the scroll clip.
    /// It carries no source identity or action capability; AS3-c's AppKit E2E uses it only to
    /// prove that an exact-card refresh anchor preserves the pre-existing intra-card pixel.
    archive_expanded_scroll_anchor = 8,
    /// Fixture-only fixed control rects; neither target carries source identity or capability.
    archive_scope_row = 9,
    archive_search = 10,
    /// Fixture-only un-clipped root of the currently expanded identity-bound card.
    archive_expanded_card = 11,
};

/// Published tree에서 나온 backing-pixel capability snapshot이다. `present=false`면 다른
/// 필드가 stale일 수 있으므로 consumer는 읽지 않는다. host ABI는 이 타입을 즉시
/// fixed-width record로 복사할 뿐, source-derived 값이나 action identity를 추가하지 않는다.
pub const AgentSessionArchiveSmokeProbe = struct {
    request_id: u64 = 0,
    /// Published SessionDock frame generation; only the scroll-anchor fixture compares this
    /// opaque UI version across retained and replacement snapshots.
    generation: u64 = 0,
    x_px: f32 = 0,
    y_px: f32 = 0,
    width_px: f32 = 0,
    height_px: f32 = 0,
    state: u32 = 0,
    present: bool = false,
    enabled: bool = false,
};

pub const SessionConfig = extern struct {
    abi_version: u32,
    cols: u32,
    rows: u32,
    queue_capacity: u32,
    command_kind: u32,
    // 1이면 chrome 최소화(사이드바·pane 탭 바 없이 터미널만) — quick terminal minimal 모드용. 0=full(메인 창).
    // Swift가 세션 생성 시 세션별로 정한다.
    chrome_minimal: u32 = 0,
    // 1이면 chrome_minimal 세션에서도 탭(워크스페이스·Term) 생성을 허용한다. 0이면 minimal은 단일 스크래치
    // (⌘T/⌘⇧T 무동작). chrome_minimal=0(full)이면 이 값과 무관하게 탭이 항상 동작한다. Swift가 quick 세션에만 정한다.
    minimal_tabs: u32 = 0,
    // 첫 셸 spawn 크기 결정용 창 backing 픽셀 + scale(둘 다 >0이면 init이 cell 메트릭으로 grid를 계산해 PTY를
    // **처음부터 실제 창 크기로** 띄운다 — 80×24 기본 spawn 후 resize하는 핸드셰이크/레이스를 없애 zsh의 첫 프롬프트
    // PROMPT_EOL_MARK(%) 잔상을 막는다). 0이면(헤드리스 테스트 등) cols/rows로 폴백. Swift가 창에서 채운다.
    width_px: u32 = 0,
    height_px: u32 = 0,
    scale_milli: u32 = 0,
    // 저장 workspace를 즉시 적용할 세션이면 첫 default tab/PTY를 만들지 않는다. applyWorkspaceWindow 성공이 첫 surface와
    // frame loop를 원자적으로 완성한다. 일반 새 Window/quick/smoke는 0.
    defer_initial_surface: u32 = 0,
};

pub const FrameSummary = extern struct {
    abi_version: u32 = abi_version,
    terminal_surface: u32 = 0,
    frame_loop_ticks: u64 = 0,
    last_tick_index: u64 = 0,
    output_events: u64 = 0,
    exit_events: u64 = 0,
    surface_id: u64 = 0,
    glyph_count: u64 = 0,
    draw_cells: u64 = 0,
    atlas_entries: u64 = 0,
    key_events: u64 = 0,
    terminal_input_events: u64 = 0,
    terminal_input_bytes: u64 = 0,
    app_key_events: u64 = 0,
    ignored_key_events: u64 = 0,
    resize_events: u64 = 0,
    close_events: u64 = 0,
    cols: u32 = 0,
    rows: u32 = 0,
    process_state: u32 = 0,
    frame_prepared: u32 = 0,
    frame_consistent: u32 = 0,
    glyph_uv_ready: u32 = 0,
    glyph_raster_ready: u32 = 0,
    ended: u32 = 0,
    last_event_kind: u32 = @intFromEnum(EventKind.none),
    // 현재 retain된 Metal frame의 generation(u64를 u32로 truncate). host는 이 값이 그대로면
    // metalFrame() ABI를 부르지 않고 draw를 건너뛸 수 있다(idle tick 비용 절감). u32 wrap은
    // 사실상 발생하지 않고, 충돌해도 redraw 한 번 누락/추가일 뿐이라 무해하다.
    metal_generation: u32 = 0,
    // Cmd+Q 종료 확인 모달의 결정을 host로 한 번 전달하는 one-shot 신호(0=대기/없음·1=accepted·2=cancelled).
    // applicationShouldTerminate가 request_app_quit으로 모달을 띄우고 .terminateLater를 돌려준 뒤, confirm 확정/취소가
    // 이 값에 latch되면(다음 tick) Swift가 NSApp.reply(toApplicationShouldTerminate:)로 종료를 진행/취소한다. tick
    // epilogue에서 self.quit_decision을 실어 보낸 직후 .none으로 리셋해 한 번만 전달한다(ended latch와 같은 패턴).
    quit_decision: u32 = 0,
    // Phase 4e-5/FP16c: 창의 어느 pane 트리에든 web Term이 있으면 1(windowHasWebTerm — 매 tick 계산, 유지
    // 카운터 아님이라 창 간 이동에도 드리프트 없음). Swift drainWebSurfaceTransition 게이트가 env 훅(MARU_WEB_PANEL) 없이도
    // command로 만든 web surface를 그리게 하는 "존재 신호"다(§10 4e-5). tick epilogue가 quit_decision 옆에서 매 tick 채운다.
    // quit_decision 뒤 4B tail padding 자리라 struct @sizeOf는 176으로 불변(ABI v102).
    web_surfaces_present: u32 = 0,
};

const NormalizedConfig = struct {
    size: terminal.Size,
    queue_capacity: usize,
    command_kind: CommandKind,
    is_quick: bool,
    chrome_minimal: bool,
    minimal_tabs: bool,
    // 첫 spawn 크기 결정용 창 backing 픽셀 + scale(0이면 size로 폴백). init이 cell 메트릭으로 grid 계산.
    width_px: u32,
    height_px: u32,
    scale_milli: u32,
    defer_initial_surface: bool = false,
};

const TermRuntime = struct {
    // persistent-session P2 seam(docs/persistent-session-host.md §13 P2): 런타임 소유는 앱 전역
    // `app_runtime.live_registry`(LiveSurfaceRegistry(LiveSurface))에 있고, GUI(Term)는 그 runtime을 가리키는 opaque
    // `RuntimeHandle`만 든다 — 더 이상 `*LivePtySession` 포인터를 직접 들지 않는다. spawn/attach/pump/close/observe는
    // 전부 `AppSession.termBackend()`(= `TermRuntimeBackend` 계약)에 이 handle을 넘겨 수행하므로, GUI는 runtime이
    // in-process인지 원격 host(P3 maru-sessiond)인지 모른다. in-process에서 handle 값은 surface_id(=pty_id)와 같아
    // registry/routing 조회가 1:1이다(그래도 GUI는 이 값을 surface_id로 해석하지 않고 backend에 되돌려 주는 불투명
    // handle로만 다룬다). reader thread가 잡는 `&live_pty.reader`·`&surface.core` 주소는 registry heap 슬롯이 고정하며
    // (backend 내부 계약), 그 heap-pin은 seam 전환과 무관하게 유지된다. **4e-1**: web Term(kind==.web)은 live PTY가
    // 없어 아래 `live_initialized=false`로 두고 handle을 미할당(0)으로 둔다. `Term.surface`는 backend `spawn`이 돌려준
    // 번들 슬롯 surface 포인터(web은 sentinel)를 참조한다.
    handle: app.TermRuntimeHandle = 0,
    pump: app.RuntimeEventPump = undefined,
    live_initialized: bool = false,
    // workspace restore staging에서 **기존** host runtime에 attach한 Term. publish 전 rollback은 이 runtime을 종료하면
    // 안 되므로 destroyTerm이 detach-only로 회수한다. applyWorkspaceWindow가 commit point를 넘으면 false로 바꿔 이후
    // 사용자 명시 close는 정상 terminate 의미를 가진다.
    restored_existing: bool = false,
    // CR5d-2 Window close after termination became unconfirmed.  The host runtime must remain in
    // inventory, so destroyTerm takes the existing detach-only remote teardown instead of sending
    // runtime.terminate. This bit is set only by the CR5d abandon suffix immediately before removal.
    abandoned_to_inventory: bool = false,
    // 이 Term의 PTY가 종료(exit/read_error) 관측 후 finishAfterTermination까지 끝났는가. tick drain이 Term별로
    // 한 번만 finish하도록, 세션 종료(모든 Term terminated) 판정에 쓴다.
    terminated: bool = false,
    // backend close가 complete를 게시했지만 layout/remove suffix는 아직 실행 전일 수 있다. 이 래치가 있어야
    // topology를 보존한 재시도와 destroy 단계가 같은 close request를 두 번 발행하지 않는다.
    close_complete: bool = false,
    // 창 close graph가 이 Term의 현재 membership과 backend request를 final address에 봉인한다. bool close_complete만으로는
    // allocator reuse나 다른 창으로 이동한 Term을 같은 재시도로 오인할 수 있어 별도 checked generation을 둔다.
    close_generation: u64 = 0,
    pending_close: PendingTermClose = .{},
    // 이 Term의 셸을 spawn한 시각(ns, `std.Io.Clock.awake` 단조 시계 — 코드베이스 선례). 종료 시 uptime(=exit−spawn)을
    // 재 비정상 시작 사망(grace window) 판정에 쓴다. createTerm이 스탬프. 0이면 미스탬프(테스트 등)로 취급 — uptime 판정 생략.
    spawned_at_ns: i128 = 0,
    // 100ms probe에서 foreground pgid 변화만 싸게 감지해 kind를 즉시 재분류한다. 0=null/미관측.
    agent_observer_pgid: i32 = 0,
    // 화면 외 runtime 관측의 caller-owned cache. in-process core와 host-backed event를 같은 SSOT로 노출해 AppSession이
    // 원격 placeholder `surface.core`를 cwd/title/semantic/SSH/agent 출처로 오인하지 않게 한다.
    observation: app.RuntimeObservation = .{},
    /// §7 **종료 placeholder**: manifest엔 있었지만 host runtime이 영구히 없어(`error.PersistentRuntimeGone`) 읽기
    /// 전용으로 복원한 Term. live PTY·pump·라우팅이 없고(`live_initialized=false`, `handle=0`) registry 슬롯은
    /// `LiveSurface.web` arm sentinel을 재사용하지만, `Term.kind`는 **`.terminal` 그대로**다 — 그래야 기존 렌더·라벨
    /// 경로가 무변경으로 마지막 화면과 안내를 그린다(`SurfaceKind`는 닫힌 열거라 확장에 사용자 승인이 필요하고,
    /// `kind == .web` 분기 40여 곳이 "PTY 없음 + 렌더 안 함"을 함께 뜻하는데 묘비는 렌더는 해야 한다).
    /// 이 플래그를 보는 곳: `destroyTerm`·세션 `deinit`(web과 같은 경량 teardown), `allTabsTerminated`(묘비만 남은
    /// 창을 닫지 않는다), `findTerminatedTerm`(자동 reap 대상 아님), `resizeTermForLayout`(core를 직접 resize),
    /// 드롭 배리어(읽기 전용).
    ended_placeholder: bool = false,

    /// N1 편집기 Term(`kind == .editor`)이 여는 문서. **`rt`에 있는 이유**는 파일을 읽는 것이 OS를
    /// 아는 층이기 때문이다 — 중립 세션 모델(`session_model.zig`)은 파일도 인코딩도 모른다(§2 레이어).
    ///
    /// 아래 셋은 함께 산다: 문서·그 줄 슬라이스·경로. 줄들은 **문서 버퍼를 빌리므로** 문서보다 오래
    /// 살면 안 되고, 그래서 해제도 한 곳(`editor_ops.releaseEditorTerm`)이 한다.
    editor_doc: ?editor_ops.Opened = null,
    /// 위 문서의 논리 줄들(문서 버퍼를 빌린다). `frame.build`가 **문서 전체**를 받아야 스크롤바
    /// 길이가 맞으므로(§4.1a) 열 때 한 번 만들어 둔다 — 매 프레임 만들면 프레임마다 할당이 생긴다.
    editor_lines: []const []const u8 = &.{},
    /// 열려 있는 파일의 절대 경로(owned). 탭 라벨과 컨트롤 플레인 `EditorMeta.path`가 읽는다.
    editor_path: ?[]u8 = null,
    /// **구문 강조 상태**(§5.3 1층 — tree-sitter 트리와 그 파생 색). 위 셋과 **같은 묶음**이라
    /// 함께 살고 함께 죽는다(`releaseEditorTerm`). grammar가 없으면 안이 비어 있고, 그러면 그
    /// 문서는 끝까지 무색이다 — 실패가 아니라 저하다(§5).
    editor_syntax: editor_ops.syntax_color.State = .{},
    /// 체인 마디의 열 범위 — **렌더가 굳히고 클릭이 읽는다**(§7.5·§4.1g).
    editor_crumb_spans: std.ArrayList(maru.cell_text.ColSpan) = .empty,
    /// 마지막으로 그린 프레임이 센 **문서 전체 시각 행 수**(랩 포함). 0이면 아직 안 그렸다.
    ///
    /// **렌더만 접힘을 안다.** 스크롤 입력은 논리 줄만 아는데, 랩된 문서에서 "화면에 다 들어가는가"는
    /// 시각 행으로만 판정된다 — 그 값을 여기 실어 입력이 읽는다.
    editor_total_visual_rows: u32 = 0,
    /// 화면 맨 위에 올 논리 줄. 스크롤 입력이 여기를 움직인다.
    editor_first_line: usize = 0,
    /// 접을 수 있는 범위(§4.1f — 들여쓰기 층). **명령이 필요할 때 세어 여기 둔다** — 렌더는 할당하지
    /// 않고 이것을 읽기만 한다. 비어 있으면 아직 안 셌거나 접을 것이 없다.
    editor_fold_ranges: []const maru.session.editor.fold.Range = &.{},
    /// 접힘이 적용된 **보이는 줄** 배열과 그 원래 줄 번호. 비어 있으면 접힌 것이 없어 `editor_lines`를
    /// 그대로 그린다.
    ///
    /// **렌더를 안 고치려고 이 모양을 골랐다** — diff가 filler 행에 쓰는 `lines` + `line_numbers` 쌍과
    /// 같다(§4.1f). 접힘이 바뀔 때만 다시 만들고 프레임마다는 읽기만 한다.
    editor_visible_lines: []const []const u8 = &.{},
    editor_visible_numbers: []const ?u32 = &.{},
    /// 그리는 줄마다의 **접힘 표식**(gutter 화살표). 줄 배열과 같은 축이고, 접힘이 바뀔 때만 다시
    /// 채운다 — 렌더는 읽기만 한다.
    ///
    /// **저장소를 문서 줄 수만큼 미리 잡는다**(`editor_folded_buf`와 같은 규율). 보이는 줄은 문서
    /// 줄보다 많을 수 없으므로 이 한 번으로 충분하고, 그래서 **펼치기가 할당 없이 끝난다** — 펼치기
    /// 경로에 실패 지점이 생기면 실패했을 때 접힌 화면에 갇힌다(그 결함을 이미 한 번 잡았다).
    editor_fold_marks: []chrome.components.editor_view.gutter.Fold = &.{},
    editor_fold_marks_len: usize = 0,
    /// 줄별 시각 행 수의 **접두합 캐시**(§2.1 — 문서 크기에 비례하는 작업을 매 프레임 하지 않는다).
    ///
    /// **왜 여기 있나.** 스크롤바 길이와 위치는 문서 전체의 시각 행 수에서 나오는데(§4.1a) 그 계수가
    /// 문서 크기에 비례한다. 캐시가 없으면 정지 상태에서도 매 프레임 전 문서를 다시 접어 보게 되고,
    /// 실측으로 4,000줄 랩 문서가 프레임당 12.9ms였다(ReleaseFast, 2026-08-18 — 60fps 예산의 76%).
    ///
    /// 유효성 판정과 계수는 **컴포넌트가 한다**(`frame.RowCache`) — 랩이 갈리는 본문 폭이 그쪽에서
    /// 정해지므로, 제품이 그 폭을 다시 구하면 출처가 둘이 된다. 여기는 저장소만 소유한다.
    editor_row_cache: chrome.components.editor_view.frame.RowCache = .{ .prefix = &.{} },
    /// 접힌 머리 줄들. **오름차순**이고 `editor_fold_ranges.len`만큼의 자리를 미리 잡아 두므로
    /// 접기/펼치기가 다시 할당하지 않는다(`hiddenSpans`가 오름차순을 계약으로 요구한다).
    editor_folded_buf: []u32 = &.{},
    editor_folded_len: usize = 0,

    /// 접힘 범위를 **구문 층으로 이미 덮었는가**(§4 — 들여쓰기 위에 tree-sitter 가 쌓인다).
    ///
    /// 여는 자리에서는 트리가 아직 없을 수 있어(§2.1a 예산) 들여쓰기로 세우고, 파싱이 끝난 프레임에
    /// 한 번 덮는다. 이 표시가 없으면 **매 프레임 다시 세게 된다** — 트리는 그대로인데 훑기와 할당이
    /// 프레임마다 돈다.
    editor_syntax_folds_applied: bool = false,
    /// 접힘 집합을 바꾸기 **직전의 집합**. 다시 만들기가 실패하면 여기서 되돌린다.
    ///
    /// **길이만 되돌리는 것으로는 부족하다.** 전체 접기뿐이던 시절에는 집합이 "전부 아니면 없음"이라
    /// 길이가 곧 내용이었지만, 레벨 접기가 들어오면 같은 길이라도 **다른 머리들**이다. 백업 없이
    /// 되돌리면 화면과 상태가 갈린다(그 부류를 이미 한 번 잡았다 — 펼치기가 거절돼 숨은 줄을 영영
    /// 못 되찾은 결함). `editor_folded_buf`와 같은 크기를 미리 잡아 **되돌리기에 실패 지점이 없다.**
    editor_folded_prev: []u32 = &.{},
    /// 화면 맨 위 줄에서 **건너뛸 조각 수**(§4.1d — 앵커 + 조각 오프셋).
    ///
    /// **앵커는 `editor_first_line`, 오프셋은 이것**이다. 논리 줄만 들면 줄 안쪽에 설 수 없어,
    /// 한 줄짜리 문서를 랩으로 열면 첫 화면 밖을 볼 방법이 없다(20만 자 한 줄 = 시각 행 2,248개).
    /// 랩이 꺼져 있으면 줄마다 조각이 하나라 늘 0이다.
    editor_first_piece: u32 = 0,
    /// 렌더가 실어 두는 **스크롤 상한** `(줄, 조각)`. `editor_total_visual_rows`와 같은 관례다 —
    /// 입력 쪽에서 구하려면 문서 끝에서 거꾸로 조각을 누적해야 하는데 clamp는 매 프레임 돈다.
    /// `line == 0 and piece == 0`이면 아직 안 그렸거나 문서가 화면에 다 들어간다.
    editor_max_top_line: usize = 0,
    editor_max_top_piece: u32 = 0,
    /// **마지막 프레임이 그린 행들**(§4.1g ②). 행마다
    /// `{원본 줄, piece, start_col, start_byte, start_byte_col}`이고,
    /// 클릭이 화면 좌표를 문서 위치로 옮길 때 이것을 읽는다.
    ///
    /// **왜 복사해 드나.** 렌더가 채우는 배열은 `appendPaneFrame`의 **스택 지역**이라 프레임이 끝나면
    /// 사라진다(`Written.visual_rows`는 개수일 뿐이다). 클릭은 렌더 **다음에** 오므로 그 결과가 살아
    /// 있어야 한다 — 스크롤바 기하(`editor_scrollbar`)를 싣는 것과 같은 자리·같은 수명이고, 다음
    /// 프레임이 통째로 덮는다.
    ///
    /// **캐시가 아니다.** 재계산을 피하려는 것이 아니라 마지막 결과를 들고 있는 것뿐이라 무효화 축이
    /// 없다. §2.1 `RowCache`가 접두합을 **프레임 사이에 살려 두는** 것과는 성격이 다르다.
    ///
    /// **스냅숏은 이 셋이다** — 이 배열, `editor_hit_lines`, `editor_hit_geom`. 기하와 셀 크기까지
    /// 굳혔으므로 `hitTestBody`가 live로 읽는 것은 **문서 내용뿐**이다(`editor_lines`·`editor_doc`).
    /// 그 둘은 편집이 있으면 바뀌지만, 편집은 렌더를 부르므로 배열도 함께 갱신된다.
    ///
    /// 여기까지 오는 데 두 번 틀렸다. 초판 doc은 *"live 상태를 하나도 안 읽는다"*고 적었고 그것이
    /// 거짓이라 7차가 잡았다. 그 정정문("layout을 live로 다시 계산한다")도 11차 시점에 거짓이 됐다 —
    /// `editor_hit_geom`이 그 계산을 렌더로 옮겼기 때문이다. **읽는 축을 세는 문장은 축이 바뀔 때마다
    /// 함께 고쳐야 한다**(§4.1g "아직 검증되지 않는 문장" 표가 같은 이유로 있다).
    ///
    /// **`RowCache` 접두합을 되짚지 않는 이유**도 여기 있다: 그 값은 점진 계수 중이면 근사이고
    /// (`filled_upto` 뒤는 "줄당 한 행"), 막대가 짧게 보이는 것은 감수해도 **클릭이 근사하면 누른 줄과
    /// 다른 줄이 선택된다**. 이 배열은 실제로 그린 결과다.
    editor_hit_rows: []chrome.ui.visual_map.VisualRow = &.{},
    /// 위 배열에서 **이번 프레임이 실제로 채운 길이**. 배열은 한 번 잡으면 줄이지 않으므로
    /// (창이 작아져도 재할당하지 않는다) 유효 구간을 이 값이 정한다. `0`이면 클릭을 받지 않는다 —
    /// 아직 안 그렸거나 저장소를 못 잡은 프레임이다.
    editor_hit_rows_len: usize = 0,
    /// 행마다의 **원본 논리 줄**(`editor_hit_rows`와 같은 축·같은 길이).
    ///
    /// **`VisualRow.line`을 그대로 쓸 수 없다** — 그것은 뷰포트 첫 줄로부터의 **상대 인덱스**이고,
    /// 접힘이 켜지면 그 축이 "보이는 줄"이라 원본 줄이 아니다. 풀려면 `editor_first_line`과
    /// `editor_visible_numbers` 둘이 필요한데, **둘 다 프레임 사이에 바뀐다**: 스크롤 입력은
    /// `first_line`을, 접힘 토글은 번호 표를 바꾸고 각각 `metal_dirty`만 세운다. 그 사이 클릭이 오면
    /// **옛 행 배열 × 새 해석**이 되고, 실측으로 접힘 토글 뒤 클릭이 **36줄** 어긋났다(2차 적대적 검증).
    ///
    /// 그래서 **푸는 것을 렌더 시점으로 옮겼다.** 행을 저장할 때 이미 절대 줄을 함께 굳히면
    /// `hitTestBody`가 이 배열들만으로 행을 해석한다 — 축을 하나씩 스냅숏으로 늘리는 것보다 적게
    /// 틀린다(§4.1g ②가 "마지막 프레임의 산출물"이라 한 것의 온전한 형태다).
    editor_hit_lines: []u32 = &.{},
    /// 그 행들을 그릴 때의 **기하와 셀 크기**. 클릭이 픽셀을 열로 바꾸려면 본문 원점·gutter 폭·본문
    /// 폭·셀 크기가 필요한데, 그것을 클릭 시점에 다시 구하면 **행 배열과 다른 프레임의 값**이 된다.
    ///
    /// 실측(10차 적대적 검증): 넓게 그린 뒤 좁은 rect로 클릭하면 답의 **80%**가 달랐고, **그 다른
    /// 답 중** 76%는 논리 줄까지 달랐다(최대 7줄 — 전체로는 61%). 노출 창은 리사이즈 다음 프레임까지로
    /// 좁지만, 그 창이 `editor_hit_lines`가 없앤 36줄 어긋남과 **같은 부류**다 — 그때는 세로 축만
    /// 굳혔고 가로·원점이 남아 있었다.
    ///
    /// **이 수치는 이제 재현할 수 없다** — `hitTestBody`가 `leaf_rect`를 안 받으므로 "넓게 그린 뒤 좁은
    /// rect로 클릭"이라는 호출 자체가 성립하지 않는다. 그것이 이 필드가 한 일이다.
    ///
    /// **셀 크기도 여기 든다**(11차 적대적 검증). 처음에는 원점·폭만 굳히고 `cell_width_px`를 live로
    /// 곱했는데, 그러면 한 표현식 안에서 **굳은 값과 live 값이 섞인다**: 8×16으로 그린 뒤 폰트가
    /// 12×24로 바뀌고 아직 다시 안 그린 창에서 본문 격자 64발 중 **60발(93%)**이 정합 상태와 달랐고,
    /// **59발(92%)**이 화면에 실제로 보이는 것과도 달랐다 — 어느 쪽 기준으로도 틀린 답이다. 노출 창은
    /// 리사이즈와 **같은 폭**이고, 그 폭이 이 필드를 만든 근거였다.
    /// 본문 **텍스트 선택**(§4.1g가 좌표계를, `session/editor/selection.zig`가 모델을 소유한다).
    ///
    /// `null`이면 선택도 caret도 없다 — 읽기 전용 뷰라 caret을 늘 그리지는 않는다(N2에서 편집이
    /// 들어오면 그때 늘 있는 것이 된다).
    ///
    /// **문서 전체 offset이다**(줄 안 offset이 아니다). `Selection`이 다중 줄 선택을 표현해야 하므로
    /// 그렇게 정했고, `hitTestBody`가 ⑤단계에서 `line_index`로 옮겨 준다.
    ///
    /// 렌더가 아니라 **입력이 세운다**. 렌더는 이 값을 읽어 띠를 그릴 뿐이고, 다음 프레임이 덮지
    /// 않는다 — `editor_hit_*`(렌더가 굳히는 스냅숏)와 방향이 반대다.
    editor_selection: ?maru.session.editor.selection.Selection = null,
    /// **IME 조합 중 글자**(N3 — native-editor.md §11). 문서에 넣지 않고 **화면에만** 끼워 그린다 —
    /// 조합은 아직 확정이 아니므로 버퍼에 들어가면 undo·저장·검색이 전부 그것을 진짜 내용으로 본다.
    /// 터미널이 `terminal/preedit.zig`로 하는 것과 **같은 모델**이다(줄에 끼우고 뒤를 민다).
    ///
    /// 편집기 Term은 코어가 1×1 sentinel이라 그쪽 오버레이가 화면에 닿지 않는다 — 그래서 여기 든다.
    editor_preedit: []u8 = &.{},
    /// 조합이 시작된 **문서 offset**. 확정 텍스트가 갈 자리이자 조합 글자를 끼울 자리다.
    editor_preedit_at: usize = 0,
