    /// CR6a-1 app-global projection publish seam. 아직 launch coordinator caller는 0이며 socket/adopt 효과도 없다.
    pub fn replaceRecoveredSessionsProjection(
        self: *AppSession,
        ws: maru.session.workspace.Workspace,
        inventories: []const maru.session.runtime_reconcile.HostInventory,
        primary_window: bool,
        workspace_generation: u64,
    ) !void {
        try app_recovered_sessions_projection.refresh(std.heap.smp_allocator, .{
            .keep_alive = appKeepAlivePolicyValue(),
            .primary_window = primary_window,
            .quick_window = self.is_quick,
            .workspace_generation = workspace_generation,
        }, ws, inventories);
        bindRecoveredEndedManifestOrdinals();
    }

    pub fn recoveredSessionsRows(self: *const AppSession, primary_window: bool) []const session_host.recovered_sessions_projection.Row {
        if (!primary_window or self.is_quick or !appKeepAlivePolicyValue()) return &.{};
        return app_recovered_sessions_projection.rows;
    }

    /// CR6c actual-AppKit smoke의 read-only 관측면. 제품 action identity나 runtime handle을
    /// 내보내지 않고 이미 발행된 recovery row의 backing-pixel rect와 채택 뒤의 총계만 준다.
    /// Swift는 이 rect로 실제 NSEvent를 만들 수 있지만 activateRecoveredSessionAt을 직접
    /// 부를 수 없으므로, sidebar hit-test가 계속 유일한 click 제품 경계다.
    pub const RecoveredSessionAppKitSmokeProbe = struct {
        row_present: bool = false,
        row_x_px: i32 = 0,
        row_y_px: i32 = 0,
        row_width_px: u32 = 0,
        row_height_px: u32 = 0,
        recovered_count: u32 = 0,
        tab_count: u32 = 0,
        surface_initialized: bool = false,
        active_remote: bool = false,
        marker_present: bool = false,
        async_wake_marker_present: bool = false,
        c3c_historical_count: u32 = 0,
        c3c_disconnect_after_count: u32 = 0,
        c3c_input_count: u32 = 0,
        c3c_sibling_live: bool = false,
        c3c_sibling_controller: bool = false,
        cols: u16 = 0,
        rows: u16 = 0,
        keep_alive_enabled: bool = false,
        discovered_candidates: u32 = 0,
        ready_adapters: u32 = 0,
        inventory_runtimes: u32 = 0,
        configured_keep_alive: bool = false,
        live_session_count: u32 = 0,
        target_activation_dispatched: bool = false,
    };

    pub fn recoveredSessionAppKitSmokeProbe(self: *AppSession) RecoveredSessionAppKitSmokeProbe {
        const expected_raw = std.c.getenv("MARU_SESSION_HOST_CR6C_RUNTIME_ID") orelse return .{};
        const expected_text = std.mem.span(expected_raw);
        if (expected_text.len != 32) return .{};
        for (expected_text) |byte| if (!std.ascii.isDigit(byte) and (byte < 'a' or byte > 'f')) return .{};
        const expected_runtime_id = std.fmt.parseInt(u128, expected_text, 16) catch return .{};
        if (expected_runtime_id == 0) return .{};
        var out: RecoveredSessionAppKitSmokeProbe = .{
            .tab_count = @intCast(@min(self.tabs.items.len, std.math.maxInt(u32))),
            .surface_initialized = self.surface_initialized,
            .keep_alive_enabled = appKeepAlivePolicyValue(),
            .discovered_candidates = app_recovery_smoke_discovered_candidates,
            .ready_adapters = app_recovery_smoke_ready_adapters,
            .inventory_runtimes = app_recovery_smoke_inventory_runtimes,
            .configured_keep_alive = self.loaded_config.config.session.keep_alive_after_quit,
            .live_session_count = @intCast(@min(live_app_sessions, std.math.maxInt(u32))),
            .target_activation_dispatched = app_recovery_smoke_last_activated_runtime_id == expected_runtime_id,
        };
        if (std.c.getenv("MARU_SESSION_HOST_CR6E_C3C_SIBLING_RUNTIME_ID")) |sibling_raw| {
            const sibling_text = std.mem.span(sibling_raw);
            if (sibling_text.len == 32) sibling: {
                for (sibling_text) |byte| if (!std.ascii.isDigit(byte) and (byte < 'a' or byte > 'f'))
                    break :sibling;
                const remote = if (app_remote_backend) |*backend| backend else break :sibling;
                for (self.tabs.items) |tab| for (tab.panes.items) |pane| for (pane.terms.items) |term| {
                    if (term.surface.remote == null) continue;
                    const runtime_id = remote.runtimeIdFor(term.rt.handle) orelse continue;
                    if (!std.mem.eql(u8, &runtime_id, sibling_text)) continue;
                    out.c3c_sibling_live = remote.currentAttachmentLive(term.rt.handle);
                    out.c3c_sibling_controller = out.c3c_sibling_live and
                        !remote.attachedAsObserver(term.rt.handle);
                    break :sibling;
                };
            }
        }
        for (self.sidebar_rows.items, 0..) |row, index| switch (row) {
            .recovered_session => |candidate| {
                const rows = self.recoveredSessionsRows(self.is_primary_window);
                if (candidate.projection_index >= rows.len or
                    rows[candidate.projection_index].runtime_id != expected_runtime_id) continue;
                const metrics = sidebar_ops.sidebarMetrics(self);
                const top = chrome.components.sidebar.rowTop(
                    self.sidebar_rows.items,
                    index,
                    self.sidebar_header_height_px,
                    metrics,
                    self.sidebar_scroll_offset_px,
                );
                const height = chrome.components.sidebar.rowHeight(row, metrics);
                out.row_present = height > 0 and self.sidebar_width_px > 0;
                out.row_x_px = 0;
                out.row_y_px = @intCast(top);
                out.row_width_px = self.sidebar_width_px;
                out.row_height_px = height;
                out.recovered_count = 1;
                break;
            },
            else => {},
        };
        if (self.tabs.items.len == 0) return out;
        const tab = self.tabs.items[@min(self.app_window.active_tab, self.tabs.items.len - 1)];
        if (tab.panes.items.len == 0) return out;
        const pane = tab.panes.items[@min(tab.active_pane, tab.panes.items.len - 1)];
        if (pane.terms.items.len == 0) return out;
        const term = pane.terms.items[@min(pane.active_term, pane.terms.items.len - 1)];
        out.active_remote = term.surface.remote != null;
        if (!out.active_remote) return out;
        const recent = self.backendFor(term).dumpRecentText(
            term.rt.handle,
            self.allocator,
            8,
            4096,
        ) catch return out;
        defer self.allocator.free(recent);
        out.marker_present = std.mem.indexOf(u8, recent, "CR6C-RECOVERED-MARKER") != null;
        out.async_wake_marker_present = std.mem.indexOf(u8, recent, "E3C-APPKIT-ASYNC-WAKE") != null;
        out.c3c_historical_count = @intCast(@min(
            std.mem.count(u8, recent, "CR6E-C3C-HISTORICAL-ONCE"),
            std.math.maxInt(u32),
        ));
        out.c3c_disconnect_after_count = @intCast(@min(
            std.mem.count(u8, recent, "CR6E-C3C-AUTO-RECONNECTED"),
            std.math.maxInt(u32),
        ));
        out.c3c_input_count = @intCast(@min(
            std.mem.count(u8, recent, "CR6E-C3C-INPUT-ONCE"),
            std.math.maxInt(u32),
        ));
        out.cols = term.rt.observation.size.cols;
        out.rows = term.rt.observation.size.rows;
        return out;
    }

    /// CR6d reads only the exact recovered runtime's published screen. The runtime id remains in
    /// the harness environment and is compared with RemoteTermBackend's canonical binding; no
    /// handle, input method, or action identity crosses the ABI.
    pub const SessionHostInputSmokeProbe = struct {
        active_remote: bool = false,
        historical_count: u32 = 0,
        ime_count: u32 = 0,
        clipboard_count: u32 = 0,
    };

    pub fn sessionHostInputSmokeProbe(self: *AppSession) SessionHostInputSmokeProbe {
        const expected_raw = std.c.getenv("MARU_SESSION_HOST_CR6C_RUNTIME_ID") orelse return .{};
        const expected_text = std.mem.span(expected_raw);
        if (expected_text.len != 32) return .{};
        for (expected_text) |byte| if (!std.ascii.isDigit(byte) and (byte < 'a' or byte > 'f')) return .{};

        if (self.tabs.items.len == 0) return .{};
        const tab = self.tabs.items[@min(self.app_window.active_tab, self.tabs.items.len - 1)];
        if (tab.panes.items.len == 0) return .{};
        const pane = tab.panes.items[@min(tab.active_pane, tab.panes.items.len - 1)];
        if (pane.terms.items.len == 0) return .{};
        const term = pane.terms.items[@min(pane.active_term, pane.terms.items.len - 1)];
        if (term.surface.remote == null) return .{};
        const remote = if (app_remote_backend) |*backend| backend else return .{};
        const runtime_id = remote.runtimeIdFor(term.rt.handle) orelse return .{};
        if (!std.mem.eql(u8, &runtime_id, expected_text)) return .{};

        const recent = self.backendFor(term).dumpRecentText(
            term.rt.handle,
            self.allocator,
            16,
            8192,
        ) catch return .{};
        defer self.allocator.free(recent);
        return .{
            .active_remote = true,
            .historical_count = @intCast(@min(
                std.mem.count(u8, recent, "CR6D-HISTORICAL-ONCE"),
                std.math.maxInt(u32),
            )),
            // UTF-8 bytes for the CR6d committed IME marker. This is a smoke oracle, not a
            // localized product string, so it must not enter the UI translation inventory.
            .ime_count = @intCast(@min(std.mem.count(u8, recent, "\xed\x95\x9c\xea\xb8\x80"), std.math.maxInt(u32))),
            .clipboard_count = @intCast(@min(
                std.mem.count(u8, recent, "CR6D-CLIPBOARD-ONCE"),
                std.math.maxInt(u32),
            )),
        };
    }

    /// CR6b one-item adopt 제품 진입점. Sidebar row는 단지 locator이며, 현재 pool generation과 fresh
    /// host.info/runtime.get을 다시 확인한 뒤에만 exact runtime attach를 시작한다. 실패는 projection과 topology를
    /// 그대로 두고, attach 뒤 construction 실패는 createTerm의 client-side detach errdefer가 host runtime을 보존한다.
    pub fn activateRecoveredSessionAt(self: *AppSession, projection_index: usize) !void {
        if (!self.is_primary_window or self.is_quick or !appKeepAlivePolicyValue())
            return error.InvalidAuthority;
        if (projection_index >= app_recovered_sessions_projection.rows.len)
            return error.InvalidAuthority;
        const row = app_recovered_sessions_projection.rows[projection_index];
        app_recovery_smoke_last_activated_runtime_id = row.runtime_id;
        const next_projection_generation = try app_recovered_sessions_projection.validateExact(projection_index, row);
        const ended_location: ?RecoveredEndedLocation = switch (row.kind) {
            .orphan => null,
            .ended_present_conflict => try locateRecoveredEnded(row),
        };
        const pool = if (app_remote_host_pool) |*value| value else return error.SessionHostUnavailable;
        const adapter_generation = pool.adapterGeneration(row.host_id) orelse return error.InvalidAuthority;
        const adapter = pool.get(row.host_id) orelse return error.InvalidAuthority;
        if (adapter.hostId() != row.host_id) return error.InvalidAuthority;

        const allocator = std.heap.smp_allocator;
        const action_deadline = session_host.client_deadline.AbsoluteDeadline.after(
            self.io,
            session_host.recovered_session_adopt.action_deadline_ns,
        ) catch return error.InvalidAuthority;
        const host_info = try adapter.callUntil("host.info", "{}", action_deadline);
        defer allocator.free(host_info);
        var runtime_id_buf: [32]u8 = undefined;
        _ = std.fmt.bufPrint(&runtime_id_buf, "{x:0>32}", .{row.runtime_id}) catch unreachable;
        var params_buf: [64]u8 = undefined;
        const params = std.fmt.bufPrint(&params_buf, "{{\"runtime_id\":\"{s}\"}}", .{&runtime_id_buf}) catch
            return error.InvalidAuthority;
        const runtime_info = try adapter.callUntil("runtime.get", params, action_deadline);
        defer allocator.free(runtime_info);
        try session_host.recovered_session_adopt.validateFreshEvidence(allocator, row, .{
            .projection_generation = app_recovered_sessions_projection.generation,
            .workspace_generation = app_recovered_sessions_workspace_generation,
            .adapter_generation = adapter_generation,
            .adapter_host_id = adapter.hostId(),
        }, host_info, runtime_info);

        var host_id_buf: [32]u8 = undefined;
        _ = std.fmt.bufPrint(&host_id_buf, "{x:0>32}", .{row.host_id}) catch unreachable;
        switch (row.kind) {
            .orphan => {
                try self.attachExistingRuntimeInNewTab(&host_id_buf, &runtime_id_buf);
                // `createTerm` keeps this bit set only while an existing host runtime is staged: every
                // fallible suffix before publication must detach instead of terminating it.  The tab is
                // now part of the live AppSession graph, so later user/window teardown owns the normal
                // terminate path just like a successfully published workspace restore.
                app_recovered_sessions_projection.consumeExactNoFail(
                    projection_index,
                    row,
                    next_projection_generation,
                );
            },
            .ended_present_conflict => try replaceRecoveredEnded(
                ended_location orelse return error.InvalidAuthority,
                &host_id_buf,
                &runtime_id_buf,
                projection_index,
                row,
                next_projection_generation,
            ),
        }
        sidebar_ops.rebuildSidebar(self) catch {};
        self.metal_dirty = true;
    }

    fn replaceRecoveredEnded(
        location: RecoveredEndedLocation,
        host_id: []const u8,
        runtime_id: []const u8,
        projection_index: usize,
        row: session_host.recovered_sessions_projection.Row,
        next_projection_generation: u64,
    ) !void {
        if (!recoveredEndedLocationCurrent(location)) return error.InvalidAuthority;
        const target = location.session;
        const tomb = location.tomb;
        const carried_name: ?[]const u8 = if (tomb.surface.custom_name) |name|
            try target.allocator.dupe(u8, name)
        else
            null;
        errdefer if (carried_name) |name| target.allocator.free(name);

        const size = terminal.clampGridSize(tomb.surface.core.size);
        var cfg = target.new_tab_config;
        cfg.size = size;
        const request = spawnRequest(
            cfg,
            target.loaded_config.config.term,
            target.loaded_config.config.shell,
            target.loaded_config.config.env,
            target.shellIntegrationZdotdir(),
            target.new_tab_ssh_bin,
        );
        std.debug.assert(target.restore_runtime_host_id.len == 0 and target.restore_runtime_id.len == 0);
        target.restore_runtime_host_id = host_id;
        target.restore_runtime_id = runtime_id;
        errdefer {
            target.restore_runtime_host_id = "";
            target.restore_runtime_id = "";
        }
        const fresh = try term_ops.createTerm(target, request, size, cfg.queue_capacity, "Maru", commandName(cfg.command_kind));
        var fresh_owned = true;
        errdefer if (fresh_owned) term_ops.destroyTerm(target, fresh);
        if (!recoveredEndedLocationCurrent(location)) return error.InvalidAuthority;

        fresh.surface.custom_name = carried_name;
        fresh.rt.restored_existing = false;
        location.pane.terms.items[location.term_index] = fresh;
        fresh_owned = false;
        app_recovered_sessions_projection.consumeExactNoFail(
            projection_index,
            row,
            next_projection_generation,
        );
        // The exact pane-slot replacement is the publication point.  Before this store the errdefer
        // above must preserve the host runtime; after it, the live Term has ordinary close ownership.
        term_ops.destroyTerm(target, tomb);
        const tab = target.tabs.items[location.tab_index];
        target.surface_ptrs.items[location.tab_index] = tab.activePane().activeTerm().surface;
        target.app_window.tabs = target.surface_ptrs.items;
        workspace_ops.advanceSessionHostWindowGraph(target);
        term_ops.finishInitialSurface(target);
        // exact pane-slot이 live runtime으로 교체되고 tombstone 소유권까지 끝난 뒤의 제품 commit.
        target.workspaceChanged(.runtime_binding);
        if (location.tab_index == target.app_window.active_tab) pane_ops.recomputeActivePaneRect(target);
        sidebar_ops.rebuildSidebar(target) catch {};
        target.metal_dirty = true;
    }

    pub fn setPrimaryWindow(self: *AppSession, value: bool) void {
        const next = value and !self.is_quick;
        if (self.is_primary_window == next) return;
        self.is_primary_window = next;
        sidebar_ops.rebuildSidebar(self) catch {};
        self.metal_dirty = true;
    }

    pub const RecoveredSessionsLaunchOutcome = enum(u32) {
        skipped = 0,
        published = 1,
        unavailable = 2,
    };

    /// CR6a-2 launch-before-terminal coordinator. 저장 Workspace 전체 binding과 secure host inventory를 한 번에
    /// reconcile해 app-global projection을 교체한다. attach/adopt/runtime spawn은 하지 않는다.
    pub fn prepareRecoveredSessionsAtLaunch(self: *AppSession, workspace_text: ?[]const u8) RecoveredSessionsLaunchOutcome {
        if (!is_macos or !appKeepAlivePolicyValue() or self.is_quick or !self.is_primary_window)
            return .skipped;
        if (app_recovered_sessions_launch_attempted) return .skipped;
        app_recovered_sessions_launch_attempted = true;

        const allocator = std.heap.smp_allocator;
        var arena_state = std.heap.ArenaAllocator.init(allocator);
        defer arena_state.deinit();
        const arena = arena_state.allocator();

        const base = sessionHostRuntimeBase(arena) orelse return .unavailable;
        return self.prepareRecoveredSessionsAtLaunchFromBase(workspace_text, base, arena);
    }

    fn prepareRecoveredSessionsAtLaunchFromBase(
        self: *AppSession,
        workspace_text: ?[]const u8,
        base: []const u8,
        arena: std.mem.Allocator,
    ) RecoveredSessionsLaunchOutcome {
        const allocator = std.heap.smp_allocator;

        var parsed: ?maru.session.workspace.ParsedWorkspace = null;
        defer if (parsed) |*value| value.deinit();
        const ws: maru.session.workspace.Workspace = if (workspace_text) |text| blk: {
            parsed = maru.session.workspace.parse(allocator, text) catch return .unavailable;
            break :blk parsed.?.workspace;
        } else .{ .windows = &.{} };
        maru.session.workspace.validateRuntimeBindings(arena, ws) catch return .unavailable;

        var dir_buf: [512]u8 = undefined;
        const session_dir = session_host.discovery.sessionHostDirPath(&dir_buf, base) catch return .unavailable;
        var discovered = session_host.recovery_discovery.discover(allocator, session_dir);
        defer discovered.deinit(allocator);
        const entries = switch (discovered) {
            .unavailable => return .unavailable,
            .complete => |items| items,
        };

        var candidates: std.ArrayListUnmanaged(session_host.recovery_discovery.Candidate) = .empty;
        defer candidates.deinit(arena);
        var adapter_generations: std.ArrayListUnmanaged(u64) = .empty;
        defer adapter_generations.deinit(arena);
        app_recovery_smoke_discovered_candidates = 0;
        app_recovery_smoke_ready_adapters = 0;
        app_recovery_smoke_inventory_runtimes = 0;
        for (entries) |entry| switch (entry) {
            .unavailable => {},
            .candidate => |candidate| {
                app_recovery_smoke_discovered_candidates +|= 1;
                if (self.ensureRestoreHostAdapterAtBase(base, candidate.manifest.host_id) != .ready) continue;
                app_recovery_smoke_ready_adapters +|= 1;
                const generation = if (app_remote_host_pool) |*pool|
                    pool.adapterGeneration(candidate.manifest.host_id) orelse continue
                else
                    continue;
                candidates.append(arena, candidate) catch return .unavailable;
                adapter_generations.append(arena, generation) catch return .unavailable;
            },
        };

        const next_workspace_generation = std.math.add(u64, app_recovered_sessions_workspace_generation, 1) catch
            return .unavailable;
        var collection = session_host.recovery_discovery.collect(
            allocator,
            base,
            candidates.items,
            adapter_generations.items,
            next_workspace_generation,
        );
        defer collection.deinit(allocator);
        const inventories = switch (collection) {
            .unavailable => return .unavailable,
            .complete => |items| items,
        };
        for (inventories) |inventory| switch (inventory) {
            .unavailable => {},
            .complete => |value| app_recovery_smoke_inventory_runtimes +|= @intCast(value.runtimes.len),
        };
        var reconciled_inventories: std.ArrayListUnmanaged(maru.session.runtime_reconcile.HostInventory) = .empty;
        defer reconciled_inventories.deinit(arena);
        mergeDiscoveredInventories(
            arena,
            entries,
            candidates.items,
            inventories,
            &reconciled_inventories,
        ) catch |err| {
            if (std.c.getenv("MARU_SESSION_HOST_CR6C_APPKIT_SMOKE") != null)
                std.debug.print("CR6c recovery merge failed: {s}\n", .{@errorName(err)});
            return .unavailable;
        };
        self.replaceRecoveredSessionsProjection(ws, reconciled_inventories.items, true, next_workspace_generation) catch |err| {
            if (std.c.getenv("MARU_SESSION_HOST_CR6C_APPKIT_SMOKE") != null)
                std.debug.print("CR6c recovery projection failed: {s}\n", .{@errorName(err)});
            return .unavailable;
        };
        app_recovered_sessions_workspace_generation = next_workspace_generation;
        sidebar_ops.rebuildSidebar(self) catch {};
        self.metal_dirty = true;
        return .published;
    }

    fn mergeDiscoveredInventories(
        allocator: std.mem.Allocator,
        entries: []const session_host.recovery_discovery.Entry,
        collected_candidates: []const session_host.recovery_discovery.Candidate,
        collected_inventories: []const maru.session.runtime_reconcile.HostInventory,
        out: *std.ArrayListUnmanaged(maru.session.runtime_reconcile.HostInventory),
    ) !void {
        if (collected_candidates.len != collected_inventories.len) return error.InvalidAuthority;
        var collected_index: usize = 0;
        for (entries) |entry| switch (entry) {
            .unavailable => |value| try out.append(allocator, .{ .unavailable = .{
                .host_id = value.host_id,
                .reason = switch (value.reason) {
                    .invalid_manifest => .malformed,
                    .lease_free => .lifecycle,
                    .lease_unknown => .stale,
                },
            } }),
            .candidate => |value| {
                if (collected_index < collected_candidates.len and
                    collected_candidates[collected_index].manifest.host_id == value.manifest.host_id)
                {
                    if (collected_inventories[collected_index].hostId() != value.manifest.host_id)
                        return error.InvalidAuthority;
                    try out.append(allocator, collected_inventories[collected_index]);
                    collected_index += 1;
                } else try out.append(allocator, .{ .unavailable = .{
                    .host_id = value.manifest.host_id,
                    .reason = .endpoint,
                } });
            },
        };
        if (collected_index != collected_candidates.len) return error.InvalidAuthority;
        // Directory iteration order is not an authority. runtime_reconcile deliberately requires
        // one canonical host-id order so duplicate/spliced inventories fail closed; normalize the
        // discovery projection here before crossing that boundary. A single-host fixture cannot
        // expose this, while a normal machine with multiple live hosts otherwise makes launch
        // recovery unavailable nondeterministically.
        std.mem.sort(maru.session.runtime_reconcile.HostInventory, out.items, {}, struct {
            fn lessThan(_: void, lhs: maru.session.runtime_reconcile.HostInventory, rhs: maru.session.runtime_reconcile.HostInventory) bool {
                return lhs.hostId() < rhs.hostId();
            }
        }.lessThan);
    }

    /// Launch가 recovery inventory를 먼저 끝낸 뒤 저장 Workspace가 없거나 적용 불가일 때만 기본 shell surface를
    /// 명시적으로 완성한다. 이미 restore가 surface를 게시했으면 mutation 0이다.
    pub fn finishDeferredInitialSurface(self: *AppSession) !void {
        if (self.tabs.items.len != 0) return;
        // A published recovery row is the launch surface. Creating a throwaway default shell here
        // would both obscure that choice and create a second persistent runtime before the user
        // acts. The pre-surface mouse seam admits only a typed recovered row; successful adoption
        // calls finishInitialSurface itself, while an empty recovery projection still falls through.
        if (self.recoveredSessionsRows(self.is_primary_window).len != 0) return;
        var spawn_config = self.new_tab_config;
        if (spawn_config.width_px > 0 and spawn_config.height_px > 0) {
            spawn_config.size = layout_math.gridFromBacking(
                spawn_config.width_px,
                spawn_config.height_px,
                self.cell_width_px,
                self.cell_height_px,
                self.sidebar_width_px,
                self.gridPadding(),
            );
        }
        var first_req = spawnRequest(
            spawn_config,
            self.loaded_config.config.term,
            self.loaded_config.config.shell,
            self.loaded_config.config.env,
            self.new_tab_zdotdir,
            self.new_tab_ssh_bin,
        );
        var root_buf: [std.fs.max_path_bytes]u8 = undefined;
        self.applySpawnCwd(&first_req, &root_buf, false);
        _ = try tab_ops.createTab(
            self,
            first_req,
            spawn_config.size,
            spawn_config.queue_capacity,
            "Maru shell",
            commandName(spawn_config.command_kind),
        );
        term_ops.finishInitialSurface(self);
        self.writeSummaryFromState();
    }
