test "세션 base 와 턴 끝은 한 이벤트가 동시에 만들지 못한다 (AT1)" {
    // **이 배타성이 `SessionStart` 를 두 번 찍지 않게 하는 유일한 근거**다. 「겹치지 않는다」를 산문으로
    // 두면 다음 사람이 `opensSessionBase` 의 `previous != .running` 을 «불필요한 가드» 로 읽고 지운다 —
    // 그러면 turn-중간 resume 이 base 와 턴 끝을 동시에 세운다. 그래서 **값으로** 남긴다.
    //
    // 두 술어를 실제 제품 함수로 부른다(규칙을 여기서 다시 적지 않는다 — 그러면 단일 출처가 깨진다).
    const hook_mode = maru.session.agent_hook_mode;
    const turn_snapshot = maru.session.turn_snapshot;
    const states = [_]maru.session.agent_observer.State{ .unknown, .running, .blocked, .idle };
    for (states) |prev| {
        for ([_]maru.session.agent_hook_event.Kind{ .session_start, .stop, .user_prompt_submit, .pre_tool_use, .notification }) |kind| {
            const ev: maru.session.agent_hook_event.Event = .{ .kind = kind };
            const now = hook_mode.next(prev, ev);
            const ends = turn_snapshot.isTurnEnd(AppSession.turnStateOf(prev), AppSession.turnStateOf(now));
            const opens = hook_mode.opensSessionBase(prev, ev);
            try std.testing.expect(!(ends and opens));
        }
    }

    // 그리고 **둘 다 실제로 일어나는** 값들이다 — 위 단언이 「둘 다 늘 거짓」이라는 항진명제로 통과하지
    // 않게 각각 참이 되는 자리를 하나씩 못 박는다(적대적 검증: 그 함정을 이 저장소가 이미 겪었다).
    const start: maru.session.agent_hook_event.Event = .{ .kind = .session_start };
    try std.testing.expect(hook_mode.opensSessionBase(.unknown, start)); // cold start = base
    try std.testing.expect(turn_snapshot.isTurnEnd( // 턴 중간 resume = 턴 끝
        AppSession.turnStateOf(.running),
        AppSession.turnStateOf(hook_mode.next(.running, start)),
    ));
}

test "hook mode fills state and conversation from the event log, and only then" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const hook_mode = maru.session.agent_hook_mode;
    const hook_command = maru.session.agent_hook_command;
    const io = std.Io.Threaded.global_single_threaded.io();
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var env_guard = try workspace_ops.ProviderEnvGuard.capture(a);
    defer env_guard.restore();
    try tmp.dir.createDirPath(io, "home");
    try tmp.dir.createDirPath(io, "cache");

    var root_buf: [std.fs.max_path_bytes]u8 = undefined;
    const root = root_buf[0..try tmp.dir.realPath(io, &root_buf)];
    const home = try std.fmt.allocPrintSentinel(a, "{s}/home", .{root}, 0);
    defer a.free(home);
    const cache = try std.fmt.allocPrintSentinel(a, "{s}/cache", .{root}, 0);
    defer a.free(cache);
    const config = try std.fmt.allocPrintSentinel(a, "{s}/missing-config", .{root}, 0);
    defer a.free(config);
    try std.testing.expectEqual(@as(c_int, 0), setenv("HOME", home.ptr, 1));
    try std.testing.expectEqual(@as(c_int, 0), setenv("XDG_CACHE_HOME", cache.ptr, 1));
    try std.testing.expectEqual(@as(c_int, 0), setenv("MARU_CONFIG", config.ptr, 1));
    // provider 디렉터리를 만들지 않아 설치는 돌지 않는다 — 이 테스트가 보는 것은 **소비** 쪽이다.
    try std.testing.expectEqual(@as(c_int, 0), unsetenv("CLAUDE_CONFIG_DIR"));
    try std.testing.expectEqual(@as(c_int, 0), unsetenv("CODEX_HOME"));

    test_config_text = agent_hooks_on_config; // 게이트 on
    defer test_config_text = "";

    var session: AppSession = undefined;
    try session.init(io, a, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    const term = pane_ops.activePane(&session).activeTerm();
    // 에이전트가 붙은 것으로 둔다 — 프로세스 관측은 헤드리스로 재현할 수 없고, 이 테스트가 보는 것은
    // 그 뒤의 소비 경로다.
    term.agent_kind = .claude;

    // ① 로그 파일이 없으면 **관측 모드**다. 게이트가 켜졌다고 훅 모드로 앉히면, 훅이 깨진 사람은
    //    영영 빈 배지를 본다(관측도 안 도니까).
    try std.testing.expectEqual(hook_mode.Mode.observe, agent_ops.agentHookMode(&session, term));

    // 로그 경로에는 **인스턴스 칸**이 있다(계약 §4) — maru 를 두 개 띄워도 이름이 안 겹치게 하는 자리다.
    const events_dir = try std.fmt.allocPrint(a, "cache/maru/{s}/{d}", .{ hook_command.log_dir_rel, agent_ops.hookInstanceId() });
    defer a.free(events_dir);
    try tmp.dir.createDirPath(io, events_dir);
    const log_rel = try std.fmt.allocPrint(a, "{s}/{d}.ndjson", .{ events_dir, term.surfaceId() });
    defer a.free(log_rel);

    // ② 턴이 시작된다.
    const start_line = "claude\t{\"hook_event_name\":\"SessionStart\",\"session_id\":\"s1\"}\n";
    const prompt_line = "claude\t{\"hook_event_name\":\"UserPromptSubmit\",\"prompt\":\"테스트 프롬프트\"}\n";
    try tmp.dir.writeFile(io, .{ .sub_path = log_rel, .data = start_line ++ prompt_line });
    agent_ops.pollAgentHookEvents(&session, term, false);

    try std.testing.expect(term.agent_hook_log_present);
    try std.testing.expectEqual(hook_mode.Mode.hook, agent_ops.agentHookMode(&session, term)); // 이제 훅 모드
    try std.testing.expectEqual(maru.session.agent_observer.State.running, term.agent_state);
    try std.testing.expectEqualStrings("테스트 프롬프트", term.agent_transcript.owned.prompt());

    // ③ 턴이 끝난다 — **이어 붙인 부분만** 읽어야 한다(커서가 전진했으므로).
    const stop_line = "claude\t{\"hook_event_name\":\"Stop\",\"last_assistant_message\":\"끝났습니다\"}\n";
    try tmp.dir.writeFile(io, .{ .sub_path = log_rel, .data = start_line ++ prompt_line ++ stop_line });
    agent_ops.pollAgentHookEvents(&session, term, false);
    try std.testing.expectEqual(maru.session.agent_observer.State.idle, term.agent_state);
    try std.testing.expectEqualStrings("끝났습니다", term.agent_transcript.owned.reply());
    try std.testing.expectEqualStrings("테스트 프롬프트", term.agent_transcript.owned.prompt());

    // ④ 새 프롬프트가 오면 **이전 응답은 지운다** — 남겨 두면 「질문은 새것, 답은 옛것」이 붙는다.
    const next_prompt = "claude\t{\"hook_event_name\":\"UserPromptSubmit\",\"prompt\":\"다음 질문\"}\n";
    try tmp.dir.writeFile(io, .{ .sub_path = log_rel, .data = start_line ++ prompt_line ++ stop_line ++ next_prompt });
    agent_ops.pollAgentHookEvents(&session, term, false);
    try std.testing.expectEqualStrings("다음 질문", term.agent_transcript.owned.prompt());
    try std.testing.expectEqual(@as(usize, 0), term.agent_transcript.owned.reply().len);
    try std.testing.expectEqual(maru.session.agent_observer.State.running, term.agent_state);

    // ⑤ **커서가 실제로 전진한다.** 파일을 통째로 다시 읽어도 마지막 상태는 같아서 상태만 보면 그 차이가
    //    드러나지 않는다(뮤테이션이 «못 잡음» 으로 그것을 보여 줬다). 읽은 지점 자체를 단언한다.
    {
        const st = try tmp.dir.statFile(io, log_rel, .{});
        try std.testing.expectEqual(st.size, term.agent_hook_cursor.offset);
    }

    // ⑥ **회전을 크기만으로 판정하면 놓친다.** 같은 크기(또는 더 큰) 새 파일로 갈리면 옛 오프셋으로 새
    //    내용을 읽어 줄 가운데부터 파싱한다. 그 상황을 실제로 만든다: 새 파일의 **앞쪽**에 의미 있는
    //    이벤트를 두고, 옛 오프셋이 떨어지는 자리는 파싱되지 않는 긴 패딩으로 채운다.
    //    - inode 를 보면: 처음부터 읽어 `Stop` 을 만나 idle 이 된다.
    //    - 크기만 보면: 옛 오프셋(패딩 한가운데)부터 읽어 아무 이벤트도 못 얻고 상태가 그대로 남는다.
    {
        var rotated: std.ArrayListUnmanaged(u8) = .empty;
        defer rotated.deinit(a);
        try rotated.appendSlice(a, stop_line);
        try rotated.appendSlice(a, "claude\t");
        try rotated.appendNTimes(a, 'x', 4096); // JSON 이 아니라 파서가 버리는 줄
        try rotated.append(a, '\n');
        try tmp.dir.deleteFile(io, log_rel); // 새 inode 를 강제한다
        try tmp.dir.writeFile(io, .{ .sub_path = log_rel, .data = rotated.items });

        agent_ops.pollAgentHookEvents(&session, term, false);
        try std.testing.expectEqual(maru.session.agent_observer.State.idle, term.agent_state);
    }

    // ⑦ **알림은 전이에 붙는다**(계약 §6). 위 ⑥에서 `Stop` 을 읽어 idle 로 갔으므로 완료 알림이 예약돼
    //    있어야 하고, 꺼내 가면 슬롯이 비어 **두 번 울리지 않아야** 한다.
    {
        const notice = agent_ops.takeAgentHookNotice(&session, term) orelse return error.MissingHookNotice;
        try std.testing.expectEqual(maru.session.agent_hook_mode.Notice.done, notice.kind);
        try std.testing.expectEqualStrings("끝났습니다", notice.body);
        try std.testing.expectEqual(@as(?agent_ops.HookNotice, null), agent_ops.takeAgentHookNotice(&session, term));
    }

    // ⑧ **주의 알림은 디바운스한다.** 예약 직후에는 아직 안 띄우고, 그 사이 상태가 blocked 를 떠나면
    //    버린다(자동 승인으로 해소된 경우 — 배지만 바뀌고 배너는 안 뜬다).
    {
        term.agent_state = .blocked;
        term.agent_hook_notice.set(.attention, "Bash 실행 승인", session.awakeMs());
        try std.testing.expectEqual(@as(?agent_ops.HookNotice, null), agent_ops.takeAgentHookNotice(&session, term)); // 아직 이르다
        term.agent_state = .running; // 자동 승인으로 해소됐다
        try std.testing.expectEqual(@as(?agent_ops.HookNotice, null), agent_ops.takeAgentHookNotice(&session, term));
        try std.testing.expectEqual(maru.session.agent_hook_mode.Notice.none, term.agent_hook_notice.kind); // 버려졌다
    }

    // ⑨ **회전해도 마지막 이벤트를 잃지 않는다**(계약 §4.2). rename 하는 순간 훅이 열어 둔 fd 는 옛 inode 에
    //    계속 쓰므로, 회전본을 한 번 더 읽어 tail 을 건지지 않으면 그 사이 이벤트가 조용히 사라진다.
    {
        const hook_event = maru.session.agent_hook_event;
        // 상한을 넘길 만큼 채우되, **마지막 줄이 상태를 바꾸는 이벤트**여야 유실이 드러난다.
        var big: std.ArrayListUnmanaged(u8) = .empty;
        defer big.deinit(a);
        // 실측 payload 크기(≈4 KB)에 맞춘 줄로 채운다 — 짧은 줄로 채우면 1 MiB 를 만드는 데 2 만 줄이
        // 필요해 tick 상한(64) 때문에 테스트가 수백 번 돌아야 한다(그 배치로 한 번 실패했다).
        var filler: std.ArrayListUnmanaged(u8) = .empty;
        defer filler.deinit(a);
        try filler.appendSlice(a, "claude\t{\"hook_event_name\":\"PreToolUse\",\"tool_name\":\"Bash\",\"pad\":\"");
        try filler.appendNTimes(a, 'p', 4000);
        try filler.appendSlice(a, "\"}\n");
        while (big.items.len < hook_event.rotate_at_bytes + 1024) try big.appendSlice(a, filler.items);
        try big.appendSlice(a, "claude\t{\"hook_event_name\":\"Stop\",\"last_assistant_message\":\"회전 뒤에도 남는다\"}\n");
        try tmp.dir.writeFile(io, .{ .sub_path = log_rel, .data = big.items });

        term.agent_state = .unknown;
        term.agent_hook_cursor = .{};
        term.agent_hook_cursor_inode = 0;
        // tick 상한 때문에 한 번에 다 못 읽는다 — `more` 가 남으면 회전을 미루므로 여러 번 돈다.
        var spins: usize = 0;
        while (spins < 200) : (spins += 1) {
            agent_ops.pollAgentHookEvents(&session, term, false);
            if (term.agent_state == .idle) break; // 마지막 `Stop` 까지 읽었다
        }
        try std.testing.expectEqual(maru.session.agent_observer.State.idle, term.agent_state);
        try std.testing.expectEqualStrings("회전 뒤에도 남는다", term.agent_transcript.owned.reply());

        // 회전이 실제로 일어나 **원본이 작아졌다**(또는 사라졌다).
        const after = tmp.dir.statFile(io, log_rel, .{}) catch null;
        if (after) |st| try std.testing.expect(st.size < hook_event.rotate_at_bytes);
        // 회전본은 남지 않는다 — 건진 뒤 지운다.
        const rotated_rel = try std.fmt.allocPrint(a, "{s}{s}", .{ log_rel, hook_event.rotated_suffix });
        defer a.free(rotated_rel);
        try std.testing.expect(tmp.dir.statFile(io, rotated_rel, .{}) catch null == null);
    }

    // ⑩ **회전 뒤 새 파일을 처음부터 읽는다.** 커서를 되돌리지 않으면 옛 오프셋(1 MiB 근처)이 새 파일보다
    //    커서 «읽을 것이 없다» 로 보고 그 pane 의 이벤트가 영영 안 들어온다.
    {
        const fresh = "claude\t{\"hook_event_name\":\"UserPromptSubmit\",\"prompt\":\"회전 뒤 첫 줄\"}\n";
        try tmp.dir.writeFile(io, .{ .sub_path = log_rel, .data = fresh });
        agent_ops.pollAgentHookEvents(&session, term, false);
        try std.testing.expectEqualStrings("회전 뒤 첫 줄", term.agent_transcript.owned.prompt());
        try std.testing.expectEqual(maru.session.agent_observer.State.running, term.agent_state);
    }

    // ⑪ **회전 도중 죽어 남은 회전본을 거둔다.** rename 은 됐는데 tail 을 못 건지고 죽으면
    //    `<id>.ndjson.rotated` 가 남는다 — 읽지 않고 덮어쓰면 그 안의 이벤트를 통째로 잃는다.
    {
        const hook_event = maru.session.agent_hook_event;
        const rotated_rel = try std.fmt.allocPrint(a, "{s}{s}", .{ log_rel, hook_event.rotated_suffix });
        defer a.free(rotated_rel);
        try tmp.dir.writeFile(io, .{
            .sub_path = rotated_rel,
            .data = "claude\t{\"hook_event_name\":\"Stop\",\"last_assistant_message\":\"회전본에 남아 있던 응답\"}\n",
        });
        const rotated_abs = try std.fmt.allocPrint(a, "{s}/{s}", .{ root, rotated_rel });
        defer a.free(rotated_abs);
        // 턴이 돌던 중에 회전이 있었다. **훅 자리를 세운다**(§1.6-⑴) — `agent_state` 는 권위표가 내는
        // 결과라 직접 쓰면 다음 판정이 그것을 덮는다. 「턴이 돌고 있다」를 말하는 자리는 훅 쪽이다.
        term.agent_hook_state = .running;
        term.agent_state = .running;
        agent_ops.test_turn_snapshot_calls = 0;
        agent_ops.drainRotatedAgentHookLogForTest(&session, term, rotated_abs);
        try std.testing.expectEqualStrings("회전본에 남아 있던 응답", term.agent_transcript.owned.reply());
        try std.testing.expectEqual(maru.session.agent_observer.State.idle, term.agent_state);
        // **건진 이벤트도 턴 끝을 만든다.** 회전본 쪽만 빠뜨리면 «마지막 Stop 이 회전본에 들어간 턴» 의
        // 작업트리가 통째로 안 굳는다 — 대화를 빠뜨렸던 것과 같은 부류의 누락이다.
        try std.testing.expectEqual(@as(usize, 1), agent_ops.test_turn_snapshot_calls);
        try std.testing.expect(tmp.dir.statFile(io, rotated_rel, .{}) catch null == null); // 건진 뒤 지운다
    }

    // ⑫ **서브에이전트가 도는 동안 lead 의 Stop 을 완료로 단정하지 않는다**(계약 §2). 그리고 마지막 자식이
    //    끝나면 풀린다 — 안 풀리면 그것도 «거짓말하는 배지» 다.
    {
        term.agent_hook_progress = .{};
        term.agent_state = .unknown;
        term.agent_hook_cursor = .{};
        term.agent_hook_cursor_inode = 0;
        term.agent_hook_notice.clear();
        const sub_prompt_line = "claude\t{\"hook_event_name\":\"UserPromptSubmit\",\"prompt\":\"조사해줘\"}\n";
        const sub_start_line = "claude\t{\"hook_event_name\":\"SubagentStart\",\"agent_id\":\"ac963bb35f95b11fd\"}\n";
        const sub_lead_stop_line = "claude\t{\"hook_event_name\":\"Stop\",\"last_assistant_message\":\"자식에게 맡겼습니다\"}\n";
        // **남의 에이전트 종료** — 우리가 시작을 본 적 없는 id 다(실사용에서 넷이 섞여 왔다).
        const sub_other_stop_line = "claude\t{\"hook_event_name\":\"SubagentStop\",\"agent_id\":\"ab60fb9ff9c21ee0\"}\n";
        const sub_our_stop_line = "claude\t{\"hook_event_name\":\"SubagentStop\",\"agent_id\":\"ac963bb35f95b11fd\"}\n";

        try tmp.dir.writeFile(io, .{ .sub_path = log_rel, .data = sub_prompt_line ++ sub_start_line ++ sub_lead_stop_line ++ sub_other_stop_line });
        agent_ops.pollAgentHookEvents(&session, term, false);
        // lead 는 끝났지만 자식이 돈다 → 여전히 진행 중이고 **완료 알림이 예약되지 않는다**.
        // 남의 종료가 하나 섞여 왔어도 우리 자식은 그대로다 — 개수를 세면 여기서 이미 풀린다.
        try std.testing.expectEqual(maru.session.agent_observer.State.running, term.agent_state);
        try std.testing.expectEqual(@as(usize, 1), term.agent_hook_progress.childCount());
        try std.testing.expect(!term.agent_hook_progress.turn_open); // lead 의 턴은 닫혔다
        try std.testing.expectEqual(maru.session.agent_hook_mode.Notice.none, term.agent_hook_notice.kind);

        // **우리** 자식이 끝나면 그때가 진짜 턴 끝이다.
        try tmp.dir.writeFile(io, .{ .sub_path = log_rel, .data = sub_prompt_line ++ sub_start_line ++ sub_lead_stop_line ++ sub_other_stop_line ++ sub_our_stop_line });
        agent_ops.pollAgentHookEvents(&session, term, false);
        try std.testing.expectEqual(maru.session.agent_observer.State.idle, term.agent_state);
    }

    // ⑬ **오류로 끝난 턴도 끝이다.** `StopFailure` 를 안 받으면 그 pane 이 영영 «진행 중» 이다.
    {
        term.agent_hook_progress = .{};
        term.agent_state = .unknown;
        term.agent_hook_cursor = .{};
        term.agent_hook_cursor_inode = 0;
        try tmp.dir.writeFile(io, .{ .sub_path = log_rel, .data = "claude\t{\"hook_event_name\":\"UserPromptSubmit\",\"prompt\":\"조사해줘\"}\n" ++
            "claude\t{\"hook_event_name\":\"StopFailure\"}\n" });
        agent_ops.pollAgentHookEvents(&session, term, false);
        try std.testing.expectEqual(maru.session.agent_observer.State.idle, term.agent_state);
    }

    // ⑭ **`background_tasks` 는 배지를 붙잡지 않는다**(2026-08-23 결정 — 계약 §2·§8). 예전 계약은
    //    «하나라도 `running` 이면 진행 중» 이었는데, 그 셈이 `type` 을 안 가려 셸 작업까지 붙잡았고 그 축에는
    //    푸는 이벤트가 없어 완료 알림이 통째로 막혔다. 이제 붙잡는 근거는 자식 로스터 하나다(아래 ⑮e).
    {
        term.agent_hook_progress = .{};
        term.agent_state = .unknown;
        term.agent_hook_cursor = .{};
        term.agent_hook_cursor_inode = 0;
        try tmp.dir.writeFile(io, .{ .sub_path = log_rel, .data = "claude\t{\"hook_event_name\":\"UserPromptSubmit\",\"prompt\":\"조사해줘\"}\n" ++
            "claude\t{\"hook_event_name\":\"Stop\",\"background_tasks\":[{\"id\":\"a\",\"status\":\"completed\"}]}\n" });
        agent_ops.pollAgentHookEvents(&session, term, false);
        try std.testing.expectEqual(maru.session.agent_observer.State.idle, term.agent_state);

        // `running` 이어도 같다 — 우리가 시작을 본 자식이 아니면 붙잡지 않는다.
        term.agent_hook_cursor = .{};
        term.agent_hook_cursor_inode = 0;
        term.agent_state = .unknown;
        try tmp.dir.writeFile(io, .{ .sub_path = log_rel, .data = "claude\t{\"hook_event_name\":\"UserPromptSubmit\",\"prompt\":\"조사해줘\"}\n" ++
            "claude\t{\"hook_event_name\":\"Stop\",\"background_tasks\":[{\"id\":\"a\",\"status\":\"running\"}]}\n" });
        agent_ops.pollAgentHookEvents(&session, term, false);
        try std.testing.expectEqual(maru.session.agent_observer.State.idle, term.agent_state);
    }

    // ⑮ **진행 중 세부가 사이드바 줄까지 간다**(계약 §2·§8). 훅 모드는 화면·프로세스 관측을 끄므로
    //    이 자리가 비면 훅을 켠 사용자가 관측 모드보다 **정보를 잃는다**.
    {
        term.agent_hook_progress = .{};
        term.agent_state = .unknown;
        term.agent_hook_cursor = .{};
        term.agent_hook_cursor_inode = 0;
        term.agent_hook_tool.clear();
        session.agent_spin_frame = 0; // 파형은 애니메이션 — 고정해야 문자열이 실행마다 같다
        try tmp.dir.writeFile(io, .{ .sub_path = log_rel, .data = "claude\t{\"hook_event_name\":\"UserPromptSubmit\",\"prompt\":\"조사해줘\"}\n" ++ "claude\t{\"hook_event_name\":\"PreToolUse\",\"tool_name\":\"Bash\",\"tool_input\":{\"description\":\"테스트를 돌린다\"}}\n" });
        agent_ops.pollAgentHookEvents(&session, term, false);
        try std.testing.expectEqualStrings("테스트를 돌린다", term.agent_hook_tool.text());
        const with_detail = try sidebar_ops.agentStatusLine(&session, term);
        defer a.free(with_detail);
        try std.testing.expect(std.mem.endsWith(u8, with_detail, "\u{00b7} 테스트를 돌린다"));
        try std.testing.expect(std.mem.indexOf(u8, with_detail, sidebar_ops.runningLabel()) != null);

        // 설명이 없는 도구는 이름이라도 보인다 — 빈 줄보다 낫다.
        try tmp.dir.writeFile(io, .{ .sub_path = log_rel, .data = "claude\t{\"hook_event_name\":\"UserPromptSubmit\",\"prompt\":\"조사해줘\"}\n" ++ "claude\t{\"hook_event_name\":\"PreToolUse\",\"tool_name\":\"Bash\",\"tool_input\":{\"description\":\"테스트를 돌린다\"}}\n" ++ "claude\t{\"hook_event_name\":\"PreToolUse\",\"tool_name\":\"Read\"}\n" });
        agent_ops.pollAgentHookEvents(&session, term, false);
        try std.testing.expectEqualStrings("Read", term.agent_hook_tool.text());

        // 자식의 도구 호출은 **부모의** 세부를 갈아 끼우지 않는다(계약 §2).
        try tmp.dir.writeFile(io, .{ .sub_path = log_rel, .data = "claude\t{\"hook_event_name\":\"UserPromptSubmit\",\"prompt\":\"조사해줘\"}\n" ++ "claude\t{\"hook_event_name\":\"PreToolUse\",\"tool_name\":\"Bash\",\"tool_input\":{\"description\":\"테스트를 돌린다\"}}\n" ++ "claude\t{\"hook_event_name\":\"PreToolUse\",\"tool_name\":\"Read\"}\n" ++ "claude\t{\"hook_event_name\":\"PreToolUse\",\"agent_id\":\"child-1\",\"tool_name\":\"Bash\",\"tool_input\":{\"description\":\"자식이 하는 일\"}}\n" });
        agent_ops.pollAgentHookEvents(&session, term, false);
        try std.testing.expectEqualStrings("Read", term.agent_hook_tool.text());

        // 새 턴이 시작되면 비운다 — 안 비우면 지난 턴의 마지막 도구가 계속 붙어 있다. 그리고 그때의
        // 상태줄은 예전과 **바이트가 같다**(세부가 없으면 구분자도 없다).
        try tmp.dir.writeFile(io, .{ .sub_path = log_rel, .data = "claude\t{\"hook_event_name\":\"UserPromptSubmit\",\"prompt\":\"조사해줘\"}\n" ++ "claude\t{\"hook_event_name\":\"PreToolUse\",\"tool_name\":\"Bash\",\"tool_input\":{\"description\":\"테스트를 돌린다\"}}\n" ++ "claude\t{\"hook_event_name\":\"PreToolUse\",\"tool_name\":\"Read\"}\n" ++ "claude\t{\"hook_event_name\":\"PreToolUse\",\"agent_id\":\"child-1\",\"tool_name\":\"Bash\",\"tool_input\":{\"description\":\"자식이 하는 일\"}}\n" ++ "claude\t{\"hook_event_name\":\"UserPromptSubmit\",\"prompt\":\"조사해줘\"}\n" });
        agent_ops.pollAgentHookEvents(&session, term, false);
        try std.testing.expectEqualStrings("", term.agent_hook_tool.text());
        const plain = try sidebar_ops.agentStatusLine(&session, term);
        defer a.free(plain);
        try std.testing.expect(std.mem.endsWith(u8, plain, sidebar_ops.runningLabel()));

        // 관측 모드로 돌아가면 남은 세부를 버린다 — 남기면 다른 소스의 배지 옆에 훅 문구가 붙는다(§1).
        term.agent_hook_tool.set("남은 것");
        // 자식 셈도 함께 버린다 — 남기면 훅 모드로 돌아온 뒤 첫 lead `Stop` 이 «자식이 남았다» 로 읽혀
        // 배지가 안 풀린다(다음 프롬프트가 셈을 지울 때까지).
        term.agent_hook_progress = .{ .turn_open = true };
        // 자식 자리는 **id 해시**다(전문을 담지 않는다) — 여기서는 «하나 담겨 있다» 만 만들면 된다.
        term.agent_hook_progress.children[0] = 0xc1;
        term.agent_hook_progress.child_count = 1;
        session.loaded_config.config.sidebar.agent_hooks = false;
        agent_ops.pollAgentConsumer(&session, term, false, false);
        try std.testing.expectEqualStrings("", term.agent_hook_tool.text());
        try std.testing.expectEqual(@as(usize, 0), term.agent_hook_progress.childCount());
        try std.testing.expect(!term.agent_hook_progress.turn_open);
        session.loaded_config.config.sidebar.agent_hooks = true;
    }

    // ── ⑯a **Notification 이 «입력 대기» 를 만든다**(계약 §6) ────────────────────────────────
    // 「입력 대기」의 다른 소스인 `PermissionRequest` 는 실측에서 **한 번도 발화하지 않았다**(헤드리스에서는
    // 권한이 실제로 거부돼도 안 온다 — §9-6). 그것 하나에만 걸어 두면 대화형에서도 안 올 경우 그 배지에
    // 소스가 하나도 없다. `Notification` 은 실사용에서 **실제로 오는 것을 봤다**.
    {
        term.agent_hook_progress = .{};
        term.agent_state = .unknown;
        term.agent_hook_cursor = .{};
        term.agent_hook_cursor_inode = 0;
        term.agent_hook_notice.clear();
        try tmp.dir.writeFile(io, .{ .sub_path = log_rel, .data = "claude\t{\"hook_event_name\":\"UserPromptSubmit\",\"prompt\":\"파일 하나 고쳐줘\"}\n" ++ "claude\t{\"hook_event_name\":\"Notification\",\"notification_type\":\"permission_prompt\",\"message\":\"Claude needs your permission to use Bash\"}\n" });
        agent_ops.pollAgentHookEvents(&session, term, false);
        try std.testing.expectEqual(maru.session.agent_observer.State.blocked, term.agent_state);
        // 무엇을 승인해야 하는지도 함께 온다. **본문까지 본다** — 종류만 물으면 «알림은 떴는데 아무 말도
        // 안 하는» 경우가 통과한다. `Notification` payload 에는 `tool_name` 이 **없으므로**(실측: 키는
        // `message`·`title`·`notification_type` + 공통부) 승인 경로의 본문 규칙을 그대로 쓰면 빈 문자열이다.
        try std.testing.expectEqual(maru.session.agent_hook_mode.Notice.attention, term.agent_hook_notice.kind);
        try std.testing.expect(std.mem.indexOf(u8, term.agent_hook_notice.text(), "permission to use Bash") != null);

        // **유휴 알림은 배지를 흔들지 않는다** — 실사용에서 이것이 턴 끝 뒤에 온다.
        term.agent_hook_cursor = .{};
        term.agent_hook_cursor_inode = 0;
        term.agent_state = .unknown;
        term.agent_hook_notice.clear();
        try tmp.dir.writeFile(io, .{ .sub_path = log_rel, .data = "claude\t{\"hook_event_name\":\"UserPromptSubmit\",\"prompt\":\"파일 하나 고쳐줘\"}\n" ++ "claude\t{\"hook_event_name\":\"Notification\",\"notification_type\":\"idle_prompt\"}\n" });
        agent_ops.pollAgentHookEvents(&session, term, false);
        try std.testing.expectEqual(maru.session.agent_observer.State.running, term.agent_state);
        try std.testing.expectEqual(maru.session.agent_hook_mode.Notice.none, term.agent_hook_notice.kind);
    }

    // ── ⑯c **자식이 남은 뒤 온 알림이 배지를 가두지 않는다**(계약 §6) ─────────────────────
    // `worker_permission_prompt` 는 **자식이 아니라 lead 가** 낸다(lead 가 자식들 요구를 모아 알린다).
    // 그래서 `agent_id` 가 없고 lead 이벤트로 도착한다 — 그것이 턴을 되살리면 마지막 자식이 끝나도
    // «턴이 안 끝났다» 가 되어 배지가 영영 「입력 대기」에 멈춘다. 순수 층이 그 규칙을 갖고 있어도
    // **제품이 이벤트 사이로 상태를 안 이어 주면** 같은 결과가 안 나오므로 여기서 한 번 더 본다.
    {
        term.agent_hook_progress = .{};
        term.agent_state = .unknown;
        term.agent_hook_cursor = .{};
        term.agent_hook_cursor_inode = 0;
        term.agent_hook_notice.clear();
        try tmp.dir.writeFile(io, .{ .sub_path = log_rel, .data = "claude\t{\"hook_event_name\":\"UserPromptSubmit\",\"prompt\":\"두 갈래로 조사해줘\"}\n" ++ "claude\t{\"hook_event_name\":\"SubagentStart\",\"agent_id\":\"c1\"}\n" ++ "claude\t{\"hook_event_name\":\"Stop\",\"last_assistant_message\":\"맡겼습니다\"}\n" ++ "claude\t{\"hook_event_name\":\"Notification\",\"notification_type\":\"worker_permission_prompt\",\"message\":\"c1 needs permission for Bash\"}\n" ++ "claude\t{\"hook_event_name\":\"SubagentStop\",\"agent_id\":\"c1\",\"last_assistant_message\":\"끝냈습니다\"}\n" });
        agent_ops.pollAgentHookEvents(&session, term, false);
        try std.testing.expectEqual(maru.session.agent_observer.State.idle, term.agent_state);
    }

    // ── ⑯b **종료를 놓친 유령을 목록이 거둔다**(계약 §2) ──────────────────────────────────
    // 자식의 `SubagentStop` 은 유실될 수 있다(§4.3 동시 append·상한). 그러면 우리는 그 자식을 영영
    // 붙잡는다 — **안 풀리는 배지**다. provider 가 `Stop` 에 실어 주는 목록이 그것을 정리한다:
    // `type: "subagent"` 항목의 `id` 가 수명 이벤트의 `agent_id` 와 **정확히 같다**(실측).
    {
        term.agent_hook_progress = .{};
        term.agent_state = .unknown;
        term.agent_hook_cursor = .{};
        term.agent_hook_cursor_inode = 0;
        term.agent_hook_notice.clear();
        try tmp.dir.writeFile(io, .{
            .sub_path = log_rel,
            .data = "claude\t{\"hook_event_name\":\"UserPromptSubmit\",\"prompt\":\"조사해줘\"}\n" ++ "claude\t{\"hook_event_name\":\"SubagentStart\",\"agent_id\":\"ghost-1\"}\n" ++ "claude\t{\"hook_event_name\":\"SubagentStart\",\"agent_id\":\"ab8b2cd7ddd4dce44\"}\n" ++ "claude\t{\"hook_event_name\":\"Stop\",\"last_assistant_message\":\"백그라운드로 띄웠습니다\",\"background_tasks\":[{\"id\":\"ab8b2cd7ddd4dce44\",\"type\":\"subagent\",\"status\":\"running\",\"description\":\"List and summarize files\"}]}\n",
        });
        agent_ops.pollAgentHookEvents(&session, term, false);
        // 유령은 거둬지고, 목록이 «도는 중» 이라 말한 자식만 남아 배지를 붙잡는다.
        try std.testing.expectEqual(@as(usize, 1), term.agent_hook_progress.childCount());
        try std.testing.expectEqual(maru.session.agent_observer.State.running, term.agent_state);

        // 그 자식이 끝나면 그때가 진짜 턴 끝이다 — 유령이 남아 있었다면 여기서 안 풀렸다.
        try tmp.dir.writeFile(io, .{
            .sub_path = log_rel,
            .data = "claude\t{\"hook_event_name\":\"UserPromptSubmit\",\"prompt\":\"조사해줘\"}\n" ++ "claude\t{\"hook_event_name\":\"SubagentStart\",\"agent_id\":\"ghost-1\"}\n" ++ "claude\t{\"hook_event_name\":\"SubagentStart\",\"agent_id\":\"ab8b2cd7ddd4dce44\"}\n" ++ "claude\t{\"hook_event_name\":\"Stop\",\"last_assistant_message\":\"백그라운드로 띄웠습니다\",\"background_tasks\":[{\"id\":\"ab8b2cd7ddd4dce44\",\"type\":\"subagent\",\"status\":\"running\",\"description\":\"List and summarize files\"}]}\n" ++ "claude\t{\"hook_event_name\":\"SubagentStop\",\"agent_id\":\"ab8b2cd7ddd4dce44\"}\n",
        });
        agent_ops.pollAgentHookEvents(&session, term, false);
        try std.testing.expectEqual(maru.session.agent_observer.State.idle, term.agent_state);
        try std.testing.expectEqual(@as(usize, 0), term.agent_hook_progress.childCount());
    }

    // ── ⑰ **실측 줄을 그대로 태운다**(2026-08-21 claude 서브에이전트 턴) ─────────────────────
    // 위의 모든 제품 테스트는 입력이 **내가 손으로 쓴 JSON** 이다 — 내가 생각한 키만 들어 있다.
    // 진짜 줄에는 `effort`·`tool_use_id`·`session_crons`·`agent_type`·`agent_transcript_path`·
    // `permission_mode` 처럼 한 번도 안 써 본 키가 있고 키 순서도 다르다. 그중 하나가 파서를 멈추면
    // 그 이벤트는 **조용히 사라지고**, 그것이 곧 안 풀리는 배지다. 경로만 가리고 나머지는 한 글자도
    // 안 고쳤다.
    {
        term.agent_hook_progress = .{};
        term.agent_state = .unknown;
        term.agent_hook_cursor = .{};
        term.agent_hook_cursor_inode = 0;
        term.agent_hook_notice.clear();
        term.agent_transcript.owned.setReply("");
        agent_ops.test_turn_snapshot_calls = 0;

        const real_turn = "claude\t{\"session_id\":\"fa0a0dd2-9bf5-4bae-9b9b-ac3369a2cada\",\"transcript_path\":\"/Users/u/.claude/projects/-private-tmp-maru-e2e-matrix/fa0a0dd2-9bf5-4bae-9b9b-ac3369a2cada.jsonl\",\"cwd\":\"/private/tmp/maru-e2e-matrix\",\"hook_event_name\":\"SessionStart\",\"source\":\"startup\"}\n" ++
            "claude\t{\"session_id\":\"fa0a0dd2-9bf5-4bae-9b9b-ac3369a2cada\",\"transcript_path\":\"/Users/u/.claude/projects/-private-tmp-maru-e2e-matrix/fa0a0dd2-9bf5-4bae-9b9b-ac3369a2cada.jsonl\",\"cwd\":\"/private/tmp/maru-e2e-matrix\",\"prompt_id\":\"b916795d-79e4-4142-9f06-5c1869e7d82c\",\"permission_mode\":\"bypassPermissions\",\"hook_event_name\":\"UserPromptSubmit\",\"prompt\":\"Use the Task tool to launch exactly one general-purpose subagent that runs `echo from-child` and reports the output. Then reply with: done.\"}\n" ++
            "claude\t{\"session_id\":\"fa0a0dd2-9bf5-4bae-9b9b-ac3369a2cada\",\"transcript_path\":\"/Users/u/.claude/projects/-private-tmp-maru-e2e-matrix/fa0a0dd2-9bf5-4bae-9b9b-ac3369a2cada.jsonl\",\"cwd\":\"/private/tmp/maru-e2e-matrix\",\"prompt_id\":\"b916795d-79e4-4142-9f06-5c1869e7d82c\",\"permission_mode\":\"bypassPermissions\",\"effort\":{\"level\":\"high\"},\"hook_event_name\":\"PreToolUse\",\"tool_name\":\"Agent\",\"tool_input\":{\"description\":\"Run echo command\",\"prompt\":\"Run the shell command `echo from-child` using the Bash tool and report its exact stdout output as your final answer.\",\"subagent_type\":\"general-purpose\",\"run_in_background\":false},\"tool_use_id\":\"toolu_01VUSoQ6gMcYrneVHhgBbHbX\"}\n" ++
            "claude\t{\"session_id\":\"fa0a0dd2-9bf5-4bae-9b9b-ac3369a2cada\",\"transcript_path\":\"/Users/u/.claude/projects/-private-tmp-maru-e2e-matrix/fa0a0dd2-9bf5-4bae-9b9b-ac3369a2cada.jsonl\",\"cwd\":\"/private/tmp/maru-e2e-matrix\",\"prompt_id\":\"b916795d-79e4-4142-9f06-5c1869e7d82c\",\"agent_id\":\"a533c21143f8edccb\",\"agent_type\":\"general-purpose\",\"hook_event_name\":\"SubagentStart\"}\n" ++
            "claude\t{\"session_id\":\"fa0a0dd2-9bf5-4bae-9b9b-ac3369a2cada\",\"transcript_path\":\"/Users/u/.claude/projects/-private-tmp-maru-e2e-matrix/fa0a0dd2-9bf5-4bae-9b9b-ac3369a2cada.jsonl\",\"cwd\":\"/private/tmp/maru-e2e-matrix\",\"prompt_id\":\"b916795d-79e4-4142-9f06-5c1869e7d82c\",\"permission_mode\":\"bypassPermissions\",\"agent_id\":\"a533c21143f8edccb\",\"agent_type\":\"general-purpose\",\"effort\":{\"level\":\"high\"},\"hook_event_name\":\"PreToolUse\",\"tool_name\":\"Bash\",\"tool_input\":{\"command\":\"echo from-child\",\"description\":\"Echo from-child\"},\"tool_use_id\":\"toolu_01WiCBM8eTrUcFwDVQRpuptm\"}\n" ++
            "claude\t{\"session_id\":\"fa0a0dd2-9bf5-4bae-9b9b-ac3369a2cada\",\"transcript_path\":\"/Users/u/.claude/projects/-private-tmp-maru-e2e-matrix/fa0a0dd2-9bf5-4bae-9b9b-ac3369a2cada.jsonl\",\"cwd\":\"/private/tmp/maru-e2e-matrix\",\"prompt_id\":\"b916795d-79e4-4142-9f06-5c1869e7d82c\",\"permission_mode\":\"bypassPermissions\",\"agent_id\":\"a533c21143f8edccb\",\"agent_type\":\"general-purpose\",\"effort\":{\"level\":\"high\"},\"hook_event_name\":\"SubagentStop\",\"stop_hook_active\":false,\"agent_transcript_path\":\"/Users/u/.claude/projects/-private-tmp-maru-e2e-matrix/fa0a0dd2-9bf5-4bae-9b9b-ac3369a2cada/subagents/agent-a533c21143f8edccb.jsonl\",\"last_assistant_message\":\"from-child\",\"background_tasks\":[],\"session_crons\":[]}\n" ++
            "claude\t{\"session_id\":\"fa0a0dd2-9bf5-4bae-9b9b-ac3369a2cada\",\"transcript_path\":\"/Users/u/.claude/projects/-private-tmp-maru-e2e-matrix/fa0a0dd2-9bf5-4bae-9b9b-ac3369a2cada.jsonl\",\"cwd\":\"/private/tmp/maru-e2e-matrix\",\"prompt_id\":\"b916795d-79e4-4142-9f06-5c1869e7d82c\",\"permission_mode\":\"bypassPermissions\",\"effort\":{\"level\":\"high\"},\"hook_event_name\":\"Stop\",\"stop_hook_active\":false,\"last_assistant_message\":\"서브에이전트가 `echo from-child`를 실행했고 출력은 `from-child`였습니다.\\n\\ndone\",\"background_tasks\":[],\"session_crons\":[]}\n";
        try tmp.dir.writeFile(io, .{ .sub_path = log_rel, .data = real_turn });
        agent_ops.pollAgentHookEvents(&session, term, false);

        // 턴이 끝났다 — 자식이 먼저 끝나고 lead 가 뒤에 끝나는 **실측 순서** 그대로다.
        try std.testing.expectEqual(maru.session.agent_observer.State.idle, term.agent_state);
        try std.testing.expectEqual(@as(usize, 0), term.agent_hook_progress.childCount());
        try std.testing.expect(!term.agent_hook_progress.turn_open);
        // 턴 키를 실제 payload 에서 집었다(`prompt_id`).
        try std.testing.expectEqual(@as(usize, 36), term.agent_hook_progress.turnKey().len);
        // 대화는 **lead 의 것**이다 — 자식의 `last_assistant_message`("from-child")가 아니다.
        //
        // 「"from-child" 를 포함하지 않는다」로 쓰면 안 된다: **lead 자신의 응답이 그 말을 인용한다**
        // ("서브에이전트가 `echo from-child`를 실행했고 …"). 실측 데이터가 그 단언을 깼다 — 합성
        // 입력이었다면 영영 안 걸렸을 함정이라, 이 자리는 «자식 것과 같지 않다» 로 물어야 한다.
        try std.testing.expect(!std.mem.eql(u8, term.agent_transcript.owned.reply(), "from-child"));
        try std.testing.expect(std.mem.indexOf(u8, term.agent_transcript.owned.reply(), "done") != null);
        try std.testing.expect(term.agent_transcript.owned.prompt().len > 0);
        // 작업트리도 굳었다(배치 안이므로 한 번).
        try std.testing.expectEqual(@as(usize, 1), agent_ops.test_turn_snapshot_calls);
        // 완료 알림이 예약됐고 오류가 아니다.
        try std.testing.expectEqual(maru.session.agent_hook_mode.Notice.done, term.agent_hook_notice.kind);
    }

    // ⑮b **JSON 이스케이프를 푼 뒤에 보여 준다**(계약 §4). 파서는 줄 버퍼를 빌려 쓰느라 이스케이프를
    //    그대로 두므로(`agent_hook_event.Event` 주석), 표시 자리에 그대로 실으면 **여러 줄 응답이 `\n`
    //    두 글자로** 보이고 따옴표마다 역슬래시가 붙는다. claude 의 `last_assistant_message` 는 대개
    //    여러 줄이라(위 ⑮ 실측 payload 도 `\n\n` 을 담고 있다) 실사용에서 늘 걸리던 자리다.
    {
        term.agent_hook_progress = .{};
        term.agent_state = .unknown;
        term.agent_hook_cursor = .{};
        term.agent_hook_cursor_inode = 0;
        term.agent_hook_notice.clear();
        try tmp.dir.writeFile(io, .{
            .sub_path = log_rel,
            .data = "claude\t{\"hook_event_name\":\"UserPromptSubmit\",\"prompt\":\"첫 줄\\n둘째 줄\"}\n" ++
                "claude\t{\"hook_event_name\":\"Stop\",\"last_assistant_message\":\"정리했습니다\\n\\n그는 \\\"네\\\"라고 했다\"}\n",
        });
        agent_ops.pollAgentHookEvents(&session, term, false);
        // **대화 줄은 한 줄로 눕는다.** 이스케이프만 풀고 멈추면 그 자리에 진짜 개행이 들어가 한 줄
        // 텍스트 run 이 뭉개진다 — 관측 모드 파서가 저장 직전에 `flatten` 을 지나는 것과 같은 모양이어야
        // 한다(계약 §1: 두 소스가 같은 자리에 같은 모양을 그린다).
        try std.testing.expectEqualStrings("첫 줄 둘째 줄", term.agent_transcript.owned.prompt());
        try std.testing.expectEqualStrings("정리했습니다 그는 \"네\"라고 했다", term.agent_transcript.owned.reply());
        try std.testing.expect(std.mem.indexOfScalar(u8, term.agent_transcript.owned.reply(), '\n') == null);
        // 알림 본문은 **반대다** — OS 배너는 여러 줄을 제대로 보여주므로 개행을 살리고, 대신 `\n` 두 글자가
        // 나가면 안 된다(인앱 히스토리는 자기 tail 에서 눕힌다).
        const notice = agent_ops.takeAgentHookNotice(&session, term) orelse return error.MissingHookNotice;
        try std.testing.expect(std.mem.indexOfScalar(u8, notice.body, '\n') != null);
        try std.testing.expect(std.mem.indexOf(u8, notice.body, "\\n") == null);
    }

    // ⑮b-2 **긴 한글 응답이 글자 중간에서 잘리지 않는다.** 훅 payload 는 고정 버퍼로 디코드되는데, 받는
    //    쪽의 `clampUtf8` 은 «상한을 **넘을** 때만» 자르므로 **버퍼를 꽉 채우고 나온** 슬라이스(길이가 정확히
    //    상한)를 손대지 않는다. 512 바이트면 한글 170자 + 2바이트라 조금 긴 답변 하나면 배너 끝에 U+FFFD 가
    //    붙는다 — 경계를 푸는 쪽(`hookDisplayText`)에서 물려야 한다.
    {
        term.agent_hook_progress = .{};
        term.agent_state = .unknown;
        term.agent_hook_cursor = .{};
        term.agent_hook_cursor_inode = 0;
        term.agent_hook_notice.clear();
        const long_korean = "가" ** 300; // 900 바이트 — 알림 상한(512)과 대화 상한(512)을 둘 다 넘긴다
        try tmp.dir.writeFile(io, .{
            .sub_path = log_rel,
            .data = "claude\t{\"hook_event_name\":\"UserPromptSubmit\",\"prompt\":\"" ++ long_korean ++ "\"}\n" ++
                "claude\t{\"hook_event_name\":\"Stop\",\"last_assistant_message\":\"" ++ long_korean ++ "\"}\n",
        });
        agent_ops.pollAgentHookEvents(&session, term, false);
        const notice = agent_ops.takeAgentHookNotice(&session, term) orelse return error.MissingHookNotice;
        try std.testing.expect(notice.body.len > 0);
        try std.testing.expect(std.unicode.utf8ValidateSlice(notice.body)); // 배너
        try std.testing.expect(std.unicode.utf8ValidateSlice(term.agent_transcript.owned.reply())); // 사이드바
        try std.testing.expect(std.unicode.utf8ValidateSlice(term.agent_transcript.owned.prompt()));
    }

    // ⑮c **턴을 거듭해도 대화 줄이 안 빈다.** 훅 모드는 Term 이 든 `Owned` 버퍼에 **직접** 쓰는데, 그
    //    버퍼가 앞으로만 미는 bump 였을 때 몇 턴 만에 자리가 말라 새 값이 잘리고 그 뒤로는 길이 0 으로
    //    들어갔다(실측: 5턴째 잘림, 6턴째부터 통째로 빔). 사용자에게는 «사이드바 대화 줄과 알림 본문이
    //    갑자기 사라진다» 로 보였고 `agent_kind` 가 바뀌기 전에는 회복되지 않았다. 관측 모드는 폴링마다
    //    새 버퍼로 다시 담아 이 증상이 없었으므로, **훅 모드에서만** 나던 회귀다.
    {
        term.agent_hook_progress = .{};
        term.agent_state = .unknown;
        term.agent_hook_cursor = .{};
        term.agent_hook_cursor_inode = 0;
        term.agent_transcript.reset();

        var log: std.ArrayListUnmanaged(u8) = .empty;
        defer log.deinit(a);
        const reply_len = 300; // 실사용 응답 길이대 — 짧은 문장으로 채우면 고갈이 한참 뒤로 밀린다
        var turn: usize = 0;
        while (turn < 8) : (turn += 1) {
            try log.appendSlice(a, "claude\t{\"hook_event_name\":\"UserPromptSubmit\",\"prompt\":\"배포 스크립트를 고치고 테스트까지 돌려줘 — 사용자가 실제로 치는 만큼 긴 문장\"}\n");
            try log.appendSlice(a, "claude\t{\"hook_event_name\":\"Stop\",\"last_assistant_message\":\"");
            try log.appendNTimes(a, 'x', reply_len);
            try log.appendSlice(a, "\"}\n");
            try tmp.dir.writeFile(io, .{ .sub_path = log_rel, .data = log.items });
            agent_ops.pollAgentHookEvents(&session, term, false);
        }
        try std.testing.expectEqual(@as(usize, reply_len), term.agent_transcript.owned.reply().len);
        try std.testing.expect(std.mem.indexOf(u8, term.agent_transcript.owned.prompt(), "배포 스크립트") != null);
    }

    // ⑮d **백그라운드 셸 작업이 도는 중에도 완료 알림이 나간다**(2026-08-23 결정). 예전에는 `Stop` 의
    //    `background_tasks` 에 `running` 이 하나라도 있으면 상태를 붙잡았는데, 그 셈이 `type` 을 안 가려
    //    **셸 작업까지** 붙잡았다. 셸에는 `SubagentStop` 같은 푸는 이벤트가 없어, `run_in_background` 를
    //    한 번 쓰면 그 pane 의 완료 알림이 그 작업이 끝날 때까지 **한 건도** 안 나갔다(사용자 보고 →
    //    실측 확인). payload 는 실측 그대로다.
    {
        term.agent_hook_progress = .{};
        term.agent_state = .unknown;
        term.agent_hook_cursor = .{};
        term.agent_hook_cursor_inode = 0;
        term.agent_hook_notice.clear();
        try tmp.dir.writeFile(io, .{
            .sub_path = log_rel,
            .data = "claude\t{\"hook_event_name\":\"UserPromptSubmit\",\"prompt\":\"sleep 을 백그라운드로 띄워줘\"}\n" ++
                "claude\t{\"hook_event_name\":\"Stop\",\"last_assistant_message\":\"띄웠음\",\"stop_hook_active\":false," ++
                "\"background_tasks\":[{\"id\":\"bmyb73pp8\",\"type\":\"shell\",\"status\":\"running\"," ++
                "\"description\":\"Sleep 200 seconds in background\",\"command\":\"sleep 200\"}],\"session_crons\":[]}\n",
        });
        agent_ops.pollAgentHookEvents(&session, term, false);
        try std.testing.expectEqual(maru.session.agent_observer.State.idle, term.agent_state);
        const bg = notification_ops.pendingNotification(&session) orelse return error.MissingHookNotification;
        try std.testing.expect(std.mem.indexOf(u8, bg.title, maru.i18n.t(.agent_hook_notice_done)) != null);
        try std.testing.expect(std.mem.indexOf(u8, bg.body, "띄웠음") != null);
    }

    // ⑮e **그래도 서브에이전트는 여전히 붙잡는다.** 위 결정은 «목록을 붙잡는 근거로 쓰지 않는다» 이지
    //    «자식을 안 기다린다» 가 아니다 — 자식은 우리 로스터가 붙잡고 `SubagentStop` 이 푼다.
    {
        term.agent_hook_progress = .{};
        term.agent_state = .unknown;
        term.agent_hook_cursor = .{};
        term.agent_hook_cursor_inode = 0;
        term.agent_hook_notice.clear();
        try tmp.dir.writeFile(io, .{
            .sub_path = log_rel,
            .data = "claude\t{\"hook_event_name\":\"UserPromptSubmit\",\"prompt\":\"자식을 하나 띄워줘\"}\n" ++
                "claude\t{\"hook_event_name\":\"SubagentStart\",\"agent_id\":\"a533c21143f8edccb\"}\n" ++
                "claude\t{\"hook_event_name\":\"Stop\",\"last_assistant_message\":\"자식을 띄웠습니다\"," ++
                "\"background_tasks\":[{\"id\":\"a533c21143f8edccb\",\"type\":\"subagent\",\"status\":\"running\"}]}\n",
        });
        agent_ops.pollAgentHookEvents(&session, term, false);
        try std.testing.expectEqual(maru.session.agent_observer.State.running, term.agent_state); // 아직 턴 끝이 아니다
        try std.testing.expect(notification_ops.pendingNotification(&session) == null);
    }

    // ⑮f **다른 maru 인스턴스의 로그를 읽지 않는다**(계약 §4). 로그 디렉터리는 사용자 캐시 하나뿐인데
    //    `surface.id` 는 **프로세스마다 1 부터** 발급되므로, 인스턴스 칸이 없던 시절에는 두 maru 의 첫 pane 이
    //    같은 파일 이름을 갖고 **서로의 이벤트를 읽었다**(그리고 시작 시 정리가 남의 살아 있는 로그를 지웠다).
    //    같은 `surface_id` 로 남의 칸에 이벤트를 놓고, 우리 Term 이 그것을 안 무는지 본다.
    {
        term.agent_hook_progress = .{};
        term.agent_state = .unknown;
        term.agent_hook_cursor = .{};
        term.agent_hook_cursor_inode = 0;
        term.agent_hook_notice.clear();
        term.agent_transcript.reset();

        // 우리 칸은 비운다(우리 것은 없다).
        try tmp.dir.deleteFile(io, log_rel);
        const foreign =
            "claude\t{\"hook_event_name\":\"UserPromptSubmit\",\"prompt\":\"남의 인스턴스 프롬프트\"}\n" ++
            "claude\t{\"hook_event_name\":\"Stop\",\"last_assistant_message\":\"남의 인스턴스 응답\"}\n";

        // ⓐ **인스턴스 칸이 없던 시절의 자리**(`<base>/<surface_id>.ndjson`). 그 시절엔 두 인스턴스가 이
        //    한 파일을 공유했다 — 이 자리를 다시 읽기 시작하면 그때의 오독이 그대로 돌아온다. 판정자가
        //    실제로 무는 자리라, 인스턴스 칸을 되돌리는 뮤테이션이 여기서 빨개진다.
        const base_dir = try std.fmt.allocPrint(a, "cache/maru/{s}", .{hook_command.log_dir_rel});
        defer a.free(base_dir);
        const shared_log = try std.fmt.allocPrint(a, "{s}/{d}.ndjson", .{ base_dir, term.surfaceId() });
        defer a.free(shared_log);
        try tmp.dir.writeFile(io, .{ .sub_path = shared_log, .data = foreign });

        // ⓑ 남의 인스턴스 칸(pid 가 다르다) — 검색 범위가 넓어지는 변경도 여기서 걸린다.
        const other_dir = try std.fmt.allocPrint(a, "{s}/{d}", .{ base_dir, agent_ops.hookInstanceId() + 1 });
        defer a.free(other_dir);
        try tmp.dir.createDirPath(io, other_dir);
        const other_log = try std.fmt.allocPrint(a, "{s}/{d}.ndjson", .{ other_dir, term.surfaceId() });
        defer a.free(other_log);
        try tmp.dir.writeFile(io, .{ .sub_path = other_log, .data = foreign });

        term.agent_hook_log_present = false;
        agent_ops.pollAgentConsumer(&session, term, false, true);
        // 우리 칸에 파일이 없으므로 훅 모드로 들어가지 않는다(관측 모드로 남는다).
        try std.testing.expect(!term.agent_hook_log_present);
        try std.testing.expectEqual(hook_mode.Mode.observe, agent_ops.agentHookMode(&session, term));
        // 그리고 남의 대화가 이 Term 에 붙지 않는다.
        try std.testing.expectEqual(@as(usize, 0), term.agent_transcript.owned.reply().len);
        try std.testing.expect(std.mem.indexOf(u8, term.agent_transcript.owned.prompt(), "남의 인스턴스") == null);
    }

    // ⑯ 게이트를 끄면 그 Term 은 **관측 모드로 돌아간다**(로그가 있어도) — 모드는 세 조건이 다 서야 한다.
    session.loaded_config.config.sidebar.agent_hooks = false;
    try std.testing.expectEqual(hook_mode.Mode.observe, agent_ops.agentHookMode(&session, term));
    session.loaded_config.config.sidebar.agent_hooks = true;

    // ⑰ 에이전트가 없으면 모드를 논할 것도 없다.
    term.agent_kind = .none;
    try std.testing.expectEqual(hook_mode.Mode.observe, agent_ops.agentHookMode(&session, term));
}

test "turning the agent hooks gate off removes what we installed and nothing else" {
    // **이 테스트는 provider 설정 파일을 실제로 고치겠다고 밝힌다.** 기본은 꺼짐이다 — 격리를 잊은
    // 테스트가 개발자의 진짜 `~/.claude/settings.json` 을 고치는 사고가 났다(`test_allow_provider_writes`).
    agent_ops.test_allow_provider_writes = true;
    defer agent_ops.test_allow_provider_writes = false;

    if (builtin.os.tag != .macos or std.c.getenv("MARU_TEST_PROVIDER_NO_MUTATION") == null) return error.SkipZigTest;
    const hook_command = maru.session.agent_hook_command;
    const hook_install = maru.session.agent_hook_install;
    const io = std.Io.Threaded.global_single_threaded.io();
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var env_guard = try workspace_ops.ProviderEnvGuard.capture(a);
    defer env_guard.restore();
    try tmp.dir.createDirPath(io, "home");
    try tmp.dir.createDirPath(io, "claude");
    try tmp.dir.createDirPath(io, "codex");
    try tmp.dir.createDirPath(io, "cache");

    // 설치 전 상태. claude 는 다른 설정과 한 파일을 나눠 쓰고, codex 에는 과거 표식과 사용자 신뢰가 있다.
    const user_hook = "printf ok # user hook";
    const settings_before = "{\"model\":\"opus\",\"hooks\":{\"Stop\":[{\"hooks\":[{\"command\":\"" ++ user_hook ++ "\"}]}]}}";
    const legacy_hook = "cat > /tmp/x # " ++ hook_command.legacy_markers[0];
    const codex_hooks_before = "{\"hooks\":{\"Stop\":[{\"hooks\":[{\"command\":\"" ++ legacy_hook ++ "\"}]}]}}";
    // 사용자가 **직접 승인해** codex 가 적은 신뢰 항목 — 우리 표식이 없으므로 살아남아야 한다.
    const codex_config_before = "model = \"gpt-5\"\n\n[hooks.state.\"/somewhere/hooks.json:stop:0:0\"]\ntrusted_hash = \"sha256:user\"\n";
    try tmp.dir.writeFile(io, .{ .sub_path = "claude/settings.json", .data = settings_before });
    try tmp.dir.writeFile(io, .{ .sub_path = "codex/hooks.json", .data = codex_hooks_before });
    try tmp.dir.writeFile(io, .{ .sub_path = "codex/config.toml", .data = codex_config_before });

    var root_buf: [std.fs.max_path_bytes]u8 = undefined;
    const root = root_buf[0..try tmp.dir.realPath(io, &root_buf)];
    const home = try std.fmt.allocPrintSentinel(a, "{s}/home", .{root}, 0);
    defer a.free(home);
    const claude = try std.fmt.allocPrintSentinel(a, "{s}/claude", .{root}, 0);
    defer a.free(claude);
    const codex = try std.fmt.allocPrintSentinel(a, "{s}/codex", .{root}, 0);
    defer a.free(codex);
    const cache = try std.fmt.allocPrintSentinel(a, "{s}/cache", .{root}, 0);
    defer a.free(cache);
    const config = try std.fmt.allocPrintSentinel(a, "{s}/missing-config", .{root}, 0);
    defer a.free(config);
    try std.testing.expectEqual(@as(c_int, 0), setenv("HOME", home.ptr, 1));
    try std.testing.expectEqual(@as(c_int, 0), setenv("CLAUDE_CONFIG_DIR", claude.ptr, 1));
    try std.testing.expectEqual(@as(c_int, 0), setenv("CODEX_HOME", codex.ptr, 1));
    try std.testing.expectEqual(@as(c_int, 0), setenv("XDG_CACHE_HOME", cache.ptr, 1));
    try std.testing.expectEqual(@as(c_int, 0), setenv("MARU_CONFIG", config.ptr, 1));

    // ① 켠다 — 두 provider 에 설치된다.
    test_config_text = agent_hooks_on_config;
    {
        var on: AppSession = undefined;
        try on.init(io, a, .{
            .abi_version = abi_version,
            .cols = 40,
            .rows = 10,
            .queue_capacity = 16,
            .command_kind = @intFromEnum(CommandKind.controlled_smoke),
        });
        on.deinit();
        const installed_claude = try tmp.dir.readFileAlloc(io, "claude/settings.json", a, .limited(64 * 1024));
        defer a.free(installed_claude);
        try std.testing.expect(std.mem.indexOf(u8, installed_claude, hook_command.marker) != null);
        const installed_codex = try tmp.dir.readFileAlloc(io, "codex/hooks.json", a, .limited(64 * 1024));
        defer a.free(installed_codex);
        try std.testing.expect(std.mem.indexOf(u8, installed_codex, hook_command.marker) != null);
        const installed_config = try tmp.dir.readFileAlloc(io, "codex/config.toml", a, .limited(64 * 1024));
        defer a.free(installed_config);
        try std.testing.expectEqual(@as(usize, hook_command.codex_events.len + 1), std.mem.count(u8, installed_config, "trusted_hash"));
    }

    // ② 끈다 — 우리 것만 사라지고 남의 것은 그대로여야 한다.
    test_config_text = agent_hooks_off_config;
    defer test_config_text = "";
    {
        var off: AppSession = undefined;
        try off.init(io, a, .{
            .abi_version = abi_version,
            .cols = 40,
            .rows = 10,
            .queue_capacity = 16,
            .command_kind = @intFromEnum(CommandKind.controlled_smoke),
        });
        off.deinit();
    }

    const claude_after = try tmp.dir.readFileAlloc(io, "claude/settings.json", a, .limited(64 * 1024));
    defer a.free(claude_after);
    try std.testing.expect(std.mem.indexOf(u8, claude_after, hook_command.marker) == null);
    {
        var parsed = try std.json.parseFromSlice(std.json.Value, a, claude_after, .{});
        defer parsed.deinit();
        // 다른 최상위 키와 사용자 훅이 살아 있다.
        try std.testing.expectEqualStrings("opus", parsed.value.object.get("model").?.string);
        try std.testing.expectEqualStrings(user_hook, parsed.value.object.get("hooks").?.object
            .get("Stop").?.array.items[0].object
            .get("hooks").?.array.items[0].object
            .get("command").?.string);
        try std.testing.expectEqual(@as(usize, 0), hook_install.scan(.claude, .local, parsed.value.object.get("hooks"), "").?.ours);
    }

    const codex_after = try tmp.dir.readFileAlloc(io, "codex/hooks.json", a, .limited(64 * 1024));
    defer a.free(codex_after);
    try std.testing.expect(std.mem.indexOf(u8, codex_after, hook_command.marker) == null);
    try std.testing.expect(std.mem.indexOf(u8, codex_after, legacy_hook) != null); // 과거 표식은 P1대로 남는다

    // **신뢰는 우리 것만 갔다.** 사용자가 직접 승인한 항목이 사라지면 그 사람은 다음 실행에 다시 묻힌다.
    const codex_config_after = try tmp.dir.readFileAlloc(io, "codex/config.toml", a, .limited(64 * 1024));
    defer a.free(codex_config_after);
    try std.testing.expectEqualStrings(codex_config_before, codex_config_after);

    // 다시 꺼도 아무 일이 없다 — 판정이 개수에만 달려 있어(`ours > 0`) 무동작이다.
    {
        var again: AppSession = undefined;
        try again.init(io, a, .{
            .abi_version = abi_version,
            .cols = 40,
            .rows = 10,
            .queue_capacity = 16,
            .command_kind = @intFromEnum(CommandKind.controlled_smoke),
        });
        again.deinit();
        const twice = try tmp.dir.readFileAlloc(io, "claude/settings.json", a, .limited(64 * 1024));
        defer a.free(twice);
        try std.testing.expectEqualStrings(claude_after, twice);
        const twice_config = try tmp.dir.readFileAlloc(io, "codex/config.toml", a, .limited(64 * 1024));
        defer a.free(twice_config);
        try std.testing.expectEqualStrings(codex_config_before, twice_config);
    }
}

test "agent hooks install into codex and record trust without touching existing entries" {
    // **이 테스트는 provider 설정 파일을 실제로 고치겠다고 밝힌다.** 기본은 꺼짐이다 — 격리를 잊은
    // 테스트가 개발자의 진짜 `~/.claude/settings.json` 을 고치는 사고가 났다(`test_allow_provider_writes`).
    agent_ops.test_allow_provider_writes = true;
    defer agent_ops.test_allow_provider_writes = false;

    if (builtin.os.tag != .macos or std.c.getenv("MARU_TEST_PROVIDER_NO_MUTATION") == null) return error.SkipZigTest;
    const hook_command = maru.session.agent_hook_command;
    const hook_install = maru.session.agent_hook_install;
    const hook_trust = maru.session.agent_hook_trust;
    const io = std.Io.Threaded.global_single_threaded.io();
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var env_guard = try workspace_ops.ProviderEnvGuard.capture(a);
    defer env_guard.restore();
    test_config_text = agent_hooks_on_config;
    defer test_config_text = "";
    try tmp.dir.createDirPath(io, "home");
    try tmp.dir.createDirPath(io, "codex");
    try tmp.dir.createDirPath(io, "cache");

    // 과거 표식 항목은 P1대로 살아남아야 하고, 사용자 훅도 순서 그대로 남아야 한다.
    const legacy_hook = "cat > /tmp/x # " ++ hook_command.legacy_markers[0];
    const hooks_before = "{\"hooks\":{\"Stop\":[{\"hooks\":[{\"command\":\"" ++ legacy_hook ++ "\"}]}]}}";
    try tmp.dir.writeFile(io, .{ .sub_path = "codex/hooks.json", .data = hooks_before });
    // 사용자가 쓰던 config.toml — 우리 항목만 뒤에 붙어야 한다.
    const config_before = "model = \"gpt-5\"\n";
    try tmp.dir.writeFile(io, .{ .sub_path = "codex/config.toml", .data = config_before });

    var root_buf: [std.fs.max_path_bytes]u8 = undefined;
    const root = root_buf[0..try tmp.dir.realPath(io, &root_buf)];
    const home = try std.fmt.allocPrintSentinel(a, "{s}/home", .{root}, 0);
    defer a.free(home);
    const codex = try std.fmt.allocPrintSentinel(a, "{s}/codex", .{root}, 0);
    defer a.free(codex);
    const cache = try std.fmt.allocPrintSentinel(a, "{s}/cache", .{root}, 0);
    defer a.free(cache);
    const config = try std.fmt.allocPrintSentinel(a, "{s}/missing-config", .{root}, 0);
    defer a.free(config);
    // **CODEX_HOME 을 심링크로 준다.** 신뢰 키는 실체 경로여야 하는데(계약 §2.1), 픽스처가 이미 실체
    // 경로면 그 규칙을 어겨도 테스트가 통과한다 — 실제로 그 상태였고 뮤테이션이 «못 잡음» 으로 드러났다.
    // dotfile 관리자와 macOS 의 `/tmp` 가 만드는 흔한 구성이기도 하다.
    const codex_link = try std.fmt.allocPrintSentinel(a, "{s}/codex-link", .{root}, 0);
    defer a.free(codex_link);
    try std.testing.expectEqual(@as(c_int, 0), std.c.symlink(codex.ptr, codex_link.ptr));

    try std.testing.expectEqual(@as(c_int, 0), setenv("HOME", home.ptr, 1));
    try std.testing.expectEqual(@as(c_int, 0), setenv("CODEX_HOME", codex_link.ptr, 1));
    // claude 디렉터리는 만들지 않는다 — 한쪽이 없어도 다른 쪽이 서야 한다(그 자체가 이 테스트의 단언이다).
    try std.testing.expectEqual(@as(c_int, 0), unsetenv("CLAUDE_CONFIG_DIR"));
    try std.testing.expectEqual(@as(c_int, 0), setenv("XDG_CACHE_HOME", cache.ptr, 1));
    try std.testing.expectEqual(@as(c_int, 0), setenv("MARU_CONFIG", config.ptr, 1));

    var session: AppSession = undefined;
    try session.init(io, a, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    session.deinit();

    const log_dir = try std.fmt.allocPrint(a, "{s}/maru/{s}", .{ cache, hook_command.log_dir_rel });
    defer a.free(log_dir);
    var want: std.ArrayListUnmanaged(u8) = .empty;
    defer want.deinit(a);
    try hook_command.build(&want, a, hook_command.Provider.codex.tag(), log_dir, .local);

    const hooks_after = try tmp.dir.readFileAlloc(io, "codex/hooks.json", a, .limited(64 * 1024));
    defer a.free(hooks_after);
    {
        var parsed = try std.json.parseFromSlice(std.json.Value, a, hooks_after, .{});
        defer parsed.deinit();
        const hooks = parsed.value.object.get("hooks").?.object;
        // **codex 세트다** — `Notification` 이 들어가면 안 된다.
        try std.testing.expect(hooks.get("Notification") == null);
        const known = hook_install.scan(.codex, .local, parsed.value.object.get("hooks"), want.items) orelse
            return error.UnknownShape;
        try std.testing.expectEqual(@as(usize, hook_command.codex_events.len), known.ours_current);
        try std.testing.expect(known.legacy_present); // 과거 표식은 그대로
        try std.testing.expectEqual(hook_install.Plan.leave, hook_install.planForSet(.codex, .local, .{ .known = known }, .ensure));
        // 사용자(legacy) 항목이 우리 것보다 **앞**이다.
        const stop = hooks.get("Stop").?.array;
        try std.testing.expectEqualStrings(
            legacy_hook,
            stop.items[0].object.get("hooks").?.array.items[0].object.get("command").?.string,
        );
    }

    // 신뢰 항목: 우리 항목 다섯의 키가 **실체 경로**로 적히고 값이 우리 계산과 같아야 한다.
    const config_after = try tmp.dir.readFileAlloc(io, "codex/config.toml", a, .limited(64 * 1024));
    defer a.free(config_after);
    try std.testing.expect(std.mem.startsWith(u8, config_after, config_before)); // 사용자 설정이 앞에 그대로
    {
        var parsed = try std.json.parseFromSlice(std.json.Value, a, hooks_after, .{});
        defer parsed.deinit();
        var slots: [hook_install.max_events]hook_install.Placement = undefined;
        const found = hook_install.ourPlacements(parsed.value.object.get("hooks"), want.items, &slots);
        try std.testing.expectEqual(@as(usize, hook_command.codex_events.len), found);

        // 링크가 아니라 **실체** 경로로 적혔어야 한다.
        const hooks_real = try std.fmt.allocPrint(a, "{s}/codex/hooks.json", .{root});
        try std.testing.expect(std.mem.indexOf(u8, config_after, "codex-link") == null);
        defer a.free(hooks_real);
        for (slots[0..found]) |placement| {
            const entry = hook_trust.forEvent(placement.json_name).?;
            var matcher: ?[]const u8 = null;
            for (hook_command.eventsFor(.codex, .local)) |e| {
                if (std.mem.eql(u8, e.name, placement.json_name)) matcher = e.matcher;
            }
            var key: std.ArrayListUnmanaged(u8) = .empty;
            defer key.deinit(a);
            try hook_trust.appendKey(&key, a, hooks_real, entry, placement.group_index, placement.handler_index);
            var hash: std.ArrayListUnmanaged(u8) = .empty;
            defer hash.deinit(a);
            try hook_trust.appendHash(&hash, a, entry, want.items, hook_command.timeout_seconds, matcher);

            if (std.mem.indexOf(u8, config_after, key.items) == null) {
                std.debug.print("missing trust key: {s}\n", .{key.items});
                return error.MissingTrustKey;
            }
            if (std.mem.indexOf(u8, config_after, hash.items) == null) {
                std.debug.print("missing trust hash for {s}\n", .{placement.json_name});
                return error.MissingTrustHash;
            }
        }
    }

    // 신뢰 파일이 **없던** 경우도 본다: 새로 만들면 권한이 umask 를 타므로 우리가 0600 으로 좁혀야 한다
    // (그 파일에 어떤 훅을 신뢰하는지가 적힌다). 기존 파일이면 승계라 손대지 않는다.
    // 훅 파일과 신뢰 파일이 **둘 다 없는** 상태에서도 서야 한다 — 새 사용자의 첫 실행이 이 경로다.
    // (순수 층은 «빈 설정에 넣기» 를 보지만, 제품 경로에서 파일을 새로 만드는 것은 여기서만 드러난다.)
    {
        try tmp.dir.deleteFile(io, "codex/hooks.json");
        try tmp.dir.deleteFile(io, "codex/config.toml");
        var fresh_both: AppSession = undefined;
        try fresh_both.init(io, a, .{
            .abi_version = abi_version,
            .cols = 40,
            .rows = 10,
            .queue_capacity = 16,
            .command_kind = @intFromEnum(CommandKind.controlled_smoke),
        });
        fresh_both.deinit();
        const made_hooks = try tmp.dir.readFileAlloc(io, "codex/hooks.json", a, .limited(64 * 1024));
        defer a.free(made_hooks);
        var parsed_new = try std.json.parseFromSlice(std.json.Value, a, made_hooks, .{});
        defer parsed_new.deinit();
        const known_new = hook_install.scan(.codex, .local, parsed_new.value.object.get("hooks"), want.items) orelse
            return error.UnknownShape;
        try std.testing.expectEqual(@as(usize, hook_command.codex_events.len), known_new.ours_current);
        const made_config = try tmp.dir.readFileAlloc(io, "codex/config.toml", a, .limited(64 * 1024));
        defer a.free(made_config);
        try std.testing.expectEqual(@as(usize, hook_command.codex_events.len), std.mem.count(u8, made_config, "trusted_hash"));
        // 원래 fixture 로 되돌려 아래 검사를 잇는다.
        try tmp.dir.writeFile(io, .{ .sub_path = "codex/hooks.json", .data = hooks_after });
        try tmp.dir.writeFile(io, .{ .sub_path = "codex/config.toml", .data = config_after });
    }

    {
        try tmp.dir.deleteFile(io, "codex/config.toml");
        var fresh_session: AppSession = undefined;
        try fresh_session.init(io, a, .{
            .abi_version = abi_version,
            .cols = 40,
            .rows = 10,
            .queue_capacity = 16,
            .command_kind = @intFromEnum(CommandKind.controlled_smoke),
        });
        fresh_session.deinit();
        const created = try tmp.dir.readFileAlloc(io, "codex/config.toml", a, .limited(64 * 1024));
        defer a.free(created);
        try std.testing.expect(std.mem.indexOf(u8, created, "trusted_hash") != null);
        const config_z = try std.fmt.allocPrintSentinel(a, "{s}/codex/config.toml", .{root}, 0);
        defer a.free(config_z);
        var st: std.posix.Stat = undefined;
        try std.testing.expectEqual(@as(c_int, 0), std.c.fstatat(std.posix.AT.FDCWD, config_z.ptr, &st, std.posix.AT.SYMLINK_NOFOLLOW));
        try std.testing.expectEqual(@as(std.posix.mode_t, 0o600), st.mode & 0o777);
        // 사용자 설정을 지우고 만든 것이므로 원본 내용은 없다 — 다시 써 넣어 아래 검사를 잇는다.
        try tmp.dir.writeFile(io, .{ .sub_path = "codex/config.toml", .data = config_after });
    }

    // **낡은 커맨드는 갱신된다.** 캐시 경로가 바뀌면(다른 `XDG_CACHE_HOME`, 캐시 정리) 커맨드 안의 로그
    // 경로가 달라져 우리 항목이 낡는다. 그때 두 벌이 되지 않고 한 벌로 교체돼야 한다.
    {
        var stale: std.ArrayListUnmanaged(u8) = .empty;
        defer stale.deinit(a);
        try hook_command.build(&stale, a, hook_command.Provider.codex.tag(), "/tmp/maru-old-log-dir", .local);
        const stale_json = try std.fmt.allocPrint(a,
            \\{{ "hooks": {{ "Stop": [ {{ "hooks": [ {{ "type": "command", "command": {f}, "timeout": 2 }} ] }} ] }} }}
        , .{std.json.fmt(std.json.Value{ .string = stale.items }, .{})});
        defer a.free(stale_json);
        try tmp.dir.writeFile(io, .{ .sub_path = "codex/hooks.json", .data = stale_json });

        var refreshed: AppSession = undefined;
        try refreshed.init(io, a, .{
            .abi_version = abi_version,
            .cols = 40,
            .rows = 10,
            .queue_capacity = 16,
            .command_kind = @intFromEnum(CommandKind.controlled_smoke),
        });
        refreshed.deinit();

        const fixed = try tmp.dir.readFileAlloc(io, "codex/hooks.json", a, .limited(64 * 1024));
        defer a.free(fixed);
        try std.testing.expect(std.mem.indexOf(u8, fixed, "maru-old-log-dir") == null); // 낡은 것이 남지 않는다
        var parsed_fixed = try std.json.parseFromSlice(std.json.Value, a, fixed, .{});
        defer parsed_fixed.deinit();
        const known_fixed = hook_install.scan(.codex, .local, parsed_fixed.value.object.get("hooks"), want.items) orelse
            return error.UnknownShape;
        try std.testing.expectEqual(@as(usize, hook_command.codex_events.len), known_fixed.ours); // 두 벌이 아니다
        try testing_expect_leave(known_fixed);
        // ⚠️ 이 경로가 드러내는 성질: 항목의 **위치가 바뀌면 신뢰 키도 바뀐다**(키가 인덱스를 담는다).
        // 옛 키의 항목은 `config.toml` 에 남는데, codex 는 어떤 훅과도 짝이 안 맞는 키를 그냥 무시하므로
        // 고장은 아니고 **잔재**다. 우리는 «비어 있을 때만 쓴다» 규칙 때문에 남의 줄을 지우지 않는다.
        const after_refresh_config = try tmp.dir.readFileAlloc(io, "codex/config.toml", a, .limited(64 * 1024));
        defer a.free(after_refresh_config);
        try std.testing.expect(after_refresh_config.len >= config_after.len); // 줄지 않는다(지우지 않으므로)

        // 되돌린다 — 훅 파일과 신뢰 파일을 **둘 다** 되돌려야 아래 바이트 비교가 성립한다.
        try tmp.dir.writeFile(io, .{ .sub_path = "codex/hooks.json", .data = hooks_after });
        try tmp.dir.writeFile(io, .{ .sub_path = "codex/config.toml", .data = config_after });
    }

    // **다시 띄워도 신뢰 항목이 늘지 않는다.** 같은 테이블을 두 번 적으면 codex 가 config 를 통째로 못 읽는다.
    {
        var again: AppSession = undefined;
        try again.init(io, a, .{
            .abi_version = abi_version,
            .cols = 40,
            .rows = 10,
            .queue_capacity = 16,
            .command_kind = @intFromEnum(CommandKind.controlled_smoke),
        });
        again.deinit();
        const twice = try tmp.dir.readFileAlloc(io, "codex/config.toml", a, .limited(64 * 1024));
        defer a.free(twice);
        try std.testing.expectEqualStrings(config_after, twice);
        const hooks_twice = try tmp.dir.readFileAlloc(io, "codex/hooks.json", a, .limited(64 * 1024));
        defer a.free(hooks_twice);
        try std.testing.expectEqualStrings(hooks_after, hooks_twice);
    }
}

// 계약 §2.1 — codex 는 `config.toml` 의 값이 그 훅의 현재 내용과 다르면 **그 훅을 실행하지 않는다**
// (`hooks/list` 의 `trustStatus` 가 `modified`). 키는 항목의 **자리**로 만들어져 커맨드를 고쳐도 그대로라,
// 커맨드가 바뀐 뒤에는 «키는 있고 값만 낡은» 상태가 남는다. 우리는 남의 값을 덮지 않으므로(무한 승인
// 프롬프트 방지) 그 상태는 사용자가 codex 에서 승인해야 풀린다 — 그래서 **알린다**.
//
// 알리지 않으면 사용자에게 남는 정보는 «훅을 켰는데 배지가 여전히 화면을 따라간다» 뿐이다. 2026-08-25 에
// 실제로 그 상태였고(V3 훅 7개가 전부 `modified`), 무엇이 잘못됐는지 알려 주는 표면이 아무 데도 없었다.
test "codex 신뢰 값이 낡으면 한 번만 고치고, 되돌아오면 알린다" {
    agent_ops.test_allow_provider_writes = true;
    defer agent_ops.test_allow_provider_writes = false;

    if (builtin.os.tag != .macos or std.c.getenv("MARU_TEST_PROVIDER_NO_MUTATION") == null) return error.SkipZigTest;
    const hook_command = maru.session.agent_hook_command;
    const io = std.Io.Threaded.global_single_threaded.io();
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var env_guard = try workspace_ops.ProviderEnvGuard.capture(a);
    defer env_guard.restore();
    test_config_text = agent_hooks_on_config;
    defer test_config_text = "";
    try tmp.dir.createDirPath(io, "home");
    try tmp.dir.createDirPath(io, "codex");
    try tmp.dir.createDirPath(io, "cache");
    try tmp.dir.writeFile(io, .{ .sub_path = "codex/config.toml", .data = "model = \"gpt-5\"\n" });

    var root_buf: [std.fs.max_path_bytes]u8 = undefined;
    const root = root_buf[0..try tmp.dir.realPath(io, &root_buf)];
    const home = try std.fmt.allocPrintSentinel(a, "{s}/home", .{root}, 0);
    defer a.free(home);
    const codex = try std.fmt.allocPrintSentinel(a, "{s}/codex", .{root}, 0);
    defer a.free(codex);
    const cache = try std.fmt.allocPrintSentinel(a, "{s}/cache", .{root}, 0);
    defer a.free(cache);
    const config = try std.fmt.allocPrintSentinel(a, "{s}/missing-config", .{root}, 0);
    defer a.free(config);
    try std.testing.expectEqual(@as(c_int, 0), setenv("HOME", home.ptr, 1));
    try std.testing.expectEqual(@as(c_int, 0), setenv("CODEX_HOME", codex.ptr, 1));
    try std.testing.expectEqual(@as(c_int, 0), unsetenv("CLAUDE_CONFIG_DIR"));
    try std.testing.expectEqual(@as(c_int, 0), setenv("XDG_CACHE_HOME", cache.ptr, 1));
    try std.testing.expectEqual(@as(c_int, 0), setenv("MARU_CONFIG", config.ptr, 1));

    // ① 한 번 설치한다 — 이 시점의 값은 **맞다**(설치가 방금 계산한 값이다).
    {
        var first: AppSession = undefined;
        try first.init(io, a, .{
            .abi_version = abi_version,
            .cols = 40,
            .rows = 10,
            .queue_capacity = 16,
            .command_kind = @intFromEnum(CommandKind.controlled_smoke),
        });
        // 갓 설치한 자리는 어긋남이 아니다 — 여기서 세면 매 설치가 경고를 띄운다.
        try std.testing.expectEqual(@as(u32, 0), first.agent_hook_trust_stale);
        first.deinit();
    }

    // ② 커맨드가 바뀐 뒤를 흉내 낸다: 값도, 우리가 남긴 `tried=` 기록도 **옛 값**이 된다(그게 실제 모양이다 —
    //    커맨드가 바뀌면 우리 해시가 달라지고 파일에 남은 둘은 그대로다). 키·자리는 안 건드린다.
    const installed = try tmp.dir.readFileAlloc(io, "codex/config.toml", a, .limited(64 * 1024));
    defer a.free(installed);
    var stale_text: std.ArrayListUnmanaged(u8) = .empty;
    defer stale_text.deinit(a);
    var replaced: usize = 0;
    var rest: []const u8 = installed;
    while (std.mem.indexOf(u8, rest, "sha256:")) |at| {
        const value_end = std.mem.indexOfAnyPos(u8, rest, at, "\"\n") orelse break;
        try stale_text.appendSlice(a, rest[0..at]);
        try stale_text.appendSlice(a, "sha256:staaale");
        rest = rest[value_end..];
        replaced += 1;
    }
    try stale_text.appendSlice(a, rest);
    // 항목마다 값 한 번 + `tried=` 한 번이다.
    try std.testing.expectEqual(@as(usize, hook_command.codex_events.len * 2), replaced);
    try tmp.dir.writeFile(io, .{ .sub_path = "codex/config.toml", .data = stale_text.items });

    // ③ 다시 뜬다. 훅 파일은 그대로라 설치는 «할 것 없음» 이고, 그 경로에서 **고친다**.
    var session: AppSession = undefined;
    try session.init(io, a, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    try std.testing.expectEqual(@as(u32, hook_command.codex_events.len), session.agent_hook_trust_refreshed);
    try std.testing.expectEqual(@as(u32, 0), session.agent_hook_trust_stale);

    // **갱신은 설치가 쓰는 바이트와 같은 것을 돌려놓는다.** 제자리 수술이 줄 하나만 갈아 끼우고 나머지는
    // 원문 그대로 흘려보낸다는 뜻이다 — 여기가 어긋나면 사용자 파일이 조금씩 변형된다.
    const healed = try tmp.dir.readFileAlloc(io, "codex/config.toml", a, .limited(64 * 1024));
    defer a.free(healed);
    try std.testing.expectEqualStrings(installed, healed);

    // 고친 것도 **알린다** — 사용자 홈의 파일을 우리가 손댔고 그 결과 codex 동작이 달라진다.
    session.update_started = true; // 첫 tick 의 새 버전 백그라운드 체크는 네트워크라 테스트에서 끈다.
    try std.testing.expect(!session.chrome_host.notice.open);
    session.runFramePreHousekeeping();
    try std.testing.expect(session.chrome_host.notice.open);
    try std.testing.expectEqual(@as(u32, 0), session.agent_hook_trust_refreshed);

    // ④ **무한 프롬프트 차단기.** 사용자가 codex 에서 승인하면 codex 가 **자기 값**을 적는다 — 우리 값이
    //    틀렸다면 그 모양이 된다(값은 남의 것, `tried=` 는 우리가 마지막에 쓴 것). 그때 또 쓰면 매 실행
    //    승인 프롬프트가 뜨는 루프가 된다. 값 하나당 시도는 한 번뿐이어야 한다.
    var reverted: std.ArrayListUnmanaged(u8) = .empty;
    defer reverted.deinit(a);
    var reverts: usize = 0;
    var tail: []const u8 = healed;
    const value_prefix = "trusted_hash = \"";
    while (std.mem.indexOf(u8, tail, value_prefix)) |at| {
        const from = at + value_prefix.len;
        const end = std.mem.indexOfScalarPos(u8, tail, from, '"') orelse break;
        try reverted.appendSlice(a, tail[0..from]);
        try reverted.appendSlice(a, "sha256:codexwroteit");
        tail = tail[end..];
        reverts += 1;
    }
    try reverted.appendSlice(a, tail);
    try std.testing.expectEqual(@as(usize, hook_command.codex_events.len), reverts); // 값만 되돌렸다
    try tmp.dir.writeFile(io, .{ .sub_path = "codex/config.toml", .data = reverted.items });

    agent_ops.reconcileAgentHooks(&session);
    // **«안 돈다» 가 아니라 «갈렸다» 다.** 우리가 쓴 직후 누군가 다른 값을 넣었다는 뜻이고, 그 누군가가
    // 승인을 받은 codex 라면 훅은 정상으로 돈다 — 그때 「승인하라」고 하면 방금 승인한 사람에게 거짓말이다.
    try std.testing.expectEqual(@as(u32, hook_command.codex_events.len), session.agent_hook_trust_diverged);
    try std.testing.expectEqual(@as(u32, 0), session.agent_hook_trust_stale);
    try std.testing.expectEqual(@as(u32, 0), session.agent_hook_trust_refreshed); // 다시 쓰지 않았다

    // **되돌아온 값을 안 건드렸다** — 이 단언이 곧 「무한 루프가 아니다」의 증거다.
    const after_revert = try tmp.dir.readFileAlloc(io, "codex/config.toml", a, .limited(64 * 1024));
    defer a.free(after_revert);
    try std.testing.expectEqualStrings(reverted.items, after_revert);

    // ⑤ 그때는 **사용자가 할 일**을 알린다(고쳤다는 알림이 아니라). tick 이 실제로 부르는 경로로 확인한다 —
    //    `showPending…` 을 직접 부르면 그 함수가 tick 에 걸려 있는지는 못 본다.
    session.dismissMessageOverlays();
    session.runFramePreHousekeeping();
    try std.testing.expect(session.chrome_host.notice.open);
    // **어느 문구가 떴는지까지 본다.** 개수만 세면 「안 돈다」 문구가 그대로 떠도 통과한다 — 이 슬라이스가
    // 고치려는 것이 바로 그 문구다.
    try std.testing.expect(std.mem.indexOf(
        u8,
        session.chrome_host.notice.message,
        maru.i18n.t(.app_agent_hook_trust_diverged)[0..12],
    ) != null);
    try std.testing.expectEqual(@as(u32, 0), session.agent_hook_trust_diverged); // 한 번 띄우고 끈다
    const after_tick = try tmp.dir.readFileAlloc(io, "codex/config.toml", a, .limited(64 * 1024));
    defer a.free(after_tick);
    try std.testing.expectEqualStrings(reverted.items, after_tick);
}

// 계약 §2.1 — 갱신은 **파일에 실제로 들어간 뒤에야** «고쳤다» 다. CAS 가 다른 인스턴스에 밀리거나 쓰기가
// 실패하면 아무것도 안 고쳐진 것이고, 그때 그 훅들은 **여전히 안 돈다**. 그 상태에서 「고쳤습니다」가 뜨면
// 두 번 틀린다 — 하지 않은 일을 했다고 말하고, 사용자가 해야 할 일(codex 에서 승인)을 안 알려 준다.
//
// CAS 경쟁은 단일 프로세스로 못 만든다. 쓰기 실패는 만들 수 있다 — 디렉터리를 읽기 전용으로 두면 원자적
// 교체(rename)가 실패한다. 같은 분기이므로 이 판정자가 그 계약을 대표한다.
test "codex 신뢰 값을 못 썼으면 «고쳤다» 고 말하지 않는다" {
    agent_ops.test_allow_provider_writes = true;
    defer agent_ops.test_allow_provider_writes = false;

    if (builtin.os.tag != .macos or std.c.getenv("MARU_TEST_PROVIDER_NO_MUTATION") == null) return error.SkipZigTest;
    const hook_command = maru.session.agent_hook_command;
    const io = std.Io.Threaded.global_single_threaded.io();
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var env_guard = try workspace_ops.ProviderEnvGuard.capture(a);
    defer env_guard.restore();
    test_config_text = agent_hooks_on_config;
    defer test_config_text = "";
    try tmp.dir.createDirPath(io, "home");
    try tmp.dir.createDirPath(io, "codex");
    try tmp.dir.createDirPath(io, "cache");
    try tmp.dir.writeFile(io, .{ .sub_path = "codex/config.toml", .data = "model = \"gpt-5\"\n" });

    var root_buf: [std.fs.max_path_bytes]u8 = undefined;
    const root = root_buf[0..try tmp.dir.realPath(io, &root_buf)];
    const home = try std.fmt.allocPrintSentinel(a, "{s}/home", .{root}, 0);
    defer a.free(home);
    const codex = try std.fmt.allocPrintSentinel(a, "{s}/codex", .{root}, 0);
    defer a.free(codex);
    const cache = try std.fmt.allocPrintSentinel(a, "{s}/cache", .{root}, 0);
    defer a.free(cache);
    const config = try std.fmt.allocPrintSentinel(a, "{s}/missing-config", .{root}, 0);
    defer a.free(config);
    try std.testing.expectEqual(@as(c_int, 0), setenv("HOME", home.ptr, 1));
    try std.testing.expectEqual(@as(c_int, 0), setenv("CODEX_HOME", codex.ptr, 1));
    try std.testing.expectEqual(@as(c_int, 0), unsetenv("CLAUDE_CONFIG_DIR"));
    try std.testing.expectEqual(@as(c_int, 0), setenv("XDG_CACHE_HOME", cache.ptr, 1));
    try std.testing.expectEqual(@as(c_int, 0), setenv("MARU_CONFIG", config.ptr, 1));

    { // 한 번 설치해 두고
        var first: AppSession = undefined;
        try first.init(io, a, .{
            .abi_version = abi_version,
            .cols = 40,
            .rows = 10,
            .queue_capacity = 16,
            .command_kind = @intFromEnum(CommandKind.controlled_smoke),
        });
        first.deinit();
    }

    // 값을 낡게 만든다(커맨드가 바뀐 뒤의 모양).
    const installed = try tmp.dir.readFileAlloc(io, "codex/config.toml", a, .limited(64 * 1024));
    defer a.free(installed);
    var stale_text: std.ArrayListUnmanaged(u8) = .empty;
    defer stale_text.deinit(a);
    var rest: []const u8 = installed;
    while (std.mem.indexOf(u8, rest, "sha256:")) |at| {
        const value_end = std.mem.indexOfAnyPos(u8, rest, at, "\"\n") orelse break;
        try stale_text.appendSlice(a, rest[0..at]);
        try stale_text.appendSlice(a, "sha256:staaale");
        rest = rest[value_end..];
    }
    try stale_text.appendSlice(a, rest);
    try tmp.dir.writeFile(io, .{ .sub_path = "codex/config.toml", .data = stale_text.items });

    // **쓰기를 막는다** — 디렉터리가 읽기 전용이면 원자적 교체가 실패한다.
    try std.testing.expectEqual(@as(c_int, 0), std.c.chmod(codex.ptr, 0o555));
    defer _ = std.c.chmod(codex.ptr, 0o755); // tmp 정리가 지울 수 있게 되돌린다

    var session: AppSession = undefined;
    try session.init(io, a, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // 못 고쳤으니 «고쳤다» 가 아니고, 사용자가 할 일이 남았으니 **어긋남으로** 센다.
    try std.testing.expectEqual(@as(u32, 0), session.agent_hook_trust_refreshed);
    try std.testing.expectEqual(@as(u32, hook_command.codex_events.len), session.agent_hook_trust_stale);

    // 파일도 그대로다.
    const after = try tmp.dir.readFileAlloc(io, "codex/config.toml", a, .limited(64 * 1024));
    defer a.free(after);
    try std.testing.expectEqualStrings(stale_text.items, after);
}

test "agent hooks stay out of provider files while the gate is off" {
    if (builtin.os.tag != .macos or std.c.getenv("MARU_TEST_PROVIDER_NO_MUTATION") == null) return error.SkipZigTest;
    // 기본값이 `false`라는 계약을 **제품 경로에서** 못 박는다. 위 hook-off fixture는 상태줄 키만 끄므로,
    // 훅 게이트가 실수로 기본 on이 되면 그 테스트가 아니라 여기가 먼저 걸린다.
    const io = std.Io.Threaded.global_single_threaded.io();
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var env_guard = try workspace_ops.ProviderEnvGuard.capture(a);
    defer env_guard.restore();
    test_config_text = ""; // 아무 설정도 주지 않는다 = 전부 기본값
    try tmp.dir.createDirPath(io, "home");
    try tmp.dir.createDirPath(io, "claude");
    try tmp.dir.createDirPath(io, "codex");
    try tmp.dir.createDirPath(io, "cache");
    const settings_before = "{\"model\":\"opus\"}";
    try tmp.dir.writeFile(io, .{ .sub_path = "claude/settings.json", .data = settings_before });
    // **codex 도 함께 본다** — 게이트 하나가 두 provider 를 다 막는지 확인해야 한다(한쪽만 막히면 끈
    // 사람의 다른 설정 파일이 조용히 고쳐진다).
    const codex_before = "{\"hooks\":{}}";
    try tmp.dir.writeFile(io, .{ .sub_path = "codex/hooks.json", .data = codex_before });

    var root_buf: [std.fs.max_path_bytes]u8 = undefined;
    const root = root_buf[0..try tmp.dir.realPath(io, &root_buf)];
    const home = try std.fmt.allocPrintSentinel(a, "{s}/home", .{root}, 0);
    defer a.free(home);
    const claude = try std.fmt.allocPrintSentinel(a, "{s}/claude", .{root}, 0);
    defer a.free(claude);
    const codex = try std.fmt.allocPrintSentinel(a, "{s}/codex", .{root}, 0);
    defer a.free(codex);
    const cache = try std.fmt.allocPrintSentinel(a, "{s}/cache", .{root}, 0);
    defer a.free(cache);
    const config = try std.fmt.allocPrintSentinel(a, "{s}/missing-config", .{root}, 0);
    defer a.free(config);
    try std.testing.expectEqual(@as(c_int, 0), setenv("HOME", home.ptr, 1));
    try std.testing.expectEqual(@as(c_int, 0), setenv("CLAUDE_CONFIG_DIR", claude.ptr, 1));
    try std.testing.expectEqual(@as(c_int, 0), setenv("CODEX_HOME", codex.ptr, 1));
    try std.testing.expectEqual(@as(c_int, 0), setenv("XDG_CACHE_HOME", cache.ptr, 1));
    try std.testing.expectEqual(@as(c_int, 0), setenv("MARU_CONFIG", config.ptr, 1));

    var session: AppSession = undefined;
    try session.init(io, a, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    session.deinit();

    // **`hooks` 키가 생기지 않았다.** 기본 config 그대로 돌렸으므로 상태줄 훅(그쪽은 기본 on)은 `statusLine`을
    // 쓸 수 있다 — 그것까지 없다고 단언하면 이 테스트가 남의 계약을 검사하게 된다. 우리 축만 본다.
    const after = try tmp.dir.readFileAlloc(io, "claude/settings.json", a, .limited(4096));
    defer a.free(after);
    try std.testing.expect(std.mem.indexOf(u8, after, maru.session.agent_hook_command.marker) == null);
    {
        var parsed = try std.json.parseFromSlice(std.json.Value, a, after, .{});
        defer parsed.deinit();
        try std.testing.expect(parsed.value.object.get("hooks") == null);
        try std.testing.expectEqualStrings("opus", parsed.value.object.get("model").?.string);
    }
    // 로그 디렉터리도 만들지 않는다 — 끈 사람의 디스크에 우리 자리를 잡아 두지 않는다.
    const log_dir = try std.fmt.allocPrintSentinel(a, "{s}/maru/{s}", .{ cache, maru.session.agent_hook_command.log_dir_rel }, 0);
    defer a.free(log_dir);
    var stat: std.posix.Stat = undefined;
    try std.testing.expect(std.c.fstatat(std.posix.AT.FDCWD, log_dir.ptr, &stat, std.posix.AT.SYMLINK_NOFOLLOW) != 0);

    // codex 쪽도 그대로다 — 훅 파일은 바이트까지 같고, 신뢰 파일은 아예 생기지 않는다.
    const codex_after = try tmp.dir.readFileAlloc(io, "codex/hooks.json", a, .limited(4096));
    defer a.free(codex_after);
    try std.testing.expectEqualStrings(codex_before, codex_after);
    try expectProviderFixtureEntries(io, codex, &.{.{ .name = "hooks.json", .kind = .file }});
}

test "statusline hook is removed on startup — the wrapped original comes back and our files go" {
    // **이 테스트는 provider 설정 파일을 실제로 고치겠다고 밝힌다**(`test_allow_provider_writes`).
    agent_ops.test_allow_provider_writes = true;
    defer agent_ops.test_allow_provider_writes = false;

    if (builtin.os.tag != .macos or std.c.getenv("MARU_TEST_PROVIDER_NO_MUTATION") == null) return error.SkipZigTest;
    const sl = maru.session.agent_statusline;
    const io = std.Io.Threaded.global_single_threaded.io();
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var env_guard = try workspace_ops.ProviderEnvGuard.capture(a);
    defer env_guard.restore();
    test_config_text = "";
    defer test_config_text = "";
    try tmp.dir.createDirPath(io, "home");
    try tmp.dir.createDirPath(io, "claude");
    try tmp.dir.createDirPath(io, "cache");

    var root_buf: [std.fs.max_path_bytes]u8 = undefined;
    const root = root_buf[0..try tmp.dir.realPath(io, &root_buf)];
    const home = try std.fmt.allocPrintSentinel(a, "{s}/home", .{root}, 0);
    defer a.free(home);
    const claude = try std.fmt.allocPrintSentinel(a, "{s}/claude", .{root}, 0);
    defer a.free(claude);
    const cache = try std.fmt.allocPrintSentinel(a, "{s}/cache", .{root}, 0);
    defer a.free(cache);
    const config = try std.fmt.allocPrintSentinel(a, "{s}/missing-config", .{root}, 0);
    defer a.free(config);
    try std.testing.expectEqual(@as(c_int, 0), setenv("HOME", home.ptr, 1));
    try std.testing.expectEqual(@as(c_int, 0), setenv("CLAUDE_CONFIG_DIR", claude.ptr, 1));
    try std.testing.expectEqual(@as(c_int, 0), setenv("XDG_CACHE_HOME", cache.ptr, 1));
    try std.testing.expectEqual(@as(c_int, 0), setenv("MARU_CONFIG", config.ptr, 1));
    try std.testing.expectEqual(@as(c_int, 0), unsetenv("CODEX_HOME"));

    // 지난 버전이 설치해 둔 상태를 그대로 만든다: settings 는 우리 스크립트를 가리키고, 스크립트는
    // 사용자 명령을 감싸고 있으며, 마커가 그 원본을 들고 있다.
    const user_command = "bunx ccusage statusline --theme dark";
    const script_path = try std.fmt.allocPrint(a, "{s}/{s}", .{ claude, sl.script_name });
    defer a.free(script_path);
    const settings_before = try std.fmt.allocPrint(a, "{{\"model\":\"opus\",\"statusLine\":{{\"type\":\"command\",\"command\":\"{s}\"}}}}", .{script_path});
    defer a.free(settings_before);
    try tmp.dir.writeFile(io, .{ .sub_path = "claude/settings.json", .data = settings_before });
    try tmp.dir.writeFile(io, .{
        .sub_path = "claude/" ++ sl.script_name,
        .data = "#!/bin/sh\n" ++ sl.wrapped_begin ++ "\nprintf '%s' \"$payload\" | sh -c '" ++ user_command ++ "'\n" ++ sl.wrapped_end ++ "\n",
    });
    try tmp.dir.writeFile(io, .{
        .sub_path = "claude/" ++ sl.marker_name,
        .data = sl.marker_header ++ "\nwrapped 1 " ++ "36" ++ "\n" ++ user_command,
    });

    var session: AppSession = undefined;
    try session.init(io, a, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    session.deinit();

    // **원본이 돌아온다.** 감싸는 설계의 존재 이유가 이것이었고, 제거가 그 약속을 지키는 자리다.
    const after = try tmp.dir.readFileAlloc(io, "claude/settings.json", a, .limited(16 * 1024));
    defer a.free(after);
    var parsed = try std.json.parseFromSlice(std.json.Value, a, after, .{});
    defer parsed.deinit();
    const root_obj = parsed.value.object;
    const status = root_obj.get("statusLine") orelse return error.StatusLineGone;
    try std.testing.expectEqualStrings(user_command, status.object.get("command").?.string);
    // 다른 최상위 키는 그대로다 — 우리는 그 한 키만 다룬다.
    try std.testing.expectEqualStrings("opus", root_obj.get("model").?.string);

    // **우리 파일은 사라진다.** 남겨 두면 provider 가 계속 실행하고, 아무도 그 결과를 읽지 않는다.
    try std.testing.expect(tmp.dir.statFile(io, "claude/" ++ sl.script_name, .{}) catch null == null);
    try std.testing.expect(tmp.dir.statFile(io, "claude/" ++ sl.marker_name, .{}) catch null == null);
}

test "statusline removal leaves someone else's statusLine alone" {
    agent_ops.test_allow_provider_writes = true;
    defer agent_ops.test_allow_provider_writes = false;

    if (builtin.os.tag != .macos or std.c.getenv("MARU_TEST_PROVIDER_NO_MUTATION") == null) return error.SkipZigTest;
    const sl = maru.session.agent_statusline;
    const io = std.Io.Threaded.global_single_threaded.io();
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var env_guard = try workspace_ops.ProviderEnvGuard.capture(a);
    defer env_guard.restore();
    test_config_text = "";
    defer test_config_text = "";
    try tmp.dir.createDirPath(io, "home");
    try tmp.dir.createDirPath(io, "claude");
    try tmp.dir.createDirPath(io, "cache");

    var root_buf: [std.fs.max_path_bytes]u8 = undefined;
    const root = root_buf[0..try tmp.dir.realPath(io, &root_buf)];
    const home = try std.fmt.allocPrintSentinel(a, "{s}/home", .{root}, 0);
    defer a.free(home);
    const claude = try std.fmt.allocPrintSentinel(a, "{s}/claude", .{root}, 0);
    defer a.free(claude);
    const cache = try std.fmt.allocPrintSentinel(a, "{s}/cache", .{root}, 0);
    defer a.free(cache);
    const config = try std.fmt.allocPrintSentinel(a, "{s}/missing-config", .{root}, 0);
    defer a.free(config);
    try std.testing.expectEqual(@as(c_int, 0), setenv("HOME", home.ptr, 1));
    try std.testing.expectEqual(@as(c_int, 0), setenv("CLAUDE_CONFIG_DIR", claude.ptr, 1));
    try std.testing.expectEqual(@as(c_int, 0), setenv("XDG_CACHE_HOME", cache.ptr, 1));
    try std.testing.expectEqual(@as(c_int, 0), setenv("MARU_CONFIG", config.ptr, 1));
    try std.testing.expectEqual(@as(c_int, 0), unsetenv("CODEX_HOME"));

    // 사용자가 그 사이 statusLine 을 **직접** 바꿔 두었다(우리 스크립트를 안 가리킨다). 그 값은 사용자의
    // 현재 의사이므로 되돌리면 안 된다 — 우리 파일만 거둔다.
    const theirs = "bunx someone-elses-statusline";
    try tmp.dir.writeFile(io, .{
        .sub_path = "claude/settings.json",
        .data = "{\"statusLine\":{\"type\":\"command\",\"command\":\"" ++ theirs ++ "\"}}",
    });
    try tmp.dir.writeFile(io, .{ .sub_path = "claude/" ++ sl.script_name, .data = "#!/bin/sh\nexit 0\n" });
    try tmp.dir.writeFile(io, .{ .sub_path = "claude/" ++ sl.marker_name, .data = sl.marker_header ++ "\nwrapped 0 0\n" });

    var session: AppSession = undefined;
    try session.init(io, a, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    session.deinit();

    const after = try tmp.dir.readFileAlloc(io, "claude/settings.json", a, .limited(16 * 1024));
    defer a.free(after);
    try std.testing.expect(std.mem.indexOf(u8, after, theirs) != null); // 남의 값은 그대로
    try std.testing.expect(tmp.dir.statFile(io, "claude/" ++ sl.script_name, .{}) catch null == null);
    try std.testing.expect(tmp.dir.statFile(io, "claude/" ++ sl.marker_name, .{}) catch null == null);
}

// 상태줄 훅이 **파일에 대해** 지키기로 한 규율 — 직렬화·원자 교체·쓰기 순서·"모르면 손대지 않음" — 을 제품
// 경로에서 검증한다. 적대 검증이 이 넷을 전부 무력화해도 기존 게이트가 green이라는 것을 실측으로 보였다
// (마커 **내용** 로직만 덮여 있었다). 각 블록은 그 뮤테이션 하나에 대응한다.

test "macOS app session config rejects unsafe fixed-width ABI input" {
    // Swift가 넘긴 config는 Zig allocator나 slice를 포함하지 않는 fixed-width record다.
    // 이 검증이 있어야 잘못된 window size나 오래된 ABI가 PTY spawn까지 내려가지 않는다.
    try std.testing.expectError(error.UnsupportedAbi, normalizeConfig(.{
        .abi_version = abi_version - 1,
        .cols = 80,
        .rows = 24,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    }));
    try std.testing.expectError(error.InvalidConfig, normalizeConfig(.{
        .abi_version = abi_version,
        .cols = 0,
        .rows = 24,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    }));
    try std.testing.expectError(error.InvalidConfig, normalizeConfig(.{
        .abi_version = abi_version,
        .cols = 80,
        .rows = 24,
        .queue_capacity = 16,
        .command_kind = 999,
    }));
}

test "macOS app session config defaults queue capacity without changing command intent" {
    const normalized = try normalizeConfig(.{
        .abi_version = abi_version,
        .cols = 80,
        .rows = 24,
        .queue_capacity = 0,
        .command_kind = @intFromEnum(CommandKind.interactive_shell),
    });
    try std.testing.expectEqual(terminal.Size{ .cols = 80, .rows = 24 }, normalized.size);
    try std.testing.expectEqual(@as(usize, default_queue_capacity), normalized.queue_capacity);
    try std.testing.expectEqual(CommandKind.interactive_shell, normalized.command_kind);
    try std.testing.expect(!normalized.is_quick);
    try std.testing.expectEqual(false, normalized.chrome_minimal); // 기본 full(0)
    try std.testing.expectEqual(false, normalized.minimal_tabs); // 기본 스크래치(0)
}

test "macOS app session normalizeConfig carries chrome_minimal and minimal_tabs flags" {
    const full = try normalizeConfig(.{
        .abi_version = abi_version,
        .cols = 80,
        .rows = 24,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
        .chrome_minimal = 0,
    });
    try std.testing.expectEqual(false, full.chrome_minimal);
    try std.testing.expectEqual(false, full.minimal_tabs);
    const quick = try normalizeConfig(.{
        .abi_version = abi_version,
        .cols = 80,
        .rows = 24,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.quick_interactive_shell),
    });
    try std.testing.expect(quick.is_quick);

    const minimal = try normalizeConfig(.{
        .abi_version = abi_version,
        .cols = 80,
        .rows = 24,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
        .chrome_minimal = 1,
        .minimal_tabs = 1,
    });
    try std.testing.expectEqual(true, minimal.chrome_minimal);
    try std.testing.expectEqual(true, minimal.minimal_tabs);
}

test "quickTerminalFrames/quickTerminalConfig: 설정 변경을 라이브로 반영(세션-불변 스냅샷 아님)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    // 이 테스트가 증명하는 것: 세션의 config를 (설정 GUI가 하듯 schema setter로) 바꾸면 quickTerminalFrames·
    // quickTerminalConfig가 **세션 재생성 없이** 새 값을 돌려준다. Swift가 매 토글마다 이 API를 다시 불러 퀵
    // 터미널 위치·두께·동작을 라이브로 반영하는 계약의 근거다 — 예전엔 Swift가 첫 생성 때 스냅샷을 캐시해 이미
    // 연 퀵 터미널엔 설정 변경이 재시작 전까지 안 먹던 버그의 회귀 가드(코어 API가 라이브임을 못박아 둔다).
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // 기본(top, 두께 0.45): 상단에 붙음.
    session.loaded_config.config.quick_terminal.position = .top;
    session.loaded_config.config.quick_terminal.height_fraction = 0.45;
    {
        const f = session.quickTerminalFrames(0, 0, 1000, 800);
        try std.testing.expectEqual(@as(f64, 440), f.shown_y); // top: vf_h - h = 800-360
        try std.testing.expectEqual(@as(u32, 0), f.is_centered);
    }
    // 설정 GUI가 하듯 같은 세션에서 position을 순환(top→bottom)하고 두께를 바꾼다.
    try std.testing.expect(config_mod.schema.cycleEnum(&session.loaded_config.config, "quick-terminal.position", 1));
    try std.testing.expect(config_mod.schema.setNumber(&session.loaded_config.config, "quick-terminal.height", 0.6));
    {
        // 재생성 없이 새 위치·두께가 바로 반영된다(라이브).
        const f = session.quickTerminalFrames(0, 0, 1000, 800);
        try std.testing.expectEqual(@as(f64, 0), f.shown_y); // bottom: 하단에 붙음
        try std.testing.expectEqual(@as(f64, 480), f.shown_h); // 800 * 0.6
        try std.testing.expectEqual(@as(f64, -480), f.hidden_y); // 아래로 빠짐
    }
    // config 스칼라(auto_hide/chrome/position)도 라이브: 바꾸면 다음 조회에 그대로 반영.
    session.loaded_config.config.quick_terminal.auto_hide = false;
    session.loaded_config.config.quick_terminal.chrome = .minimal;
    const cfg = settings_ops.quickTerminalConfig(session);
    try std.testing.expectEqual(@as(u32, 0), cfg.auto_hide);
    try std.testing.expectEqual(@as(u32, @intFromEnum(config_mod.theme.QuickTerminalChrome.minimal)), cfg.chrome);
    try std.testing.expectEqual(@as(u32, @intFromEnum(config_mod.theme.QuickTerminalPosition.bottom)), cfg.position);
}

// gridFromBacking·pointInRect·paneDropZone·halfRect 단위 test는 session/layout_math.zig로 이동(b1, 순수 기하).

// refreshCellMetrics의 단일 적용점이 호출하는 line-height·letter-spacing 산술을 못박는다(OS·CoreText 없이 곱/가산
// 검증 — 비-macOS CI에서도 돈다). 이 두 px가 grid·atlas·hit-test의 진실 소스라, 여기 곱/가산이 맞으면 나머지가 자동 정합.
test "sidebar_ops.applyFontSpacing: line-height multiplies height, letter-spacing adds to advance (scaled, saturating)" {
    // 기본값(1.0/0.0)은 base 그대로 — advance·glyph 폭 모두 base.
    {
        const r = sidebar_ops.applyFontSpacing(8, 18, 1.0, 0.0, 1000);
        try std.testing.expectEqual(@as(u32, 8), r.advance_width_px);
        try std.testing.expectEqual(@as(u32, 8), r.glyph_width_px);
        try std.testing.expectEqual(@as(u32, 18), r.height_px);
    }
    // line-height 2.0 → 높이 2배(18→36), 폭은 letter-spacing 0이라 불변.
    {
        const r = sidebar_ops.applyFontSpacing(8, 18, 2.0, 0.0, 1000);
        try std.testing.expectEqual(@as(u32, 8), r.advance_width_px);
        try std.testing.expectEqual(@as(u32, 36), r.height_px);
    }
    // line-height 1.5 → 18×1.5=27(round). letter-spacing 4pt @1x → advance +4px(8→12).
    {
        const r = sidebar_ops.applyFontSpacing(8, 18, 1.5, 4.0, 1000);
        try std.testing.expectEqual(@as(u32, 12), r.advance_width_px);
        try std.testing.expectEqual(@as(u32, 27), r.height_px);
    }
    // letter-spacing은 논리 pt × 분수 scale로 환산 — 2x(scale 2000)에서 4pt는 advance +8px(8→16). 높이는 1.0이라 불변.
    {
        const r = sidebar_ops.applyFontSpacing(8, 18, 1.0, 4.0, 2000);
        try std.testing.expectEqual(@as(u32, 16), r.advance_width_px);
        try std.testing.expectEqual(@as(u32, 18), r.height_px);
    }
    // 음수 letter-spacing → advance 좁힘(8 + (-3) = 5). round(half-away): -3.
    {
        const r = sidebar_ops.applyFontSpacing(8, 18, 1.0, -3.0, 1000);
        try std.testing.expectEqual(@as(u32, 5), r.advance_width_px);
    }
    // 큰 음수 letter-spacing이 advance를 1 미만으로 끌어내려도 1px로 saturate(0폭 grid div 폭주 방지).
    {
        const r = sidebar_ops.applyFontSpacing(8, 18, 1.0, -100.0, 1000);
        try std.testing.expectEqual(@as(u32, 1), r.advance_width_px);
    }
    // 정확히 base를 0으로 만드는 음수도 1로 saturate(8 + (-8) = 0 → 1).
    {
        const r = sidebar_ops.applyFontSpacing(8, 18, 1.0, -8.0, 1000);
        try std.testing.expectEqual(@as(u32, 1), r.advance_width_px);
    }
    // **핵심(슬롯 분리)**: 자간은 advance만 바꾸고 **글리프 비트맵 폭(glyph_width_px)은 자연폭 base 불변**이다 —
    // 음수든 양수든 큰 음수든. 이 불변식이 깨지면 음수 자간에서 slot이 좁아져 글자가 세로로 흔들리는 버그가 재발한다.
    {
        try std.testing.expectEqual(@as(u32, 8), sidebar_ops.applyFontSpacing(8, 18, 1.0, -3.0, 1000).glyph_width_px);
        try std.testing.expectEqual(@as(u32, 8), sidebar_ops.applyFontSpacing(8, 18, 1.0, 4.0, 1000).glyph_width_px);
        try std.testing.expectEqual(@as(u32, 8), sidebar_ops.applyFontSpacing(8, 18, 1.0, -100.0, 1000).glyph_width_px); // saturate 무관: 자연폭 유지
        try std.testing.expectEqual(@as(u32, 8), sidebar_ops.applyFontSpacing(8, 18, 2.0, 4.0, 2000).glyph_width_px); // line-height·scale 무관
    }
}

test "chromePointerFromMouse: kind→phase, xterm button→PointerButton, mods 비트→Mods" {
    // kind: 1=down, 2=drag→move, 3=up, 4/5=더블/트리플→down. 좌표는 그대로 통과.
    const down = AppSession.chromePointerFromMouse(1, 12.5, 34.0, 0, 0);
    try std.testing.expectEqual(chrome.input.PointerPhase.down, down.phase);
    try std.testing.expectEqual(@as(f64, 12.5), down.x_px);
    try std.testing.expectEqual(@as(f64, 34.0), down.y_px);
    try std.testing.expectEqual(chrome.input.PointerButton.left, down.button);
    try std.testing.expectEqual(chrome.input.Mods{}, down.mods);
    try std.testing.expectEqual(chrome.input.PointerPhase.move, AppSession.chromePointerFromMouse(2, 0, 0, 0, 0).phase);
    try std.testing.expectEqual(chrome.input.PointerPhase.up, AppSession.chromePointerFromMouse(3, 0, 0, 0, 0).phase);
    try std.testing.expectEqual(chrome.input.PointerPhase.down, AppSession.chromePointerFromMouse(4, 0, 0, 0, 0).phase); // 더블클릭도 down

    // button(xterm): 0=L, 2=R, 1(middle)/그 외=other.
    try std.testing.expectEqual(chrome.input.PointerButton.right, AppSession.chromePointerFromMouse(1, 0, 0, 2, 0).button);
    try std.testing.expectEqual(chrome.input.PointerButton.other, AppSession.chromePointerFromMouse(1, 0, 0, 1, 0).button);

    // mods 비트: 4=shift, 8=option, 16=control(modsBits). command는 마우스 ABI에 없어 항상 false.
    const m = AppSession.chromePointerFromMouse(1, 0, 0, 0, 4 | 8 | 16).mods;
    try std.testing.expect(m.shift and m.option and m.control and !m.command);
}

// window padding이 터미널 영역 rect(termRect)를 좌상으로 들이고 폭/높이를 2배만큼 줄이는지 고정한다 — 이 rect가
// 렌더 origin·마우스 hit-test(pxToCell)·IME·split leaf의 단일 출처라, 여기서 inset이 맞으면 그 전부가 정합한다.
test "agent_ops.classifyAgent: claude/codex 부분일치(대소문자 무시), 그 외·null=none" {
    try std.testing.expectEqual(AgentKind.claude, agent_ops.classifyAgent("claude"));
    try std.testing.expectEqual(AgentKind.claude, agent_ops.classifyAgent("Claude")); // 대소문자 무시
    try std.testing.expectEqual(AgentKind.codex, agent_ops.classifyAgent("codex"));
    try std.testing.expectEqual(AgentKind.codex, agent_ops.classifyAgent("codex-cli")); // 부분일치
    try std.testing.expectEqual(AgentKind.none, agent_ops.classifyAgent("zsh"));
    try std.testing.expectEqual(AgentKind.none, agent_ops.classifyAgent("node")); // "node"는 에이전트명 아님 — foregroundProcessNames가 argv[1]("codex")로 먼저 해소
    try std.testing.expectEqual(AgentKind.none, agent_ops.classifyAgent(null));
    try std.testing.expectEqual(AgentKind.none, agent_ops.classifyAgent(""));
    // 아이콘 코드포인트 매핑(독립 아이콘 셀에 쓰임).
    try std.testing.expectEqual(@as(u21, 0), agentSymbolCodepoint(.none));
    try std.testing.expectEqual(@as(u21, 0x2736), agentSymbolCodepoint(.claude)); // 알림용 실제 ✶
    try std.testing.expectEqual(@as(u21, 0x25C6), agentSymbolCodepoint(.codex)); // 알림용 실제 ◆
    try std.testing.expectEqual(icons.codepoint(.sparkle), agentIconCodepoint(.claude)); // 사이드바 PUA sparkle
    try std.testing.expectEqual(icons.codepoint(.diamond), agentIconCodepoint(.codex)); // 사이드바 PUA diamond
}

test "agent_ops.classifyAgentProcesses: login/shell leader를 건너뛰고 같은 foreground group의 agent를 찾는다" {
    var processes: [3]maru.pty.types.ForegroundProcessName = undefined;
    const fixtures = [_][]const u8{ "login", "zsh", "claude" };
    for (&processes, fixtures, 1..) |*process, fixture, pid| {
        process.pid = @intCast(pid);
        process.len = @intCast(fixture.len);
        @memcpy(process.bytes[0..fixture.len], fixture);
    }
    try std.testing.expectEqual(AgentKind.claude, agent_ops.classifyAgentProcesses(&processes));

    const codex = "codex";
    processes[2].len = @intCast(codex.len);
    @memcpy(processes[2].bytes[0..codex.len], codex);
    try std.testing.expectEqual(AgentKind.codex, agent_ops.classifyAgentProcesses(&processes));

    processes[2].len = 3;
    @memcpy(processes[2].bytes[0..3], "vim");
    try std.testing.expectEqual(AgentKind.none, agent_ops.classifyAgentProcesses(&processes));

    // 같은 group에 서로 다른 provider가 동시에 보이는 비정상/중첩 경로는 proc_list 순서에 따라 임의 선택하지 않는다.
    processes[1].len = 5;
    @memcpy(processes[1].bytes[0..5], "codex");
    processes[2].len = 6;
    @memcpy(processes[2].bytes[0..6], "claude");
    try std.testing.expectEqual(AgentKind.none, agent_ops.classifyAgentProcesses(&processes));
}

test "dimRgb: 색을 45%로 낮춘다(0 아님 — 글자 안 사라짐; 현재 pane grip muted에 쓰임)" {
    // 밝기 변조라 0이 아니다(깜빡임 아님). 200×45/100=90. (옛 에이전트 아이콘 펄스는 폐기 — 스피너로 대체.)
    try std.testing.expectEqual(maru.color.Rgb{ .r = 90, .g = 90, .b = 90 }, dimRgb(.{ .r = 200, .g = 200, .b = 200 }));
    try std.testing.expectEqual(maru.color.Rgb{ .r = 0, .g = 0, .b = 0 }, dimRgb(.{ .r = 0, .g = 0, .b = 0 }));
}

// running 스피너 = codex식 4칸 이퀄라이저 파형(옛 브라유 회전 dot 대체). 이 테스트가 증명하는 것:
// (1) 모든 프레임의 모든 바가 블록 글리프(▁~█)라 색칠 게이트(sidebar_ops.isAgentSpinnerCp)에 잡히고 renderer/block_glyph 합성 경로로 또렷하게 그려진다.
// (2) 위상 offset 덕에 한 프레임 안에서 바 높이가 획일적이지 않다(파도처럼 보이는 근거) — 최소 한 프레임은 서로 다른 높이를 갖는다.
// (3) advance가 파형 길이(14)로 wrap하므로 프레임이 그 범위를 넘지 않는다(u8 자연 wrap 시 파형 튐 회피).
test "spinner: 4칸 이퀄라이저 바가 전부 블록 글리프이고 위상차로 파도친다" {
    var any_varied = false;
    for (0..spinner_wave.len) |f| {
        const frame: u8 = @intCast(f);
        var prev: ?u21 = null;
        for (0..sidebar_ops.spinner_bar_count) |bar| {
            const cp = sidebar_ops.spinnerBarCp(frame, bar);
            try std.testing.expect(cp >= 0x2581 and cp <= 0x2588); // ▁~█ 범위
            try std.testing.expect(sidebar_ops.isAgentSpinnerCp(cp)); // 색칠 게이트가 잡는다
            if (prev) |p| {
                if (p != cp) any_varied = true;
            }
            prev = cp;
        }
    }
    try std.testing.expect(any_varied); // 획일적이지 않다(파형)
    // 브라유(U+280B 등)는 더 이상 스피너로 취급되지 않는다 — 게이트가 블록 전용.
    try std.testing.expect(!sidebar_ops.isAgentSpinnerCp(0x280B));
    try std.testing.expect(!sidebar_ops.isAgentSpinnerCp(sidebar_ops.spinner_block_base)); // base(U+2580, 높이 0=바 없음)는 게이트 밖 — emit 최소가 base+1이라 일치.
    // 프레임 0 = 사용자가 승인한 모양 "▁▅▇▃"(wave[0,4,8,12]=1,5,7,3). 시각 계약을 고정한다.
    try std.testing.expectEqual(@as(u21, 0x2581), sidebar_ops.spinnerBarCp(0, 0)); // ▁
    try std.testing.expectEqual(@as(u21, 0x2585), sidebar_ops.spinnerBarCp(0, 1)); // ▅
    try std.testing.expectEqual(@as(u21, 0x2587), sidebar_ops.spinnerBarCp(0, 2)); // ▇
    try std.testing.expectEqual(@as(u21, 0x2583), sidebar_ops.spinnerBarCp(0, 3)); // ▃
}

// workspaceStatusLine(탭 단위 상태줄)과 tabAgentKind(대표 종류)의 상태별 문자열/폴백을 고정한다. 1-Term 탭이라
// tabHasRunningAgent==활성 Term running이지만, running=파형 prefix / idle=✓ / none="" 폴백 규칙은 그대로 증명된다.
// (다중 pane/Term에서 백그라운드 Term이 running인 경로는 Term 생성이 무거워 앱 수동 검증 — anyAgentRunning 통합 테스트가 게이트를 커버.)
test "projectRows: group_start가 group_header row를 삽입하고 카드는 depth 1·접힘은 헤더만 (SG3b)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // 탭0에 그룹 시작 마커. group_start는 owned(destroyTab/deinit이 free) — dupe로 세팅.
    session.tabs.items[0].group_start = try allocator.dupe(u8, "frontend");

    // 펼침: [group_header{frontend, member=1}, card{tab0, depth1}].
    tab_ops.recomputeVisibleTabs(session);
    try std.testing.expectEqual(@as(usize, 2), session.sidebar_rows.items.len);
    try std.testing.expect(session.sidebar_rows.items[0] == .group_header);
    try std.testing.expectEqualStrings("frontend", session.sidebar_rows.items[0].group_header.label);
    try std.testing.expectEqual(@as(u16, 1), session.sidebar_rows.items[0].group_header.member_count);
    try std.testing.expect(session.sidebar_rows.items[1] == .card);
    try std.testing.expectEqual(@as(usize, 0), session.sidebar_rows.items[1].card.tab);
    try std.testing.expectEqual(@as(u8, 1), session.sidebar_rows.items[1].card.depth); // 그룹 안 = 들여쓰기

    // 접힘: 헤더만(카드 skip). member_count는 전체(1) 유지.
    session.tabs.items[0].group_collapsed = true;
    tab_ops.recomputeVisibleTabs(session);
    try std.testing.expectEqual(@as(usize, 1), session.sidebar_rows.items.len);
    try std.testing.expect(session.sidebar_rows.items[0].group_header.collapsed);
    try std.testing.expectEqual(@as(u16, 1), session.sidebar_rows.items[0].group_header.member_count);
}

// SG8a 동작 보존 단언(docs/plans/sidebar-groups.md §9): recomputeVisibleTabs를 projectRowsFrom(order, group_depth) 순수 코어
// 위의 얇은 래퍼로 일반화했으므로, **identity order + 라이브 group_depth**를 직접 넘긴 코어 산출이 래퍼 산출과
// byte-identical(모든 Row 태그·필드)임을 헤드리스로 고정한다 — 순수 리팩터가 옛 flat/그룹 투영을 바꾸지 않았다는 증명.
test "SG8a: projectRowsFrom(identity)가 recomputeVisibleTabs와 byte-identical row를 낸다(동작 보존)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..3) |_| _ = try tab_ops.newTab(session); // [t0, t1, t2, t3]

    // 중첩 배치: t0 최상위, t1 그룹 A(depth1, 색 지정→has_color 경로), t2 자식 그룹 B(depth2, A 안), t3 B 소속.
    session.tabs.items[1].group_start = try allocator.dupe(u8, "A");
    session.tabs.items[1].group_depth = 1;
    session.tabs.items[1].group_color = 0x336699;
    session.tabs.items[2].group_start = try allocator.dupe(u8, "B");
    session.tabs.items[2].group_depth = 2;

    // (1) 라이브 래퍼(=identity projectRowsFrom) 결과를 스냅샷.
    tab_ops.recomputeVisibleTabs(session);
    var expected: [16]chrome.components.sidebar.Row = undefined;
    const expected_len = session.sidebar_rows.items.len;
    try std.testing.expect(expected_len > 0 and expected_len <= expected.len);
    for (session.sidebar_rows.items, 0..) |row, i| expected[i] = row;

    // (2) 명시적 identity order + 라이브 group_depth로 순수 코어를 직접 호출.
    const n = session.tabs.items.len;
    const order = try allocator.alloc(usize, n);
    defer allocator.free(order);
    const gd = try allocator.alloc(u8, n);
    defer allocator.free(gd);
    for (session.tabs.items, 0..) |tab, i| {
        order[i] = i;
        gd[i] = tab.group_depth;
    }
    session.projectRowsFrom(order, gd);

    // (3) byte-identical 단언 — 태그·모든 필드가 일치.
    try std.testing.expectEqual(expected_len, session.sidebar_rows.items.len);
    for (session.sidebar_rows.items, 0..) |got, i| {
        const want = expected[i];
        try std.testing.expectEqual(std.meta.activeTag(want), std.meta.activeTag(got));
        switch (want) {
            .agent_toggle, .agent, .recovered_sessions_header, .recovered_session => try std.testing.expect(false), // 이 fixture는 목록 행을 만들지 않는다
            .card => |wc| {
                try std.testing.expectEqual(wc.tab, got.card.tab);
                try std.testing.expectEqual(wc.active, got.card.active);
                try std.testing.expectEqual(wc.depth, got.card.depth);
            },
            .group_header => |wh| {
                try std.testing.expectEqual(wh.tab, got.group_header.tab);
                try std.testing.expectEqual(wh.collapsed, got.group_header.collapsed);
                try std.testing.expectEqual(wh.member_count, got.group_header.member_count);
                try std.testing.expectEqual(wh.depth, got.group_header.depth);
                try std.testing.expectEqual(wh.has_color, got.group_header.has_color);
                try std.testing.expectEqualStrings(wh.label, got.group_header.label);
            },
        }
    }
}

// SG8a 토대 증명: 순수 코어가 **order 순열을 존중**한다(SG8b simulateDrop 고스트 프리뷰가 이 위에 선다). 뒤집힌 순열을
// 넘기면 표시 행 순서가 뒤집히되 self.tabs 원본은 불변(비커밋) — 라이브 재배치가 아니라 가상 배치임을 헤드리스로 고정.
test "SG8a: projectRowsFrom가 order 순열을 존중한다(SG8b 프리뷰 토대)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try tab_ops.newTab(session); // [t0, t1] — 둘 다 최상위 카드(그룹 없음)

    // 뒤집힌 순열 [1, 0] → 표시 순서가 뒤집힌다. 마커가 없어 group_depth는 미사용이나 위치별로 채워 넘긴다.
    const order = [_]usize{ 1, 0 };
    const gd = [_]u8{ session.tabs.items[1].group_depth, session.tabs.items[0].group_depth };
    session.projectRowsFrom(&order, &gd);
    try std.testing.expectEqual(@as(usize, 2), session.sidebar_rows.items.len);
    try std.testing.expect(session.sidebar_rows.items[0] == .card);
    try std.testing.expectEqual(@as(usize, 1), session.sidebar_rows.items[0].card.tab); // order[0]=1
    try std.testing.expectEqual(@as(usize, 0), session.sidebar_rows.items[1].card.tab); // order[1]=0
    // self.tabs 자체는 재배열되지 않았다(비커밋 가상 배치).
    try std.testing.expectEqual(@as(usize, 2), session.tabs.items.len);
}

// GP1(그룹 고정 C2 — pin-region-aware 파생 토대, docs/sidebar-groups-pinning.md §12). "고정 그룹(마커 pinned=1) + 비고정 최상위
// 카드 + 비고정 그룹" 배치를 인위로 만들어 7개 subtree-스캔 경계가 **핀 리전 경계(per-position pinned 플립)**에서 멈추는지
// 단언한다. Phase A(모든 탭 비고정=고정 그룹 0개)는 pin 리셋이 **inert**해 옛 §2.1 연속 파티션 그대로(비고정 카드가 그룹에
// 흡수·member_count 포함) — 동작 보존. Phase B(마커+멤버 pin)는 pin 플립에서 리전이 갈라져 비고정 카드가 고정 subtree에
// 안 삼켜지고(#4 tab_ops.groupSubtreeEnd·#1 pass1 depth), 고정 collapsed 뒤에도 안 숨고(#2 pass2), (N) 배지가 안 오염(#6 directCardCount)됨.
test "GP1: pin-region 경계가 7개 subtree-스캔을 리전에서 멈춘다(고정 그룹+비고정 카드 삼킴/shred/배지오염 방지) — 동작 보존" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..4) |_| _ = try tab_ops.newTab(session); // [t0..t4]

    // 배치: t0=그룹 PG 마커(depth1)·t1=PG 멤버·t2=비고정 최상위 카드·t3=그룹 UG 마커(depth1)·t4=UG 멤버.
    session.tabs.items[0].group_start = try allocator.dupe(u8, "PG");
    session.tabs.items[0].group_depth = 1;
    session.tabs.items[3].group_start = try allocator.dupe(u8, "UG");
    session.tabs.items[3].group_depth = 1;

    // ── Phase A — 고정 그룹 0개(모든 탭 비고정). pin 리셋 inert → 옛 §2.1: t2가 PG에 흡수(depth1), PG=[0,3), member=3.
    tab_ops.recomputeVisibleTabs(session);
    // rows: [gh PG, c t0 d1, c t1 d1, c t2 d1, gh UG, c t3 d1, c t4 d1] — t2가 PG 소속(연속 파티션).
    try std.testing.expectEqual(@as(usize, 7), session.sidebar_rows.items.len);
    try std.testing.expectEqual(@as(u8, 1), session.sidebar_rows.items[3].card.depth); // t2 = 그룹 안(흡수, 옛 동작)
    try std.testing.expectEqual(@as(u16, 3), session.sidebar_rows.items[0].group_header.member_count); // t0·t1·t2
    try std.testing.expectEqual(@as(usize, 3), tab_ops.groupSubtreeEnd(session, 0, null, null)); // PG subtree = [0,3)
    try std.testing.expectEqual(@as(u8, 1), tab_ops.effectiveDepthAt(session, 2, null, null)); // t2 = PG 소속
    try std.testing.expect(tab_ops.tabIsInGroup(session, session.tabs.items[2])); // 흡수됐으니 그룹 안

    // ── Phase B — 고정 그룹: PG 마커+멤버를 pin(프리픽스 [1,1,0,0,0] 유지). pin 플립(pos2)에서 리전이 갈라진다.
    session.tabs.items[0].pinned = true; // PG 마커 = 그룹 고정 권위
    session.tabs.items[1].pinned = true; // PG 멤버(정규화 캐시)
    tab_ops.recomputeVisibleTabs(session);
    // #1 pass1: t2가 고정 subtree에 안 삼켜지고 비고정 리전 최상위(depth0)로 파생.
    try std.testing.expectEqual(@as(usize, 7), session.sidebar_rows.items.len);
    try std.testing.expect(session.sidebar_rows.items[3] == .card);
    try std.testing.expectEqual(@as(usize, 2), session.sidebar_rows.items[3].card.tab); // t2
    try std.testing.expectEqual(@as(u8, 0), session.sidebar_rows.items[3].card.depth); // 비고정 리전 최상위(삼킴 방지)
    // #6 directCardCount: (N) 배지가 비고정 카드로 오염 안 됨(PG 직접 카드 = t0·t1 = 2).
    try std.testing.expectEqual(@as(u16, 2), session.sidebar_rows.items[0].group_header.member_count);
    // #4 tab_ops.groupSubtreeEnd: 고정 PG subtree가 pin 경계(pos2)에서 끝난다.
    try std.testing.expectEqual(@as(usize, 2), tab_ops.groupSubtreeEnd(session, 0, null, null));
    try std.testing.expectEqual(@as(usize, 5), tab_ops.groupSubtreeEnd(session, 3, null, null)); // 비고정 UG subtree = [3,5)
    // #3 tab_ops.effectiveDepthAt: t2는 비고정 리전 최상위(0), 리전별로 정확.
    try std.testing.expectEqual(@as(u8, 0), tab_ops.effectiveDepthAt(session, 2, null, null));
    try std.testing.expectEqual(@as(u8, 1), tab_ops.effectiveDepthAt(session, 0, null, null)); // 고정 PG 마커
    try std.testing.expectEqual(@as(u8, 1), tab_ops.effectiveDepthAt(session, 3, null, null)); // 비고정 UG 마커
    // 리전 국소화된 소속 판정: 비고정 최상위 t2=밖, 비고정 그룹 멤버 t4=안, 고정 그룹 멤버 t1=안.
    try std.testing.expect(!tab_ops.tabIsInGroup(session, session.tabs.items[2]));
    try std.testing.expect(tab_ops.tabIsInGroup(session, session.tabs.items[4]));
    try std.testing.expect(tab_ops.tabIsInGroup(session, session.tabs.items[1]));

    // #2 pass2: 고정 PG를 접어도 그 뒤 비고정 t2가 접힘을 상속받아 숨지(shred) 않는다.
    session.tabs.items[0].group_collapsed = true;
    tab_ops.recomputeVisibleTabs(session);
    // rows: [gh PG(▸,2), c t2 d0, gh UG, c t3 d1, c t4 d1] — 고정 멤버(t0·t1)는 숨고 t2는 남는다.
    try std.testing.expectEqual(@as(usize, 5), session.sidebar_rows.items.len);
    try std.testing.expect(session.sidebar_rows.items[0].group_header.collapsed);
    try std.testing.expect(session.sidebar_rows.items[1] == .card);
    try std.testing.expectEqual(@as(usize, 2), session.sidebar_rows.items[1].card.tab); // t2 안 사라짐(shred 방지)
    try std.testing.expectEqual(@as(u8, 0), session.sidebar_rows.items[1].card.depth);
}

// SR1(§2.1 재설계 — top_level 저장·파생 토대, docs/sidebar-groups-top-level.md §14). `top_level` 카드가 한 핀 리전 안에서
// **최상위(depth 0)로 복귀**하는 리딩 break 신호임을 7 파생 경계에서 헤드리스로 고정한다: (#1 pass1 depth·#2 pass2
// cstack shred 방지·#3 tab_ops.effectiveDepthAt·#4 tab_ops.groupSubtreeEnd·#5 subtreeHasMatch·#6 directCardCount 배지·#7
// ghostOverlapsSubtree) + tab_ops.enclosingGroupMarkerIndex 상향 클램프·tabIsInGroup 정확. 배치 [A(마커), a1, TOP(top_level),
// B(마커), b1]: TOP은 A subtree를 끊고 depth 0으로 파생되며, 뒤 B는 빈 스택에서 형제 top-level 그룹으로 시작한다.
test "SR1: top_level이 7 파생 경계에서 최상위 복귀 서브파티션을 만든다(§2.1 재설계 §14)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..4) |_| _ = try tab_ops.newTab(session); // [t0..t4]

    // 배치: t0=그룹 A 마커(depth1)·t1=A 멤버·t2=top_level 최상위 복귀 카드·t3=그룹 B 마커(depth1)·t4=B 멤버.
    session.tabs.items[0].group_start = try allocator.dupe(u8, "A");
    session.tabs.items[0].group_depth = 1;
    session.tabs.items[2].top_level = true;
    session.tabs.items[3].group_start = try allocator.dupe(u8, "B");
    session.tabs.items[3].group_depth = 1;

    // #1 pass1 depth — rows: [gh A, c t0 d1, c t1 d1, c t2 d0, gh B, c t3 d1, c t4 d1]. TOP이 A를 끊어 depth 0,
    // B는 빈 스택에서 형제 top-level 그룹(depth1)으로 시작한다.
    tab_ops.recomputeVisibleTabs(session);
    try std.testing.expectEqual(@as(usize, 7), session.sidebar_rows.items.len);
    try std.testing.expect(session.sidebar_rows.items[0] == .group_header);
    try std.testing.expectEqual(@as(u8, 1), session.sidebar_rows.items[1].card.depth); // t0 = A 마커 카드
    try std.testing.expectEqual(@as(u8, 1), session.sidebar_rows.items[2].card.depth); // t1 = A 멤버
    try std.testing.expectEqual(@as(usize, 2), session.sidebar_rows.items[3].card.tab); // t2
    try std.testing.expectEqual(@as(u8, 0), session.sidebar_rows.items[3].card.depth); // TOP = 최상위 복귀 depth0
    try std.testing.expect(session.sidebar_rows.items[4] == .group_header); // B 헤더(형제 top-level 그룹)
    try std.testing.expectEqual(@as(u8, 1), session.sidebar_rows.items[5].card.depth); // t3 = B 마커 카드(depth1)
    try std.testing.expectEqual(@as(u8, 1), session.sidebar_rows.items[6].card.depth); // t4 = B 멤버
    // #6 directCardCount — A 배지 = 직접 카드 2(t0·t1), TOP은 subtree 밖이라 안 세짐. B 배지 = 2(t3·t4).
    try std.testing.expectEqual(@as(u16, 2), session.sidebar_rows.items[0].group_header.member_count);
    try std.testing.expectEqual(@as(u16, 2), session.sidebar_rows.items[4].group_header.member_count);

    // #3 tab_ops.effectiveDepthAt — TOP은 최상위(0), 마커는 각 1.
    try std.testing.expectEqual(@as(u8, 0), tab_ops.effectiveDepthAt(session, 2, null, null)); // TOP
    try std.testing.expectEqual(@as(u8, 1), tab_ops.effectiveDepthAt(session, 0, null, null)); // A 마커
    try std.testing.expectEqual(@as(u8, 1), tab_ops.effectiveDepthAt(session, 3, null, null)); // B 마커(형제 top-level)
    // #4 tab_ops.groupSubtreeEnd — A subtree가 top_level에서 끊긴다(=[0,2), TOP 미포함). B subtree=[3,5).
    try std.testing.expectEqual(@as(usize, 2), tab_ops.groupSubtreeEnd(session, 0, null, null));
    try std.testing.expectEqual(@as(usize, 5), tab_ops.groupSubtreeEnd(session, 3, null, null));

    // tab_ops.enclosingGroupMarkerIndex 상향 클램프 — TOP은 그룹 밖(null), TOP 뒤 sticky 카드도 top카드에 닿아 밖. 멤버는 마커로.
    try std.testing.expect(tab_ops.enclosingGroupMarkerIndex(session, 2) == null); // TOP = 최상위(그룹 밖)
    try std.testing.expectEqual(@as(usize, 0), tab_ops.enclosingGroupMarkerIndex(session, 1).?); // t1 = A 소속
    try std.testing.expectEqual(@as(usize, 3), tab_ops.enclosingGroupMarkerIndex(session, 4).?); // t4 = B 소속
    // tabIsInGroup 정확 — TOP은 밖(옛 "첫 마커 이후" 판정은 오판했음), 멤버는 안.
    try std.testing.expect(!tab_ops.tabIsInGroup(session, session.tabs.items[2])); // TOP = 밖
    try std.testing.expect(tab_ops.tabIsInGroup(session, session.tabs.items[1])); // A 멤버 = 안
    try std.testing.expect(tab_ops.tabIsInGroup(session, session.tabs.items[4])); // B 멤버 = 안

    // #5 subtreeHasMatch — 순수 함수 직접 호출(order=identity, depth 위 파생 고정값). A subtree [0,2)는 TOP을 안 본다.
    const order = [_]usize{ 0, 1, 2, 3, 4 };
    const depth = [_]u8{ 1, 1, 0, 1, 1 };
    const only_top = [_]bool{ false, false, true, false, false }; // TOP만 매치
    try std.testing.expect(!session.subtreeHasMatch(&order, 0, 1, &depth, &only_top, null)); // A subtree엔 TOP이 없음(top_level break; null=라이브 tab.top_level)
    const only_a1 = [_]bool{ false, true, false, false, false }; // a1만 매치
    try std.testing.expect(session.subtreeHasMatch(&order, 0, 1, &depth, &only_a1, null)); // A subtree엔 a1이 있음

    // #7 ghostOverlapsSubtree — 순수 함수 직접 호출. A subtree [0,2)는 top_level에서 끊겨 TOP 뒤(pos3~4) 고스트와 안 겹친다.
    try std.testing.expect(!session.ghostOverlapsSubtree(&order, &depth, 0, 1, .{ .ghost_lo = 3, .ghost_hi = 4 }, null)); // B쪽 고스트 ∉ A
    try std.testing.expect(session.ghostOverlapsSubtree(&order, &depth, 0, 1, .{ .ghost_lo = 1, .ghost_hi = 2 }, null)); // a1 위치 고스트 ∈ A

    // #2 pass2 cstack — A를 접어도 그 뒤 top_level TOP이 접힘을 상속받아 숨지(shred) 않는다.
    session.tabs.items[0].group_collapsed = true;
    tab_ops.recomputeVisibleTabs(session);
    // rows: [gh A(▸,2), c TOP d0, gh B, c t3 d1, c t4 d1] — A 멤버(t0·t1)는 숨고 TOP은 남는다.
    try std.testing.expectEqual(@as(usize, 5), session.sidebar_rows.items.len);
    try std.testing.expect(session.sidebar_rows.items[0].group_header.collapsed);
    try std.testing.expect(session.sidebar_rows.items[1] == .card);
    try std.testing.expectEqual(@as(usize, 2), session.sidebar_rows.items[1].card.tab); // TOP 안 사라짐(shred 방지)
    try std.testing.expectEqual(@as(u8, 0), session.sidebar_rows.items[1].card.depth);
}

// SR2(§2.1 재설계 §14 + code-review finding #3 — normalizePinnedFromGroups·tab_ops.pinBoundariesAlignGroups top_level 인식). top_level은
// subtree 끝을 하드 break해 top카드를 그룹 밖으로 두되, **재기록은 suffix-exclusion(pin 경계 존중)**으로 한다: 마커 pin과 다른
// pin이 subtree 끝까지 이어지는 꼬리(=다음 핀 리전의 genuine 비고정 카드)는 top_level 경계 앞이라도 **안 흡수**한다(finding #3:
// 옛 exact-full-rewrite가 pin flip을 넘어 비고정 카드를 고정 오염·persist시켰다). 사이에 낀 desync(마커 pin이 뒤에서 재등장 =
// 같은 리전 내 샌드위치)는 여전히 흡수(치유 유지). 아래 (a·c·e)=꼬리 비흡수·(b)=샌드위치 흡수+align 검출·(d)=byte-identical.
test "SR2(a·c·e): normalize top_level suffix-exclusion — pin-경계 꼬리 비흡수(finding #3)·TOP 안 흡수·idempotent·pinned top_level 통과" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..3) |_| _ = try tab_ops.newTab(session); // [t0..t3]

    // 배치: [A(pin1,마커), x(pin0 비고정 꼬리), TOP(top_level,pin0), a2(pin1)]. 고정 그룹 A 뒤에 비고정 카드 x가 오고 그 뒤
    // top_level 최상위 복귀 카드 TOP(pin0)·독립 카드 a2(pin1). x는 마커와 다른 pin이 subtree 끝(TOP)까지 이어지는 **꼬리**라
    // 다음 핀 리전의 genuine 비고정 카드다 — suffix-exclusion이 **안 흡수**한다(finding #3: pin flip 넘는 재기록=고정 오염 방지).
    // TOP 자신은 e 밖(top_level 하드 break)이라 절대 안 흡수.
    session.tabs.items[0].group_start = try allocator.dupe(u8, "A");
    session.tabs.items[0].group_depth = 1;
    session.tabs.items[0].pinned = true; // 마커 = 그룹 고정 권위
    session.tabs.items[1].pinned = false; // x = 비고정 꼬리(finding #3 — pin flip 넘어 재기록 금지, 0 유지돼야)
    session.tabs.items[2].top_level = true;
    session.tabs.items[2].pinned = false; // TOP — top_level 하드 break로 subtree 밖(0 유지)
    session.tabs.items[3].pinned = true; // a2 — subtree 밖 독립 카드(불변)

    // (a) 꼬리 비흡수 + TOP 안 흡수(finding #3 — revert하면 x.pinned=1로 실패).
    session.normalizePinnedFromGroups();
    try std.testing.expect(!session.tabs.items[1].pinned); // x: 0 유지(pin 경계 넘는 꼬리 비흡수 = 고정 오염 방지)
    try std.testing.expect(!session.tabs.items[2].pinned); // TOP: 0 유지(top_level 하드 break — subtree 밖)
    try std.testing.expect(session.tabs.items[2].top_level); // top_level 필드 불변
    try std.testing.expect(session.tabs.items[3].pinned); // a2: 불변
    try std.testing.expect(session.tabs.items[0].pinned); // 마커 권위 불변

    // (c) idempotent — 2회 normalize 고정점, top_level 필드 불변, align canonical 통과.
    session.normalizePinnedFromGroups();
    try std.testing.expect(!session.tabs.items[1].pinned);
    try std.testing.expect(!session.tabs.items[2].pinned);
    try std.testing.expect(session.tabs.items[2].top_level);
    try std.testing.expect(tab_ops.pinBoundariesAlignGroups(session)); // 비고정 꼬리는 위반 아님(pin 경계 존중)

    // (e) pinned × top_level 정합 — TOP을 고정(pin1)으로 승격(고정 리전 안 top_level 서브파티션). normalize/align 통과.
    session.tabs.items[2].pinned = true; // TOP now pinned top_level 카드(pinned=1·top_level=1)
    session.normalizePinnedFromGroups();
    try std.testing.expect(session.tabs.items[2].pinned); // pinned top_level 카드 불변(마커 아니라 재기록 대상 아님)
    try std.testing.expect(session.tabs.items[2].top_level); // top_level 필드 불변
    try std.testing.expect(!session.tabs.items[1].pinned); // x 여전히 0(비흡수)
    try std.testing.expect(tab_ops.pinBoundariesAlignGroups(session)); // pinned×top_level 정합 통과
}

test "SR2(b): normalize/align 샌드위치 desync 흡수 유지(같은 리전 내) — top_level 앞 진짜 멤버 desync는 치유·align 검출" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..3) |_| _ = try tab_ops.newTab(session); // [t0..t3]

    // 배치: [A(pin1,마커), a1(pin0 샌드위치 desync), a2(pin1), TOP(top_level,pin0)]. top_level TOP이 A subtree를 [0,3)로 하드 끊고,
    // a1(pin0)은 그 안에서 마커 pin(1)이 a2에서 **재등장**하는 샌드위치 desync = 진짜 멤버(같은 리전 내)라 흡수돼야 한다. a1이
    // subtree 중간을 자르므로 align은 I3 위반으로 검출한다(finding #3 후에도 샌드위치 흡수·검출은 유지 — 꼬리 배제만 pin 경계 존중).
    session.tabs.items[0].group_start = try allocator.dupe(u8, "A");
    session.tabs.items[0].group_depth = 1;
    session.tabs.items[0].pinned = true;
    session.tabs.items[1].pinned = false; // a1 DESYNC(샌드위치 — a2에서 마커 pin 재등장 → 진짜 멤버, 흡수돼야)
    session.tabs.items[2].pinned = true; // a2 = 마커 pin 재등장(last_match)
    session.tabs.items[3].top_level = true;
    session.tabs.items[3].pinned = false; // TOP = top_level 하드 break(subtree 밖)

    try std.testing.expect(!tab_ops.pinBoundariesAlignGroups(session)); // ★ 샌드위치 desync가 subtree 중간 자름 = I3 위반 검출

    // normalize suffix-exclusion이 [1, last_match=a2] 전량을 마커 pin1로 재기록 → a1 흡수. TOP은 e 밖(top_level 하드 break).
    session.normalizePinnedFromGroups();
    try std.testing.expect(session.tabs.items[1].pinned); // a1: 0→1 샌드위치 흡수(같은 리전 내 치유 유지)
    try std.testing.expect(session.tabs.items[2].pinned); // a2: 1 유지
    try std.testing.expect(!session.tabs.items[3].pinned); // TOP: 0 유지(top_level 하드 break)
    try std.testing.expect(session.tabs.items[3].top_level); // top_level 필드 불변
    try std.testing.expect(tab_ops.pinBoundariesAlignGroups(session)); // 흡수 후 정렬 복귀
}

test "SR2(d): top_level 0개 byte-identical — suffix-exclusion 꼬리 배제·샌드위치 흡수 동일(회귀 0)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..3) |_| _ = try tab_ops.newTab(session); // [t0..t3]

    // top_level **0개**(전부 false) 배치로 기존 suffix-exclusion과 동일함을 고정한다: [G(pin1,마커), g1(pin0 샌드위치 desync),
    // g2(pin1), C(pin0 꼬리 top카드)]. suffix-exclusion은 g1을 흡수(마커 pin이 g2에서 재등장 → last_match=g2)하되 꼬리 C는
    // 배제(다음 리전 genuine top카드, 위치 파생). hard_end never-true라 exact-full-rewrite 분기가 안 타 byte-identical.
    session.tabs.items[0].group_start = try allocator.dupe(u8, "G");
    session.tabs.items[0].group_depth = 1;
    session.tabs.items[0].pinned = true;
    session.tabs.items[1].pinned = false; // g1 샌드위치 desync(흡수돼야)
    session.tabs.items[2].pinned = true; // g2 = 마커 pin 재등장 → last_match
    session.tabs.items[3].pinned = false; // C = 꼬리 top카드(top_level 없음, 위치 파생) → 배제돼야

    session.normalizePinnedFromGroups();
    try std.testing.expect(session.tabs.items[1].pinned); // g1: 0→1 샌드위치 흡수(suffix-exclusion)
    try std.testing.expect(session.tabs.items[2].pinned); // g2: 1 유지
    try std.testing.expect(!session.tabs.items[3].pinned); // C: 0 유지(꼬리 배제 — top_level 없이 위치 파생, byte-identical)
    for (session.tabs.items) |t| try std.testing.expect(!t.top_level); // SR2가 top_level 필드를 안 건드림
}

// CR(code-review §2.1 경계 유지 회귀) — §2.1 재설계가 top_level 경계 플래그를 기존 mutation/render 경로에서 유지 안 한 6건.
// 각 테스트는 finding을 revert하면 실패한다("revert-fail"). #3은 위 SR2(a)가 커버(pin-경계 꼬리 비흡수).

test "CR#1: inheritGroupMarker leaf-only — 단일 카드 그룹 마커 닫기 시 다음 top카드로 승계 안 함(그룹 소멸)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..2) |_| _ = try tab_ops.newTab(session); // [t0..t2]

    // 단일 카드 그룹 A = [t0(마커)] — 뒤 TOP(top_level)이 subtree를 하드 끊어 A는 마커뿐. z는 TOP의 sticky follower.
    session.tabs.items[0].group_start = try allocator.dupe(u8, "A");
    session.tabs.items[0].group_depth = 1;
    session.tabs.items[1].top_level = true; // TOP = 그룹 밖 최상위 복귀 개시
    const top = session.tabs.items[1];
    try std.testing.expectEqual(@as(usize, 1), tab_ops.groupSubtreeEnd(session, 0, null, null)); // A={t0}(단일 카드)

    // 마커 t0를 닫는다 → inheritGroupMarker가 TOP(top_level)로 승계하면 leaf-only 위반(top카드가 그룹 헤더). 승계 안 함 → 그룹 소멸.
    tab_ops.closeTab(session, 0);
    try std.testing.expectEqual(@as(usize, 2), session.tabs.items.len);
    try std.testing.expectEqual(top, session.tabs.items[0]); // TOP이 새 index0
    try std.testing.expect(top.group_start == null); // ★ TOP은 마커가 안 됨(승계 거부 — revert하면 group_start!=null로 실패)
    try std.testing.expect(top.top_level); // top_level 유지
    try std.testing.expect(!tab_ops.tabIsInGroup(session, top)); // 그룹 밖
}

test "CR#2: top카드 제거/이동이 경계를 다음 sticky follower에 재확립 — follower 안 흡수(닫기·드래그)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    // (닫기) [A(마커,d1), a1, TOP(top_level), f] — TOP 닫으면 f가 앞 그룹 A에 흡수되면 안 된다(경계 재확립).
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..3) |_| _ = try tab_ops.newTab(session); // [t0..t3]
    session.tabs.items[0].group_start = try allocator.dupe(u8, "A");
    session.tabs.items[0].group_depth = 1;
    session.tabs.items[2].top_level = true; // TOP
    const f = session.tabs.items[3];
    try std.testing.expect(!tab_ops.tabIsInGroup(session, f)); // 사전: f는 TOP sticky follower(그룹 밖)

    tab_ops.closeTab(session, 2); // TOP 닫기
    try std.testing.expectEqual(@as(usize, 3), session.tabs.items.len);
    try std.testing.expectEqual(f, session.tabs.items[2]); // f가 index2로 당겨짐
    try std.testing.expect(f.top_level); // ★ 경계 재확립(revert하면 false)
    try std.testing.expect(!tab_ops.tabIsInGroup(session, f)); // ★ f 안 흡수(revert하면 A에 흡수돼 true)
    try std.testing.expectEqual(@as(usize, 2), tab_ops.groupSubtreeEnd(session, 0, null, null)); // A=[0,2), f 밖

    // (드래그) [A(마커,d1), a1, TOP(top_level), f] — TOP을 f 뒤로 드래그. commit=프리뷰 등가(expectCardDropTopLevelEquivalent).
    const s2 = try allocator.create(AppSession);
    defer allocator.destroy(s2);
    try s2.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer s2.deinit();
    inline for (0..3) |_| _ = try tab_ops.newTab(s2); // [t0..t3]
    s2.tabs.items[0].group_start = try allocator.dupe(u8, "A");
    s2.tabs.items[0].group_depth = 1;
    s2.tabs.items[2].top_level = true; // TOP
    const f2 = s2.tabs.items[3];
    // TOP(origin=2)을 index3(f 뒤)으로 이동 — origin이 빠져도 f가 앞 그룹에 흡수되면 안 된다. 등가 헬퍼가 프리뷰=확정도 검증.
    try expectCardDropTopLevelEquivalent(s2, 2, .{ .card = .{ .target_tab = 3, .top_level = false } });
    var f2_idx: usize = 99;
    for (s2.tabs.items, 0..) |t, i| if (t == f2) {
        f2_idx = i;
    };
    try std.testing.expectEqual(@as(usize, 2), f2_idx); // [A, a1, f, TOP] — f가 index2
    try std.testing.expect(f2.top_level); // ★ 드래그 경계 재확립(revert하면 false)
    try std.testing.expect(!tab_ops.tabIsInGroup(s2, f2)); // ★ f 안 흡수
    try std.testing.expectEqual(@as(usize, 2), tab_ops.groupSubtreeEnd(s2, 0, null, null)); // A=[0,2)
}

test "CR#2(tab_ops.togglePin): top_level 카드 pin이 경계를 follower에 재확립 — follower 앞 그룹 흡수 안 됨([3])" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
