test "code-review #6: accent 색 top_level 경계 리셋 — 색 그룹 뒤 top카드는 그룹 색 막대 안 받음" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli); // rich 메트릭(막대 폭>0)
    _ = try tab_ops.newTab(session); // [t0, t1]

    // 그룹 색 막대 개수를 센다 — 마커 자기 카드는 항상 그룹 색을 받으므로(그룹의 일부), top카드가 색을 받는지는 **개수**로 가른다.
    const countBar = struct {
        fn run(s: *const AppSession, fill: u32) usize {
            var n: usize = 0;
            for (s.gpu_quads.items) |q| if (q.fill_color0 == fill) {
                n += 1;
            };
            return n;
        }
    }.run;
    const group_bar = sidebar_ops.packStraightRgbU32(0x4A7BC4, 0xFF); // 그룹 색 막대(불투명) — SG5-2와 동일 팔레트

    // 색 그룹 A = [t0(마커, 파랑), t1(멤버)] — 마커 자기 카드 + 멤버 t1 = 그룹 색 막대 2개(색 렌더 sanity).
    session.tabs.items[0].group_start = try allocator.dupe(u8, "A");
    session.tabs.items[0].group_depth = 1;
    session.tabs.items[0].group_color = 0x4A7BC4;
    sidebar_ops.rebuildSidebar(session) catch {};
    try std.testing.expectEqual(@as(usize, 2), countBar(session, group_bar)); // 마커 카드 + 멤버 t1 = 2개(색 렌더 확인)

    // t1을 top_level(그룹 밖 최상위 복귀)로 → current_group_color를 리셋해야 하므로 t1은 그룹 색을 잃는다. 마커 자기 카드만 남아 1개.
    session.tabs.items[1].top_level = true;
    sidebar_ops.rebuildSidebar(session) catch {};
    try std.testing.expectEqual(@as(usize, 1), countBar(session, group_bar)); // ★ 마커 카드만(revert하면 t1도 상속 = 2개로 실패)
}

// SR3(§2.1 재설계 §14.5 — createGroup write "선택 탭만 그룹" + promote-in-place). 프로덕션 createGroup은 이제 마커 뒤 첫 탭에
// top_level:=true를 써 그룹을 **선택 탭만**으로 끊고(정책 b — 뒤 탭들 promote), 마커 승격 시 그 카드의 top_level을 clear한다
// (leaf-only §13.8). 아래 (a)선택-탭-만·(b)엣지·(c)promote-in-place·(d)inline depth 리셋·(e)흡수 변형 byte-identical을 고정한다.
test "SR3(a): createGroup 선택 탭만 그룹 — 마커 뒤 첫 탭 top_level write·뒤 탭 promote·흡수 안 됨(§14.5 요구1)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..3) |_| _ = try tab_ops.newTab(session); // [t0..t3]

    // createGroup(t1) in [t0,t1,t2,t3] → t1이 마커·그룹 첫 멤버, 마커 뒤 첫 탭 t2에 top_level write. t3은 top_level 플래그가
    // 없어도 sticky top-level run(t2가 스택을 비움)이라 자동 최상위 → 그룹은 {t1}만.
    tab_ops.createGroupForTab(session, session.tabs.items[1]);
    try std.testing.expect(session.tabs.items[1].group_start != null); // t1 = 마커
    try std.testing.expect(!session.tabs.items[1].top_level); // 마커는 top_level 금지(leaf-only) — 원래 false라 no-op
    try std.testing.expect(session.tabs.items[2].top_level); // ★ 마커 뒤 첫 탭에 top_level write(선택 탭만 그룹)
    try std.testing.expect(!session.tabs.items[3].top_level); // t3은 플래그 없음 — sticky 파생으로만 최상위(첫 탭에만 write)
    try std.testing.expect(!session.tabs.items[0].top_level); // t0은 마커 앞 최상위 카드(무변화)

    // 파생: 그룹={t1}. tab_ops.groupSubtreeEnd(1)=2(t1만), t2·t3은 depth0 최상위·enclosing null·그룹 밖.
    try std.testing.expectEqual(@as(usize, 2), tab_ops.groupSubtreeEnd(session, 1, null, null)); // A subtree=[1,2) — t2 흡수 안 됨
    try std.testing.expectEqual(@as(u8, 1), tab_ops.effectiveDepthAt(session, 1, null, null)); // t1 마커 depth1
    try std.testing.expectEqual(@as(u8, 0), tab_ops.effectiveDepthAt(session, 2, null, null)); // t2 = 최상위 복귀 depth0
    try std.testing.expectEqual(@as(u8, 0), tab_ops.effectiveDepthAt(session, 3, null, null)); // t3 = sticky top-level depth0
    try std.testing.expect(tab_ops.enclosingGroupMarkerIndex(session, 2) == null); // t2 = 그룹 밖
    try std.testing.expect(tab_ops.enclosingGroupMarkerIndex(session, 3) == null); // t3 = 그룹 밖(sticky — t2 top_level에 닿아 null)
    try std.testing.expect(!tab_ops.tabIsInGroup(session, session.tabs.items[2])); // t2 흡수 안 됨
    try std.testing.expect(!tab_ops.tabIsInGroup(session, session.tabs.items[3])); // t3도 최상위
    try std.testing.expect(tab_ops.tabIsInGroup(session, session.tabs.items[1])); // 마커는 자기 그룹 안

    // 렌더: rows=[c t0, gh A(member_count=1), c t1, c t2, c t3]. 배지는 마커+자기카드 1개만(t2 흡수 안 됨).
    tab_ops.recomputeVisibleTabs(session);
    try std.testing.expectEqual(@as(usize, 5), session.sidebar_rows.items.len);
    try std.testing.expect(session.sidebar_rows.items[1] == .group_header);
    try std.testing.expectEqual(@as(u16, 1), session.sidebar_rows.items[1].group_header.member_count); // ★ 그룹={t1} 배지 1
}

test "SR3(b): createGroup top_level write 엣지 — 다음 마커·리스트 끝·다른 핀 리전 안전 skip + 형제 그룹 정합" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..3) |_| _ = try tab_ops.newTab(session); // [t0..t3]

    // 엣지(1) 다음이 이미 마커(연속 그룹): createGroup(t2)이 먼저 t2를 마커로(다음 t3에 top_level). 그다음 createGroup(t1) —
    // t1의 다음 탭 t2가 **마커**라 top_level write skip(마커엔 top_level 금지·그 자체가 경계). t2.top_level은 false 유지.
    tab_ops.createGroupForTab(session, session.tabs.items[2]); // t2 마커, t3.top_level=true
    try std.testing.expect(session.tabs.items[3].top_level);
    tab_ops.createGroupForTab(session, session.tabs.items[1]); // 다음 t2=마커 → write skip
    try std.testing.expect(session.tabs.items[1].group_start != null);
    try std.testing.expect(!session.tabs.items[2].top_level); // ★ 마커엔 top_level 안 씀(엣지 skip)
    try std.testing.expectEqual(@as(usize, 2), tab_ops.groupSubtreeEnd(session, 1, null, null)); // {t1}만(t2 마커가 형제로 끊음)

    // 엣지(2) 리스트 끝(다음 탭 없음): 새 세션 [u0,u1]에서 createGroup(u1) — u1이 마지막이라 write 대상 없음, 안전(그룹={u1}).
    const s2 = try allocator.create(AppSession);
    defer allocator.destroy(s2);
    try s2.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer s2.deinit();
    _ = try tab_ops.newTab(s2); // [u0, u1]
    tab_ops.createGroupForTab(s2, s2.tabs.items[1]); // 마지막 탭 → 다음 없음
    try std.testing.expect(s2.tabs.items[1].group_start != null);
    try std.testing.expectEqual(@as(usize, 2), tab_ops.groupSubtreeEnd(s2, 1, null, null)); // {u1}(len까지, 안전)

    // 엣지(3) 다음이 다른 핀 리전: [p0(pin),p1(pin),c0,c1]에서 createGroup(p1) — 다음 c0는 비고정(다른 리전)이라 write skip
    // (핀 경계가 이미 subtree를 끊음). c0.top_level false 유지. 그룹={p1}.
    const s3 = try allocator.create(AppSession);
    defer allocator.destroy(s3);
    try s3.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer s3.deinit();
    inline for (0..3) |_| _ = try tab_ops.newTab(s3); // [p0,p1,c0,c1]
    s3.tabs.items[0].pinned = true;
    s3.tabs.items[1].pinned = true;
    tab_ops.createGroupForTab(s3, s3.tabs.items[1]); // 다음 c0=비고정(다른 리전) → write skip
    try std.testing.expect(s3.tabs.items[1].group_start != null);
    try std.testing.expect(!s3.tabs.items[2].top_level); // ★ 다른 핀 리전 카드엔 top_level 안 씀(엣지 skip)

    // 형제 그룹 정합: [w0, w1, w2, w3] 흡수 그룹 A(w0) 뒤 createSiblingGroup(w2) — w2가 형제 마커, 다음 w3에 top_level write.
    // A={w0,w1}(w2가 형제로 끊음), B={w2}(w3 promote). "선택 탭만 그룹"이 형제 경로에도 적용됨.
    const s4 = try allocator.create(AppSession);
    defer allocator.destroy(s4);
    try s4.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer s4.deinit();
    inline for (0..3) |_| _ = try tab_ops.newTab(s4); // [w0..w3]
    tab_ops.createGroupAbsorbForTab(s4, s4.tabs.items[0]); // A = [w0,w1,w2,w3] 흡수(SR3 이전 다중 멤버)
    tab_ops.createSiblingGroupForTab(s4, s4.tabs.items[2]); // w2 형제 마커(선택 탭만) → w3에 top_level write
    try std.testing.expect(s4.tabs.items[3].top_level); // ★ 형제도 다음 탭 promote
    try std.testing.expectEqual(@as(usize, 2), tab_ops.groupSubtreeEnd(s4, 0, null, null)); // A={w0,w1}
    try std.testing.expectEqual(@as(usize, 3), tab_ops.groupSubtreeEnd(s4, 2, null, null)); // B={w2}(w3 흡수 안 됨)
    try std.testing.expect(!tab_ops.tabIsInGroup(s4, s4.tabs.items[3])); // w3 최상위
}

test "SR3(c): promote-in-place — 제자리 top_level·위치·pin 불변(removeFromGroup eject flavor 대비, §14.7)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..3) |_| _ = try tab_ops.newTab(session); // [t0..t3]

    // 다중 멤버 그룹 A=[t0(마커),t1,t2,t3]을 흡수로 만든 뒤(SR4 드래그로 도달 가능한 정상 상태) 중간 멤버 t2를 promote.
    tab_ops.createGroupAbsorbForTab(session, session.tabs.items[0]);
    const t2 = session.tabs.items[2];
    try std.testing.expect(tab_ops.tabIsInGroup(session, t2)); // 승격 전 = 그룹 안
    tab_ops.promoteTabToTopLevelInPlace(session, t2);

    try std.testing.expect(t2.top_level); // ★ 제자리 top_level 세팅
    try std.testing.expectEqual(t2, session.tabs.items[2]); // ★ 위치 불변(이동 없음 — removeFromGroup의 첫마커 앞 이동과 대비)
    try std.testing.expectEqual(@as(u8, 0), tab_ops.effectiveDepthAt(session, 2, null, null)); // ★ 그룹 depth 벗어남(0)
    try std.testing.expect(tab_ops.enclosingGroupMarkerIndex(session, 2) == null); // 그룹 밖
    try std.testing.expect(!tab_ops.tabIsInGroup(session, t2)); // 그룹 밖
    try std.testing.expect(tab_ops.tabIsInGroup(session, session.tabs.items[1])); // 앞 멤버 t1은 여전히 A 안
    try std.testing.expectEqual(@as(usize, 2), tab_ops.groupSubtreeEnd(session, 0, null, null)); // A={t0,t1}(t2에서 끊김)
    try std.testing.expect(!tab_ops.tabIsInGroup(session, session.tabs.items[3])); // t3 sticky top-level(cascade — §14.1)

    // 마커 카드 promote = no-op(leaf-only §13.8 — 마커는 top_level 금지). 그룹 밖 카드도 no-op.
    tab_ops.promoteTabToTopLevelInPlace(session, session.tabs.items[0]); // 마커 t0
    try std.testing.expect(!session.tabs.items[0].top_level); // 마커엔 안 씀
    tab_ops.promoteTabToTopLevelInPlace(session, t2); // 이미 최상위(그룹 밖) → no-op(idempotent)
    try std.testing.expect(t2.top_level);

    // pin 불변(eject flavor divergence §14.7): 고정 그룹에서 promote는 pin을 유지(고정 top카드). removeFromGroup은 unpin.
    const s2 = try allocator.create(AppSession);
    defer allocator.destroy(s2);
    try s2.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer s2.deinit();
    inline for (0..3) |_| _ = try tab_ops.newTab(s2); // [t0..t3]
    tab_ops.createGroupAbsorbForTab(s2, s2.tabs.items[0]);
    for (s2.tabs.items) |t| t.pinned = true; // 고정 그룹(I1 uniform)
    s2.normalizePinnedFromGroups();
    const p2 = s2.tabs.items[2];
    tab_ops.promoteTabToTopLevelInPlace(s2, p2);
    try std.testing.expect(p2.top_level); // 제자리 승격
    try std.testing.expect(p2.pinned); // ★ pin 불변(고정 top카드 — removeFromGroup의 unpin과 대비)
    try std.testing.expect(tab_ops.pinBoundariesAlignGroups(s2)); // 고정 리전 안 top_level 정합(§14.4·§14.7 (1))
}

test "SR3(d): beginGroupForTab inline depth 리셋 — top_level 뒤 새 그룹이 그룹 depth 상속 안 함(§14.5)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..3) |_| _ = try tab_ops.newTab(session); // [t0..t3]

    // 배치: t0=그룹 A 마커(d1)·t1=A 멤버·t2=top_level 최상위 복귀 카드·t3=최상위. t3에 createGroup(.nested)을 부르면,
    // inline depth 스택이 t2의 top_level에서 리셋돼야 enclosing_depth=0 → 새 그룹 C가 depth 1(t3이 A 안이 아님). 리셋이
    // 없으면 t3이 A depth(1)를 상속해 C.group_depth=2(오중첩·persist)가 된다.
    session.tabs.items[0].group_start = try allocator.dupe(u8, "A");
    session.tabs.items[0].group_depth = 1;
    session.tabs.items[2].top_level = true;
    tab_ops.createGroupForTab(session, session.tabs.items[3]); // C 마커(t3은 마지막이라 다음 top_level write 없음)
    try std.testing.expect(session.tabs.items[3].group_start != null);
    try std.testing.expectEqual(@as(u8, 1), session.tabs.items[3].group_depth); // ★ depth1(A depth 상속 안 함 — 리셋 동작)
    try std.testing.expectEqual(@as(u8, 1), tab_ops.effectiveDepthAt(session, 3, null, null)); // 렌더 depth도 1(형제 top-level 그룹)
}

test "SR3(e): createGroupAbsorb 다중 멤버 byte-identical 재현(회귀 0) + 마커 top_level clear" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..2) |_| _ = try tab_ops.newTab(session); // [t0..t2]

    // 흡수 변형(테스트용)은 SR3 이전 동작을 재현 — createGroupAbsorb(t0) → 그룹={t0,t1,t2}(마커 뒤 전부 흡수), top_level 0개.
    tab_ops.createGroupAbsorbForTab(session, session.tabs.items[0]);
    try std.testing.expectEqual(@as(usize, 3), tab_ops.groupSubtreeEnd(session, 0, null, null)); // 전부 한 그룹(연속 파티션)
    for (session.tabs.items) |t| try std.testing.expect(!t.top_level); // 흡수 경로는 top_level를 안 씀(byte-identical)
    try std.testing.expect(tab_ops.tabIsInGroup(session, session.tabs.items[1])); // t1 흡수됨
    try std.testing.expect(tab_ops.tabIsInGroup(session, session.tabs.items[2])); // t2 흡수됨

    // 마커 top_level clear(카드→마커 전이): top_level 최상위 카드를 그룹으로 묶으면 그 top_level이 clear된다(leaf-only §13.8).
    const s2 = try allocator.create(AppSession);
    defer allocator.destroy(s2);
    try s2.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer s2.deinit();
    inline for (0..2) |_| _ = try tab_ops.newTab(s2); // [t0..t2]
    s2.tabs.items[1].top_level = true; // t1 = top_level 최상위 섬
    tab_ops.createGroupForTab(s2, s2.tabs.items[1]); // t1을 그룹 마커로 승격
    try std.testing.expect(s2.tabs.items[1].group_start != null); // 마커
    try std.testing.expect(!s2.tabs.items[1].top_level); // ★ 카드→마커 전이 시 top_level clear(마커는 leaf-only상 top_level 금지)
}

// GP2(그룹 고정 C2 — normalizePinnedFromGroups + 복원 순서 + 마커 승계, docs/sidebar-groups-pinning.md §12.5·§12.7·§12.9).
// 마커 pinned = 그룹 고정 권위, 멤버 카드 pinned = 파생 캐시. normalize가 멤버를 마커 값으로 재기록해 stablePartition이
// 그룹을 통째 옮기게 한다(정규화 누락 = shred). 아래 (a)shred방지·(b)복원순서·(c)마커승계·(d)드래그불변 4케이스.
test "GP2: normalizePinnedFromGroups가 멤버 pinned를 마커 기준 canonical화한다(desync→shred 방지) + stablePartition 통째 프리픽스" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..2) |_| _ = try tab_ops.newTab(session); // [t0..t2]

    // 고정 그룹 PG(마커 pinned=1)에 멤버 t1이 **desync pinned=0**로 손상, t2는 정상 pinned=1. 마커 권위(§12.2)상 t1도 1이어야.
    session.tabs.items[0].group_start = try allocator.dupe(u8, "PG");
    session.tabs.items[0].group_depth = 1;
    session.tabs.items[0].pinned = true; // 마커 = 그룹 고정 권위
    session.tabs.items[1].pinned = false; // 멤버 DESYNC(0 — 정규화가 1로 고쳐야)
    session.tabs.items[2].pinned = true; // 멤버 정상
    const t0 = session.tabs.items[0];
    const t1 = session.tabs.items[1];
    const t2 = session.tabs.items[2];

    // normalize 전 stablePartition을 돌리면 [1,0,1] → 고정 [t0,t2]·비고정 [t1] 순열로 t1이 뒤로 새 그룹이 찢긴다(대조 —
    // 여기선 안 돌린다). normalize를 먼저 부르면 멤버가 마커 값으로 동기돼 그런 shred가 원천 차단된다.
    session.normalizePinnedFromGroups();
    try std.testing.expect(t1.pinned); // desync 멤버 t1: 0→1(마커 권위로 canonical) — shred 방지 핵심
    try std.testing.expect(t0.pinned and t2.pinned); // 나머지 불변
    try std.testing.expect(t0.group_start != null); // 마커 pinned는 권위라 불변(재기록 대상 아님)

    // 이제 stablePartition은 전부 pinned=1이라 재배열 없음 → 그룹이 순서 그대로 통째 프리픽스로 남는다(안 찢김).
    tab_ops.stablePartitionPinned(session);
    try std.testing.expectEqual(t0, session.tabs.items[0]);
    try std.testing.expectEqual(t1, session.tabs.items[1]);
    try std.testing.expectEqual(t2, session.tabs.items[2]);
    try std.testing.expectEqual(@as(usize, 3), tab_ops.groupSubtreeEnd(session, 0, null, null)); // PG subtree=[0,3) 통째 고정
    tab_ops.recomputeVisibleTabs(session);
    try std.testing.expectEqual(@as(u16, 3), session.sidebar_rows.items[0].group_header.member_count); // t0·t1·t2 통째
}

test "GP2: 복원 순서 — 혼합 파일(멤버 pinned=1·마커=0)을 normalize→stablePartition으로 canonical화(그룹 안 찢김)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..2) |_| _ = try tab_ops.newTab(session); // [t0..t2]

    // 손상/레거시 혼합 파일 시뮬(§12.9): 비고정 그룹 UG(마커 pinned=0)인데 멤버 t1이 pinned=1로 저장됨. 마커 권위상 t1=0이어야.
    // 정규화를 안 하고 stablePartition만 돌리면(옛 복원 = 오직 (3)) [0,1,0] → t1이 프리픽스로 새 앞으로, 마커 t0는 뒤로 밀려 그룹이 찢긴다.
    session.tabs.items[0].group_start = try allocator.dupe(u8, "UG");
    session.tabs.items[0].group_depth = 1;
    session.tabs.items[0].pinned = false; // 마커 = 비고정 권위
    session.tabs.items[1].pinned = true; // 멤버 DESYNC(1 — 정규화가 0으로 고쳐야)
    session.tabs.items[2].pinned = false; // 멤버 정상
    const t0 = session.tabs.items[0];
    const t1 = session.tabs.items[1];
    const t2 = session.tabs.items[2];

    // 복원 특례 순서(applyWorkspaceWindow 삽입과 동일): (2) normalize → (3) stablePartition.
    session.normalizePinnedFromGroups();
    try std.testing.expect(!t1.pinned); // 멤버 t1: 1→0(마커 권위) — 그룹이 안 찢기게 canonical
    try std.testing.expect(!t0.pinned and !t2.pinned);
    tab_ops.stablePartitionPinned(session);
    // 전부 pinned=0이라 재배열 없음 → 마커·멤버 순서 그대로(그룹 무결).
    try std.testing.expectEqual(t0, session.tabs.items[0]);
    try std.testing.expectEqual(t1, session.tabs.items[1]);
    try std.testing.expectEqual(t2, session.tabs.items[2]);
    try std.testing.expectEqual(@as(usize, 3), tab_ops.groupSubtreeEnd(session, 0, null, null)); // UG subtree=[0,3) 무결
}

test "GP2: inheritGroupMarker pinned 승계 — 고정 그룹 마커 카드 closeTab → 승계 마커가 pinned=1 유지(그룹 고정 보존)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..2) |_| _ = try tab_ops.newTab(session); // [t0..t2]

    // 고정 그룹 PG = [t0(마커) t1 t2] 전부 pinned=1(그룹이 리스트 전체 = 승계 뒤 흡수될 후행 top-level 카드 없음).
    session.tabs.items[0].group_start = try allocator.dupe(u8, "PG");
    session.tabs.items[0].group_depth = 1;
    session.tabs.items[0].pinned = true;
    session.tabs.items[1].pinned = true;
    session.tabs.items[2].pinned = true;

    // 마커 카드 t0를 닫는다 → inheritGroupMarker가 마커(group_start/depth/**pinned**)를 다음 카드(옛 t1)로 승계.
    tab_ops.closeTab(session, 0);
    try std.testing.expectEqual(@as(usize, 2), session.tabs.items.len);
    // 새 index0(옛 t1)이 승계 마커 — group_start 존재 + pinned=1(고정 소실 방지, §12.7 보강 6).
    try std.testing.expect(session.tabs.items[0].group_start != null);
    try std.testing.expect(session.tabs.items[0].pinned); // 그룹 고정 유지
    try std.testing.expect(session.tabs.items[1].pinned); // 남은 멤버(옛 t2)도 고정 캐시 유지
    try std.testing.expectEqual(@as(usize, 2), tab_ops.groupSubtreeEnd(session, 0, null, null)); // PG=[0,2) 통째 고정
}

test "GP2: 드래그 중 불변 — sidebar_drag_preview!=null이면 normalizePinnedFromGroups가 self.tabs.pinned를 안 건드린다(SG8 게이트)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..2) |_| _ = try tab_ops.newTab(session); // [t0..t2]

    // 고정 그룹 + desync 멤버(정규화하면 바뀔 상태) — 드래그 게이트가 없으면 normalize가 t1을 바꿀 것.
    session.tabs.items[0].group_start = try allocator.dupe(u8, "PG");
    session.tabs.items[0].group_depth = 1;
    session.tabs.items[0].pinned = true;
    session.tabs.items[1].pinned = false; // desync
    session.tabs.items[2].pinned = true;
    const t1 = session.tabs.items[1];

    // 드래그 프리뷰 활성(비커밋) — self.tabs는 드래그 내내 불변이어야 한다(SG8). normalize는 이 게이트에서 즉시 return.
    session.sidebar_drag_preview = .{ .origin = 0, .origin_len = 1, .plan = .none, .cursor_y = 0, .ghost_lo = 0, .ghost_hi = 0 };
    session.normalizePinnedFromGroups();
    try std.testing.expect(!t1.pinned); // 게이트로 안 돎 → desync 그대로(self.tabs.pinned 불변 단언)

    // 프리뷰 종료 후엔 정상 정규화(게이트가 유일한 억제 원인이었음을 확인).
    session.sidebar_drag_preview = null;
    session.normalizePinnedFromGroups();
    try std.testing.expect(t1.pinned); // 이제 마커 권위로 canonical(0→1)
}

// GP3(그룹 고정 C2 — toggleGroupPin + clampGroupMoveToRegion + 개별 pin 입구 차단 + GP1/GP2 정합, §12.6·§12.7·§12.10).
// (a)tension 해소·(b)개별 pin 차단·(c)toggleGroupPin·(d)clamp 프리뷰=확정·(e)removeFromGroup unpin 선행.

test "GP3(a): tension 해소 — normalize가 고정그룹 뒤 비고정 top카드를 안 흡수(GP1 렌더 depth0 정합·idempotent)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..4) |_| _ = try tab_ops.newTab(session); // [t0..t4]

    // §12.1 약점 최상 "고정그룹 + 비고정 top카드": t0=PG(마커,pin1)·t1=PG멤버(pin1)·t2=비고정 top카드(pin0)·
    // t3=UG(마커,pin0)·t4=UG멤버(pin0). 마커=1·다음카드=0 패턴이 desync가 아니라 genuine이다(개별 pin 차단으로 desync 불가).
    session.tabs.items[0].group_start = try allocator.dupe(u8, "PG");
    session.tabs.items[0].group_depth = 1;
    session.tabs.items[0].pinned = true;
    session.tabs.items[1].pinned = true;
    session.tabs.items[3].group_start = try allocator.dupe(u8, "UG");
    session.tabs.items[3].group_depth = 1;

    session.normalizePinnedFromGroups();
    try std.testing.expect(!session.tabs.items[2].pinned); // ★ top카드 안 흡수(0 유지) — tension 해소 핵심
    try std.testing.expect(session.tabs.items[0].pinned and session.tabs.items[1].pinned); // 고정 그룹 유지
    try std.testing.expect(!session.tabs.items[3].pinned and !session.tabs.items[4].pinned); // 비고정 그룹 유지
    // GP1 per-position 파생과 정합: t2 = 비고정 리전 최상위 depth 0(안 삼켜짐), groupSubtreeEnd가 pin 경계서 끊김.
    try std.testing.expectEqual(@as(u8, 0), tab_ops.effectiveDepthAt(session, 2, null, null)); // GP1 렌더 depth0
    try std.testing.expectEqual(@as(usize, 2), tab_ops.groupSubtreeEnd(session, 0, null, null)); // PG=[0,2), t2는 밖
    // idempotent — 2회 normalize 동일(추가 흡수 없음).
    session.normalizePinnedFromGroups();
    try std.testing.expect(!session.tabs.items[2].pinned);
    try std.testing.expect(session.tabs.items[0].pinned and session.tabs.items[1].pinned);
    try std.testing.expect(!session.tabs.items[3].pinned and !session.tabs.items[4].pinned);
}

test "GP3(b)/GL2: 카드 pin 라우팅 — 마커 카드=그룹째 고정·비마커 멤버=그룹-로컬 pin·최상위=개별 전역 pin(tab_ops.cardPinRole 분기)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..2) |_| _ = try tab_ops.newTab(session); // [t0..t2]
    tab_ops.createGroupAbsorbForTab(session, session.tabs.items[0]); // t0=마커, t1·t2=위치 파생 멤버(그룹 [t0,t1,t2])

    // ── (1) **마커 카드**(t0) 우클릭 → 그룹째 고정(cardPinRole=.group). 마커는 그룹 시작이라 개별 pin이면 C2 캐시 권위
    //    (§12.2)가 깨지므로 그룹째로 위임(GP3 유지). accept → 마커+모든 멤버 통째 pinned.
    session.context_menu_target = .{ .workspace = session.tabs.items[0] };
    try std.testing.expectEqualStrings(maru.i18n.t(.ctx_group_pin), settings_ops.buildContextMenuItems(session)[ctx_menu_pin]);
    session.context_menu_target = .{ .workspace = session.tabs.items[0] };
    session.chrome_host.context_menu.selected = ctx_menu_pin;
    settings_ops.acceptContextMenu(session);
    try std.testing.expect(session.tabs.items[0].pinned and session.tabs.items[1].pinned and session.tabs.items[2].pinned);
    // 다시 열면 "그룹 고정 해제"(그룹째 토글 상태 반영). 해제 → 전부 unpinned.
    session.context_menu_target = .{ .workspace = session.tabs.items[0] };
    try std.testing.expectEqualStrings(maru.i18n.t(.ctx_group_unpin), settings_ops.buildContextMenuItems(session)[ctx_menu_pin]);
    session.context_menu_target = .{ .workspace = session.tabs.items[0] };
    session.chrome_host.context_menu.selected = ctx_menu_pin;
    settings_ops.acceptContextMenu(session);
    try std.testing.expect(!session.tabs.items[0].pinned and !session.tabs.items[1].pinned);

    // ── (2) **비마커 멤버**(t1) 우클릭 → **그룹-로컬 위치 고정**(cardPinRole=.local, GL §13 — 그룹째 위임을 되돌림).
    //    라벨은 "그룹 내 위치 고정", accept → local_pinned만 세팅되고 **전역 pinned는 불변**(그룹째 고정이 아님).
    const m1 = session.tabs.items[1];
    session.context_menu_target = .{ .workspace = m1 };
    try std.testing.expectEqualStrings(maru.i18n.t(.ctx_local_pin), settings_ops.buildContextMenuItems(session)[ctx_menu_pin]);
    session.context_menu_target = .{ .workspace = m1 };
    session.chrome_host.context_menu.selected = ctx_menu_pin;
    settings_ops.acceptContextMenu(session);
    try std.testing.expect(m1.local_pinned); // ★ 로컬 pin 세팅(그룹-로컬)
    try std.testing.expect(!session.tabs.items[0].pinned and !m1.pinned); // ★ 전역 pinned 불변(그룹째 아님)
    // 다시 열면 "그룹 내 고정 해제"(로컬 토글 상태 반영).
    session.context_menu_target = .{ .workspace = m1 };
    try std.testing.expectEqualStrings(maru.i18n.t(.ctx_local_unpin), settings_ops.buildContextMenuItems(session)[ctx_menu_pin]);

    // ── (3) **최상위**(그룹 미소속) 카드 → 개별 전역 pin(cardPinRole=.individual, tab_ops.togglePin — 현행 유지).
    tab_ops.ungroupTab(session, session.tabs.items[0]); // 그룹 풀어 전부 최상위 카드로
    const top0 = session.tabs.items[0];
    session.context_menu_target = .{ .workspace = top0 };
    try std.testing.expectEqualStrings(maru.i18n.t(.ctx_pin), settings_ops.buildContextMenuItems(session)[ctx_menu_pin]);
    session.context_menu_target = .{ .workspace = top0 };
    session.chrome_host.context_menu.selected = ctx_menu_pin;
    settings_ops.acceptContextMenu(session);
    try std.testing.expect(top0.pinned); // 개별 전역 pin
}

test "GP3(c): toggleGroupPin — 그룹 통째 고정→프리픽스 끝 이동·멤버 pin 동기, 해제→역(top카드 보존)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..3) |_| _ = try tab_ops.newTab(session); // [t0..t3]

    // [p0(고정 top카드,1), u0(비고정 top카드,0), G(마커,0), m(멤버,0)]. G를 고정하면 p0 **뒤**(프리픽스 끝)로 이동해야.
    session.tabs.items[0].pinned = true; // p0 = 고정 최상위 카드(개별 pin)
    session.tabs.items[2].group_start = try allocator.dupe(u8, "G");
    session.tabs.items[2].group_depth = 1;
    const p0 = session.tabs.items[0];
    const utop = session.tabs.items[1];
    const g = session.tabs.items[2];
    const m = session.tabs.items[3];

    tab_ops.toggleGroupPin(session, g); // 그룹째 고정
    try std.testing.expect(g.pinned and m.pinned); // 멤버 pin 동기(0→1)
    try std.testing.expect(p0.pinned and !utop.pinned); // p0 고정 유지·u0 비고정 top카드 보존(안 흡수)
    try std.testing.expectEqual(p0, session.tabs.items[0]); // 기존 고정 카드가 앞
    try std.testing.expectEqual(g, session.tabs.items[1]); // 그룹이 **프리픽스 끝**(p0 바로 뒤)에 안착
    try std.testing.expectEqual(m, session.tabs.items[2]);
    try std.testing.expectEqual(utop, session.tabs.items[3]); // 비고정 top카드는 뒤로
    try std.testing.expectEqual(@as(usize, 3), tab_ops.groupSubtreeEnd(session, 1, null, null)); // G=[1,3) 통째 고정

    tab_ops.toggleGroupPin(session, g); // 해제 = 역
    try std.testing.expect(!g.pinned and !m.pinned); // 멤버 pin 역동기(1→0)
    try std.testing.expect(p0.pinned and !utop.pinned); // p0 개별 고정은 불변(그룹 토글과 직교)
    try std.testing.expectEqual(p0, session.tabs.items[0]); // 고정 프리픽스 [0,1) 유지
    try std.testing.expectEqual(g, session.tabs.items[1]); // 그룹은 비고정 리전 시작에 남음
}

test "GP3(c2): toggleGroupPin unpin — 다른 고정 그룹 앞의 그룹을 해제해도 프리픽스 무결(경계 케이스)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..3) |_| _ = try tab_ops.newTab(session); // [t0..t3]

    // 고정 그룹 둘: PG1[0,1]·PG2[2,3] 전부 pin1. PG1(다른 고정 그룹 **앞**)을 해제 → 비고정 리전으로 나가고 PG2는 고정 프리픽스에.
    session.tabs.items[0].group_start = try allocator.dupe(u8, "PG1");
    session.tabs.items[0].group_depth = 1;
    session.tabs.items[2].group_start = try allocator.dupe(u8, "PG2");
    session.tabs.items[2].group_depth = 1;
    for (0..4) |i| session.tabs.items[i].pinned = true;
    const pg1 = session.tabs.items[0];
    const pm1 = session.tabs.items[1];
    const pg2 = session.tabs.items[2];
    const pm2 = session.tabs.items[3];

    tab_ops.toggleGroupPin(session, pg1); // PG1 해제 — tab_ops.moveGroupRange 단일 insert_before로는 못 옮기는 경계(stablePartition 정렬)
    try std.testing.expect(!pg1.pinned and !pm1.pinned); // PG1 비고정
    try std.testing.expect(pg2.pinned and pm2.pinned); // PG2 고정 유지
    // 프리픽스 무결: [PG2, pm2, PG1, pm1] = [1,1,0,0](복원식 stable 정렬로 고정이 앞·그룹 연속).
    try std.testing.expectEqual(pg2, session.tabs.items[0]);
    try std.testing.expectEqual(pm2, session.tabs.items[1]);
    try std.testing.expectEqual(pg1, session.tabs.items[2]);
    try std.testing.expectEqual(pm1, session.tabs.items[3]);
    try std.testing.expectEqual(@as(usize, 2), tab_ops.groupSubtreeEnd(session, 0, null, null)); // PG2=[0,2) 고정 통째
    try std.testing.expectEqual(@as(usize, 4), tab_ops.groupSubtreeEnd(session, 2, null, null)); // PG1=[2,4) 비고정 통째
}

test "ungroup-pin: 고정 그룹 ungroup — 그룹째 고정이 멤버에 인계 안 됨(비고정 최상위 복귀) + 비고정 그룹 무변" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..2) |_| _ = try tab_ops.newTab(session); // [t0..t2]

    // ── (a) 그룹째 고정 그룹 A={m,a1,a2}(toggleGroupPin 통째 고정, 모두 pinned=1) ungroup → 셋 다 pinned=0·최상위(enclosing null).
    tab_ops.createGroupAbsorbForTab(session, session.tabs.items[0]); // t0=마커, t1·t2 위치 파생 멤버
    const m = session.tabs.items[0];
    const a1 = session.tabs.items[1];
    const a2 = session.tabs.items[2];
    tab_ops.toggleGroupPin(session, m); // 그룹째 고정 — 마커+멤버 모두 pinned=1
    try std.testing.expect(m.pinned and a1.pinned and a2.pinned);
    tab_ops.ungroupTab(session, a1); // 멤버 a1 ungroup = enclosing 마커 m 제거(그룹 소멸)
    try std.testing.expect(m.group_start == null); // 그룹 소멸
    try std.testing.expect(!m.pinned and !a1.pinned and !a2.pinned); // ★ 그룹째 고정이 멤버에 인계 안 됨(비고정 복귀)
    try std.testing.expect(tab_ops.enclosingGroupMarkerTab(session, m) == null); // 셋 다 그룹 밖 최상위(enclosing 마커 없음)
    try std.testing.expect(tab_ops.enclosingGroupMarkerTab(session, a1) == null);
    try std.testing.expect(tab_ops.enclosingGroupMarkerTab(session, a2) == null);

    // ── (b) 비고정 그룹 ungroup → 무변(pinned=0 유지, 회귀 0). 셋 다 비고정 최상위이므로 재그룹 후 다시 푼다.
    tab_ops.createGroupAbsorbForTab(session, m); // B={m,a1,a2}(전부 비고정)
    try std.testing.expect(m.group_start != null and !m.pinned and !a1.pinned and !a2.pinned);
    tab_ops.ungroupTab(session, a2);
    try std.testing.expect(m.group_start == null);
    try std.testing.expect(!m.pinned and !a1.pinned and !a2.pinned); // 무변

    // ── (c) 로컬 pin 멤버 있던 고정 그룹 ungroup → local_pinned도 정리(+ pinned 클리어).
    tab_ops.createGroupAbsorbForTab(session, m); // C={m,a1,a2}
    tab_ops.toggleLocalPin(session, a1); // a1 그룹-로컬 pin(그룹째 고정과 직교)
    try std.testing.expect(a1.local_pinned);
    tab_ops.toggleGroupPin(session, m); // 그룹째 고정 — 로컬 pin은 고정 켜는 동안 보존
    try std.testing.expect(m.pinned and a1.pinned and a2.pinned and a1.local_pinned);
    tab_ops.ungroupTab(session, m); // 마커 카드 자체 ungroup
    try std.testing.expect(m.group_start == null);
    try std.testing.expect(!m.pinned and !a1.pinned and !a2.pinned); // 고정 인계 안 됨
    try std.testing.expect(!a1.local_pinned); // ★ top-level 전이라 로컬 pin도 정리(고아 📌 방지)
}

test "ungroup-pin(d): 다른 고정 그룹 앞의 고정 그룹 ungroup — 프리픽스 무결(I1)·남은 고정 그룹 유지" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..3) |_| _ = try tab_ops.newTab(session); // [t0..t3]

    // 고정 그룹 둘: PG1[0,1]·PG2[2,3] 전부 pin1(GP3(c2)와 같은 셋업). PG1(다른 고정 그룹 **앞**)을 ungroup →
    // PG1 멤버는 비고정으로 프리픽스에서 빠지고, PG2는 고정 프리픽스에 stable 재파티션으로 안착(I1 무결).
    session.tabs.items[0].group_start = try allocator.dupe(u8, "PG1");
    session.tabs.items[0].group_depth = 1;
    session.tabs.items[2].group_start = try allocator.dupe(u8, "PG2");
    session.tabs.items[2].group_depth = 1;
    for (0..4) |i| session.tabs.items[i].pinned = true;
    const pg1 = session.tabs.items[0];
    const pm1 = session.tabs.items[1];
    const pg2 = session.tabs.items[2];
    const pm2 = session.tabs.items[3];

    tab_ops.ungroupTab(session, pg1); // PG1 그룹 해제(마커 제거)
    try std.testing.expect(pg1.group_start == null); // PG1 소멸
    try std.testing.expect(!pg1.pinned and !pm1.pinned); // PG1 멤버 비고정(인계 금지)
    try std.testing.expect(pg2.pinned and pm2.pinned and pg2.group_start != null); // PG2 고정 그룹은 유지
    // 프리픽스 무결: [PG2, pm2, PG1, pm1] = [1,1,0,0](stable 재파티션으로 고정이 앞·그룹 연속).
    try std.testing.expectEqual(pg2, session.tabs.items[0]);
    try std.testing.expectEqual(pm2, session.tabs.items[1]);
    try std.testing.expectEqual(pg1, session.tabs.items[2]);
    try std.testing.expectEqual(pm1, session.tabs.items[3]);
    try std.testing.expectEqual(@as(usize, 2), tab_ops.groupSubtreeEnd(session, 0, null, null)); // PG2=[0,2) 고정 통째
}

test "ungroup-pin(nested): 고정 중첩 subgroup ungroup — 멤버가 부모 pinned 상속·부모 재소속(eject 없음)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..3) |_| _ = try tab_ops.newTab(session); // [t0..t3]
    // 고정 top-level 그룹 P=[Pm=t0(d1), c1=t1] 안에 **중첩** subgroup S=[Sm=t2(d2), s1=t3]. 넷 다 pinned.
    try setGroupMarker(session, 0, "P", 1);
    try setGroupMarker(session, 2, "S", 2);
    for (0..4) |i| session.tabs.items[i].pinned = true;
    const pm = session.tabs.items[0];
    const c1 = session.tabs.items[1];
    const sm = session.tabs.items[2];
    const s1 = session.tabs.items[3];
    try std.testing.expectEqual(@as(u8, 2), tab_ops.effectiveDepthAt(session, 2, null, null)); // 사전: S는 중첩(depth 2)

    tab_ops.ungroupTab(session, s1); // s1 소속=S → 가장 가까운 마커 S(중첩) 제거. 멤버는 부모 P로 재소속되어야.
    try std.testing.expect(sm.group_start == null); // S 마커 제거
    try std.testing.expect(pm.group_start != null); // P 유지
    // ★ [1] 중첩 subgroup ungroup: 멤버 pinned **상속**(eject 없음) — 넷 다 여전히 pinned(부모 P가 고정).
    try std.testing.expect(pm.pinned and c1.pinned and sm.pinned and s1.pinned);
    // ★ 부모 P로 재소속 — 옛 S 멤버(sm-card·s1)의 enclosing 마커가 P.
    try std.testing.expectEqual(pm, tab_ops.enclosingGroupMarkerTab(session, sm).?);
    try std.testing.expectEqual(pm, tab_ops.enclosingGroupMarkerTab(session, s1).?);
    // 순서 불변(중첩은 partition 스킵이라 front-jump 없음): [Pm, c1, sm-card, s1].
    try std.testing.expectEqual(pm, session.tabs.items[0]);
    try std.testing.expectEqual(c1, session.tabs.items[1]);
    try std.testing.expectEqual(sm, session.tabs.items[2]);
    try std.testing.expectEqual(s1, session.tabs.items[3]);
}

test "ungroup-pin(top-jump): 중첩 subgroup ungroup이 무관 고정 top카드를 front-jump 안 시킴(위치·pin 유지, [5])" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..4) |_| _ = try tab_ops.newTab(session); // [t0..t4]
    // 고정 top-level 그룹 P 안 중첩 S, 그 **뒤**에 그룹 밖 고정 top카드 TOP(top_level)·비고정 u1.
    // 배치: [Pm=t0(d1), Sm=t1(d2), s1=t2, TOP=t3(pin,top_level), u1=t4(unpin)].
    // tab_ops.groupSubtreeEnd(P)가 TOP의 top_level break서 멈춰 TOP은 P 밖 = "무관 고정 top카드".
    try setGroupMarker(session, 0, "P", 1);
    try setGroupMarker(session, 1, "S", 2);
    for (0..4) |i| session.tabs.items[i].pinned = true; // Pm·Sm·s1·TOP 고정, u1 비고정
    session.tabs.items[3].top_level = true; // TOP = P subtree 밖 그룹 밖 고정 top카드
    const top = session.tabs.items[3];
    const sm = session.tabs.items[1];
    const s1 = session.tabs.items[2];
    const pm = session.tabs.items[0];
    try std.testing.expect(tab_ops.enclosingGroupMarkerIndex(session, 3) == null); // 사전: TOP은 그룹 밖

    tab_ops.ungroupTab(session, s1); // 중첩 S ungroup — partition 스킵이라 TOP front-jump 없어야.
    try std.testing.expect(sm.group_start == null); // S 소멸
    // ★ [5] 무관 고정 top카드 TOP: 위치(index 3)·pinned·top_level 모두 유지(front-jump 없음).
    try std.testing.expectEqual(top, session.tabs.items[3]);
    try std.testing.expect(top.pinned and top.top_level);
    try std.testing.expect(tab_ops.enclosingGroupMarkerIndex(session, 3) == null); // 여전히 그룹 밖
    // ★ [1] S 멤버는 부모 P로 재소속·pinned 유지(eject 없음).
    try std.testing.expect(sm.pinned and s1.pinned);
    try std.testing.expectEqual(pm, tab_ops.enclosingGroupMarkerTab(session, s1).?);
}

test "GP3(d): clampGroupMoveToRegion — 그룹 드래그 plan을 리전 경계로 clamp, 프리뷰=확정(simulateDrop==move)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..5) |_| _ = try tab_ops.newTab(session); // [t0..t5]

    // 고정 리전 = 그룹 PG1[0,1]·PG2[2,3](마커+멤버 각 pin1), 비고정 리전 = UG[4,5](pin0).
    session.tabs.items[0].group_start = try allocator.dupe(u8, "PG1");
    session.tabs.items[0].group_depth = 1;
    session.tabs.items[2].group_start = try allocator.dupe(u8, "PG2");
    session.tabs.items[2].group_depth = 1;
    session.tabs.items[4].group_start = try allocator.dupe(u8, "UG");
    session.tabs.items[4].group_depth = 1;
    for (0..4) |i| session.tabs.items[i].pinned = true; // [1,1,1,1,0,0] — 프리픽스 canonical

    // 고정 그룹 PG1을 비고정 리전(len=6)으로 끌어도 고정 리전 경계(pinned_count=4)로 clamp.
    try std.testing.expectEqual(@as(usize, 4), session.clampGroupMoveToRegion(0, 6));
    // 비고정 그룹 UG를 고정 리전(0)으로 끌어도 비고정 리전 경계(pinned_count=4)로 clamp.
    try std.testing.expectEqual(@as(usize, 4), session.clampGroupMoveToRegion(4, 0));
    // clamp된 insert_before(4)로 만든 group_sibling plan은 프리뷰(simulateDrop)와 확정(tab_ops.moveGroupSibling)이 **동일**
    // (SG8 이중경로 없음 — plan에 이미 clamp 구움). PG1이 고정 리전 안에서 PG2 뒤로 이동.
    try expectDropEquivalent(session, 0, .{ .group_sibling = .{ .insert_before = 4 } });
    try std.testing.expect(session.tabs.items[0].pinned and session.tabs.items[3].pinned); // 이동 후에도 고정 프리픽스 무결
    try std.testing.expect(!session.tabs.items[4].pinned); // 비고정 리전 침범 없음
}

test "GP3(e): removeFromGroup 고정 멤버 — unpin 선행 후 비고정 top카드로(clampMoveToGroup pin-trap 회피)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..2) |_| _ = try tab_ops.newTab(session); // [t0..t2]

    // 고정 그룹 PG = [t0(마커) t1 t2] 전부 pin1.
    session.tabs.items[0].group_start = try allocator.dupe(u8, "PG");
    session.tabs.items[0].group_depth = 1;
    for (0..3) |i| session.tabs.items[i].pinned = true;
    const pg = session.tabs.items[0];
    const a = session.tabs.items[1];
    const b = session.tabs.items[2];

    tab_ops.removeFromGroupForTab(session, a); // 고정 멤버 a 빼기 → §12.7 보강4: unpin 후 비고정 top카드
    try std.testing.expect(!a.pinned); // ★ 빼기 = 고정 상실(unpin 선행)
    try std.testing.expect(pg.pinned and b.pinned); // 남은 그룹은 고정 유지(shred 없음)
    try std.testing.expectEqual(b, session.tabs.items[1]); // 남은 멤버가 프리픽스에 붙어 있고
    try std.testing.expectEqual(a, session.tabs.items[2]); // 빠진 카드는 비고정 리전(프리픽스 밖)
    try std.testing.expect(!tab_ops.tabIsInGroup(session, a)); // 그룹 밖(비고정 최상위)
    try std.testing.expect(tab_ops.tabIsInGroup(session, b)); // b는 여전히 PG 소속
    try std.testing.expectEqual(@as(usize, 2), tab_ops.groupSubtreeEnd(session, 0, null, null)); // PG=[0,2) 통째 고정
}

// GP4(그룹 고정 C2 — pin_derived 렌더 힌트·멤버 📌 억제·헤더 인디케이터·assert 확장, §12.8·§12.11 보강7·9). 이 훅 없이
// 스크린샷만으로는 회귀를 못 잡으므로(op 방출 도메인), pin_derived 세팅과 sidebarRowShowsPin(렌더가 pins[]로 쓰는 단일
// 출처)을 헤드리스로 단언한다. 스크린샷(MARU_FORCE_GROUP_PIN)은 시각 마감 1급 검증으로 별도.

test "GP4(a): pin_derived·sidebarRowShowsPin — 멤버 📌 억제·헤더 인디케이터·최상위 개별 pin 유지(§12.8)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..4) |_| _ = try tab_ops.newTab(session); // [t0..t4]

    // MARU_FORCE_GROUP_PIN 훅과 동형: t0=고정 최상위 카드(개별 pin), A=[t1,t2] 고정 그룹, B=[t3,t4] 비고정 그룹(대조).
    tab_ops.createGroupAbsorbForTab(session, session.tabs.items[1]); // A
    tab_ops.createSiblingGroupAbsorbForTab(session, session.tabs.items[3]); // B(형제, depth1)
    session.tabs.items[0].pinned = true; // 고정 최상위 카드(개별 pin — 그룹과 직교)
    tab_ops.toggleGroupPin(session, session.tabs.items[1]); // A 그룹째 고정 → 프리픽스로·멤버 pin 동기(§12.10 GP3)
    tab_ops.recomputeVisibleTabs(session);

    // 표시 rows: [card t0, header A, card A마커, card A멤버, header B, card B마커, card B멤버]
    const rows = session.sidebar_rows.items;
    try std.testing.expectEqual(@as(usize, 7), rows.len);

    // ── pin_derived(§12.2): 비마커 멤버=true(파생 캐시)·최상위=false(개별)·마커 자기 카드=false(권위, 파생 아님) ──
    try std.testing.expect(!rows[0].card.pin_derived); // t0 최상위 개별 pin
    try std.testing.expect(!rows[2].card.pin_derived); // A 마커 자기 카드 = 그룹 고정 권위
    try std.testing.expect(rows[3].card.pin_derived); // A 멤버 = 파생 캐시(억제 대상)
    try std.testing.expect(!rows[5].card.pin_derived); // B 마커 자기 카드
    try std.testing.expect(rows[6].card.pin_derived); // B 멤버 = 파생 캐시

    // ── sidebarRowShowsPin(§12.8): 렌더가 pins[]로 쓰는 단일 출처. 헤더 인디케이터·멤버 억제·마커 카드 억제·최상위 유지 ──
    try std.testing.expect(sidebar_ops.sidebarRowShowsPin(session, rows[0])); // 고정 최상위 카드 → 📌 유지
    try std.testing.expect(sidebar_ops.sidebarRowShowsPin(session, rows[1])); // 고정 그룹 A 헤더 → 인디케이터 📌("이 그룹 고정됨")
    try std.testing.expect(!sidebar_ops.sidebarRowShowsPin(session, rows[2])); // A 마커 카드 → 억제(헤더가 인디케이터)
    try std.testing.expect(!sidebar_ops.sidebarRowShowsPin(session, rows[3])); // A 멤버 → 억제(멤버 📌 노이즈 제거)
    try std.testing.expect(!sidebar_ops.sidebarRowShowsPin(session, rows[4])); // B 헤더(비고정) → 인디케이터 없음
    try std.testing.expect(!sidebar_ops.sidebarRowShowsPin(session, rows[5])); // B 마커 카드
    try std.testing.expect(!sidebar_ops.sidebarRowShowsPin(session, rows[6])); // B 멤버

    // 종합(§12.8 게이트): 카드 row에 뜨는 📌는 최상위 개별 pin(t0) 하나뿐 — 그룹 멤버/마커 카드 📌 노이즈 0. 고정 인디케이터는
    // 고정 그룹 헤더(A) 하나뿐 — "멤버 📌 op 없음 + 헤더 인디케이터 op 있음"(태스크 헤드리스 요구)을 draw 소스 도메인에서 고정.
    var card_pins: usize = 0;
    var header_pins: usize = 0;
    for (rows) |r| switch (r) {
        .card => if (sidebar_ops.sidebarRowShowsPin(session, r)) {
            card_pins += 1;
        },
        .agent_toggle, .agent, .recovered_sessions_header, .recovered_session => {},
        .group_header => if (sidebar_ops.sidebarRowShowsPin(session, r)) {
            header_pins += 1;
        },
    };
    try std.testing.expectEqual(@as(usize, 1), card_pins); // 최상위 개별 pin(t0)만
    try std.testing.expectEqual(@as(usize, 1), header_pins); // 고정 그룹 A 헤더 인디케이터만
}

test "GP4(b): assert 확장 tab_ops.pinBoundariesAlignGroups — canonical 정렬 통과·멤버 desync 검출·normalize 흡수(§12.11 보강9)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..3) |_| _ = try tab_ops.newTab(session); // [t0..t3]

    // 고정 그룹 G=[t0(마커),t1,t2] 전부 pin1 + 비고정 top카드 t3. 핀 경계(3)가 그룹 subtree 밖 = 정렬(canonical).
    session.tabs.items[0].group_start = try allocator.dupe(u8, "G");
    session.tabs.items[0].group_depth = 1;
    for (0..3) |i| session.tabs.items[i].pinned = true;
    try std.testing.expect(tab_ops.pinBoundariesAlignGroups(session)); // canonical → 핀 경계 = 그룹 경계 정렬(통과)

    // 멤버 desync 주입: **중간** 멤버 t1을 비고정으로(마커=1·t1=0·t2=1). 핀 경계가 그룹 subtree **중간**(t1)을 자름 = I3 위반.
    // (마지막 멤버 t2는 마커 pin과 일치하므로 t1이 "다음 리전 top카드 꼬리"가 아니라 샌드위치 desync임이 확정된다.)
    session.tabs.items[1].pinned = false;
    try std.testing.expect(!tab_ops.pinBoundariesAlignGroups(session)); // ★ 어긋남 검출(확장 assert가 잡는 위반)

    // normalize가 마커 기준 canonical로 흡수(멤버 t1을 마커 pin1로 재기록, GP2 suffix-exclusion) → 다시 정렬 통과.
    session.normalizePinnedFromGroups();
    try std.testing.expect(session.tabs.items[1].pinned); // desync 흡수
    try std.testing.expect(tab_ops.pinBoundariesAlignGroups(session)); // 흡수 후 정렬 복귀
}

// ── 그룹 고정 리뷰 회귀(/code-review max confirmed 8건, docs/plans/sidebar-groups.md §9 SG8·§12 C2) ──────────────────
// pin ⊃ group ⊃ nest 설계에서 파생 코어·마커 조작·드래그가 핀 리전을 존중하는지 헤드리스로 고정한다. 각 테스트는
// "옛(버그) 동작이면 실패"하도록 단언을 골랐다(수정이 회귀하면 즉시 red).

test "그룹핀 리뷰 #1: 잃은 mouse-up 뒤 카드 재-arm이 stale 프리뷰를 지워 옛 plan을 안 커밋한다(§9 SG8)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);
    inline for (0..3) |_| _ = try tab_ops.newTab(session); // [t0..t3] 전부 최상위 카드
    const t0 = session.tabs.items[0];
    const t1 = session.tabs.items[1];
    const t2 = session.tabs.items[2];
    const t3 = session.tabs.items[3];

    tab_ops.recomputeVisibleTabs(session); // rows: [c t0(0), c t1(1), c t2(2), c t3(3)]
    const sb = chrome.components.sidebar;
    const header_h = session.sidebar_header_height_px;
    const x: f64 = @floatFromInt(session.sidebar_width_px / 2);
    const rowY = struct {
        fn f(s: *AppSession, row: usize, hh: u32) f64 {
            const top = chrome.components.sidebar.rowTop(s.sidebar_rows.items, row, hh, sidebar_ops.sidebarMetrics(s), 0);
            return @floatFromInt(top + @as(i64, @intCast(chrome.components.sidebar.rowHeight(s.sidebar_rows.items[row], sidebar_ops.sidebarMetrics(s)) / 2)));
        }
    }.f;
    _ = sb;

    // t0(row0) 카드를 잡아(down) t2(row2) 위로 드래그 → 비커밋 카드 프리뷰(plan=.card, 실제 이동). self.tabs 불변.
    session.mouse(1, x, rowY(session, 0, header_h), 0, 0);
    try std.testing.expect(session.pointerGestureIs(.sidebar_tab));
    try std.testing.expectEqual(@as(usize, 0), session.pointer_gesture_owner.sidebar_tab.index);
    session.mouse(2, x, rowY(session, 2, header_h), 0, 0);
    try std.testing.expect(session.sidebar_drag_preview != null); // 프리뷰 활성
    try std.testing.expect(std.meta.activeTag(session.sidebar_drag_preview.?.plan) == .card); // up이 커밋하면 재배치될 plan

    // ★ 잃은 mouse-up 시뮬 — up 없이 다른 카드 t3(row3)에서 새 down(재-arm). 재-arm이 stale 프리뷰를 지운다.
    session.mouse(1, x, rowY(session, 3, header_h), 0, 0);
    try std.testing.expect(session.sidebar_drag_preview == null); // ★ 재-arm이 옛 프리뷰 클리어(잃은 up 정상화)
    try std.testing.expectEqual(@as(usize, 3), session.pointer_gesture_owner.sidebar_tab.index); // 새 origin(t3)

    // up → commitSidebarDragPreview는 프리뷰 null이라 no-op → 옛 plan 안 커밋(순서 불변).
    session.mouse(3, x, rowY(session, 3, header_h), 0, 0);
    try std.testing.expectEqual(t0, session.tabs.items[0]);
    try std.testing.expectEqual(t1, session.tabs.items[1]);
    try std.testing.expectEqual(t2, session.tabs.items[2]);
    try std.testing.expectEqual(t3, session.tabs.items[3]);
    try std.testing.expect(!session.pointerGestureIs(.sidebar_tab));
    try std.testing.expect(session.sidebar_drag_preview == null);
}

test "그룹핀 리뷰 #2: beginGroupForTab depth가 pin-region-aware — 고정 그룹 뒤 비고정 카드 중첩 depth=1(오중첩 방지, §12)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..3) |_| _ = try tab_ops.newTab(session); // [t0..t3]

    // 고정 그룹 PG=[t0(마커,depth1),t1](pin1) + 비고정 top카드 t2·t3. 프리픽스 [1,1,0,0].
    session.tabs.items[0].group_start = try allocator.dupe(u8, "PG");
    session.tabs.items[0].group_depth = 1;
    session.tabs.items[0].pinned = true;
    session.tabs.items[1].pinned = true;

    // 비고정 top카드 t2에 새 그룹 생성 → t2는 자기 리전 최상위(고정 그룹과 다른 리전)라 enclosing_depth=0 → 저장 depth=1.
    // 옛 버그: PG 마커가 depth 스택에 남아 enclosing_depth=1 → depth=2(오중첩)로 저장됐다.
    tab_ops.createGroupAbsorbForTab(session, session.tabs.items[2]);
    try std.testing.expectEqual(@as(u8, 1), session.tabs.items[2].group_depth); // ★ 저장 depth 정확(오중첩 방지)
    // pin-region-aware 파생(tab_ops.effectiveDepthAt)과도 일치 — 저장값이 렌더 파생과 어긋나지 않는다.
    try std.testing.expectEqual(@as(u8, 1), tab_ops.effectiveDepthAt(session, 2, null, null));
}

test "그룹핀 리뷰 #3: toggleGroupPin이 중첩 subgroup에서 top-level로 해소(부모 detach 없음, §12.1 pin ⊃ group ⊃ nest)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..4) |_| _ = try tab_ops.newTab(session); // [t0..t4]
    const t0 = session.tabs.items[0];
    const t2 = session.tabs.items[2];
    const t3 = session.tabs.items[3];

    // 최상위 그룹 G1=[t0..t4](depth1), 그 안 중첩 subgroup G1a=[t2..t4](depth2). t3 = G1a 멤버.
    tab_ops.createGroupAbsorbForTab(session, t0); // G1(마커 t0, depth1)
    tab_ops.createGroupAbsorbForTab(session, t2); // t2가 G1 안 → 중첩 subgroup(depth2)
    try std.testing.expectEqual(@as(u8, 1), tab_ops.effectiveDepthAt(session, 0, null, null)); // G1 top-level
    try std.testing.expectEqual(@as(u8, 2), tab_ops.effectiveDepthAt(session, 2, null, null)); // G1a 중첩

    // enclosingGroupMarkerTab이 중첩 멤버/마커에서 **top-level(t0)**로 해소(nearest t2가 아니다).
    try std.testing.expectEqual(t0, tab_ops.enclosingGroupMarkerTab(session, t3).?); // 중첩 멤버 → top-level
    try std.testing.expectEqual(t0, tab_ops.enclosingGroupMarkerTab(session, t2).?); // 중첩 마커 자신 → top-level 부모

    // 그룹 헤더 우클릭 "그룹 고정"을 **중첩 subgroup 헤더(t2)**에서 실행 → top-level G1 통째 고정(subtree만 떼지 않음).
    session.context_menu_target = .{ .group = t2 };
    session.chrome_host.context_menu.selected = ctx_group_menu_pin;
    settings_ops.acceptContextMenu(session);
    // ★ G1 전체(t0..t4)가 pinned — 옛 버그면 t2..t4만 pin돼 t0·t1에서 떨어져 나갔다(detach).
    for (session.tabs.items) |t| try std.testing.expect(t.pinned);
    try std.testing.expect(tab_ops.pinBoundariesAlignGroups(session)); // 핀 경계가 subtree 중간을 안 자름(I3)
    try std.testing.expect(t2.group_start != null and t2.group_depth == 2); // 중첩 구조 보존
}

test "그룹핀 리뷰 #4: inheritGroupMarker same-region 가드 — 단일 고정탭 그룹 닫아도 다음 top카드 안 pinned(§12 GP1)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try tab_ops.newTab(session); // [t0, t1]

    // 단일 고정탭 그룹 PG=[t0](마커,pin1) + 비고정 top카드 t1(다른 리전). t1은 위치상 마커 바로 뒤지만 리전이 달라 멤버 아님.
    session.tabs.items[0].group_start = try allocator.dupe(u8, "PG");
    session.tabs.items[0].group_depth = 1;
    session.tabs.items[0].pinned = true;
    const t1 = session.tabs.items[1];

    // 마커 카드 t0를 닫는다 → inheritGroupMarker는 next(t1)가 다른 핀 리전이라 승계 안 함(그룹 소멸, 마커 free).
    tab_ops.closeTab(session, 0);
    try std.testing.expectEqual(@as(usize, 1), session.tabs.items.len);
    try std.testing.expectEqual(t1, session.tabs.items[0]);
    // ★ t1이 고정 그룹 마커로 오승격되지 않는다 — 옛 버그면 group_start+pinned를 물려받아 pinned 마커가 됐다.
    try std.testing.expect(session.tabs.items[0].group_start == null);
    try std.testing.expect(!session.tabs.items[0].pinned);
}

test "그룹핀 리뷰 #5: newWorkspaceHighlightSlot이 비고정 리전 첫 마커 헤더를 가리킨다(고정 그룹 앞이어도, §12)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
