test "N5: 접힌 그룹을 Cmd 없이 지나 드롭 → 형제(현재 불가하던 케이스 개선)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try makeTwoSiblingGroups(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    const t0 = session.tabs.items[0];
    const t2 = session.tabs.items[2];
    session.tabs.items[2].group_collapsed = true; // B 접힘
    tab_ops.recomputeVisibleTabs(session); // [hA(0), c t0(1), c t1(2), hB(3, collapsed)] — B 카드 숨김
    const x: f64 = @floatFromInt(session.sidebar_width_px / 2);

    // 헤더 A(row0)를 접힌 헤더 B(row3)에 Cmd 없이 드래그 → 형제(과거엔 헤더 드롭=중첩이라 이 재정렬이 애매했다).
    session.mouse(1, x, sbRowCenterY(session, 0), 0, 0);
    session.mouse(2, x, sbRowCenterY(session, 3), 0, 0);
    try std.testing.expect(session.sidebar_drag_preview.?.plan == .group_sibling);
    session.mouse(3, x, sbRowCenterY(session, 3), 0, 0);
    // A가 접힌 B 뒤 형제로 — [t2(B), t3, t0(A), t1], depth 불변.
    try std.testing.expectEqual(t2, session.tabs.items[0]);
    try std.testing.expectEqual(t0, session.tabs.items[2]);
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t0));
    try std.testing.expect(session.sidebar_drag_preview == null);
}

test "N6: 프리뷰=확정 — 드래그 중 캡처한 plan이 up 커밋 결과와 일치(nest·sibling)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const CMD: i32 = 32;

    // (a) nest: Cmd 헤더 드롭 → 드래그 중 plan=.group_nest, up 후 착지 depth=target_depth.
    {
        const session = try makeTwoSiblingGroups(allocator);
        defer allocator.destroy(session);
        defer session.deinit();
        const t0 = session.tabs.items[0];
        const x: f64 = @floatFromInt(session.sidebar_width_px / 2);
        session.mouse(1, x, sbRowCenterY(session, 0), 0, CMD);
        session.mouse(2, x, sbRowCenterY(session, 3), 0, CMD);
        const captured = session.sidebar_drag_preview.?.plan;
        try std.testing.expect(captured == .group_nest);
        const target_depth = captured.group_nest.target_depth; // 프리뷰가 계획한 착지 depth
        session.mouse(3, x, sbRowCenterY(session, 3), 0, CMD);
        try std.testing.expectEqual(@as(?u8, target_depth), sidebarCardDepth(session, t0)); // 착지 = 프리뷰 plan
    }
    // (b) sibling: Cmd 없는 헤더 드롭 → plan=.group_sibling, up 후 형제 위치 착지.
    {
        const session = try makeTwoSiblingGroups(allocator);
        defer allocator.destroy(session);
        defer session.deinit();
        const t0 = session.tabs.items[0];
        const x: f64 = @floatFromInt(session.sidebar_width_px / 2);
        session.mouse(1, x, sbRowCenterY(session, 0), 0, 0);
        session.mouse(2, x, sbRowCenterY(session, 3), 0, 0);
        try std.testing.expect(session.sidebar_drag_preview.?.plan == .group_sibling);
        session.mouse(3, x, sbRowCenterY(session, 3), 0, 0);
        try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t0)); // 형제(depth 불변)
    }
}

test "P1: 고정 탭끼리 재정렬 — 둘 다 최상위 유지(enclosing null·depth 0)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..2) |_| _ = try tab_ops.newTab(session); // [t0,t1,t2]
    session.tabs.items[0].pinned = true;
    session.tabs.items[1].pinned = true; // 고정 탭 2개(그룹 아님)
    const t0 = session.tabs.items[0];
    const t1 = session.tabs.items[1];

    _ = tab_ops.moveTab(session, 1, 0); // t1을 t0 앞으로(고정 리전 [0,2) 안 재정렬)
    try std.testing.expectEqual(@as(usize, 2), tab_ops.countPinnedTabs(session));
    try std.testing.expectEqual(t1, session.tabs.items[0]);
    try std.testing.expectEqual(t0, session.tabs.items[1]);
    // 둘 다 그룹 밖 최상위(enclosing null·depth 0).
    try std.testing.expect(tab_ops.enclosingGroupMarkerIndex(session, 0) == null);
    try std.testing.expect(tab_ops.enclosingGroupMarkerIndex(session, 1) == null);
    try std.testing.expectEqual(@as(?u8, 0), sidebarCardDepth(session, t0));
    try std.testing.expectEqual(@as(?u8, 0), sidebarCardDepth(session, t1));
}

test "P2: 고정 그룹끼리 재정렬 — 둘 다 고정 유지(연속 파티션)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try makeTwoSiblingGroups(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    // A·B 둘 다 고정(마커+멤버 pinned = 정규화 캐시).
    for (0..4) |i| session.tabs.items[i].pinned = true;
    const t0 = session.tabs.items[0]; // A 마커
    const t2 = session.tabs.items[2]; // B 마커

    // B(index2)를 A 앞으로 형제 이동 → [t2,t3,t0,t1]. 리전 clamp(고정)로 파티션 유지.
    const boundary = sidebar_ops.sidebarGroupDropBoundary(session, 0, 2).?; // B를 A 헤더(row... 여기선 raw_row=0)에 = A 앞
    const clamped = session.clampGroupMoveToRegion(2, boundary);
    _ = tab_ops.moveGroupSibling(session, 2, clamped);
    try std.testing.expectEqual(t2, session.tabs.items[0]);
    try std.testing.expectEqual(t0, session.tabs.items[2]);
    // 둘 다 여전히 고정(재정렬이 고정 리전 안에서만).
    try std.testing.expect(session.tabs.items[0].pinned); // B 마커
    try std.testing.expect(session.tabs.items[2].pinned); // A 마커
    try std.testing.expectEqual(@as(usize, 4), tab_ops.countPinnedTabs(session));
}

test "P3: 그룹이 고정 탭 위로 못 감 — clampGroupMoveToRegion이 비고정 리전에 가둠" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..2) |_| _ = try tab_ops.newTab(session); // [t0,t1,t2]
    session.tabs.items[0].pinned = true; // 고정 최상위 탭
    try setGroupMarker(session, 1, "A", 1); // 비고정 그룹 A=[t1,t2]

    // 비고정 그룹 A(마커 index1)를 고정 리전(index0)으로 넣으려 해도 pinned_count=1로 clamp.
    try std.testing.expectEqual(@as(usize, 1), tab_ops.countPinnedTabs(session));
    try std.testing.expectEqual(@as(usize, 1), session.clampGroupMoveToRegion(1, 0)); // insert 0 → max(0, pinned_count=1)=1
}

test "P4(음성): 고정 탭을 그룹 뒤로 드래그해도 그룹에 흡수 안 됨(인터리빙 미지원 — 고정 리전에 clamp)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..2) |_| _ = try tab_ops.newTab(session); // [t0,t1,t2]
    session.tabs.items[0].pinned = true; // 고정 최상위 탭
    try setGroupMarker(session, 1, "A", 1); // 비고정 그룹 A=[t1,t2]
    const t0 = session.tabs.items[0];

    // 고정 탭 t0(index0)를 그룹 A 뒤(index2 이후)로 이동 시도 → clampMoveToGroup이 고정 리전 [0,1)에 가둔다(흡수 아님).
    _ = tab_ops.moveTab(session, 0, 2);
    // t0는 여전히 index0(고정 최상위), 그룹 A 멤버가 되지 않음(enclosing null).
    var t0_idx: usize = 0;
    for (session.tabs.items, 0..) |t, i| if (t == t0) {
        t0_idx = i;
    };
    try std.testing.expectEqual(@as(usize, 0), t0_idx); // 고정 리전 앞에 그대로
    try std.testing.expect(tab_ops.enclosingGroupMarkerIndex(session, t0_idx) == null); // 그룹에 인터리빙 안 됨
    try std.testing.expect(session.tabs.items[t0_idx].pinned);
}

test "R1: 터미널 tracking + Cmd 마우스 → report_mouse.mods에 32 없음(마스킹 회귀 가드)" {
    var session: AppSession = undefined;
    session.addr_edit = null; // 슬라이스 3: mouse()가 조기 addr 밴드 캡처에서 읽음(undefined면 UB — [[devsession-undefined-test-field-trap]])
    session.tabs = .empty;
    session.pointer_gesture_owner = .none;
    // divider capture는 `PointerGestureOwner` 밖의 두 번째 pointer 축이라 여기서 함께 비운다
    // — `undefined` 세션이 mouse()를 타면 이 필드도 읽는다(CIM2).
    session.divider_interaction = .{};
    session.divider_capture_seg = null;
    session.divider_capture_split = null;
    session.divider_coalescer = .{};
    session.divider_entry_scratch = .empty;
    session.divider_split_scratch = .empty;
    session.divider_snapshot_generation = 0;
    session.scrollbar_interaction = .{};
    session.dock_list_scroll_drag = .{};
    session.dock_list_scroll_drag_owner = null;
    session.dock_list_scroll_entry_count = 0;
    session.dock_list_scroll_generation = 0;
    session.allocator = std.testing.allocator;
    session.io = std.Io.Threaded.global_single_threaded.io();
    var tab_surface = try maru.session.Surface.init(std.testing.allocator, 1, .{ .cols = 8, .rows = 4 });
    defer tab_surface.deinit();
    session.surface_initialized = true;
    var st_ptrs = [_]*maru.session.Surface{&tab_surface};
    session.app_window = .{ .tabs = &st_ptrs };

    var capture_buf: std.ArrayList(u8) = .empty;
    defer capture_buf.deinit(std.testing.allocator);
    var cap_ctx = ReportCaptureCtx{ .buf = &capture_buf };
    // M3b: runtime은 앱-전역 공유 포인터라, 이 undefined-session 테스트는 로컬 SurfaceRuntime을 소유해 격리한다.
    var test_rt: app.SurfaceRuntime = undefined;
    test_rt = app.SurfaceRuntime.init(std.testing.allocator);
    session.runtime = &test_rt;
    defer session.runtime.deinit();
    _ = try session.runtime.attach(&tab_surface, tab_surface.id, .{ .ctx = &cap_ctx, .write_input = ReportCaptureCtx.write, .resize_fn = testNoopPtyResize });

    // 리포트 경로가 읽는 상태를 전부 명시(undefined 트랩 회피 — 모든 드래그 캡처 플래그 false).
    session.metal_dirty = false;
    session.chrome_host = .{};
    session.rename = null;
    session.drag_autoscroll = 0;
    session.mouse_drag_selecting = false;
    session.cell_width_px = 8;
    session.cell_height_px = 16;
    session.scale_milli = 1000;
    session.sidebar_width_px = 0; // inSidebar=false → 본문 리포트 경로
    session.active_pane_rect = .{ .x = 0, .y = 0, .w = 64, .h = 64 };
    session.last_drag_col = 0;

    // any-event(1003) tracking + SGR — motion을 리포트한다.
    tab_surface.core.mouse_tracking = .any;
    tab_surface.core.mouse_format = .sgr;

    // **그 버튼이 눌려 있다고 세워 둔다.** 리포트 경로는 짝 없는 끌기·뗌을 버리므로(press 없이 release만
    // 받은 TUI가 그것을 클릭으로 읽어 링크가 두 번 열리던 결함의 수정) 드래그가 그냥은 안 나간다.
    // `mouse(1, …)`을 부르지 않는 이유는 down 경로가 이 하네스가 세우지 않은 사이드바 드래그 상태까지
    // 읽기 때문이다 — 이 테스트가 볼 것은 마스킹 하나이고, 짝 규칙은 아래 전용 테스트가 고정한다.
    session.mouse_report_press_surface = tab_surface.id;
    session.mouse_report_press_buttons = 1; // button 0
    // Cmd(mods=32) 드래그(motion) → cb = button(0) + mods(0=마스킹) + motion(32) = 32. 32비트가 안 빠졌으면 cb=64로 오염.
    session.mouse(2, 16.0, 16.0, 0, 32);
    try std.testing.expect(std.mem.indexOf(u8, capture_buf.items, "\x1b[<32;") != null); // 정상: cb=32(motion만)
    try std.testing.expect(std.mem.indexOf(u8, capture_buf.items, "\x1b[<64;") == null); // 오염 없음: command 32가 안 섞임
    try std.testing.expect(std.mem.indexOf(u8, capture_buf.items, "\x1b[<96;") == null); // 방어: 32+32+32=96도 없음
}

test "마우스 리포팅: 누른 적 없는 버튼의 뗌·끌기는 앱에 보내지 않는다(링크 Cmd+클릭 이중 열림)" {
    // 사용자 보고(2026-08-20): 터미널에 출력된 생 URL을 Cmd+클릭하면 **브라우저가 두 번** 떴다. 실측으로
    // 발신자를 갈랐더니 LaunchServices에 `maru-macos-app` 한 건과 `open` 한 건이 1초 간격으로 남았다 —
    // 두 번째는 maru가 아니라 **터미널 안의 TUI가 띄운 `/usr/bin/open`**이었다.
    //
    // 원인은 반쪽 이벤트다. host는 링크 클릭의 `down`을 소비하는데(Swift `handleUrlClick`이 true면
    // `handleMouse`를 안 부른다) 짝인 `up`은 그대로 리포트 경로로 흘러, TUI가 press 없이 release만 받고
    // 그것을 클릭으로 해석해 자기도 같은 URL을 열었다. xterm 프로토콜에서 release는 press의 짝이므로
    // 짝 없는 release를 보내는 것 자체가 위반이고, 받은 쪽이 어떻게 반응해도 이상하지 않다.
    //
    // **게이트마다 짝을 맞추는 대신 리포트 직전 한 자리에서 막는다** — `mouse()`에는 `kind == 1`에서만
    // 삼키는 게이트가 여럿이고(상태바·팔레트·모달), 링크만 100% 재현된 것은 그것이 터미널 pane 안이라
    // up이 여기까지 닿기 때문이지 나머지가 안전해서가 아니다.
    var session: AppSession = undefined;
    session.addr_edit = null;
    session.tabs = .empty;
    session.pointer_gesture_owner = .none;
    session.divider_interaction = .{};
    session.divider_capture_seg = null;
    session.divider_capture_split = null;
    session.divider_coalescer = .{};
    session.divider_entry_scratch = .empty;
    session.divider_split_scratch = .empty;
    session.divider_snapshot_generation = 0;
    session.scrollbar_interaction = .{};
    session.dock_list_scroll_drag = .{};
    session.dock_list_scroll_drag_owner = null;
    session.dock_list_scroll_entry_count = 0;
    session.dock_list_scroll_generation = 0;
    session.allocator = std.testing.allocator;
    session.io = std.Io.Threaded.global_single_threaded.io();
    var tab_surface = try maru.session.Surface.init(std.testing.allocator, 1, .{ .cols = 8, .rows = 4 });
    defer tab_surface.deinit();
    session.surface_initialized = true;
    var st_ptrs = [_]*maru.session.Surface{&tab_surface};
    session.app_window = .{ .tabs = &st_ptrs };

    var capture_buf: std.ArrayList(u8) = .empty;
    defer capture_buf.deinit(std.testing.allocator);
    var cap_ctx = ReportCaptureCtx{ .buf = &capture_buf };
    var test_rt: app.SurfaceRuntime = undefined;
    test_rt = app.SurfaceRuntime.init(std.testing.allocator);
    session.runtime = &test_rt;
    defer session.runtime.deinit();
    _ = try session.runtime.attach(&tab_surface, tab_surface.id, .{ .ctx = &cap_ctx, .write_input = ReportCaptureCtx.write, .resize_fn = testNoopPtyResize });

    session.metal_dirty = false;
    session.chrome_host = .{};
    session.rename = null;
    session.drag_autoscroll = 0;
    session.mouse_drag_selecting = false;
    session.mouse_report_press_surface = 0;
    session.mouse_report_press_buttons = 0;
    session.cell_width_px = 8;
    session.cell_height_px = 16;
    session.scale_milli = 1000;
    session.sidebar_width_px = 0;
    session.active_pane_rect = .{ .x = 0, .y = 0, .w = 64, .h = 64 };
    session.last_drag_col = 0;
    tab_surface.core.mouse_tracking = .normal;
    tab_surface.core.mouse_format = .sgr;

    // ① **누름을 삼킨 클릭의 뗌**(링크 Cmd+클릭이 그 모양이다) — 아무것도 나가지 않는다.
    session.mouse(3, 16.0, 16.0, 0, 0);
    try std.testing.expectEqual(@as(usize, 0), capture_buf.items.len);

    // ② 짝 없는 끌기도 마찬가지다. 버튼 없는 hover 이동은 이 경로가 아니라 `mouseMoved`가 낸다.
    session.mouse(2, 24.0, 16.0, 0, 0);
    try std.testing.expectEqual(@as(usize, 0), capture_buf.items.len);

    // ③ 짝이 맞으면 **평소대로 나간다** — 이 가드가 정상 클릭을 죽이지 않는다는 것이 핵심이다.
    //
    // 누름을 `mouse(1, …)`로 태우지 않는 것은 down 경로가 이 하네스가 세우지 않은 사이드바 드래그
    // 상태까지 읽기 때문이다. 여기서 고정하는 계약은 "짝이 있으면 통과하고, 그 뗌이 짝을 소비한다"이고,
    // 누름이 짝을 세우는 쪽은 같은 블록의 한 줄(`mouse_report_press_buttons |= button_bit`)이다.
    session.mouse_report_press_surface = tab_surface.id;
    session.mouse_report_press_buttons = 1; // button 0
    session.mouse(3, 16.0, 16.0, 0, 0);
    try std.testing.expect(capture_buf.items.len > 0); // 짝이 있는 뗌은 리포트된다
    try std.testing.expect(std.mem.endsWith(u8, capture_buf.items, "m")); // SGR 뗌은 `m`으로 끝난다

    // ④ 뗌이 짝을 **소비했으니** 그다음 뗌은 다시 버려진다(래치가 남아 이중으로 새지 않는다).
    const after_release = capture_buf.items.len;
    session.mouse(3, 16.0, 16.0, 0, 0);
    try std.testing.expectEqual(after_release, capture_buf.items.len);

    // ⑤ **다른 surface에서 눌린 버튼의 뗌도 아니다.** 마우스는 하나뿐이라 짝은 (surface, 버튼) 쌍이고,
    //    남의 pane에서 시작한 제스처의 뗌이 이 pane의 앱에 클릭처럼 들어가면 안 된다.
    session.mouse_report_press_surface = tab_surface.id + 1;
    session.mouse_report_press_buttons = 1;
    session.mouse(3, 16.0, 16.0, 0, 0);
    try std.testing.expectEqual(after_release, capture_buf.items.len);
}

// B1 헬퍼 — 각 위치의 (그룹 마커 이름 첫 글자<<8 | group_depth) 시그니처. 구조적으로 동일한 두 세션의 착지 비교용.
fn groupSig4(session: *AppSession, out: *[4]u16) void {
    for (session.tabs.items, 0..) |t, i| {
        if (i >= 4) break;
        const nm: u16 = if (t.group_start) |g| (if (g.len > 0) @as(u16, g[0]) else 0) else 0;
        out[i] = (nm << 8) | t.group_depth;
    }
}

test "B1: 고정 그룹 0 + Cmd 미사용 그룹 드래그 = moveGroupSibling과 동일 착지(SG5/SG8 회귀 0)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;

    // 경로 A: mouse 시뮬레이션(Cmd 없음)으로 헤더 A를 헤더 B에 드롭.
    var sig_mouse: [4]u16 = undefined;
    {
        const session = try makeTwoSiblingGroups(allocator);
        defer allocator.destroy(session);
        defer session.deinit();
        const x: f64 = @floatFromInt(session.sidebar_width_px / 2);
        session.mouse(1, x, sbRowCenterY(session, 0), 0, 0);
        session.mouse(2, x, sbRowCenterY(session, 3), 0, 0);
        session.mouse(3, x, sbRowCenterY(session, 3), 0, 0);
        groupSig4(session, &sig_mouse);
    }
    // 경로 B: 직접 tab_ops.moveGroupSibling(A 마커=0, insert_before=B subtree 끝) — 옛 SG5-1 확정 경로.
    var sig_direct: [4]u16 = undefined;
    {
        const session = try makeTwoSiblingGroups(allocator);
        defer allocator.destroy(session);
        defer session.deinit();
        const boundary = sidebar_ops.sidebarGroupDropBoundary(session, 3, 0).?; // 헤더 B(row3) 드롭 경계
        const clamped = session.clampGroupMoveToRegion(0, boundary);
        _ = tab_ops.moveGroupSibling(session, 0, clamped);
        groupSig4(session, &sig_direct);
    }
    try std.testing.expectEqualSlices(u16, &sig_mouse, &sig_direct); // 두 경로 동일(그룹 구조 byte-identical 착지)
}

test "fillSidebarGlyphPyTop: 그룹 헤더가 앞서면 카드 glyph py_top이 rowTop(가변 높이)로 밀린다 (SG3b-2-ii #1·#5·#6)" {
    const sb = chrome.components.sidebar;
    const header_row_h: u32 = 24;
    const ch: u32 = 20;
    // glyph 셀 하나 만들기(슬롯=**표시 row 인덱스**; 헤더도 slot을 차지, line_index/line_count는 sidebarGlyphRow로 인코딩). slot_id≠0=glyph.
    const glyphCell = struct {
        fn make(row_idx: usize, li: u16, lc: u16) metal_frame.NativeMetalCell {
            return .{ .row = coretext_frame_builder.sidebarGlyphRow(row_idx, li, lc), .col = 0, .width = 1, .codepoint = 'x', .slot_id = 7, .atlas_x_px = 0, .atlas_y_px = 0, .atlas_width_px = 0, .atlas_height_px = 0, .u0 = 0, .v0 = 0, .u1 = 0, .v1 = 0 };
        }
    }.make;
    // 밴드 셀(slot_id==0, row=표시 row 인덱스) — 손대지 않아야 한다.
    const bandCell: metal_frame.NativeMetalCell = .{ .row = 1, .col = 0, .width = 1, .codepoint = 0, .slot_id = 0, .atlas_x_px = 0, .atlas_y_px = 0, .atlas_width_px = 0, .atlas_height_px = 0, .u0 = -1, .v0 = -1, .u1 = -1, .v1 = -1 };

    // (A) 가변 높이 + 헤더 glyph: [헤더(24), 카드(100), 카드(100)]. slot=표시 row 인덱스라 헤더도 slot0을 차지한다.
    const rows = [_]sb.Row{
        .{ .group_header = .{ .collapsed = false, .label = "g", .member_count = 2, .tab = 0 } },
        .{ .card = .{ .tab = 0, .label = "", .active = false, .depth = 1 } },
        .{ .card = .{ .tab = 1, .label = "", .active = false, .depth = 1 } },
    };
    // 헤더 glyph(slot0, 1줄), 카드0 glyph(slot1), 카드1 glyph(slot2), 밴드 셀.
    var cells = [_]metal_frame.NativeMetalCell{ glyphCell(0, 0, 1), glyphCell(1, 0, 1), glyphCell(2, 0, 1), bandCell };
    // 카드 높이는 줄 수 기반(cardHeight)이라 기대값도 그 계산에서 파생한다 — 줄 기하 조정 시 자동 정합.
    const m_t = chrome.components.sidebar.Metrics.init(ch, header_row_h);
    const pad_t = m_t.content_pad_v; // 목록 위 여백 — 밴드·글자·클릭이 공유하는 시작 오프셋
    sidebar_ops.fillSidebarGlyphPyTop(std.testing.allocator, &cells, &rows, m_t);
    try std.testing.expectEqual(@as(u32, pad_t + (24 - 20) / 2), cells[0].origin_y); // 여백 + 헤더 slot0: content top0 + 얇은 줄(24) 세로 중앙(24-20)/2=2
    const card_h_t = chrome.components.sidebar.cardHeight(1, m_t); // 이 rows의 카드는 1줄
    const block_off_t = (card_h_t - sidebar_ops.sidebarBlockHeight(1, ch)) / 2;
    try std.testing.expectEqual(@as(u32, pad_t + 24 + block_off_t), cells[1].origin_y); // 카드0 slot1: content top=헤더(24) + 블록중앙
    try std.testing.expectEqual(@as(u32, pad_t + 24 + card_h_t + block_off_t), cells[2].origin_y); // 카드1 slot2: + 카드0 높이
    try std.testing.expectEqual(@as(u32, 0), cells[3].origin_y); // 밴드 셀은 그대로

    // (B) 동작 보존: 헤더 없이 카드만이면 content top = row*slot_h(균일 — 옛 slot_idx*slot_h와 동일).
    const rows_flat = [_]sb.Row{
        .{ .card = .{ .tab = 0, .label = "", .active = false } },
        .{ .card = .{ .tab = 1, .label = "", .active = false } },
    };
    var cells2 = [_]metal_frame.NativeMetalCell{ glyphCell(0, 0, 1), glyphCell(1, 0, 1) };
    sidebar_ops.fillSidebarGlyphPyTop(std.testing.allocator, &cells2, &rows_flat, .init(ch, header_row_h));
    try std.testing.expectEqual(@as(u32, pad_t + 0 * card_h_t + block_off_t), cells2[0].origin_y);
    try std.testing.expectEqual(@as(u32, pad_t + 1 * card_h_t + block_off_t), cells2[1].origin_y);

    // (C) 다줄 카드: 카드0(slot1, 헤더 뒤) line_count=3. 줄 스텝=ch+여유(sidebarLineStep)라 블록 높이=sidebarBlockHeight(3,ch),
    // 블록중앙 오프셋=(slot_h-블록)/2, 2줄째는 +2*step. content top=헤더(24). 값은 헬퍼로 파생해 스텝 조정 시 자동 정합.
    var cells3 = [_]metal_frame.NativeMetalCell{glyphCell(1, 2, 3)};
    sidebar_ops.fillSidebarGlyphPyTop(std.testing.allocator, &cells3, &rows, .init(ch, header_row_h));
    // 이 카드 row의 실제 높이(1줄)로 블록중앙을 잡는다 — 3줄 glyph를 1줄 카드에 넣는 인코딩 검증이라
    // 블록이 카드보다 크면 오프셋 0으로 포화된다(-|). 옛 고정 슬롯(100) 하드코딩을 대체.
    const block_off_c: u32 = (card_h_t -| sidebar_ops.sidebarBlockHeight(3, ch)) / 2;
    try std.testing.expectEqual(@as(u32, pad_t + 24 + block_off_c + 2 * sidebar_ops.sidebarLineStep(ch)), cells3[0].origin_y); // 헤더24 + block_off + 2줄*step(여유)
}

// 카드 줄 수는 **행 높이(hit-test·밴드·glyph)와 렌더가 공유하는 단일 출처**다(sidebarCardLines). 두 곳이 갈리면
// 카드가 그리는 줄 수와 그 카드가 차지하는 높이가 어긋나 "보이는 곳과 눌리는 곳이 다른" 회귀가 난다. 이 테스트는
// 상태 변화가 줄 수 → 카드 높이 → 다음 row의 시작 y까지 실제로 전파되는지 못박는다.
// 목록의 **조작**을 못박는다: 토글 클릭은 접기만, 에이전트 행 클릭은 그 자리로 이동한다(§5 3단계).
// 터미널에서 왜 중요한가: 3단계(Term 탭 활성화)가 빠지면 Pane까지만 가고 사용자가 지목한 에이전트는 여전히
// 가려진 탭에 있다 — 목록이 "보여주기"만 하고 "데려다주기"를 못 하면 이 기능의 절반이 없는 것이다.
// code-review(max) 회귀: 에이전트 행 ✕가 `closeTermAt`을 직접 불러 (1) 실행 중 에이전트를 확인 없이 죽이고
// (2) 마지막 워크스페이스의 마지막 Term에서 해제된 surface에 쓰는 UAF + 빈 pane 인덱싱 패닉으로 이어졌다.
// 터미널에서 왜 중요한가: 사이드바 ✕ 한 번이 되돌릴 수 없는 종료인데, 다른 모든 닫기 경로가 거치는 확인 규율만
// 이 자리에서 빠져 있었다. 이제 requestClose가 캐스케이드 범위(Term→pane→탭→세션)를 풀고 그 범위로 확인한다.
// 4단계(§7): 세션 기록에서 읽은 마지막 대화가 **행 라벨·줄 수·알림 본문** 셋에 실제로 도달하는지 고정한다.
// 캐시(Term.agent_transcript)까지는 폴링이 채우고, 여기서 검증하는 건 그 아래 소비 경로다 — 파일→캐시 구간은
// 실제 FS·provider 포맷에 의존해 단위 테스트가 못 덮으므로 앱 실행으로 확인한다(§10).
// 활동 시각의 **우선순위**를 고정한다: 관측된 출력 > 세션 기록 mtime > 빈칸. mtime 폴백이 없으면 앱을 새로 켠
// 직후(= 사이드바를 보는 바로 그 순간) 모든 행이 빈칸이 된다.
test "에이전트 행 활동 시각: 출력이 mtime보다 우선하고, 둘 다 없으면 빈칸이다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const a = std.testing.allocator;
    const session = try initSmokeSessionSized(a);
    defer a.destroy(session);
    defer session.deinit();

    const term = session.tabs.items[0].panes.items[0].terms.items[0];
    term.agent_kind = .claude;
    // 두 경로 모두 wall clock 기준이라 호스트 uptime에 의존하지 않는다 — 예전 테스트는 출력 시각을
    // `awakeMs() -| 5분`으로 만들어, uptime이 5분 미만인 호스트(CI 러너)에서 0으로 포화돼 mtime 경로로
    // 조용히 미끄러졌고 우선순위를 전혀 검증하지 못했다(code-review max).
    const now: i96 = @intCast(std.Io.Clock.real.now(session.io).nanoseconds);

    // 관측된 출력도, 기록 mtime도 없다 → 빈칸(그 앱 세션에서 아직 아무 일도 없었다).
    {
        const age = try sidebar_ops.agentAgeOwned(session, term);
        defer a.free(age);
        try std.testing.expectEqualStrings("", age);
    }

    // mtime만 있다 → 폴백이 값을 낸다. 앱을 새로 켠 직후가 정확히 이 상태다.
    term.agent_transcript.read_mtime_ns = now - 2 * std.time.ns_per_hour;
    {
        const age = try sidebar_ops.agentAgeOwned(session, term);
        defer a.free(age);
        try std.testing.expectEqualStrings("2h", age);
    }

    // 출력이 관측되면 그쪽이 이긴다 — 값이 확실히 달라야 우선순위가 검증된다(2h ↔ 5m).
    term.agent_last_output_wall_ns = now - 5 * std.time.ns_per_min;
    {
        const age = try sidebar_ops.agentAgeOwned(session, term);
        defer a.free(age);
        try std.testing.expectEqualStrings("5m", age);
    }

    // 방금 출력한 에이전트는 경과가 0에 가깝다 — 빈칸이 아니라 `now`여야 한다(이 칼럼이 가장 보여줘야 할 행이다).
    term.agent_last_output_wall_ns = now;
    {
        const age = try sidebar_ops.agentAgeOwned(session, term);
        defer a.free(age);
        try std.testing.expectEqualStrings("now", age);
    }

    // Term이 없는 행(그룹 헤더·편집 중 카드)은 빈칸이다.
    {
        const age = try sidebar_ops.agentAgeOwned(session, null);
        defer a.free(age);
        try std.testing.expectEqualStrings("", age);
    }
}

// 세션 행의 **폴더·브랜치 줄**이 cwd에서 실제로 나오는지, 그리고 **관측(OSC 7)이 커널 폴백보다 우선**인지
// 고정한다. 목록을 Term 전수로 넓히면서(2026-08-11) "행에 폴더·브랜치가 안 보인다"는 제보를 받았고, 그것이
// 코드 회귀인지 cwd를 몰라서인지 가르는 축이 없었다. 이 테스트가 그 축이다.
//
// 관측이 비어도 줄이 붙는다는 것(커널 폴백)은 바로 아래 회귀 테스트가 소유한다. 여기서 잠그는 것은
// **우선순위**다 — 관측이 값을 주면 커널에 묻지 않고 그 값을 쓴다. 순서가 뒤집히면 셸이 방금 보고한 cwd를
// 최대 한 폴링 주기 동안 무시하게 된다.
test "사이드바 세션 행: 관측 cwd가 있으면 폴더·브랜치 줄이 붙는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const a = std.testing.allocator;
    const session = try initSmokeSessionSized(a);
    defer a.destroy(session);
    defer session.deinit();

    const tab = session.tabs.items[0];
    const term = tab.panes.items[0].terms.items[0];
    term.agent_kind = .claude;
    term.agent_state = .idle;

    // 관측이 비어도 라벨 한 줄로 줄지 않는다 — 커널 폴백이 답하므로 최소한 폴더 줄이 붙는다.
    // (테스트 프로세스의 cwd가 저장소 안이면 브랜치 줄까지 3줄이라 여기서는 하한만 잠근다.)
    try std.testing.expect(sidebar_ops.sidebarAgentRowLines(session, tab, .{ .pane = 0, .term = 0 }) >= 2);

    // cwd를 심는다. 스모크 세션은 `live_initialized=false`라 refreshTermObservation이 early-return하므로
    // 이 값이 덮이지 않는다. git repo가 **아닌** 경로를 쓰는 이유는 결정성 때문이다 — 테스트가 어디서
    // 돌든 같은 답을 내야 한다. 브랜치 줄은 repo 안에서만 붙고 그 파생은 git.zig가 따로 검증한다.
    try term.rt.observation.cwd.appendSlice(a, "/tmp");
    term.rt.observation.availability = .current;

    // **관측이 커널보다 우선이다.** 심은 값이 `/tmp`(저장소 아님)라 브랜치 줄이 사라져 정확히 2줄이 된다 —
    // 폴백이 우선이었다면 테스트 프로세스의 저장소 cwd가 이겨 3줄이 나온다. 즉 이 등식이 순서를 잠근다.
    try std.testing.expectEqual(@as(u8, 2), sidebar_ops.sidebarAgentRowLines(session, tab, .{ .pane = 0, .term = 0 }));
    const folder = try sidebar_ops.agentRowFolderOwned(session, term, "");
    defer a.free(folder);
    try std.testing.expect(folder.len > 0);
    try std.testing.expect(std.mem.indexOf(u8, folder, "tmp") != null);
}

// **회귀 잠금**: "활성 터미널이 서 있는 폴더"를 푸는 지점은 하나여야 한다. 예전에는 둘이었고 한쪽만 커널
// 폴백을 갖고 있었다 — `git_ops.activeTerminalCwd`(소스 컨트롤·파일 탐색기)는 OSC 7이 비면 `proc_pidinfo`로
// 내려가는데(docs/editor-surface-dock.md §3.5), 사이드바의 `sidebarHasCwd`·`termGitBranch`는 관측만 봤다.
//
// 그 비대칭이 언제 보이는가가 핵심이었다. 재개(에이전트 세션 기록 → 이어하기)는 셸을
// `zsh -l -i -c "exec claude --resume <id>"`로 띄우는데(agent.zig의 `resumeAgentSessionInNewTerm`),
// `-c`는 프롬프트를 한 번도 그리지 않아 `_maru_osc7` precmd 훅이 돌지 않는다(실측: `.zshrc`는 source되고
// 훅 등록도 되지만 precmd는 안 돈다) — 그 Term은 평생 OSC 7을 한 번도 못 받는다. 프롬프트를 거쳐 provider를
// 띄운 보통 탭은 이미 한 번 보고했으므로 값이 남아 있다. 그래서 증상이 **재개에서만** 보였다.
// (claude·codex가 RIS로 그 값을 지운다는 옛 설명은 실측과 다르다 — 2026-08-12 pty 캡처에서 두 provider 모두
// RIS를 보내지 않는다. 지우는 쪽이 아니라 **애초에 안 받는 쪽**이 원인이다.)
//
// 스모크 세션은 `live_initialized=false`라 관측이 빈 채로 남아 "OSC 7 미수신" 상태를 그대로 재현한다.
test "OSC 7이 비어도 사이드바는 소스 컨트롤과 같은 답을 낸다(폴더·브랜치줄이 살아 있다)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const a = std.testing.allocator;
    const session = try initSmokeSessionSized(a);
    defer a.destroy(session);
    defer session.deinit();

    const tab = session.tabs.items[0];
    const term = tab.panes.items[0].terms.items[0];
    term.agent_kind = .claude; // 재개된 provider Term을 흉내낸다
    term.agent_state = .idle;

    // 전제: OSC 7 미수신.
    try std.testing.expectEqual(@as(usize, 0), term.rt.observation.cwd.items.len);

    // 축 1 — 소스 컨트롤·파일 탐색기: 커널 폴백이 답한다(저장소 밖에서 돌면 판정 불가라 skip).
    var buf: [std.fs.max_path_bytes]u8 = undefined;
    const cwd = git_ops.activeTerminalCwd(session, &buf) orelse return error.SkipZigTest;
    const fallback_branch = git_ops.readGitBranch(session.io, a, cwd) orelse return error.SkipZigTest;
    defer a.free(fallback_branch);

    // 축 2 — 사이드바: **같은 Term, 같은 순간**에 같은 답을 내야 한다. 예전에는 여기서 전부 "모른다"였다.
    try std.testing.expect(sidebar_ops.sidebarHasCwd(session, term));
    try std.testing.expect(sidebar_ops.sidebarFolderLineShown(session, term));
    const branch = git_ops.termGitBranch(session, term) orelse return error.SidebarBranchMissing;
    try std.testing.expectEqualStrings(fallback_branch, branch);

    // 경로줄도 같은 폴더를 가리킨다 — 판정(`sidebarHasCwd`)과 표시(`sidebarCwdPath`)가 갈리면 줄 수와
    // 글자가 어긋나 "보이는 곳과 눌리는 곳이 다른" 회귀가 난다.
    const path = try sidebarCwdPath(session, term);
    defer a.free(path);
    try std.testing.expect(std.mem.endsWith(u8, path, std.fs.path.basename(cwd)));

    // 결과: 카드가 이름+브랜치+폴더 3줄, 에이전트 행도 라벨+폴더+브랜치 3줄이다(기본 토글 both-on 기준).
    try std.testing.expectEqual(@as(u8, 3), sidebar_ops.sidebarCardLines(session, tab));
    try std.testing.expectEqual(@as(u8, 3), sidebar_ops.sidebarAgentRowLines(session, tab, .{ .pane = 0, .term = 0 }));
}

// 사이드바 **검색**도 같은 축을 쓴다. `tabMatchesSearch`는 이름·브랜치·폴더 셋으로 카드를 거르는데, 폴더만
// 관측(OSC 7)을 직독하면 사이드바가 커널 폴백으로 폴더줄을 **그리고 있는** 카드인데 그 폴더 이름으로는 검색이
// 안 되는 반쪽 필터가 된다(브랜치로는 된다 — 그쪽은 `termGitBranch`라 축을 탄다). 적대적 검증에서 실제로 만들
// 뻔한 회귀라 여기서 잠근다.
test "사이드바 검색: 폴더도 브랜치와 같은 축으로 매칭한다(OSC 7이 없어도)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const a = std.testing.allocator;
    const session = try initSmokeSessionSized(a);
    defer a.destroy(session);
    defer session.deinit();

    const tab = session.tabs.items[0];
    const term = tab.panes.items[0].terms.items[0];
    try std.testing.expectEqual(@as(usize, 0), term.rt.observation.cwd.items.len); // 전제: OSC 7 미수신

    var buf: [std.fs.max_path_bytes]u8 = undefined;
    const cwd = git_ops.termCwd(session, term, &buf) orelse return error.SkipZigTest;
    const leaf = std.fs.path.basename(cwd);
    try std.testing.expect(leaf.len > 0);
    // 이름줄에 우연히 폴더명이 들어 있으면 이 테스트가 **폴더 축을 검증하지 못한다**(이름 매칭으로 통과한다).
    // 그때는 통과시키지 않고 판정 불가로 물러난다.
    if (std.ascii.indexOfIgnoreCase(workspaceLabel(tab), leaf) != null) return error.SkipZigTest;

    try std.testing.expect(tab_ops.tabMatchesSearch(session, tab, leaf));
    // 브랜치도 같은 cwd에서 파생되므로 함께 매칭된다(저장소 밖이면 판정할 것이 없다).
    if (git_ops.termGitBranch(session, term)) |branch| {
        try std.testing.expect(tab_ops.tabMatchesSearch(session, tab, branch));
    }
    // 위 단언이 "무엇을 넣어도 true"라서 통과한 것이 아님을 보인다 — 이게 없으면 필터가 통째로 고장 나도
    // 이 테스트는 계속 초록이다.
    try std.testing.expect(!tab_ops.tabMatchesSearch(session, tab, "zzz-no-such-token-zzz"));
}

// **에이전트 행의 줄 수도 투영 뒤에 바뀐다.** 제품 스크린샷에서 실제로 발견했다(bash 셸 = OSC 7 없음):
// 폴더줄이 **다음 행의 라벨 위에 겹쳐** 그려졌다. 원인은 재투영 가드가 카드 행만 보고 에이전트 행은
// `else => {}`로 건너뛴 것이다 — 예전에는 보조줄이 OSC 7에만 달려 있었고 그 값이 대개 첫 투영 전에 도착해
// 어긋남이 드물었지만, cwd가 커널 폴백까지 가면서 값이 투영 **뒤에** 오는 것이 흔해졌다(커널 조회는 자식이
// foreground process group을 잡은 뒤에야 답한다).
//
// 여기서는 그 상태를 손으로 만든다: 줄 수를 굳힌 뒤 cwd가 도착하는 순서를 재현하고, 가드가 그것을 낡음으로
// 보는지 확인한다.
test "사이드바 재투영: 비활성 Term의 cwd가 투영 뒤에 와도 그 행 줄 수가 따라온다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const a = std.testing.allocator;
    const session = try initSmokeSessionSized(a);
    defer a.destroy(session);
    defer session.deinit();
    _ = try session.resize(1400, 900, 1000);

    // **비활성 Term이어야 한다.** 활성 Term은 카드(`sidebarCardTerm`)도 함께 쓰므로 그 cwd를 바꾸면 카드 줄
    // 수도 같이 바뀌고, 가드의 `.card` 갈래가 낡음을 감지해 rebuild한다 — 그러면 `.agent` 갈래를 통째로 빼도
    // 에이전트 행이 덤으로 재투영돼 **테스트가 헛돈다**(실측: 갈래를 제거해도 통과했다). 카드는 그대로인데
    // 에이전트 행만 바뀌는 상황을 만들어야 이 가드를 실제로 잠근다.
    try pane_ops.newTermInActivePane(session); // 새 Term이 활성이 되고, 0번이 비활성으로 남는다
    const tab = session.tabs.items[0];
    const pane = tab.panes.items[0];
    if (pane.terms.items.len < 2) return error.SkipZigTest;
    const inactive_index: usize = if (pane.active_term == 0) 1 else 0;
    const inactive = pane.terms.items[inactive_index];
    for (pane.terms.items) |t| {
        t.agent_kind = .claude;
        t.agent_state = .idle;
    }
    sidebar_ops.rebuildSidebar(session) catch {};

    const card_lines_before = sidebar_ops.sidebarCardLines(session, tab);
    const projected: u8 = blk: {
        for (session.sidebar_rows.items) |row| switch (row) {
            .agent => |g| if (g.term == inactive_index) break :blk g.lines,
            else => {},
        };
        return error.SkipZigTest; // 그 행이 투영되지 않았으면 판정할 것이 없다
    };
    const ag: AppSession.WorkspaceSession = .{ .pane = 0, .term = inactive_index };
    try std.testing.expectEqual(sidebar_ops.sidebarAgentRowLines(session, tab, ag), projected);

    // 비활성 Term의 cwd만 투영 **뒤에** 바꾼다. `/tmp`는 저장소가 아니라 브랜치줄이 사라져 줄 수가 줄고,
    // 관측은 커널 폴백보다 우선이므로 이 심기가 실제로 이긴다.
    inactive.rt.observation.cwd.clearRetainingCapacity();
    try inactive.rt.observation.cwd.appendSlice(a, "/tmp");
    inactive.rt.observation.availability = .current;
    const now_lines = sidebar_ops.sidebarAgentRowLines(session, tab, ag);
    if (now_lines == projected) return error.SkipZigTest; // 원래 같은 줄 수면 볼 것이 없다

    // **카드는 안 바뀌었다**는 것이 이 테스트의 전제다. 바뀌었다면 `.card` 갈래가 대신 일해 버려 이 단언이
    // `.agent` 갈래를 검증하지 못한다.
    try std.testing.expectEqual(card_lines_before, sidebar_ops.sidebarCardLines(session, tab));

    // 가드가 그 차이를 보고 다시 투영해야 한다. 안 하면 행 높이와 렌더가 갈려 보조줄이 아래 행을 덮는다.
    sidebar_ops.reprojectSidebarIfRowLinesStale(session);
    for (session.sidebar_rows.items) |row| switch (row) {
        .agent => |g| if (g.term == inactive_index) try std.testing.expectEqual(now_lines, g.lines),
        else => {},
    };
}

// transcript 매핑도 **같은 축**을 쓰고, provider별로 필요한 것만 요구해야 한다. 예전 `pollAgentTranscript`는
// 관측(OSC 7)을 직독한 뒤 `if (cwd.len == 0) return;`로 **둘 다** 막았다. 그래서 두 가지가 함께 깨졌다.
//
//   1. Claude — cwd가 정말 필요한데(`~/.claude/projects/<슬러그>/`) OSC 7이 없는 Term에서 못 풀어 대화가 빈다.
//   2. codex — `refreshCodexTranscript`가 `_ = cwd`로 무시하는데도 그 게이트에 함께 걸렸다. **필요하지도
//      않은 값 때문에** 대화를 못 읽은 것이다.
//
// 여기서는 2를 잠근다: 신원만 세우고 cwd는 비워 둔 codex Term이 `.codex/sessions`의 rollout을 실제로 읽어
// 마지막 대화를 채우는지 본다. 1은 축 자체(`termCwd`)를 다른 테스트가 덮는다.
test "에이전트 대화: codex는 cwd를 몰라도 신원만으로 rollout을 읽는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const a = std.testing.allocator;
    const session = try initSmokeSessionSized(a);
    defer a.destroy(session);
    defer session.deinit();

    // 격리 HOME에 codex rollout 하나를 심는다 — 실제 파일 규칙(`rollout-<ts>-<thread_id>.jsonl`)을 따른다.
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var home_buf: [std.fs.max_path_bytes]u8 = undefined;
    const home = home_buf[0..try tmp.dir.realPath(session.io, &home_buf)];
    // 실제 배치를 따른다: `~/.codex/sessions/YYYY/MM/DD/rollout-<ts>-<thread_id>.jsonl`.
    // `findCodexByThreadId`가 그 날짜 계층을 훑으므로 평평하게 두면 찾지 못한다(첫 시도가 그래서 실패했다).
    for ([_][]const u8{ ".codex", ".codex/sessions", ".codex/sessions/2026", ".codex/sessions/2026/08", ".codex/sessions/2026/08/12" }) |dir|
        try tmp.dir.createDir(session.io, dir, .default_dir);
    const thread_id = "t-cwdless-1";
    var name_buf: [160]u8 = undefined;
    const name = try std.fmt.bufPrint(&name_buf, ".codex/sessions/2026/08/12/rollout-2026-08-12T00-00-00-{s}.jsonl", .{thread_id});
    try tmp.dir.writeFile(session.io, .{
        .sub_path = name,
        .data =
        \\{"type":"session_meta","payload":{"id":"t-cwdless-1","cwd":"/repo","thread_source":"user"}}
        \\{"type":"event_msg","payload":{"type":"user_message","message":"cwd 없이도 읽히나"}}
        \\{"type":"event_msg","payload":{"type":"agent_message","message":"읽힌다"}}
        \\
        ,
    });

    var home_z: [std.fs.max_path_bytes:0]u8 = undefined;
    @memcpy(home_z[0..home.len], home);
    home_z[home.len] = 0;
    const prev_home = std.c.getenv("HOME");
    _ = setenv("HOME", home_z[0..home.len :0].ptr, 1);
    defer if (prev_home) |ph| {
        _ = setenv("HOME", ph, 1);
    };

    const term = session.tabs.items[0].panes.items[0].terms.items[0];
    term.agent_kind = .codex;
    term.agent_state = .idle;
    term.agent_transcript.setIdentity(thread_id);
    // **전제: cwd를 모른다.** 관측은 비어 있고, 커널 폴백이 답하더라도 codex 경로는 그 값을 쓰지 않는다.
    try std.testing.expectEqual(@as(usize, 0), term.rt.observation.cwd.items.len);

    agent_ops.pollAgentTranscript(session, term, true);

    // 예전에는 cwd 게이트에 걸려 여기가 빈 채로 남았다.
    try std.testing.expect(std.mem.indexOf(u8, term.agent_transcript.owned.reply(), "읽힌다") != null);
}

test "에이전트 행: 마지막 대화가 라벨·줄 수·알림 본문에 실린다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const a = std.testing.allocator;
    const session = try initSmokeSessionSized(a);
    defer a.destroy(session);
    defer session.deinit();

    const tab = session.tabs.items[0];
    const term = tab.panes.items[0].terms.items[0];
    term.agent_kind = .claude;
    term.agent_state = .idle;

    // 대화가 없을 때(계약 1: 기록을 못 읽은 상태) — 기존 표시가 그대로다.
    {
        const label = try sidebar_ops.agentRowLabelOwned(session, term);
        defer a.free(label);
        try std.testing.expect(std.mem.indexOf(u8, label, "Claude Code") != null);
    }
    const lines_before = sidebar_ops.sidebarAgentRowLines(session, tab, .{ .pane = 0, .term = 0 });

    term.agent_transcript.owned.setPrompt("배포 스크립트 고쳐줘");
    term.agent_transcript.owned.setReply("네, 수정했습니다");

    // 라벨: 종류 이름 대신 **프롬프트**가 오고, 상태 마커(✓)는 남는다 — 진행 여부를 잃지 않는다.
    {
        const label = try sidebar_ops.agentRowLabelOwned(session, term);
        defer a.free(label);
        try std.testing.expect(std.mem.indexOf(u8, label, "배포 스크립트 고쳐줘") != null);
        try std.testing.expect(std.mem.indexOf(u8, label, "Claude Code") == null);
        try std.testing.expect(std.mem.indexOf(u8, label, "\u{2713}") != null);
    }

    // **본문은 상태가 정한다**(사용자 결정 2026-08-22). 프롬프트를 알아도 «지금» 이 더 급하면 그것을 싣는다.
    // 이 규칙이 없으면 훅 모드에서 프롬프트가 **항상** 있어 상태 문구와 진행 중 세부가 영영 가려진다 —
    // 훅을 켜야만 얻는 정보가 훅을 켠 화면에서만 안 보이는 뒤집힌 상태가 된다.
    {
        term.agent_state = .running;
        term.agent_hook_tool.set("파일 씀");
        const label = try sidebar_ops.agentRowLabelOwned(session, term);
        defer a.free(label);
        try std.testing.expect(std.mem.indexOf(u8, label, "파일 씀") != null); // 무엇을 하는 중인지
        try std.testing.expect(std.mem.indexOf(u8, label, "배포 스크립트 고쳐줘") == null);

        term.agent_state = .blocked;
        const blocked = try sidebar_ops.agentRowLabelOwned(session, term);
        defer a.free(blocked);
        // 사용자의 **행동을 요구하는 유일한 상태**라 기호 하나로 두지 않는다.
        try std.testing.expect(std.mem.indexOf(u8, blocked, maru.i18n.t(.sb_awaiting_input)) != null);
        try std.testing.expect(std.mem.indexOf(u8, blocked, "배포 스크립트 고쳐줘") == null);

        term.agent_hook_tool.clear();
        term.agent_state = .idle;
    }

    // 줄 수: 응답 줄이 하나 늘어야 한다. 늘지 않으면 응답이 행 높이 밖에 그려져 아래 행을 침범한다.
    const lines_after = sidebar_ops.sidebarAgentRowLines(session, tab, .{ .pane = 0, .term = 0 });
    try std.testing.expectEqual(lines_before + 1, lines_after);
    try std.testing.expect(lines_after <= 4); // sidebarGlyphRow의 line_index는 2비트다

    // 알림 본문: provider 문구 뒤에 대화가 붙는다. 프롬프트가 먼저다 — OS 배너는 뒷줄을 자른다.
    {
        const body = try notification_ops.notificationBodyOwned(session, term, "Claude is waiting for your input");
        defer a.free(body);
        const pi = std.mem.indexOf(u8, body, "배포 스크립트 고쳐줘") orelse return error.PromptMissing;
        const ri = std.mem.indexOf(u8, body, "네, 수정했습니다") orelse return error.ReplyMissing;
        try std.testing.expect(std.mem.indexOf(u8, body, "Claude is waiting") != null);
        try std.testing.expect(pi < ri);
    }

    // 대화가 없으면 알림은 provider 문구 그대로 — 기존 동작과 byte-identical이어야 한다.
    term.agent_transcript.reset();
    {
        const body = try notification_ops.notificationBodyOwned(session, term, "Claude is waiting for your input");
        defer a.free(body);
        try std.testing.expectEqualStrings("Claude is waiting for your input", body);
    }
}

// [회귀 2026-08-13] 같은 목록의 두 codex 행에서 **파형이 서로 다른 열에 섰다**(사용자 보고 — 스크린샷).
// 프롬프트를 아는 행은 `◆ ▁▅▇▃ 지금 용량 …`, 아직 모르는 행은 `◆ Codex · ▁▅▇▃ 진행중`이라 폴백만 마커를
// 본문 뒤에 뒀기 때문이다. 두 파형은 같은 `agent_spin_frame`을 쓰므로 어긋난 것은 애니메이션이 아니라 자리다.
//
// 마커 위치는 두 형태를 **함께** 봐야만 판정된다 — 한쪽만 보는 테스트는 어긋남 자체를 표현할 수 없다.
// 그래서 같은 Term에서 프롬프트만 붙였다 떼며 라벨 전문을 비교한다.
test "에이전트 행 라벨: 프롬프트를 알든 모르든 상태 마커가 같은 자리(선두)에 온다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const a = std.testing.allocator;
    const session = try initSmokeSessionSized(a);
    defer a.destroy(session);
    defer session.deinit();

    const term = session.tabs.items[0].panes.items[0].terms.items[0];
    term.agent_kind = .codex;
    term.agent_state = .running;
    // 파형은 프레임마다 바 높이가 달라 문자열이 바뀐다. 고정하지 않으면 아래 기대값이 비결정적이다.
    session.agent_spin_frame = 0;
    const bars = try sidebar_ops.spinnerBarsUtf8(session, a);
    defer a.free(bars);

    // (1) 프롬프트를 모를 때(§7 보강 실패·미도달) — 종류 이름 폴백. 마커가 **맨 앞**이고 `·` 구분자는 없다.
    {
        const label = try sidebar_ops.agentRowLabelOwned(session, term);
        defer a.free(label);
        const expected = try std.fmt.allocPrint(a, "{s} Codex {s}", .{ bars, sidebar_ops.runningLabel() });
        defer a.free(expected);
        try std.testing.expectEqualStrings(expected, label);
    }

    // (2) 프롬프트를 알 때 — 본문만 갈리고 **마커 자리는 그대로**다. 두 라벨의 공통 prefix가 마커라는 것이
    // 이 회귀의 핵심 계약이므로, 프롬프트 포함 여부가 아니라 그 prefix를 단언한다.
    //
    // **본문을 무엇으로 채우는지는 2026-08-22 에 바뀌었다**(사용자 결정): 프롬프트를 알아도 `running` 이면
    // «무엇을 하는 중인가» 를 싣는다. 그 세부는 이 행 말고 보일 자리가 없고, 훅 모드에서는 프롬프트가 **항상**
    // 있어 예전 규칙으로는 영영 가려졌다. 프롬프트는 턴이 끝난 뒤 `idle` 에서 본문이 된다(아래 2b).
    term.agent_transcript.owned.setPrompt("지금 용량 없는데 용량 늘려줘");
    {
        const label = try sidebar_ops.agentRowLabelOwned(session, term);
        defer a.free(label);
        const expected = try std.fmt.allocPrint(a, "{s} {s}", .{ bars, sidebar_ops.runningLabel() });
        defer a.free(expected);
        try std.testing.expectEqualStrings(expected, label);
    }

    // (2b) 같은 프롬프트라도 `idle` 이면 그것이 본문이다 — 마커만 갈린다.
    {
        term.agent_state = .idle;
        defer term.agent_state = .running;
        const label = try sidebar_ops.agentRowLabelOwned(session, term);
        defer a.free(label);
        try std.testing.expectEqualStrings("\u{2713} 지금 용량 없는데 용량 늘려줘", label);
    }

    // (3) running이 아닌 상태도 같은 규칙이다. unknown은 마커 자체가 `·`라, 옛 형태에서는 구분자와 겹쳐
    // `Codex · · 상태 확인 중`으로 점이 둘이었다.
    term.agent_transcript.reset();
    term.agent_state = .unknown;
    {
        const label = try sidebar_ops.agentRowLabelOwned(session, term);
        defer a.free(label);
        // 문구를 박지 않는다 — 상태 라벨이 이제 키를 거치므로 언어가 바뀌면 이 단언만 옛 것을 잰다.
        const expect_unknown = try std.fmt.allocPrint(a, "\u{00b7} Codex {s}", .{maru.i18n.t(.sb_agent_unknown)});
        defer a.free(expect_unknown);
        try std.testing.expectEqualStrings(expect_unknown, label);
    }

    // (4) **claude도 같은 규칙**이다(사용자 확인 2026-08-13). 종류는 `kind_name`으로만 갈리고 경로는 하나지만,
    // 사용자가 보는 화면에서는 두 provider가 같은 목록에 섞이므로 한쪽만 고쳐졌다면 그 목록에서 다시 어긋난다.
    term.agent_kind = .claude;
    term.agent_state = .idle;
    {
        const label = try sidebar_ops.agentRowLabelOwned(session, term);
        defer a.free(label);
        const expect_idle = try std.fmt.allocPrint(a, "\u{2713} Claude Code {s}", .{maru.i18n.t(.sb_agent_idle)});
        defer a.free(expect_idle);
        try std.testing.expectEqualStrings(expect_idle, label);
    }
}

// [적대적 검증 1회차] 위 테스트는 **문자열**만 본다. 사용자가 신고한 것은 화면의 열이므로, 라벨이 맞아도 그
// 문자열이 draw list에서 어디에 놓이는지는 별개다(사이드바에는 "존재하지만 안 보인다"·"보이는 곳과 눌리는 곳이
// 다르다" 계열 회귀가 이미 여러 번 있었다). 그런데 기존 렌더 테스트는 전부 **토글 행(slot 1)**만 본다 —
// 에이전트 행의 파형은 렌더 가드가 없었고, 이번 변경이 바로 그 자리를 옮긴다.
//
// 그래서 두 형태를 **한 화면에 나란히** 세우고 파형의 시작 열을 직접 비교한다. 이것이 신고된 증상 그 자체다.
test "에이전트 행 렌더: 프롬프트 유무가 갈린 두 행의 파형이 같은 열에서 시작한다(정렬 회귀)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const a = std.testing.allocator;
    const session = try initSmokeSessionSized(a);
    defer a.destroy(session);
    defer session.deinit();

    try pane_ops.newTermInActivePane(session); // Term 2개 → 목록이 생긴다(카드 0·토글 1·행 2·행 3)
    const tab = session.tabs.items[0];
    const terms = tab.panes.items[0].terms.items;
    // **같은 종류로 둔다.** 종류가 다르면 색이 갈려 "왜 어긋났는가"에 kind 아이콘 폭까지 섞인다 — 사용자가 본
    // 화면도 codex 둘이었고, 이 테스트가 재려는 것은 오직 라벨 형태에서 오는 열 차이다.
    for (terms) |t| {
        t.agent_kind = .codex;
        t.agent_state = .running;
    }
    terms[1].agent_transcript.owned.setPrompt("지금 용량 없는데 용량 늘려줘");
    session.agent_spin_frame = 0; // 파형은 애니메이션 — 고정하지 않으면 칸 수가 실행마다 다르다

    // 기본 fixture 사이드바는 20칸이라 라벨이 통째로 말줄임된다. 잘린 화면에서는 파형이 아예 안 나와 아래
    // 판정이 공허해진다(토글 요약 테스트가 실측으로 겪은 함정과 같은 것).
    sidebar_ops.setSidebarWidthPx(session, @floatFromInt(sidebar_ops.sidebar_max_pt * session.scale_milli / 1000));
    sidebar_ops.rebuildSidebar(session) catch {};
    var dl = try sidebar_ops.buildSidebarTitleDrawList(session);
    defer dl.deinit(a);

    const codex_brand = agent_ops.agentBrandColor(.codex).?;
    var first_col = [_]?u16{ null, null }; // slot 2·3의 이름줄 첫 파형 열
    var painted = [_]usize{ 0, 0 }; // 그중 브랜드색을 받은 칸
    var kind_glyphs: usize = 0; // 폴백 행에 종류 이름이 그려졌는가(아래 전제)
    for (dl.cells) |c| {
        const slot = c.row / coretext_frame_builder.sidebar_line_base;
        if (slot < 2 or slot > 3) continue;
        if ((c.row % coretext_frame_builder.sidebar_line_base) % 4 != 0) continue; // 이름줄만
        if (slot == 2 and c.codepoint == 'C') kind_glyphs += 1; // 폴백 행의 `Codex`
        if (!sidebar_ops.isAgentSpinnerCp(c.codepoint)) continue;
        const i = slot - 2;
        if (first_col[i] == null or c.col < first_col[i].?) first_col[i] = c.col;
        switch (c.style.foreground) {
            .rgb => |rgb| if (std.meta.eql(rgb, codex_brand)) {
                painted[i] += 1;
            },
            else => {},
        }
    }

    // **전제부터 단언한다.** 두 행이 실제로 다른 형태여야 이 비교가 의미를 갖는다 — 두 행이 같은 모양이면
    // 열이 같은 것이 당연해지고, 통과가 아무것도 증명하지 않는다.
    //
    // 무엇이 두 행을 가르는지가 2026-08-22 에 바뀌었다. 예전에는 «프롬프트가 있나» 였는데, 이제 `running` 은
    // 프롬프트를 알아도 상태 문구를 싣는다(사용자 결정). 그래서 가르는 것은 **폴백이냐** 다 — 프롬프트를
    // 모르는 행만 `<마커> <종류> <문구>` 로 종류 이름을 싣는다. 옛 회귀(폴백이 마커를 뒤로 밀던 것)를 재는
    // 데는 그 행이 정확히 필요하다.
    try std.testing.expect(kind_glyphs >= 1); // 폴백 행의 `Codex`
    {
        const l0 = try sidebar_ops.agentRowLabelOwned(session, terms[0]);
        defer a.free(l0);
        const l1 = try sidebar_ops.agentRowLabelOwned(session, terms[1]);
        defer a.free(l1);
        try std.testing.expect(!std.mem.eql(u8, l0, l1)); // 두 행이 실제로 다른 형태다
    }
    var expected_bars: usize = 0;
    for (0..sidebar_ops.spinner_bar_count) |bar| {
        if (sidebar_ops.isAgentSpinnerCp(sidebar_ops.spinnerBarCp(0, bar))) expected_bars += 1;
    }
    try std.testing.expect(expected_bars > 0);

    // 두 행 모두 파형이 그려지고 브랜드색을 받는다 — 자리를 옮기면서 색칠 게이트(codepoint + row 종류) 밖으로
    // 나가지 않았다는 확인이다.
    try std.testing.expectEqual(expected_bars, painted[0]);
    try std.testing.expectEqual(expected_bars, painted[1]);

    // **핵심**: 두 형태의 파형 시작 열이 같다. 옛 폴백(`Codex · ▁▅▇▃ …`)이면 slot 2가 `Codex · ` 만큼 밀려
    // 여기서 갈린다 — 사용자가 신고한 그 차이다.
    const c0 = first_col[0] orelse return error.SpinnerMissingOnFallbackRow;
    const c1 = first_col[1] orelse return error.SpinnerMissingOnPromptRow;
    try std.testing.expectEqual(c1, c0);

    // **claude도 같은 화면 판정을 받는다.** 위 판정은 codex 둘이라(사용자가 신고한 구성) claude 행이 렌더에서
    // 어긋나도 통과한다 — 실측으로 확인했다: `claude`만 옛 형태로 되돌리는 mutation에서 이 테스트는 green이고
    // 문자열 테스트만 red였다(적대적 검증 2회차). 종류 이름 길이가 다르므로(`Claude Code` vs `Codex`) 폴백에서
    // 마커를 앞으로 빼지 않으면 밀리는 폭도 달라진다. 같은 행을 종류만 바꿔 다시 재는 것으로 그 공백을 덮는다.
    for (terms) |t| t.agent_kind = .claude;
    sidebar_ops.rebuildSidebar(session) catch {};
    var dl2 = try sidebar_ops.buildSidebarTitleDrawList(session);
    defer dl2.deinit(a);

    var claude_col = [_]?u16{ null, null };
    for (dl2.cells) |c| {
        const slot = c.row / coretext_frame_builder.sidebar_line_base;
        if (slot < 2 or slot > 3) continue;
        if ((c.row % coretext_frame_builder.sidebar_line_base) % 4 != 0) continue;
        if (!sidebar_ops.isAgentSpinnerCp(c.codepoint)) continue;
        const i = slot - 2;
        if (claude_col[i] == null or c.col < claude_col[i].?) claude_col[i] = c.col;
    }
    const k0 = claude_col[0] orelse return error.SpinnerMissingOnClaudeFallbackRow;
    const k1 = claude_col[1] orelse return error.SpinnerMissingOnClaudePromptRow;
    try std.testing.expectEqual(k1, k0);
    // 종류가 바뀌어도 **파형의 절대 열은 같다** — 아이콘은 종류와 무관하게 한 슬롯이고, 마커가 그 바로 뒤이기
    // 때문이다. 종류 이름이 파형 앞에 끼어드는 순간 이 등식이 먼저 깨진다.
    try std.testing.expectEqual(c0, k0);
}

test "에이전트 행 ✕: 실행 중이면 확인 모달을 거치고, 마지막 Term에서도 크래시하지 않는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const a = std.testing.allocator;
    const session = try initSmokeSessionSized(a);
    defer a.destroy(session);
    defer session.deinit();

    const tab = session.tabs.items[0];
    const t0 = tab.panes.items[0].terms.items[0];
    t0.agent_kind = .claude;
    t0.agent_state = .running;
    sidebar_ops.rebuildSidebar(session) catch {};

    // 단일 워크스페이스·단일 pane·단일 Term = 캐스케이드가 세션 종료까지 가는 최악 경로. 예전엔 여기서
    // closeTab→latchSessionClose가 해제된 surface에 쓰고 이어지는 rebuild가 빈 pane을 인덱싱했다.
    agent_ops.closeAgentRow(session, 0, 0, 0);

    // 확인 모달이 열렸고(실행 중 명령) 아직 아무것도 파괴되지 않았다 — 즉시 종료가 아니다.
    try std.testing.expectEqual(@as(usize, 1), session.tabs.items.len);
    try std.testing.expectEqual(@as(usize, 1), tab.panes.items[0].terms.items.len);

    // 투영은 teardown 중간 상태에서도 안전해야 한다(빈 pane 방어) — 강제로 비운 뒤 재투영해도 패닉하지 않는다.
    const doomed = tab.panes.items[0].terms.orderedRemove(0);
    term_ops.destroyTerm(session, doomed);
    sidebar_ops.rebuildSidebar(session) catch {};
}

test "사이드바 에이전트 목록: 행 클릭이 워크스페이스·Pane·Term까지 데려간다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const a = std.testing.allocator;
    const session = try initSmokeSessionSized(a);
    defer a.destroy(session);
    defer session.deinit();

    const tab = session.tabs.items[0];
    // pane 2개, 각 pane에 Term 2개 → 그 중 **가려진 탭**(pane0의 term1)에 에이전트를 둔다.
    try pane_ops.splitActivePane(session, .horizontal);
    _ = pane_ops.focusPaneByPtr(session, tab.panes.items[0]);
    try pane_ops.newTermInActivePane(session);
    const target_pane: usize = 0;
    const target_term: usize = 1;
    const t = tab.panes.items[target_pane].terms.items[target_term];
    t.agent_kind = .claude;
    t.agent_state = .idle;
    // 다른 pane을 활성으로 만들어 "가려진 자리"를 재현한다.
    _ = pane_ops.focusPaneByPtr(session, tab.panes.items[1]);
    tab.panes.items[target_pane].active_term = 0; // 그 pane의 활성 탭도 0(에이전트는 1에 있다)
    sidebar_ops.rebuildSidebar(session) catch {};

    // 목록에 그 에이전트 행이 있고, 인덱스 경로가 실제 자리를 가리킨다.
    // 목록은 이제 터미널 Term도 담으므로(2026-08-11) `.agent` variant만으로는 대상을 못 고른다 — 세 Term이 모두
    // 행이라 마지막 `.agent` 행은 pane1의 터미널이다. **라이브 `agent_kind`로** 에이전트 행을 집는다(행이 인덱스만
    // 들고 kind를 캐시하지 않는 계약과 같은 재조회).
    const rows = session.sidebar_rows.items;
    var agent_row: ?usize = null;
    for (rows, 0..) |r, i| switch (r) {
        .agent => |row| {
            const rt = agent_ops.agentTermOf(tab, .{ .pane = row.pane, .term = row.term }) orelse continue;
            if (rt.agent_kind != .none) agent_row = i;
        },
        else => {},
    };
    const ar = agent_row orelse return error.NoAgentRow;
    try std.testing.expectEqual(target_pane, rows[ar].agent.pane);
    try std.testing.expectEqual(target_term, rows[ar].agent.term);

    // 클릭 → 세 단계가 모두 수행된다.
    agent_ops.focusAgentRow(session, rows[ar].agent.tab, rows[ar].agent.pane, rows[ar].agent.term);
    try std.testing.expectEqual(tab.panes.items[target_pane], pane_ops.activePane(session)); // 2) Pane
    try std.testing.expectEqual(target_term, tab.panes.items[target_pane].active_term); // 3) Term 탭

    // 사라진 Term을 가리키는 행은 무동작(stale 인덱스 방어).
    agent_ops.focusAgentRow(session, 0, target_pane, 999);
    try std.testing.expectEqual(target_term, tab.panes.items[target_pane].active_term);
}

test "사이드바 에이전트 목록: Term 전수 나열·개수와 무관하게 접기 토글" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const a = std.testing.allocator;
    const session = try initSmokeSessionSized(a);
    defer a.destroy(session);
    defer session.deinit();

    const sb = chrome.components.sidebar;
    const tab = session.tabs.items[0];

    // (0) 에이전트가 없으면 카드만 — 목록 행이 붙지 않는다.
    sidebar_ops.rebuildSidebar(session) catch {};
    try std.testing.expectEqual(@as(usize, 1), session.sidebar_rows.items.len);

    // (1) 에이전트가 **1개여도 토글**이 붙는다 — 접기는 개수가 아니라 "이 카드를 얼마나 펼쳐 둘 것인가"의
    // 문제라서다(사용자 요청으로 초기 정책을 바꿨다). 카드 + 토글 + 행 1.
    const t0 = tab.panes.items[0].terms.items[0];
    t0.agent_kind = .claude;
    t0.agent_state = .idle;
    sidebar_ops.rebuildSidebar(session) catch {};
    try std.testing.expectEqual(@as(usize, 3), session.sidebar_rows.items.len);
    try std.testing.expect(sb.onAgentToggle(session.sidebar_rows.items, 1));
    try std.testing.expectEqual(@as(u16, 1), session.sidebar_rows.items[1].agent_toggle.count);
    try std.testing.expect(session.sidebar_rows.items[2] == .agent);

    // 1개짜리도 실제로 접힌다 — 토글만 남는다.
    tab.agents_collapsed = true;
    sidebar_ops.rebuildSidebar(session) catch {};
    try std.testing.expectEqual(@as(usize, 2), session.sidebar_rows.items.len);
    try std.testing.expect(session.sidebar_rows.items[1] == .agent_toggle);
    tab.agents_collapsed = false;

    // (2) 같은 pane에 Term을 하나 더 띄워 에이전트 2개 → `N agents` 토글 + 행 2개.
    try pane_ops.newTermInActivePane(session);
    const t1 = tab.panes.items[0].terms.items[1];
    t1.agent_kind = .claude;
    t1.agent_state = .idle;
    sidebar_ops.rebuildSidebar(session) catch {};
    try std.testing.expectEqual(@as(usize, 4), session.sidebar_rows.items.len); // 카드 + 토글 + 행 2
    try std.testing.expect(sb.onAgentToggle(session.sidebar_rows.items, 1));
    try std.testing.expectEqual(@as(u16, 2), session.sidebar_rows.items[1].agent_toggle.count);

    // 행은 **Term 단위 전수**다 — 같은 pane의 두 Term이 각각 행을 갖는다(가려진 탭도 포함, §2).
    try std.testing.expectEqual(@as(usize, 0), session.sidebar_rows.items[2].agent.term);
    try std.testing.expectEqual(@as(usize, 1), session.sidebar_rows.items[3].agent.term);

    // (3) 접으면 행이 사라지고 토글만 남는다(§4).
    tab.agents_collapsed = true;
    sidebar_ops.rebuildSidebar(session) catch {};
    try std.testing.expectEqual(@as(usize, 2), session.sidebar_rows.items.len); // 카드 + 토글
    try std.testing.expect(session.sidebar_rows.items[1] == .agent_toggle);
}

// 목록이 에이전트 전수에서 **Term 전수**로 넓어진 것을 고정한다(사용자 결정 2026-08-11 —
// docs/sidebar-agent-list.md §1·§2). 터미널이 목록에 없으면 가려진 탭에서 도는 셸이 화면에 존재하지 않는데,
// 그것은 "안 보이는 것을 없는 것처럼 만들지 않는다"는 §2 원칙이 에이전트에만 적용되던 빈틈이었다.
//
// 함께 증명하는 것: (a) 에이전트를 돌리는 Term이 **에이전트 행 하나로만** 나오고 터미널 행으로 중복되지
// 않는다(= "터미널이 에이전트 실행 중이면 에이전트만"이 Term 1:1 규율에서 공짜로 나온다), (b) 터미널 1개짜리
// 워크스페이스는 카드 헤더가 곧 그 Term이라 목록을 내지 않는다.
// [사용자 결정 2026-08-12] **running 집계 배지는 `sessions` 토글 행에 산다.** 처음엔 카드(부모 탭)에 두었는데,
// 카드와 그 아래 세션 행에 같은 파형이 겹쳐 보여 "부모 탭에서도 나온다"는 보고를 받았다(사용자 요청: 카드에서 제거).
// 토글 행은 목록의 접힘과 무관하게 **항상 한 줄** 있으므로, 카드에 4번째 줄을 만들지 않고도 "무엇이 몇 개 도는가"가
// 늘 보인다 — 배지를 되살린 원래 근거(접으면 파형이 어디에도 안 남는다)를 카드 없이 지킨다.
//
// 배지는 대표 하나를 고르는 옛 상태줄과 다른 정보다 — "무엇이 몇 개 도는가"를 종류별로 센다. 종류 아이콘은
// 붙이지 않고 **색으로** 가른다(사용자 결정). 개수 1은 숫자를 생략한다(파형이 이미 "하나"를 말한다).
test "사이드바 running 배지: 종류별 running 개수를 세고, 개수 1은 숫자를 생략한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const a = std.testing.allocator;
    const session = try initSmokeSessionSized(a);
    defer a.destroy(session);
    defer session.deinit();
    const tab = session.tabs.items[0];

    // running이 없으면 집계도 0 — 배지는 ""이라 토글 행에 개수 라벨만 남는다.
    {
        const counts = tab_ops.tabRunningCountsByKind(tab);
        try std.testing.expectEqual(@as(u16, 0), counts.total());
        try std.testing.expectEqual(@as(u8, 0), counts.kindCount());
    }

    const first = pane_ops.activePane(session).activeTerm();
    first.agent_kind = .claude;
    first.agent_state = .running;
    {
        const counts = tab_ops.tabRunningCountsByKind(tab);
        try std.testing.expectEqual(@as(u16, 1), counts.claude);
        try std.testing.expectEqual(@as(u8, 1), counts.kindCount());
    }

    // 같은 종류가 하나 더 running이면 개수가 오른다 — 대표 하나로 압축하던 옛 상태줄이 답하지 못한 질문이다.
    try pane_ops.newTermInActivePane(session);
    const second = tab.panes.items[0].terms.items[1];
    second.agent_kind = .claude;
    second.agent_state = .running;
    // 다른 종류도 함께 돌면 **따로** 센다(색으로 구분되는 두 배지가 된다).
    try pane_ops.newTermInActivePane(session);
    const third = tab.panes.items[0].terms.items[2];
    third.agent_kind = .codex;
    third.agent_state = .running;
    {
        const counts = tab_ops.tabRunningCountsByKind(tab);
        try std.testing.expectEqual(@as(u16, 2), counts.claude);
        try std.testing.expectEqual(@as(u16, 1), counts.codex);
        try std.testing.expectEqual(@as(u8, 2), counts.kindCount());
        try std.testing.expectEqual(@as(u16, 3), counts.total());
    }

    // **문자열 형태와 색 구간**을 함께 고정한다. 공백 규칙(파형·개수 사이 한 칸, 종류 사이 두 칸)은 사용자
    // 피드백으로 정해진 것이라 회귀하기 쉽고, 색 구간은 조립과 색칠이 **같은 좌표계**를 봐야 한 칸도 안 밀린다.
    {
        var spans: std.ArrayList(sidebar_ops.BadgeSpan) = .empty;
        defer spans.deinit(a);
        const line = try sidebar_ops.runningBadgeText(session, tab_ops.tabRunningCountsByKind(tab), 0, &spans, 0);
        defer a.free(line);
        // claude 2 + codex 1 → 파형+공백+2, 두 칸, 파형(개수 1은 숫자 생략).
        try std.testing.expect(std.mem.indexOf(u8, line, " 2") != null); // 숫자가 파형에 붙지 않는다
        try std.testing.expect(std.mem.indexOf(u8, line, "  ") != null); // 종류 사이는 두 칸
        try std.testing.expect(!std.mem.endsWith(u8, line, "1")); // 개수 1은 숫자를 붙이지 않는다
        // 배지는 **본문만** 만든다 — 앞의 개수 라벨은 호출자가 붙이므로 여기서 들여쓰기가 새어 들어오면 안 된다.
        try std.testing.expect(!std.mem.startsWith(u8, line, " "));
        // 구간은 종류마다 하나이고, 서로 겹치지 않으며, claude가 먼저다(색이 뒤바뀌면 종류가 뒤바뀐다).
        try std.testing.expectEqual(@as(usize, 2), spans.items.len);
        try std.testing.expectEqual(AgentKind.claude, spans.items[0].kind);
        try std.testing.expectEqual(AgentKind.codex, spans.items[1].kind);
        try std.testing.expect(spans.items[0].end_col <= spans.items[1].start_col);
        try std.testing.expect(spans.items[0].start_col < spans.items[0].end_col);
    }

    // idle은 세지 않는다 — 배지는 "돌고 있는 것"만 말한다(알림이 오는 것과 무관하게 판정이 근거다).
    second.agent_state = .idle;
    third.agent_state = .idle;
    {
        const counts = tab_ops.tabRunningCountsByKind(tab);
        try std.testing.expectEqual(@as(u16, 1), counts.claude);
        try std.testing.expectEqual(@as(u16, 0), counts.codex);
    }

    // 시작 열은 **인자 그대로** 반영돼야 한다. 토글 행에서 배지 앞에는 개수 라벨(`1  `)이 오는데, 그 폭이 span에
    // 안 실리면 색만 왼쪽으로 밀려 파형 대신 라벨이 브랜드색을 받는다 — 조립과 색칠이 같은 좌표계를 봐야 한다는
    // 규율이 깨지는 지점이라 숫자로 고정한다.
    first.agent_state = .running;
    {
        var spans: std.ArrayList(sidebar_ops.BadgeSpan) = .empty;
        defer spans.deinit(a);
        const line = try sidebar_ops.runningBadgeText(session, tab_ops.tabRunningCountsByKind(tab), 7, &spans, 3);
        defer a.free(line);
        try std.testing.expectEqual(@as(usize, 1), spans.items.len);
        try std.testing.expectEqual(@as(u16, 7), spans.items[0].start_col); // prefix 폭만큼 밀려 시작한다
        try std.testing.expectEqual(@as(usize, 3), spans.items[0].slot); // slot도 호출자 것을 그대로 쓴다
    }

    // running이 0이면 **빈 문자열**이고 구간도 없다 — 호출자는 개수 라벨만 그린다(배지 자리에 공백이 남지 않는다).
    first.agent_state = .idle;
    {
        var spans: std.ArrayList(sidebar_ops.BadgeSpan) = .empty;
        defer spans.deinit(a);
        const line = try sidebar_ops.runningBadgeText(session, tab_ops.tabRunningCountsByKind(tab), 4, &spans, 0);
        defer a.free(line);
        try std.testing.expectEqual(@as(usize, 0), line.len);
        try std.testing.expectEqual(@as(usize, 0), spans.items.len);
    }
}

test "사이드바 세션 목록: 터미널도 행이 되고, 에이전트 Term은 한 행으로만 나온다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const a = std.testing.allocator;
    const session = try initSmokeSessionSized(a);
    defer a.destroy(session);
    defer session.deinit();

    const tab = session.tabs.items[0];

    // (0) 터미널 1개 + 에이전트 0 = 목록 없음. 카드 헤더(활성 pane의 활성 Term)가 이미 그 Term의 폴더·브랜치를
    // 그리므로 행을 더하면 같은 정보가 두 번 나오고 모든 카드가 토글만큼 길어진다.
    sidebar_ops.rebuildSidebar(session) catch {};
    try std.testing.expectEqual(@as(usize, 1), session.sidebar_rows.items.len);

    // (1) 에이전트 없이 Term만 2개 → 목록이 생긴다. **예전에는 여기서 아무 행도 안 나왔다**(agent_kind == .none
    // 필터). 토글 개수는 에이전트 수가 아니라 **Term 수**다.
    try pane_ops.newTermInActivePane(session);
    sidebar_ops.rebuildSidebar(session) catch {};
    try std.testing.expectEqual(@as(usize, 4), session.sidebar_rows.items.len); // 카드 + 토글 + 행 2
    try std.testing.expect(chrome.components.sidebar.onAgentToggle(session.sidebar_rows.items, 1));
    try std.testing.expectEqual(@as(u16, 2), session.sidebar_rows.items[1].agent_toggle.count);
    try std.testing.expectEqual(@as(usize, 0), session.sidebar_rows.items[2].agent.term);
    try std.testing.expectEqual(@as(usize, 1), session.sidebar_rows.items[3].agent.term);

    // (2) 그중 하나를 에이전트로 만든다 → **행 수와 개수는 그대로**다. 같은 Term이 에이전트 행 + 터미널 행으로
    // 쪼개지지 않는다는 뜻이고, 이것이 "에이전트 실행 중이면 에이전트만 보인다"의 실체다.
    const t0 = tab.panes.items[0].terms.items[0];
    t0.agent_kind = .claude;
    t0.agent_state = .idle;
    sidebar_ops.rebuildSidebar(session) catch {};
    try std.testing.expectEqual(@as(usize, 4), session.sidebar_rows.items.len);
    try std.testing.expectEqual(@as(u16, 2), session.sidebar_rows.items[1].agent_toggle.count);

    // (3) 두 행의 표현이 갈린다 — 에이전트 행은 상태 문구(✓ 대기중)를, 터미널 행은 Term 라벨을 싣고,
    // gutter 아이콘도 kind 아이콘 vs 없음으로 갈린다.
    const t1 = tab.panes.items[0].terms.items[1];
    const agent_label = try sidebar_ops.agentRowLabelOwned(session, t0);
    defer a.free(agent_label);
    const term_label = try sidebar_ops.agentRowLabelOwned(session, t1);
    defer a.free(term_label);
    try std.testing.expect(std.mem.indexOf(u8, agent_label, maru.i18n.t(.sb_agent_idle)) != null); // 에이전트=상태 문구
    try std.testing.expect(std.mem.indexOf(u8, term_label, maru.i18n.t(.sb_agent_idle)) == null); // 터미널=상태 문구 없음
    try std.testing.expectEqual(icons.codepoint(.sparkle), sidebar_ops.sessionRowIconCodepoint(t0));
    try std.testing.expectEqual(@as(u21, 0), sidebar_ops.sessionRowIconCodepoint(t1)); // 일반 터미널=아이콘 없음
}

// [회귀 2026-08-12] running 배지를 토글 행에 붙인 뒤 **제품 캡처에서 목록이 통째로 사라졌다** — 카드만 남고
// 토글·세션 행이 안 그려졌다. rows에는 토글이 있었으므로(위 테스트가 그것을 이미 고정한다) 원인은 조립 아래,
// 즉 draw list 단계였다. `agent_state = .running`일 때만 재현됐다 — 배지 문자열이 들어가는 유일한 경로다.
//
// 이 테스트는 rows가 아니라 **그려진 결과**를 본다: 토글 슬롯(표시 row 인덱스 1)의 셀이 실제로 나왔는가.
// rows만 보는 테스트는 이 결함을 통과시켰다("존재하지만 안 보인다"는 격차가 정확히 사용자가 본 증상이다).
test "사이드바 토글 행: running 배지가 붙어도 그려진다(목록 소실 회귀)" {
    // 요약 문구를 **코드포인트로** 센다(`진행중`의 세 글자) — 한국어일 때만 성립하므로 언어를 고정한다.
    // 재는 것은 "말줄임이 걸려 요약이 사라지지 않는가"이지 문구가 아니다.
    const lang_before = maru.i18n.lang();
    defer maru.i18n.setLang(lang_before);
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const a = std.testing.allocator;
    const session = try initSmokeSessionSized(a);
    defer a.destroy(session);
    defer session.deinit();
    maru.i18n.setLang(.ko);

    try pane_ops.newTermInActivePane(session); // Term 2개 → 목록이 생긴다
    const tab = session.tabs.items[0];
    // **종류를 섞어 둘 다 running**으로 만든다. 한 종류만이면 배지 파형이 span 경로로 칠해지든 스피너 경로
    // (대표 kind)로 칠해지든 **같은 색**이라, 구간이 통째로 밀려도 결과가 같아 아래 색 판정이 무력해진다
    // (mutation으로 확인: 시작 열을 +1 해도 claude 단일 케이스는 통과한다). 두 종류가 함께 도는 화면에서만
    // "어느 칸이 어느 종류인가"가 색으로 갈리고, 그때 비로소 span이 제 일을 한다.
    const terms = tab.panes.items[0].terms.items;
    terms[0].agent_kind = .claude;
    terms[0].agent_state = .running;
    terms[1].agent_kind = .codex;
    terms[1].agent_state = .running;
    // 파형은 **애니메이션**이라 프레임마다 바 높이가 다르고, 높이 0인 바는 `isAgentSpinnerCp` 게이트를 통과하지
    // 못한다. 프레임을 고정하지 않으면 색칠된 칸 수가 실행마다 달라져 이 테스트가 비결정적이 된다(실제로 같은
    // 코드에서 `found 2`·`found 1`이 번갈아 나왔다). 기대값도 상수로 박지 않고 **이 프레임에서 파생**한다.
    session.agent_spin_frame = 0;
    sidebar_ops.rebuildSidebar(session) catch {};
    try std.testing.expect(chrome.components.sidebar.onAgentToggle(session.sidebar_rows.items, 1));

    var dl = try sidebar_ops.buildSidebarTitleDrawList(session);
    defer dl.deinit(a);

    // 토글 행 slot = 표시 row 인덱스 1(카드가 0). 셀이 하나도 없으면 그 행은 화면에서 사라진 것이다.
    var toggle_cells: usize = 0;
    for (dl.cells) |c| {
        if (c.row / coretext_frame_builder.sidebar_line_base == 1) toggle_cells += 1;
    }
    try std.testing.expect(toggle_cells > 0);

    // **셀이 surface 폭 안에 있어야 한다.** 여기가 제품과 갈린 지점이었다 — draw list에 셀이 있어도 `col`이
    // `size.cols`를 넘으면 셰이핑 단계가 `ShapedRecordOutsideSurface`로 실패하고, 그 프레임의 사이드바 텍스트가
    // 통째로 사라진다(사용자가 본 "목록이 없어졌다"). 셀 존재만 보는 위 검사는 그것을 통과시킨다.
    for (dl.cells) |c| {
        try std.testing.expect(c.col < dl.size.cols);
    }

    // **두 종류 배지가 각자 브랜드색으로 칠해졌는가** — span 정합의 end-to-end 판정이다.
    //
    // 조립(`runningBadgeText`)이 기록한 열 구간과 색칠 루프가 보는 `c.col`은 서로 다른 코드가 계산한다. 개수 라벨
    // 폭을 한 칸이라도 잘못 넘기면 구간이 밀려, 밀려난 칸이 span 대신 **스피너 경로(대표 kind 색)** 로 떨어진다 —
    // 대표는 하나뿐이므로 두 색의 칸 수가 곧바로 어긋난다. 좌표를 직접 비교하지 않고 결과 색을 세는 이유는 그것이
    // 사용자가 실제로 보는 것이기 때문이고, 종류를 섞어야만 이 판정이 힘을 갖는다(위 주석).
    const claude_brand = agent_ops.agentBrandColor(.claude).?;
    const codex_brand = agent_ops.agentBrandColor(.codex).?;
    var claude_painted: usize = 0;
    var codex_painted: usize = 0;
    for (dl.cells) |c| {
        if (c.row / coretext_frame_builder.sidebar_line_base != 1) continue;
        if (!sidebar_ops.isAgentSpinnerCp(c.codepoint)) continue;
        switch (c.style.foreground) {
            .rgb => |rgb| {
                if (std.meta.eql(rgb, claude_brand)) claude_painted += 1;
                if (std.meta.eql(rgb, codex_brand)) codex_painted += 1;
            },
            else => {},
        }
    }
    // 기대값은 **고정한 프레임에서 파생**한다 — 그 프레임에 높이 0인 바가 있으면 게이트를 통과하는 칸이 그만큼
    // 적다. 상수 `spinner_bar_count`로 박으면 파형 테이블이 바뀔 때 이 테스트가 애먼 곳에서 깨진다.
    var expected_bars: usize = 0;
    for (0..sidebar_ops.spinner_bar_count) |bar| {
        if (sidebar_ops.isAgentSpinnerCp(sidebar_ops.spinnerBarCp(0, bar))) expected_bars += 1;
    }
    try std.testing.expect(expected_bars > 0); // 파형이 한 칸도 안 보이는 프레임을 골랐다면 판정이 무의미하다
    // 종류마다 자기 칸 수만큼. 구간이 밀리면 밀려난 칸이 대표 kind 색으로 떨어져 한쪽이 모자라고 다른 쪽이 넘친다.
    try std.testing.expectEqual(expected_bars, claude_painted);
    try std.testing.expectEqual(expected_bars, codex_painted);

    // **접으면 대표 상태 요약이 같은 줄에 붙는다.** 그 요약은 파형을 싣지 않는다(`agentSummaryLine`) — 배지가
    // 이미 같은 프레임의 파형을 그리는 줄이라, 상태줄을 통째로 실으면 같은 애니메이션이 한 줄에 두 번 나온다
    // (사용자 결정 2026-08-13, docs/sidebar-agent-list.md §2). 배지가 접힘에서도 남아야 한다는 계약
    // («접힘과 무관하게 항상»)도 여기서 함께 지켜진다.
    tab.agents_collapsed = true;
    // **폭을 넓히고 본다.** 기본 fixture 사이드바는 20칸이라 요약이 통째로 `…`로 잘려, 파형이 중복돼도 화면에
    // 나타나지 않는다 — 그 폭에서는 아래 판정이 공허하다(실측: 요약을 상태줄로 되돌리는 mutation을 넣어도 통과했다).
    // 잘리지 않는 폭에서만 "요약이 파형을 얹지 않는다"가 실제로 시험된다.
    sidebar_ops.setSidebarWidthPx(session, @floatFromInt(sidebar_ops.sidebar_max_pt * session.scale_milli / 1000));
    sidebar_ops.rebuildSidebar(session) catch {};
    var dl2 = try sidebar_ops.buildSidebarTitleDrawList(session);
    defer dl2.deinit(a);

    // 요약이 **정말 그려졌는지** 먼저 확인한다. 이것이 위 폭 확장의 근거이자 아래 판정의 전제다 — 요약이 잘려
    // 사라지면 파형 칸 수는 저절로 맞아떨어지고, 그 통과는 아무것도 증명하지 않는다.
    var summary_glyphs: usize = 0;
    for (dl2.cells) |c| {
        if (c.row / coretext_frame_builder.sidebar_line_base != 1) continue;
        // `진행중`의 세 글자 — 말줄임(`…`)이 걸리면 하나도 남지 않는다.
        if (c.codepoint == '\u{c9c4}' or c.codepoint == '\u{d589}' or c.codepoint == '\u{c911}') summary_glyphs += 1;
    }
    try std.testing.expectEqual(@as(usize, 3), summary_glyphs);

    var claude2: usize = 0;
    var codex2: usize = 0;
    for (dl2.cells) |c| {
        if (c.row / coretext_frame_builder.sidebar_line_base != 1) continue;
        if (!sidebar_ops.isAgentSpinnerCp(c.codepoint)) continue;
        switch (c.style.foreground) {
            .rgb => |rgb| {
                if (std.meta.eql(rgb, claude_brand)) claude2 += 1;
                if (std.meta.eql(rgb, codex_brand)) codex2 += 1;
            },
            else => {},
        }
    }
    // 판정은 **등호**다. 종류마다 자기 칸이 그대로 남아야 하고(«접힘과 무관하게 항상»), 그 위에 요약 파형이
    // 얹히지 않아야 한다 — 대표 kind는 하나뿐이므로 요약이 파형을 다시 싣는 순간 그쪽 종류만 칸 수가 늘어
    // 여기서 걸린다(파형 중복 회귀 가드). 배지가 접힘에서 사라지거나 구간이 밀리면 반대로 모자라 걸린다.
    try std.testing.expectEqual(expected_bars, claude2);
    try std.testing.expectEqual(expected_bars, codex2);

    // **한 종류만 도는 경우**(여기선 codex)도 시작 자리가 같아야 한다. 조립은 종류 사이 간격을 `first` 분기로
    // 넣는데, 그 분기가 첫 배지에도 간격을 붙이면 배지 전체가 오른쪽으로 밀리고 색만 어긋난다 — claude·codex가
    // 함께 도는 위 화면에서는 **두 번째** 배지만 틀어져 가려지기 쉬운 실패다. 종류 순서상 뒤에 오는 codex를
    // 단독으로 세우는 것이 이 분기를 가장 세게 친다(첫 항목이 건너뛰어진 뒤 first가 유지되는지).
    tab.agents_collapsed = false;
    terms[0].agent_kind = .codex;
    sidebar_ops.rebuildSidebar(session) catch {};
    var dl3 = try sidebar_ops.buildSidebarTitleDrawList(session);
    defer dl3.deinit(a);

    var codex_only: usize = 0;
    var claude_leak: usize = 0;
    for (dl3.cells) |c| {
        if (c.row / coretext_frame_builder.sidebar_line_base != 1) continue;
        if (!sidebar_ops.isAgentSpinnerCp(c.codepoint)) continue;
        switch (c.style.foreground) {
            .rgb => |rgb| {
                if (std.meta.eql(rgb, codex_brand)) codex_only += 1;
                if (std.meta.eql(rgb, claude_brand)) claude_leak += 1;
            },
            else => {},
        }
    }
    // 배지는 하나(codex 2개 → 파형 + 숫자). 밀리면 파형 일부가 구간 밖으로 나가 칸 수가 줄고, claude가 하나도
    // 안 도는데 코랄이 보이면 구간이 남의 종류를 칠한 것이다.
    try std.testing.expectEqual(expected_bars, codex_only);
    try std.testing.expectEqual(@as(usize, 0), claude_leak);
}

// [적대적 검증 7회차] `badge_spans`는 **모든 토글 행의 구간을 한 배열**에 담고 `span.slot`으로만 갈린다. 워크스페이스가
// 여럿이면 그 매칭이 유일한 방어선인데, 지금까지의 테스트는 카드가 하나뿐이라 slot이 언제나 1이어서 이 방어가 한 번도
// 시험되지 않았다(slot을 무시해도 통과한다).
//
// 두 워크스페이스에 **서로 다른 종류**를 두면 교차가 색으로 드러난다: claude만 도는 카드의 토글 행에 청록이 한 칸이라도
// 보이면 옆 워크스페이스의 구간이 남의 행을 칠한 것이다. 각 카드의 대표 kind가 자기 종류라서 스피너 경로로 칠해져도
// 자기 색이 나오므로, 이 판정은 **오염만** 정확히 겨냥한다.
test "사이드바 배지: 워크스페이스가 여럿이어도 구간이 남의 행을 칠하지 않는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const a = std.testing.allocator;
    const session = try initSmokeSessionSized(a);
    defer a.destroy(session);
    defer session.deinit();
    session.agent_spin_frame = 0;

    // 워크스페이스 A: claude 2개
    try pane_ops.newTermInActivePane(session);
    for (session.tabs.items[0].panes.items[0].terms.items) |t| {
        t.agent_kind = .claude;
        t.agent_state = .running;
    }
    // 워크스페이스 B: codex 2개
    _ = try tab_ops.newTab(session);
    try pane_ops.newTermInActivePane(session);
    const tab_b = session.tabs.items[1];
    for (tab_b.panes.items[0].terms.items) |t| {
        t.agent_kind = .codex;
        t.agent_state = .running;
    }
    sidebar_ops.rebuildSidebar(session) catch {};

    // 토글 행 slot을 **찾아서** 쓴다 — 행 구성(카드 줄 수·목록 길이)에 인덱스를 하드코딩하면 이 테스트가 엉뚱한
    // 이유로 깨진다.
    var toggle_a: ?usize = null;
    var toggle_b: ?usize = null;
    for (session.sidebar_rows.items, 0..) |row, i| switch (row) {
        .agent_toggle => |t| {
            if (t.tab == 0) toggle_a = i else if (t.tab == 1) toggle_b = i;
        },
        else => {},
    };
    try std.testing.expect(toggle_a != null and toggle_b != null);

    var dl = try sidebar_ops.buildSidebarTitleDrawList(session);
    defer dl.deinit(a);

    const claude_brand = agent_ops.agentBrandColor(.claude).?;
    const codex_brand = agent_ops.agentBrandColor(.codex).?;
    var a_claude: usize = 0;
    var a_codex: usize = 0;
    var b_codex: usize = 0;
    var b_claude: usize = 0;
    for (dl.cells) |c| {
        if (!sidebar_ops.isAgentSpinnerCp(c.codepoint)) continue;
        const slot = c.row / coretext_frame_builder.sidebar_line_base;
        const rgb = switch (c.style.foreground) {
            .rgb => |v| v,
            else => continue,
        };
        if (slot == toggle_a.?) {
            if (std.meta.eql(rgb, claude_brand)) a_claude += 1;
            if (std.meta.eql(rgb, codex_brand)) a_codex += 1;
        } else if (slot == toggle_b.?) {
            if (std.meta.eql(rgb, codex_brand)) b_codex += 1;
            if (std.meta.eql(rgb, claude_brand)) b_claude += 1;
        }
    }
    var expected_bars: usize = 0;
    for (0..sidebar_ops.spinner_bar_count) |bar| {
        if (sidebar_ops.isAgentSpinnerCp(sidebar_ops.spinnerBarCp(0, bar))) expected_bars += 1;
    }
    try std.testing.expectEqual(expected_bars, a_claude);
    try std.testing.expectEqual(expected_bars, b_codex);
    try std.testing.expectEqual(@as(usize, 0), a_codex); // 옆 워크스페이스(codex) 구간이 새어 들어왔다
    try std.testing.expectEqual(@as(usize, 0), b_claude);

    // [적대적 검증 12회차] 사이드바를 좁혀 이름줄이 잘릴 때 말줄임 `…`이 배지 구간에 들어가 브랜드색을 받는지
    // 노렸다. **재현하지 못했다** — 폭 90에서는 `…`이 배지 구간 뒤(줄 끝)에 오고, 72에서는 토글 행에 `…` 자체가
    // 나오지 않으며, 56은 사이드바가 성립하지 않는다(`NoSidebar`). 배지가 줄 앞부분이라 구간과 겹치는 창이 아주
    // 좁은 것으로 보인다.
    //
    // 색칠 쪽 codepoint 게이트(`badge_glyph`)는 **그래도 남긴다**: 스피너 경로가 이미 같은 규율을 갖고 있어
    // 일관되고 비용이 없다. 다만 그 게이트를 잠그는 판정은 여기 두지 않는다 — 재현하지 못한 것을 테스트로 굳히면
    // 무엇을 지키는지 모르는 채 나중에 애먼 이유로 깨진다.
}

test "workspaceStatusLine: running=파형, blocked=입력 대기, idle=대기중, unknown=상태 확인" {
    // 기대값이 한국어 상태 문구다 — 재는 것은 **어느 상태로 분류하는가**이고 그 판정은 문장으로 봐야
    // 드러난다. 고정은 아래 `init` **뒤**에 건다(init 이 ui.language 를 읽어 언어를 세운다).
    const lang_before = maru.i18n.lang();
    defer maru.i18n.setLang(lang_before);

    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    maru.i18n.setLang(.ko);
    const tab = tab_ops.activeTab(session);
    const term = tab.activePane().activeTerm();

    // running: 파형 바로 시작 + "진행중"으로 끝. 대표 종류=claude.
    term.agent_kind = .claude;
    term.agent_state = .running;
    {
        const s = try sidebar_ops.workspaceStatusLine(session, tab);
        defer allocator.free(s);
        try std.testing.expect(std.mem.endsWith(u8, s, "진행중"));
        const first_len = std.unicode.utf8ByteSequenceLength(s[0]) catch 1;
        const first_cp = std.unicode.utf8Decode(s[0..first_len]) catch 0;
        try std.testing.expect(sidebar_ops.isAgentSpinnerCp(first_cp)); // 선두가 이퀄라이저 바
    }
    try std.testing.expectEqual(AgentKind.claude, tab_ops.tabAgentKind(tab));

    // blocked는 running보다 높은 대표 상태다.
    term.agent_state = .blocked;
    {
        const s = try sidebar_ops.workspaceStatusLine(session, tab);
        defer allocator.free(s);
        try std.testing.expectEqualStrings("? 입력 대기", s);
    }

    // idle은 완료로 단정하지 않고 입력 가능한 대기 상태로 표시한다.
    term.agent_state = .idle;
    {
        const s = try sidebar_ops.workspaceStatusLine(session, tab);
        defer allocator.free(s);
        try std.testing.expectEqualStrings("\u{2713} 대기중", s);
    }

    term.agent_state = .unknown;
    {
        const s = try sidebar_ops.workspaceStatusLine(session, tab);
        defer allocator.free(s);
        try std.testing.expectEqualStrings("\u{00b7} 상태 확인 중", s);
    }

    // none: 상태줄 빈 문자열(그 줄 생략). tabAgentKind 폴백도 none.
    term.agent_kind = .none;
    term.agent_state = .idle;
    {
        const s = try sidebar_ops.workspaceStatusLine(session, tab);
        defer allocator.free(s);
        try std.testing.expectEqual(@as(usize, 0), s.len);
    }
    try std.testing.expectEqual(AgentKind.none, tab_ops.tabAgentKind(tab));
}

// 토글 행의 **접힘 요약**은 상태줄과 running에서만 갈린다. 그 줄에는 running 집계 배지가 접힘과 무관하게 늘 같은
// 파형을 그리므로(docs/sidebar-agent-list.md §2), 요약이 상태줄을 통째로 실으면 같은 프레임의 파형이 한 줄에 두 번
// 나온다 — 사용자가 본 `▶ 1  ▁▅▇▃ · ▁▅▇▃ 진행중`이 그것이다(결정 2026-08-13). 이 테스트는 갈리는 자리가 running
// **하나뿐**임을 고정한다: 나머지 상태의 마커(`?`·`✓`·`·`)까지 벗기면 요약이 상태 없는 문구가 된다.
test "agentSummaryLine: running만 파형을 뺀 문구, 나머지 상태는 상태줄과 동일" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    const term = tab_ops.activeTab(session).activePane().activeTerm();
    term.agent_kind = .claude;

    term.agent_state = .running;
    {
        const summary = try sidebar_ops.agentSummaryLine(session, term);
        defer allocator.free(summary);
        // 문구만 — 파형이 한 칸이라도 남으면 그 줄에서 배지와 겹친다.
        try std.testing.expectEqualStrings(sidebar_ops.runningLabel(), summary);
        var it = std.unicode.Utf8Iterator{ .bytes = summary, .i = 0 };
        while (it.nextCodepoint()) |cp| try std.testing.expect(!sidebar_ops.isAgentSpinnerCp(cp));
        // 반면 상태줄은 파형을 그대로 유지한다(카드·목록 행이 쓰는 자리 — 거기엔 배지가 없다).
        const status = try sidebar_ops.agentStatusLine(session, term);
        defer allocator.free(status);
        const first_len = std.unicode.utf8ByteSequenceLength(status[0]) catch 1;
        try std.testing.expect(sidebar_ops.isAgentSpinnerCp(std.unicode.utf8Decode(status[0..first_len]) catch 0));
        try std.testing.expect(std.mem.endsWith(u8, status, sidebar_ops.runningLabel()));
    }

    // 나머지 상태는 **글자 하나 안 바뀐다** — 배지는 running만 세므로 이 상태들의 마커·문구를 대신 말해주지 않는다.
    for ([_]@TypeOf(term.agent_state){ .blocked, .idle, .unknown }) |state| {
        term.agent_state = state;
        const summary = try sidebar_ops.agentSummaryLine(session, term);
        defer allocator.free(summary);
        const status = try sidebar_ops.agentStatusLine(session, term);
        defer allocator.free(status);
        try std.testing.expectEqualStrings(status, summary);
    }

    // 에이전트가 아니면 빈 문자열(그 자리에 요약을 붙이지 않는다) — 상태줄과 같은 규율.
    term.agent_kind = .none;
    term.agent_state = .running; // kind가 none이면 상태는 의미가 없다: running 분기가 kind를 먼저 봐야 한다.
    {
        const summary = try sidebar_ops.agentSummaryLine(session, term);
        defer allocator.free(summary);
        try std.testing.expectEqual(@as(usize, 0), summary.len);
    }
}

// 상단 탭 바 running 표시는 파형(5칸)이 아니라 **정적 1칸 플래그 ●**(U+25CF) — tmux 창-플래그 관례로 이름 폭을 거의 안
// 먹는다(code-review max #1). flagPrefixedLabel이 running이면 "● {이름}", 아니면 이름만 돌려준다.
test "flagPrefixedLabel: running=●+이름, 아니면 이름만" {
    const allocator = std.testing.allocator;
    const run = try AppSession.flagPrefixedLabel(allocator, "svc", true);
    defer allocator.free(run);
    var flag: [4]u8 = undefined;
    const n = std.unicode.utf8Encode(agent_running_flag, &flag) catch 0;
    try std.testing.expect(std.mem.startsWith(u8, run, flag[0..n])); // 선두가 ●
    try std.testing.expect(std.mem.endsWith(u8, run, "svc"));
    const off = try AppSession.flagPrefixedLabel(allocator, "svc", false);
    defer allocator.free(off);
    try std.testing.expectEqualStrings("svc", off); // 아니면 이름만(플래그 없음)
}

// agentDisplayVisible(pollAgentKinds/State의 metal_dirty 게이트)은 **화면에 running 표시가 보이는 탭**만 true —
// 접힘/최소크롬 + 비활성 탭이면 진짜 안 보여 false(백그라운드 Term churn으로 헛 재렌더 방지). 여기선 단일 탭이라
// (탭0=활성) 탭바(paneBarHeightPx>0)만으로도 true이고, 접힘+비활성으로 만들면 false가 되는 걸 고정한다.
test "도크 뷰 스위처: 호버는 슬롯 위에서만 포인터가 바뀐다" {
    // 슬롯 위=클릭 가능(pointingHand), 바 안 여백=화살표. 렌더 강조와 커서가 같은 판정을 쓰는지 함께 본다.
    const bar = chrome.components.dock_view_bar.Rect{ .x = 100, .y = 40, .w = 200, .h = 24 };
    const cw: u32 = 10;
    try std.testing.expectEqual(@as(usize, 0), chrome.components.dock_view_bar.slotAtPoint(bar, cw, 110, 50).?);
    try std.testing.expectEqual(@as(usize, 2), chrome.components.dock_view_bar.slotAtPoint(bar, cw, 190, 50).?);
    // **폭을 `slot_count` 에서 유도한다.** 여기 숫자를 적어 두면 뷰를 하나 더할 때 이 test 가 계약이 아니라
    // 옛 슬롯 수를 지킨다 — 실제로 3→4 에서 그렇게 깨졌다(x=230 이 여백에서 슬롯 안으로 바뀌었다).
    const bar_mod = chrome.components.dock_view_bar;
    const slots_px: u32 = @intCast(bar_mod.slot_cols * cw * bar_mod.slot_count);
    // 마지막 슬롯 **안**은 그 index 다.
    try std.testing.expectEqual(
        @as(usize, bar_mod.slot_count - 1),
        bar_mod.slotAtPoint(bar, cw, bar.x + slots_px - 1, 50).?,
    );
    // 슬롯이 끝나면 그 뒤는 여백이라 null(커서도 default 가 된다).
    try std.testing.expect(bar_mod.slotAtPoint(bar, cw, bar.x + slots_px, 50) == null);
}

test "도크 뷰 스위처: 슬롯 index 대응과 포커스 되돌림" {
    // chrome 컴포넌트는 도메인 enum을 모르므로(레이어 경계) 뷰↔슬롯 대응은 session이 소유한다. 두 곳에
    // 흩어지면 그린 자리와 눌리는 자리가 어긋나므로 왕복을 여기서 못박는다.
    try std.testing.expectEqual(dock_panel.View.explorer, dock_ops.dockViewForSlot(0).?);
    try std.testing.expectEqual(dock_panel.View.source_control, dock_ops.dockViewForSlot(1).?);
    try std.testing.expect(dock_ops.dockViewForSlot(chrome.components.dock_view_bar.slot_count) == null);
}

test "agentDisplayVisible: 카드·탭바 안 보이면 false (재렌더 게이트)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    tab_ops.recomputeVisibleTabs(session);
    session.cell_height_px = 20; // paneBarHeightPx()>0 되게(탭 바 분기 검증용) — 0이면 바 없음 취급

    session.sidebar_collapsed = false;
    try std.testing.expect(agent_ops.agentDisplayVisible(session, 0)); // 펼침 → 카드 보임 → true

    // 카드도 없고(접힘) 탭바도 없게(chrome_minimal → paneBarHeightPx=0) 만들면 false.
    session.sidebar_collapsed = true;
    session.chrome_minimal = true;
    try std.testing.expect(!agent_ops.agentDisplayVisible(session, 0)); // 카드·탭바 둘 다 없음 → false

    // 접힘이어도 활성 탭(0)의 탭 바가 있으면 true(탭바 플래그 갱신 필요).
    session.chrome_minimal = false;
    try std.testing.expect(agent_ops.agentDisplayVisible(session, 0)); // 접힘이지만 활성 탭 탭바 → true

    // 활성 탭이 아니고(idx 99) 접힘이면 카드·탭바 둘 다 없음 → false.
    try std.testing.expect(!agent_ops.agentDisplayVisible(session, 99));
}

// anyAgentRunning은 **사이드바 카드의 애니메이션 파형**이 실제로 보일 때만 true여야 한다(매 130ms full-grid 재투영 낭비
// 회피, code-review high #1). 탭 바 running 표시는 **정적 플래그(●)**라 이 위상 게이트와 무관하다(상태 변화 시에만 dirty).
// 따라서: 펼침 + 보이는 running 탭 → true; 접힘·chrome_minimal → false(사이드바 없음); 검색 필터아웃 → false(카드 없음).
// running 판정은 **어느 pane/Term이든**(tabHasRunningAgent)이라 활성 Term을 running으로 두면 그 탭이 running으로 잡힌다.
test "anyAgentRunning: 펼침+보이는 running=true, 접힘·필터아웃=false (사이드바 파형 게이트)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    tab_ops.activeTab(session).activePane().activeTerm().agent_state = .running; // 이 워크스페이스가 running(어느 Term이든)
    tab_ops.recomputeVisibleTabs(session); // 검색 없음 → visible_tabs = 전체(1개)
    try std.testing.expect(session.sidebar_rows.items.len >= 1);

    session.sidebar_collapsed = false;
    try std.testing.expect(agent_ops.anyAgentRunning(session)); // 펼침 + 보이는 running → true

    session.sidebar_collapsed = true;
    try std.testing.expect(!agent_ops.anyAgentRunning(session)); // 접힘 → 카드 파형 안 보임 → false(탭바 플래그는 정적이라 무관)

    session.sidebar_collapsed = false;
    session.sidebar_rows.clearRetainingCapacity(); // 검색 필터로 카드 숨김
    try std.testing.expect(!agent_ops.anyAgentRunning(session)); // 필터아웃 → 카드 없음 → false
}

test "advanceAgentSpinner: 출력 독립 + wall-clock 경과 기반 위상 진행(굶김·cadence 회귀)" {
    // primary(§10.5): 스피너 advance가 updateCursorBlink(출력 없는 tick에만 호출)에 있어 연속 출력이 굶겨 멈췄다 →
    // advanceAgentSpinner를 출력 게이트 밖에서 호출(출력 인자 없음 = 출력 독립). secondary(§10.5): 위상 진행을 tick
    // 카운트가 아니라 **wall-clock 경과**로 → tick rate가 떨어져도 실시간을 따라가고 stall 후 여러 프레임 catch-up.
    // 이 테스트는 baseline(agent_spin_last_ns)을 과거로 밀어 경과분만큼 위상이 진행되는지 결정적으로 고정한다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    const term = session.tabs.items[0].activePane().activeTerm();
    const interval_ns: i128 = @as(i128, agent_ops.agent_spin_interval_ms) * std.time.ns_per_ms;
    const wave_len: u8 = @intCast(spinner_wave.len);

    // 에이전트 없음 → 여러 번 돌려도 위상 불변 + chrome_dirty 안 세움 + baseline 0 유지(idle 재투영 없음).
    session.chrome_dirty = false;
    const f0 = session.agent_spin_frame;
    for (0..5) |_| agent_ops.advanceAgentSpinner(session);
    try std.testing.expectEqual(f0, session.agent_spin_frame);
    try std.testing.expect(!session.chrome_dirty);
    try std.testing.expectEqual(@as(i128, 0), session.agent_spin_last_ns);

    // running 에이전트 + 사이드바에 그 탭 보임. 첫 호출은 baseline만 세팅(위상 불변) — 이후 wall-clock 경과로 진행.
    term.agent_state = .running;
    term.agent_kind = .claude;
    try session.sidebar_rows.append(allocator, .{ .card = .{ .tab = 0, .active = true, .label = "", .depth = 0 } }); // 사이드바에 탭0 카드 보임(collapsed/minimal 기본 false)
    session.chrome_dirty = false;
    agent_ops.advanceAgentSpinner(session); // baseline 설정
    try std.testing.expectEqual(f0, session.agent_spin_frame); // 아직 경과 0 → 불변
    try std.testing.expect(!session.chrome_dirty);
    try std.testing.expect(session.agent_spin_last_ns != 0);

    // baseline을 2 interval 과거로 밀어 2프레임 경과를 모사 → 한 번 호출에 위상 +2(tick 카운트 아님) + chrome_dirty.
    session.agent_spin_last_ns = std.Io.Clock.awake.now(session.io).nanoseconds - 2 * interval_ns;
    session.chrome_dirty = false;
    agent_ops.advanceAgentSpinner(session);
    try std.testing.expectEqual(@as(u8, (f0 + 2) % wave_len), session.agent_spin_frame); // catch-up 2프레임
    try std.testing.expect(session.chrome_dirty);

    // 방금 진행해 baseline이 ~현재라, 곧바로 다시 불러도 한 주기 안 지나 위상 불변(경과 기반 정확).
    session.chrome_dirty = false;
    agent_ops.advanceAgentSpinner(session);
    try std.testing.expectEqual(@as(u8, (f0 + 2) % wave_len), session.agent_spin_frame);
    try std.testing.expect(!session.chrome_dirty);
}

test "activateSurfaceById: surface.id로 (탭·split panel·가로탭)을 역조회해 그 자리로 활성화한다" {
    // OSC 9/777 데스크톱 알림 클릭이 발신 터미널로 점프하는 경로의 핵심이다. Swift는 창 토큰으로
    // '어느 창(세션)'까지만 고르고, 그 세션 안에서 surface_id로 '어느 탭/split panel/가로탭'인지 찾아 포커스하는 건
    // Zig가 소유한다. 순서(switchTab→focusPaneByPtr→focusTerm)가 틀리면 비활성 탭의 panel/term을 못 찾으므로,
    // 비활성 탭의 둘째 panel 둘째 가로탭을 표적으로 삼아 세 단계 모두 정확히 들어가는지 검증한다. 터미널에서
    // 중요한 이유: 알림은 "지금 안 보는 터미널"이 보내므로, 클릭이 정확히 그 화면을 되살리지 못하면 기능이 무의미하다.
    if (builtin.os.tag != .macos) return error.SkipZigTest; // splitActivePane/newTab/newTermInActivePane = 실 PTY/CoreText
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.backing_width_px = session.sidebar_width_px + 800; // split/resize가 의미 있으려면 backing 필요
    session.backing_height_px = 600;
    session.window_padding_px = .{};

    // 표적: 비활성 탭(t1)의 둘째 panel(우측 split)의 둘째 가로탭. 만든 직후 활성이라 activeSurface로 id를 잡는다.
    _ = try tab_ops.newTab(session); // tabs [t0, t1], 활성 t1
    try pane_ops.splitActivePane(session, .horizontal); // t1: pane [p0, p1], 활성 p1
    try pane_ops.newTermInActivePane(session); // p1: term [tm0, tm1], 활성 tm1
    const target_id = term_ops.activeSurface(session).id;
    try std.testing.expectEqual(@as(usize, 1), session.app_window.active_tab);
    try std.testing.expectEqual(@as(usize, 1), tab_ops.activeTab(session).active_pane);
    try std.testing.expectEqual(@as(usize, 1), pane_ops.activePane(session).active_term);

    // 활성을 다른 워크스페이스(t0)로 옮겨, 활성화가 탭 경계를 넘는지(단순 no-op이 아닌지) 본다.
    try std.testing.expect(tab_ops.switchTab(session, 0));
    try std.testing.expectEqual(@as(usize, 0), session.app_window.active_tab);

    // 알림 클릭 모사: id로 끝까지(탭→panel→가로탭) 정확히 점프.
    try std.testing.expect(term_ops.activateSurfaceById(session, target_id));
    try std.testing.expectEqual(@as(usize, 1), session.app_window.active_tab);
    try std.testing.expectEqual(@as(usize, 1), tab_ops.activeTab(session).active_pane);
    try std.testing.expectEqual(@as(usize, 1), pane_ops.activePane(session).active_term);
    try std.testing.expectEqual(target_id, term_ops.activeSurface(session).id);

    // 없는 id(알림 후 그 Term이 닫힌 경우 모사)는 false + 활성 상태 불변 — stale 알림이 엉뚱한 surface를 깨우지 않는다.
    try std.testing.expect(!term_ops.activateSurfaceById(session, 0xFFFF_FFFF));
    try std.testing.expectEqual(@as(usize, 1), session.app_window.active_tab);
    try std.testing.expectEqual(@as(usize, 1), pane_ops.activePane(session).active_term);
}

test "pendingNotification: 비활성 pane/Term의 OSC 9 알림도 그 surface_id로 drain한다" {
    // 예전엔 activeSurface().core만 drain해 background split pane·가로탭이 보낸 OSC 9/777 알림이 영영 안 나왔다 —
    // 클릭이 발신 Term으로 점프하려면(activateSurfaceById) 발신 Term의 surface_id가 알림에 실려야 하는데, 활성
    // surface의 id만 실려 "탭은 맞는데 pane/Term이 어긋나는" 증상이 났다. 이제 모든 Term의 코어를 훑어 발신 Term의
    // surface_id를 싣는다. 비활성 pane Term에 OSC 9를 먹이고(활성 surface엔 알림 없음), 그 비활성 Term의 알림을
    // surface_id까지 정확히 돌려주는지 + 그 id로 점프가 비활성 pane을 포커스하는지 본다(알림→점프 전제 폐곡선).
    if (builtin.os.tag != .macos) return error.SkipZigTest; // splitActivePane/newTermInActivePane = 실 PTY/CoreText
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.backing_width_px = session.sidebar_width_px + 800; // split이 의미 있으려면 backing 필요
    session.backing_height_px = 600;
    session.window_padding_px = .{};
    session.loaded_config.config.notifications.osc = true; // OSC 게이트 명시(기본값 의존 안 함)
    session.window_focused = true; // 포커스 창 — 활성 Term이 "지금 보는" Term이 되게(전면 배너 억제 대상)

    // 활성 탭에 split을 만들어 비활성 pane을 둔다: panes [p0, p1], 활성 p1. 발신원 = 비활성 p0의 Term.
    try pane_ops.splitActivePane(session, .horizontal);
    try std.testing.expectEqual(@as(usize, 1), tab_ops.activeTab(session).active_pane); // p1 활성
    const bg_term = tab_ops.activeTab(session).panes.items[0].terms.items[0]; // 비활성 p0의 Term(*Term)
    const bg_id = bg_term.surface.id;
    const active_id = term_ops.activeSurface(session).id; // 활성 p1의 Term(지금 보는 Term)
    try std.testing.expect(bg_id != active_id); // 활성과 다른 surface여야 의미 있음
    // 라벨을 rename으로 명시해 제목 위치 접두를 결정적으로 검증한다(탭 custom_name 없음 → workspaceLabel은 활성 p1
    // Term 라벨로 폴백). deinit이 surface.custom_name을 free.
    bg_term.surface.custom_name = try allocator.dupe(u8, "빌드");
    term_ops.activeSurface(session).custom_name = try allocator.dupe(u8, "활성작업");

    // 두 Term 모두 OSC 9(iTerm2: ESC ] 9 ; <body> BEL)를 먹인다 — title 없음, body=메시지.
    try bg_term.surface.core.write("\x1b]9;배경 pane 빌드 완료\x07");
    try term_ops.activeSurface(session).core.write("\x1b]9;활성 pane 알림\x07");

    // 루프는 p0(배경)→p1(활성) 순. 첫 drain = 배경 Term: surface_id=bg_id, 안 보는 곳이라 **전면 배너 뜸**(=1).
    const n1 = notification_ops.pendingNotification(session) orelse return error.TestExpectedNotification;
    try std.testing.expectEqualStrings("배경 pane 빌드 완료", n1.body);
    try std.testing.expectEqual(bg_id, n1.surface_id);
    try std.testing.expect(n1.foreground_banner); // 배경 pane OSC → 전면에서도 배너(사용자가 안 보는 곳)
    // OSC 9은 title 없음 → 제목=위치만. 탭 라벨(=활성 p1 폴백 "활성작업") ≠ 팬 라벨("빌드")이라 `탭 › 팬`.
    try std.testing.expectEqualStrings("활성작업 › 빌드", n1.title);

    // 둘째 drain = 활성(지금 보는) Term: 자기 화면 노이즈라 전면 배너 억제(=0, 목록만).
    const n2 = notification_ops.pendingNotification(session) orelse return error.TestExpectedNotification;
    try std.testing.expectEqual(active_id, n2.surface_id);
    try std.testing.expect(!n2.foreground_banner); // 지금 보는 Term OSC → 전면 배너 억제
    // 활성 Term은 탭 라벨(활성 Term 폴백)==팬 라벨이라 dedup — 위치가 "활성작업" 하나만(중복 억제).
    try std.testing.expectEqualStrings("활성작업", n2.title);

    // OSC 777(title 있음)은 위치를 **접두**하고 앱 title을 보존한다 — `위치 · 앱 title`, body도 앱 그대로.
    try bg_term.surface.core.write("\x1b]777;notify;Build finished;42개 컴파일\x07");
    const n3 = notification_ops.pendingNotification(session) orelse return error.TestExpectedNotification;
    try std.testing.expectEqualStrings("활성작업 › 빌드 · Build finished", n3.title);
    try std.testing.expectEqualStrings("42개 컴파일", n3.body);

    // 모두 소비됐으니 다음 호출은 null(clearNotification으로 코어 pending 비움 — 다음 tick 재발화 방지).
    try std.testing.expect(notification_ops.pendingNotification(session) == null);

    // 배경 Term의 surface_id로 점프하면 비활성 p0로 정확히 활성화된다(알림→점프 전제가 닫힌다).
    try std.testing.expect(term_ops.activateSurfaceById(session, bg_id));
    try std.testing.expectEqual(@as(usize, 0), tab_ops.activeTab(session).active_pane);
}

test "알림 히스토리: push 상한 ring + unread 증감 + markRead + formatRelativeTime 경계" {
    // formatRelativeTime 의 기대값이 한국어 문장이다 — 재는 것은 **경계**(60초·60분·24시간)이고 그
    // 판정은 문장으로 봐야 드러난다. 언어를 고정하되 **세션 생성 뒤에** 건다(아래 참고).
    const lang_before = maru.i18n.lang();
    defer maru.i18n.setLang(lang_before);

    // 인앱 알림 센터의 토대 — 드레인되면 사라지는 OS 배너와 달리 히스토리는 보관·열람된다. 상한(ring) 초과 시 가장
    // 오래된 걸 버리고, unread 캐시는 push/markRead/cap-drop 3곳에서만 정확히 증감해야 종 배지 수가 맞는다.
    if (builtin.os.tag != .macos) return error.SkipZigTest; // AppSession.init = 실 PTY/CoreText
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // **`AppSession.init` 이 `ui.language` 를 읽어 언어를 덮는다**(applyPreference). 그래서 언어 고정은
    // 반드시 **init 뒤**에 걸어야 한다 — 앞에 걸면 조용히 지워지고 테스트가 기본 언어로 돈다.
    maru.i18n.setLang(.ko);

    // push 2건 → len 2, unread 2, owned dupe.
    _ = notification_ops.pushNotificationHistory(session, "ws1", "done", 1);
    _ = notification_ops.pushNotificationHistory(session, "ws2", "fail", 2);
    try std.testing.expectEqual(@as(usize, 2), session.notification_history.items.len);
    try std.testing.expectEqual(@as(usize, 2), session.notification_unread);
    try std.testing.expectEqual(@as(u64, 2), session.notification_history.items[1].surface_id);

    // markRead(0) → unread 1, 다시 호출은 무동작(이미 읽음).
    notification_ops.markNotificationRead(session, 0);
    try std.testing.expectEqual(@as(usize, 1), session.notification_unread);
    notification_ops.markNotificationRead(session, 0);
    try std.testing.expectEqual(@as(usize, 1), session.notification_unread);
    notification_ops.markNotificationRead(session, 999); // 범위 밖 — 무동작
    try std.testing.expectEqual(@as(usize, 1), session.notification_unread);

    // 상한 초과: cap+5건 더 push → len은 cap(config notifications.history-limit) 유지(ring), 누수 없이 오래된 것 free.
    const cap: usize = @intCast(session.loaded_config.config.notifications.history_limit);
    var i: usize = 0;
    while (i < cap + 5) : (i += 1) _ = notification_ops.pushNotificationHistory(session, "x", "y", 100);
    try std.testing.expectEqual(cap, session.notification_history.items.len);

    // formatRelativeTime 경계(arena).
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    const a = arena_state.allocator();
    try std.testing.expectEqualStrings("방금", try notification_ops.formatRelativeTime(session, a, 30 * std.time.ns_per_s));
    try std.testing.expectEqualStrings("5분 전", try notification_ops.formatRelativeTime(session, a, 5 * 60 * std.time.ns_per_s));
    try std.testing.expectEqualStrings("2시간 전", try notification_ops.formatRelativeTime(session, a, 2 * 3600 * std.time.ns_per_s));
    try std.testing.expectEqualStrings("3일 전", try notification_ops.formatRelativeTime(session, a, 3 * 86400 * std.time.ns_per_s));
    try std.testing.expectEqualStrings("방금", try notification_ops.formatRelativeTime(session, a, -100)); // 시계 역행 → 0
}

test "acceptNotification: 목록 역순 매핑(0=최신) + 클릭 surface 전체 읽음(배너와 통일) + 패널 닫기" {
    // 목록은 최신이 위(역순)라 selected 0 = 히스토리 끝. accept는 그 카드의 surface를 봤다는 의미라 같은 surface의
    // 안읽음을 모두 읽음 처리하고(데스크톱 배너 클릭과 동일 정책 — markNotificationsReadBySurface) 패널을 닫는다.
    // 다른 surface 알림은 안읽음 점을 유지한다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    _ = notification_ops.pushNotificationHistory(session, "old-A", "1", 11); // history 0: surface 11
    _ = notification_ops.pushNotificationHistory(session, "other", "2", 22); // history 1: surface 22(다른 터미널)
    _ = notification_ops.pushNotificationHistory(session, "new-A", "3", 11); // history 2(최신): surface 11(또 한 번)
    session.chrome_host.notifications.show(0, 0, 3);
    session.chrome_host.notifications.selected = 0; // 목록 0 = 최신("new-A") = surface 11
    try std.testing.expectEqual(@as(usize, 3), session.notification_unread);

    notification_ops.acceptNotification(session);
    try std.testing.expect(!session.chrome_host.notifications.open); // 패널 닫힘
    // 클릭 카드의 surface(11) 안읽음(old-A·new-A) 모두 읽음, 다른 surface(22, "other")는 유지.
    try std.testing.expect(session.notification_history.items[0].is_read); // old-A (surface 11)
    try std.testing.expect(!session.notification_history.items[1].is_read); // other (surface 22)
    try std.testing.expect(session.notification_history.items[2].is_read); // new-A (surface 11)
    try std.testing.expectEqual(@as(usize, 1), session.notification_unread); // other만 안읽음
}

test "알림 액션: deleteNotification(역순) + markAllNotificationsRead + clearNotifications + unread 보정" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    _ = notification_ops.pushNotificationHistory(session, "a", "1", 11); // 히스토리 idx 0(가장 오래됨)
    _ = notification_ops.pushNotificationHistory(session, "b", "2", 22); // idx 1
    _ = notification_ops.pushNotificationHistory(session, "c", "3", 33); // idx 2(최신) — 목록 역순 [c, b, a]
    try std.testing.expectEqual(@as(usize, 3), session.notification_unread);

    // 목록 list_index 0 = 최신("c") = 히스토리 끝. 삭제 → "c" 제거, unread 1 감소.
    notification_ops.deleteNotification(session, 0);
    try std.testing.expectEqual(@as(usize, 2), session.notification_history.items.len);
    try std.testing.expectEqual(@as(usize, 2), session.notification_unread);
    try std.testing.expectEqualStrings("b", session.notification_history.items[1].title); // 최신이 이제 "b"

    // 모두 읽음 → unread 0, 항목 유지(목록엔 남음).
    notification_ops.markAllNotificationsRead(session);
    try std.testing.expectEqual(@as(usize, 0), session.notification_unread);
    try std.testing.expectEqual(@as(usize, 2), session.notification_history.items.len);

    // 모두 지우기 → 히스토리 비움(누수 없이 owned free).
    notification_ops.clearNotifications(session);
    try std.testing.expectEqual(@as(usize, 0), session.notification_history.items.len);
    try std.testing.expectEqual(@as(usize, 0), session.notification_unread);
}

test "markNotificationsReadBySurface: 배너 클릭→그 surface 안읽음 모두 읽음(센터 동기화)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    _ = notification_ops.pushNotificationHistory(session, "a", "1", 11); // surface 11
    _ = notification_ops.pushNotificationHistory(session, "b", "2", 22); // surface 22
    _ = notification_ops.pushNotificationHistory(session, "c", "3", 11); // surface 11 (또 한 번)
    try std.testing.expectEqual(@as(usize, 3), session.notification_unread);

    // surface 11 배너 클릭 → surface 11의 안읽음(a·c) 모두 읽음, surface 22(b)는 유지.
    notification_ops.markNotificationsReadBySurface(session, 11);
    try std.testing.expectEqual(@as(usize, 1), session.notification_unread); // b만 안읽음
    try std.testing.expect(session.notification_history.items[0].is_read); // a (surface 11)
    try std.testing.expect(!session.notification_history.items[1].is_read); // b (surface 22)
    try std.testing.expect(session.notification_history.items[2].is_read); // c (surface 11)

    // 없는 surface → 무동작.
    notification_ops.markNotificationsReadBySurface(session, 999);
    try std.testing.expectEqual(@as(usize, 1), session.notification_unread);
}

test "git_ops.parseGitHead: ref branch / nested ref / detached SHA / empty ref / junk" {
    try std.testing.expectEqualStrings("main", git_ops.parseGitHead("ref: refs/heads/main\n").?);
    try std.testing.expectEqualStrings("feature/x", git_ops.parseGitHead("ref: refs/heads/feature/x").?); // 슬래시 포함 브랜치
    try std.testing.expectEqualStrings("0123456", git_ops.parseGitHead("0123456789abcdef0123456789abcdef01234567\n").?); // detached → short
    try std.testing.expect(git_ops.parseGitHead("ref: refs/heads/\n") == null); // 빈 브랜치
    try std.testing.expect(git_ops.parseGitHead("garbage here") == null); // hex 아님·ref 아님
    try std.testing.expect(git_ops.parseGitHead("ref: refs/tags/v1") == null); // heads 아님(태그) → 미지원
    try std.testing.expect(git_ops.parseGitHead("") == null);
    try std.testing.expect(git_ops.parseGitHead("abc") == null); // 7자 미만 hex
}

test "window padding insets only the cell grid, not chrome (termRect/paneBarRect to edge, paneTermRect inset)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    // 결정적 padding(scale 1000 기본이라 appearance 8/4가 그대로 8/4px이지만 명시 고정).
    session.window_padding_px = .{ .left = 8, .right = 8, .top = 4, .bottom = 4 };
    session.cell_height_px = 18; // 탭 바 높이 결정적(bar_h = cell_height + 2·tab_bar_pad_y)
    session.titlebar_strip_px = 0; // 상단 타이틀바 띠는 별도 테스트 — 여기선 window padding/grid 수학만 격리
    session.backing_width_px = session.sidebar_width_px + 800;
    session.backing_height_px = 600;

    // termRect: 사이드바와 **창 바닥 상태표시줄**을 뺀다 — window padding 없음(chrome이 사이드바 경계/창 가장자리까지).
    const r = session.termRect();
    try std.testing.expectEqual(session.sidebar_width_px, r.x);
    try std.testing.expectEqual(@as(u32, 0), r.y);
    try std.testing.expectEqual(@as(u32, 800), r.w);
    try std.testing.expectEqual(600 - session.statusBarHeightPx(), r.h);

    // 탭 바: leaf rect 상단·사이드바 경계에 붙는다(padding inset 없음 — chrome은 가장자리까지).
    const bar = pane_ops.paneBarRect(session, r).?;
    try std.testing.expectEqual(session.sidebar_width_px, bar.x);
    try std.testing.expectEqual(@as(u32, 0), bar.y);
    try std.testing.expectEqual(@as(u32, 800), bar.w);

    // 셀 그리드: 탭 바 아래 + window padding inset(여기만 여백).
    const bar_h = pane_ops.paneBarHeightPx(session);
    const g = pane_ops.paneTermRect(session, r);
    try std.testing.expectEqual(session.sidebar_width_px + 8, g.x); // 좌 = 사이드바 + pad_x
    try std.testing.expectEqual(bar_h + 4, g.y); // 상 = 탭 바 + pad_y
    try std.testing.expectEqual(@as(u32, 800 - 16), g.w); // 폭 = backing − 사이드바 − 2·pad_x
    try std.testing.expectEqual((600 - session.statusBarHeightPx()) -| bar_h -| 8, g.h); // 높이 = backing − 상태바 − 바 − 2·pad_y

    // padding 0이면 grid도 inset 없음(탭 바만 뺀 영역).
    session.window_padding_px = .{};
    const g0 = pane_ops.paneTermRect(session, r);
    try std.testing.expectEqual(session.sidebar_width_px, g0.x);
    try std.testing.expectEqual(bar_h, g0.y);
    try std.testing.expectEqual(@as(u32, 800), g0.w);
    try std.testing.expectEqual((600 - session.statusBarHeightPx()) -| bar_h, g0.h); // padding 0이어도 상태바는 빠진다
}

// 비대칭 window padding(left≠right, top≠bottom) 회귀: paneTermRect가 좌상으로 left/top만큼만 들이고 폭/높이를
// (left+right)/(top+bottom)만큼 줄이며, gridFromBacking이 같은 비대칭 합을 grid에서 빼는지 고정한다. 대칭 합산
// (2×)으로 회귀하면 left≠right일 때 origin·폭이 어긋나므로 이 단언이 잡는다.
test "asymmetric window padding insets paneTermRect by left/top and grid by left+right/top+bottom" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    // 비대칭: 좌 10·우 20·상 4·하 8.
    session.window_padding_px = .{ .left = 10, .right = 20, .top = 4, .bottom = 8 };
    session.cell_height_px = 18; // 탭 바 높이 결정적
    session.titlebar_strip_px = 0; // 상단 타이틀바 띠는 별도 테스트 — 여기선 비대칭 padding/grid 수학만 격리
    session.backing_width_px = session.sidebar_width_px + 800;
    session.backing_height_px = 600;

    const r = session.termRect();
    const bar_h = pane_ops.paneBarHeightPx(session);
    const g = pane_ops.paneTermRect(session, r);
    // x는 left(10)만큼만, y는 top(4) + 바만큼 들어간다(우/하는 origin에 영향 없음).
    try std.testing.expectEqual(session.sidebar_width_px + 10, g.x);
    try std.testing.expectEqual(bar_h + 4, g.y);
    // 폭은 left+right(30), 높이는 바 + top+bottom(12)만큼 줄어든다.
    try std.testing.expectEqual(@as(u32, 800 - 30), g.w);
    try std.testing.expectEqual((600 - session.statusBarHeightPx()) -| bar_h -| 12, g.h); // backing − 상태바 − 바 − (pad_top+pad_bottom)

    // gridFromBacking도 비대칭 합(left+right=30, top+bottom=12)을 grid에서 뺀다(좌우·상하 대칭 가정 없이).
    // 800px term 폭(사이드바 뺀) 기준 cell 8px: (800−30)/8=96 cols, (600−12)/18=32 rows.
    const grid = layout_math.gridFromBacking(session.sidebar_width_px + 800, 600, 8, 18, session.sidebar_width_px, session.window_padding_px);
    try std.testing.expectEqual(@as(u16, 96), grid.cols);
    try std.testing.expectEqual(@as(u16, 32), grid.rows);
}

test "takeBell respects bell.audible; createTerm injects config scrollback" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // createTerm이 config 스크롤백(is_test 빈 config → 기본 1000)을 활성 surface core에 주입했다.
    try std.testing.expectEqual(@as(usize, 1000), term_ops.activeSurface(session).core.maxScrollback());

    // audible(기본 true): BEL → dispatchBell이 분배 → takeBell true, 한 번 drain(두 번째는 false). (F2-4: takeBell은
    // 코어가 아니라 dispatchBell이 세운 bell_audible_pending을 본다 — 코어 단일 drain.)
    session.audible_bell = true;
    try term_ops.activeSurface(session).core.write("\x07");
    notification_ops.dispatchBell(session);
    try std.testing.expect(notification_ops.takeBell(session));
    try std.testing.expect(!notification_ops.takeBell(session));

    // 음소거: BEL → dispatchBell이 코어를 drain하되 audible_pending은 안 켬 → takeBell false(소리 억제, stale 안 쌓임).
    session.audible_bell = false;
    try term_ops.activeSurface(session).core.write("\x07");
    notification_ops.dispatchBell(session);
    try std.testing.expect(!notification_ops.takeBell(session));

    // 시각 벨(bell.visual): on이면 BEL이 bell_flash_ticks를 켠다(audible과 독립). (F2-4)
    session.bell_visual = true;
    try term_ops.activeSurface(session).core.write("\x07");
    notification_ops.dispatchBell(session);
    try std.testing.expect(session.bell_flash_ticks > 0);
    session.bell_visual = false;
    session.bell_flash_ticks = 0;

    // Dock 배지(bell.dock-badge): **언포커스 시에만** bell_badge_pending. 포커스 중엔 안 켠다. take_bell_badge는 1회성.
    session.bell_dock_badge = true;
    session.window_focused = true;
    try term_ops.activeSurface(session).core.write("\x07");
    notification_ops.dispatchBell(session);
    try std.testing.expect(!notification_ops.takeBellBadge(session)); // 포커스 중 → 배지 없음
    session.window_focused = false;
    try term_ops.activeSurface(session).core.write("\x07");
    notification_ops.dispatchBell(session);
    try std.testing.expect(notification_ops.takeBellBadge(session)); // 언포커스 → 배지
    try std.testing.expect(!notification_ops.takeBellBadge(session)); // 1회성
}

// M0a SurfaceIdAllocator — surface_id는 앱 인스턴스 전역 opaque u64로 발급되며, 서로 다른 창(AppSession)이
// 같은 allocator 인스턴스를 공유한다(docs/window-surface-mobility.md §8). per-session next_id로 발급하면 두 창의
// 첫 surface가 둘 다 1이라 충돌하는데(멀티 창 MARU_PANE_ID 충돌 포함), 이 테스트가 그 회귀를 잡는다.
test "setWebNavState: upsert + 옛 url free + 조회 + 없는 surface null (7e-1a)" {
    // setWebNavState/webNavState는 self.allocator·self.web_nav_states만 만지므로 minimal init로 충분하다
    // (undefined session의 나머지 필드는 안 읽음 — [[devsession-undefined-test-field-trap]] 범위 밖). testing.allocator가
    // upsert의 옛 url free 누락(누수)·이중 free(UAF)를 검출한다.
    var session: AppSession = undefined;
    session.allocator = std.testing.allocator;
    session.web_nav_states = .empty;
    defer {
        var it = session.web_nav_states.valueIterator();
        while (it.next()) |v| session.allocator.free(v.url);
        session.web_nav_states.deinit(session.allocator);
    }
    web_ops.setWebNavState(&session, 42, true, false, "https://a/");
    try std.testing.expectEqualStrings("https://a/", web_ops.webNavState(&session, 42).?.url);
    try std.testing.expect(web_ops.webNavState(&session, 42).?.can_go_back);
    try std.testing.expect(!web_ops.webNavState(&session, 42).?.can_go_forward);
    // upsert: 옛 url을 free하고 새 url(다른 길이)로 교체 — 누수/UAF 없어야 통과.
    web_ops.setWebNavState(&session, 42, false, true, "https://b/longer");
    try std.testing.expectEqualStrings("https://b/longer", web_ops.webNavState(&session, 42).?.url);
    try std.testing.expect(web_ops.webNavState(&session, 42).?.can_go_forward);
    try std.testing.expect(!web_ops.webNavState(&session, 42).?.can_go_back);
    // 빈 url(url_ptr null ABI 경로) 저장.
    web_ops.setWebNavState(&session, 7, false, false, "");
    try std.testing.expectEqualStrings("", web_ops.webNavState(&session, 7).?.url);
    // 없는 surface → null.
    try std.testing.expect(web_ops.webNavState(&session, 999) == null);
}

test "AddrEdit 흐름: enter→append→commit(navigate)·cancel·teardown 정리 (7e-2a 헤드리스)" {
    // enter/append/backspace/commit/cancel + take 3종은 addr_edit·pending 필드만 만지므로 minimal init로 충분하다
    // ([[devsession-undefined-test-field-trap]]). **dropAddrEditIfSurface(step 6)가 읽는 pending 필드 전부**를 초기화한다 —
    // web_nav_action_pending도 그중 하나라 초기화하지 않으면 undefined read(UB)다(리뷰 [6]; 옛 주석 "나머지 필드 안 읽음"은
    // 틀렸음). 시각(metal_dirty·blink)은 순수 코어 밖(handleKeyEvent 래퍼/클릭 핸들러)이라 여기서 안 탄다 = 헤드리스 검증 가능.
    var session: AppSession = undefined;
    session.allocator = std.testing.allocator; // TextField(addr_field)가 self.allocator를 쓴다(text/preedit 동적)
    session.addr_field = .{};
    defer session.addr_field.deinit(std.testing.allocator);
    session.addr_edit = null;
    session.addr_focus_pull_pending = null;
    session.addr_navigate_pending = null;
    session.addr_navigate_url_len = 0;
    session.addr_focus_restore_pending = null;
    session.web_nav_action_pending = null; // dropAddrEditIfSurface가 읽음(teardown 정리 대상 일치 검사) — undefined read 방지
    // WP-P: takeWebAddrNavigate가 commit 슬롯이 비면 복원 브라우저 pending_url을 찾아 **탭 트리를 walk**한다 —
    // 이 최소 init에서 tabs/web_panel_prev를 안 채우면 undefined read(0xaa deref)다. 빈 목록으로 명시 초기화한다
    // (같은 계열 함정을 이미 겪은 자리라 주석으로 남긴다 — [[devsession-undefined-test-field-trap]]).
    session.tabs = .empty;
    session.web_panel_prev = .empty;

    // 1) 편집 진입: 현재 URL 시드 + focus-pull pending(1회성).
    web_ops.enterAddrEdit(&session, 42, "https://old.example/");
    try std.testing.expect(session.addr_edit != null);
    try std.testing.expectEqualStrings("https://old.example/", web_ops.addrEditText(&session));
    try std.testing.expectEqual(@as(?u64, 42), web_ops.takeWebAddrFocusPull(&session));
    try std.testing.expectEqual(@as(?u64, null), web_ops.takeWebAddrFocusPull(&session)); // 1회성 drain

    // 2) 백스페이스로 비우고 새 bare 도메인 타이핑 → commit이 resolveNavUrl로 https:// 프리픽스.
    while (web_ops.addrEditText(&session).len > 0) web_ops.addrEditBackspace(&session);
    try std.testing.expectEqualStrings("", web_ops.addrEditText(&session));
    for ("example.com") |c| web_ops.addrEditAppend(&session, c);
    try std.testing.expectEqualStrings("example.com", web_ops.addrEditText(&session));

    // 3) commit: navigate pending(surface_id + resolved url) + 편집 종료 + focus-restore. navigate url은 세션 버퍼라 유효.
    web_ops.commitAddrEdit(&session);
    try std.testing.expect(session.addr_edit == null); // 편집 종료
    const nav = web_ops.takeWebAddrNavigate(&session) orelse return error.TestUnexpectedNull;
    try std.testing.expectEqual(@as(u64, 42), nav.surface_id);
    try std.testing.expectEqualStrings("https://example.com", nav.url); // bare → https:// 프리픽스
    try std.testing.expect(web_ops.takeWebAddrNavigate(&session) == null); // 1회성 drain
    try std.testing.expectEqual(@as(?u64, 42), web_ops.takeWebAddrFocusRestore(&session));
    try std.testing.expect(web_ops.takeWebAddrFocusRestore(&session) == null); // 1회성

    // 4) 위험 스킴(허용 안 되는 스킴)은 commit해도 navigate 안 세우고 **편집을 유지**한다 — 입력을 지우고 조용히 종료하지
    //    않아(제보 "그냥 무시 당함") 사용자가 고치거나 Esc로 취소하게 한다(이슈2).
    web_ops.enterAddrEdit(&session, 7, "");
    _ = web_ops.takeWebAddrFocusPull(&session);
    for ("javascript://evil") |c| web_ops.addrEditAppend(&session, c);
    web_ops.commitAddrEdit(&session);
    try std.testing.expect(session.addr_edit != null); // 무효 → 편집 유지(조용히 종료 안 함)
    try std.testing.expectEqualStrings("javascript://evil", web_ops.addrEditText(&session)); // 입력 보존
    try std.testing.expect(web_ops.takeWebAddrNavigate(&session) == null); // 무효 스킴 → navigate 없음
    try std.testing.expect(web_ops.takeWebAddrFocusRestore(&session) == null); // 편집 유지 = focus-restore 안 세움
    web_ops.cancelAddrEdit(&session, true); // 다음 step 위해 편집 정리(Esc 의미)
    _ = web_ops.takeWebAddrFocusRestore(&session); // drain

    // 5) cancel(Esc): 편집만 종료, navigate 없음, focus-restore만.
    web_ops.enterAddrEdit(&session, 9, "https://x/");
    _ = web_ops.takeWebAddrFocusPull(&session);
    for ("abc") |c| web_ops.addrEditAppend(&session, c);
    web_ops.cancelAddrEdit(&session, true); // Esc 의미 — focus-restore 세움
    try std.testing.expect(session.addr_edit == null);
    try std.testing.expect(web_ops.takeWebAddrNavigate(&session) == null); // cancel은 로드 안 함
    try std.testing.expectEqual(@as(?u64, 9), web_ops.takeWebAddrFocusRestore(&session));

    // 6) teardown 정리: 편집 중 그 surface가 닫히면 addr_edit·관련 pending을 비운다(stale surface_id 방지).
    web_ops.enterAddrEdit(&session, 11, "https://y/");
    try std.testing.expect(session.addr_edit != null);
    web_ops.dropAddrEditIfSurface(&session, 999); // 다른 surface → 무동작
    try std.testing.expect(session.addr_edit != null);
    try std.testing.expectEqual(@as(?u64, 11), web_ops.addrEditSurfaceId(&session));
    web_ops.dropAddrEditIfSurface(&session, 11); // 대상 surface → 정리
    try std.testing.expect(session.addr_edit == null);
    try std.testing.expect(session.addr_focus_pull_pending == null); // enter가 세운 pull도 대상 일치라 정리
}

test "슬라이스 4: 주소창 키보드 편집 — 화살표·shift 선택·단어·⌘A (handleAddrEditKey 배선)" {
    // handleAddrEditKey는 addr_field(TextField)만 만지므로 minimal init로 충분([[devsession-undefined-test-field-trap]]).
    var session: AppSession = undefined;
    session.allocator = std.testing.allocator;
    session.addr_field = .{};
    defer session.addr_field.deinit(std.testing.allocator);
    session.addr_edit = 1; // 편집 활성(addrEditAppend/Backspace가 읽음)
    try session.addr_field.setText(std.testing.allocator, "abc/def"); // caret=끝(7)

    const key = struct {
        fn ev(k: chrome.input.Key, mods: chrome.input.Mods) chrome.input.InputEvent {
            return .{ .key = .{ .key = k, .mods = mods } };
        }
    }.ev;

    // ← : 그래핌 이동(7→6). 선택 없음.
    web_ops.handleAddrEditKey(&session, key(.left, .{}));
    try std.testing.expectEqual(@as(usize, 6), session.addr_field.caret);
    try std.testing.expect(session.addr_field.selection == null);

    // ⇧← : 선택 확장(anchor=6, focus=5).
    web_ops.handleAddrEditKey(&session, key(.left, .{ .shift = true }));
    try std.testing.expectEqual(@as(usize, 5), session.addr_field.caret);
    try std.testing.expectEqual(@as(usize, 5), session.addr_field.selection.?.lo());
    try std.testing.expectEqual(@as(usize, 6), session.addr_field.selection.?.hi());

    // → (no shift, 선택 있음): 선택 끝으로 collapse(6).
    web_ops.handleAddrEditKey(&session, key(.right, .{}));
    try std.testing.expectEqual(@as(usize, 6), session.addr_field.caret);
    try std.testing.expect(session.addr_field.selection == null);

    // ⌥← : 단어 시작으로("def" 시작=byte 4). URL 구분자 '/'가 경계.
    web_ops.handleAddrEditKey(&session, key(.left, .{ .option = true }));
    try std.testing.expectEqual(@as(usize, 4), session.addr_field.caret);

    // ⌘A : 전체 선택.
    web_ops.handleAddrEditKey(&session, .{ .key = .{ .key = .char, .codepoint = 'a', .mods = .{ .command = true } } });
    try std.testing.expectEqual(@as(usize, 0), session.addr_field.selection.?.lo());
    try std.testing.expectEqual(@as(usize, 7), session.addr_field.selection.?.hi());

    // 타이핑(선택 대체): 'X' → 선택 전체가 "X"로.
    web_ops.handleAddrEditKey(&session, .{ .key = .{ .key = .char, .codepoint = 'X' } });
    try std.testing.expectEqualStrings("X", session.addr_field.text.items);
}

test "리뷰: 주소창 편집 중 ⌘A(select_all 액션)는 터미널이 아니라 주소 필드를 전체 선택한다" {
    // ⌘A는 Edit 메뉴 "Select All" 카탈로그 항목의 keyEquivalent라 keyDown이 아니라 runCatalogAction→run_action→
    // dispatchAppAction으로 온다(제보: 주소창서 ⌘A 안 먹음 — 옛 코드가 addr_edit 무시하고 터미널만 선택). addr_edit
    // 활성이면 터미널 코어(enqueueCoreCommand·activeSurface)로 안 새고 addr_field.selectAll만 만지므로 runtime/
    // activeSurface/chrome_host 없이 minimal init로 충분하다([[devsession-undefined-test-field-trap]]).
    var session: AppSession = undefined;
    session.allocator = std.testing.allocator;
    session.metal_dirty = false;
    session.addr_edit = 1; // 편집 활성 → select_all이 필드 분기(터미널 경로 안 탐)
    session.addr_field = .{};
    defer session.addr_field.deinit(std.testing.allocator);

    try session.addr_field.setText(std.testing.allocator, "example.com"); // caret=끝, 선택 없음
    try std.testing.expect(session.addr_field.selection == null);
    session.dispatchAppAction(.select_all);
    // 필드 전체 [0, len)가 선택됨(터미널 select_all이 아니라). metal_dirty=하이라이트 재빌드 신호.
    try std.testing.expect(session.addr_field.selection != null);
    try std.testing.expectEqual(@as(usize, 0), session.addr_field.selection.?.anchor);
    try std.testing.expectEqual(@as(usize, "example.com".len), session.addr_field.selection.?.focus);
    try std.testing.expect(session.metal_dirty);
}

test "슬라이스 4: 주소창 클립보드 — copyText는 필드 선택(⌘C), pasteText는 caret 삽입·개행 strip(⌘V)" {
    // copyText/pasteText는 addr_edit 분기에서 addr_field만 만진다(터미널 경로 안 탐). minimal init로 충분하되
    // surface_initialized·copy_buffer는 명시 초기화([[devsession-undefined-test-field-trap]]).
    var session: AppSession = undefined;
    session.allocator = std.testing.allocator;
    session.surface_initialized = true;
    session.copy_buffer = &.{};
    session.clipboard_out_buffer = &.{}; // pendingClipboard가 drain 시 free(undefined면 UB) — [[devsession-undefined-test-field-trap]]
    session.metal_dirty = false;
    session.addr_edit = 1; // 편집 활성 → copy/paste가 필드 분기
    session.addr_field = .{};
    session.chrome_clipboard_write = &.{};
    defer session.addr_field.deinit(std.testing.allocator);
    defer if (session.copy_buffer.len > 0) std.testing.allocator.free(session.copy_buffer);
    defer if (session.clipboard_out_buffer.len > 0) std.testing.allocator.free(session.clipboard_out_buffer);
    defer if (session.chrome_clipboard_write.len > 0) std.testing.allocator.free(session.chrome_clipboard_write);

    try session.addr_field.setText(std.testing.allocator, "abcdef"); // caret=끝(6)
    // ⌘C: 선택 [1,4)="bcd"를 복사(필드 선택).
    session.addr_field.selection = .{ .anchor = 1, .focus = 4 };
    try std.testing.expectEqualStrings("bcd", session.copyText());
    // 선택 없으면 빈(터미널 선택으로 안 샘 — 편집 컨텍스트는 주소창이 클립보드 주체).
    session.addr_field.selection = null;
    try std.testing.expectEqualStrings("", session.copyText());

    // ⌘V: 클립보드 텍스트를 caret에 삽입(개행·NUL strip → 단일행). caret=끝 → "abcdef"+"XYZ".
    session.pasteText("X\nY\r\nZ", false);
    try std.testing.expectEqualStrings("abcdefXYZ", session.addr_field.text.items);
    // 선택 대체 붙여넣기: 전체 선택 후 → 선택이 붙여넣기로 대체.
    session.addr_field.selectAll();
    session.pasteText("hello", false);
    try std.testing.expectEqualStrings("hello", session.addr_field.text.items);

    // 리뷰 #3: 모든 C0 제어문자(ESC 0x1B·FF 0x0C·VT 0x0B·BS 0x08)·DEL(0x7F) 제거(옛 코드는 \r\n\0\t만 걸렀다).
    session.addr_field.selectAll();
    session.pasteText("a\x1bb\x0cc\x0bd\x08e\x7ff", false);
    try std.testing.expectEqualStrings("abcdef", session.addr_field.text.items);
    // 리뷰 #7: 손상 UTF-8 바이트는 건너뛰고 유효 UTF-8만 삽입(text가 항상 유효 UTF-8 — 폭 드리프트 방지).
    session.addr_field.selectAll();
    session.pasteText("가\xffab", false); // 0xFF는 유효 UTF-8 아님 → 건너뜀
    try std.testing.expectEqualStrings("가ab", session.addr_field.text.items);
    try std.testing.expect(std.unicode.utf8ValidateSlice(session.addr_field.text.items));
    try session.addr_field.setText(std.testing.allocator, "hello"); // 아래 ⌘X 테스트 상태 복원

    // ⌘X: 전체 선택 잘라내기 → text에서 제거 + 클립보드-쓰기 큐에 **먼저 캡처**(삭제와 순서 무관). pendingClipboard가
    // 그 바이트를 반환(Swift가 NSPasteboard에 씀 — OSC52 write와 같은 drain). chrome_clipboard_write set이라 터미널 경로 안 탐.
    session.addr_field.selectAll();
    web_ops.handleAddrEditKey(&session, .{ .key = .{ .key = .char, .codepoint = 'x', .mods = .{ .command = true } } });
    try std.testing.expectEqualStrings("", session.addr_field.text.items); // 잘려서 비었음
    try std.testing.expect(session.addr_field.selection == null);
    try std.testing.expectEqualStrings("hello", term_ops.pendingClipboard(&session)); // 잘라낸 바이트가 클립보드로

    // ⌘X 선택 없으면 무동작(클립보드 큐 안 채움).
    try session.addr_field.setText(std.testing.allocator, "abc");
    web_ops.handleAddrEditKey(&session, .{ .key = .{ .key = .char, .codepoint = 'x', .mods = .{ .command = true } } });
    try std.testing.expectEqualStrings("abc", session.addr_field.text.items); // 선택 없어 그대로
    try std.testing.expectEqual(@as(usize, 0), session.chrome_clipboard_write.len);
}

test "navButtonAt: 밴드 좌측 존을 back/forward/reload로 가르고 URL 존은 null (7e-3 hit-test)" {
    // 순수 함수 — nav_button_w=3, nav_button_count=3(단일 소스). band_x=100px, cw=10px 기준.
    // 존: [100,130)=back·[130,160)=forward·[160,190)=reload·[190,∞)=URL(null). 렌더 글리프 col(1·4·7 = 존 가운데)와 정합.
    const band_x: u32 = 100;
    const cw: u32 = 10;
    // back 존(cell 0~2 = px 100~129). 렌더 글리프는 col 1(px 110~119)에 — 존 안.
    try std.testing.expectEqual(@as(?NavButton, .back), navButtonAt(100, band_x, cw)); // 존 좌단
    try std.testing.expectEqual(@as(?NavButton, .back), navButtonAt(115, band_x, cw)); // 글리프 칸(col 1)
    try std.testing.expectEqual(@as(?NavButton, .back), navButtonAt(129, band_x, cw)); // 존 우단
    // forward 존(cell 3~5). 글리프 col 4.
    try std.testing.expectEqual(@as(?NavButton, .forward), navButtonAt(130, band_x, cw));
    try std.testing.expectEqual(@as(?NavButton, .forward), navButtonAt(145, band_x, cw)); // 글리프 칸(col 4)
    try std.testing.expectEqual(@as(?NavButton, .forward), navButtonAt(159, band_x, cw));
    // reload 존(cell 6~8). 글리프 col 7.
    try std.testing.expectEqual(@as(?NavButton, .reload), navButtonAt(160, band_x, cw));
    try std.testing.expectEqual(@as(?NavButton, .reload), navButtonAt(175, band_x, cw)); // 글리프 칸(col 7)
    try std.testing.expectEqual(@as(?NavButton, .reload), navButtonAt(189, band_x, cw));
    // URL 존(cell >= 9 = px >= 190) → null(밴드 클릭이 편집 진입으로).
    try std.testing.expectEqual(@as(?NavButton, null), navButtonAt(190, band_x, cw));
    try std.testing.expectEqual(@as(?NavButton, null), navButtonAt(500, band_x, cw));
    // 밴드 좌측 밖·cw==0·비유한 → null(방어).
    try std.testing.expectEqual(@as(?NavButton, null), navButtonAt(99, band_x, cw)); // band_x 왼쪽
    try std.testing.expectEqual(@as(?NavButton, null), navButtonAt(150, band_x, 0)); // cw==0
    try std.testing.expectEqual(@as(?NavButton, null), navButtonAt(std.math.inf(f64), band_x, cw));
}

test "takeWebNavAction: 활성 버튼 클릭이 세운 pending을 1회 drain + teardown 정리 (7e-3 헤드리스)" {
    // web_nav_action_pending/code만 만지므로 minimal init로 충분([[devsession-undefined-test-field-trap]]).
    var session: AppSession = undefined;
    session.allocator = std.testing.allocator;
    session.addr_edit = null;
    session.addr_focus_pull_pending = null;
    session.addr_navigate_pending = null;
    session.addr_focus_restore_pending = null;
    session.web_nav_action_pending = null;
    session.web_nav_action_code = 0;

    // 초기: 없음(-1 상당 = null).
    try std.testing.expect(session.takeWebNavAction() == null);

    // back(code 0) 세움 → 1회 drain으로 (surface_id, code) 반환, 두 번째는 null(1회성).
    session.web_nav_action_pending = 42;
    session.web_nav_action_code = 0;
    const act = session.takeWebNavAction() orelse return error.TestUnexpectedNull;
    try std.testing.expectEqual(@as(u64, 42), act.surface_id);
    try std.testing.expectEqual(@as(u8, 0), act.code);
    try std.testing.expect(session.takeWebNavAction() == null); // 1회성 drain

    // reload(code 2) 세움 → 반환 code=2.
    session.web_nav_action_pending = 7;
    session.web_nav_action_code = 2;
    const act2 = session.takeWebNavAction() orelse return error.TestUnexpectedNull;
    try std.testing.expectEqual(@as(u8, 2), act2.code);

    // teardown: pending을 세운 채 그 surface가 닫히면 dropAddrEditIfSurface가 비운다(stale 방지). addr_field은 이 경로가
    // 안 만지므로(대상 addr_edit=null) init 불요 — web_nav_action_pending 정리만 검증.
    session.web_nav_action_pending = 11;
    session.web_nav_action_code = 1;
    web_ops.dropAddrEditIfSurface(&session, 999); // 다른 surface → 무동작
    try std.testing.expectEqual(@as(?u64, 11), session.web_nav_action_pending);
    web_ops.dropAddrEditIfSurface(&session, 11); // 대상 → 정리
    try std.testing.expect(session.web_nav_action_pending == null);
}

test "setBrowserNavAction: 활성 버튼만 pending을 세운다 (7e-3 클릭·7e-4 키보드 공유 정책, 헤드리스)" {
    // web_nav_states(활성 판정) + web_nav_action_pending/code/metal_dirty만 만지므로 minimal init로 충분
    // ([[devsession-undefined-test-field-trap]]). testing.allocator가 url 누수를 검출한다.
    var session: AppSession = undefined;
    session.allocator = std.testing.allocator;
    session.web_nav_states = .empty;
    session.web_nav_action_pending = null;
    session.web_nav_action_code = 0;
    session.metal_dirty = false;
    defer {
        var it = session.web_nav_states.valueIterator();
        while (it.next()) |v| session.allocator.free(v.url);
        session.web_nav_states.deinit(session.allocator);
    }

    // 42: can_go_back=true, can_go_forward=false.
    web_ops.setWebNavState(&session, 42, true, false, "https://a/");

    // reload는 nav 상태 무관 항상 활성 → pending=42·code=2·metal_dirty.
    web_ops.setBrowserNavAction(&session, 42, .reload);
    try std.testing.expectEqual(@as(?u64, 42), session.web_nav_action_pending);
    try std.testing.expectEqual(@as(u8, 2), session.web_nav_action_code);
    try std.testing.expect(session.metal_dirty);

    // back: can_go_back=true → 활성 → code=0.
    session.web_nav_action_pending = null;
    session.web_nav_action_code = 9;
    web_ops.setBrowserNavAction(&session, 42, .back);
    try std.testing.expectEqual(@as(?u64, 42), session.web_nav_action_pending);
    try std.testing.expectEqual(@as(u8, 0), session.web_nav_action_code);

    // forward: can_go_forward=false → 비활성 → no-op(pending·code 불변, 클릭도 소비만).
    session.web_nav_action_pending = null;
    session.web_nav_action_code = 9;
    web_ops.setBrowserNavAction(&session, 42, .forward);
    try std.testing.expect(session.web_nav_action_pending == null);
    try std.testing.expectEqual(@as(u8, 9), session.web_nav_action_code);

    // nav 상태 없는 surface: back(비활성) no-op, reload(항상 활성)만 세운다.
    session.web_nav_action_pending = null;
    web_ops.setBrowserNavAction(&session, 999, .back);
    try std.testing.expect(session.web_nav_action_pending == null);
    web_ops.setBrowserNavAction(&session, 999, .reload);
    try std.testing.expectEqual(@as(?u64, 999), session.web_nav_action_pending);
    try std.testing.expectEqual(@as(u8, 2), session.web_nav_action_code);
}

test "setWebNavState: 값이 바뀔 때만 metal_dirty (링크 이동 주소창 재렌더, 7e-4 후속 헤드리스)" {
    // web_nav_states + metal_dirty만 만지므로 minimal init로 충분([[devsession-undefined-test-field-trap]]).
    // testing.allocator가 url 누수를 검출한다.
    var session: AppSession = undefined;
    session.allocator = std.testing.allocator;
    session.web_nav_states = .empty;
    session.metal_dirty = false;
    defer {
        var it = session.web_nav_states.valueIterator();
        while (it.next()) |v| session.allocator.free(v.url);
        session.web_nav_states.deinit(session.allocator);
    }

    // 첫 상태 = 새 항목 → metal_dirty(첫 주소 표시).
    web_ops.setWebNavState(&session, 7, false, false, "https://a/");
    try std.testing.expect(session.metal_dirty);

    // 같은 값 재push(무변화 KVO 재관측) → metal_dirty 안 세움(불필요 재렌더 방지).
    session.metal_dirty = false;
    web_ops.setWebNavState(&session, 7, false, false, "https://a/");
    try std.testing.expect(!session.metal_dirty);

    // url 변경(링크 이동) → metal_dirty(주소창 갱신 — 이 슬라이스의 핵심 수정).
    web_ops.setWebNavState(&session, 7, true, false, "https://b/");
    try std.testing.expect(session.metal_dirty);

    // can_go_back만 변경 → metal_dirty(nav 버튼 활성색 갱신).
    session.metal_dirty = false;
    web_ops.setWebNavState(&session, 7, false, false, "https://b/");
    try std.testing.expect(session.metal_dirty);
}

test "P4 C3b browser URL만 persisted mutation이고 history availability는 volatile이다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const saved_checkpoint = app_runtime.workspace_checkpoint;
    app_runtime.workspace_checkpoint = .{};
    defer app_runtime.workspace_checkpoint = saved_checkpoint;

    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    const surface_id = try pane_ops.appendWebTermInActivePane(session, .browser);
    session.workspace_checkpoint_mutations_enabled = true;
    try app_runtime.workspace_checkpoint.arm(.{
        .debounce_ns = 500_000_000,
        .retry_initial_ns = 1_000_000_000,
        .retry_max_ns = 30_000_000_000,
    }, false);

    web_ops.setWebNavState(session, surface_id, false, false, "https://example.test/a");
    try std.testing.expectEqual(@as(u64, 1), app_runtime.workspace_checkpoint.change_revision);
    web_ops.setWebNavState(session, surface_id, true, false, "https://example.test/a");
    try std.testing.expectEqual(@as(u64, 1), app_runtime.workspace_checkpoint.change_revision);
    web_ops.setWebNavState(session, surface_id, true, false, "https://example.test/b");
    try std.testing.expectEqual(@as(u64, 2), app_runtime.workspace_checkpoint.change_revision);
}

test "P4 C3b staged Window construction mutation은 publish enable 전 revision을 만들지 않는다" {
    const saved_checkpoint = app_runtime.workspace_checkpoint;
    app_runtime.workspace_checkpoint = .{};
    defer app_runtime.workspace_checkpoint = saved_checkpoint;
    try app_runtime.workspace_checkpoint.arm(.{
        .debounce_ns = 500_000_000,
        .retry_initial_ns = 1_000_000_000,
        .retry_max_ns = 30_000_000_000,
    }, false);

    var session: AppSession = undefined;
    session.workspace_checkpoint_mutations_enabled = false;
    session.workspaceChanged(.topology);
