    session.dock_list_scroll_drag = .{};
    session.dock_list_scroll_drag_owner = null;
    session.dock_list_scroll_entry_count = 0;
    session.dock_list_scroll_generation = 0;
    session.allocator = std.testing.allocator;
    session.io = std.Io.Threaded.global_single_threaded.io(); // updateCursorBlink→readActiveSnapshot이 lockCore(self.io)
    var tab_surface = try maru.session.Surface.init(std.testing.allocator, 1, .{ .cols = 4, .rows = 2 });
    defer tab_surface.deinit();
    session.surface_initialized = true;
    var st_ptrs = [_]*maru.session.Surface{&tab_surface};
    session.app_window = .{ .tabs = &st_ptrs };
    var test_rt: app.SurfaceRuntime = undefined;
    try attachTestRuntime(&session, &test_rt, &tab_surface);
    defer session.runtime.deinit();
    session.metal_dirty = false;
    session.chrome_host = .{}; // mouse()가 context_menu.open을 kind 무관하게 읽음([[devsession-undefined-test-field-trap]])
    session.rename = null;
    session.mouse_drag_selecting = true;
    session.pointer_gesture_owner = .none;
    // divider capture는 `PointerGestureOwner` 밖의 두 번째 pointer 축이라 여기서 함께 비운다
    // — `undefined` 세션이 mouse()를 타면 이 필드도 읽는다(CIM2).
    session.divider_interaction = .{};
    session.divider_capture_seg = null;
    session.divider_capture_split = null;
    session.divider_coalescer = .{};
    session.divider_entry_scratch = .empty;
    session.divider_split_scratch = .empty;
    session.divider_snapshot_generation = 0;
    session.scrollbar_interaction = .{};
    session.dock_list_scroll_drag = .{};
    session.dock_list_scroll_drag_owner = null;
    session.dock_list_scroll_entry_count = 0;
    session.dock_list_scroll_generation = 0;
    // 자동 스크롤은 frame rate 무관 ≈30줄/s(경과 ms 게이트). frame_loop_rate_hz=30이면 msPerTick=33=step_ms라 tick
    // 마다 한 줄 — 이 테스트의 "tick당 한 줄" 가정과 맞는 cadence를 명시한다(undefined frame_loop_rate_hz 트랩도 회피).
    session.frame_loop_rate_hz = 30;
    session.drag_autoscroll = 0;
    session.drag_autoscroll_accum_ms = 0;
    session.last_drag_col = 1;
    session.cell_width_px = 8;
    session.cell_height_px = 16;
    session.scale_milli = 1000;
    session.sidebar_width_px = 0; // 사이드바 없음 — 마우스가 터미널 선택 경로를 타게(inSidebar=false)
    session.active_pane_rect = .{ .x = 0, .y = 0, .w = 32, .h = 32 }; // 단일 panel 좌표 origin(pxToCell이 읽음)

    const core = &tab_surface.core;
    try core.write("a\r\nb\r\nc\r\nd"); // 스크롤백 2(a,b) + 화면 c,d
    core.selectionStart(1, 0); // 화면 행1(d)에서 드래그 시작

    // 드래그가 grid 위 밖으로(y<0) — kind 2가 자동 스크롤 방향을 세운다.
    session.mouse(2, 0.0, -5.0, 0, 0); // col 0, grid 위 밖
    try std.testing.expectEqual(@as(i8, 1), session.drag_autoscroll);

    scroll_ops.applyDragAutoscroll(&session); // tick 1: 한 줄 위로 + 선택이 뷰 최상단으로 확장
    try std.testing.expectEqual(@as(usize, 1), core.view_offset);
    scroll_ops.applyDragAutoscroll(&session); // tick 2: 맨 위까지
    try std.testing.expectEqual(@as(usize, 2), core.view_offset);
    const text = (try core.extractSelection(std.testing.allocator)).?;
    defer std.testing.allocator.free(text);
    // 선택이 a(맨 위)까지 닿았다.
    try std.testing.expectEqualStrings("a\nb\nc\nd", text);

    // up(3)이 자동 스크롤을 멈춘다.
    session.mouse(3, 8.0, 8.0, 0, 0);
    try std.testing.expectEqual(@as(i8, 0), session.drag_autoscroll);
}

test "drag autoscroll 속도는 frame rate에 비례하지 않는다 (경과 ms 게이트)" {
    // 옛날엔 tick마다 한 줄이라 기본이 30→60Hz로 오르며 자동 스크롤이 2배(120Hz면 4배) 빨라졌다. 이제 경과 ms로
    // 게이트해, 같은 호출 횟수라도 고프레임일수록 호출당 적게 스크롤한다(120Hz: msPerTick=8, step=33 → ~4콜당 한 줄).
    // 8콜이면 옛 모델은 8줄(과속)이지만 ms 게이트는 1~2줄에 그친다.
    var session: AppSession = undefined;
    session.addr_edit = null; // 슬라이스 3: mouse()가 조기 addr 밴드 캡처에서 읽음(undefined면 UB — [[devsession-undefined-test-field-trap]])
    session.pointer_gesture_owner = .none;
    // divider capture는 `PointerGestureOwner` 밖의 두 번째 pointer 축이라 여기서 함께 비운다
    // — `undefined` 세션이 mouse()를 타면 이 필드도 읽는다(CIM2).
    session.divider_interaction = .{};
    session.divider_capture_seg = null;
    session.divider_capture_split = null;
    session.divider_coalescer = .{};
    session.divider_entry_scratch = .empty;
    session.divider_split_scratch = .empty;
    session.divider_snapshot_generation = 0;
    session.scrollbar_interaction = .{};
    session.dock_list_scroll_drag = .{};
    session.dock_list_scroll_drag_owner = null;
    session.dock_list_scroll_entry_count = 0;
    session.dock_list_scroll_generation = 0;
    session.allocator = std.testing.allocator;
    session.io = std.Io.Threaded.global_single_threaded.io(); // updateCursorBlink→readActiveSnapshot이 lockCore(self.io)
    var tab_surface = try maru.session.Surface.init(std.testing.allocator, 1, .{ .cols = 4, .rows = 2 });
    defer tab_surface.deinit();
    session.surface_initialized = true;
    var st_ptrs = [_]*maru.session.Surface{&tab_surface};
    session.app_window = .{ .tabs = &st_ptrs };
    var test_rt: app.SurfaceRuntime = undefined;
    try attachTestRuntime(&session, &test_rt, &tab_surface);
    defer session.runtime.deinit();
    session.chrome_host = .{};
    session.frame_loop_rate_hz = 120; // host cadence 120Hz → msPerTick=8
    session.drag_autoscroll = 1; // grid 위 밖 — 위(과거)로 스크롤
    session.drag_autoscroll_accum_ms = 0;
    session.last_drag_col = 0;

    const core = &tab_surface.core;
    var i: usize = 0;
    while (i < 20) : (i += 1) try core.write("x\r\n"); // 넉넉한 스크롤백(8콜로 한도에 안 막히게)
    core.selectionStart(1, 0); // 화면 행1에서 드래그 시작(autoscroll이 선택을 위로 확장)

    var calls: usize = 0;
    while (calls < 8) : (calls += 1) scroll_ops.applyDragAutoscroll(&session);
    try std.testing.expect(core.view_offset >= 1); // 스크롤은 일어난다(게이트가 영영 막지 않음)
    try std.testing.expect(core.view_offset <= 2); // 그러나 8콜에 8줄이 아니다 — 고프레임 과속 회귀 방어
}

test "frame-rate helpers: config 희망값과 host cadence를 분리해 ms→tick 환산" {
    var session: AppSession = undefined;
    session.loaded_config.config = .{};
    session.frame_loop_rate_hz = config_mod.theme.render_frame_rate_default;

    try std.testing.expectEqual(config_mod.theme.render_frame_rate_default, session.configuredFrameRateHz());
    try std.testing.expectEqual(config_mod.theme.render_frame_rate_default, session.frameRateHz());
    try std.testing.expectEqual(@as(u32, 30), session.ticksForMs(500)); // 500ms@60Hz
    try std.testing.expectEqual(@as(u32, 60), session.syncTimeoutTicks()); // 1s@60Hz
    try std.testing.expectEqual(@as(u32, 100), scroll_ops.scrollbarVisibleTicks(&session)); // 1.667s@60Hz
    try std.testing.expectEqual(@as(u32, 27), scroll_ops.scrollbarFadeTicks(&session)); // 450ms@60Hz
    try std.testing.expectEqual(@as(u32, 15), notification_ops.bellFlashTotalTicks(&session)); // 250ms@60Hz
    try std.testing.expectEqual(@as(u32, 17), session.msPerTick()); // round(1000/60) — 드래그 자동 스크롤 누적용

    session.loaded_config.config.render_frame_rate = 30;
    try std.testing.expectEqual(@as(u32, 30), session.configuredFrameRateHz()); // Swift timer 재시작 판단용 희망값
    try std.testing.expectEqual(@as(u32, 60), session.frameRateHz()); // host timer가 아직 60Hz면 내부 환산도 60Hz
    try std.testing.expectEqual(@as(u32, 30), session.ticksForMs(500));

    session.setFrameLoopRateHz(30);
    try std.testing.expectEqual(@as(u32, 30), session.frameRateHz());
    try std.testing.expectEqual(@as(u32, 15), session.ticksForMs(500));
    try std.testing.expectEqual(@as(u32, 30), session.syncTimeoutTicks());
    try std.testing.expectEqual(@as(u32, 50), scroll_ops.scrollbarVisibleTicks(&session));
    try std.testing.expectEqual(@as(u32, 14), scroll_ops.scrollbarFadeTicks(&session));
    try std.testing.expectEqual(@as(u32, 8), notification_ops.bellFlashTotalTicks(&session));
    try std.testing.expectEqual(@as(u32, 33), session.msPerTick()); // round(1000/30) = scroll_ops.drag_autoscroll_step_ms

    session.loaded_config.config.render_frame_rate = 120;
    try std.testing.expectEqual(@as(u32, 120), session.configuredFrameRateHz());
    try std.testing.expectEqual(@as(u32, 30), session.frameRateHz()); // host cadence는 tick 입력이 바꾸기 전까지 독립
    session.setFrameLoopRateHz(120);
    try std.testing.expectEqual(@as(u32, 120), session.frameRateHz());
    try std.testing.expectEqual(@as(u32, 60), session.ticksForMs(500));
    try std.testing.expectEqual(@as(u32, 120), session.syncTimeoutTicks());
    try std.testing.expectEqual(@as(u32, 200), scroll_ops.scrollbarVisibleTicks(&session));
    try std.testing.expectEqual(@as(u32, 54), scroll_ops.scrollbarFadeTicks(&session));
    try std.testing.expectEqual(@as(u32, 30), notification_ops.bellFlashTotalTicks(&session));
    try std.testing.expectEqual(@as(u32, 8), session.msPerTick()); // round(1000/120)

    session.loaded_config.config.render_frame_rate = 1; // 파일 파서는 막지만 getter도 방어적으로 clamp
    try std.testing.expectEqual(@as(u32, 30), session.configuredFrameRateHz());
    session.setFrameLoopRateHz(1);
    try std.testing.expectEqual(@as(u32, 30), session.frameRateHz());
    session.loaded_config.config.render_frame_rate = 999;
    try std.testing.expectEqual(@as(u32, 120), session.configuredFrameRateHz());
    session.setFrameLoopRateHz(999);
    try std.testing.expectEqual(@as(u32, 120), session.frameRateHz());
    try std.testing.expectEqual(@as(u32, 1), ticksForMsAtRate(10, 60)); // 극단값도 최소 1틱
}

// 위상 진행이 **tick 수가 아니라 실경과 시간** 기준임을 고정한다(§10.5 secondary — 스피너와 같은 모델).
// 회귀: 옛 코드는 ms를 **설정값** render.frame-rate로 틱 환산해 셌다. 실효 tick rate가 그보다 낮으면(무거운 tick·
// 백그라운드 스로틀링, 실측 ~17Hz vs 설정 60Hz) 반주기가 그만큼 늘어나 깜빡임이 3배 넘게 느려졌다(사용자 제보
// "너무 느리다"). 이제 tick을 아무리 많이 돌려도 시간이 안 지났으면 위상이 안 넘어가고, baseline을 과거로 밀면
// tick 한 번으로도 넘어간다 — 두 방향을 함께 잠근다.
/// 테스트 전용: blink 위상 baseline을 `halves`개 반주기만큼 과거로 밀어, 다음 `updateCursorBlink` 한 번이
/// 그만큼 실경과한 것으로 보게 한다. wall-clock 모델이라 tick을 여러 번 도는 것으로는 위상이 안 넘어간다.
fn testAdvanceBlinkHalves(session: *AppSession, halves: i128) void {
    const interval_ns: i128 = @as(i128, @max(session.appearance.cursor.blink_interval_ms, 1)) * std.time.ns_per_ms;
    session.blink_phase_ns = std.Io.Clock.awake.now(session.io).nanoseconds - halves * interval_ns;
}

test "cursor blink 위상: tick 수가 아니라 wall-clock 경과로 진행한다" {
    var session: AppSession = undefined;
    session.allocator = std.testing.allocator;
    session.addr_edit = null;
    session.focus_owner = .workspace;
    session.pending_dock_focus = null;
    session.io = std.Io.Threaded.global_single_threaded.io();
    var tab_surface = try maru.session.Surface.init(std.testing.allocator, 1, .{ .cols = 4, .rows = 2 });
    defer tab_surface.deinit();
    session.surface_initialized = true;
    var st_ptrs = [_]*maru.session.Surface{&tab_surface};
    session.app_window = .{ .tabs = &st_ptrs };
    session.metal_dirty = false;
    session.metal_buffer = .{};
    session.blink_visible = true;
    session.blink_phase_ns = 0;
    session.chrome_host = .{};
    session.rename = null;
    session.tabs = .empty;
    session.sidebar_rows = .empty;
    session.sidebar_collapsed = false;
    session.sidebar_search_active = false;
    session.loaded_config.config = .{};
    session.frame_loop_rate_hz = config_mod.theme.render_frame_rate_default;
    session.appearance.cursor.blink = true;
    session.appearance.cursor.blink_interval_ms = 500;
    session.appearance.cursor.blink_fade_ms = 0;
    session.appearance.blink_text = false;

    // ① tick을 반주기 틱 수(60Hz면 30틱)의 몇 배로 돌려도 **실시간이 안 지났으면** 위상은 그대로다.
    //    (옛 tick-카운트 모델이면 여기서 여러 번 토글됐다.)
    var i: u32 = 0;
    while (i < 201) : (i += 1) session.updateCursorBlink(session.readActiveSnapshot(false)); // 홀수 — tick당 토글 모델이면 false로 뒤집힌다
    try std.testing.expect(session.blink_visible);
    try std.testing.expect(session.blink_phase_ns != 0); // 첫 tick이 baseline을 잡았다

    // ② baseline을 정확히 한 반주기 과거로 밀면 다음 tick 한 번에 토글된다(실경과 기준).
    const interval_ns: i128 = 500 * std.time.ns_per_ms;
    session.blink_phase_ns = std.Io.Clock.awake.now(session.io).nanoseconds - interval_ns;
    session.updateCursorBlink(session.readActiveSnapshot(false));
    try std.testing.expect(!session.blink_visible);

    // ③ 두 반주기를 한 번에 건너뛰면(stall 후 재개) 짝수 번이라 위상이 제자리로 catch-up한다 — drift 없음.
    session.blink_phase_ns = std.Io.Clock.awake.now(session.io).nanoseconds - 2 * interval_ns;
    session.updateCursorBlink(session.readActiveSnapshot(false));
    try std.testing.expect(!session.blink_visible);

    // ④ 활동 리셋은 baseline을 폐기해 다음 tick이 새 반주기를 시작하게 한다(보이는 위상 고정).
    session.resetCursorBlink();
    try std.testing.expect(session.blink_visible);
    try std.testing.expectEqual(@as(i128, 0), session.blink_phase_ns);
}

test "cursor blink: 틱마다 토글·steady/조합 고정·활동 리셋·오버레이 caret도 깜빡(suffix-trim 재활용)" {
    var session: AppSession = undefined;
    session.allocator = std.testing.allocator;
    session.addr_edit = null; // 7e-2: inputFocus가 addr_edit을 읽음([[devsession-undefined-test-field-trap]])
    session.focus_owner = .workspace;
    session.pending_dock_focus = null;
    session.io = std.Io.Threaded.global_single_threaded.io(); // updateCursorBlink→readActiveSnapshot이 lockCore(self.io)
    var tab_surface = try maru.session.Surface.init(std.testing.allocator, 1, .{ .cols = 4, .rows = 2 });
    defer tab_surface.deinit();
    session.surface_initialized = true;
    var st_ptrs = [_]*maru.session.Surface{&tab_surface};
    session.app_window = .{ .tabs = &st_ptrs };
    session.metal_dirty = false;
    session.metal_buffer = .{};
    session.blink_visible = true;
    session.blink_phase_ns = 0;
    session.chrome_host = .{}; // updateCursorBlink이 find/palette.open을 읽음 — undefined면 UB([[devsession-undefined-test-field-trap]])
    session.rename = null; // inputFocus/updateCursorBlink가 rename을 읽음(undefined면 garbage가 .rename 분기)
    session.tabs = .empty;
    session.sidebar_rows = .empty; // updateCursorBlink→anyAgentRunning이 sidebar_rows를 순회(code-review high #1) — undefined면 UB(같은 함정). 빈 목록=스피너 없음
    session.sidebar_collapsed = false; // anyAgentRunning이 먼저 읽음(접힘이면 false 조기반환) — undefined면 garbage 분기
    session.loaded_config.config = .{}; // configured frame-rate 기본값
    session.frame_loop_rate_hz = config_mod.theme.render_frame_rate_default;
    session.appearance.cursor.blink = true; // config 게이트(앱 DECSCUSR에 위임) — updateCursorBlink가 읽음, undefined면 UB([[devsession-undefined-test-field-trap]])
    session.appearance.cursor.blink_interval_ms = 500; // updateCursorBlink 위상 계산이 읽음 — undefined면 overflow([[devsession-undefined-test-field-trap]])
    session.appearance.cursor.blink_fade_ms = 0; // 페이드 끔 = 하드 토글 — 이 테스트는 위상/리셋/steady 로직 검증(페이드 램프는 cursorFadeMilliForPhase 순수 테스트). updateCursorBlink가 읽음 — undefined면 UB([[devsession-undefined-test-field-trap]])

    // 기본(DECSCUSR 1 = 깜빡 block, 페이드 끔): interval 틱마다 즉각 토글. rebuild(metal_dirty) 없이 generation만(suffix 불투명도).
    testAdvanceBlinkHalves(&session, 1);
    session.updateCursorBlink(session.readActiveSnapshot(false));
    try std.testing.expect(!session.blink_visible);
    try std.testing.expect(!session.metal_dirty);
    try std.testing.expectEqual(@as(u64, 1), session.metal_buffer.generation);
    try std.testing.expectEqual(@as(u32, 0), session.metal_buffer.cursor_fade_milli); // off 위상 = 완전히 사라짐(페이드 끔이라 즉각)
    testAdvanceBlinkHalves(&session, 1);
    session.updateCursorBlink(session.readActiveSnapshot(false));
    try std.testing.expect(session.blink_visible);

    // 활동(입력/출력) 리셋: off 위상이어도 즉시 보이게.
    session.blink_visible = false;
    testAdvanceBlinkHalves(&session, 1); // 위상 한복판
    session.resetCursorBlink();
    try std.testing.expect(session.blink_visible);
    try std.testing.expectEqual(@as(i128, 0), session.blink_phase_ns); // baseline 폐기 = 다음 tick이 새 반주기

    // steady 커서(DECSCUSR 2) + 오버레이 닫힘: 토글 안 함(보이는 위상 고정 — idle 절전).
    try tab_surface.core.write("\x1b[2 q");
    session.blink_visible = true;
    testAdvanceBlinkHalves(&session, 3);
    session.updateCursorBlink(session.readActiveSnapshot(false));
    try std.testing.expect(session.blink_visible); // steady/조합 중 — 위상이 아무리 지나도 고정

    // 오버레이(find) 열림: steady 커서여도 caret은 깜빡인다(overlay_open이라 토글 — suffix=오버레이 caret). 회귀:
    // 사용자 제보 "오버레이 커서가 안 깜빡임" 수정 — 터미널 커서와 같은 틱-카운터+suffix-trim 재활용.
    session.chrome_host.find.open = true;
    session.blink_visible = true;
    testAdvanceBlinkHalves(&session, 1);
    session.updateCursorBlink(session.readActiveSnapshot(false));
    try std.testing.expect(!session.blink_visible); // caret이 off 위상으로 토글됨
    session.chrome_host.find.open = false;

    // IME 조합 중(preedit) + 오버레이 닫힘: 깜빡이지 않고 고정 — 조합 글자 옆에서 안 반짝.
    try tab_surface.core.write("\x1b[1 q"); // 다시 blink 커서로
    tab_surface.lockCore(session.io);
    try std.testing.expect(tab_surface.setPreeditLocked("\xec\x95\x88"));
    tab_surface.unlockCore(session.io);
    session.blink_visible = true;
    testAdvanceBlinkHalves(&session, 3);
    session.updateCursorBlink(session.readActiveSnapshot(false));
    try std.testing.expect(session.blink_visible); // steady/조합 중 — 위상이 아무리 지나도 고정
    tab_surface.lockCore(session.io);
    try std.testing.expect(tab_surface.setPreeditLocked(""));
    tab_surface.unlockCore(session.io);
}

// config `cursor.blink = false`가 실제로 커서를 고정하는지 고정한다. 회귀: `ResolvedCursor.blink`이 resolve만 되고
// **아무도 읽지 않아** 설정이 무동작이었다(사용자 제보 "커서 깜빡임 옵션이 동작하지 않음"). 두 갈래를 함께 잠근다 —
// ① 앱 DECSCUSR blink 요청(기본 `CSI 1 SP q` 상태)을 config가 덮는가, ② 텍스트 blink(SGR 5)로 위상이 도는 동안에도
// 커서 suffix가 페이드되지 않는가(옛 코드는 위상이 돌면 주인과 무관하게 무조건 커서를 페이드했다).
test "cursor blink: config cursor.blink=false가 앱 DECSCUSR blink를 덮어 커서를 고정(텍스트 blink 위상 중에도)" {
    var session: AppSession = undefined;
    session.allocator = std.testing.allocator;
    session.addr_edit = null;
    session.focus_owner = .workspace;
    session.pending_dock_focus = null;
    session.io = std.Io.Threaded.global_single_threaded.io();
    var tab_surface = try maru.session.Surface.init(std.testing.allocator, 1, .{ .cols = 4, .rows = 2 });
    defer tab_surface.deinit();
    session.surface_initialized = true;
    var st_ptrs = [_]*maru.session.Surface{&tab_surface};
    session.app_window = .{ .tabs = &st_ptrs };
    session.metal_dirty = false;
    session.metal_buffer = .{};
    session.blink_visible = true;
    session.blink_phase_ns = 0;
    session.chrome_host = .{};
    session.rename = null;
    session.tabs = .empty;
    session.sidebar_rows = .empty;
    session.sidebar_collapsed = false;
    session.sidebar_search_active = false; // 검색 caret이 위상을 돌리지 않게 명시(undefined면 UB — [[devsession-undefined-test-field-trap]])
    session.loaded_config.config = .{};
    session.frame_loop_rate_hz = config_mod.theme.render_frame_rate_default;
    session.appearance.cursor.blink = false; // ← 검증 대상: 사용자가 깜빡임을 껐다
    session.appearance.cursor.blink_interval_ms = 500;
    session.appearance.cursor.blink_fade_ms = 0; // 페이드 끔 = 하드 토글 → 고정이면 1000, 안 고쳤으면 off 위상에 0
    session.appearance.blink_text = false;

    // ① 커서는 DECSCUSR 기본(깜빡 block)인데 config가 껐다: 위상이 아예 안 돈다(다른 깜빡임도 없음 → idle 유지).
    testAdvanceBlinkHalves(&session, 3);
    session.updateCursorBlink(session.readActiveSnapshot(false));
    try std.testing.expect(session.blink_visible);
    try std.testing.expectEqual(@as(u32, 1000), session.metal_buffer.cursor_fade_milli); // 완전 표시로 고정
    try std.testing.expectEqual(@as(u64, 0), session.metal_buffer.generation); // 값 불변 = 재present 없음(idle)
    try std.testing.expect(!session.metal_dirty);

    // ② 화면에 blink 글자(SGR 5)가 있어 위상은 돈다 — 그래도 커서는 고정이어야 한다(옛 코드는 여기서 같이 깜빡였다).
    try tab_surface.core.write("\x1b[5mblink\x1b[m");
    session.appearance.blink_text = true;
    session.blink_visible = true;
    testAdvanceBlinkHalves(&session, 1);
    session.updateCursorBlink(session.readActiveSnapshot(true));
    try std.testing.expect(!session.blink_visible); // 텍스트 blink 위상은 정상 진행(off 위상으로 토글)
    try std.testing.expect(session.metal_dirty); // 텍스트 blink는 full rebuild
    try std.testing.expectEqual(@as(u32, 1000), session.metal_buffer.cursor_fade_milli); // 커서 suffix는 그대로 완전 표시

    // ③ config를 다시 켜면(true=앱 DECSCUSR에 위임) 같은 조건에서 커서가 off 위상으로 사라진다 — 게이트가 config 값을
    //    실제로 보고 있다는 양방향 증거(true로도 red→green이 갈린다).
    session.appearance.cursor.blink = true;
    session.blink_visible = true;
    testAdvanceBlinkHalves(&session, 1);
    session.updateCursorBlink(session.readActiveSnapshot(true));
    try std.testing.expect(!session.blink_visible);
    try std.testing.expectEqual(@as(u32, 0), session.metal_buffer.cursor_fade_milli); // 페이드 끔 = 즉각 사라짐
}

// config enum(`theme.CursorShape` = block/bar/underline)과 terminal enum(`types.CursorShape` = block/underline/bar)은
// **멤버 순서가 다르다**. 숫자 재해석(@intFromEnum)으로 옮기면 bar↔underline이 조용히 뒤바뀌어, `cursor.shape = bar`가
// underline으로 그려진다(테스트 없이는 "그려지긴 하니까" 통과해 보이는 종류의 버그). 세 값을 전수 고정한다.
test "configCursorShape: config↔terminal CursorShape 멤버 순서가 달라도 값이 보존된다" {
    var session: AppSession = undefined;
    session.appearance.cursor.shape = .block;
    try std.testing.expectEqual(terminal.CursorShape.block, settings_ops.configCursorShape(&session));
    session.appearance.cursor.shape = .bar;
    try std.testing.expectEqual(terminal.CursorShape.bar, settings_ops.configCursorShape(&session));
    session.appearance.cursor.shape = .underline;
    try std.testing.expectEqual(terminal.CursorShape.underline, settings_ops.configCursorShape(&session));
    // 숫자 재해석이었다면 bar(config 1)가 underline(terminal 1)로 갔을 것 — 그 경로를 명시적으로 배제한다.
    try std.testing.expect(@intFromEnum(config_mod.theme.CursorShape.bar) != @intFromEnum(terminal.CursorShape.bar));
}

test "cursorFadeMilliForPhase: 반주기 끝에서 대칭 램프(사라짐 1000→0·나타남 0→1000)·hold·페이드끔·clamp" {
    const f = AppSession.cursorFadeMilliForPhase;
    // 페이드 끔(fade=0): 위상만 보고 즉각 on/off(하드 토글 하위 호환).
    try std.testing.expectEqual(@as(u32, 1000), f(0, 30, 0, true));
    try std.testing.expectEqual(@as(u32, 1000), f(29, 30, 0, true));
    try std.testing.expectEqual(@as(u32, 0), f(0, 30, 0, false));
    try std.testing.expectEqual(@as(u32, 0), f(29, 30, 0, false));

    // half=30, fade=10 → hold=20. visible 반: [0,20) 완전 표시, [20,30) 1000→0으로 램프(마지막 tick에 정확히 0).
    try std.testing.expectEqual(@as(u32, 1000), f(0, 30, 10, true));
    try std.testing.expectEqual(@as(u32, 1000), f(19, 30, 10, true)); // 마지막 hold tick
    try std.testing.expectEqual(@as(u32, 900), f(20, 30, 10, true)); // 램프 첫 tick
    try std.testing.expectEqual(@as(u32, 500), f(24, 30, 10, true)); // 중간
    try std.testing.expectEqual(@as(u32, 0), f(29, 30, 10, true)); // 반주기 끝 = 완전히 사라짐
    // hidden 반: [0,20) 완전 숨김, [20,30) 0→1000으로 램프(마지막 tick에 정확히 1000 — 다음 visible 반에 이어짐).
    try std.testing.expectEqual(@as(u32, 0), f(0, 30, 10, false));
    try std.testing.expectEqual(@as(u32, 0), f(19, 30, 10, false));
    try std.testing.expectEqual(@as(u32, 100), f(20, 30, 10, false));
    try std.testing.expectEqual(@as(u32, 1000), f(29, 30, 10, false)); // 반주기 끝 = 완전 표시

    // clamp: fade가 반주기보다 크면 반주기로 잘려 hold 없는 삼각파(호흡) — half=10, fade=20 → fade=10, hold=0.
    try std.testing.expectEqual(@as(u32, 900), f(0, 10, 20, true)); // hold 없이 즉시 램프 시작
    try std.testing.expectEqual(@as(u32, 0), f(9, 10, 20, true));
    // half_ticks=0 방어: 최소 1로 clamp(0으로 나눗셈·언더플로 없음).
    try std.testing.expectEqual(@as(u32, 1000), f(0, 0, 0, true));
}

test "cursor blink fade: updateCursorBlink이 반주기 끝에서 커서 불투명도를 램프(중간값 존재)·램프 중 매 틱 generation↑·재빌드 없음" {
    var session: AppSession = undefined;
    session.allocator = std.testing.allocator;
    session.addr_edit = null; // 7e-2: inputFocus가 addr_edit을 읽음([[devsession-undefined-test-field-trap]])
    session.focus_owner = .workspace;
    session.pending_dock_focus = null;
    session.io = std.Io.Threaded.global_single_threaded.io(); // updateCursorBlink→readActiveSnapshot이 lockCore(self.io)
    var tab_surface = try maru.session.Surface.init(std.testing.allocator, 1, .{ .cols = 4, .rows = 2 });
    defer tab_surface.deinit();
    session.surface_initialized = true;
    var st_ptrs = [_]*maru.session.Surface{&tab_surface};
    session.app_window = .{ .tabs = &st_ptrs };
    session.metal_dirty = false;
    session.metal_buffer = .{};
    session.blink_visible = true;
    session.blink_phase_ns = 0;
    session.chrome_host = .{};
    session.rename = null;
    session.tabs = .empty;
    session.sidebar_rows = .empty;
    session.sidebar_collapsed = false;
    session.loaded_config.config = .{};
    session.frame_loop_rate_hz = 60; // 500ms@60Hz=30틱 반주기
    session.appearance.cursor.blink = true; // config 게이트 — updateCursorBlink가 읽음, undefined면 UB([[devsession-undefined-test-field-trap]])
    session.appearance.cursor.blink_interval_ms = 500;
    session.appearance.cursor.blink_fade_ms = 150; // 반주기 500 중 마지막 150ms가 램프 → hold 350ms

    // hold 구간(경과 300ms < hold 350ms): 완전 표시 유지 — 값 불변이라 generation 안 오름(idle 절전).
    session.blink_phase_ns = std.Io.Clock.awake.now(session.io).nanoseconds - 300 * std.time.ns_per_ms;
    session.updateCursorBlink(session.readActiveSnapshot(false));
    try std.testing.expectEqual(@as(u32, 1000), session.metal_buffer.cursor_fade_milli);
    try std.testing.expectEqual(@as(u64, 0), session.metal_buffer.generation);

    // 램프 한복판(경과 425ms = hold 350 + 75/150): 1000도 0도 아닌 **중간 불투명도**가 나온다(부드러운 페이드 증거).
    // 값이 바뀌었으니 generation이 오르고, 재빌드(metal_dirty)는 없다 — 커서 pass 불투명도만 바꿔 재present.
    session.blink_phase_ns = std.Io.Clock.awake.now(session.io).nanoseconds - 425 * std.time.ns_per_ms;
    session.updateCursorBlink(session.readActiveSnapshot(false));
    const mid = session.metal_buffer.cursor_fade_milli;
    try std.testing.expect(mid > 0 and mid < 1000);
    try std.testing.expect(session.metal_buffer.generation >= 1);
    try std.testing.expect(!session.metal_dirty);

    // 반주기를 넘기면 off 위상으로 토글 + 완전히 사라짐.
    testAdvanceBlinkHalves(&session, 1);
    session.updateCursorBlink(session.readActiveSnapshot(false));
    try std.testing.expect(!session.blink_visible);
    try std.testing.expectEqual(@as(u32, 0), session.metal_buffer.cursor_fade_milli);

    // 활동 리셋: 페이드 중이어도 즉시 완전 표시(1000)로 복귀 + baseline 폐기.
    session.blink_visible = true;
    session.metal_buffer.cursor_fade_milli = 400; // 반쯤 사라진 상태 가정
    session.resetCursorBlink();
    try std.testing.expectEqual(@as(u32, 1000), session.metal_buffer.cursor_fade_milli);
    try std.testing.expectEqual(@as(i128, 0), session.blink_phase_ns);
}

// 셸을 처음부터 실제 창 크기로 spawn하는 핸드셰이크 제거(zsh 첫 프롬프트 % 잔상 방지)를 고정한다. backing px가
// 주어지면 init이 cell 메트릭으로 grid를 계산해 그 크기로 spawn하고(80×24 아님), 없으면 cols/rows로 폴백한다.
test "init: backing px가 주어지면 셸을 그 창 grid로 spawn(80×24 핸드셰이크 없음), 없으면 cols/rows 폴백" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // refreshCellMetrics가 실제 CoreText 메트릭을 읽음
    const allocator = std.testing.allocator;
    // backing px(1600×900, 1x) 주어진 경우 — cols/rows(80×24)는 폴백값일 뿐, 실제 spawn은 창 grid여야 한다.
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
            .abi_version = abi_version,
            .cols = 80,
            .rows = 24,
            .queue_capacity = 16,
            .command_kind = @intFromEnum(CommandKind.controlled_smoke),
            .width_px = 1600,
            .height_px = 900,
            .scale_milli = 1000,
        });
        defer session.deinit();
        // spawn 크기 = layout_math.gridFromBacking(창 px, 세션 자신의 cell·사이드바 메트릭) — resize 경로와 같은 단일 출처.
        const expected = layout_math.gridFromBacking(1600, 900, session.cell_width_px, session.cell_height_px, session.sidebar_width_px, session.gridPadding()); // spawn은 gridPadding(상단 띠 포함)을 쓴다
        const got = pane_ops.activePane(session).activeTerm().surface.core.size;
        try std.testing.expectEqual(expected, got);
        try std.testing.expect(got.cols != 80 or got.rows != 24); // 80×24 폴백이 아니다(창이 더 넓어 grid가 다름)
    }
    // 2x(retina) — 진단: width_px=1920·scale_milli=2000일 때 cell·sidebar·grid 실측(MARU_DEBUG 로그).
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
            .abi_version = abi_version,
            .cols = 80,
            .rows = 24,
            .queue_capacity = 16,
            .command_kind = @intFromEnum(CommandKind.controlled_smoke),
            .width_px = 1920,
            .height_px = 1200,
            .scale_milli = 2000,
        });
        defer session.deinit();
        // 진단으로 확인됨: 2x에서 cell=17×37·sidebar_px=360·grid 91×32. init의 spawn 그리드는 정확하다(불일치 없음).
        const expected = layout_math.gridFromBacking(1920, 1200, session.cell_width_px, session.cell_height_px, session.sidebar_width_px, session.gridPadding()); // spawn은 gridPadding(상단 띠 포함)을 쓴다
        try std.testing.expectEqual(expected, pane_ops.activePane(session).activeTerm().surface.core.size);
    }
    // backing px 0(헤드리스·창 미상) — cols/rows로 폴백 spawn.
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
            .abi_version = abi_version,
            .cols = 100,
            .rows = 30,
            .queue_capacity = 16,
            .command_kind = @intFromEnum(CommandKind.controlled_smoke),
            .width_px = 0,
            .height_px = 0,
            .scale_milli = 0,
        });
        defer session.deinit();
        try std.testing.expectEqual(terminal.Size{ .cols = 100, .rows = 30 }, pane_ops.activePane(session).activeTerm().surface.core.size);
    }
}

fn testBuildSidebarTitleFrame(session: *AppSession) !renderer.RenderFrame {
    const dl = try sidebar_ops.buildSidebarTitleDrawList(session);
    return pane_ops.paneFrameBuilder(session).buildFromDrawList(session.allocator, dl, &session.renderer_state);
}

fn testBuildChromeOverlayFrame(session: *AppSession) !metal_frame.PaneFrame {
    const prep = (try session.buildChromeOverlayPrep()) orelse return error.NotOpen;
    const f = try prep.builder.buildFromDrawList(session.allocator, prep.dl, &session.renderer_state);
    return .{ .frame = f, .origin_x = prep.placement.origin_x, .origin_y = prep.placement.origin_y, .colors = prep.placement.colors, .clip_rect = prep.placement.clip_rect };
}

fn testBuildFloatingTabFrame(session: *AppSession, builder: coretext_frame_builder.CoreTextFrameBuilder, built_frames: *std.ArrayList(renderer.RenderFrame)) ?metal_frame.PaneFrame {
    const dp = tab_ops.buildFloatingTabDrawListAndPlacement(session) orelse return null;
    var f = builder.buildFromDrawList(session.allocator, dp.dl, &session.renderer_state) catch return null;
    built_frames.append(session.allocator, f) catch {
        f.deinit(session.allocator);
        return null;
    };
    return .{ .frame = f, .origin_x = dp.placement.origin_x, .origin_y = dp.placement.origin_y, .colors = dp.placement.colors };
}

test "placeAndDistribute: 멀티 페인 collect를 dest별로 분배 + collected 소진 + 소유권(누수/double-free 없음)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // 실 CoreText shapeOnly/place 경로
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // renderTick의 멀티 페인 빌드와 동일한 out 변수 셋업. defer들이 testing.allocator로 누수/double-free를 잡는다.
    var collected: std.ArrayList(AppSession.CollectedPane) = .empty;
    defer {
        for (collected.items) |*c| c.deinit(allocator); // placeAndDistribute가 소진하면 빈 배열(no-op)
        collected.deinit(allocator);
    }
    var pane_frames: std.ArrayList(metal_frame.PaneFrame) = .empty;
    defer pane_frames.deinit(allocator);
    var built_frames: std.ArrayList(renderer.RenderFrame) = .empty;
    defer {
        for (built_frames.items) |*bf| bf.deinit(allocator);
        built_frames.deinit(allocator);
    }
    var sidebar_frame: ?renderer.RenderFrame = null;
    defer if (sidebar_frame) |*f| f.deinit(allocator);
    var sidebar_header_frame: ?renderer.RenderFrame = null;
    defer if (sidebar_header_frame) |*f| f.deinit(allocator);
    var overlay_frame: ?metal_frame.PaneFrame = null;
    defer if (overlay_frame) |*pf| pf.frame.deinit(allocator);
    var floating_pf: ?metal_frame.PaneFrame = null; // built_frames 소유(view) — 따로 deinit 안 함
    var sticky_pf: ?metal_frame.PaneFrame = null; // built_frames 소유(view)
    var active_result: ?AppSession.ActiveResult = null; // built_frames 소유(view)

    const builder = pane_ops.paneFrameBuilder(session);
    const colors: metal_frame.CellColors = .{ .default_fg = session.appearance.theme.foreground };
    // 활성 surface의 DrawList(실 CoreText shape 대상)를 dest별로 collect — sidebar/pane/active/floating/sticky 5종.
    const dests = [_]AppSession.CollectDest{
        .sidebar,
        .{ .pane = .{ .origin_x = 100, .origin_y = 0, .colors = colors } },
        .active,
        .{ .floating = .{ .origin_x = 50, .origin_y = 50, .colors = colors } },
        .{ .sticky = .{ .origin_x = 100, .origin_y = 20, .colors = colors } },
    };
    for (dests) |dest| {
        const active = session.app_window.active().?;
        active.lockCore(session.io);
        const dl_or = renderer.buildDrawListWithUnfocused(allocator, active.renderSnapshot(), .normal);
        active.unlockCore(session.io);
        const dl = dl_or catch continue;
        session.collectShaped(&collected, dl, builder, dest);
    }
    try std.testing.expectEqual(@as(usize, 5), collected.items.len); // 5종 전부 shapeOnly 성공

    session.placeAndDistribute(&collected, &pane_frames, &built_frames, &sidebar_frame, &sidebar_header_frame, &overlay_frame, &floating_pf, &sticky_pf, &active_result);

    // dest 분배 정확성(리뷰 #4: wrong dest routing 방지).
    try std.testing.expect(sidebar_frame != null); // .sidebar → sidebar_frame(소유)
    try std.testing.expect(active_result != null); // .active → active_result(built_frames 소유, view)
    try std.testing.expect(floating_pf != null); // .floating → floating_pf(built_frames 소유, view)
    try std.testing.expect(sticky_pf != null); // .sticky → sticky_pf(built_frames 소유, view)
    try std.testing.expectEqual(@as(usize, 1), pane_frames.items.len); // .pane만 pane_frames(active append는 호출자 몫)
    try std.testing.expectEqual(@as(usize, 4), built_frames.items.len); // .pane + .active + .floating + .sticky 소유
    // .pane placement 보존(분배 시 origin이 안 뒤섞임).
    try std.testing.expectEqual(@as(u32, 100), pane_frames.items[0].origin_x);
    // collected는 placeAndDistribute가 clearRetainingCapacity로 소진(finishPane consume ↔ 바깥 defer double-free 차단).
    try std.testing.expectEqual(@as(usize, 0), collected.items.len);
}

test "buildSidebarTitleFrame: 에이전트 심볼(✶/◆) prefix여도 프레임 빌드 성공(제목 사라짐 회귀 방지)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // 실 CoreText shaper 경로
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    // 에이전트 없음 → 정상 빌드(baseline).
    {
        var f = try testBuildSidebarTitleFrame(session);
        f.deinit(allocator);
    }
    // claude/codex 심볼 prefix가 붙어도 buildSidebarTitleFrame이 에러 없이 프레임을 만들어야 한다
    // (catch null로 흘러 전체 사이드바 제목이 사라지면 안 됨).
    tab_ops.activeTab(session).activePane().activeTerm().agent_kind = .claude;
    {
        var f = try testBuildSidebarTitleFrame(session);
        f.deinit(allocator);
    }
    tab_ops.activeTab(session).activePane().activeTerm().agent_kind = .codex;
    {
        var f = try testBuildSidebarTitleFrame(session);
        f.deinit(allocator);
    }
    // 3줄 카드(이름/브랜치/경로): buildSidebarTitleFrame은 buildSidebarDrawList 결과를 indent_cols만큼 우측 시프트한다.
    // 폭을 꽉 채운 긴 경로줄이 size.cols를 넘으면 ShapedRecordOutsideSurface로 프레임이 통째로 실패(catch null →
    // 사이드바 텍스트 전부 사라짐). 시프트 후 size.cols를 full_cols로 넓혀 수용하는지 고정 — 실 앱에서 못 봤던 버그.
    {
        const names = [_][]const u8{"\u{2733} maru"};
        const branches = [_][]const u8{comptime icons.utf8(.mark_github) ++ " main"};
        const paths = [_][]const u8{"~/documents/workspace/maru"}; // 길어 좁은 폭을 꽉 채움 → 시프트 시 overflow
        const muted: terminal.Color = .{ .rgb = session.appearance.theme.sidebar_foreground };
        const sidebar_cols: u16 = 12;
        const indent_cols: u16 = 3;
        const full_cols: u16 = 20; // ≥ sidebar_cols + indent_cols
        const fb = coretext_frame_builder.CoreTextFrameBuilder{
            .appearance = session.appearance,
            .shape_draw_list = coretext_bridge.maru_macos_coretext_shape_draw_list,
            .rasterize_glyph = coretext_bridge.maru_macos_coretext_smoke_rasterize_glyph,
            .scale_milli = session.scale_milli,
            .cell_width_px = @intCast(session.cell_width_px),
            .cell_height_px = @intCast(session.cell_height_px),
        };
        // (1) 시프트만 하고 size.cols를 안 넓히면 ShapedRecordOutsideSurface로 실패함을 고정(버그 재현 — buildFromDrawList가
        //     실패 시 draw_list를 정리하므로 별도 free 안 함).
        {
            const dl = try coretext_frame_builder.buildSidebarDrawList(allocator, &names, &branches, &paths, &[_][]const u8{}, &[_]u21{}, &[_]u21{}, &[_]bool{}, sidebar_cols, muted, &.{}, &.{}, 1, 0, muted, null);
            for (dl.cells) |*c| c.col += indent_cols;
            try std.testing.expectError(error.ShapedRecordOutsideSurface, fb.buildFromDrawList(allocator, dl, &session.renderer_state));
        }
        // (2) 시프트 후 size.cols=full_cols로 넓히면(수정) 정상 빌드 + row 보존(이름 idx0·경로 idx2, count=3).
        {
            var dl = try coretext_frame_builder.buildSidebarDrawList(allocator, &names, &branches, &paths, &[_][]const u8{}, &[_]u21{}, &[_]u21{}, &[_]bool{}, sidebar_cols, muted, &.{}, &.{}, 1, 0, muted, null);
            for (dl.cells) |*c| c.col += indent_cols;
            dl.size.cols = full_cols;
            var f = try fb.buildFromDrawList(allocator, dl, &session.renderer_state);
            defer f.deinit(allocator);
            var saw_name = false;
            var saw_path = false;
            for (f.glyph_quad_frame.glyphs) |g| {
                if (g.run.codepoint == 'm' and g.run.row == coretext_frame_builder.sidebarGlyphRow(0, 0, 3)) saw_name = true;
                if (g.run.codepoint == '~' and g.run.row == coretext_frame_builder.sidebarGlyphRow(0, 2, 3)) saw_path = true;
            }
            try std.testing.expect(saw_name);
            try std.testing.expect(saw_path);
        }
    }
}

test "headless ticks toggle the blink phase and bump the metal generation" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // 실제 CoreText frame builder 경로
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // 출력 타이밍에 흔들리지 않게(느린 CI에서 controlled 출력이 여러 tick에 걸쳐 와 위상을
    // 계속 리셋할 수 있다) "첫 토글이 관측될 때까지" 충분한 상한으로 tick한다 — 출력은 유한하니
    // 멎은 뒤 interval 틱이 지나면 반드시 토글된다.
    // 먼저 controlled 출력이 멎을 때까지 tick한다(출력 tick은 resetCursorBlink라 위상이 계속 리셋된다).
    var i: usize = 0;
    while (i < 200) : (i += 1) _ = try session.tick();
    // 위상은 이제 **실경과 시간** 기준이라(§10.5) tick을 아무리 돌려도 500ms가 안 지나면 안 넘어간다 — CI 속도에
    // 의존하지 않게 baseline을 한 반주기 과거로 밀어 다음 tick이 정확히 한 번 토글하게 한다(타이밍만 주입, 경로는 실제 tick).
    var toggles: usize = 0;
    var gen_changes: usize = 0;
    const last_vis = session.blink_visible;
    const last_gen: u64 = session.metal_buffer.generation;
    testAdvanceBlinkHalves(session, 1);
    _ = try session.tick();
    if (session.blink_visible != last_vis) toggles += 1;
    if (session.metal_buffer.generation != last_gen) gen_changes += 1;
    try std.testing.expect(toggles >= 1);
    // 토글은 rebuild 없이도 재드로우를 유발해야 한다(setCursorVisible의 generation 증가).
    try std.testing.expect(gen_changes >= toggles);
}

// 인라인 rename 동작(PR3): start→입력→commit이 custom_name을 쓰고, cancel은 원래 이름 유지, 빈 텍스트 commit은
// 이름을 지우고, 대상 Term teardown이 rename을 자동 취소(stale 포인터 방지)하는지를 풀-세션 경로로 고정한다.
test "context menu: workspace=Rename+Pin+배경 항목, accept가 pin 토글·배경색 설정; pane/term=Rename만" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    const tab = tab_ops.activeTab(session);

    // workspace 대상: Rename + Pin + 배경 프리셋(없음·앰버·파랑·초록·빨강·보라) + 바 프리셋(같은 6색) + 그룹(묶기·분리·풀기·색).
    // "그룹에서 빼기"는 **그룹 소속 카드에만** 뜨므로 미그룹 활성 카드엔 안 나온다(아래 그룹 생성 후 등장 확인).
    session.context_menu_target = .{ .workspace = tab };
    const items = settings_ops.buildContextMenuItems(session);
    try std.testing.expectEqual(@as(usize, 2 + tab_color_presets.len + tab_accent_labels.len + 3 + tab_group_color_labels.len), items.len);
    try std.testing.expectEqual(ctx_menu_group_remove, items.len); // 최상위 카드 → 빼기 미포함(버퍼 최대 ctx_menu_count보다 1 적다)
    try std.testing.expectEqualStrings("Rename", items[0]);
    try std.testing.expectEqualStrings(maru.i18n.t(.ctx_pin), items[1]); // 미고정 → "위치 고정"
    try std.testing.expectEqualStrings("배경: 없음", items[ctx_menu_bg_first]);
    try std.testing.expectEqualStrings("바: 없음", items[ctx_menu_accent_first]);
    try std.testing.expectEqualStrings(maru.i18n.t(.ctx_group_create), items[ctx_menu_group_create]);
    try std.testing.expectEqualStrings(maru.i18n.t(.ctx_group_sibling), items[ctx_menu_group_sibling]); // SG5-3 형제 액션
    try std.testing.expectEqualStrings(maru.i18n.t(.ctx_group_ungroup), items[ctx_menu_group_ungroup]);
    try std.testing.expectEqualStrings("그룹 색: 없음", items[ctx_menu_group_color_first]); // SG5-2 그룹 색 프리셋(카드 색과 같은 팔레트)
    try std.testing.expectEqualStrings("그룹 색: 파랑", items[ctx_menu_group_color_first + 2]);

    // 그룹으로 묶기(selected=create) → 활성 워크스페이스에 group_start 마커. 풀기(selected=ungroup) → 제거.
    session.context_menu_target = .{ .workspace = tab };
    session.chrome_host.context_menu.selected = ctx_menu_group_create;
    settings_ops.acceptContextMenu(session);
    try std.testing.expect(tab.group_start != null);
    // 그룹 소속이 되면 메뉴 맨 끝에 "그룹에서 빼기"가 뜬다. **tab은 이제 마커 카드**(createGroup으로 group_start!=null)라
    // "여기서 최상위로 분리"(promote)는 숨긴다(§14.8 SR5 결정 (a) — 마커 promote no-op). 그래서 len=ctx_menu_group_promote
    // (=ctx_menu_count-1, remove까지만)이고 remove=ctx_menu_group_remove에 그대로 정렬한다(마커에선 promote 슬롯 비어 한 칸 짧다).
    session.context_menu_target = .{ .workspace = tab };
    const grouped_items = settings_ops.buildContextMenuItems(session);
    try std.testing.expectEqual(ctx_menu_group_promote, grouped_items.len); // 마커 → remove만(promote 숨김)
    try std.testing.expectEqualStrings(maru.i18n.t(.ctx_group_remove), grouped_items[ctx_menu_group_remove]);
    session.context_menu_target = .{ .workspace = tab };
    session.chrome_host.context_menu.selected = ctx_menu_group_ungroup;
    settings_ops.acceptContextMenu(session);
    try std.testing.expect(tab.group_start == null);

    // accept selected=1 → pin 토글(true). acceptContextMenu가 target을 null화하므로 매번 재설정.
    session.context_menu_target = .{ .workspace = tab };
    session.chrome_host.context_menu.selected = 1;
    settings_ops.acceptContextMenu(session);
    try std.testing.expect(tab.pinned);

    // 다시 열면 "고정 해제"가 뜬다(토글 상태 반영).
    session.context_menu_target = .{ .workspace = tab };
    try std.testing.expectEqualStrings(maru.i18n.t(.ctx_unpin), settings_ops.buildContextMenuItems(session)[1]);

    // accept selected=3(배경: 앰버, idx 0=Rename·1=Pin·2=없음·3=앰버) → background_color = 0xDDA15E.
    session.context_menu_target = .{ .workspace = tab };
    session.chrome_host.context_menu.selected = ctx_menu_bg_first + 1;
    settings_ops.acceptContextMenu(session);
    try std.testing.expectEqual(@as(u32, 0xDDA15E), tab.background_color);

    // 배경: 없음(selected=2) → 0으로 해제.
    session.context_menu_target = .{ .workspace = tab };
    session.chrome_host.context_menu.selected = ctx_menu_bg_first;
    settings_ops.acceptContextMenu(session);
    try std.testing.expectEqual(@as(u32, 0), tab.background_color);

    // 바: 파랑(accent_first + 2, 프리셋 0=없음·1=앰버·2=파랑) → accent_color = 0x4A7BC4(배경과 직교, 별도 필드).
    session.context_menu_target = .{ .workspace = tab };
    session.chrome_host.context_menu.selected = ctx_menu_accent_first + 2;
    settings_ops.acceptContextMenu(session);
    try std.testing.expectEqual(@as(u32, 0x4A7BC4), tab.accent_color);
    try std.testing.expectEqual(@as(u32, 0), tab.background_color); // 배경은 안 건드림(직교 확인)

    // 바: 없음(accent_first) → 0으로 해제.
    session.context_menu_target = .{ .workspace = tab };
    session.chrome_host.context_menu.selected = ctx_menu_accent_first;
    settings_ops.acceptContextMenu(session);
    try std.testing.expectEqual(@as(u32, 0), tab.accent_color);

    // 그룹 색(SG5-2): 그룹에 안 속하면 no-op(색 얹을 마커 없음). tab은 앞서 ungroup되어 group_start==null.
    session.context_menu_target = .{ .workspace = tab };
    session.chrome_host.context_menu.selected = ctx_menu_group_color_first + 2; // 파랑
    settings_ops.acceptContextMenu(session);
    try std.testing.expectEqual(@as(u32, 0), tab.group_color); // 그룹 아님 → no-op

    // 그룹으로 묶은 뒤 그룹 색: 파랑 → 마커 탭(=자기)에 group_color. 개별 background/accent는 안 건드림(층 분리 — 직교).
    session.context_menu_target = .{ .workspace = tab };
    session.chrome_host.context_menu.selected = ctx_menu_group_create;
    settings_ops.acceptContextMenu(session);
    session.context_menu_target = .{ .workspace = tab };
    session.chrome_host.context_menu.selected = ctx_menu_group_color_first + 2; // 파랑(프리셋 0=없음·1=앰버·2=파랑)
    settings_ops.acceptContextMenu(session);
    try std.testing.expectEqual(@as(u32, 0x4A7BC4), tab.group_color);
    try std.testing.expectEqual(@as(u32, 0), tab.background_color); // 그룹 색은 카드 배경 tint와 직교(다른 층)
    try std.testing.expectEqual(@as(u32, 0), tab.accent_color); // 그룹 색은 개별 accent 막대와도 별도 저장

    // 그룹 색: 없음(group_color_first) → 0으로 해제.
    session.context_menu_target = .{ .workspace = tab };
    session.chrome_host.context_menu.selected = ctx_menu_group_color_first;
    settings_ops.acceptContextMenu(session);
    try std.testing.expectEqual(@as(u32, 0), tab.group_color);
    // 정리: 다음 pane/term 검증 전에 그룹 마커 해제(단일 탭 그룹).
    session.context_menu_target = .{ .workspace = tab };
    session.chrome_host.context_menu.selected = ctx_menu_group_ungroup;
    settings_ops.acceptContextMenu(session);

    // pane/term 대상은 Rename만(색·고정 없음).
    session.context_menu_target = .{ .pane = pane_ops.activePane(session) };
    try std.testing.expectEqual(@as(usize, 1), settings_ops.buildContextMenuItems(session).len);
    session.context_menu_target = null;
}

test "group header context menu(SG5-2-header): 헤더 우클릭 = Rename+그룹 풀기+그룹 색, accept가 마커 탭에 색 세팅·ungroup" {
    // 증명: 그룹 **헤더** 우클릭(context_menu_target=.group, 대상=group_start 마커 탭)이 카드 우클릭과 **같은** 그룹 색
    // 메뉴를 띄우고, accept 시 setGroupColorForTab/ungroupTab이 그 마커 그룹에 적용된다. 사용자 피드백("헤더 우클릭에 색이
    // 안 보인다")을 헤드리스로 고정한다. 이전엔 .group 대상 메뉴가 Rename 하나뿐이라 헤더에서 색을 못 찾았다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try tab_ops.newTab(session);
    _ = try tab_ops.newTab(session); // [t0, t1, t2]
    try std.testing.expect(session.tabs.items.len >= 3);
    const marker = session.tabs.items[1];
    tab_ops.createGroupAbsorbForTab(session, marker); // t1=그룹 시작 마커(헤더가 가리키는 탭)

    // 헤더 우클릭 대상 = 마커 탭(.group). 메뉴: Rename + 그룹 고정 + 그룹 풀기 + 그룹 색 6프리셋 = 3 + tab_group_color_labels.len.
    session.context_menu_target = .{ .group = marker };
    const items = settings_ops.buildContextMenuItems(session);
    try std.testing.expectEqual(@as(usize, 3 + tab_group_color_labels.len), items.len);
    try std.testing.expectEqualStrings("Rename", items[0]); // 그룹 이름 편집(startRename(.group))
    try std.testing.expectEqualStrings(maru.i18n.t(.ctx_group_pin_header), items[ctx_group_menu_pin]); // GP3 §12.10 — 미고정 그룹 → "그룹 고정"
    try std.testing.expectEqualStrings(maru.i18n.t(.ctx_group_ungroup), items[ctx_group_menu_ungroup]);
    try std.testing.expectEqualStrings("그룹 색: 없음", items[ctx_group_menu_color_first]); // 카드 메뉴와 같은 색 라벨 공유
    try std.testing.expectEqualStrings("그룹 색: 파랑", items[ctx_group_menu_color_first + 2]);

    // accept 그룹 색: 파랑 → 마커 탭(t1)에 group_color(카드 우클릭 색 dispatch와 같은 setGroupColorForTab 경로).
    session.context_menu_target = .{ .group = marker };
    session.chrome_host.context_menu.selected = ctx_group_menu_color_first + 2; // 파랑(0=없음·1=앰버·2=파랑)
    settings_ops.acceptContextMenu(session);
    try std.testing.expectEqual(@as(u32, 0x4A7BC4), marker.group_color);
    try std.testing.expectEqual(@as(u32, 0), marker.background_color); // 그룹 색은 개별 카드 배경/막대와 직교(층 분리)
    try std.testing.expectEqual(@as(u32, 0), marker.accent_color);

    // accept 그룹 색: 없음 → 0으로 해제(카드 메뉴와 동일한 폴백).
    session.context_menu_target = .{ .group = marker };
    session.chrome_host.context_menu.selected = ctx_group_menu_color_first; // 없음
    settings_ops.acceptContextMenu(session);
    try std.testing.expectEqual(@as(u32, 0), marker.group_color);

    // accept Rename(sel=0) → 그룹 이름 인라인 편집 시작(마커 group_start 시드). 그룹은 유지.
    session.context_menu_target = .{ .group = marker };
    session.chrome_host.context_menu.selected = 0;
    settings_ops.acceptContextMenu(session);
    try std.testing.expect(session.rename != null);
    try std.testing.expect(std.meta.activeTag(session.rename.?) == .group);
    settings_ops.closeRename(session);
    try std.testing.expect(marker.group_start != null); // Rename은 그룹을 풀지 않는다(ungroup과 분리)

    // accept 그룹 풀기(ungroup) → 마커의 group_start 제거(그룹 해제). 헤더 스코프 액션이 마커에 그대로 적용됨.
    session.context_menu_target = .{ .group = marker };
    session.chrome_host.context_menu.selected = ctx_group_menu_ungroup;
    settings_ops.acceptContextMenu(session);
    try std.testing.expect(marker.group_start == null);
}

test "sidebar group color(SG5-2): 그룹 색 → 헤더 밴드 tint·소속 카드 막대 gpu_quad(층 분리)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli); // rich 메트릭(둥근 밴드=gpu_quad·막대 폭>0)

    // 워크스페이스 3개 [t0, t1, t2], t1에 그룹 시작 마커 → t0=최상위, t1·t2=그룹 소속(위치 파생).
    _ = try tab_ops.newTab(session);
    _ = try tab_ops.newTab(session);
    try std.testing.expect(session.tabs.items.len >= 3);
    tab_ops.createGroupAbsorbForTab(session, session.tabs.items[1]);

    const hasQuad = struct {
        fn run(s: *const AppSession, fill: u32) bool {
            for (s.gpu_quads.items) |q| if (q.fill_color0 == fill) return true;
            return false;
        }
    }.run;
    const group_bar = sidebar_ops.packStraightRgbU32(0x4A7BC4, 0xFF); // 그룹 색 막대(불투명) = 0xFF4A7BC4

    // 색 지정 전: 소속 카드가 무색이라 그룹 색 막대는 없다(활성만 기본 accent, 비활성은 막대 없음).
    sidebar_ops.rebuildSidebar(session) catch {};
    try std.testing.expect(!hasQuad(session, group_bar));

    // 그룹 색(파랑) 지정 → 마커 탭(t1)에만 group_color. rebuildSidebar가 소속 카드(t1·t2) 좌측 막대에 그룹 색을 싣는다.
    tab_ops.setGroupColorForTab(session, session.tabs.items[1], 0x4A7BC4);
    try std.testing.expectEqual(@as(u32, 0x4A7BC4), session.tabs.items[1].group_color);
    try std.testing.expect(hasQuad(session, group_bar)); // 소속 카드 막대 = 그룹 색

    // 헤더 밴드 그룹 색 tint: lowerSidebar가 헤더 밴드(.tab_hover_bg) 색에 그룹 색을 **카드 배경 tint와 같은 blend
    // 경로·같은 알파**로 섞는다. 렌더가 쓰는 것과 동일한 헬퍼로 기대값을 계산해 정확히 일치하는 quad가 있는지 본다.
    const expected_header = session.chromeQuadBg(blendRgb(sidebar_ops.sidebarHoverBg(session), 0x4A7BC4, sidebar_ops.tab_bg_tint_alpha));
    try std.testing.expect(hasQuad(session, expected_header));

    // 층 분리: 그룹 색은 마커 탭의 group_color에만 실리고 개별 카드 background_color/accent_color는 0(안 겹침).
    try std.testing.expectEqual(@as(u32, 0), session.tabs.items[1].background_color);
    try std.testing.expectEqual(@as(u32, 0), session.tabs.items[1].accent_color);
    try std.testing.expectEqual(@as(u32, 0), session.tabs.items[2].group_color); // 소속 카드는 group_color 저장 안 함(위치 파생)

    // 색 없는 그룹 폴백: 그룹 색을 0으로 해제하면 그룹 색 막대가 사라진다(기본 폴백 — 활성만 기본 accent).
    tab_ops.setGroupColorForTab(session, session.tabs.items[1], 0);
    try std.testing.expectEqual(@as(u32, 0), session.tabs.items[1].group_color);
    try std.testing.expect(!hasQuad(session, group_bar));
}

test "right-click menu(F2-5): 터미널 컨텍스트 메뉴 복사/붙여넣기 → pending_clipboard_action, takeClipboardAction 1회성" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // showTerminalContextMenu가 복사/붙여넣기 2항목을 박고 terminal_context_menu 플래그를 세운다.
    settings_ops.showTerminalContextMenu(session, 200, 100);
    try std.testing.expect(session.terminal_context_menu);
    const items = settings_ops.contextMenuItems(session);
    try std.testing.expectEqual(@as(usize, 2), items.len);
    try std.testing.expectEqualStrings(maru.i18n.t(.ctx_copy), items[0]);
    try std.testing.expectEqualStrings(maru.i18n.t(.ctx_paste), items[1]);

    // 항목 0(복사) accept → pending=.copy, 메뉴 닫힘(terminal_context_menu 비움).
    session.chrome_host.context_menu.selected = 0;
    settings_ops.acceptContextMenu(session);
    try std.testing.expect(!session.terminal_context_menu);
    // takeClipboardAction이 1회성 — 처음엔 .copy, 다음엔 .none.
    try std.testing.expectEqual(ClipboardAction.copy, session.takeClipboardAction());
    try std.testing.expectEqual(ClipboardAction.none, session.takeClipboardAction());

    // 항목 1(붙여넣기) accept → pending=.paste.
    settings_ops.showTerminalContextMenu(session, 200, 100);
    session.chrome_host.context_menu.selected = 1;
    settings_ops.acceptContextMenu(session);
    try std.testing.expectEqual(ClipboardAction.paste, session.takeClipboardAction());

    // 기본 config는 paste(사용자 결정) — 트래킹 .none이면 우클릭이 paste 동작을 의도.
    try std.testing.expectEqual(config_mod.theme.RightClick.paste, session.loaded_config.config.input.right_click);
}

test "observer 강등: 입력이 안 되는 이유를 notice로 알리고 모달 중엔 보존한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // 강등이 없었으면 아무 notice도 안 뜬다.
    session.showPendingObserverAttachNotice();
    try std.testing.expect(!session.chrome_host.notice.open);

    // host가 두 번째 controller를 observer로 강등하면(§9) attach는 성공으로 돌아오지만 입력이 전부 거부된다.
    // 그 사실을 알리지 않으면 사용자는 "화면은 나오는데 키가 안 먹는" 터미널을 이유도 모른 채 쓰게 된다.
    session.observer_attach_notice_pending = true;
    session.showPendingObserverAttachNotice();
    try std.testing.expect(session.chrome_host.notice.open);
    try std.testing.expect(!session.observer_attach_notice_pending); // 1회성
    session.chrome_host.notice.dismiss();

    // 불청 이벤트라 모달이 열려 있으면 억제한다 — showNotice가 그 모달을 닫아 사용자를 끊지 않게.
    session.chrome_host.settings.open = true;
    session.observer_attach_notice_pending = true;
    session.showPendingObserverAttachNotice();
    try std.testing.expect(!session.chrome_host.notice.open);
    try std.testing.expect(session.observer_attach_notice_pending); // 신호는 보존 — 다음 tick에 다시 시도한다
    session.chrome_host.settings.open = false;
    session.showPendingObserverAttachNotice();
    try std.testing.expect(session.chrome_host.notice.open);
}

test "OSC 52 상한 초과 거부: surfaceClipboardWriteRejected가 notice로 표면화(모달 열림 시 억제)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // 거부 신호가 없으면 아무 notice도 안 뜬다.
    term_ops.surfaceClipboardWriteRejected(session);
    try std.testing.expect(!session.chrome_host.notice.open);

    // 코어가 거부 신호를 세우면 tick 헬퍼가 notice를 띄우고 신호를 소비한다(1회성).
    term_ops.activeSurface(session).core.clipboard_write_rejected = true;
    term_ops.surfaceClipboardWriteRejected(session);
    try std.testing.expect(session.chrome_host.notice.open); // 무음 실패 대신 가시적
    try std.testing.expect(!term_ops.activeSurface(session).core.clipboard_write_rejected); // drain됨
    session.chrome_host.notice.dismiss();

    // 인터랙티브 모달(세팅)이 열려 있으면 억제 — 사용자를 끊지 않는다. 신호도 아직 안 건드린다(락 전 early-return).
    session.chrome_host.settings.open = true;
    term_ops.activeSurface(session).core.clipboard_write_rejected = true;
    term_ops.surfaceClipboardWriteRejected(session);
    try std.testing.expect(!session.chrome_host.notice.open); // 억제됨
    try std.testing.expect(term_ops.activeSurface(session).core.clipboard_write_rejected); // 신호 보존(drain 안 함)
    session.chrome_host.settings.open = false;

    // 모달을 닫으면 다음 표면화에서 정상적으로 뜬다(보존된 신호 소비).
    term_ops.surfaceClipboardWriteRejected(session);
    try std.testing.expect(session.chrome_host.notice.open);
    try std.testing.expect(!term_ops.activeSurface(session).core.clipboard_write_rejected);
}

test "파일 저장 실패는 native notice로 표면화하고 close-save 중엔 억제한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // ⌘S 등 일반 저장 실패는 웹뷰 sticky 텍스트 대신 chrome native notice로 뜬다(무음 실패도, 안 사라지는 텍스트도 아님).
    try std.testing.expect(!session.chrome_host.notice.open);
    session.noticeFilePanelWriteFailure(901, error.ExternalConflict);
    try std.testing.expect(session.chrome_host.notice.open);
    session.chrome_host.notice.dismiss();

    // close-save(phase=.saving)가 진행 중이면 억제한다 — completeFilePanelSaveClose가 "…탭을 닫지 않았습니다"
    // notice를 이미 띄우므로 중복을 피한다. early-return이라 showNotice/cancelPendingClose를 타지 않으므로 스택
    // expected_path를 써도 안전하고, teardown 전에 null로 되돌린다.
    var fake_path = [_]u8{'x'};
    session.pending_file_panel_close = .{
        .surface_id = 901,
        .surface_generation = 0,
        .request_id = 1,
        .expected_path = fake_path[0..],
        .state_generation = 0,
        .phase = .saving,
    };
    session.noticeFilePanelWriteFailure(901, error.ExternalConflict);
    try std.testing.expect(!session.chrome_host.notice.open); // 억제됨
    session.pending_file_panel_close = null;
}

test "OSC 52 read(F2-6): 정책 게이트(deny=무응답·allow=true) + base64 응답 포맷" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // 응답 포맷(순수): "hi" = base64 "aGk=" → ESC ] 52 ; c ; aGk= ESC \. 빈 target은 c로.
    const r1 = session.formatOsc52ReadResponse("c", "hi").?;
    defer allocator.free(r1);
    try std.testing.expectEqualStrings("\x1b]52;c;aGk=\x1b\\", r1);
    const r2 = session.formatOsc52ReadResponse("", "hi").?; // 빈 Pc → c
    defer allocator.free(r2);
    try std.testing.expectEqualStrings("\x1b]52;c;aGk=\x1b\\", r2);
    const r3 = session.formatOsc52ReadResponse("p", "").?; // 빈 클립보드도 응답(빈 base64)
    defer allocator.free(r3);
    try std.testing.expectEqualStrings("\x1b]52;p;\x1b\\", r3);

    // 정책 게이트: 기본 deny. 코어에 `?` 읽기 쿼리를 흘리고 takeClipboardReadRequest는 false(클립보드 안 읽음),
    // 그래도 코어 pending은 소비(clear)된다.
    try std.testing.expectEqual(config_mod.theme.Osc52Read.deny, session.loaded_config.config.osc52.read);
    {
        const s = term_ops.activeSurface(session);
        s.lockCore(session.io);
        s.core.write("\x1b]52;c;?\x1b\\") catch {};
        s.unlockCore(session.io);
    }
    try std.testing.expect(!session.takeClipboardReadRequest()); // deny → false
    {
        const s = term_ops.activeSurface(session);
        s.lockCore(session.io);
        const still_pending = s.core.clipboardReadPending();
        s.unlockCore(session.io);
        try std.testing.expect(!still_pending); // deny여도 소비됨(재트리거 방지)
    }

    // allow면 true + target 캡처.
    session.loaded_config.config.osc52.read = .allow;
    {
        const s = term_ops.activeSurface(session);
        s.lockCore(session.io);
        s.core.write("\x1b]52;p;?\x1b\\") catch {};
        s.unlockCore(session.io);
    }
    try std.testing.expect(session.takeClipboardReadRequest()); // allow → true
    try std.testing.expectEqualStrings("p", session.clipboard_read_target_buf.items); // 응답 echo용 target
}

test "moveTab: 고정 탭은 고정 영역 안에서만, 비고정은 비고정 영역 안에서만 재정렬(그룹 clamp)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    // 4탭으로(앞 2개 고정, 뒤 2개 비고정). newTab은 끝에 추가.
    inline for (0..3) |_| _ = try tab_ops.newTab(session);
    try std.testing.expectEqual(@as(usize, 4), session.tabs.items.len);
    const t0 = session.tabs.items[0];
    const t1 = session.tabs.items[1];
    const t2 = session.tabs.items[2];
    const t3 = session.tabs.items[3];
    t0.pinned = true;
    t1.pinned = true; // [P0, P1, u2, u3], pinned_count=2

    // 고정(0)을 아래(끝, 3)로 끌어도 고정 영역 [0,2)로 clamp → swap(0↔1)만. 비고정(2,3) 불변.
    // moveTab은 clamp으로 확정된 안착 인덱스(1)를 반환한다.
    try std.testing.expectEqual(@as(usize, 1), tab_ops.moveTab(session, 0, 3));
    try std.testing.expectEqual(t1, session.tabs.items[0]);
    try std.testing.expectEqual(t0, session.tabs.items[1]);
    try std.testing.expectEqual(t2, session.tabs.items[2]); // 비고정 불변
    try std.testing.expectEqual(t3, session.tabs.items[3]);

    // 비고정(끝, 3=t3)을 위(0)로 끌어도 비고정 영역 [2,4)로 clamp → t3가 2로, t2가 3으로. 고정(0,1) 불변.
    // 안착 인덱스(2) 반환.
    try std.testing.expectEqual(@as(usize, 2), tab_ops.moveTab(session, 3, 0));
    try std.testing.expectEqual(t1, session.tabs.items[0]); // 고정 영역 불변
    try std.testing.expectEqual(t0, session.tabs.items[1]);
    try std.testing.expectEqual(t3, session.tabs.items[2]); // 비고정 영역 시작으로만
    try std.testing.expectEqual(t2, session.tabs.items[3]);
}

test "tab_ops.togglePin: pin은 탭을 고정 영역 끝으로, unpin은 비고정 영역 시작으로 정렬(불변식 유지)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..3) |_| _ = try tab_ops.newTab(session);
    try std.testing.expectEqual(@as(usize, 4), session.tabs.items.len);
    const t0 = session.tabs.items[0];
    const t1 = session.tabs.items[1];
    const t2 = session.tabs.items[2];
    const t3 = session.tabs.items[3];

    // 끝 탭(t3)을 pin → 고정 영역 끝(index 0, 첫 고정)으로 이동. 나머지 한 칸씩 밀림.
    tab_ops.togglePin(session, t3);
    try std.testing.expect(t3.pinned);
    try std.testing.expectEqual(t3, session.tabs.items[0]);
    try std.testing.expectEqual(@as(usize, 1), tab_ops.countPinnedTabs(session));
    // 불변식: tabs[0..pinned_count]가 전부 고정.
    try assertPinnedPrefix(session);

    // 중간 탭(t1, 지금 index 2)을 pin → 고정 영역 끝(index 1)으로 이동.
    tab_ops.togglePin(session, t1);
    try std.testing.expect(t1.pinned);
    try std.testing.expectEqual(t3, session.tabs.items[0]);
    try std.testing.expectEqual(t1, session.tabs.items[1]);
    try std.testing.expectEqual(@as(usize, 2), tab_ops.countPinnedTabs(session));
    try assertPinnedPrefix(session);

    // t3 unpin → 비고정 영역 시작(새 pinned_count=1, index 1)으로 이동. t1만 고정으로 남음(index 0).
    tab_ops.togglePin(session, t3);
    try std.testing.expect(!t3.pinned);
    try std.testing.expectEqual(t1, session.tabs.items[0]);
    try std.testing.expectEqual(t3, session.tabs.items[1]);
    try std.testing.expectEqual(@as(usize, 1), tab_ops.countPinnedTabs(session));
    try assertPinnedPrefix(session);
    // 나머지 비고정(t0,t2)은 t3 뒤.
    try std.testing.expect(!t0.pinned and !t2.pinned);
}

/// 불변식 검사 헬퍼: 고정 탭은 배열 앞쪽 `[0, pinned_count)`에 연속으로 모이고, 그 뒤는 전부 비고정.
fn assertPinnedPrefix(session: *AppSession) !void {
    const pc = tab_ops.countPinnedTabs(session);
    for (session.tabs.items, 0..) |t, i| {
        if (i < pc) try std.testing.expect(t.pinned) else try std.testing.expect(!t.pinned);
    }
}

/// SG4 테스트 헬퍼 — 재투영(projectRows/recomputeVisibleTabs) 후 그 탭의 카드 row depth를 돌려준다(0=최상위·1=그룹 안).
/// 위치 파생 소속을 단언하는 단일 출처: 넣기=depth 1, 빼기=depth 0. 표시 안 되는 탭(접힘 등)이면 null.
fn sidebarCardDepth(session: *AppSession, tab: *Tab) ?u8 {
    tab_ops.recomputeVisibleTabs(session);
    var idx: ?usize = null;
    for (session.tabs.items, 0..) |t, i| if (t == tab) {
        idx = i;
        break;
    };
    const ti = idx orelse return null;
    for (session.sidebar_rows.items) |row| switch (row) {
        .agent_toggle, .agent, .recovered_sessions_header, .recovered_session => {},
        .card => |c| if (c.tab == ti) return c.depth,
        .group_header => {},
    };
    return null;
}

/// 사이드바 제목 프레임에 📌(U+1F4CC) 핀 글리프 셀이 있는가 — buildSidebarTitleFrame이 pins[]로 tab.pinned를
/// 넘겨 buildSidebarDrawList가 이름줄 **우측 끝**에 그렸을 때만 나타난다(옛 설계의 이름 prefix "📌 "는 폐기). 프레임은
/// 매 frame 재-shape(tab.pinned 라이브)되므로 토글 직후 빌드하면 새 상태가 보인다.
fn frameHasPinGlyph(session: *AppSession) !bool {
    var f = try testBuildSidebarTitleFrame(session);
    defer f.deinit(session.allocator);
    for (f.draw_list.cells) |c| if (c.codepoint == 0x1F4CC) return true;
    return false;
}

test "tab_ops.togglePin: 경계 탭(from==to)도 토글 즉시 📌 라벨이 갱신된다(불변식 유지)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // 실 CoreText shaper 경로
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000); // 사이드바 grid 확보(제목 프레임 빌드 가능)
    // 단일 탭: pin하면 새 pinned_count=1, to=count-1=0=현재 인덱스 → moveTab이 from==to로 early-return(reorder 없음).
    // togglePin이 무조건 rebuildSidebar를 부르고 metal_dirty를 세워 즉시 재렌더되며, 제목 프레임이 tab.pinned를
    // 라이브로 읽어 📌를 붙인다. 토글 전엔 없고, pin 후엔 있고, unpin 후엔 다시 없어야 한다(경계 탭에서도).
    const t0 = session.tabs.items[0];
    try std.testing.expect(!(try frameHasPinGlyph(session)));
    tab_ops.togglePin(session, t0); // 경계 탭(from==to)
    try std.testing.expect(t0.pinned);
    try std.testing.expect(session.metal_dirty); // 재렌더 트리거
    try std.testing.expect(try frameHasPinGlyph(session)); // 📌가 즉시 떠야 한다
    try assertPinnedPrefix(session); // 불변식 성립
    tab_ops.togglePin(session, t0); // unpin도 경계(from==to)
    try std.testing.expect(!t0.pinned);
    try std.testing.expect(!(try frameHasPinGlyph(session))); // 📌가 즉시 사라져야 한다
    try assertPinnedPrefix(session);
}

test "사이드바 이름줄 선두에 활성 마커('*')가 붙는다 — 핀과 위치 분리" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // 실 CoreText shaper 경로
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000); // 사이드바 grid 확보

    // 단일 탭 = 활성 워크스페이스. 이름줄 선두에 동작/활성 마커 '*'(U+002A)가 붙는다(비활성이면 '·' U+00B7).
    var f = try testBuildSidebarTitleFrame(session);
    defer f.deinit(session.allocator);
    // '*' 마커를 찾아 **위치까지** 검증한다(단순 존재 X — 엉뚱한 칸의 '*'나 이름 속 '*'를 통과시키지 않게):
    // ① 활성 슬롯(0)의 이름줄(line_index 0)에 있고, ② 그 줄(row)에서 최좌단(선두) 글리프여야 한다.
    var found = false;
    var mrow: u16 = 0;
    var mcol: u16 = 0;
    for (f.draw_list.cells) |c| if (c.codepoint == '*') {
        found = true;
        mrow = c.row;
        mcol = c.col;
    };
    try std.testing.expect(found); // 활성 탭 선두 '*'
    const base = coretext_frame_builder.sidebar_line_base;
    try std.testing.expectEqual(@as(u16, 0), mrow / base); // 슬롯 0 = 활성 워크스페이스
    try std.testing.expectEqual(@as(u16, 0), (mrow % base) % 4); // line_index 0 = 이름줄
    for (f.draw_list.cells) |c| {
        if (c.row == mrow) try std.testing.expect(c.col >= mcol); // '*'가 이름줄 최좌단(선두)
    }
    // 핀(📌)은 안 붙었으니 핀 글리프는 없어야 한다 — 마커와 핀이 독립임을 고정.
    try std.testing.expect(!(try frameHasPinGlyph(session)));
}

test "applyWorkspaceWindow: 섞인 [P,u,P,u] 복원을 고정-prefix로 stable-partition한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // 실 PTY spawn
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000);

    // 4개 단일-pane 탭, 저장 순서 [P, u, P, u](#685 이전 빌드가 만든 섞인 상태). custom_name으로 정렬 추적.
    const s0 = [_]maru.session.workspace.Surface{.{ .cwd = "/tmp", .cols = 40, .rows = 24 }};
    const s1 = [_]maru.session.workspace.Surface{.{ .cwd = "/tmp", .cols = 40, .rows = 24 }};
    const s2 = [_]maru.session.workspace.Surface{.{ .cwd = "/tmp", .cols = 40, .rows = 24 }};
    const s3 = [_]maru.session.workspace.Surface{.{ .cwd = "/tmp", .cols = 40, .rows = 24 }};
    const p0 = [_]maru.session.workspace.Pane{.{ .surfaces = &s0 }};
    const p1 = [_]maru.session.workspace.Pane{.{ .surfaces = &s1 }};
    const p2 = [_]maru.session.workspace.Pane{.{ .surfaces = &s2 }};
    const p3 = [_]maru.session.workspace.Pane{.{ .surfaces = &s3 }};
    const leaf = [_]maru.session.workspace.TreeNode{.{ .leaf = 0 }};
    const tabs = [_]maru.session.workspace.Tab{
        .{ .custom_name = "P0", .pinned = true, .tree = &leaf, .panes = &p0 },
        .{ .custom_name = "u1", .pinned = false, .tree = &leaf, .panes = &p1 },
        .{ .custom_name = "P2", .pinned = true, .tree = &leaf, .panes = &p2 },
        .{ .custom_name = "u3", .pinned = false, .tree = &leaf, .panes = &p3 },
    };
    // active_tab=3(u3, 비고정 끝) — 재배열 후에도 u3을 가리켜야(stable-partition이 active *Tab 추적).
    try workspace_ops.applyWorkspaceWindow(session, .{ .active_tab = 3, .tabs = &tabs });

    try std.testing.expectEqual(@as(usize, 4), session.tabs.items.len);
    // stable-partition: 고정(P0,P2)이 앞으로(상대 순서 유지), 비고정(u1,u3)이 뒤로(상대 순서 유지) → [P0, P2, u1, u3].
    try std.testing.expectEqualStrings("P0", session.tabs.items[0].custom_name.?);
    try std.testing.expectEqualStrings("P2", session.tabs.items[1].custom_name.?);
    try std.testing.expectEqualStrings("u1", session.tabs.items[2].custom_name.?);
    try std.testing.expectEqualStrings("u3", session.tabs.items[3].custom_name.?);
    try std.testing.expectEqual(@as(usize, 2), tab_ops.countPinnedTabs(session));
    try assertPinnedPrefix(session); // 불변식 성립
    // active_tab은 가리키던 u3(원래 index 3)의 새 위치(index 3)로 보정 — 여기선 그대로지만 추적 경로를 탄다.
    try std.testing.expectEqualStrings("u3", session.tabs.items[session.app_window.active_tab].custom_name.?);
}

test "사이드바 드래그: 비고정 탭을 위로 끌어도 고정 영역을 침범하지 않는다(그룹 경계)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..3) |_| _ = try tab_ops.newTab(session);
    try std.testing.expectEqual(@as(usize, 4), session.tabs.items.len);
    const t0 = session.tabs.items[0];
    const t1 = session.tabs.items[1];
    const t2 = session.tabs.items[2];
    const t3 = session.tabs.items[3];
    t0.pinned = true;
    t1.pinned = true; // [P0, P1, u2, u3], pinned_count=2
    sidebar_ops.rebuildSidebar(session) catch {};

    const x: f64 = @as(f64, @floatFromInt(session.sidebar_width_px)) / 2; // ✕ zone(우측 2칸) 밖 — ✕는 이제 고정 표시라 그 자리는 닫기다

    // 비고정 끝 탭(slot 3=t3)을 잡아 slot 0(고정 영역)으로 드래그 → 비고정 영역 시작(index 2)으로만 안착.
    session.mouse(1, x, sidebar_ops.testSidebarRowCenterY(session, 3), 0, 0); // down on slot 3 → arm
    try std.testing.expect(session.pointerGestureIs(.sidebar_tab));
    try std.testing.expectEqual(@as(usize, 3), session.pointer_gesture_owner.sidebar_tab.index);
    session.mouse(2, x, sidebar_ops.testSidebarRowCenterY(session, 0), 0, 0); // drag toward slot 0
    session.mouse(3, x, sidebar_ops.testSidebarRowCenterY(session, 0), 0, 0); // up

    // 고정(t0,t1)은 [0,1] 불변, t3는 비고정 영역 시작(2)으로만, t2가 3으로 밀림.
    try std.testing.expectEqual(t0, session.tabs.items[0]);
    try std.testing.expectEqual(t1, session.tabs.items[1]);
    try std.testing.expectEqual(t3, session.tabs.items[2]);
    try std.testing.expectEqual(t2, session.tabs.items[3]);
    try assertPinnedPrefix(session);
    try std.testing.expect(!session.pointerGestureIs(.sidebar_tab));
}

test "사이드바 드래그: 고정 탭끼리 재정렬(고정 영역 내 swap, 비고정 불변)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..3) |_| _ = try tab_ops.newTab(session);
    const t0 = session.tabs.items[0];
    const t1 = session.tabs.items[1];
    const t2 = session.tabs.items[2];
    const t3 = session.tabs.items[3];
    t0.pinned = true;
    t1.pinned = true; // [P0, P1, u2, u3], pinned_count=2
    sidebar_ops.rebuildSidebar(session) catch {};

    const x: f64 = @as(f64, @floatFromInt(session.sidebar_width_px)) / 2; // ✕ zone(우측 2칸) 밖 — ✕는 이제 고정 표시라 그 자리는 닫기다

    // 고정 탭 0(t0)을 slot 1(다른 고정)로 드래그 → 고정 영역 내 swap. 비고정 영향 없음.
    session.mouse(1, x, sidebar_ops.testSidebarRowCenterY(session, 0), 0, 0); // down slot 0(고정도 이제 arm)
    try std.testing.expect(session.pointerGestureIs(.sidebar_tab));
    try std.testing.expectEqual(@as(usize, 0), session.pointer_gesture_owner.sidebar_tab.index);
    session.mouse(2, x, sidebar_ops.testSidebarRowCenterY(session, 1), 0, 0); // drag to slot 1
    session.mouse(3, x, sidebar_ops.testSidebarRowCenterY(session, 1), 0, 0); // up

    try std.testing.expectEqual(t1, session.tabs.items[0]); // swap
    try std.testing.expectEqual(t0, session.tabs.items[1]);
    try std.testing.expectEqual(t2, session.tabs.items[2]); // 비고정 불변
    try std.testing.expectEqual(t3, session.tabs.items[3]);
    try assertPinnedPrefix(session);
}

test "rename: commit writes custom_name, cancel keeps old, empty clears, teardown clears target" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // 풀 세션(실 PTY/CoreText) 경로
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    const tab = tab_ops.activeTab(session);
    // 1) 워크스페이스 rename: 시작 → 'h','i' → Enter 확정 → custom_name == "hi", 편집기 닫힘.
    settings_ops.startRename(session, .{ .workspace = tab });
    try std.testing.expect(session.rename != null);
    settings_ops.handleRenameKey(session, .{ .key = .{ .key = .char, .codepoint = 'h' } });
    settings_ops.handleRenameKey(session, .{ .key = .{ .key = .char, .codepoint = 'i' } });
    settings_ops.handleRenameKey(session, .{ .key = .{ .key = .enter } });
    try std.testing.expect(session.rename == null);
    try std.testing.expectEqualStrings("hi", tab.custom_name.?);

    // 2) 취소: 시작 시 현재 이름으로 시드 → 'x' 추가 → Esc → custom_name 그대로("hi").
    settings_ops.startRename(session, .{ .workspace = tab });
    try std.testing.expectEqualStrings("hi", session.rename_input.query.items);
    settings_ops.handleRenameKey(session, .{ .key = .{ .key = .char, .codepoint = 'x' } });
    settings_ops.handleRenameKey(session, .{ .key = .{ .key = .escape } });
    try std.testing.expect(session.rename == null);
    try std.testing.expectEqualStrings("hi", tab.custom_name.?);

    // 3) 빈 텍스트 확정 → custom_name 지워짐(null = 이름 없음).
    settings_ops.startRename(session, .{ .workspace = tab });
    settings_ops.handleRenameKey(session, .{ .key = .{ .key = .backspace } });
    settings_ops.handleRenameKey(session, .{ .key = .{ .key = .backspace } });
    settings_ops.handleRenameKey(session, .{ .key = .{ .key = .enter } });
    try std.testing.expect(tab.custom_name == null);

    // 4) Term rename 중 그 Term을 닫으면 rename이 자동 취소된다(destroyTerm 무효화 — stale 포인터/UAF 방지).
    //    pane에 Term을 하나 더 만들어 닫기가 Term 단위로 끝나게(cascade로 세션 종료 latch를 안 치게) 한다.
    pane_ops.newTermInActivePane(session) catch {};
    term_ops.focusTerm(session, 0); // 첫 Term을 활성으로
    const term0 = pane_ops.activePane(session).activeTerm();
    settings_ops.startRename(session, .{ .term = term0 });
    try std.testing.expect(session.rename != null);
    pane_ops.closeActiveTermOrPane(session); // 활성(term0) 닫힘 → destroyTerm(term0) → rename null
    try std.testing.expect(session.rename == null);
}

// 더블클릭(kind 4) 트리거(PR4): Term 탭·사이드바 슬롯을 더블클릭하면 그 대상 rename이 시작되는지 — 실 init/
// resize/좌표 hit-test라 macOS 게이트. (kind 1=단일 클릭은 전환·포커스만, 단어 선택은 터미널 영역 kind 4로 폴백.)
test "double-click on a Term tab or sidebar slot starts rename" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{}; // 레이아웃 기하만 격리 — window padding(기본 8/4) inset은 gridFromBacking·loader 전용 테스트가 커버
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    // ① Term 탭 더블클릭 → 그 Term rename(custom_name 없어도 좌측 grip 핸들이 항상 있어 탭은 grip 뒤 pb.tabs부터).
    var lr: std.ArrayList(PaneTree.LeafRect) = .empty;
    defer lr.deinit(allocator);
    try tab_ops.activeTabLeafRects(session, allocator, session.termRect(), &lr);
    const pb = pane_ops.paneBar(session, lr.items[0].rect, lr.items[0].leaf).?;
    const term0 = pane_ops.activePane(session).activeTerm();
    session.mouse(4, @floatFromInt(pb.tabs.x + 4), @floatFromInt(pb.full.y + 1), 0, 0);
    try std.testing.expect(term_ops.renamingTerm(session, term0));
    settings_ops.closeRename(session);

    // ② 사이드바 슬롯 더블클릭 → 그 워크스페이스 rename.
    const tab = tab_ops.activeTab(session);
    const sx = @as(f64, @floatFromInt(session.sidebar_width_px)) * 0.5;
    const sy = sidebar_ops.testSidebarRowCenterY(session, 0); // 슬롯 0 중앙(상단 헤더 아래)
    session.mouse(4, sx, sy, 0, 0);
    try std.testing.expect(workspace_ops.renamingWorkspace(session, tab));
    settings_ops.closeRename(session);
}

// 우클릭 컨텍스트 메뉴(PR5): Term 탭 우클릭 → 메뉴 열림 + 대상 세팅, 항목(Rename) 클릭 → 메뉴 닫힘 + 그 대상
// rename 시작. 터미널 본문 우클릭 → 메뉴 안 열림(대상 없음). 실 좌표 hit-test라 macOS 게이트.
test "right-click opens context menu on a rename target; clicking Rename starts rename" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{}; // 레이아웃 기하만 격리 — window padding(기본 8/4) inset은 gridFromBacking·loader 전용 테스트가 커버
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    var lr: std.ArrayList(PaneTree.LeafRect) = .empty;
    defer lr.deinit(allocator);
    try tab_ops.activeTabLeafRects(session, allocator, session.termRect(), &lr);
    const pb = pane_ops.paneBar(session, lr.items[0].rect, lr.items[0].leaf).?; // 탭은 grip 뒤 pb.tabs부터
    const term0 = pane_ops.activePane(session).activeTerm();

    // ① Term 탭 우클릭(button==2) → 메뉴 열림 + 대상 = term0(아직 rename 아님 — 메뉴만).
    session.mouse(1, @floatFromInt(pb.tabs.x + 4), @floatFromInt(pb.full.y + 1), 2, 0);
    try std.testing.expect(session.chrome_host.context_menu.open);
    try std.testing.expect(session.rename == null);

    // ② 메뉴 항목(Rename, 행 0)을 좌클릭 → 메뉴 닫힘 + term0 rename 시작. anchor = 우클릭 px(작아서 clamp 없음).
    const mx: f64 = @floatFromInt(session.chrome_host.context_menu.anchor_x + 1);
    const my: f64 = @floatFromInt(session.chrome_host.context_menu.anchor_y + 1);
    session.mouse(1, mx, my, 0, 0);
    try std.testing.expect(!session.chrome_host.context_menu.open);
    try std.testing.expect(term_ops.renamingTerm(session, term0));
    settings_ops.closeRename(session);

    // ③ 터미널 본문(바 아래) 우클릭 → 대상 없음 → 메뉴 안 열림.
    session.mouse(1, @floatFromInt(pb.full.x + 4), @floatFromInt(pb.full.y + pb.full.h + 5), 2, 0);
    try std.testing.expect(!session.chrome_host.context_menu.open);
}

// rename caret 깜빡임(blink_visible로 '|'↔공백, 폭 고정)과 IME 후보창 caret rect(편집기 위치 추적)를 고정한다.
test "rename caret blinks (width-stable) and IME caret rect tracks the editor, not the terminal cursor" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{}; // 레이아웃 기하만 격리 — window padding(기본 8/4) inset은 gridFromBacking·loader 전용 테스트가 커버
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    const term0 = pane_ops.activePane(session).activeTerm();
    settings_ops.startRename(session, .{ .term = term0 });
    settings_ops.handleRenameKey(session, .{ .key = .{ .key = .char, .codepoint = 'h' } });
    settings_ops.handleRenameKey(session, .{ .key = .{ .key = .char, .codepoint = 'i' } });

    // 깜빡임: blink_visible면 '|', 아니면 공백으로 끝난다 — 두 표시폭이 같아야(폭 흔들림 없음).
    session.blink_visible = true;
    const on = try settings_ops.renameEditText(session, allocator);
    defer allocator.free(on);
    session.blink_visible = false;
    const off = try settings_ops.renameEditText(session, allocator);
    defer allocator.free(off);
    try std.testing.expect(std.mem.endsWith(u8, on, "hi|"));
    try std.testing.expect(std.mem.endsWith(u8, off, "hi ")); // 공백 caret
    try std.testing.expectEqual(on.len, off.len); // 폭 고정

    // IME caret rect: rename 활성이면 imeCursorRect가 편집기 caret(탭 바 영역, 화면 상단)에서 난다 — 터미널 본문
    // (바 아래)이 아니다. renameCaretRect와 일치.
    var lr: std.ArrayList(PaneTree.LeafRect) = .empty;
    defer lr.deinit(allocator);
    try tab_ops.activeTabLeafRects(session, allocator, session.termRect(), &lr);
    const bar = pane_ops.paneBarRect(session, lr.items[0].rect).?;
    const term_body = pane_ops.paneTermRect(session, lr.items[0].rect);
    const cr = settings_ops.renameCaretRect(session) orelse return error.NoCaret;
    try std.testing.expectEqual(@as(u32, session.cell_width_px), cr.w);
    try std.testing.expect(@as(u32, @intCast(cr.y)) >= bar.y and @as(u32, @intCast(cr.y)) < term_body.y); // 탭 바 안(본문 위)
    const ime = session.imeCursorRect();
    try std.testing.expectEqual(@as(f64, @floatFromInt(cr.y)), ime.y); // imeCursorRect가 rename caret을 씀
    settings_ops.closeRename(session);
}

// F1 회귀 가드(코드리뷰 high CONFIRMED): 워크스페이스 리네임 중 상태줄(running 파형·idle ✓)이 붙어 카드가 2줄이 되면
// 렌더러(maru_metal_renderer.m)가 2줄 블록을 슬롯 세로 중앙 정렬해 이름줄(line 0)이 위로 (ch/2) 밀린다 —
// renameCaretRect도 같은 line_count로 caret y를 올려야 IME 후보창이 이름 caret 아래(파형 상태줄과 겹치지 않게)에 온다.
// non-agent 워크스페이스는 상태줄이 없어 1줄이라 슬롯 중앙 그대로. buildSidebarDrawList의 line_count 인코딩(빈 보조줄
// skip)과 caret 정렬을 묶는다 — 상태줄이 이름줄 아래에 늘 붙던 회귀(커밋 8c4c969)에서 캐럿만 1줄 기준으로 남던 것을 고정.
// 겸해서 caret y가 view 절대 좌표 규약(사이드바 header 더하고 scroll 뺌 — Swift firstRect가 origin 보정 없이 변환만)을
// 지키는지도 고정한다(케이스 3: scroll offset 반영). 예전엔 idx*slot_h만 써서 header만큼 위·scroll만큼 아래로 어긋났다.
test "F1: workspace rename caret y follows card line count + sidebar header/scroll offset" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    const tab = session.tabs.items[0];
    const term = tab.activeTerm();
    const ch: u32 = session.cell_height_px;
    const header: u32 = session.sidebar_header_height_px;
    try std.testing.expect(header > 0); // 헤더(검색바·아이콘)가 있다는 전제 — caret y가 그만큼 내려가야 렌더러와 정합

    // **기대값을 렌더러와 같은 식으로 만든다.** rename 중에는 보조줄(브랜치·경로)이 숨으므로 **그리는 줄 수**가
    // 투영된 카드 줄 수보다 적을 수 있고, 그때 블록중앙 오프셋은 카드 여백과 같지 않다. 옛 기대식
    // (`card_pad_v + content_pad_v`)은 둘이 우연히 같던 스모크 세션(관측 cwd가 비어 카드가 1줄)에서만 맞았다 —
    // 커널 cwd 폴백이 들어오며 그 카드가 3줄이 되자 어긋났고, 어긋난 쪽은 **기대식**이다(렌더는 아래와 같은
    // `fillSidebarGlyphPyTop` 계산을 쓴다). 실제 사용자 카드는 예전부터 3줄이었으므로 제품 동작은 안 바뀐다.
    const expectedCaretY = struct {
        fn f(s: *AppSession, drawn_lines: u32, cell_h: u32) i64 {
            const m = sidebar_ops.sidebarMetrics(s);
            const rows = sidebar_ops.sidebarRenderRows(s);
            const top = chrome.components.sidebar.rowTop(rows, 0, s.sidebar_header_height_px, m, s.sidebar_scroll_offset_px);
            const row_h = chrome.components.sidebar.rowHeight(rows[0], m);
            const off: i64 = @intCast((row_h -| sidebar_ops.sidebarBlockHeight(drawn_lines, cell_h)) / 2);
            return @max(top + off, @as(i64, s.sidebar_header_height_px));
        }
    }.f;

    // 1) non-agent 워크스페이스(scroll 0): rename 중 그리는 줄은 이름줄 하나뿐이다.
    term.agent_kind = .none;
    sidebar_ops.rebuildSidebar(session) catch {}; // Row.lines(줄 수)는 투영 때 굳는다 — 상태를 바꿨으면 다시 투영해야 정합
    settings_ops.startRename(session, .{ .workspace = tab });
    const cr1 = settings_ops.renameCaretRect(session) orelse return error.NoCaret;
    try std.testing.expectEqual(@as(i32, @intCast(expectedCaretY(session, 1, ch))), cr1.y);
    settings_ops.closeRename(session);

    // 2) 에이전트가 있으면 **rename 중에도 상태줄이 그려지므로**(편집 화면에서 파형을 보여달라는 사용자 요청)
    // 카드는 2줄 블록이고 이름줄은 그만큼 위로 올라간다. caret은 렌더와 **같은 줄 수**를 봐야 IME 후보창이
    // 상태줄을 덮지 않는다(code-review max: 이 계산을 1로 고정했다가 반 줄 어긋났다).
    term.agent_kind = .claude;
    term.agent_state = .idle;
    sidebar_ops.rebuildSidebar(session) catch {};
    settings_ops.startRename(session, .{ .workspace = tab });
    const cr2 = settings_ops.renameCaretRect(session) orelse return error.NoCaret;
    const m2 = sidebar_ops.sidebarMetrics(session);
    const row_h2 = chrome.components.sidebar.rowHeight(session.sidebar_rows.items[0], m2);
    const off2 = (row_h2 -| sidebar_ops.sidebarBlockHeight(2, ch)) / 2;
    try std.testing.expectEqual(@as(i32, @intCast(header + m2.content_pad_v + off2)), cr2.y);
    settings_ops.closeRename(session);
    try std.testing.expect(cr2.y < cr1.y); // 상태줄이 붙으면 이름줄(=caret)이 위로 올라간다

    // 3) scroll offset 반영: 콘텐츠가 offset만큼 위로 밀리면 caret도 따라 올라간다(slotTop이 scroll을 뺌).
    // 작은 offset(블록중앙보다 작아 헤더 clamp 전)이라 caret이 정확히 그만큼 올라가야 한다.
    term.agent_kind = .none;
    sidebar_ops.rebuildSidebar(session) catch {};
    const before_scroll = expectedCaretY(session, 1, ch);
    const offset: u32 = @min(ch / 2, sidebar_ops.sidebarMetrics(session).card_pad_v); // 헤더 clamp(@max header)에 안 걸리게
    session.sidebar_scroll_offset_px = offset;
    settings_ops.startRename(session, .{ .workspace = tab });
    const cr3 = settings_ops.renameCaretRect(session) orelse return error.NoCaret;
    try std.testing.expectEqual(@as(i32, @intCast(expectedCaretY(session, 1, ch))), cr3.y);
    try std.testing.expectEqual(@as(i64, before_scroll - @as(i64, offset)), @as(i64, cr3.y)); // 스크롤한 만큼 정확히 올라간다
    settings_ops.closeRename(session);
    session.sidebar_scroll_offset_px = 0; // 복원
}

// 코드리뷰 수정 고정: (#7) 포커스 상실 시 rename 확정, (#2) 터미널 본문 우클릭은 consume 안 하고 mouse-reporting으로
// 흘림(트래킹 앱 보존), (#8) 사이드바 ✕(close) zone은 rename 대상 아님.
test "review fixes: focus-loss commits rename, body right-click reports, close-zone excluded" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{}; // 레이아웃 기하만 격리 — window padding(기본 8/4) inset은 gridFromBacking·loader 전용 테스트가 커버
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);
    const term0 = pane_ops.activePane(session).activeTerm();

    // (#7) rename 중 setFocused(false) → 확정(custom_name 기록, 편집기 닫힘).
    settings_ops.startRename(session, .{ .term = term0 });
    settings_ops.handleRenameKey(session, .{ .key = .{ .key = .char, .codepoint = 'z' } });
    session.setFocused(false);
    try std.testing.expect(session.rename == null);
    try std.testing.expectEqualStrings("z", term0.surface.custom_name.?);

    // (#8) 사이드바 슬롯 ✕(close) 칸은 renameTargetAt가 null(닫기 자리에서 rename 방지), 좌측은 워크스페이스.
    // 좌표는 **그려진 ✕ 칸**에서 얻는다 — 폭 역산(`w - cw`)은 gutter만큼 어긋나 실제 ✕가 아닌 자리를 짚는다.
    const slot_y = sidebar_ops.testSidebarRowCenterY(session, 0); // 슬롯 0 중앙(상단 헤더 아래)
    const rename_close_range = sidebar_ops.sidebarColumns(session).?.closeXRange(session.cell_width_px);
    const close_x = rename_close_range.start + (rename_close_range.end - rename_close_range.start) / 2;
    try std.testing.expect(settings_ops.renameTargetAt(session, close_x, slot_y) == null);
    try std.testing.expect(settings_ops.renameTargetAt(session, @floatFromInt(session.cell_width_px), slot_y) != null); // 좌측=워크스페이스

    // (#2) mouse_tracking 켠 상태에서 터미널 본문 우클릭(button==2) → 메뉴 안 열림 + reporting 경로 도달
    //      (drag_autoscroll/selecting 리셋이 그 증거). 가드가 본문을 consume하면(회귀) 리셋 안 됨.
    var lr: std.ArrayList(PaneTree.LeafRect) = .empty;
    defer lr.deinit(allocator);
    try tab_ops.activeTabLeafRects(session, allocator, session.termRect(), &lr);
    const body = pane_ops.paneTermRect(session, lr.items[0].rect);
    term_ops.activeSurface(session).core.mouse_tracking = .normal;
    session.drag_autoscroll = 1;
    session.mouse_drag_selecting = true;
    session.mouse(1, @floatFromInt(body.x + 10), @floatFromInt(body.y + 10), 2, 0); // 본문 우클릭
    try std.testing.expect(!session.chrome_host.context_menu.open); // 메뉴 안 열림(본문엔 대상 없음)
    try std.testing.expectEqual(@as(i8, 0), session.drag_autoscroll); // reporting 경로 도달(=consume 안 함)
    try std.testing.expect(!session.mouse_drag_selecting);
}

test "synchronized output(2026) hold: ESU 누락 시 sync timeout을 넘으면 강제 투영(freeze 복구)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // 실제 CoreText frame builder 경로
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // controlled 출력이 멎을 때까지 tick한다 — 이후 output_events=0이라 우리가 세팅한 metal_dirty가 유지된다.
    var i: usize = 0;
    while (i < 150) : (i += 1) _ = try session.tick();

    // BSU 상황 모사: 활성 surface가 sync로 진입하고 누적 출력(metal_dirty)이 한 프레임 대기 중.
    term_ops.activeSurface(session).core.sync_output = true;
    session.metal_dirty = true;
    session.sync_hold_ticks = 0;
    const timeout = session.syncTimeoutTicks();
    // timeout 직전까지는 sync가 투영을 막아 metal_dirty가 false로 안 풀리고 누적된다(투영 판정엔
    // metal_dirty를 본다 — generation은 blink 토글로 따로 올라 투영 여부의 지표가 못 된다).
    var k: usize = 0;
    while (k + 1 < @as(usize, @intCast(timeout))) : (k += 1) _ = try session.tick();
    try std.testing.expect(session.metal_dirty); // 아직 hold(투영 skip)
    try std.testing.expectEqual(timeout - 1, session.sync_hold_ticks);

    // timeout 도달 tick에서 sync_active여도 강제 투영 → metal_dirty가 풀린다(ESU 없이 freeze 해제).
    _ = try session.tick();
    try std.testing.expect(!session.metal_dirty);

    // ESU 모사: sync가 꺼지면 다음 tick에 hold 카운터가 0으로 리셋된다.
    term_ops.activeSurface(session).core.sync_output = false;
    _ = try session.tick();
    try std.testing.expectEqual(@as(u32, 0), session.sync_hold_ticks);
}

test "shouldProjectFrame: sync(2026) hold는 라이브 투영만 막고 스크롤 리페인트는 막지 않는다" {
    const timeout: u32 = ticksForMsAtRate(sync_timeout_ms, config_mod.theme.render_frame_rate_default);
    // 라이브(스크롤 안 함, view_offset==직전 렌더, esu_advanced=false, force_reproject=false): sync hold 중엔 metal_dirty여도 투영 보류.
    try std.testing.expect(!shouldProjectFrame(true, true, 0, timeout, 0, 0, false, false));
    // hold가 timeout 도달 → ESU 없이 강제 투영(freeze 복구) — 기존 동작 보존.
    try std.testing.expect(shouldProjectFrame(true, true, timeout, timeout, 0, 0, false, false));
    // ── 버그 재현: 스크롤백을 위로 본 채(view_offset 3 ≠ 직전 렌더 0) sync hold면, 예전 게이트
    //    (metal_dirty and !(sync and hold<timeout))는 false라 스크롤 리페인트를 막아 viewport가 stale로 멈췄다.
    //    이제 스크롤 변화는 라이브 출력 배칭과 무관하게 투영한다(이 버그의 수정점). ──
    try std.testing.expect(shouldProjectFrame(true, true, 0, timeout, 3, 0, false, false));
    // view_offset 변화는 metal_dirty 누락(스크롤 reader 위임이 build 락-읽기보다 늦는 race)에도 투영을 강제한다.
    try std.testing.expect(shouldProjectFrame(false, false, 0, timeout, 3, 0, false, false));
    // 변화 없음 + dirty 없음 → 투영 안 함(idle tick 비용 절감 보존).
    try std.testing.expect(!shouldProjectFrame(false, false, 0, timeout, 5, 5, false, false));
    // sync 아님 + dirty → 평소대로 투영.
    try std.testing.expect(shouldProjectFrame(true, false, 0, timeout, 0, 0, false, false));
    // ── [B] ESU edge: sync hold 중(sync_active, hold<timeout, 스크롤 없음)이라도 직전 투영 이후 리더가 ESU를
    //    처리했으면(esu_advanced=true) 완성 프레임을 flush한다 — 폴링이 다음 BSU만 관측해 완성 프레임을 놓치던 MISS 수정. ──
    //    **SSH 트레이드오프(docs/io-render-present.md §11.6 esu_edge)**: 이 case에서 sync_active=true는 "리더가 이미
    //    **다음** 프레임 BSU를 시작"했다는 뜻일 수 있다(연속 조각 프레임). 그러면 flush가 그 진행 중 next 프레임을
    //    half-drawn으로 투영한다 — 로컬은 곧 다음 ESU가 교정하지만 bubbletea diff는 그 셀을 다시 안 보내 영구 stale.
    //    `.sync` 로거의 `active=1 gproj=1`(esu_edge)로 관측되는 maru ssh desync 유력 원인.
    try std.testing.expect(shouldProjectFrame(true, true, 0, timeout, 0, 0, true, false));
    // esu_advanced=false면 여전히 hold가 막는다(진행 중 프레임 tearing 방지 — 정당한 막힘 보존).
    try std.testing.expect(!shouldProjectFrame(true, true, 0, timeout, 0, 0, false, false));
    // esu advanced면 metal_dirty가 누락돼도(reader race) 투영을 강제한다(view_offset 안전판과 동형).
    try std.testing.expect(shouldProjectFrame(false, true, 0, timeout, 0, 0, true, false));
    // ── [A: code-review 0] force_reproject: sync hold 중(hold<timeout)이라도 사이드바 전용 place가 atlas를 repack한 뒤
    //    GPU 정합을 위해 강제 full 투영한다 — metal_dirty 없이도(reader race) 투영, sync hold 우회. ──
    try std.testing.expect(shouldProjectFrame(false, true, 0, timeout, 0, 0, false, true));
    // force_reproject=false면 위와 동일 상황에서 hold가 막는다(대조).
    try std.testing.expect(!shouldProjectFrame(false, true, 0, timeout, 0, 0, false, false));
}

test "synchronized output(2026) hold가 스크롤백 탐색 리페인트는 막지 않는다(rapid 스크롤 stale 수정)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // 실제 CoreText frame builder 경로(tick 투영)
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // controlled 출력이 멎을 때까지 tick한다 — 이후 output_events=0이라 우리가 세팅한 상태(view_offset·sync)가 유지된다.
    var i: usize = 0;
    while (i < 150) : (i += 1) _ = try session.tick();

    // 사용자가 스크롤백을 위로 본 상태(view_offset>0)에서 직전 렌더보다 더 스크롤했고(2≠1), 활성 surface가
    // 동기 출력(2026) hold에 들어간 상황을 모사한다(scroll-lock으로 라이브 출력 중에도 스크롤 위치 유지).
    term_ops.activeSurface(session).core.view_offset = 2;
    session.last_rendered_view_offset = 1;
    term_ops.activeSurface(session).core.sync_output = true;
    session.sync_hold_ticks = 0;
    session.metal_dirty = true;

    // 예전 게이트는 sync hold가 metal_dirty 투영을 막아 스크롤이 stale로 멈췄다. 이제 view_offset 변화는 sync와
    // 무관하게 투영한다 — tick 한 번에 metal_dirty가 풀리고(투영됨) 방금 본 위치를 last_rendered_view_offset에 기록한다.
    _ = try session.tick();
    try std.testing.expect(!session.metal_dirty); // 투영됨(예전엔 sync hold로 막혀 metal_dirty가 true로 남았다)
    try std.testing.expectEqual(@as(usize, 2), session.last_rendered_view_offset);
}

// 탭 전환 sync-게이트 회귀 테스트 공용 스캐폴딩: controlled_smoke 세션을 만들어 tab0을 정착시키고(출력 소진),
// 둘째 탭을 만들어(→tab1 활성) 정착시킨 뒤 세션을 돌려준다(호출자가 deinit+destroy). tab0 surface는
// session.tabs.items[0].panes.items[0].terms.items[0].surface로 얻는다. [code-review 5] 네 테스트의 중복 제거.
fn setupTwoTabsSettled(allocator: std.mem.Allocator) !*AppSession {
    const session = try allocator.create(AppSession);
    errdefer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    errdefer session.deinit();
    var i: usize = 0;
    while (i < 150) : (i += 1) _ = try session.tick(); // tab0 정착(controlled 출력 소진 → output_events=0)
    _ = try tab_ops.newTab(session); // 둘째 탭 → tab1 활성(createTab이 새 탭을 활성으로)
    std.debug.assert(session.tabs.items.len == 2);
    i = 0;
    while (i < 150) : (i += 1) _ = try session.tick(); // tab1 정착
    return session;
}

// ── 회귀: 백그라운드 Term의 출력이 활성 커서 blink 위상을 굶기지 않는다 ─────────────────────────────
// tick의 blink 게이트가 `drain_summary.output_events`(**모든** 탭/pane/Term의 합)를 보던 탓에, 백그라운드에서
// 계속 출력하는 Term이 하나라도 있으면(에이전트·로그 tail·dev 서버) 활성 커서가 매 tick resetCursorBlink로
// 위상 0에 묶여 **영영 깜빡이지 않았다**. 사용자 제보 "커서가 안 깜빡인다"의 실제 원인이고, 스피너가 같은 이유로
// 출력 게이트 밖으로 나갔던 §10.5 primary와 같은 계열이다. 게이트를 활성 surface 출력으로 좁혀 고쳤다.
//
// 기존 blink 단위 테스트가 못 잡은 이유: 전부 `updateCursorBlink`를 **직접** 불러 tick의 게이트를 건너뛴다.
// 그래서 이 테스트는 반드시 `session.tick()`을 돈다.
test "cursor blink: 백그라운드 Term이 계속 출력해도 활성 커서 위상은 진행한다(전역 output 게이트 회귀)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // 실제 PTY + CoreText tick 경로
    const allocator = std.testing.allocator;
    const session = try setupTwoTabsSettled(allocator); // tab1 활성, 둘 다 출력 소진 상태
    defer {
        session.deinit();
        allocator.destroy(session);
    }
    // 실 config 파일 값에 의존하지 않게 고정(다른 머신에서 cursor.blink=false면 무의미해진다).
    session.appearance.cursor.blink = true;
    session.appearance.cursor.blink_fade_ms = 0; // 하드 토글 — 위상 판정을 blink_visible로 단순화

    const bg_id = session.tabs.items[0].panes.items[0].terms.items[0].surface.id; // tab0 = 백그라운드
    const active_id = term_ops.activeSurface(session).id;
    try std.testing.expect(bg_id != active_id);

    session.blink_visible = true;
    session.blink_phase_ns = 0;
    // 매 tick 백그라운드에 개행 없는 paste를 밀어 넣어 **그쪽 PTY만** 계속 에코(출력)하게 한다. 개행이 없어야
    // 자식이 `read`에서 살아남아 reap/UAF가 없다([[controlled-smoke-child-exit-reap-uaf]] 규율).
    // 위상은 wall-clock 기준이라 tick 수로는 안 넘어간다 — baseline을 매번 한 반주기 과거로 밀어, 백그라운드 출력이
    // 흐르는 **동안에도** 위상이 진행되는지(=리셋에 굶지 않는지) 본다. 수정 전이면 매 tick resetCursorBlink가
    // baseline을 0으로 되돌리고 blink_visible을 true로 고정해 아래 토글이 한 번도 안 일어난다.
    var toggles: u32 = 0;
    var last = session.blink_visible;
    var i: u32 = 0;
    while (i < 3) : (i += 1) {
        session.pasteTextTo(bg_id, "x", false);
        testAdvanceBlinkHalves(session, 1);
        _ = try session.tick();
        if (session.blink_visible != last) {
            toggles += 1;
            last = session.blink_visible;
        }
    }
    // ★ 활성 커서 위상은 백그라운드 출력과 무관하게 세 번 다 진행했어야 한다.
    try std.testing.expectEqual(@as(u32, 3), toggles);
}

// ── 회귀: 탭 전환 시 mid-sync·완성 프레임 없는(esu==0) surface는 미완성 프레임을 안 그리고 hold한다 ──────
// 대상 탭이 2026 sync 중이고 ESU로 프레임을 완성한 적이 없으면(sync_esu_count==0), 전환 tick은 공유 buffer의
// 직전 완성 프레임을 유지한 채 hold한다(미완성/빈 프레임 안 그림 = 화면 소멸 방지). 완성 프레임이 없으니
// esu-edge로는 못 풀고, sync 게이트를 우회하는 스크롤(view_offset 변화)이나 1초 timeout으로 복구된다.
// 전환 시 baseline 3개를 새 surface 기준으로 리셋하는 수정에서 esu==0이면 이 hold는 불변이라 수정 전후 모두 통과.
test "탭 전환: mid-sync·완성없음(esu==0) surface는 미완성 프레임을 안 그리고 hold하며 스크롤/timeout으로 복구된다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // 실제 CoreText tick 투영 경로
    const allocator = std.testing.allocator;
    const session = try setupTwoTabsSettled(allocator);
    defer {
        session.deinit();
        allocator.destroy(session);
    }

    // tab0을 "2026 sync 진입 + ESU 완성 이력 없음(esu==0)" 상태로: BSU를 열었지만 아직 ESU로 완성하지 않은 순간.
    const tab0_surface = session.tabs.items[0].panes.items[0].terms.items[0].surface;
    tab0_surface.core.sync_output = true;
    tab0_surface.core.sync_esu_count = 0;
    tab0_surface.core.view_offset = 0;
    session.sync_hold_ticks = 0;

    try std.testing.expect(tab_ops.switchTab(session, 0));
    try std.testing.expect(session.metal_dirty); // 전환이 재그림을 요청함

    // ★ 전환 후 첫 tick: 새 surface(tab0) 현재 esu=0으로 baseline 리셋 → esu_advanced=(0!=0)=false → sync_blocks=true
    //   → will_project=false. 완성 프레임이 없어 hold(직전 완성 프레임 유지, 미완성 안 그림). metal_dirty 유지.
    _ = try session.tick();
    try std.testing.expect(session.metal_dirty); // ★ held(미완성 프레임 안 그림)

    // timeout 전까지 계속 hold — 완성 프레임이 없어 esu-edge로 자가복구가 안 됨(스크롤 전까진 유지).
    var k: usize = 0;
    while (k < 5) : (k += 1) {
        _ = try session.tick();
        try std.testing.expect(session.metal_dirty);
    }

    // 스크롤(view_offset 변경) → view_scrolled가 sync_blocks를 우회 → 투영 → metal_dirty 해제.
    tab0_surface.core.view_offset = 1; // 스크롤백을 한 줄 위로 본 것 모사
    _ = try session.tick();
    try std.testing.expect(!session.metal_dirty); // ★ 스크롤로 복구(전환은 못 풀던 것을 스크롤이 푼다)
    try std.testing.expectEqual(@as(usize, 1), session.last_rendered_view_offset);
}

// ── 회귀: 탭 전환 시 mid-sync(esu>0) surface의 진행 중 프레임을 조기 투영하지 않는다(hold 후 ESU에 투영) ──
// 실제 Claude류 TUI는 완성 프레임 이력이 있어 sync_esu_count>0. 탭 전환의 resizeTabPanes→SIGWINCH가 전체
// clear+repaint(2026 블록)를 유발하는데, "clear됐고 리페인트 전"인 순간에 전환해도 baseline을 새 surface 현재
// esu로 리셋(=core_snap.esu)해 esu_advanced=(N!=N)=false → 전환 tick은 hold(진행 중 빈 프레임 안 그림 = 소멸 방지).
// 새 surface가 ESU로 완성하는 순간 비로소 투영. ⚠️ 예전(=0)엔 esu_advanced=(N!=0)=true로 위조돼 전환 tick에 빈
// 프레임을 강제 투영했다(소멸 버그) — 그 회귀가 재발하면 아래 "전환 tick=hold" 단언이 깨진다.
test "탭 전환: mid-sync(esu>0) surface의 진행 중 프레임을 조기 투영하지 않는다(hold 후 ESU 완성 시 투영)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try setupTwoTabsSettled(allocator);
    defer {
        session.deinit();
        allocator.destroy(session);
    }

    // tab0 = SIGWINCH 후 2026 블록 안에서 화면을 지우고 리페인트 전: ?2J로 grid 비우고 sync 진입, 완성 이력 있음(esu=5).
    const tab0_surface = session.tabs.items[0].panes.items[0].terms.items[0].surface;
    tab0_surface.core.write("\x1b[2J\x1b[H") catch {};
    tab0_surface.core.sync_output = true;
    tab0_surface.core.sync_esu_count = 5; // 실제 Claude 조건: 이미 완성 프레임 이력 있음(핵심 — esu>0)
    session.sync_hold_ticks = 0;

    try std.testing.expect(tab_ops.switchTab(session, 0));
    try std.testing.expect(session.metal_dirty);

    // ★ 전환 후 첫 tick: baseline이 tab0 현재 esu(5)라 esu_advanced=(5!=5)=false → sync_blocks=true → hold.
    //   (예전 =0이면 강제 투영돼 metal_dirty=false = 소멸. 그 회귀를 이 단언이 잡는다.)
    _ = try session.tick();
    try std.testing.expect(session.metal_dirty); // ★ hold — 미완성 프레임을 안 그림

    var k: usize = 0;
    while (k < 5) : (k += 1) {
        _ = try session.tick();
        try std.testing.expect(session.metal_dirty);
    }

    // Claude가 리페인트를 끝내고 ESU로 프레임 완성(sync 해제 + esu 증가) → 이때 비로소 완성 프레임 투영.
    tab0_surface.core.write("repainted content after the resize redraw") catch {};
    tab0_surface.core.sync_output = false;
    tab0_surface.core.sync_esu_count = 6;
    _ = try session.tick();
    try std.testing.expect(!session.metal_dirty); // ★ 완성 프레임이 투영됨 — 소멸 없이 새 탭이 뜬다
}

// ── 회귀: 스크롤된 이전 탭이 있어도 mid-sync surface로 전환 시 view_scrolled로 오투영하지 않는다 [code-review 0/1] ──
// last_rendered_view_offset은 단일 필드다. 이전 탭을 스크롤백 위로 본 채(offset>0) mid-sync·완성 이력 있는(esu>0)
// 탭으로 전환하면, view_offset 리셋이 없으면 view_scrolled=(0 != 이전offset)=true가 sync_blocks를 우회해 진행 중
// (비워진) 프레임을 강제 투영 = 소멸. 수정은 전환 시 last_rendered_view_offset도 새 surface view_offset(0)으로
// 리셋해 view_scrolled=false로 만든다. 이 vector만 격리하려 esu·hold는 안 걸리게(esu_advanced=false·hold=0) 세팅.
test "탭 전환: 스크롤된 이전 탭이 있어도 mid-sync surface로 전환 시 view_scrolled로 오투영하지 않는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try setupTwoTabsSettled(allocator);
    defer {
        session.deinit();
        allocator.destroy(session);
    }

    // 이전 활성 탭이 스크롤백 위로 본 채 렌더된 상태 모사(마지막 렌더 offset이 0이 아님).
    session.last_rendered_view_offset = 5;

    // tab0 = mid-sync(esu>0), 현재 뷰포트는 라이브(view_offset=0).
    const tab0_surface = session.tabs.items[0].panes.items[0].terms.items[0].surface;
    tab0_surface.core.write("\x1b[2J\x1b[H") catch {};
    tab0_surface.core.sync_output = true;
    tab0_surface.core.sync_esu_count = 5; // esu vector 차단(esu_advanced=false가 되게)
    tab0_surface.core.view_offset = 0;
    session.sync_hold_ticks = 0; // hold vector 차단

    try std.testing.expect(tab_ops.switchTab(session, 0));
    _ = try session.tick();
    // 수정: last_rendered_view_offset을 tab0 view_offset(0)으로 리셋 → view_scrolled=(0!=0)=false → hold.
    // (리셋 없으면 view_scrolled=(0!=5)=true → 진행 중 프레임 강제 투영 = 소멸.)
    try std.testing.expect(session.metal_dirty); // ★ hold — 스크롤된 이전 탭 때문에 오투영하지 않음
}

// ── 회귀: 이월된 sync_hold_ticks가 timeout을 넘겨도 mid-sync surface로 전환 시 오투영하지 않는다 [code-review 2] ──
// sync_hold_ticks는 단일 필드다. 이전 탭이 mid-sync로 멈춰 hold가 timeout(≈60틱/1초)을 넘긴 채 전환하면, hold
// 리셋이 없으면 새 탭이 그 만료 예산을 이월받아 sync_blocks=false(hold>=timeout)로 진행 중 프레임을 강제 투영
// = 소멸. 수정은 전환 시 sync_hold_ticks=0으로 리셋해 새 surface freeze 예산을 0부터 시작한다.
test "탭 전환: 이월된 sync_hold_ticks가 timeout을 넘겨도 mid-sync surface로 전환 시 오투영하지 않는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try setupTwoTabsSettled(allocator);
    defer {
        session.deinit();
        allocator.destroy(session);
    }

    const tab0_surface = session.tabs.items[0].panes.items[0].terms.items[0].surface;
    tab0_surface.core.write("\x1b[2J\x1b[H") catch {};
    tab0_surface.core.sync_output = true;
    tab0_surface.core.sync_esu_count = 5; // esu vector 차단
    tab0_surface.core.view_offset = 0;

    // 이전 탭이 mid-sync로 멈춰 hold가 timeout을 넘긴 상황 모사 — 전환이 이 만료 예산을 이월하면 안 된다.
    session.sync_hold_ticks = session.syncTimeoutTicks() + 5;

    try std.testing.expect(tab_ops.switchTab(session, 0));
    _ = try session.tick();
    // 수정: 전환 시 sync_hold_ticks=0 리셋 → hold=1 < timeout → sync_blocks=true → hold.
    // (리셋 없으면 이월된 hold>=timeout이라 sync_blocks=false → 진행 중 프레임 강제 투영 = 소멸.)
    try std.testing.expect(session.metal_dirty); // ★ hold — 이월된 hold 예산으로 오투영하지 않음
}

test "chrome_minimal session suppresses the pane tab bar and the sidebar" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // refreshCellMetrics가 CoreText 메트릭 경로
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
        .chrome_minimal = 1,
    });
    defer session.deinit();

    // minimal: 사이드바 폭 0(refreshCellMetrics 게이트), 탭 바 높이 0(paneBarHeightPx 게이트) →
    // paneBarRect가 null, paneTermRect는 바를 빼지 않는다. window padding은 0으로 격리해 바 기하만 본다
    // (paneTermRect가 이제 padding도 inset — minimal grid의 padding 동작은 별도 테스트가 커버).
    session.window_padding_px = .{};
    try std.testing.expectEqual(@as(u32, 0), session.sidebar_width_px);
    try std.testing.expectEqual(@as(u32, 0), pane_ops.paneBarHeightPx(session));
    const rect: maru.session.SplitRect = .{ .x = 0, .y = 0, .w = 800, .h = 600 };
    try std.testing.expect(pane_ops.paneBarRect(session, rect) == null);
    const term = pane_ops.paneTermRect(session, rect);
    try std.testing.expectEqual(@as(u32, 0), term.y);
    try std.testing.expectEqual(@as(u32, 600), term.h);
}

test "minimal scratch session blocks new_tab/new_term; minimal_tabs re-enables them" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // 실 PTY spawn(newTab/newTermInActivePane)
    const allocator = std.testing.allocator;

    // ① chrome_minimal + minimal_tabs=0(기본 스크래치): 탭/Term 생성 액션이 무동작.
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
            .abi_version = abi_version,
            .cols = 20,
            .rows = 5,
            .queue_capacity = 16,
            .command_kind = @intFromEnum(CommandKind.controlled_smoke),
            .chrome_minimal = 1,
            .minimal_tabs = 0,
        });
        defer session.deinit();
        try std.testing.expect(session.tabsBlocked());
        try std.testing.expectEqual(@as(usize, 1), session.tabs.items.len);
        try std.testing.expectEqual(@as(usize, 1), pane_ops.activePane(session).terms.items.len);
        session.dispatchAppAction(.new_tab);
        session.dispatchAppAction(.new_term);
        try std.testing.expectEqual(@as(usize, 1), session.tabs.items.len); // 새 워크스페이스 안 생김
        try std.testing.expectEqual(@as(usize, 1), pane_ops.activePane(session).terms.items.len); // 새 Term 안 생김
    }

    // ② chrome_minimal + minimal_tabs=1: 탭/Term 생성이 다시 동작.
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
            .abi_version = abi_version,
            .cols = 20,
            .rows = 5,
            .queue_capacity = 16,
            .command_kind = @intFromEnum(CommandKind.controlled_smoke),
            .chrome_minimal = 1,
            .minimal_tabs = 1,
        });
        defer session.deinit();
        try std.testing.expect(!session.tabsBlocked());
        session.dispatchAppAction(.new_term); // 활성 pane에 Term 추가
        try std.testing.expectEqual(@as(usize, 2), pane_ops.activePane(session).terms.items.len);
        session.dispatchAppAction(.new_tab); // 새 워크스페이스
        try std.testing.expectEqual(@as(usize, 2), session.tabs.items.len);
    }
}

test "minimal tab indicator: adaptive dots appear only in minimal with >1 tab" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // refreshCellMetrics(cell_width_px) + 실 PTY
    const allocator = std.testing.allocator;
    var out: std.ArrayList(metal_frame.NativeMetalCell) = .empty;
    defer out.deinit(allocator);

    // ① minimal + minimal_tabs: 단일이면 무동작, Term 2개면 strip+점2개(활성=마지막에 그려진 셀).
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
            .abi_version = abi_version,
            .cols = 40,
            .rows = 5,
            .queue_capacity = 16,
            .command_kind = @intFromEnum(CommandKind.controlled_smoke),
            .chrome_minimal = 1,
            .minimal_tabs = 1,
        });
        defer session.deinit();
        _ = try session.resize(800, 600, 1000); // backing 폭을 잡아야 termRect.w>0(인디케이터 폭 계산)

        out.clearRetainingCapacity();
        tab_ops.appendMinimalTabIndicator(session, &out);
        try std.testing.expectEqual(@as(usize, 0), out.items.len); // 탭 1개 → 점 없음

        session.dispatchAppAction(.new_term); // Term 2개(새 Term이 활성 = index 1)
        out.clearRetainingCapacity();
        tab_ops.appendMinimalTabIndicator(session, &out);
        try std.testing.expectEqual(@as(usize, 3), out.items.len); // strip + 점 2개
        try std.testing.expectEqual(sidebar_ops.sidebarBg(session), out.items[0].background); // strip
        try std.testing.expectEqual(sidebar_ops.sidebarHoverBg(session), out.items[1].background); // 비활성 점(i=0)
        try std.testing.expectEqual(sidebar_ops.sidebarActiveBg(session), out.items[2].background); // 활성 점(i=1)
        // 점은 strip 안에서 우상단(row 0), 활성 점이 비활성보다 오른쪽(+2칸).
        try std.testing.expectEqual(@as(u16, 0), out.items[2].row);
        try std.testing.expectEqual(out.items[1].col + 2, out.items[2].col);

        // 워크스페이스가 여러 개면 그쪽을 우선 표시(차원 전환). 새 워크스페이스 = 활성 index 1.
        session.dispatchAppAction(.new_tab);
        out.clearRetainingCapacity();
        tab_ops.appendMinimalTabIndicator(session, &out);
        try std.testing.expectEqual(@as(usize, 3), out.items.len); // 워크스페이스 2개 → strip + 점 2개
        try std.testing.expectEqual(sidebar_ops.sidebarActiveBg(session), out.items[2].background); // 활성 워크스페이스(index 1)

        // band가 화면보다 넓으면(아주 좁은 패널) 아예 안 그린다 — 좌상단 relocate 방지(우상단에 안 들어가면 skip).
        _ = try session.resize(16, 200, 1000); // 폭 16px → cols ≤ 2, band(2 워크스페이스=5)+margin > cols
        out.clearRetainingCapacity();
        tab_ops.appendMinimalTabIndicator(session, &out);
        try std.testing.expectEqual(@as(usize, 0), out.items.len);
    }

    // ② full(chrome_minimal=0): 탭이 여러 개여도 인디케이터 없음(사이드바·탭 바가 보여줌).
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
            .abi_version = abi_version,
            .cols = 40,
            .rows = 5,
            .queue_capacity = 16,
            .command_kind = @intFromEnum(CommandKind.controlled_smoke),
            .chrome_minimal = 0,
        });
        defer session.deinit();
        session.dispatchAppAction(.new_term); // Term 2개(full은 게이트 없음)
        try std.testing.expectEqual(@as(usize, 2), pane_ops.activePane(session).terms.items.len);
        out.clearRetainingCapacity();
        tab_ops.appendMinimalTabIndicator(session, &out);
        try std.testing.expectEqual(@as(usize, 0), out.items.len); // full → 무동작
    }
}

test "command catalog: 엔트리·바인딩 표시 + runAction 디스패치" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // 실 init(loaded_config resolver) + PTY
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    const catalog = session.commandCatalog();
    try std.testing.expectEqual(command_catalog.entries.len, catalog.len);
    // new_term 엔트리: 제목 + 빌트인 Cmd+T 바인딩 표시. close_tab: 기본 바인딩 없어 빈 표시.
    var saw_new_term = false;
    var saw_close_tab = false;
    for (catalog) |e| {
        const key = std.mem.span(e.action_key);
        if (std.mem.eql(u8, key, "new_term")) {
            try std.testing.expectEqualStrings("New Terminal", std.mem.span(e.title));
            try std.testing.expectEqualStrings("⌘T", std.mem.span(e.key_display));
            try std.testing.expectEqualStrings("t", std.mem.span(e.key_equivalent)); // NSMenuItem keyEquivalent
            try std.testing.expectEqual(command_catalog.mod_command, e.key_modifiers);
            saw_new_term = true;
        } else if (std.mem.eql(u8, key, "close_tab")) {
            try std.testing.expectEqualStrings("", std.mem.span(e.key_display)); // 기본 바인딩 없음
            try std.testing.expectEqualStrings("", std.mem.span(e.key_equivalent));
            try std.testing.expectEqual(@as(u32, 0), e.key_modifiers);
            saw_close_tab = true;
        }
    }
    try std.testing.expect(saw_new_term and saw_close_tab);

    // runAction: new_term → 활성 pane Term +1(full 세션이라 tabsBlocked=false). 모르는 키는 false·무동작.
    try std.testing.expectEqual(@as(usize, 1), pane_ops.activePane(session).terms.items.len);
    try std.testing.expect(session.runAction("new_term"));
    try std.testing.expectEqual(@as(usize, 2), pane_ops.activePane(session).terms.items.len);
    try std.testing.expect(!session.runAction("bogus_action"));
    try std.testing.expectEqual(@as(usize, 2), pane_ops.activePane(session).terms.items.len);
}

test "command palette(chrome): 토글 열림 → 타이핑 필터 → IME 조합 표시 → Enter 디스패치+닫힘 → 프레임 빌드" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // buildChromeOverlayFrame=CoreText, 실 PTY
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000); // 메트릭·backing(palette.view가 chrome props로 씀)

    // 토글로 열린다(chrome palette 컴포넌트) — 빈 쿼리라 전체 카탈로그가 필터에(platform palette_filtered).
    try std.testing.expect(!session.chrome_host.palette.open);
    session.dispatchAppAction(.toggle_command_palette);
    try std.testing.expect(session.chrome_host.palette.open);
    try std.testing.expectEqual(command_catalog.entries.len, session.palette_filtered.items.len);
    try std.testing.expectEqual(command_catalog.entries.len, session.chrome_host.palette.result_count); // 컴포넌트 동기화

    // IME 조합 회귀(C1b 버그 수정): 팝업 열린 동안 marked text가 팝업 preedit에 들어간다(뒤의 터미널 core가 아니라).
    // 레거시 팝업은 IME 조합 배선이 없어 한글 조합이 숨은 터미널로 샜다.
    input_ops.imeMarked(session, "\xea\xb0\x80"); // 조합 중 "가"
    try std.testing.expectEqualStrings("\xea\xb0\x80", session.chrome_host.palette.input.preedit.items);
    try std.testing.expect(!term_ops.activeSurface(session).preedit.active()); // 터미널 Surface overlay로 안 샌다
    input_ops.imeMarked(session, ""); // 조합 해제(확정 직전)

    // "new t" 타이핑(chrome 라우팅 → palette.handle → query_changed → recomputePalette) → "New Terminal"만 남는다.
    for ("new t") |c| _ = try session.handleKeyEvent(.{ .key = .{ .char = c }, .modifiers = .{} });
    try std.testing.expectEqual(@as(usize, 1), session.palette_filtered.items.len);
    try std.testing.expect(command_palette.actionAt(session.palette_filtered.items, session.chrome_host.palette.selected).? == .new_term);

    // Enter → accept → acceptPalette가 new_term 실행(full이라 게이트 없음) 후 닫힘. 활성 pane Term +1.
    const before = pane_ops.activePane(session).terms.items.len;
    _ = try session.handleKeyEvent(.{ .key = .enter, .modifiers = .{} });
    try std.testing.expect(!session.chrome_host.palette.open);
    try std.testing.expectEqual(before + 1, pane_ops.activePane(session).terms.items.len);

    // 다시 열고 Esc로 닫힌다.
    session.dispatchAppAction(.toggle_command_palette);
    try std.testing.expect(session.chrome_host.palette.open);
    _ = try session.handleKeyEvent(.{ .key = .escape, .modifiers = .{} });
    try std.testing.expect(!session.chrome_host.palette.open);

    // 열린 상태에서 chrome 오버레이 프레임 빌드가 크래시 없이 셀을 낸다(palette.view → 일반 rasterizer).
    session.dispatchAppAction(.toggle_command_palette);
    var pf = try testBuildChromeOverlayFrame(session);
    defer pf.frame.deinit(allocator);
    try std.testing.expect(pf.frame.draw_list.cells.len > 0);

    // 회귀(메뉴 모달 우회): 팝업이 열린 동안 메뉴바 keyEquivalent 경로(runAction)는 무시된다 — 모달 뒤 터미널이
    // 조작되면 안 된다. (팝업 자신의 Enter는 chrome_host.handleInput → dispatchChromeAction이 처리하므로 별개.)
    try std.testing.expect(session.chrome_host.palette.open);
    const terms_before_runaction = pane_ops.activePane(session).terms.items.len;
    try std.testing.expect(!session.runAction("new_term"));
    try std.testing.expectEqual(terms_before_runaction, pane_ops.activePane(session).terms.items.len);

    // caret 깜빡임: 팝업이 열린 프레임을 tick으로 빌드하면 cursor_cells=1(팝업 입력 caret이 맨 끝 suffix) — 이제
    // caret이 터미널 커서와 같은 suffix-trim 깜빡임을 탄다. (예전엔 0으로 고정해 정적이었음 — caret 깜빡임 추가로 변경.)
    _ = try session.tick();
    try std.testing.expectEqual(@as(usize, 1), session.metal_buffer.cursor_cells);
}

test "scrollback find(chrome): 토글 열림 → 증분 검색 → 매치 네비게이션 → 하이라이트·오버레이 프레임" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // buildChromeOverlayFrame=CoreText, 실 PTY
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 6,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000); // 메트릭·backing(find.view가 chrome props로 씀)

    // 검색 대상 텍스트를 코어에 직접 쓴다(유니크 토큰 2곳 — 셸 출력과 충돌 없게).
    try term_ops.activeSurface(session).core.write("MARUFIND one\r\ntwo MARUFIND three");

    // 토글로 열린다(chrome find 컴포넌트) — 빈 검색어라 매치 0. 매치 리스트는 session(find_matches) 소유.
    try std.testing.expect(!session.chrome_host.find.open);
    session.dispatchAppAction(.toggle_find);
    try std.testing.expect(session.chrome_host.find.open);
    try std.testing.expectEqual(@as(usize, 0), session.find_matches.items.len);

    // "MARUFIND" 타이핑(chrome 라우팅 → find.handle → query_changed → recomputeFind) → 2곳 매치, 현재는 첫 매치.
    for ("MARUFIND") |c| _ = try session.handleKeyEvent(.{ .key = .{ .char = c }, .modifiers = .{} });
    try std.testing.expectEqual(@as(usize, 2), session.find_matches.items.len);
    try std.testing.expectEqual(@as(usize, 2), session.chrome_host.find.match_count); // 컴포넌트 카운트 동기화
    try std.testing.expectEqual(@as(usize, 0), session.chrome_host.find.current);

    // Enter=다음 매치, Shift+Enter=이전(wrap). 모디파이어가 chrome.input으로 매핑돼 Shift가 prev로 간다.
    _ = try session.handleKeyEvent(.{ .key = .enter, .modifiers = .{} });
    try std.testing.expectEqual(@as(usize, 1), session.chrome_host.find.current);
    _ = try session.handleKeyEvent(.{ .key = .enter, .modifiers = .{ .shift = true } });
    try std.testing.expectEqual(@as(usize, 0), session.chrome_host.find.current);

    // Backspace로 한 글자 지워도("MARUFIN") 부분일치라 두 곳 다 매치 유지.
    _ = try session.handleKeyEvent(.{ .key = .backspace, .modifiers = .{} });
    try std.testing.expectEqual(@as(usize, 2), session.find_matches.items.len);

    // chrome 오버레이 프레임 빌드가 크래시 없이 셀을 낸다(find.view → 일반 rasterizer: "Find: …" + 카운터).
    var ff = try testBuildChromeOverlayFrame(session);
    defer ff.frame.deinit(allocator);
    try std.testing.expect(ff.frame.draw_list.cells.len > 0);

    // 회귀: Find 열린 동안 메뉴 keyEquivalent(runAction)는 무시된다(모달 뒤 터미널 조작 차단).
    try std.testing.expect(!session.runAction("new_term"));

    // tick으로 Find 열린 프레임을 빌드하면 cursor_cells=1(Find 입력 caret이 맨 끝 suffix) — caret이 터미널 커서와
    // 같은 suffix-trim 깜빡임을 탄다(예전엔 0 고정으로 정적이었음 — caret 깜빡임 추가로 변경).
    _ = try session.tick();
    try std.testing.expectEqual(@as(usize, 1), session.metal_buffer.cursor_cells);

    // ⌘+글자는 검색어에 안 쌓고 닫는다(평문만 입력) — 위 흐름에서 find가 아직 열려 있다.
    try std.testing.expect(session.chrome_host.find.open);
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'c' }, .modifiers = .{ .command = true } });
    try std.testing.expect(!session.chrome_host.find.open);

    // 다시 열고 Esc로 닫힌다.
    session.dispatchAppAction(.toggle_find);
    try std.testing.expect(session.chrome_host.find.open);
    _ = try session.handleKeyEvent(.{ .key = .escape, .modifiers = .{} });
    try std.testing.expect(!session.chrome_host.find.open);
}

test "EF1 편집기 pane의 ⌘F는 **문서**를 검색한다 (§5.1)" {
    // **없던 기능을 더하는 것이 아니라 조용히 틀린 것을 고친다.** 편집기 Term의 코어는 1×1
    // sentinel이고(`createEditorTerm`) 텍스트는 `rt.editor_lines`에 있다 — 그런데 ⌘F는 갈래 없이
    // `activeSurface().core`를 검색했다. 그래서 편집기에서 ⌘F를 누르고 아무 단어나 쳐도 **늘 0/0**이었다.
    //
    // 이 판정자는 **종단**이다: 키 이벤트 → chrome 라우팅 → `query_changed` → `recomputeFind`.
    // 그 사이 어느 한 곳만 재면 배선을 지워도 초록이 남는다(탭 폭 슬라이스가 그 형태로 한 번 틀렸다).
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const io = std.testing.io;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 12,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000);

    var dir = std.testing.tmpDir(.{});
    defer dir.cleanup();
    // `MARUFIND`가 **한 줄에 둘, 다른 줄에 하나** — 줄당 여러 매치가 목록에도 서는지 함께 본다.
    // **마지막 매치를 화면 밖에 둔다.** 그래야 Enter가 뷰를 옮기는지(=`scrollToCurrentMatch`의
    // 편집기 갈래가 배선돼 있는지) 잴 수 있다 — 그 두 줄을 지워도 판정자 전부가 초록이었다
    // (뮤턴트 M14, 적대적 검증 2026-08-23). `EM3`·`EM4`가 `revealCurrentFindMatch`를 **직접**
    // 부르는 형태라 배선을 건너뛴다 — 이 저장소가 반복해 당한 그 모양이다.
    var doc: std.ArrayList(u8) = .empty;
    defer doc.deinit(allocator);
    try doc.appendSlice(allocator, "MARUFIND one MARUFIND\nplain\ntwo MARUFIND three\n");
    for (0..300) |i| {
        var line_buf: [32]u8 = undefined;
        try doc.appendSlice(allocator, try std.fmt.bufPrint(&line_buf, "filler {d}\n", .{i}));
    }
    try doc.appendSlice(allocator, "MARUFIND far below\n");
    try dir.dir.writeFile(io, .{ .sub_path = "d.txt", .data = doc.items });
    var root_buf: [std.fs.max_path_bytes]u8 = undefined;
    const root = root_buf[0..try dir.dir.realPath(io, &root_buf)];
    const path = try std.fs.path.join(allocator, &.{ root, "d.txt" });
    defer allocator.free(path);
    const term = try editor_ops.openPathInActivePane(session, path);
    try std.testing.expectEqual(@as(usize, 305), term.rt.editor_lines.len); // 끝 개행이 만든 빈 줄까지

    // **대상이 갈린다.** tick이 `find.target`을 세우고, 그 값이 `.scrollback`으로 남으면 아래 검색이
    // sentinel 코어로 간다 — 이 단언이 그 갈림을 잰다.
    _ = try session.tick();
    try std.testing.expectEqual(chrome.components.find.Target.editor, session.chrome_host.find.target);

    session.dispatchAppAction(.toggle_find);
    try std.testing.expect(session.chrome_host.find.open);

    for ("MARUFIND") |c| _ = try session.handleKeyEvent(.{ .key = .{ .char = c }, .modifiers = .{} });
    try std.testing.expectEqual(@as(usize, 4), session.editor_find_matches.items.len);
    try std.testing.expectEqual(@as(usize, 4), session.chrome_host.find.match_count); // 카운터 동기화
    try std.testing.expectEqual(@as(usize, 0), session.chrome_host.find.current);
    try std.testing.expectEqual(term.surfaceId(), session.editor_find_source);
    // **스크롤백 목록은 안 건드린다** — 둘이 따로 살고, 섞이면 렌더가 남의 좌표를 클립한다.
    try std.testing.expectEqual(@as(usize, 0), session.find_matches.items.len);

    // 매치 좌표가 **문서 축**이다(줄, 줄 안 byte). 스크롤백 축이면 여기서 갈린다.
    try std.testing.expectEqual(@as(u32, 0), session.editor_find_matches.items[0].line);
    try std.testing.expectEqual(@as(u32, 0), session.editor_find_matches.items[0].start);
    try std.testing.expectEqual(@as(u32, 0), session.editor_find_matches.items[1].line);
    try std.testing.expectEqual(@as(u32, 13), session.editor_find_matches.items[1].start);
    try std.testing.expectEqual(@as(u32, 2), session.editor_find_matches.items[2].line);

    // Enter=다음, Shift+Enter=이전(wrap) — 스크롤백과 같은 키·같은 컴포넌트다.
    _ = try session.handleKeyEvent(.{ .key = .enter, .modifiers = .{} });
    try std.testing.expectEqual(@as(usize, 1), session.chrome_host.find.current);
    _ = try session.handleKeyEvent(.{ .key = .enter, .modifiers = .{ .shift = true } });
    try std.testing.expectEqual(@as(usize, 0), session.chrome_host.find.current);

    // **Enter가 뷰를 옮긴다.** ⇧Enter로 마지막(화면 밖) 매치까지 감아 가면 그 줄이 보이게
    // 굴러야 한다 — 이 단언이 `scrollToCurrentMatch`의 편집기 갈래를 판정 대상으로 만든다.
    try std.testing.expectEqual(@as(usize, 0), term.rt.editor_first_line);
    _ = try session.handleKeyEvent(.{ .key = .enter, .modifiers = .{ .shift = true } }); // 0 → 3(wrap)
    try std.testing.expectEqual(@as(usize, 3), session.chrome_host.find.current);
    try std.testing.expect(term.rt.editor_first_line > 0);
    // **한 프레임 그린다.** "이미 보이나"는 렌더가 굳힌 스냅숏(`editor_hit_lines`)을 읽는데,
    // 그것은 **굴러가기 전** 화면의 것이라 아직 첫 줄을 담고 있다. 제품은 매 tick 그리므로
    // 이 자리가 자연히 갱신되지만, 판정자가 그 프레임을 안 돌리면 옛 화면을 근거로 판정한다.
    _ = try session.tick();
    _ = try session.handleKeyEvent(.{ .key = .enter, .modifiers = .{} }); // 3 → 0(wrap) — 맨 위로 돌아온다
    try std.testing.expectEqual(@as(usize, 0), session.chrome_host.find.current);
    try std.testing.expectEqual(@as(usize, 0), term.rt.editor_first_line);

    // 한 글자 지우면 부분일치라 매치가 그대로다(증분 검색이 도는지).
    _ = try session.handleKeyEvent(.{ .key = .backspace, .modifiers = .{} });
    try std.testing.expectEqual(@as(usize, 4), session.editor_find_matches.items.len);

    // **닫으면 강조가 멈춘다** — 목록 둘 중 편집기 쪽만 비우면 남은 쪽이 계속 그린다.
    _ = try session.handleKeyEvent(.{ .key = .escape, .modifiers = .{} });
    try std.testing.expect(!session.chrome_host.find.open);
    try std.testing.expectEqual(@as(usize, 0), session.editor_find_matches.items.len);
    try std.testing.expectEqual(@as(u64, 0), session.editor_find_source);
}

test "EF2 편집기에서 터미널로 돌아오면 편집기 매치를 버린다" {
    // 목록이 둘이라 **대상이 바뀔 때 지난 쪽을 비우는 자리**가 필요하다. 안 비우면 터미널 pane
    // 위에서 편집기 매치가 살아 있고, 그 좌표는 이 화면 것이 아니다(웹 전환이 같은 이유로
    // `find_matches`를 비운다 — R5 실측).
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const io = std.testing.io;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 12,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000);

    var dir = std.testing.tmpDir(.{});
    defer dir.cleanup();
    try dir.dir.writeFile(io, .{ .sub_path = "d.txt", .data = "MARUFIND here\n" });
    var root_buf: [std.fs.max_path_bytes]u8 = undefined;
    const root = root_buf[0..try dir.dir.realPath(io, &root_buf)];
    const path = try std.fs.path.join(allocator, &.{ root, "d.txt" });
    defer allocator.free(path);
    _ = try editor_ops.openPathInActivePane(session, path);

    session.dispatchAppAction(.toggle_find);
    for ("MARUFIND") |c| _ = try session.handleKeyEvent(.{ .key = .{ .char = c }, .modifiers = .{} });
    try std.testing.expectEqual(@as(usize, 1), session.editor_find_matches.items.len);

    // **먼저 한 프레임을 돌려 대상을 굳힌다.** tick이 `target`을 세우는데, 그 재검색은 **값이 바뀔
    // 때만** 돈다 — 이 tick을 빼면 target이 기본값 `.scrollback`에 머물러 아래 전환이 "변화 없음"이
    // 되고, 판정자가 **아무것도 재지 않으면서 초록**이 된다(초판이 실제로 그랬다).
    _ = try session.tick();
    try std.testing.expectEqual(chrome.components.find.Target.editor, session.chrome_host.find.target);

    // 터미널 Term으로 돌아간다(편집기를 열기 전 것이 0번이다).
    session.focusTerm(0);
    _ = try session.tick();
    try std.testing.expectEqual(chrome.components.find.Target.scrollback, session.chrome_host.find.target);
    try std.testing.expectEqual(@as(usize, 0), session.editor_find_matches.items.len);
    try std.testing.expectEqual(@as(u64, 0), session.editor_find_source);
}

test "EF3 편집기에서 편집기로 옮기면 대상이 따라온다 — target 값만으로는 안 바뀐다" {
    // **적대적 검증이 잡은 결함**(2026-08-23). tick의 재검색 게이트가 `target` **값** 비교라
    // 편집기 A → 편집기 B는 둘 다 `.editor`여서 **분기가 안 열렸다**. 그래서 B는 재검색되지
    // 않아 강조가 하나도 안 그려지고, 카운터는 A의 수를 계속 말했다 — 사용자에겐 "검색이 죽었다".
    //
    // Term을 **닫는** 경우도 같은 뿌리다(다음 활성이 다른 편집기면 같은 상태). 그래서 이제
    // tick이 **출처 id**를 대조한다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const io = std.testing.io;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 12,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000);

    var dir = std.testing.tmpDir(.{});
    defer dir.cleanup();
    try dir.dir.writeFile(io, .{ .sub_path = "a.txt", .data = "MARUFIND MARUFIND MARUFIND\n" }); // 셋
    try dir.dir.writeFile(io, .{ .sub_path = "b.txt", .data = "MARUFIND once\n" }); // 하나
    var root_buf: [std.fs.max_path_bytes]u8 = undefined;
    const root = root_buf[0..try dir.dir.realPath(io, &root_buf)];
    const path_a = try std.fs.path.join(allocator, &.{ root, "a.txt" });
    defer allocator.free(path_a);
    const path_b = try std.fs.path.join(allocator, &.{ root, "b.txt" });
    defer allocator.free(path_b);

    const term_a = try editor_ops.openPathInActivePane(session, path_a);
    session.dispatchAppAction(.toggle_find);
    for ("MARUFIND") |c| _ = try session.handleKeyEvent(.{ .key = .{ .char = c }, .modifiers = .{} });
    _ = try session.tick();
    try std.testing.expectEqual(@as(usize, 3), session.editor_find_matches.items.len);
    try std.testing.expectEqual(term_a.surfaceId(), session.editor_find_source);

    // **오버레이를 연 채** 두 번째 편집기를 연다 — target은 `.editor`로 그대로다.
    const term_b = try editor_ops.openPathInActivePane(session, path_b);
    try std.testing.expectEqual(chrome.components.find.Target.editor, session.chrome_host.find.target);
    _ = try session.tick();

    // 재검색이 돌아 **B의 수**가 나오고 출처도 B다. 안 돌면 3과 A의 id가 그대로 남는다.
    try std.testing.expectEqual(@as(usize, 1), session.editor_find_matches.items.len);
    try std.testing.expectEqual(term_b.surfaceId(), session.editor_find_source);
    try std.testing.expectEqual(@as(usize, 1), session.chrome_host.find.match_count);

    // **가만히 있으면 프레임을 새로 만들지 않는다** — 매 tick 재검색하면 정지 화면이 계속 깨어난다.
    //
    // **`metal_dirty`로는 못 잰다.** tick이 그것을 소비해 늘 false로 되돌리므로 대입도 단언도
    // 죽은 코드가 된다 — 초판이 그랬고, 게이트를 `if (true)`로 바꿔도 초록이었다(2라운드 적대적
    // 검증. **이 커밋이 잡았다고 자랑한 바로 그 형태가 새 판정자에 그대로 있었다**).
    // 대신 **프레임 세대**를 두 tick 비교한다 — 재검색이 돌면 `metal_dirty`가 서고 그 tick이
    // 프레임을 새로 만들어 세대가 는다.
    const gen_before = (try session.tick()).metal_generation;
    const gen_after = (try session.tick()).metal_generation;
    try std.testing.expectEqual(gen_before, gen_after);
    try std.testing.expectEqual(term_b.surfaceId(), session.editor_find_source);
}

test "EF4 팔레트를 열면 편집기 강조도 멎는다 — 목록이 둘이라 한쪽만 비우면 남는다" {
    // 초판은 `toggleFind`와 `.find_close` 둘만 짝을 맞췄고, 같은 성질의 세 자리(커맨드 팔레트·
    // 설정 화면·모달 정리)는 `find_matches`만 비웠다. 터미널은 목록이 비어 증상이 안 보이지만
    // 편집기는 `find_nav`가 살아 있어 **오버레이가 사라졌는데 강조가 남았다**(적대적 검증 2026-08-23).
    if (builtin.os.tag != .macos) return error.SkipZigTest;
