    const io = std.testing.io;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 12,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000);

    var dir = std.testing.tmpDir(.{});
    defer dir.cleanup();
    try dir.dir.writeFile(io, .{ .sub_path = "d.txt", .data = "MARUFIND here\n" });
    var root_buf: [std.fs.max_path_bytes]u8 = undefined;
    const root = root_buf[0..try dir.dir.realPath(io, &root_buf)];
    const path = try std.fs.path.join(allocator, &.{ root, "d.txt" });
    defer allocator.free(path);
    _ = try editor_ops.openPathInActivePane(session, path);

    session.dispatchAppAction(.toggle_find);
    for ("MARUFIND") |c| _ = try session.handleKeyEvent(.{ .key = .{ .char = c }, .modifiers = .{} });
    try std.testing.expectEqual(@as(usize, 1), session.editor_find_matches.items.len);

    // ⌘⇧P — 배타적이라 find를 닫는다. 편집기 목록도 함께 비워야 한다.
    session.dispatchAppAction(.toggle_command_palette);
    try std.testing.expect(!session.chrome_host.find.open);
    try std.testing.expectEqual(@as(usize, 0), session.editor_find_matches.items.len);
    try std.testing.expectEqual(@as(u64, 0), session.editor_find_source);
}

test "EF5 웹으로 옮기면 편집기 매치를 버린다 — 렌더는 활성 pane만 도는 것이 아니다" {
    // **살아 있던 뮤턴트를 닫는다**(2라운드 적대적 검증 N4). tick 대조 블록에서 `clearEditorFind`
    // 만 지워도 아무도 못 잡았다 — `want_source != 0`인 경로는 뒤이은 `recomputeFind`가 목록을
    // 새로 채워 등가이기 때문이다. **새는 자리는 `want_source == 0`인데 위쪽 target 블록이
    // 재검색을 건너뛰는 경우**, 즉 `.page`로 갈 때다.
    //
    // 그 자리가 실제로 문제인 이유: 렌더는 **모든 leaf**를 돌아 `appendPaneFrame`을 부른다.
    // split 옆의 편집기는 활성이 아니어도 계속 그려지므로, 목록이 남으면 **오버레이는 페이지를
    // 검색 중인데 옆 편집기가 옛 검색어 강조를 계속 그린다**.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const io = std.testing.io;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 12,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000);

    var dir = std.testing.tmpDir(.{});
    defer dir.cleanup();
    try dir.dir.writeFile(io, .{ .sub_path = "d.txt", .data = "MARUFIND here\n" });
    var root_buf: [std.fs.max_path_bytes]u8 = undefined;
    const root = root_buf[0..try dir.dir.realPath(io, &root_buf)];
    const path = try std.fs.path.join(allocator, &.{ root, "d.txt" });
    defer allocator.free(path);
    _ = try editor_ops.openPathInActivePane(session, path);

    session.dispatchAppAction(.toggle_find);
    for ("MARUFIND") |c| _ = try session.handleKeyEvent(.{ .key = .{ .char = c }, .modifiers = .{} });
    _ = try session.tick();
    try std.testing.expectEqual(@as(usize, 1), session.editor_find_matches.items.len);
    try std.testing.expectEqual(chrome.components.find.Target.editor, session.chrome_host.find.target);

    // 같은 pane에 web Term을 만들어 활성화한다 — 편집기는 **여전히 그려지는 leaf**다.
    const web = try web_ops.createWebTerm(session, .browser);
    const pane = pane_ops.activePane(session);
    try pane.terms.append(allocator, web);
    term_ops.focusTerm(session, pane.terms.items.len - 1);
    _ = try session.tick();

    try std.testing.expectEqual(chrome.components.find.Target.page, session.chrome_host.find.target);
    try std.testing.expectEqual(@as(usize, 0), session.editor_find_matches.items.len);
    try std.testing.expectEqual(@as(u64, 0), session.editor_find_source);
}

test "EF6 ⌘G 네비 중 팔레트를 열면 tick이 강조를 되살리지 않는다 — 플래그가 아니라 행동을 잰다" {
    // **`EF4`는 이것을 못 잰다**(적대적 검증 2026-08-24, 뮤턴트 P7). 그쪽 시나리오는 오버레이를
    // **연 채** 팔레트를 열 뿐이라 `find_nav`가 참이 된 적이 없다. 그래서 `clearAllFindMatches`의
    // `find_nav = false`를 지워도 초록이었고, 커밋이 자랑한 *"편집기가 팔레트 뒤에서 맨 위로
    // 튄다(283 → 0)"* 는 **아무도 재지 않았다**.
    //
    // **플래그를 안 잰다.** `expect(!find_nav)`는 그 한 줄이 있는지만 보는데, 여기서 문제인 것은
    // 그 다음 tick의 **행동**이다 — 목록이 되살아나고 `current`가 0으로 리셋되며 뷰가 튄다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const io = std.testing.io;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 12,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000);

    var dir = std.testing.tmpDir(.{});
    defer dir.cleanup();
    var doc: std.ArrayList(u8) = .empty;
    defer doc.deinit(allocator);
    try doc.appendSlice(allocator, "MARUFIND top\n");
    for (0..300) |i| {
        var line_buf: [32]u8 = undefined;
        try doc.appendSlice(allocator, try std.fmt.bufPrint(&line_buf, "filler {d}\n", .{i}));
    }
    try doc.appendSlice(allocator, "MARUFIND far below\n");
    try dir.dir.writeFile(io, .{ .sub_path = "d.txt", .data = doc.items });
    var root_buf: [std.fs.max_path_bytes]u8 = undefined;
    const root = root_buf[0..try dir.dir.realPath(io, &root_buf)];
    const path = try std.fs.path.join(allocator, &.{ root, "d.txt" });
    defer allocator.free(path);
    const term = try editor_ops.openPathInActivePane(session, path);

    // 검색해서 아래쪽 매치로 간 뒤 **닫는다**.
    session.dispatchAppAction(.toggle_find);
    for ("MARUFIND") |c| _ = try session.handleKeyEvent(.{ .key = .{ .char = c }, .modifiers = .{} });
    _ = try session.tick();
    _ = try session.handleKeyEvent(.{ .key = .enter, .modifiers = .{} }); // 아래쪽 매치로
    _ = try session.tick();
    const scrolled = term.rt.editor_first_line;
    try std.testing.expect(scrolled > 0);
    _ = try session.handleKeyEvent(.{ .key = .escape, .modifiers = .{} });

    // **⌘G로 닫힘-네비를 연다** — 여기가 `find_nav = true`가 서는 유일한 자리다.
    session.dispatchAppAction(.find_next);
    try std.testing.expect(session.find_nav);
    try std.testing.expect(session.editor_find_matches.items.len > 0);

    // **한 번 더 쳐서 아래쪽 매치로 간다.** 이 줄이 없으면 아래 "뷰가 안 튄다"가 **공허하다** —
    // 첫 ⌘G는 `current`를 감아 **문서 줄 0**으로 가므로 `before == 0`이고, 회귀(`recomputeFind`가
    // `current = 0`으로 리셋)도 0으로 가서 `expectEqual(0, 0)`이 된다(적대적 검증 2026-08-24가
    // 프로브로 실측: `scrolled=276 before=0 after=0`).
    session.dispatchAppAction(.find_next);
    _ = try session.tick();
    const before = term.rt.editor_first_line;
    try std.testing.expect(before > 0); // 전제 — 깨지면 아래 단언이 아무것도 안 잰다

    // 팔레트를 연다. 그리고 **한 프레임 더 돈다** — 되살아나는 것은 tick이다.
    session.dispatchAppAction(.toggle_command_palette);
    _ = try session.tick();

    // **뷰 단언을 맨 앞에 둔다.** 뒤에 두면 목록 단언이 **먼저** 터져, 이 판정자의 이름
    // (*"플래그가 아니라 행동을 잰다"*)이 실제로는 목록만 재는 상태가 된다 — 도달하는 유일한
    // 제품 뮤턴트에서 앞 단언이 먼저 발화한다(적대적 검증 2026-08-24, 뮤턴트 R9/R10).
    try std.testing.expectEqual(before, term.rt.editor_first_line); // 뷰가 안 튄다
    try std.testing.expectEqual(@as(usize, 0), session.editor_find_matches.items.len); // 안 되살아난다
    try std.testing.expectEqual(@as(u64, 0), session.editor_find_source);
}

test "EF7 ⌘F를 다시 열면 빈 상자에 옛 강조가 안 남는다 — `show()`도 목록을 비운다" {
    // **4라운드가 고친 결함이 완전 무판정이었다**(적대적 검증 2026-08-24, 뮤턴트 Q10). `toggleFind`의
    // 여는 갈래에서 `clearAllFindMatches`를 지워도 **저장소 3,857개가 전부 초록**이었고, 프로브는
    // 그 나쁜 상태가 그대로 재현됨을 보였다:
    //
    //   원본  : open=true query_len=0 match_count=0 editor_matches=0 find_nav=false
    //   뮤턴트: open=true query_len=0 match_count=0 editor_matches=2 find_nav=true
    //
    // `show()`가 컴포넌트 상태(검색어·카운터)만 비우고 목록은 세션 소유라 안 건드리기 때문이다 —
    // **카운터는 0을 말하면서 화면엔 매치가 다 칠해져 있는** 상태다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const io = std.testing.io;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 12,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000);

    var dir = std.testing.tmpDir(.{});
    defer dir.cleanup();
    try dir.dir.writeFile(io, .{ .sub_path = "d.txt", .data = "MARUFIND one MARUFIND\n" });
    var root_buf: [std.fs.max_path_bytes]u8 = undefined;
    const root = root_buf[0..try dir.dir.realPath(io, &root_buf)];
    const path = try std.fs.path.join(allocator, &.{ root, "d.txt" });
    defer allocator.free(path);
    const term = try editor_ops.openPathInActivePane(session, path);

    session.dispatchAppAction(.toggle_find);
    for ("MARUFIND") |c| _ = try session.handleKeyEvent(.{ .key = .{ .char = c }, .modifiers = .{} });
    _ = try session.tick();
    try std.testing.expectEqual(@as(usize, 2), session.editor_find_matches.items.len);

    // 닫고 ⌘G로 닫힘-네비를 연다 — 목록이 되살아나고 `find_nav`가 선다.
    _ = try session.handleKeyEvent(.{ .key = .escape, .modifiers = .{} });
    session.dispatchAppAction(.find_next);
    try std.testing.expect(session.find_nav);
    try std.testing.expect(session.editor_find_matches.items.len > 0);

    // **다시 ⌘F.** `show()`가 검색어를 비우므로 상자는 비었다 — 그러면 강조도 없어야 한다.
    session.dispatchAppAction(.toggle_find);
    try std.testing.expect(session.chrome_host.find.open);
    try std.testing.expectEqual(@as(usize, 0), session.chrome_host.find.input.query.items.len);
    try std.testing.expectEqual(@as(usize, 0), session.editor_find_matches.items.len);
    // **이 줄은 공허하다** — 활성 pane이 편집기라 터미널 목록은 전후로 0이다(적대적 검증
    // 2026-08-24, 뮤턴트 R7b/R8이 각각 증명했다). 그래도 두는 이유는 **두 목록이 함께 비는 것이
    // 계약**이어서다. 터미널 축을 실제로 재는 것은 아래 `EF9`다.
    try std.testing.expectEqual(@as(usize, 0), session.find_matches.items.len);
    try std.testing.expect(!session.find_nav);
    // 그리고 렌더가 그 Term을 검색 대상으로 안 본다 — 마크가 실제로 안 그려진다는 뜻이다.
    try std.testing.expect(!editor_ops.isFindTarget(session, term));
}

test "EF8 낡은 스냅숏으로 놓은 자리는 **다음 프레임이 예약된다** — tick을 타야 보이는 배선" {
    // **6라운드가 찾은 차단 결함이다**(적대적 검증 2026-08-24). 5라운드가 만든 재조준은 자리를
    // 옳게 다시 잡았지만 **그 자리를 그릴 프레임을 못 불렀다**: 재조준이 세운 `metal_dirty`를
    // 같은 tick 뒤쪽 소거가 지웠고(그 자리 doc), 다음 tick은 투영을 건너뛰었다. 실측으로
    // **자리는 맞는데 tick 12번을 더 돌려도 화면은 옛 자리**였고, 손으로 dirty를 세우자 즉시 보였다.
    //
    // **`EM13`은 이것을 원리적으로 못 잰다** — `appendPaneFrame`을 직접 부르므로 그 함수 **바깥의**
    // 배선을 안 지난다. `EM*` 열넷이 전부 그 형태였고, 그래서 이 결함이 한 커밋을 지나 밀렸다.
    // 여기서는 **제품 `tick()`만** 쓴다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const io = std.testing.io;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 12,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000);

    var dir = std.testing.tmpDir(.{});
    defer dir.cleanup();
    var doc: std.ArrayList(u8) = .empty;
    defer doc.deinit(allocator);
    // 랩을 켜면 보이는 줄이 확 줄도록 **긴 줄**로 채운다.
    for (0..60) |i| {
        var buf: [400]u8 = undefined;
        const filler = "wrap me " ** 20;
        try doc.appendSlice(allocator, try std.fmt.bufPrint(&buf, "{d} {s}\n", .{ i, filler }));
    }
    try doc.appendSlice(allocator, "MARUFIND far below\n");
    try dir.dir.writeFile(io, .{ .sub_path = "w.txt", .data = doc.items });
    var root_buf: [std.fs.max_path_bytes]u8 = undefined;
    const root = root_buf[0..try dir.dir.realPath(io, &root_buf)];
    const path = try std.fs.path.join(allocator, &.{ root, "w.txt" });
    defer allocator.free(path);
    const term = try editor_ops.openPathInActivePane(session, path);

    // 랩을 끈 채 한 프레임 — 스냅숏이 그 배치로 굳는다.
    term.rt.editor_wrap = false;
    _ = try session.tick();
    try std.testing.expect(term.rt.editor_hit_rows_len > 0); // 렌더 경로를 실제로 탔다

    session.dispatchAppAction(.toggle_find);
    for ("MARUFIND") |c| _ = try session.handleKeyEvent(.{ .key = .{ .char = c }, .modifiers = .{} });
    _ = try session.tick();
    try std.testing.expect(session.editor_find_matches.items.len > 0);

    // **랩을 켠다 — 프레임 없이.** 세로 위치는 그대로다(토글이 일부러 안 건드린다).
    term.rt.editor_wrap = true;
    term.rt.editor_first_line = 0;
    session.chrome_host.find.current = 0;

    // Enter로 아래쪽 매치를 부른다 — 낡은 스냅숏이라 재조준이 예약돼야 한다.
    _ = try session.handleKeyEvent(.{ .key = .enter, .modifiers = .{} });
    _ = try session.handleKeyEvent(.{ .key = .enter, .modifiers = .{ .shift = true } });
    try std.testing.expect(term.rt.editor_find_reveal_pending);

    // 그 프레임이 재조준을 돌리고 **다음 프레임을 예약한다**. 예약이 없으면 자리는 맞고 화면이 멈춘다.
    _ = try session.tick();
    try std.testing.expect(!term.rt.editor_find_reveal_pending); // 소진됐다
    try std.testing.expect(session.metal_dirty); // **다음 프레임이 예약됐다** — 이 줄이 그 결함을 잡는다
    try std.testing.expect(!session.reproject_after_frame); // 한 번 쓰고 소진된다

    // 그리고 그 다음 프레임이 매치를 실제로 그린다.
    _ = try session.tick();
    const target = session.editor_find_matches.items[session.chrome_host.find.current].line;
    const shown = for (term.rt.editor_hit_lines[0..term.rt.editor_hit_rows_len]) |dl| {
        if (dl == target) break true;
    } else false;
    try std.testing.expect(shown);
}

test "EF9 터미널에서도 ⌘F를 다시 열면 옛 강조가 안 남는다 — `show()` 규칙의 나머지 절반" {
    // **`EF7`의 터미널 단언이 공허했다**(적대적 검증 2026-08-24, 뮤턴트 R7b). 그쪽은 활성 pane이
    // 편집기라 `find_matches`가 전후로 0이다 — 그래서 여는 갈래가 **편집기 쪽만** 비우도록
    // 바꿔도 저장소가 전부 초록이었다. `show()`가 검색어를 비우는 것은 pane 종류와 무관하므로
    // **터미널에도 같은 결함이 있었다**: 빈 상자에 옛 강조.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 6,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000);
    try term_ops.activeSurface(session).core.write("MARUFIND one\r\ntwo MARUFIND three");

    session.dispatchAppAction(.toggle_find);
    for ("MARUFIND") |c| _ = try session.handleKeyEvent(.{ .key = .{ .char = c }, .modifiers = .{} });
    try std.testing.expectEqual(@as(usize, 2), session.find_matches.items.len);

    // 닫고 ⌘G로 닫힘-네비를 연다 — 목록이 되살아나고 `find_nav`가 선다.
    _ = try session.handleKeyEvent(.{ .key = .escape, .modifiers = .{} });
    session.dispatchAppAction(.find_next);
    try std.testing.expect(session.find_nav);
    try std.testing.expect(session.find_matches.items.len > 0);

    // **다시 ⌘F.** 상자가 비었으니 강조도 없어야 한다.
    session.dispatchAppAction(.toggle_find);
    try std.testing.expectEqual(@as(usize, 0), session.chrome_host.find.input.query.items.len);
    try std.testing.expectEqual(@as(usize, 0), session.find_matches.items.len);
    try std.testing.expect(!session.find_nav);
}

test "EF11 현재 일치가 primary selection을 옮긴다 — 닫으면 그 자리에서 편집이 이어진다 (§5.1)" {
    // **색만 바꾸면 찾은 자리와 고치는 자리가 갈린다.** Enter로 매치를 오가다 Esc를 누르면 caret은
    // 검색 전 자리에 남아, 사용자는 **화면이 가리키는 곳과 다른 곳**을 고친다. §5.1이 *"별도 커서
    // 개념을 만들지 않는다"*고 정한 이유가 그것이다.
    //
    // **종단으로 잰다** — 키 → chrome → recomputeFind → reveal. 중간만 재면 배선을 지워도 초록이다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const io = std.testing.io;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 12,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000);

    var dir = std.testing.tmpDir(.{});
    defer dir.cleanup();
    // 매치 셋: 0줄 4, 0줄 17, 2줄 0. 줄 안 offset이 0이 아닌 것을 섞어야 **줄 머리로 가는 실수**가 잡힌다.
    try dir.dir.writeFile(io, .{ .sub_path = "d.txt", .data = "abc NEEDLE def NEEDLE\nplain\nNEEDLE tail\n" });
    var root_buf: [std.fs.max_path_bytes]u8 = undefined;
    const root = root_buf[0..try dir.dir.realPath(io, &root_buf)];
    const path = try std.fs.path.join(allocator, &.{ root, "d.txt" });
    defer allocator.free(path);
    const term = try editor_ops.openPathInActivePane(session, path);
    _ = try session.tick();

    // 검색 전 caret은 문서 머리다.
    term.rt.editor_selection = maru.session.editor.selection.Selection.at(0);

    session.dispatchAppAction(.toggle_find);
    for ("NEEDLE") |c| _ = try session.handleKeyEvent(.{ .key = .{ .char = c }, .modifiers = .{} });
    try std.testing.expectEqual(@as(usize, 3), session.editor_find_matches.items.len);

    // ⑴ **증분 검색이 첫 매치를 고른다** — caret이 아니라 **범위**여야 무엇을 찾았는지 화면이 말한다.
    {
        const sel = term.rt.editor_selection.?;
        try std.testing.expectEqual(@as(usize, 4), sel.start());
        try std.testing.expectEqual(@as(usize, 10), sel.end());
    }

    // ⑵ Enter가 다음 매치로 옮긴다(같은 줄 두 번째 — 줄 머리로 가면 여기서 걸린다).
    _ = try session.handleKeyEvent(.{ .key = .enter, .modifiers = .{} });
    {
        const sel = term.rt.editor_selection.?;
        try std.testing.expectEqual(@as(usize, 15), sel.start());
        try std.testing.expectEqual(@as(usize, 21), sel.end());
    }

    // ⑶ 한 번 더 — 줄이 바뀌어도 문서 offset 축을 지킨다("plain\n"이 22..28).
    _ = try session.handleKeyEvent(.{ .key = .enter, .modifiers = .{} });
    {
        const sel = term.rt.editor_selection.?;
        try std.testing.expectEqual(@as(usize, 28), sel.start());
        try std.testing.expectEqual(@as(usize, 34), sel.end());
    }

    // ⑷ **닫으면 그 자리에서 편집이 이어진다** — 고른 매치 위에 타이핑하면 그것을 덮어쓴다.
    _ = try session.handleKeyEvent(.{ .key = .escape, .modifiers = .{} });
    try std.testing.expect(!session.chrome_host.find.open);
    _ = editor_ops.insertText(session, term, "X");
    try std.testing.expectEqualStrings("abc NEEDLE def NEEDLE\nplain\nX tail\n", term.rt.editor_doc.?.file.content);
}

test "EF12 매치로 옮길 때 멀티커서를 정리한다 (§3.2)" {
    // 커서를 새로 놓는 경로는 전부 나머지를 버린다 — 안 버리면 사용자가 그것을 없앨 방법이 없고,
    // 곧 설 **바꾸기**가 엉뚱한 자리까지 건드린다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const io = std.testing.io;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 12,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000);

    var dir = std.testing.tmpDir(.{});
    defer dir.cleanup();
    try dir.dir.writeFile(io, .{ .sub_path = "d.txt", .data = "aa NEEDLE bb\ncc NEEDLE dd\n" });
    var root_buf: [std.fs.max_path_bytes]u8 = undefined;
    const root = root_buf[0..try dir.dir.realPath(io, &root_buf)];
    const path = try std.fs.path.join(allocator, &.{ root, "d.txt" });
    defer allocator.free(path);
    const term = try editor_ops.openPathInActivePane(session, path);
    _ = try session.tick();

    const extras = try allocator.alloc(maru.session.editor.selection.Selection, 2);
    extras[0] = maru.session.editor.selection.Selection.at(1);
    extras[1] = maru.session.editor.selection.Selection.at(2);
    allocator.free(term.rt.editor_extra_selections);
    term.rt.editor_extra_selections = extras;
    term.rt.editor_selection = maru.session.editor.selection.Selection.at(0);

    session.dispatchAppAction(.toggle_find);
    for ("NEEDLE") |c| _ = try session.handleKeyEvent(.{ .key = .{ .char = c }, .modifiers = .{} });

    try std.testing.expectEqual(@as(usize, 0), term.rt.editor_extra_selections.len);
    try std.testing.expectEqual(@as(usize, 3), term.rt.editor_selection.?.start());
}

test "EF13 검색으로 옮긴 커서는 앞의 타이핑과 한 묶음이 아니다 (§3.3)" {
    // **묶음 판단은 종류와 시간만 본다**(`sameUndoGroup`) — 커서가 어디로 갔는지는 안 본다.
    // 그래서 검색 네비게이션이 `breakUndoGroup`을 안 부르면, 찾아가서 고친 것이 **찾기 전에 친
    // 글자와 한 덩어리**가 되어 되돌리기 한 번에 둘 다 사라진다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const io = std.testing.io;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 12,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000);

    var dir = std.testing.tmpDir(.{});
    defer dir.cleanup();
    try dir.dir.writeFile(io, .{ .sub_path = "d.txt", .data = "aa NEEDLE bb\n" });
    var root_buf: [std.fs.max_path_bytes]u8 = undefined;
    const root = root_buf[0..try dir.dir.realPath(io, &root_buf)];
    const path = try std.fs.path.join(allocator, &.{ root, "d.txt" });
    defer allocator.free(path);
    const term = try editor_ops.openPathInActivePane(session, path);
    _ = try session.tick();

    term.rt.editor_selection = maru.session.editor.selection.Selection.at(0);
    _ = editor_ops.insertText(session, term, "X"); // ⑴ 찾기 전 타이핑
    try std.testing.expectEqualStrings("Xaa NEEDLE bb\n", term.rt.editor_doc.?.file.content);

    session.dispatchAppAction(.toggle_find);
    for ("NEEDLE") |c| _ = try session.handleKeyEvent(.{ .key = .{ .char = c }, .modifiers = .{} });
    _ = try session.handleKeyEvent(.{ .key = .escape, .modifiers = .{} });
    _ = editor_ops.insertText(session, term, "Y"); // ⑵ 찾아간 자리를 고친다
    try std.testing.expectEqualStrings("Xaa Y bb\n", term.rt.editor_doc.?.file.content);

    // **한 번의 되돌리기는 ⑵만 되돌린다.** 묶이면 여기서 ⑴까지 사라진다.
    try std.testing.expect(editor_ops.undoEdit(session, term));
    try std.testing.expectEqualStrings("Xaa NEEDLE bb\n", term.rt.editor_doc.?.file.content);
}

test "EF23 ⌥⌘C·⌥⌘W가 찾기 규칙을 바꾼다 — 키 경로 전체 (§5.1)" {
    // **함수를 직접 부르는 판정자만 두면 chord 가 안 붙어도 전부 초록이다.** 이 저장소가 반복해
    // 겪은 실패라(EF14 가 같은 이유로 섰다) 여기서는 **키부터** 지난다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const io = std.testing.io;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 12,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000);

    var dir = std.testing.tmpDir(.{});
    defer dir.cleanup();
    // `Id`·`id`·`ID` 셋에 `id_x` 안에 박힌 것 하나 — 두 축이 각각 다른 답을 낸다.
    try dir.dir.writeFile(io, .{ .sub_path = "d.txt", .data = "Id id ID id_x\n" });
    var root_buf: [std.fs.max_path_bytes]u8 = undefined;
    const root = root_buf[0..try dir.dir.realPath(io, &root_buf)];
    const path = try std.fs.path.join(allocator, &.{ root, "d.txt" });
    defer allocator.free(path);
    _ = try editor_ops.openPathInActivePane(session, path);
    _ = try session.tick();

    session.dispatchAppAction(.toggle_find);
    for ("id") |c| _ = try session.handleKeyEvent(.{ .key = .{ .char = c }, .modifiers = .{} });
    try std.testing.expectEqual(@as(usize, 4), session.editor_find_matches.items.len); // 기본: 넷 다

    // **⌥⌘C — 대소문자를 가린다.** `id` 와 `id_x` 안의 `id` 둘만 남는다.
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'c' }, .modifiers = .{ .command = true, .option = true } });
    try std.testing.expect(session.chrome_host.find.match_case);
    try std.testing.expectEqual(@as(usize, 2), session.editor_find_matches.items.len);

    // **⌥⌘W — 낱말 단위.** 둘 중 `id_x` 안의 것이 빠져 하나가 된다.
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'w' }, .modifiers = .{ .command = true, .option = true } });
    try std.testing.expect(session.chrome_host.find.whole_word);
    try std.testing.expectEqual(@as(usize, 1), session.editor_find_matches.items.len);

    // **카운터가 목록과 같이 움직인다** — 안 맞추면 「1/4」 같은 거짓이 뜬다.
    try std.testing.expectEqual(@as(usize, 1), session.chrome_host.find.match_count);
    try std.testing.expectEqual(@as(usize, 0), session.chrome_host.find.current);

    // **검색어는 그대로다** — 규칙만 바뀌는 것이지 다시 치게 하는 것이 아니다.
    try std.testing.expectEqualStrings("id", session.chrome_host.find.input.query.items);

    // **되돌리면 넷으로 돌아온다** — 토글이 한 방향이면 사용자가 원래 규칙으로 못 간다.
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'c' }, .modifiers = .{ .command = true, .option = true } });
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'w' }, .modifiers = .{ .command = true, .option = true } });
    try std.testing.expectEqual(@as(usize, 4), session.editor_find_matches.items.len);
}

test "EF24 규칙 토글은 편집기 찾기가 떠 있을 때만 먹는다 — 범위와 첫 매치 (§5.1)" {
    // **세 가지가 조용히 틀릴 수 있는 자리다.** ⑴ 규칙이 좁아질 때 `current` 를 그대로 두면
    // `setMatchCount` 가 **끝으로 clamp** 해 사용자가 보던 자리가 아니라 마지막으로 튄다.
    // ⑵ 찾기가 닫혀 있는데 토글되면 다음에 ⌘F 를 눌렀을 때 **켠 기억이 없는 규칙**으로 검색된다.
    // ⑶ 스크롤백을 보는 중에 토글되면 그 pane 은 이 값을 안 읽으므로 **아무 일도 안 일어나는데
    // 상태만 바뀐다** — 편집기로 돌아가면 그때 규칙이 달라져 있다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const io = std.testing.io;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 12,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000);

    var dir = std.testing.tmpDir(.{});
    defer dir.cleanup();
    try dir.dir.writeFile(io, .{ .sub_path = "d.txt", .data = "id Id ID id\n" });
    var root_buf: [std.fs.max_path_bytes]u8 = undefined;
    const root = root_buf[0..try dir.dir.realPath(io, &root_buf)];
    const path = try std.fs.path.join(allocator, &.{ root, "d.txt" });
    defer allocator.free(path);
    _ = try editor_ops.openPathInActivePane(session, path);
    _ = try session.tick();

    // ⑴ **좁아지면 첫 매치로 간다.** 끝으로 clamp 되면 여기서 0 이 아니다.
    session.dispatchAppAction(.toggle_find);
    for ("id") |c| _ = try session.handleKeyEvent(.{ .key = .{ .char = c }, .modifiers = .{} });
    try std.testing.expectEqual(@as(usize, 4), session.editor_find_matches.items.len);
    session.chrome_host.find.current = 3; // 마지막 매치를 보고 있다
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'c' }, .modifiers = .{ .command = true, .option = true } });
    try std.testing.expectEqual(@as(usize, 2), session.editor_find_matches.items.len);
    try std.testing.expectEqual(@as(usize, 0), session.chrome_host.find.current);

    // ⑵ **찾기가 닫혀 있으면 무동작이다** — 열지도 않는다.
    _ = try session.handleKeyEvent(.{ .key = .escape, .modifiers = .{} });
    try std.testing.expect(!session.chrome_host.find.open);
    const before = session.chrome_host.find.match_case;
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'w' }, .modifiers = .{ .command = true, .option = true } });
    try std.testing.expect(!session.chrome_host.find.whole_word);
    try std.testing.expectEqual(before, session.chrome_host.find.match_case);
    try std.testing.expect(!session.chrome_host.find.open);

    // ⑶ **스크롤백을 보고 있으면 토글이 안 먹는다.** 편집기 타깃일 때만 뜻이 있다.
    //
    // **그때 그 chord 는 오버레이로 흘러 찾기를 닫는다** — find 컴포넌트가 `⌘·⌃·⌥+글자` 를
    // 「알 수 없는 키 = 닫기」로 다루기 때문이다. 그 자체가 계약이므로 함께 고정한다:
    // 토글이 조용히 켜지는 것보다 **닫히는 편이 낫다**(사용자가 무슨 일이 일어났는지 본다).
    session.dispatchAppAction(.toggle_find);
    session.chrome_host.find.target = .scrollback;
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'w' }, .modifiers = .{ .command = true, .option = true } });
    try std.testing.expect(!session.chrome_host.find.whole_word); // 상태는 안 바뀐다
    try std.testing.expect(!session.chrome_host.find.open); // 대신 닫혔다
}

test "EF25 규칙 토글의 가로채기가 사용자 rebind 를 따른다 — chord 모양이 아니라 액션이다 (§5.1)" {
    // **가로채기는 오버레이보다 먼저 도는 자리다**(그래야 모달이 키를 삼키기 전에 잡는다).
    // 그만큼 위험도 크다: chord **모양**(⌥ 가 붙었나 같은)으로 판정하면 사용자가 다른 키로
    // 바꿔 둔 순간 그 키는 안 먹고, 빌트인 chord 는 rebind 했는데도 계속 먹는다.
    // 그래서 `resolve` 가 **낸 액션**으로만 판정한다 — 이 판정자가 그것을 고정한다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const io = std.testing.io;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 12,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000);

    // 사용자가 **Option 없는** chord 로 바꿔 둔다 — 모양으로 판정하면 이것이 안 먹는다.
    const user_binds = [_]maru.config.keybinding.AppBinding{
        .{ .chord = .{ .modifiers = .{ .command = true, .shift = true }, .key = .{ .char = 'K' } }, .action = .toggle_find_match_case },
    };
    session.loaded_config.keybindings = &user_binds;

    var dir = std.testing.tmpDir(.{});
    defer dir.cleanup();
    try dir.dir.writeFile(io, .{ .sub_path = "d.txt", .data = "id Id ID id\n" });
    var root_buf: [std.fs.max_path_bytes]u8 = undefined;
    const root = root_buf[0..try dir.dir.realPath(io, &root_buf)];
    const path = try std.fs.path.join(allocator, &.{ root, "d.txt" });
    defer allocator.free(path);
    _ = try editor_ops.openPathInActivePane(session, path);
    _ = try session.tick();

    session.dispatchAppAction(.toggle_find);
    for ("id") |c| _ = try session.handleKeyEvent(.{ .key = .{ .char = c }, .modifiers = .{} });
    try std.testing.expectEqual(@as(usize, 4), session.editor_find_matches.items.len);

    // **사용자가 정한 키가 먹는다.**
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'k' }, .modifiers = .{ .command = true, .shift = true } });
    try std.testing.expect(session.chrome_host.find.match_case);
    try std.testing.expectEqual(@as(usize, 2), session.editor_find_matches.items.len);
}

test "EF26 선택 영역 내에서만 — 범위는 사본이라 Enter 가 파괴하지 않는다 (§5.1)" {
    // **이 판정자가 이 슬라이스의 이유다.** §5.1 은 *"현재 일치는 primary selection 을 옮긴다"* 로
    // 정해져 있다 — 그래서 「선택 안에서만」이 **살아 있는 선택**을 읽으면 첫 Enter 가 범위를
    // 그 매치 하나로 쪼그라뜨리고 두 번째 Enter 는 갈 곳이 없다. 범위를 **사본**으로 드는 것이
    // 그 충돌을 가르는 유일한 방법이고, 여기서 그것을 고정한다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const io = std.testing.io;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 12,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000);

    var dir = std.testing.tmpDir(.{});
    defer dir.cleanup();
    // `aa` 다섯 — 앞 셋만 선택 범위에 든다.
    try dir.dir.writeFile(io, .{ .sub_path = "d.txt", .data = "aa aa aa\naa aa\n" });
    var root_buf: [std.fs.max_path_bytes]u8 = undefined;
    const root = root_buf[0..try dir.dir.realPath(io, &root_buf)];
    const path = try std.fs.path.join(allocator, &.{ root, "d.txt" });
    defer allocator.free(path);
    const term = try editor_ops.openPathInActivePane(session, path);
    _ = try session.tick();

    // 첫 줄(`aa aa aa` = 0..8)을 고른다.
    term.rt.editor_selection = maru.session.editor.selection.Selection.fromPoints(0, 8);

    session.dispatchAppAction(.toggle_find);
    for ("aa") |c| _ = try session.handleKeyEvent(.{ .key = .{ .char = c }, .modifiers = .{} });
    try std.testing.expectEqual(@as(usize, 5), session.editor_find_matches.items.len); // 전체

    // **⌥⌘L — 범위 안 셋으로 좁아진다.**
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'l' }, .modifiers = .{ .command = true, .option = true } });
    try std.testing.expect(session.chrome_host.find.in_selection != null);
    try std.testing.expectEqual(@as(usize, 3), session.editor_find_matches.items.len);

    // **Enter 로 오가도 범위가 안 무너진다.** 살아 있는 선택을 읽었다면 여기서 1 이 된다.
    _ = try session.handleKeyEvent(.{ .key = .enter, .modifiers = .{} });
    _ = try session.handleKeyEvent(.{ .key = .enter, .modifiers = .{} });
    try std.testing.expectEqual(@as(usize, 3), session.editor_find_matches.items.len);

    // **끄면 전체로 돌아온다.**
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'l' }, .modifiers = .{ .command = true, .option = true } });
    try std.testing.expect(session.chrome_host.find.in_selection == null);
    try std.testing.expectEqual(@as(usize, 5), session.editor_find_matches.items.len);
}

test "EF28 범위 경계가 반열린 구간이다 — 걸친 매치는 안 든다 (§5.1)" {
    // **경계를 밟는 픽스처가 없으면 `>=`·`<=` 를 어느 쪽으로 밀어도 안 잡힌다**(변이 G1·G2).
    // 그리고 이것은 사용자에게 보이는 차이다: 선택 끝에 **반쯤 걸친** 매치를 바꾸면 고르지도
    // 않은 글자가 고쳐진다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const io = std.testing.io;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 12,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000);

    var dir = std.testing.tmpDir(.{});
    defer dir.cleanup();
    // **한 칸 차이를 만들려면 검색어가 한 글자여야 한다.** 두 글자짜리는 겹치지 않아 매치가
    // 두 칸씩 떨어지고, 그러면 `>=`/`<=` 를 한 칸 밀어도 결과가 안 바뀐다(첫 픽스처가 그랬다).
    // `aaaa` 에서 `a` 는 0..1 · 1..2 · 2..3 · 3..4 이고, 범위 **1..3** 은 가운데 둘만 담는다 —
    // `end` 를 한 칸 넘보면 3..4 가, `start` 를 한 칸 물리면 0..1 이 곧바로 들어온다.
    try dir.dir.writeFile(io, .{ .sub_path = "d.txt", .data = "aaaa\n" });
    var root_buf: [std.fs.max_path_bytes]u8 = undefined;
    const root = root_buf[0..try dir.dir.realPath(io, &root_buf)];
    const path = try std.fs.path.join(allocator, &.{ root, "d.txt" });
    defer allocator.free(path);
    const term = try editor_ops.openPathInActivePane(session, path);
    _ = try session.tick();

    term.rt.editor_selection = maru.session.editor.selection.Selection.fromPoints(1, 3);
    session.dispatchAppAction(.toggle_find);
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'a' }, .modifiers = .{} });
    try std.testing.expectEqual(@as(usize, 4), session.editor_find_matches.items.len);

    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'l' }, .modifiers = .{ .command = true, .option = true } });
    try std.testing.expectEqual(@as(usize, 2), session.editor_find_matches.items.len);
    try std.testing.expectEqual(@as(u32, 1), session.editor_find_matches.items[0].start);
    try std.testing.expectEqual(@as(u32, 2), session.editor_find_matches.items[1].start);
}

test "EF29 선택 범위 토글도 편집기 찾기일 때만 먹는다 — 팔레트 경로 포함 (§5.1)" {
    // chord 는 `findRuleChordIntercept` 가 먼저 걸러 주지만 **팔레트는 `dispatchAppAction` 으로
    // 곧장 들어온다** — 게이트가 액션 쪽에도 있어야 하고, 그것을 재는 판정자가 없으면 액션 쪽
    // 게이트를 지워도 아무도 안 잡는다(변이 G4).
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const io = std.testing.io;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 12,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000);

    var dir = std.testing.tmpDir(.{});
    defer dir.cleanup();
    try dir.dir.writeFile(io, .{ .sub_path = "d.txt", .data = "abab ab\n" });
    var root_buf: [std.fs.max_path_bytes]u8 = undefined;
    const root = root_buf[0..try dir.dir.realPath(io, &root_buf)];
    const path = try std.fs.path.join(allocator, &.{ root, "d.txt" });
    defer allocator.free(path);
    const term = try editor_ops.openPathInActivePane(session, path);
    _ = try session.tick();

    term.rt.editor_selection = maru.session.editor.selection.Selection.fromPoints(2, 4);
    session.dispatchAppAction(.toggle_find);
    for ("ab") |c| _ = try session.handleKeyEvent(.{ .key = .{ .char = c }, .modifiers = .{} });

    session.chrome_host.find.target = .scrollback;
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'l' }, .modifiers = .{ .command = true, .option = true } });
    try std.testing.expect(session.chrome_host.find.in_selection == null);

    session.dispatchAppAction(.toggle_find_in_selection); // 팔레트 경로
    try std.testing.expect(session.chrome_host.find.in_selection == null);
}

test "EF27 빈 선택이면 안 켜지고, 편집이 들어오면 범위를 버린다 (§5.1)" {
    // ⑴ 빈 선택에서 켜지면 「그 안에서만」이 문서 전체와 같은 말인데 사용자는 좁혀진 줄 안다.
    // ⑵ 편집 뒤에도 범위를 들고 있으면 굳혀 둔 offset 이 **다른 글자**를 가리킨다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const io = std.testing.io;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 12,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000);

    var dir = std.testing.tmpDir(.{});
    defer dir.cleanup();
    try dir.dir.writeFile(io, .{ .sub_path = "d.txt", .data = "aa aa aa\naa aa\n" });
    var root_buf: [std.fs.max_path_bytes]u8 = undefined;
    const root = root_buf[0..try dir.dir.realPath(io, &root_buf)];
    const path = try std.fs.path.join(allocator, &.{ root, "d.txt" });
    defer allocator.free(path);
    const term = try editor_ops.openPathInActivePane(session, path);
    _ = try session.tick();

    // ⑴ **빈 선택(caret 만)으로 열면 켤 것이 없다.** 범위는 **여는 순간** 뜨므로 그 전에 세운다.
    term.rt.editor_selection = maru.session.editor.selection.Selection.at(3);
    session.dispatchAppAction(.toggle_find);
    for ("aa") |c| _ = try session.handleKeyEvent(.{ .key = .{ .char = c }, .modifiers = .{} });
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'l' }, .modifiers = .{ .command = true, .option = true } });
    try std.testing.expect(session.chrome_host.find.in_selection == null);
    try std.testing.expectEqual(@as(usize, 5), session.editor_find_matches.items.len);

    // ⑵ **범위를 갖고 다시 열면 켜진다.** 그리고 편집이 들어오면 버린다.
    _ = try session.handleKeyEvent(.{ .key = .escape, .modifiers = .{} });
    term.rt.editor_selection = maru.session.editor.selection.Selection.fromPoints(0, 8);
    session.dispatchAppAction(.toggle_find);
    for ("aa") |c| _ = try session.handleKeyEvent(.{ .key = .{ .char = c }, .modifiers = .{} });
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'l' }, .modifiers = .{ .command = true, .option = true } });
    try std.testing.expect(session.chrome_host.find.in_selection != null);

    term.rt.editor_selection = maru.session.editor.selection.Selection.at(0);
    _ = editor_ops.insertText(session, term, "X");
    try std.testing.expect(session.chrome_host.find.in_selection == null); // 버렸다
    // **떠 둔 값도 버려야 한다.** 이것만 남기면 편집 뒤 `⌥⌘L` 이 **편집 전 offset** 으로 켜져,
    // 사용자가 고른 적 없는 자리에 검색이 갇힌다(변이 G6).
    try std.testing.expect(session.find_selection_at_open == null);

    // ⑶ **찾기를 닫으면 굳혀 둔 선택도 버린다.** 남기면 다음에 ⌘F 를 눌렀을 때 **지난번 범위**로
    // 켜져, 사용자가 고르지도 않은 자리에 검색이 갇힌다.
    //
    // 위 ⑵ 가 찾기를 **열어 둔 채** 끝났다 — 여기서 바로 토글하면 열리는 것이 아니라 닫힌다.
    _ = try session.handleKeyEvent(.{ .key = .escape, .modifiers = .{} });
    try std.testing.expect(!session.chrome_host.find.open);
    term.rt.editor_selection = maru.session.editor.selection.Selection.fromPoints(0, 8);
    session.dispatchAppAction(.toggle_find); // 열고
    try std.testing.expect(session.find_selection_at_open != null);
    session.dispatchAppAction(.toggle_find); // 닫는다
    try std.testing.expect(session.find_selection_at_open == null);
    try std.testing.expect(session.chrome_host.find.in_selection == null);

    // ⑷ **빈 선택으로 열면 그 상태가 「없음」이다** — 위 ⑴ 은 토글 결과만 봤고, 여기서는
    // **떠 둔 값 자체**를 본다(둘 다 없어야 「빈 범위면 안 켜진다」가 성립한다).
    term.rt.editor_selection = maru.session.editor.selection.Selection.at(3);
    try std.testing.expect(!session.chrome_host.find.open); // ⑶ 이 닫아 두었다
    session.dispatchAppAction(.toggle_find);
    try std.testing.expect(session.find_selection_at_open == null);
}

test "EF14 ⌥⌘F가 바꾸기 줄을 연다 — 키 경로 전체 (§5.1)" {
    // **함수를 직접 부르는 판정자만 두면 chord가 안 붙어도 전부 초록이다.** 이 저장소가 반복해
    // 당한 모양이라 여기서는 **키를 눌러** 지난다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const io = std.testing.io;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 12,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000);

    var dir = std.testing.tmpDir(.{});
    defer dir.cleanup();
    try dir.dir.writeFile(io, .{ .sub_path = "d.txt", .data = "aa NEEDLE bb\n" });
    var root_buf: [std.fs.max_path_bytes]u8 = undefined;
    const root = root_buf[0..try dir.dir.realPath(io, &root_buf)];
    const path = try std.fs.path.join(allocator, &.{ root, "d.txt" });
    defer allocator.free(path);
    const term = try editor_ops.openPathInActivePane(session, path);
    _ = try session.tick();

    // ⌘F는 한 줄 그대로다 — 평범한 찾기의 배치를 건드리지 않는 것이 설계다.
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'f' }, .modifiers = .{ .command = true } });
    try std.testing.expect(session.chrome_host.find.open);
    try std.testing.expect(!session.chrome_host.find.replace_open);
    _ = try session.handleKeyEvent(.{ .key = .escape, .modifiers = .{} });

    // ⌥⌘F가 두 줄을 연다. 포커스는 **바꿀 문자열** 쪽이다 — 그것을 치러 온 것이다.
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'f' }, .modifiers = .{ .command = true, .option = true } });
    try std.testing.expect(session.chrome_host.find.open);
    try std.testing.expect(session.chrome_host.find.replace_open);
    try std.testing.expectEqual(chrome.components.find.Focus.replace, session.chrome_host.find.focus);
    _ = term;
}

test "EF15 바꾸기 하나 — 되돌리기 하나로 풀리고 다음 매치로 간다 (§5.1·§3.3)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const io = std.testing.io;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 12,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000);

    var dir = std.testing.tmpDir(.{});
    defer dir.cleanup();
    try dir.dir.writeFile(io, .{ .sub_path = "d.txt", .data = "aa NEEDLE bb NEEDLE cc\n" });
    var root_buf: [std.fs.max_path_bytes]u8 = undefined;
    const root = root_buf[0..try dir.dir.realPath(io, &root_buf)];
    const path = try std.fs.path.join(allocator, &.{ root, "d.txt" });
    defer allocator.free(path);
    const term = try editor_ops.openPathInActivePane(session, path);
    _ = try session.tick();

    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'f' }, .modifiers = .{ .command = true, .option = true } });
    // 검색어는 **찾기 줄**에 친다 — Tab으로 옮겨 간다.
    _ = try session.handleKeyEvent(.{ .key = .tab, .modifiers = .{} });
    try std.testing.expectEqual(chrome.components.find.Focus.find, session.chrome_host.find.focus);
    for ("NEEDLE") |c| _ = try session.handleKeyEvent(.{ .key = .{ .char = c }, .modifiers = .{} });
    try std.testing.expectEqual(@as(usize, 2), session.editor_find_matches.items.len);

    _ = try session.handleKeyEvent(.{ .key = .tab, .modifiers = .{} }); // 바꿀 문자열 줄로
    for ("Z") |c| _ = try session.handleKeyEvent(.{ .key = .{ .char = c }, .modifiers = .{} });
    // **바꿀 문자열은 재검색을 부르지 않는다** — 부르면 current가 0으로 리셋돼 고른 매치를 잃는다.
    try std.testing.expectEqual(@as(usize, 2), session.editor_find_matches.items.len);

    _ = try session.handleKeyEvent(.{ .key = .enter, .modifiers = .{} }); // 바꾸기
    try std.testing.expectEqualStrings("aa Z bb NEEDLE cc\n", term.rt.editor_doc.?.file.content);

    // **다음 매치로 갔다** — 바꾼 자리를 다시 가리키면 Enter가 같은 곳을 되풀이한다.
    {
        const sel = term.rt.editor_selection.?;
        try std.testing.expectEqual(@as(usize, 8), sel.start());
        try std.testing.expectEqual(@as(usize, 14), sel.end());
    }

    // 한 번 더 → 둘 다 바뀐다.
    _ = try session.handleKeyEvent(.{ .key = .enter, .modifiers = .{} });
    try std.testing.expectEqualStrings("aa Z bb Z cc\n", term.rt.editor_doc.?.file.content);

    // **되돌리기 둘이 각각 풀린다**(바꾸기 하나 = 편집 하나).
    _ = try session.handleKeyEvent(.{ .key = .escape, .modifiers = .{} });
    try std.testing.expect(editor_ops.undoEdit(session, term));
    try std.testing.expectEqualStrings("aa Z bb NEEDLE cc\n", term.rt.editor_doc.?.file.content);
    try std.testing.expect(editor_ops.undoEdit(session, term));
    try std.testing.expectEqualStrings("aa NEEDLE bb NEEDLE cc\n", term.rt.editor_doc.?.file.content);
}

test "EF16 전부 바꾸기는 되돌리기 하나다 (§5.1·§3.3)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const io = std.testing.io;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 12,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000);

    var dir = std.testing.tmpDir(.{});
    defer dir.cleanup();
    try dir.dir.writeFile(io, .{ .sub_path = "d.txt", .data = "x1\nAB y AB\nz AB\n" });
    var root_buf: [std.fs.max_path_bytes]u8 = undefined;
    const root = root_buf[0..try dir.dir.realPath(io, &root_buf)];
    const path = try std.fs.path.join(allocator, &.{ root, "d.txt" });
    defer allocator.free(path);
    const term = try editor_ops.openPathInActivePane(session, path);
    _ = try session.tick();

    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'f' }, .modifiers = .{ .command = true, .option = true } });
    _ = try session.handleKeyEvent(.{ .key = .tab, .modifiers = .{} });
    for ("AB") |c| _ = try session.handleKeyEvent(.{ .key = .{ .char = c }, .modifiers = .{} });
    try std.testing.expectEqual(@as(usize, 3), session.editor_find_matches.items.len);
    _ = try session.handleKeyEvent(.{ .key = .tab, .modifiers = .{} });
    for ("QQ") |c| _ = try session.handleKeyEvent(.{ .key = .{ .char = c }, .modifiers = .{} });

    // ⌘Enter = 전부 바꾸기.
    _ = try session.handleKeyEvent(.{ .key = .enter, .modifiers = .{ .command = true } });
    try std.testing.expectEqualStrings("x1\nQQ y QQ\nz QQ\n", term.rt.editor_doc.?.file.content);

    // **셋이 한 번에 되돌아간다.** 셋이면 사용자는 "전부 바꾸기를 취소"할 수 없다.
    _ = try session.handleKeyEvent(.{ .key = .escape, .modifiers = .{} });
    try std.testing.expect(editor_ops.undoEdit(session, term));
    try std.testing.expectEqualStrings("x1\nAB y AB\nz AB\n", term.rt.editor_doc.?.file.content);
}

test "EF17 바꿀 문자열이 검색어를 품어도 되풀이하지 않는다 (§5.1)" {
    // `a` → `aa`가 고전적인 자리다. 하나씩 바꾸며 다시 찾는 구현은 **끝나지 않는다**.
