test "EF21 두 입력의 IME 조합은 서로 독립이다 (§5.1)" {
    // §5.1이 *"두 입력 사이 포커스 이동(Tab)과 IME 조합이 각각 독립이어야 한다"*고 **명시**한 자리다.
    // 조합을 검색어 칸에 고정해 두면 바꿀 문자열을 한글로 치는 동안 글자가 **위 줄에 쌓인다**.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const io = std.testing.io;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 12,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000);

    var dir = std.testing.tmpDir(.{});
    defer dir.cleanup();
    try dir.dir.writeFile(io, .{ .sub_path = "d.txt", .data = "\xea\xb0\x80 x\n" });
    var root_buf: [std.fs.max_path_bytes]u8 = undefined;
    const root = root_buf[0..try dir.dir.realPath(io, &root_buf)];
    const path = try std.fs.path.join(allocator, &.{ root, "d.txt" });
    defer allocator.free(path);
    _ = try editor_ops.openPathInActivePane(session, path);
    _ = try session.tick();

    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'f' }, .modifiers = .{ .command = true, .option = true } });
    try std.testing.expect(session.chrome_host.find.replaceActive());
    try std.testing.expectEqual(chrome.components.find.Focus.replace, session.chrome_host.find.focus);

    // 바꿀 문자열 줄에서 조합 "나" → 확정 → 다음 조합 "다".
    input_ops.imeBegin(session);
    input_ops.imeMarked(session, "\xeb\x82\x98");
    input_ops.imeInsert(session, "\xeb\x82\x98");
    input_ops.imeMarked(session, "\xeb\x8b\xa4");
    input_ops.imeEnd(session, null);

    // **바꿀 문자열 쪽에만** 쌓인다. 검색어는 손대지 않은 그대로여야 한다.
    try std.testing.expectEqualStrings("\xeb\x82\x98", session.chrome_host.find.replace.query.items);
    try std.testing.expectEqualStrings("\xeb\x8b\xa4", session.chrome_host.find.replace.preedit.items);
    try std.testing.expectEqual(@as(usize, 0), session.chrome_host.find.input.query.items.len);
    try std.testing.expectEqual(@as(usize, 0), session.chrome_host.find.input.preedit.items.len);

    // Tab으로 옮기면 이번엔 검색어 쪽이 받는다 — 조합 버퍼가 서로 안 섞인다.
    _ = try session.handleKeyEvent(.{ .key = .tab, .modifiers = .{} });
    input_ops.imeBegin(session);
    input_ops.imeMarked(session, "\xea\xb0\x80");
    input_ops.imeEnd(session, null);
    try std.testing.expectEqualStrings("\xeb\x8b\xa4", session.chrome_host.find.replace.preedit.items); // 그대로
}

test "IME6 포커스를 잃으면 편집기 조합이 확정된다 — 유령 글자가 안 남는다 (N3)" {
    // **편집기 조합은 코어에 없다.** 확정 경로가 sentinel 코어만 보면 "확정할 것 없음"으로 답하고
    // 고정만 푸는데, 그러면 화면에 그려지던 조합 글자가 **영영 남는다**(적대적 검증 2026-08-27).
    // Terminal.app·Ghostty 의미론대로 **확정**한다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const io = std.testing.io;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 12,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000);

    var dir = std.testing.tmpDir(.{});
    defer dir.cleanup();
    try dir.dir.writeFile(io, .{ .sub_path = "d.txt", .data = "ab\n" });
    var root_buf: [std.fs.max_path_bytes]u8 = undefined;
    const root = root_buf[0..try dir.dir.realPath(io, &root_buf)];
    const path = try std.fs.path.join(allocator, &.{ root, "d.txt" });
    defer allocator.free(path);
    const term = try editor_ops.openPathInActivePane(session, path);
    _ = try session.tick();
    term.rt.editor_selection = maru.session.editor.selection.Selection.at(1);

    input_ops.imeBegin(session);
    input_ops.imeMarked(session, "\xed\x95\x9c"); // 조합 "한"
    try std.testing.expectEqual(@as(usize, 3), term.rt.editor_preedit.len);
    try std.testing.expect(input_ops.imeComposingActive(session)); // 조합 중으로 보고한다

    session.setFocused(false); // 앱 전환

    // 조합은 **문서로 확정**되고 화면 상태는 비었다.
    try std.testing.expectEqual(@as(usize, 0), term.rt.editor_preedit.len);
    try std.testing.expectEqualStrings("a\xed\x95\x9cb\n", term.rt.editor_doc.?.file.content);
}

test "EF10 모달이 강조를 멎게 해도 ⌘G는 이어진다 — `find_nav`를 내리는 대가의 크기" {
    // **이것이 트레이드오프의 크기를 재는 판정자다.** `clearAllFindMatches`가 `find_nav`를 내리는
    // 탓에 **비동기 토스트·확인 모달**(`showNotice`/`showConfirm` 호출자 66곳이 전부
    // `dismissMessageOverlays`를 지난다)이 ⌘G 세션을 끝낸다. 4라운드 검증이 그것을 지적했다.
    //
    // **반대로 하면 더 나쁘다** — 실험으로 확인했다: `find_nav`를 안 내리면 다음 tick이 목록을
    // 되살리고 `current`를 0으로 리셋해 **뷰가 맨 위로 튄다**(`EF6`이 `expected 276, found 0`으로
    // 잡는다). 1라운드 R7이 잡았던 그 실패다.
    //
    // 그래서 남는 질문은 **"⌘G 세션이 끝나면 사용자가 무엇을 잃는가"**이고, 답은 **강조뿐**이다:
    // 검색어와 현재 위치는 `clearAllFindMatches`가 안 건드리므로 다음 ⌘G가 그 자리에서 이어간다.
    // 이 판정자가 그 사실을 고정한다 — 그것이 깨지면 트레이드오프의 크기가 달라진다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const io = std.testing.io;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 12,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000);

    var dir = std.testing.tmpDir(.{});
    defer dir.cleanup();
    try dir.dir.writeFile(io, .{ .sub_path = "d.txt", .data = "MARUFIND a\nMARUFIND b\nMARUFIND c\n" });
    var root_buf: [std.fs.max_path_bytes]u8 = undefined;
    const root = root_buf[0..try dir.dir.realPath(io, &root_buf)];
    const path = try std.fs.path.join(allocator, &.{ root, "d.txt" });
    defer allocator.free(path);
    _ = try editor_ops.openPathInActivePane(session, path);

    session.dispatchAppAction(.toggle_find);
    for ("MARUFIND") |c| _ = try session.handleKeyEvent(.{ .key = .{ .char = c }, .modifiers = .{} });
    _ = try session.tick();
    try std.testing.expectEqual(@as(usize, 3), session.editor_find_matches.items.len);

    // 둘째 매치로 옮기고 닫는다.
    _ = try session.handleKeyEvent(.{ .key = .enter, .modifiers = .{} });
    try std.testing.expectEqual(@as(usize, 1), session.chrome_host.find.current);
    _ = try session.handleKeyEvent(.{ .key = .escape, .modifiers = .{} });

    // **비동기 토스트가 뜬다** — ⌘G 세션이 끝나고 강조가 멎는다(그것이 이 설계의 대가다).
    session.showNotice("something happened");
    try std.testing.expect(!session.find_nav);
    try std.testing.expectEqual(@as(usize, 0), session.editor_find_matches.items.len);

    // **그러나 검색어와 위치는 살아 있다.** ⌘G가 그 자리에서 이어간다 — 처음으로 안 돌아간다.
    try std.testing.expectEqual(@as(usize, 8), session.chrome_host.find.input.query.items.len);
    try std.testing.expectEqual(@as(usize, 1), session.chrome_host.find.current);
    session.dispatchAppAction(.find_next);
    try std.testing.expectEqual(@as(usize, 3), session.editor_find_matches.items.len); // 다시 찾았다
    try std.testing.expectEqual(@as(usize, 2), session.chrome_host.find.current); // 1 → 2, 0이 아니다
    try std.testing.expect(session.find_nav);
}

test "find ⌘G/⌘⇧G: 오버레이 닫힌 채 다음/이전 매치 네비(보존 검색어 재검색·타이핑이 종료)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // 실 PTY(controlled_smoke)
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 6,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000);
    try term_ops.activeSurface(session).core.write("MARUFIND one\r\ntwo MARUFIND three\r\nMARUFIND four"); // 3곳 매치

    // 검색: 열고 타이핑 → 3곳 매치, 현재 0.
    session.dispatchAppAction(.toggle_find);
    for ("MARUFIND") |c| _ = try session.handleKeyEvent(.{ .key = .{ .char = c }, .modifiers = .{} });
    try std.testing.expectEqual(@as(usize, 3), session.find_matches.items.len);
    try std.testing.expectEqual(@as(usize, 0), session.chrome_host.find.current);

    // Esc로 닫기 — 매치 정리, 검색어 보존, find_nav false.
    _ = try session.handleKeyEvent(.{ .key = .escape, .modifiers = .{} });
    try std.testing.expect(!session.chrome_host.find.open);
    try std.testing.expectEqual(@as(usize, 0), session.find_matches.items.len);
    try std.testing.expect(!session.find_nav);
    try std.testing.expect(session.chrome_host.find.input.query.items.len > 0); // 검색어 보존(hide는 안 비움)

    // ⌘G(닫힌 채): 보존 검색어로 재검색 + 다음 매치(0→1) + find_nav 세움.
    session.dispatchAppAction(.find_next);
    try std.testing.expect(session.find_nav);
    try std.testing.expectEqual(@as(usize, 3), session.find_matches.items.len);
    try std.testing.expectEqual(@as(usize, 1), session.chrome_host.find.current);
    try std.testing.expect(!session.chrome_host.find.open); // 오버레이는 여전히 닫힘

    // ⌘G 두 번 더 → 2 → 0(wrap).
    session.dispatchAppAction(.find_next);
    try std.testing.expectEqual(@as(usize, 2), session.chrome_host.find.current);
    session.dispatchAppAction(.find_next);
    try std.testing.expectEqual(@as(usize, 0), session.chrome_host.find.current);

    // ⌘⇧G(이전) → 2(뒤로 wrap).
    session.dispatchAppAction(.find_previous);
    try std.testing.expectEqual(@as(usize, 2), session.chrome_host.find.current);

    // 닫힌 채 네비 중 tick 프레임 빌드가 크래시 없이 동작(현재 매치만 하이라이트 — cell_colors 경로).
    _ = try session.tick();

    // 셸에 타이핑 재개 = 검색 종료 → find_nav 해제 + 매치 정리.
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'x' }, .modifiers = .{} });
    try std.testing.expect(!session.find_nav);
    try std.testing.expectEqual(@as(usize, 0), session.find_matches.items.len);

    // 빈 검색어면 ⌘G 무동작(새로 열어 show가 검색어를 비우고, 닫은 뒤 find_next).
    session.dispatchAppAction(.toggle_find); // show → query clear
    _ = try session.handleKeyEvent(.{ .key = .escape, .modifiers = .{} });
    session.dispatchAppAction(.find_next);
    try std.testing.expect(!session.find_nav); // 검색어 없음 — 무동작
}

test "alt screen에서도 maru Find가 열린다(⌘F 동작·진입해도 tick이 안 닫음 — 현재 화면 검색)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // 실 PTY
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 6,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000);

    // 메인 화면: ⌘F가 Find를 연다(정상).
    session.dispatchAppAction(.toggle_find);
    try std.testing.expect(session.chrome_host.find.open);
    session.dispatchAppAction(.toggle_find); // 닫기
    try std.testing.expect(!session.chrome_host.find.open);

    // alt screen 진입(DECSET 1049 — vim/less/Claude/Codex).
    try term_ops.activeSurface(session).core.write("\x1b[?1049h");
    try std.testing.expect(term_ops.activeSurface(session).core.alt_active);

    // alt에서도 ⌘F가 Find를 연다 — alt에선 findMatches가 현재 화면만 검색한다(과거엔 iTerm2 관례로 막았음).
    session.dispatchAppAction(.toggle_find);
    try std.testing.expect(session.chrome_host.find.open);
    session.dispatchAppAction(.toggle_find); // 닫기
    try std.testing.expect(!session.chrome_host.find.open);

    // 엣지: 메인에서 Find를 연 뒤 앱이 출력으로 alt에 들어가도 tick이 Find를 닫지 않는다(현재 화면 검색 유지).
    try term_ops.activeSurface(session).core.write("\x1b[?1049l"); // 메인 복귀
    try std.testing.expect(!term_ops.activeSurface(session).core.alt_active);
    session.dispatchAppAction(.toggle_find);
    try std.testing.expect(session.chrome_host.find.open); // 메인에선 열림
    try term_ops.activeSurface(session).core.write("\x1b[?1049h"); // 앱이 alt 진입
    _ = try session.tick();
    try std.testing.expect(session.chrome_host.find.open); // tick이 닫지 않음(유지)
}

test "alt screen Find: 실제 쿼리가 현재 화면만 매치하고 ⌘G가 동작한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // 실 PTY(controlled_smoke)
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 6,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000);

    // primary 스크롤백에 needle "MARUHIT"를 출력한 뒤 화면(6행) 밖으로 밀어낸다(대조군 — alt에선 제외돼야).
    try term_ops.activeSurface(session).core.write("MARUHIT primary\r\n");
    var i: usize = 0;
    while (i < 10) : (i += 1) try term_ops.activeSurface(session).core.write("pad\r\n");

    // alt 진입 + alt 화면에 needle 한 곳.
    try term_ops.activeSurface(session).core.write("\x1b[?1049h");
    try std.testing.expect(term_ops.activeSurface(session).core.alt_active);
    try term_ops.activeSurface(session).core.write("MARUHIT alt line");

    // Find 열고 "MARUHIT" 타이핑 → recompute가 현재 화면(alt)만 스캔해 1곳 매치(primary 스크롤백 제외).
    session.dispatchAppAction(.toggle_find);
    try std.testing.expect(session.chrome_host.find.open);
    for ("MARUHIT") |c| _ = try session.handleKeyEvent(.{ .key = .{ .char = c }, .modifiers = .{} });
    try std.testing.expectEqual(@as(usize, 1), session.find_matches.items.len); // alt 화면 1곳만(스크롤백 제외)

    // ⌘G(오버레이 닫힌 채): alt에서도 findNavigate가 동작한다(과거엔 무동작이었음) — 보존 검색어 재검색 + find_nav.
    _ = try session.handleKeyEvent(.{ .key = .escape, .modifiers = .{} }); // 닫기(검색어 보존)
    try std.testing.expect(!session.chrome_host.find.open);
    session.dispatchAppAction(.find_next);
    try std.testing.expect(session.find_nav); // alt에서 ⌘G 동작(억제 안 됨)
    try std.testing.expectEqual(@as(usize, 1), session.find_matches.items.len);
}

test "find IME 멀티-문자: 커밋이 다음 조합 preedit를 안 지운다(조합 안 보임 회귀)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // handleKeyEvent → chrome 라우팅, 실 PTY
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 6,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000);

    session.dispatchAppAction(.toggle_find);
    try std.testing.expect(session.chrome_host.find.open);

    // 실제 IME 흐름(라이브 로그와 동일): setMarkedText "나" → insertText "나"(커밋) → setMarkedText "다"(다음 조합).
    // 한 keyDown 트랜잭션 안에서 일어난다.
    input_ops.imeBegin(session);
    input_ops.imeMarked(session, "\xeb\x82\x98"); // 조합 "나"
    input_ops.imeInsert(session, "\xeb\x82\x98"); // "나" 커밋 누적
    input_ops.imeMarked(session, "\xeb\x8b\xa4"); // 다음 조합 "다"
    input_ops.imeEnd(session, null);

    // 커밋 "나"는 검색어로, 조합 "다"는 preedit로 **유지**돼야 한다. 예전엔 imeEnd의 커밋(appendChar)이 방금 set된
    // "다"를 지워 조합이 화면에서 사라졌다(사용자 제보 "입력중 상태 안 보임"). 단일 출처·core 모델 통일로 수정.
    try std.testing.expectEqualStrings("\xeb\x82\x98", session.chrome_host.find.input.query.items); // "나" 확정
    try std.testing.expectEqualStrings("\xeb\x8b\xa4", session.chrome_host.find.input.preedit.items); // "다" 조합 유지
}

test "오버레이 배타 + IME 단일 출처: showNotice가 find/palette를 닫고 notice가 최우선(IME 무시)·toggle이 notice를 닫음" {
    // 경량 — show/toggle·inputFocus·IME 헬퍼만 탄다(CoreText/PTY 불필요). undefined 세션은 이들이 읽는 필드만 초기화.
    var session: AppSession = undefined;
    session.allocator = std.testing.allocator;
    session.chrome_host = .{}; // inputFocus가 notice/find/palette.open을 읽음([[devsession-undefined-test-field-trap]])
    session.rename = null; // inputFocus가 rename을 읽음([[devsession-undefined-test-field-trap]])
    session.addr_edit = null; // 7e-2b: inputFocus가 addr_edit을 읽음([[devsession-undefined-test-field-trap]])
    session.sidebar_search_active = false;
    session.focus_owner = .workspace; // inputFocus가 file-tree owner를 읽음([[devsession-undefined-test-field-trap]])
    session.find_matches = .empty; // toggleFind/showNotice가 clearRetainingCapacity 호출
    // **검색 목록은 둘이다**(§5.1). `clearAllFindMatches`가 편집기 쪽도 비우므로 이 필드가
    // undefined면 `0xaaaa…`를 역참조해 **세그폴트**가 난다 — 실제로 났고, `FAIL`만 찾던 눈이
    // "Segmentation fault"를 놓쳐 한 커밋이 그대로 밀렸다([[devsession-undefined-test-field-trap]]).
    session.editor_find_matches = .empty;
    session.editor_find_source = 0;
    session.find_nav = false; // `clearAllFindMatches`가 내린다 — undefined면 그 대입이 의미를 잃는다
    session.palette_filtered = .empty; // togglePalette→recomputePalette가 채운다
    session.pending_confirm = .none; // showNotice→cancelPendingClose가 읽음([[devsession-undefined-test-field-trap]])
    session.metal_dirty = false;
    session.ime_terminal_target_id = null; // IME 라우팅이 pin 유무를 먼저 읽음([[devsession-undefined-test-field-trap]])
    session.file_content_menu = null; // showNotice→closeContextMenu가 읽음([[devsession-undefined-test-field-trap]])
    defer {
        session.chrome_host.deinit(std.testing.allocator);
        session.find_matches.deinit(std.testing.allocator);
        session.editor_find_matches.deinit(std.testing.allocator);
        session.palette_filtered.deinit(std.testing.allocator);
    }

    // 오버레이 없음 → terminal
    try std.testing.expectEqual(AppSession.InputFocus.terminal, session.inputFocus());

    // find 열림 → .find
    session.toggleFind();
    try std.testing.expect(session.chrome_host.find.open);
    try std.testing.expectEqual(AppSession.InputFocus.find, session.inputFocus());

    // showNotice가 find를 닫는다(#2 배타) — notice가 최우선 포커스(#3)
    session.showNotice("corrupt");
    try std.testing.expect(session.chrome_host.notice.open);
    try std.testing.expect(!session.chrome_host.find.open); // #2: 두 박스가 합쳐진 frame으로 안 깨짐
    try std.testing.expectEqual(AppSession.InputFocus.notice, session.inputFocus()); // #3: 최우선
    // #3: notice 중 IME 연산은 무시 — 조합이 뒤(find/터미널)로 새지 않는다
    input_ops.imeSetPreedit(&session, "\xea\xb0\x80"); // "가"
    try std.testing.expect(!input_ops.imeComposingActive(&session));

    // toggleFind가 notice를 닫는다(#2)
    session.toggleFind();
    try std.testing.expect(!session.chrome_host.notice.open); // #2
    try std.testing.expect(session.chrome_host.find.open);

    // togglePalette가 notice·find를 닫는다(#2) → palette 포커스
    session.showNotice("corrupt2");
    try std.testing.expect(!session.chrome_host.find.open); // showNotice가 find도 닫음
    session.togglePalette();
    try std.testing.expect(!session.chrome_host.notice.open); // #2
    try std.testing.expect(session.chrome_host.palette.open);
    try std.testing.expectEqual(AppSession.InputFocus.palette, session.inputFocus());
}

test "IME 라우팅: 세팅 모달 열림이면 inputFocus=.settings이라 조합/확정 텍스트가 검색줄로(터미널로 안 샘)" {
    // 경량 — inputFocus/IME preedit·compose만 탄다(CoreText/PTY 불필요). undefined 세션은 이들이 읽는 필드만 초기화.
    var session: AppSession = undefined;
    session.allocator = std.testing.allocator;
    session.chrome_host = .{}; // inputFocus가 settings/notice/find/palette.open을 읽음([[devsession-undefined-test-field-trap]])
    session.rename = null; // inputFocus가 rename을 읽음
    session.addr_edit = null; // 7e-2b: inputFocus가 addr_edit을 읽음([[devsession-undefined-test-field-trap]])
    session.sidebar_search_active = false; // inputFocus가 읽음(설정 안 하면 UB로 .sidebar_search 오판)
    session.focus_owner = .workspace; // inputFocus가 file-tree owner를 읽음([[devsession-undefined-test-field-trap]])
    session.find_matches = .empty;
    session.palette_filtered = .empty;
    session.metal_dirty = false;
    session.ime_terminal_target_id = null; // IME 라우팅이 pin 유무를 먼저 읽음([[devsession-undefined-test-field-trap]])
    defer {
        session.chrome_host.deinit(std.testing.allocator);
        session.find_matches.deinit(std.testing.allocator);
        session.palette_filtered.deinit(std.testing.allocator);
    }

    // 세팅 안 열림 → terminal.
    try std.testing.expectEqual(AppSession.InputFocus.terminal, session.inputFocus());

    // 세팅 모달 열림 → .settings. 이게 핵심 — 예전엔 inputFocus에 settings가 없어 macOS 확정 텍스트가 .terminal로
    // 라우팅돼 검색어가 뒤 터미널로 샜다(검색 입력이 안 되던 근본 원인). 회귀 가드.
    session.chrome_host.settings.show();
    session.chrome_host.settings.startSearch();
    try std.testing.expectEqual(AppSession.InputFocus.settings, session.inputFocus());

    // IME 조합(marked)이 세팅 검색 preedit로 들어간다(뒤 터미널/find로 안 샘) — imeComposingActive도 반영.
    input_ops.imeSetPreedit(&session, "\xea\xb0\x80"); // "가"
    try std.testing.expect(input_ops.imeComposingActive(&session));
    try std.testing.expectEqualStrings("\xea\xb0\x80", session.chrome_host.settings.searchPreedit());
    // 조합 해제(빈 bytes) → 조합 없음.
    input_ops.imeSetPreedit(&session, "");
    try std.testing.expect(!input_ops.imeComposingActive(&session));
}

test "imeBegin: 터미널 포커스만 바닥으로 스냅 — find 조합은 뒤 터미널 스크롤백을 보존(#4)" {
    var session: AppSession = undefined;
    session.allocator = std.testing.allocator;
    var tab_surface = try maru.session.Surface.init(std.testing.allocator, 1, .{ .cols = 4, .rows = 5 });
    defer tab_surface.deinit();
    session.surface_initialized = true;
    var st_ptrs = [_]*maru.session.Surface{&tab_surface};
    session.app_window = .{ .tabs = &st_ptrs };
    var test_rt: app.SurfaceRuntime = undefined;
    try attachTestRuntime(&session, &test_rt, &tab_surface);
    defer session.runtime.deinit();
    session.metal_dirty = false;
    session.chrome_host = .{}; // inputFocus가 읽음
    session.rename = null; // inputFocus가 rename을 읽음([[devsession-undefined-test-field-trap]])
    session.addr_edit = null; // 7e-2b: inputFocus가 addr_edit을 읽음([[devsession-undefined-test-field-trap]])
    session.sidebar_search_active = false;
    session.focus_owner = .workspace; // inputFocus가 file-tree owner를 읽음([[devsession-undefined-test-field-trap]])
    session.tabs = .empty; // [4e-2] scrollPage 게이트 activeTermIsTerminal이 tabs를 읽음 — 빈 트리=terminal 취급(byte-identical)
    session.ime_inserted = .empty; // imeBegin이 clearRetainingCapacity 호출
    session.ime_terminal_target_id = null; // imeBegin이 pin 유무를 먼저 읽음([[devsession-undefined-test-field-trap]])
    session.ime_terminal_target_tombstoned = false;
    defer session.chrome_host.deinit(std.testing.allocator);
    defer session.ime_inserted.deinit(std.testing.allocator);

    // 9줄 출력 → 5행 화면 위로 4줄 스크롤백
    try tab_surface.core.write("1\r\n2\r\n3\r\n4\r\n5\r\n6\r\n7\r\n8\r\n9");
    scroll_ops.scrollPage(&session, 1); // 위로 한 화면
    try std.testing.expectEqual(@as(usize, 4), tab_surface.core.view_offset);

    // (a) 터미널 포커스: imeBegin이 바닥으로 스냅한다(조합도 타이핑 — preedit이 보이게)
    input_ops.imeBegin(&session);
    try std.testing.expectEqual(@as(usize, 0), tab_surface.core.view_offset);
    input_ops.imeEnd(&session, null); // 실제 keyDown처럼 트랜잭션을 닫아 terminal pin을 해제한다.

    // 다시 위로 스크롤
    scroll_ops.scrollPage(&session, 1);
    try std.testing.expectEqual(@as(usize, 4), tab_surface.core.view_offset);

    // (b) find 포커스: imeBegin은 뒤 터미널을 건드리지 않는다(#4 — 조합은 find 입력칸으로 간다)
    session.chrome_host.find.open = true;
    input_ops.imeBegin(&session);
    try std.testing.expectEqual(@as(usize, 4), tab_surface.core.view_offset); // 보존
}

test "find overlay: 한글(wide)은 atlas slot이 2칸 — ㄱㄴㄷ 잘림 회귀 실측(실 CoreText)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // buildChromeOverlayFrame=CoreText, 실 PTY
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 6,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    session.dispatchAppAction(.toggle_find);
    try std.testing.expect(session.chrome_host.find.open);
    // 'A'(ASCII, span 1)와 '가'(U+AC00, EAW-Wide span 2)를 같은 오버레이 frame에 그린다.
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'A' }, .modifiers = .{} });
    _ = try session.handleKeyEvent(.{ .key = .{ .char = '가' }, .modifiers = .{} });

    // scale 1.0과 Retina 2.0 둘 다 검증 — 실제 맥 화면은 2.0이라 1.0만으론 라이브 경로(오버레이 셀 × scale)를
    // 못 잡는다. 같은 세션에서 resize를 반복해 공유 atlas가 두 메트릭을 함께 들었을 때도 잘림이 없는지 본다.
    for ([_]u32{ 1000, 2000 }) |scale_milli| {
        _ = try session.resize(800, 600, scale_milli);
        var ff = try testBuildChromeOverlayFrame(session);
        defer ff.frame.deinit(allocator);

        // caret 재활용: cursor-role fill이 **cursor 오버레이**(glyph_quad_frame.overlays의 .cursor, visible)로 lower돼야
        // 한다 — buildNativeCellsSplit이 이걸 반전-블록으로 그리고 suffix-trim으로 깜빡인다. draw_list.cursor 필드만으론
        // 안 그려진다(렌더는 overlays를 본다). 회귀: caret이 안 보이던 버그(overlays 누락) 고정.
        var has_caret = false;
        for (ff.frame.glyph_quad_frame.overlays) |ov| {
            if (ov == .cursor and ov.cursor.visible) has_caret = true;
        }
        try std.testing.expect(has_caret);

        // 실측: 결과 글리프에서 '가'와 'A'의 cell_width(span)와 atlas slot 픽셀 폭을 뽑는다.
        var ga_span: ?u3 = null;
        var ga_slot_w: u32 = 0;
        var a_slot_w: u32 = 0;
        for (ff.frame.glyph_quad_frame.glyphs) |q| {
            if (q.run.codepoint == '가') {
                ga_span = q.run.cell_width;
                ga_slot_w = q.slot.width_px;
            } else if (q.run.codepoint == 'A') {
                a_slot_w = q.slot.width_px;
            }
        }
        // 핵심: '가'는 span=2여야 하고, atlas slot이 ASCII(span 1)의 2배 폭이어야 wide 글리프가 안 잘린다.
        // slot이 1칸이면 rasterizer가 글자를 1칸에 가운데정렬+우측 클립해 왼쪽 절반(ㄱ)만 남는다.
        try std.testing.expectEqual(@as(?u3, 2), ga_span);
        try std.testing.expect(a_slot_w > 0);
        try std.testing.expectEqual(a_slot_w * 2, ga_slot_w);
    }
}

test "command palette(chrome): 한글(wide) query는 atlas slot이 2칸 — ㄱㄴㄷ 잘림 회귀 실측(실 CoreText)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // buildChromeOverlayFrame=CoreText, 실 PTY
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 6,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    session.dispatchAppAction(.toggle_command_palette);
    try std.testing.expect(session.chrome_host.palette.open);
    // 'A'(ASCII, span 1)와 '가'(U+AC00, span 2)를 팝업 쿼리에 입력 — row0 프롬프트 "> A가"로 그려진다(필터 결과는
    // 0이어도 쿼리 글리프는 frame에 있다). C1b 전 팝업(putUtf8 span=1)이면 '가'가 1칸 slot에 잘렸다.
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'A' }, .modifiers = .{} });
    _ = try session.handleKeyEvent(.{ .key = .{ .char = '가' }, .modifiers = .{} });

    // scale 1.0·Retina 2.0 둘 다(실제 맥은 2.0).
    for ([_]u32{ 1000, 2000 }) |scale_milli| {
        _ = try session.resize(800, 600, scale_milli);
        var ff = try testBuildChromeOverlayFrame(session);
        defer ff.frame.deinit(allocator);

        // caret 재활용: cursor-role fill이 cursor 오버레이(glyph_quad_frame.overlays의 .cursor, visible)로 lower돼 터미널
        // 커서와 같은 반전-블록 경로로 그려지고 깜빡인다(draw_list.cursor 필드만으론 안 그려짐 — 회귀 고정).
        var has_caret = false;
        for (ff.frame.glyph_quad_frame.overlays) |ov| {
            if (ov == .cursor and ov.cursor.visible) has_caret = true;
        }
        try std.testing.expect(has_caret);

        var ga_span: ?u3 = null;
        var ga_slot_w: u32 = 0;
        var a_slot_w: u32 = 0;
        for (ff.frame.glyph_quad_frame.glyphs) |q| {
            if (q.run.codepoint == '가') {
                ga_span = q.run.cell_width;
                ga_slot_w = q.slot.width_px;
            } else if (q.run.codepoint == 'A') {
                a_slot_w = q.slot.width_px;
            }
        }
        try std.testing.expectEqual(@as(?u3, 2), ga_span); // 팝업 '가'도 span=2(find와 같은 경로)
        try std.testing.expect(a_slot_w > 0);
        try std.testing.expectEqual(a_slot_w * 2, ga_slot_w); // 2칸 slot — 안 잘림
    }
}

test "rasterizeOverlayCells: 다중 fill(painter order) + 다중 행 text → 셀 그리드(헤드리스)" {
    const allocator = std.testing.allocator;
    const c = struct {
        fn rgb(r: u8, g: u8, b: u8) maru.color.Rgb {
            return .{ .r = r, .g = g, .b = b };
        }
    };
    // 2색이 구분되게 토큰을 만든다: surface_bg=(2,2,2), selection=(7,7,7).
    const tk = chrome.tokens.Tokens.base(.{
        .diff_added = .{ .r = 64, .g = 160, .b = 64 }, // 픽스처: 비교 밴드 입력(§7)
        .diff_removed = .{ .r = 176, .g = 64, .b = 64 },
        .foreground = c.rgb(1, 1, 1),
        .sidebar_background = c.rgb(2, 2, 2),
        .sidebar_foreground = c.rgb(3, 3, 3),
        .sidebar_active = c.rgb(4, 4, 4),
        .search_match = c.rgb(5, 5, 5),
        .search_match_current = c.rgb(6, 6, 6),
        .selection = c.rgb(7, 7, 7),
        .cursor = c.rgb(8, 8, 8),
        .terminal_background = c.rgb(8, 8, 8), // 픽스처: 터미널 배경 입력(§4.1b terminal_bg)
        .accent = c.rgb(9, 9, 9),
    });
    // cw=10, ch=20. 패널 2칸×2행(0,0,20,40). row1만 selection으로 덮고(painter order), 각 행에 텍스트.
    const run_ab = [_]chrome.draw.Run{.{ .text = "ab" }};
    const run_cd = [_]chrome.draw.Run{.{ .text = "cd" }};
    const ops = [_]chrome.draw.Op{
        .{ .fill = .{ .rect = .{ .x = 0, .y = 0, .w = 20, .h = 40 }, .role = .surface_bg } },
        .{ .fill = .{ .rect = .{ .x = 0, .y = 20, .w = 20, .h = 20 }, .role = .selection } },
        .{ .text = .{ .origin = .{ .x = 0, .y = 0 }, .runs = &run_ab, .role = .surface_fg } },
        .{ .text = .{ .origin = .{ .x = 0, .y = 20 }, .runs = &run_cd, .role = .surface_fg } },
    };
    const draws = [_]chrome.ChromeDraw{.{ .layer = .modal, .ops = &ops }};

    var raster = try AppSession.rasterizeOverlayCells(allocator, &draws, &tk, 10, 20, false);
    defer raster.cells.deinit(allocator);
    defer raster.gpu_quads.deinit(allocator);
    defer raster.gpu_shadows.deinit(allocator);

    try std.testing.expectEqual(@as(u16, 2), raster.cols);
    try std.testing.expectEqual(@as(u16, 2), raster.rows);
    try std.testing.expectEqual(@as(u32, 0), raster.origin_x);
    try std.testing.expectEqual(@as(u32, 0), raster.origin_y);
    try std.testing.expectEqual(@as(usize, 4), raster.cells.items.len);
    // 행 0: "ab" + surface_bg, 행 1: "cd" + selection(나중 fill이 이김).
    try std.testing.expectEqual(@as(u21, 'a'), raster.cells.items[0].codepoint);
    try std.testing.expectEqual(@as(u21, 'b'), raster.cells.items[1].codepoint);
    try std.testing.expectEqual(@as(u21, 'c'), raster.cells.items[2].codepoint);
    try std.testing.expectEqual(@as(u21, 'd'), raster.cells.items[3].codepoint);
    try std.testing.expectEqual(c.rgb(2, 2, 2), raster.cells.items[0].style.background.rgb); // row0 surface_bg
    try std.testing.expectEqual(c.rgb(7, 7, 7), raster.cells.items[2].style.background.rgb); // row1 selection(painter order)
}

// 셀보다 얇은 fill(구분선·inset 버튼 배경)은 **셀 배경이 아니라 GPU quad**로 나가야 한다.
//
// `paintRectBg`는 픽셀 rect를 `trunc(y/ch) .. trunc((y+h)/ch)` 행 범위로 내린다. 그래서 1px 구분선은 위치에
// 따라 **행 전체가 칠해지거나**(마지막 픽셀에 걸릴 때 r1==r0+1) **아예 안 보인다**(중간에 걸릴 때 r1==r0).
// 알림 카드 구분선이 18px 회색 밴드로 보이던 것이 앞의 경우다 — 규율로 피할 수 없는 표현력의 한계라
// 얇은 것만 quad 경로로 가른다(`.swatch`/`.quad`가 둥근 모서리를 quad로 보내는 것과 같은 규칙).
test "rasterizeOverlayCells: 셀보다 얇은 fill은 셀 배경이 아니라 GPU quad로 나간다(구분선 밴드 회귀)" {
    const allocator = std.testing.allocator;
    const c = struct {
        fn rgb(r: u8, g: u8, b: u8) maru.color.Rgb {
            return .{ .r = r, .g = g, .b = b };
        }
    };
    const tk = chrome.tokens.Tokens.base(.{
        .diff_added = .{ .r = 64, .g = 160, .b = 64 }, // 픽스처: 비교 밴드 입력(§7)
        .diff_removed = .{ .r = 176, .g = 64, .b = 64 },
        .foreground = c.rgb(1, 1, 1),
        .sidebar_background = c.rgb(2, 2, 2),
        .sidebar_foreground = c.rgb(3, 3, 3),
        .sidebar_active = c.rgb(4, 4, 4),
        .search_match = c.rgb(5, 5, 5),
        .search_match_current = c.rgb(6, 6, 6),
        .selection = c.rgb(7, 7, 7),
        .cursor = c.rgb(8, 8, 8),
        .terminal_background = c.rgb(8, 8, 8), // 픽스처: 터미널 배경 입력(§4.1b terminal_bg)
        .accent = c.rgb(9, 9, 9),
    });
    // cw=10, ch=20. 2칸×2행 패널 + 행0 마지막 픽셀(y=19)에 1px 구분선 — 옛 경로면 행0이 통째로 칠해졌다.
    const ops = [_]chrome.draw.Op{
        .{ .fill = .{ .rect = .{ .x = 0, .y = 0, .w = 20, .h = 40 }, .role = .surface_bg } },
        .{ .fill = .{ .rect = .{ .x = 0, .y = 19, .w = 20, .h = 1 }, .role = .selection } },
    };
    const draws = [_]chrome.ChromeDraw{.{ .layer = .modal, .ops = &ops }};

    var raster = try AppSession.rasterizeOverlayCells(allocator, &draws, &tk, 10, 20, false);
    defer raster.cells.deinit(allocator);
    defer raster.gpu_quads.deinit(allocator);
    defer raster.gpu_shadows.deinit(allocator);

    // 구분선은 quad 하나로 나가고, **픽셀 크기 그대로**다(행 높이로 반올림되지 않는다).
    try std.testing.expectEqual(@as(usize, 1), raster.gpu_quads.items.len);
    const q = raster.gpu_quads.items[0];
    try std.testing.expectEqual(@as(f32, 19), q.y);
    try std.testing.expectEqual(@as(f32, 1), q.h);
    try std.testing.expectEqual(@as(f32, 20), q.w);
    try std.testing.expectEqual(@as(u32, 1), q.layer); // 모달 배경과 같은 층 — 뒤에 append돼 그 위에 그려진다

    // 그리고 어느 셀 배경도 구분선 색으로 바뀌지 않았다(옛 결함은 행0 전체가 selection 색이었다).
    for (raster.cells.items) |cell| {
        try std.testing.expectEqual(c.rgb(2, 2, 2), cell.style.background.rgb);
    }
}

test "rasterizeOverlayCells: draw.Op.clip → OverlayRaster.clip_rect(렌더러 scissor 인프라, 안 그림)" {
    const allocator = std.testing.allocator;
    const cc = struct {
        fn rgb(r: u8, g: u8, b: u8) maru.color.Rgb {
            return .{ .r = r, .g = g, .b = b };
        }
    };
    const tk = chrome.tokens.Tokens.base(.{
        .diff_added = .{ .r = 64, .g = 160, .b = 64 }, // 픽스처: 비교 밴드 입력(§7)
        .diff_removed = .{ .r = 176, .g = 64, .b = 64 },
        .foreground = cc.rgb(1, 1, 1),
        .sidebar_background = cc.rgb(2, 2, 2),
        .sidebar_foreground = cc.rgb(3, 3, 3),
        .sidebar_active = cc.rgb(4, 4, 4),
        .search_match = cc.rgb(5, 5, 5),
        .search_match_current = cc.rgb(6, 6, 6),
        .selection = cc.rgb(7, 7, 7),
        .cursor = cc.rgb(8, 8, 8),
        .terminal_background = cc.rgb(8, 8, 8), // 픽스처: 터미널 배경 입력(§4.1b terminal_bg)
        .accent = cc.rgb(9, 9, 9),
    });
    // clip op은 그리지 않고(셀·bounding-box 무영향) OverlayRaster.clip_rect로만 모인다 — 렌더러가 모달 셀 draw에 scissor.
    var ops = [_]chrome.draw.Op{
        .{ .fill = .{ .rect = .{ .x = 0, .y = 0, .w = 10, .h = 20 }, .role = .surface_bg } },
        .{ .clip = .{ .x = 5, .y = 10, .w = 100, .h = 50 } },
    };
    const draws = [_]chrome.ChromeDraw{.{ .layer = .modal, .ops = &ops }};
    var raster = try AppSession.rasterizeOverlayCells(allocator, &draws, &tk, 10, 20, false);
    defer raster.cells.deinit(allocator);
    defer raster.gpu_quads.deinit(allocator);
    defer raster.gpu_shadows.deinit(allocator);
    try std.testing.expect(raster.clip_rect != null);
    try std.testing.expectEqual(@as(i32, 5), raster.clip_rect.?.x);
    try std.testing.expectEqual(@as(i32, 10), raster.clip_rect.?.y);
    try std.testing.expectEqual(@as(u32, 100), raster.clip_rect.?.w);
    try std.testing.expectEqual(@as(u32, 50), raster.clip_rect.?.h);

    // clip op이 없으면 null = 클리핑 없음(기존 동작 무변).
    var ops2 = [_]chrome.draw.Op{.{ .fill = .{ .rect = .{ .x = 0, .y = 0, .w = 10, .h = 20 }, .role = .surface_bg } }};
    const draws2 = [_]chrome.ChromeDraw{.{ .layer = .modal, .ops = &ops2 }};
    var raster2 = try AppSession.rasterizeOverlayCells(allocator, &draws2, &tk, 10, 20, false);
    defer raster2.cells.deinit(allocator);
    defer raster2.gpu_quads.deinit(allocator);
    defer raster2.gpu_shadows.deinit(allocator);
    try std.testing.expect(raster2.clip_rect == null);
}

test "rasterizeOverlayCells: wide 글리프 뒤 continuation 칸은 emit 안 함(배경이 글리프 안 덮게 — ㄱ 잘림 회귀)" {
    const allocator = std.testing.allocator;
    const cc = struct {
        fn rgb(r: u8, g: u8, b: u8) maru.color.Rgb {
            return .{ .r = r, .g = g, .b = b };
        }
    };
    const tk = chrome.tokens.Tokens.base(.{
        .diff_added = .{ .r = 64, .g = 160, .b = 64 }, // 픽스처: 비교 밴드 입력(§7)
        .diff_removed = .{ .r = 176, .g = 64, .b = 64 },
        .foreground = cc.rgb(1, 1, 1),
        .sidebar_background = cc.rgb(2, 2, 2),
        .sidebar_foreground = cc.rgb(3, 3, 3),
        .sidebar_active = cc.rgb(4, 4, 4),
        .search_match = cc.rgb(5, 5, 5),
        .search_match_current = cc.rgb(6, 6, 6),
        .selection = cc.rgb(7, 7, 7),
        .cursor = cc.rgb(8, 8, 8),
        .terminal_background = cc.rgb(8, 8, 8), // 픽스처: 터미널 배경 입력(§4.1b terminal_bg)
        .accent = cc.rgb(9, 9, 9),
    });
    // cw=10, ch=20. 패널 4칸×1행. "가b" — '가'(wide=2칸) col0, 'b' col2. continuation 칸(col1)은 emit 안 돼야 한다.
    const run = [_]chrome.draw.Run{.{ .text = "가b" }};
    const ops = [_]chrome.draw.Op{
        .{ .fill = .{ .rect = .{ .x = 0, .y = 0, .w = 40, .h = 20 }, .role = .surface_bg } },
        .{ .text = .{ .origin = .{ .x = 0, .y = 0 }, .runs = &run, .role = .surface_fg } },
    };
    const draws = [_]chrome.ChromeDraw{.{ .layer = .modal, .ops = &ops }};

    var raster = try AppSession.rasterizeOverlayCells(allocator, &draws, &tk, 10, 20, false);
    defer raster.cells.deinit(allocator);
    defer raster.gpu_quads.deinit(allocator);
    defer raster.gpu_shadows.deinit(allocator);

    try std.testing.expectEqual(@as(u16, 4), raster.cols);
    // 셀: 가@col0(w2) + b@col2 + space@col3 = 3개. continuation col1은 스킵(emit하면 그 배경이 '가' 오른쪽 절반을 덮음).
    try std.testing.expectEqual(@as(usize, 3), raster.cells.items.len);
    try std.testing.expectEqual(@as(u21, '가'), raster.cells.items[0].codepoint);
    try std.testing.expectEqual(@as(u16, 0), raster.cells.items[0].col);
    try std.testing.expectEqual(@as(u2, 2), raster.cells.items[0].width); // wide
    try std.testing.expectEqual(@as(u21, 'b'), raster.cells.items[1].codepoint);
    try std.testing.expectEqual(@as(u16, 2), raster.cells.items[1].col); // 가가 2칸 차지 → b는 col2
    // col1(가의 continuation)을 가진 셀이 없어야 한다.
    for (raster.cells.items) |cell| try std.testing.expect(cell.col != 1);
}

test "chrome Notice 모달: showNotice → 메시지 소유 복사·오버레이 프레임·입력 라우팅·메뉴 차단·Esc 닫기" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // buildNoticeFrame=CoreText, 실 PTY
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 6,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000); // 메트릭·backing(buildNoticeFrame이 chrome props로 씀)

    // 닫힘이면 buildNoticeFrame은 NotOpen(오버레이 없음 — 호출자가 무시).
    try std.testing.expect(!session.chrome_host.notice.open);
    try std.testing.expectError(error.NotOpen, testBuildChromeOverlayFrame(session));

    // showNotice는 메시지를 세션 소유 버퍼로 복사하고 연다 — 호출자의 transient 버퍼를 지워도 모달 메시지는 산다.
    {
        var transient = [_]u8{ 'c', 'o', 'r', 'r', 'u', 'p', 't' };
        session.showNotice(&transient);
        @memset(&transient, 0);
    }
    try std.testing.expect(session.chrome_host.notice.open);
    try std.testing.expectEqualStrings("corrupt", session.chrome_host.notice.message);

    // 오버레이 프레임이 크래시 없이 셀을 낸다(박스 bg + 메시지 glyph — 컴포넌트 view→ChromeDraw→lower 경로).
    var nf = try testBuildChromeOverlayFrame(session);
    defer nf.frame.deinit(allocator);
    try std.testing.expect(nf.frame.draw_list.cells.len > 0);

    // 회귀: Notice 열린 동안 메뉴 keyEquivalent(runAction)는 무시된다(모달 뒤 터미널 조작 차단).
    try std.testing.expect(!session.runAction("new_term"));

    // 평문 키는 토스트를 **닫고 소비한다** — notice는 비-인터랙티브 정보 토스트라 아무 키로나 닫히되, 그 닫는 키는
    // 셸로 안 흘린다(옛날엔 Enter/Esc 외 키는 소비만 하고 안 닫혀 입력이 막힌 것처럼 보이던 회귀를 수정). 'a'는 토스트만
    // 닫고 터미널 입력 카운터는 그대로다(닫기 제스처라 소비).
    const ti_before = session.total_terminal_input_events;
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'a' }, .modifiers = .{} });
    try std.testing.expect(!session.chrome_host.notice.open);
    try std.testing.expectEqual(ti_before, session.total_terminal_input_events); // 닫는 키는 소비 — 터미널로 안 감

    // Esc도 토스트를 닫고 소비한다(셸로 esc를 안 흘린다). 다시 띄워 확인.
    session.showNotice("corrupt");
    try std.testing.expect(session.chrome_host.notice.open);
    const ti_before_esc = session.total_terminal_input_events;
    _ = try session.handleKeyEvent(.{ .key = .escape, .modifiers = .{} });
    try std.testing.expect(!session.chrome_host.notice.open);
    try std.testing.expectEqual(ti_before_esc, session.total_terminal_input_events); // 셸로 안 흘림
}

test "runtime font size: ⌘+/−/0 cell 메트릭·grid 재계산 + 하한·상한 클램프" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // 실 CoreText 메트릭 + PTY
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1000, 700, 1000); // backing px 확정 → grid 산출

    const base = session.base_font_size;
    try std.testing.expectEqual(base, session.appearance.font.size);
    const cw0 = session.cell_width_px;
    const cols0 = term_ops.activeSurface(session).core.snapshot().size.cols;

    // 폰트 변경 전 baseline: init·resize는 이 플래그를 세우지 않는다(applyMetricsPipeline만 세우고 resize는 그걸
    // 안 탄다) → 이미 false여야 아래 폰트 변경이 세우는 신호를 격리 관측할 수 있다. 이 단언이 깨지면 폰트-무관 경로가
    // dirty를 세운 것.
    try std.testing.expect(!session.file_panel_zoom_dirty);
    // 기본(⌘0 기준)에서 파일 패널 줌 배율은 정확히 1.0(=1000milli)이라 프리뷰가 평소 크기를 유지한다(§2.3).
    try std.testing.expectEqual(@as(u32, 1000), session.filePanelZoomMilli());

    // ⌘+ : 폰트 +보폭(고정 1pt, font_size_step 상수) → cell 픽셀이 커지고(메트릭) grid는 줄거나 같다(같은 backing px).
    session.dispatchAppAction(.increase_font_size);
    try std.testing.expectEqual(base + font_size_step, session.appearance.font.size);
    try std.testing.expect(session.cell_width_px > cw0);
    const cols1 = term_ops.activeSurface(session).core.snapshot().size.cols;
    try std.testing.expect(cols1 <= cols0);

    // **atlas를 비웠으니 sync hold를 우회하는 강제 재투영이 예약돼야 한다.** 이게 없으면 hold 중(BSU 후 ESU 지연)에
    // 사이드바 전용 부분 투영이 커밋되고, 유지된 셀의 UV가 비워진 atlas의 옛 좌표를 가리켜 본문이 다른 글리프로
    // 오염된다(hold timeout ≈1초까지 지속). `shouldProjectFrame`이 이 플래그로 sync 게이트를 우회한다.
    try std.testing.expect(session.force_reproject);
    try std.testing.expect(shouldProjectFrame(false, true, 0, 60, 0, 0, false, session.force_reproject)); // hold여도 투영

    // 폰트가 바뀌면 파일 패널 줌 dirty가 서고(Swift tick이 drain해 webview 재적용), 배율은 (base+1)/base로 1.0 초과다.
    try std.testing.expect(session.file_panel_zoom_dirty);
    try std.testing.expect(session.takeFilePanelZoomDirty()); // 1회성: 읽으면 비워진다
    try std.testing.expect(!session.file_panel_zoom_dirty);
    try std.testing.expect(session.filePanelZoomMilli() > 1000);
    const expected_milli: u32 = @intFromFloat(@round((base + font_size_step) / base * 1000.0));
    try std.testing.expectEqual(expected_milli, session.filePanelZoomMilli());

    // ⌘0 : config 기본값 복원 → 폰트·cell 픽셀 원래대로(refreshCellMetrics 재계산은 결정적) + 배율도 1.0 복귀.
    session.dispatchAppAction(.reset_font_size);
    try std.testing.expectEqual(base, session.appearance.font.size);
    try std.testing.expectEqual(cw0, session.cell_width_px);
    try std.testing.expectEqual(@as(u32, 1000), session.filePanelZoomMilli());

    // set_font_size:N — 절대 지정(config 바인딩). 그 크기로 바로 설정, [6,72]로 클램프.
    session.dispatchAppAction(.{ .set_font_size = 24 });
    try std.testing.expectEqual(@as(f32, 24), session.appearance.font.size);
    session.dispatchAppAction(.{ .set_font_size = 1000 }); // 상한 클램프
    try std.testing.expectEqual(font_size_max, session.appearance.font.size);
    session.dispatchAppAction(.{ .set_font_size = 1 }); // 하한 클램프
    try std.testing.expectEqual(font_size_min, session.appearance.font.size);
    session.dispatchAppAction(.reset_font_size); // base로 복원(아래 경계 반복 기준)

    // ⌘- 반복 : 하한(font_size_min) 아래로 안 내려간다(경계에서 무동작).
    var i: usize = 0;
    while (i < 100) : (i += 1) session.dispatchAppAction(.decrease_font_size);
    try std.testing.expectEqual(font_size_min, session.appearance.font.size);

    // ⌘+ 반복 : 상한(font_size_max) 위로 안 올라간다.
    i = 0;
    while (i < 200) : (i += 1) session.dispatchAppAction(.increase_font_size);
    try std.testing.expectEqual(font_size_max, session.appearance.font.size);
}

test "Session Dock Cmd zoom grows and shrinks one resolved layout/text/scroll scale" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1000, 700, 1000);

    const base_scale = agent_dock.agentSessionDockScaleMilli(session);
    const base_card_h_px = agent_dock.agentSessionDockScrollItems(session).card_h_px;
    try std.testing.expectEqual(@as(u32, 1000), agent_dock.agentSessionDockUiZoomMilli(session));
    try std.testing.expectEqual(@as(u32, 1000), base_scale);

    session.dispatchAppAction(.increase_font_size);
    const larger_scale = agent_dock.agentSessionDockScaleMilli(session);
    const larger_card_h_px = agent_dock.agentSessionDockScrollItems(session).card_h_px;
    try std.testing.expect(larger_scale > base_scale);
    try std.testing.expect(larger_card_h_px > base_card_h_px);

    session.dispatchAppAction(.reset_font_size);
    session.dispatchAppAction(.decrease_font_size);
    const smaller_scale = agent_dock.agentSessionDockScaleMilli(session);
    const smaller_card_h_px = agent_dock.agentSessionDockScrollItems(session).card_h_px;
    try std.testing.expect(smaller_scale < base_scale);
    try std.testing.expect(smaller_card_h_px < base_card_h_px);

    session.setFontSize(font_size_min);
    try std.testing.expectEqual(agent_dock.session_dock_ui_zoom_min_milli, agent_dock.agentSessionDockUiZoomMilli(session));
    session.setFontSize(font_size_max);
    try std.testing.expectEqual(agent_dock.session_dock_ui_zoom_max_milli, agent_dock.agentSessionDockUiZoomMilli(session));
    session.dispatchAppAction(.reset_font_size);
    try std.testing.expectEqual(@as(u32, 1000), agent_dock.agentSessionDockUiZoomMilli(session));
}

test "Session Dock search owns committed text and IME preedit instead of leaking to the terminal" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1000, 700, 1000);

    // Keep this input-routing test synchronous: archive scanning owns a detached worker and is
    // separately covered by the AppKit fixture.  The visible dock is enough to establish the
    // exact `InputFocus.agent_session_search` owner.
    session.dock.presented = true;
    session.dock.collapsed = false;
    session.dock.side = .right;
    session.agent_session_archive_initialized = false;
    dock_ops.setDockView(session, .agent_sessions);
    session.agent_session_archive_initialized = true;
    session.agent_session_archive_search_active = true;
    try std.testing.expectEqual(AppSession.InputFocus.agent_session_search, session.inputFocus());

    const before_terminal_input = session.total_terminal_input_events;
    input_ops.routeCommittedText(session, "codex");
    try std.testing.expectEqualStrings("codex", session.agent_session_archive_search.query.items);
    try std.testing.expectEqual(before_terminal_input, session.total_terminal_input_events);

    // Marked text is visible immediately but must not filter until composition commits.
    input_ops.imeMarked(session, "한");
    try std.testing.expectEqualStrings("한", session.agent_session_archive_search.preedit.items);
    try std.testing.expectEqualStrings("codex", session.agent_session_archive_search.query.items);
    try std.testing.expect(input_ops.imeComposingActive(session));
    session.commitComposition();
    try std.testing.expectEqualStrings("codex한", session.agent_session_archive_search.query.items);
    try std.testing.expectEqual(@as(usize, 0), session.agent_session_archive_search.preedit.items.len);
    try std.testing.expectEqual(before_terminal_input, session.total_terminal_input_events);
}

// reapplyLoadedConfig(세팅 GUI 라이브 재적용 — 커서 깜빡임 토글 등)가 런타임 ⌘+/− 줌을 날리지 않는지(버그 회귀
// 가드: 확대 상태에서 폰트 무관 설정을 토글하면 확대가 리셋되던 문제). config 폰트 크기가 바뀌면 줌이 그 위에
// 상대로 얹히는지(base_font_size=⌘0 기준은 줌 제외 config 값)도 함께 본다.
test "reapplyLoadedConfig: GUI 토글이 런타임 줌(⌘+/−)을 보존한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // 실 CoreText 메트릭 + PTY
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1000, 700, 1000); // backing px 확정 → grid 산출

    const factory = try config_mod.resolveAppearance(.{});
    const cw0 = session.cell_width_px;
    try std.testing.expectEqual(factory.font.size, session.appearance.font.size);
    try std.testing.expectEqual(factory.font.size, session.base_font_size);

    // ⌘+ 로 6pt 확대 — appearance만 바뀌고 loaded_config.config.font.size는 파일 기본 그대로.
    session.setFontSize(factory.font.size + 6);
    const zoomed_cw = session.cell_width_px;
    try std.testing.expect(zoomed_cw > cw0);
    try std.testing.expectEqual(factory.font.size + 6, session.appearance.font.size);

    // 폰트와 무관한 설정 토글(예: cursor.blink) → loaded_config in-place flip 후 reapplyLoadedConfig.
    _ = config_mod.schema.setBool(&session.loaded_config.config, "cursor.blink", false);
    settings_ops.reapplyLoadedConfig(session);
    try std.testing.expectEqual(factory.font.size + 6, session.appearance.font.size); // 줌 보존(버그였다면 factory로 리셋)
    try std.testing.expectEqual(factory.font.size, session.base_font_size); // ⌘0 기준은 줌 제외 config 값
    try std.testing.expectEqual(zoomed_cw, session.cell_width_px); // cell 메트릭도 확대 그대로

    // ⌘0 reset은 여전히 config 기본으로 복귀(base 보존 확인).
    session.resetFontSize();
    try std.testing.expectEqual(factory.font.size, session.appearance.font.size);
    try std.testing.expectEqual(cw0, session.cell_width_px);

    // config 폰트 크기 자체를 GUI(슬라이더/스텝)로 바꾸면, 그 값이 사용자가 의도한 절대 크기다 — 줌을 얹지 않고
    // 그 값으로 간다(슬라이더 표시 == 렌더 크기, code-review high #1). 확대 상태에서 슬라이더를 끌어도 줌이 흡수돼
    // base=appearance=새 config 값이 된다(안 그러면 슬라이더는 14를 가리키는데 렌더는 20이 되는 불일치).
    session.setFontSize(factory.font.size + 6); // 다시 +6 확대(appearance=base+6, base=base)
    session.loaded_config.config.font.size = factory.font.size + 2; // 슬라이더로 config 폰트 크기 변경
    settings_ops.reapplyLoadedConfig(session);
    try std.testing.expectEqual(factory.font.size + 2, session.base_font_size); // ⌘0 기준 = 새 config 값
    try std.testing.expectEqual(factory.font.size + 2, session.appearance.font.size); // 줌 안 얹힘 — 슬라이더 값 그대로
}

// resetAllSettings(통합 리셋 — 메뉴 Reset to Defaults·커맨드 팝업 공용 단일 함수)가 런타임 줌·config 변경을 공장
// 기본값으로 되돌리는지. 파일 덮어쓰기·테마 프리셋은 별도 통합 테스트가 다루므로, 여기선 런타임 상태
// (appearance·cell 메트릭·behavior 캐시·loaded_config)가 기본값이 되는지 + 완료 notice가 뜨는지(회귀 가드) 본다.
test "resetAllSettings: 런타임 줌·config 변경을 공장 기본값으로 복원한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // 실 CoreText 메트릭 + PTY
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1000, 700, 1000); // backing px 확정 → grid 산출

    const factory = try config_mod.resolveAppearance(.{});
    const cw0 = session.cell_width_px;
    try std.testing.expectEqual(factory.font.size, session.appearance.font.size);

    // 런타임 줌 + config behavior 변경.
    session.setFontSize(factory.font.size + 6);
    session.loaded_config.config.font.size = factory.font.size + 6;
    session.loaded_config.config.bell.audible = false;
    session.audible_bell = false;
    try std.testing.expect(session.appearance.font.size != factory.font.size);
    try std.testing.expect(session.cell_width_px > cw0); // 폰트 키우면 cell 픽셀이 커진다(메트릭)

    // 안전 가드: resetAllSettings가 configPath()에 파일을 쓰므로, 실제 사용자 config(~/.config/maru/config)가 아니라
    // tmp 파일을 덮어쓰도록 config_path_buffer를 박는다(없으면 macOS에서 zig build test가 실 config를 헤더만 남기고 지운다).
    var reset_tmp = std.testing.tmpDir(.{});
    defer reset_tmp.cleanup();
    var reset_path_buf: [4096]u8 = undefined;
    const reset_cfg_path = try std.fmt.bufPrint(&reset_path_buf, ".zig-cache/tmp/{s}/config", .{reset_tmp.sub_path});
    if (session.config_path_buffer) |b| allocator.free(b);
    session.config_path_buffer = try allocator.dupe(u8, reset_cfg_path);
    // keybind 초기화(#2-b) 검증용: unbind 1개를 arena에 심어 reset이 비우는지 본다(빈 슬라이스에서 시작하면 약한 검증이라).
    session.loaded_config.unbinds = try session.loaded_config.arena.allocator().dupe(config_mod.KeyChord, &.{try config_mod.KeyChord.parse("Cmd+J")});

    settings_ops.resetAllSettings(session);

    // 런타임·loaded_config가 공장 기본값으로(resetAllSettings: loaded_config=Config{} + reapplyLoadedConfig).
    try std.testing.expectEqual(factory.font.size, session.appearance.font.size);
    try std.testing.expectEqual(cw0, session.cell_width_px);
    try std.testing.expectEqual(factory.font.size, session.base_font_size); // ⌘0 기준도 기본으로
    try std.testing.expectEqual(true, session.audible_bell); // 기본 bell.audible로 복원
    try std.testing.expectEqual(factory.font.size, session.loaded_config.config.font.size);
    try std.testing.expectEqual(true, session.loaded_config.config.bell.audible);
    try std.testing.expect(session.chrome_host.notice.open); // 완료 notice가 떴는지(showNotice)
    // keybind 바인딩 4종이 빈 슬라이스(빌트인만)로 초기화됐는지(#2-b — reset은 keybind도 기본값으로).
    try std.testing.expectEqual(@as(usize, 0), session.loaded_config.unbinds.len);
    try std.testing.expectEqual(@as(usize, 0), session.loaded_config.keybindings.len);
    try std.testing.expectEqual(@as(usize, 0), session.loaded_config.terminal_bindings.len);
    try std.testing.expectEqual(@as(usize, 0), session.loaded_config.global_bindings.len);
}

// applyAppearance: 새 appearance를 통째로 갈아끼우면 appearance·base_font_size·cell 메트릭이 따라 바뀌는지.
// reloadConfig가 파일 새 값으로 부르는 일반 적용 경로 — 파일 I/O 없이 직접 호출로 핵심(appearance/메트릭 갱신)을 고정한다.
test "applyAppearance: 새 appearance로 appearance·base_font_size·메트릭을 갱신한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // 실 CoreText 메트릭 + PTY
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1000, 700, 1000);

    const cw0 = session.cell_width_px;
    // 폰트가 더 큰 appearance를 만든다(기본 resolve에서 size만 키움).
    var bigger = try config_mod.resolveAppearance(.{});
    bigger.font = session.appearance.font; // family 슬라이스는 살아있는 loaded_config 빌림(undefined family 회피)
    bigger.font.size = session.appearance.font.size + 8;

    settings_ops.applyAppearance(session, bigger);
    try std.testing.expectEqual(bigger.font.size, session.appearance.font.size);
    try std.testing.expectEqual(bigger.font.size, session.base_font_size); // base_font_size도 새 크기로(⌘0 기준)
    try std.testing.expect(session.cell_width_px > cw0); // 메트릭 재계산(큰 폰트 → 큰 cell)
}

test "captureWorkspaceWindow: 라이브 탭/split/Term을 workspace 모델로 캡처" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // 실 PTY + split/탭 생성
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000);

    // 활성 surface에 cwd(OSC 7) 심기 + split으로 pane 2개 + 새 탭(탭 2개). authority는 로컬(빈 값) —
    // 원격 cwd는 워크스페이스에 저장되지 않으므로(§9.4) 임의 host를 쓰면 이 캡처 단언이 빈 문자열을 본다.
    try term_ops.activeSurface(session).core.write("\x1b]7;file:///tmp/proj\x07");
    session.dispatchAppAction(.split_horizontal);
    session.dispatchAppAction(.new_tab);

    var arena = std.heap.ArenaAllocator.init(allocator);
    defer arena.deinit();
    const win = try workspace_ops.captureWorkspaceWindow(session, arena.allocator(), false, null);

    // 탭 2개, 활성 탭 = 1(방금 만든 새 탭).
    try std.testing.expectEqual(@as(usize, 2), win.tabs.len);
    try std.testing.expectEqual(@as(usize, 1), win.active_tab);
    // 탭0: split → pane 2개 + tree preorder(split, leaf, leaf).
    const tab0 = win.tabs[0];
    try std.testing.expectEqual(@as(usize, 2), tab0.panes.len);
    try std.testing.expectEqual(@as(usize, 3), tab0.tree.len);
    try std.testing.expect(std.meta.activeTag(tab0.tree[0]) == .split);
    try std.testing.expect(std.meta.activeTag(tab0.tree[1]) == .leaf);
    // cwd /tmp/proj가 어떤 surface에 잡혔고, 모든 surface가 유효 크기를 가진다.
    var saw_cwd = false;
    for (tab0.panes) |pane| {
        for (pane.surfaces) |s| {
            if (std.mem.eql(u8, s.cwd, "/tmp/proj")) saw_cwd = true;
            try std.testing.expect(s.cols > 0 and s.rows > 0);
        }
    }
    try std.testing.expect(saw_cwd);

    // **원격 cwd는 저장하지 않는다**(§9.4). 워크스페이스 파일에는 host가 없으므로 원격 경로를 담으면 복원 때
    // 그것을 로컬 경로로 알고 spawn해 자식이 chdir에 실패한다. 빈 값이면 복원이 기본 자리에서 연다.
    try term_ops.activeSurface(session).core.write("\x1b]7;file://build-box/srv/app\x07");
    var remote_arena = std.heap.ArenaAllocator.init(allocator);
    defer remote_arena.deinit();
    const remote_win = try workspace_ops.captureWorkspaceWindow(session, remote_arena.allocator(), false, null);
    for (remote_win.tabs) |t| {
        for (t.panes) |pane| {
            for (pane.surfaces) |s| {
                try std.testing.expect(!std.mem.eql(u8, s.cwd, "/srv/app")); // 원격 경로가 새어 나가지 않는다
            }
        }
    }

    // capture → serialize가 크래시 없이 기대 라인을 낸다(R1 writer와 결합).
    const wins = [_]maru.session.workspace.Window{win};
    const text = try maru.session.workspace.serialize(allocator, .{ .windows = &wins });
    defer allocator.free(text);
    try std.testing.expect(std.mem.indexOf(u8, text, "maru.workspace.v1\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, text, "tree-node split horizontal") != null);
    try std.testing.expect(std.mem.indexOf(u8, text, "cwd=\"/tmp/proj\"") != null);
}

test "dock toggle visual bottom covers 1.7x glyph when titlebar is below equal or above cell height" {
    // strip < cell: renderer starts the cell at y=0, so visible bottom is 1.35ch.
    try std.testing.expectEqual(@as(u32, 27), file_panel_ops.dockToggleVisualBottomPx(20, 10));
    // strip == cell: 같은 경계이며 큰 글꼴에서도 glyph 아래쪽까지 hit rect가 포함한다.
    try std.testing.expectEqual(@as(u32, 27), file_panel_ops.dockToggleVisualBottomPx(20, 20));
    // strip > 1.7ch: glyph가 strip 안에 완전히 들어가므로 호출부의 max(strip, bottom)가 strip을 유지한다.
    try std.testing.expectEqual(@as(u32, 37), file_panel_ops.dockToggleVisualBottomPx(20, 40));
    // 제품 기본 근사(ch=18, strip=28)는 1.7x quad의 1px 남짓한 아래 돌출까지 포함한다.
    try std.testing.expectEqual(@as(u32, 29), file_panel_ops.dockToggleVisualBottomPx(18, 28));
}

test "empty file dock launcher presents explorer and empty content requests the shared file picker" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1400, 900, 1000);

    try std.testing.expect(!file_panel_ops.dockHasContent(session));
    try std.testing.expect(!dock_ops.dockVisible(session));
    try std.testing.expectEqual(AppSession.FilePanelDockControlAction.open, file_panel_ops.filePanelDockControlAction(session).?);
    const launcher = file_panel_ops.filePanelDockControlRect(session) orelse return error.MissingDockLauncher;
    try std.testing.expect(!workspace_ops.isWindowDragRegion(
        session,
        @floatFromInt(launcher.x + 1),
        @floatFromInt(launcher.y + 1),
    ));

    session.metal_dirty = true;
    _ = try session.tick();
    var saw_launcher = false;
    for (session.metal_buffer.cells) |cell| {
        if (cell.codepoint == icons.codepoint(.sidebar_collapse) and cell.reserved == metal_frame.native_cell_role_dock_toggle and
            cell.origin_x >= launcher.x and cell.origin_x < launcher.x + launcher.w and
            cell.origin_y < session.titlebar_strip_px)
        {
            saw_launcher = true;
            break;
        }
    }
    try std.testing.expect(saw_launcher);

    session.mouse(1, @floatFromInt(launcher.x + 1), @floatFromInt(launcher.y + 1), 0, 0);
    try std.testing.expect(!session.takeFilePanelPickRequest());
    try std.testing.expect(dock_ops.dockVisible(session));
    const tree_content = dock_ops.dockGeometry(session).tree_content;
    // FP16: 트리가 도크 전체라 좌측 가장자리는 outer divider의 grab band와 겹친다 — 밴드 밖(가운데)을 누른다.
    session.mouse(1, @floatFromInt(tree_content.x + tree_content.w / 2), @floatFromInt(tree_content.y + 1), 0, 0);
    try std.testing.expect(session.takeFilePanelPickRequest());
    try std.testing.expect(!session.takeFilePanelPickRequest());

    _ = 0; // FP16: 도크 그룹 개념 제거
    _ = try pane_ops.openFileTermInActivePane(session, "/tmp/launcher-transition.md", .markdown);
    try std.testing.expectEqual(AppSession.FilePanelDockControlAction.collapse, file_panel_ops.filePanelDockControlAction(session).?);
    file_panel_ops.activateFilePanelDockControl(session);
    try std.testing.expect(session.dock.collapsed);
    try std.testing.expectEqual(AppSession.FilePanelDockControlAction.expand, file_panel_ops.filePanelDockControlAction(session).?);
    file_panel_ops.activateFilePanelDockControl(session);
    try std.testing.expect(!session.dock.collapsed);

    session.chrome_minimal = true;
    try std.testing.expect(file_panel_ops.filePanelDockControlRect(session) == null);
}

test "file tree root picker is a typed one-shot and cancel or invalid path preserves roots" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    try session.file_tree.replaceExplicitRoots(&.{"/before"});
    const generation = session.file_tree.rootGeneration();

    file_panel_ops.requestFileTreeRootPick(session, .replace);
    try std.testing.expectEqual(FileTreeRootOutcome.picker_requested, file_panel_ops.fileTreeRootOutcome(session));
    try std.testing.expectEqual(FileTreeRootOperation.replace, session.takeFileTreeRootPickRequest());
    try std.testing.expectEqual(FileTreeRootOperation.none, session.takeFileTreeRootPickRequest());
    file_panel_ops.provideFileTreeRootPick(session, &.{}); // AppKit cancel
    try std.testing.expectEqual(FileTreeRootOutcome.picker_canceled, file_panel_ops.fileTreeRootOutcome(session));
    try std.testing.expectEqual(generation, session.file_tree.rootGeneration());
    try std.testing.expectEqualStrings("/before", session.file_tree.rootAt(0).?);

    file_panel_ops.requestFileTreeRootPick(session, .add);
    try std.testing.expectEqual(FileTreeRootOperation.add, session.takeFileTreeRootPickRequest());
    file_panel_ops.provideFileTreeRootPick(session, "relative");
    try std.testing.expectEqual(FileTreeRootOutcome.invalid_path, file_panel_ops.fileTreeRootOutcome(session));
    try std.testing.expectEqual(generation, session.file_tree.rootGeneration());
    try std.testing.expectEqualStrings("/before", session.file_tree.rootAt(0).?);
}

// 적대적 검증이 잡은 넷을 고정한다. 전부 "조용히 안 따라간다"로만 드러나 눈으로는 구분되지 않는다.
test "file tree ET-CWD: 자동 root 전환은 mutation·비탐색기 view에서 미루고, 미룬 cwd를 다시 시도한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    try tmp.dir.createDir(session.io, "project", .default_dir);
    try tmp.dir.createDir(session.io, "away", .default_dir);
    try tmp.dir.createDir(session.io, "other", .default_dir);
    var tmp_buf: [std.fs.max_path_bytes]u8 = undefined;
    const tmp_root = tmp_buf[0..try tmp.dir.realPath(session.io, &tmp_buf)];
    const project = try std.fs.path.join(allocator, &.{ tmp_root, "project" });
    defer allocator.free(project);
    const away = try std.fs.path.join(allocator, &.{ tmp_root, "away" });
    defer allocator.free(away);
    const other = try std.fs.path.join(allocator, &.{ tmp_root, "other" });
    defer allocator.free(other);

    file_panel_ops.activateFilePanelDockControl(session);
    try session.file_tree.replaceExplicitRoots(&.{project});
    const initial_scan = session.file_tree.takeScanRequest().?;
    allocator.free(initial_scan);

    // ① **파일 mutation 중에는 전환하지 않는다.** root 교체는 그때 거부되는 동작이고(file-explorer.md §2),
    //    자동 경로가 `provideFileTreeRootPick`을 직접 불러 그 게이트를 우회하고 있었다.
    session.file_tree_edit_inflight = true;
    try testWriteActiveTermCwd(session, away);
    try file_panel_ops.updateFileTree(session);
    try std.testing.expect(session.file_tree_root_validation == null);
    // ② **미룬 cwd는 "따라간 것"으로 표시되지 않는다.** 표시하면 다음 `cd` 전까지 영영 재시도되지 않아
    //    시작 직후처럼 슬롯이 잠깐 바쁜 순간의 첫 따라가기가 통째로 사라진다.
    try std.testing.expect(session.file_tree_followed_cwd == null);

    session.file_tree_edit_inflight = false;
    try file_panel_ops.updateFileTree(session); // 같은 cwd 그대로 — 이제는 걸려야 한다
    {
        const pending = session.file_tree_root_validation orelse return error.TestUnexpectedResult;
        try std.testing.expect(pending.auto);
        try std.testing.expectEqualStrings(away, session.file_tree_followed_cwd.?);
    }
    try testWaitForFileTreeRootCompletion(session);
    try std.testing.expect(session.file_tree.rootIsExactly(away));

    // ③ **탐색기를 보고 있지 않으면 미룬다.** 트리가 화면에 없는데 root를 갈면 보이지도 않는 접힘·스크롤을
    //    버리고 `dock-tree-roots` 영속까지 덮는다. reveal 모델에서는 비파괴적이라 상관없었지만 이제
    //    모든 `cd`가 교체라 이 게이트가 유일한 방어다(file-explorer.md §1.1).
    session.dock.view = .source_control;
    try testWriteActiveTermCwd(session, other);
    try file_panel_ops.updateFileTree(session);
    try std.testing.expect(session.file_tree_root_validation == null);
    try std.testing.expectEqualStrings(away, session.file_tree_followed_cwd.?); // 표시하지 않는다 → 재시도가 남는다
    try std.testing.expect(session.file_tree.rootIsExactly(away)); // 트리는 그대로다

    //    **미룰 때는 스크롤 pending도 끈다.** 살려 두면 지금 cwd와 무관한 옛 대상으로 스크롤한다 —
    //    이 단언이 없으면 그 클리어를 지워도 테스트가 통과한다(적대적 검증 1회차).
    try std.testing.expect(!session.file_tree_follow_scroll_pending);

    // ④ **제출 자체가 실패해도 재시도로 남긴다.** `provideFileTreeRootPick`은 backend busy·할당 실패·
    //    request id 소진에서 검증을 안 세우고 조용히 빠져나온다(자동 경로라 알림도 없다). 그때 이 cwd를
    //    "따라간 것"으로 표시하면 다음 `cd` 전까지 영영 재시도되지 않는다 — §1.1의 규율과 같은 상황인데
    //    실패 지점만 한 단계 안쪽이다(적대적 검증 2회차가 잡은 실제 버그).
    session.dock.view = .explorer;
    const saved_request_id = session.file_tree_root_request_id;
    session.file_tree_root_request_id = std.math.maxInt(u64); // request id 소진 경로를 강제한다
    try file_panel_ops.updateFileTree(session);
    try std.testing.expect(session.file_tree_root_validation == null); // 검증은 안 걸렸고
    try std.testing.expectEqual(FileTreeRootOutcome.request_id_exhausted, file_panel_ops.fileTreeRootOutcome(session));
    try std.testing.expectEqualStrings(away, session.file_tree_followed_cwd.?); // followed로 표시하지 않는다
    session.file_tree_root_request_id = saved_request_id;
    session.file_tree_root_outcome = .none;

    // ⑤ 조건이 풀리면 **`cd` 없이도** 그 tick이 밀린 전환을 건다.
    try file_panel_ops.updateFileTree(session);
    {
        const pending = session.file_tree_root_validation orelse return error.TestUnexpectedResult;
        try std.testing.expect(pending.auto);
        try std.testing.expectEqualStrings(other, session.file_tree_followed_cwd.?);
    }
    try testWaitForFileTreeRootCompletion(session);
    try std.testing.expect(session.file_tree.rootIsExactly(other));
}

fn testWriteActiveTermCwd(session: *AppSession, cwd: []const u8) !void {
    // 실제 OSC 7→core observation 경로를 쓴다. cache를 직접 바꾸면 updateFileTree가 renderer보다 먼저
    // observation을 refresh해야 한다는 제품 불변을 증명하지 못한다.
    var osc: [std.fs.max_path_bytes + 32]u8 = undefined;
    const bytes = try std.fmt.bufPrint(&osc, "\x1b]7;file://localhost{s}\x07", .{cwd});
    try pane_ops.activePane(session).activeTerm().surface.core.write(bytes);
}

test "file tree ET-CWD: root는 활성 pane cwd를 그대로 따라간다 (하위·형제·상위·홈 구분 없이)" {
    // 2026-08-31 사용자 결정(docs/file-explorer.md §1)의 제품 경로 회귀다. 앞의 두 판은 root **밖**일
    // 때만(그것도 저장소 루트로) 갈아끼웠고, 그래서 홈이 한 번 root가 되면 그 아래 어디로 `cd` 해도
    // 빠져나오지 못했다. 이 테스트가 닫는 것은 **하위로 들어갈 때도 교체된다**는 것 — 옛 계약에서는
    // 정확히 그 경우가 reveal(무교체)이었다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    try tmp.dir.createDir(session.io, "project", .default_dir);
    // **project를 실제 저장소로 만든다.** 이게 없으면 `repoRootFor`가 어차피 null을 돌려줘 cwd로 떨어지고,
    // 그러면 "저장소 루트로 올려 세우지 않는다"는 이 슬라이스의 절반이 **테스트로 고정되지 않는다** —
    // `followRootSwitch`에 옛 `repoRootFor(cwd) orelse cwd`를 되돌려 놔도 초록이었다(적대적 검증 1회차).
    // `repoRootFor`는 `<dir>/.git`의 존재만 보므로 빈 디렉터리로 충분하다.
    try tmp.dir.createDir(session.io, "project/.git", .default_dir);
    try tmp.dir.createDir(session.io, "project/one", .default_dir);
    try tmp.dir.createDir(session.io, "project/two", .default_dir);
    try tmp.dir.createDir(session.io, "outside", .default_dir);
    var tmp_buf: [std.fs.max_path_bytes]u8 = undefined;
    const tmp_root = tmp_buf[0..try tmp.dir.realPath(session.io, &tmp_buf)];
    const project = try std.fs.path.join(allocator, &.{ tmp_root, "project" });
    defer allocator.free(project);
    const one = try std.fs.path.join(allocator, &.{ project, "one" });
    defer allocator.free(one);
    const two = try std.fs.path.join(allocator, &.{ project, "two" });
    defer allocator.free(two);
    const outside = try std.fs.path.join(allocator, &.{ tmp_root, "outside" });
    defer allocator.free(outside);

    file_panel_ops.activateFilePanelDockControl(session);
    try session.file_tree.replaceExplicitRoots(&.{project});
    const initial_scan = session.file_tree.takeScanRequest().?;
    allocator.free(initial_scan);

    // ① **이미 그 자리면 아무것도 하지 않는다.** 복원된 root가 마침 터미널 cwd와 같은, 앱을 켤 때마다
    //    도는 경로다. 가드가 없으면 시작하자마자 재스캔·watcher 재등록이 헛돌아 트리가 이유 없이 깜빡인다.
    //    updateFileTree는 renderer보다 먼저 run하므로, 내부에서 observation을 refresh하지 않으면 이 OSC 7이
    //    아직 Term cache에 안 들어와 첫 따라가기를 통째로 놓친다.
    const generation_before = session.file_tree.rootGeneration();
    try testWriteActiveTermCwd(session, project);
    try file_panel_ops.updateFileTree(session);
    try std.testing.expect(session.file_tree_root_validation == null);
    try std.testing.expectEqualStrings(project, session.file_tree_followed_cwd.?);
    try std.testing.expectEqual(generation_before, session.file_tree.rootGeneration());

    // ② **하위로 들어가도 교체하고, 저장소 루트로 올려 세우지 않는다** — 이 슬라이스의 핵심 둘이 여기서
    //    함께 닫힌다. 옛 계약에서는 root 안이라 reveal만 했고(교체 없음), 그 앞 판은 교체하되 `project`(=
    //    저장소 루트)를 세웠다. 지금은 `one`이 그대로 root다.
    try testWriteActiveTermCwd(session, one);
    try file_panel_ops.updateFileTree(session);
    {
        const pending = session.file_tree_root_validation orelse return error.TestUnexpectedResult;
        try std.testing.expect(pending.auto); // 사용자 조작이 아니라 따라가기다
        try std.testing.expectEqual(FileTreeRootOperation.replace, pending.operation);
        try std.testing.expectEqualStrings(one, session.file_tree_followed_cwd.?);
    }
    try testWaitForFileTreeRootCompletion(session);
    try std.testing.expect(session.file_tree.rootIsExactly(one)); // ★ 트리 최상위가 곧 cwd다
    try std.testing.expect(!session.file_tree.rootIsExactly(project)); // ★ 저장소 루트로 올라가지 않았다
    try std.testing.expectEqual(@as(usize, 1), session.file_tree.rootCount());

    // ③ 관측은 tick마다 같은 cwd를 되풀이한다. 같은 값에서 또 교체를 걸면 트리가 매 프레임 재구성된다.
    //    **교체가 없다는 것만으로는 부족하다** — `followed_cwd` 대조를 지워도 `rootIsExactly`가 참이라
    //    교체는 여전히 안 걸리고, 대신 매 tick 재투영과 스크롤 보정이 돈다(사용자에게는 트리가 계속
    //    깜빡이고 스크롤이 안 잡히는 것으로 보인다). 그래서 그 둘을 함께 고정한다(적대적 검증 1회차).
    session.file_tree_rows_dirty = false;
    session.file_tree_follow_scroll_pending = false;
    try file_panel_ops.updateFileTree(session);
    try std.testing.expect(session.file_tree_root_validation == null);
    try std.testing.expect(!session.file_tree_rows_dirty);
    try std.testing.expect(!session.file_tree_follow_scroll_pending);

    // ④ 형제로 이동 — 공통 조상으로 올려 세우지 않고 그 폴더 자체가 root다.
    try testWriteActiveTermCwd(session, two);
    try file_panel_ops.updateFileTree(session);
    try testWaitForFileTreeRootCompletion(session);
    try std.testing.expect(session.file_tree.rootIsExactly(two));

    // ⑤ 상위로 이동(`cd ..`)도 같다. 옛 계약에서는 root 밖이라 교체됐지만 저장소 루트로 올라갔다 —
    //    지금은 저장소 여부를 묻지 않으므로 그 폴더가 그대로 선다.
    try testWriteActiveTermCwd(session, project);
    try file_panel_ops.updateFileTree(session);
    try testWaitForFileTreeRootCompletion(session);
    try std.testing.expect(session.file_tree.rootIsExactly(project));

    // ⑥ 완전히 다른 가지로 나가도 같은 한 규칙이다.
    try testWriteActiveTermCwd(session, outside);
    try file_panel_ops.updateFileTree(session);
    try testWaitForFileTreeRootCompletion(session);
    try std.testing.expect(session.file_tree.rootIsExactly(outside));

    // ⑦ **사용자 조작이 자동 전환을 밀어낸다.** 자동 검증이 슬롯을 잡은 채로 폴더 열기를 거절하면,
    //    사용자는 방금 누른 메뉴가 왜 안 먹는지 알 수 없다(docs/file-explorer.md §1.1).
    try testWriteActiveTermCwd(session, one);
    try file_panel_ops.updateFileTree(session);
    try std.testing.expect(session.file_tree_root_validation != null);
    file_panel_ops.requestFileTreeRootPick(session, .add);
    try std.testing.expect(session.file_tree_root_validation == null); // 자동 검증은 자리를 내준다
    try std.testing.expectEqual(FileTreeRootOperation.add, session.takeFileTreeRootPickRequest());
    file_panel_ops.provideFileTreeRootPick(session, &.{}); // picker 취소로 정리
    session.file_tree_root_outcome = .none;

    // ⑧ 새 split pane을 active로 바꾸면 이전 pane의 cwd가 아니라 새 active Term의 cwd만 따라간다.
    //    도크는 창 전역인데 cwd는 Term별이라, 이 축이 갈리면 트리가 어느 pane의 것인지 알 수 없다.
    try pane_ops.splitActivePane(session, .horizontal);
    try testWriteActiveTermCwd(session, two);
    try file_panel_ops.updateFileTree(session);
    try std.testing.expectEqualStrings(two, session.file_tree_followed_cwd.?);
    try testWaitForFileTreeRootCompletion(session);
    try std.testing.expect(session.file_tree.rootIsExactly(two));

    // ⑨ 파일/브라우저 Term은 cwd가 없으므로 직전 값을 지우지 않는다 — 문서를 보다 터미널로 돌아왔을 때
    //    트리가 리셋되면 안 된다.
    session.dispatchAppAction(.new_web_tab);
    try std.testing.expect(pane_ops.activePane(session).activeTerm().kind == .web);
    try file_panel_ops.updateFileTree(session);
    try std.testing.expectEqualStrings(two, session.file_tree_followed_cwd.?);
    try std.testing.expect(session.file_tree.rootIsExactly(two));
}

fn testWaitForFileTreeRootCompletion(session: *AppSession) !void {
    var attempts: usize = 0;
    while (session.file_tree_root_validation != null and attempts < 2_000) : (attempts += 1) {
        try file_panel_ops.updateFileTree(session);
        std.Io.sleep(session.io, std.Io.Duration.fromMilliseconds(1), .awake) catch {};
    }
    if (session.file_tree_root_validation != null) return error.TestUnexpectedResult;
    try file_panel_ops.updateFileTree(session);
}

// **파일을 열어도 트리의 선택과 스크롤은 그 자리에 있어야 한다**(사용자 보고 2026-08-27 — "열면 맨 위로
// 팅겨서요"). 목록을 스크롤해 아래쪽 파일을 눌렀는데 트리가 맨 위로 돌아가면, 이어서 형제 파일을 열려는
// 사용자는 매번 그 자리를 다시 찾아 내려와야 한다.
//
// **루트커즈**: `commitFileTreeCandidate` 가 첫 줄에서 선택을 지웠다. 그 함수는 2026-07-20 에 **root 교체
// 전용**으로 태어났고(`220c09dd`), 그때는 호출자가 직후에 같은 clear 를 한 번 더 부르는 중복이었다. 파일
// 열기가 같은 헬퍼를 재사용하면서 **정책만 따라와**, 선택이 사라진 자리에서 `reconcileFileTreeSelection`
// 이 «포커스가 트리에 있으면 첫 행» 규칙으로 떨어져 스크롤이 0 이 됐다.
test "파일을 열어도 트리 선택과 스크롤은 그 자리다 (사용자 보고 2026-08-27)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    // **낮은 창**이다 — 목록이 넘쳐야 «그 자리»라는 말이 성립한다(스크롤이 없으면 offset 은 늘 0 이고
    // 이 테스트는 아무것도 증언하지 못한다).
    _ = try session.resize(1400, 320, 1000);

    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var name_buf: [32]u8 = undefined;
    for (0..60) |i| {
        const name = try std.fmt.bufPrint(&name_buf, "f{d:0>3}.md", .{i});
        try tmp.dir.writeFile(session.io, .{ .sub_path = name, .data = "# x" });
    }
    var tmp_buf: [std.fs.max_path_bytes]u8 = undefined;
    const tmp_root = tmp_buf[0..try tmp.dir.realPath(session.io, &tmp_buf)];
    const root = try allocator.dupe(u8, tmp_root);
    defer allocator.free(root);

    file_panel_ops.requestFileTreeRootPick(session, .replace);
    _ = session.takeFileTreeRootPickRequest();
    file_panel_ops.provideFileTreeRootPick(session, root);
    try testWaitForFileTreeRootCompletion(session);
    file_panel_ops.activateFilePanelDockControl(session);

    // **첫 스캔은 비동기다.** 행이 찰 때까지 재투영을 돌린다 — 안 기다리면 목록이 root 한 줄이라
    // 아래에서 고를 행이 없다.
    var spins: usize = 0;
    const target_index = blk: while (spins < 400) : (spins += 1) {
        // **tick 이 스캔 요청을 backend 에 낸다** — `updateFileTree` 만 돌리면 첫 배치에서 멈춘다.
        _ = session.tick() catch {};
        try file_panel_ops.updateFileTree(session);
        // **목록 끝 근처의 파일**을 고른다. 그 행을 보이게 하려면 실제로 스크롤이 내려가야 한다.
        var last_file: ?usize = null;
        var files_seen: usize = 0;
        for (session.file_tree_rows.items, 0..) |row, i| if (row == .file) {
            files_seen += 1;
            last_file = i;
        };
        if (files_seen >= 6) if (last_file) |i| break :blk i;
        std.Io.sleep(session.io, std.Io.Duration.fromMilliseconds(2), .awake) catch {};
    } else return error.FileTreeScanNeverFilled;

    // 목록 아래쪽 파일을 고른다. **트리에 포커스를 준다** — 사용자가 트리를 눌러 여는 그 상태다.
    file_panel_ops.focusFileTree(session);
    const target_path = try allocator.dupe(u8, maru.session.file_tree.rowPath(session.file_tree_rows.items[target_index]).?);
    defer allocator.free(target_path);
    try std.testing.expect(file_panel_ops.setFileTreeSelection(session, target_index));
    const scrolled = file_panel_ops.fileTreeEffectiveScrollPx(session);
    try std.testing.expect(scrolled > 0); // 그 행을 보이게 하느라 실제로 내려갔다

    // 트리 클릭과 **같은 경로**를 태운다(intent → 선택 → 열기). 여기서 파일이 열리고
    // `commitFileTreeCandidate` 가 돈다.
    file_tree_dock_ops.applyFileTreeIntent(session, .{ .activate_row = @intCast(target_index) });
    // 선택 재조정은 tick 의 일이다 — 사용자가 보는 다음 프레임까지 간다.
    file_panel_ops.reconcileFileTreeSelection(session);

    // ① 선택이 **그 파일에 그대로** 있다. 지워지면 아래 스크롤 단언은 «우연히» 통과할 수 있다.
    const still = file_panel_ops.selectedFileTreeRow(session) orelse return error.SelectionLost;
    const still_path = maru.session.file_tree.rowPath(session.file_tree_rows.items[still]) orelse return error.SelectedRowHasNoPath;
    try std.testing.expectEqualStrings(target_path, still_path);

    // ② 스크롤이 맨 위로 튀지 않았다. 행이 밀려 정확히 같은 px 는 아닐 수 있으므로 **0 이 아님**과
    //    «그 행이 여전히 창 안»을 함께 본다 — 후자가 없으면 1px 만 남아도 통과한다.
    try std.testing.expect(file_panel_ops.fileTreeEffectiveScrollPx(session) > 0);
    const row_h = file_tree_dock_ops.fileTreeRowHeightPx(session);
    const offset = file_panel_ops.fileTreeEffectiveScrollPx(session);
    const viewport = file_panel_ops.fileTreeScrollExtent(session).viewport_h_px;
    const row_top: u64 = @as(u64, still) * @as(u64, row_h);
    try std.testing.expect(row_top + row_h > offset and row_top < @as(u64, offset) + viewport);
}

test "file tree root picker replaces adds repeats and rejects stale completion without touching dirty dock entries" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    try tmp.dir.createDir(session.io, "root-a", .default_dir);
    try tmp.dir.createDir(session.io, "root-b", .default_dir);
    try tmp.dir.createDir(session.io, "root-c", .default_dir);
    try tmp.dir.writeFile(session.io, .{ .sub_path = "outside.md", .data = "# dirty" });
    var tmp_buf: [std.fs.max_path_bytes]u8 = undefined;
    const tmp_root = tmp_buf[0..try tmp.dir.realPath(session.io, &tmp_buf)];
    const root_a = try std.fs.path.join(allocator, &.{ tmp_root, "root-a" });
    defer allocator.free(root_a);
    const root_b = try std.fs.path.join(allocator, &.{ tmp_root, "root-b" });
    defer allocator.free(root_b);
    const root_c = try std.fs.path.join(allocator, &.{ tmp_root, "root-c" });
    defer allocator.free(root_c);
    const outside = try std.fs.path.join(allocator, &.{ tmp_root, "outside.md" });
    defer allocator.free(outside);

    try std.testing.expectEqual(AppSession.FilePanelOpenPathResult.opened, file_panel_ops.openFilePanelPath(session, outside));
    const entry = file_panel_ops.fileEntryForPath(session, outside).?;
    entry.dirty = true;
    entry.external_change = true;
    const entry_id = entry.id;
    const surface_id = entry.surface_id;

    file_panel_ops.requestFileTreeRootPick(session, .replace);
    try std.testing.expectEqual(FileTreeRootOperation.replace, session.takeFileTreeRootPickRequest());
    file_panel_ops.provideFileTreeRootPick(session, root_a);
    try testWaitForFileTreeRootCompletion(session);
    try std.testing.expectEqual(FileTreeRootOutcome.committed_replace, file_panel_ops.fileTreeRootOutcome(session));
    try std.testing.expectEqual(file_tree.RootMode.explicit, session.file_tree.rootMode());
    try std.testing.expectEqualStrings(root_a, session.file_tree.rootAt(0).?);

    file_panel_ops.requestFileTreeRootPick(session, .add);
    try std.testing.expectEqual(FileTreeRootOperation.add, session.takeFileTreeRootPickRequest());
    file_panel_ops.provideFileTreeRootPick(session, root_b);
    try testWaitForFileTreeRootCompletion(session);
    try std.testing.expectEqual(FileTreeRootOutcome.committed_add, file_panel_ops.fileTreeRootOutcome(session));
    try std.testing.expectEqual(@as(usize, 2), session.file_tree.rootCount());

    file_panel_ops.requestFileTreeRootPick(session, .replace);
    try std.testing.expectEqual(FileTreeRootOperation.replace, session.takeFileTreeRootPickRequest());
    file_panel_ops.provideFileTreeRootPick(session, root_c);
    try testWaitForFileTreeRootCompletion(session);
    try std.testing.expectEqual(FileTreeRootOutcome.committed_replace, file_panel_ops.fileTreeRootOutcome(session));
    try std.testing.expectEqual(@as(usize, 1), session.file_tree.rootCount());
    try std.testing.expectEqualStrings(root_c, session.file_tree.rootAt(0).?);

    // A completion issued against C must not publish after an intervening root generation change.
    file_panel_ops.requestFileTreeRootPick(session, .replace);
    try std.testing.expectEqual(FileTreeRootOperation.replace, session.takeFileTreeRootPickRequest());
    file_panel_ops.provideFileTreeRootPick(session, root_a);
    try session.file_tree.replaceExplicitRoots(&.{root_b});
    try testWaitForFileTreeRootCompletion(session);
    try std.testing.expectEqual(FileTreeRootOutcome.stale_generation, file_panel_ops.fileTreeRootOutcome(session));
    try std.testing.expectEqualStrings(root_b, session.file_tree.rootAt(0).?);

    const preserved = file_panel_ops.fileEntryForPath(session, outside).?.*;
    try std.testing.expectEqual(entry_id, preserved.id);
    try std.testing.expectEqual(surface_id, preserved.surface_id);
    try std.testing.expect(preserved.dirty and preserved.external_change);
    var saw_outside_safety_root = false;
    while (session.file_tree.takeWatchRequest()) |watch| {
        defer allocator.free(watch);
        if (std.mem.eql(u8, watch, tmp_root)) saw_outside_safety_root = true;
    }
    try std.testing.expect(saw_outside_safety_root);
}

test "file tree root validation completion projects live dock open close state and watcher safety roots" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    try tmp.dir.createDir(session.io, "initial-root", .default_dir);
    try tmp.dir.createDir(session.io, "selected-root", .default_dir);
    try tmp.dir.createDir(session.io, "closed-parent", .default_dir);
    try tmp.dir.createDir(session.io, "live-parent", .default_dir);
    try tmp.dir.writeFile(session.io, .{ .sub_path = "closed-parent/closed.md", .data = "# closed" });
    try tmp.dir.writeFile(session.io, .{ .sub_path = "live-parent/live.md", .data = "# live" });
    var tmp_buf: [std.fs.max_path_bytes]u8 = undefined;
    const tmp_root = tmp_buf[0..try tmp.dir.realPath(session.io, &tmp_buf)];
    const initial_root = try std.fs.path.join(allocator, &.{ tmp_root, "initial-root" });
    defer allocator.free(initial_root);
    const selected_root = try std.fs.path.join(allocator, &.{ tmp_root, "selected-root" });
    defer allocator.free(selected_root);
    const closed_parent = try std.fs.path.join(allocator, &.{ tmp_root, "closed-parent" });
    defer allocator.free(closed_parent);
    const live_parent = try std.fs.path.join(allocator, &.{ tmp_root, "live-parent" });
    defer allocator.free(live_parent);
    const closed_path = try std.fs.path.join(allocator, &.{ closed_parent, "closed.md" });
    defer allocator.free(closed_path);
    const live_path = try std.fs.path.join(allocator, &.{ live_parent, "live.md" });
    defer allocator.free(live_path);

    try std.testing.expectEqual(AppSession.FilePanelOpenPathResult.opened, file_panel_ops.openFilePanelPath(session, closed_path));
    const closed_surface = file_panel_ops.fileEntryForPath(session, closed_path).?.surface_id;
    // Keep the namespace explicit so opening an outside file during validation does not itself change
    // root_generation and turn this freshness case into the separate stale-generation case.
    try session.file_tree.replaceExplicitRoots(&.{initial_root});
    const validation_generation = session.file_tree.rootGeneration();
    file_panel_ops.requestFileTreeRootPick(session, .replace);
    try std.testing.expectEqual(FileTreeRootOperation.replace, session.takeFileTreeRootPickRequest());
    file_panel_ops.provideFileTreeRootPick(session, selected_root);
    try std.testing.expect(session.file_tree_root_validation != null);

    try std.testing.expect(file_panel_ops.closeFilePanelSurfaceNow(session, closed_surface));
    try std.testing.expectEqual(AppSession.FilePanelOpenPathResult.opened, file_panel_ops.openFilePanelPath(session, live_path));
    try std.testing.expectEqual(validation_generation, session.file_tree.rootGeneration());
    try testWaitForFileTreeRootCompletion(session);

    try std.testing.expectEqual(FileTreeRootOutcome.committed_replace, file_panel_ops.fileTreeRootOutcome(session));
    try std.testing.expectEqual(@as(usize, 1), file_panel_ops.fileEntryCount(session));
    try std.testing.expect(file_panel_ops.fileEntryForPath(session, closed_path) == null);
    try std.testing.expect(file_panel_ops.fileEntryForPath(session, live_path) != null);
    var saw_closed_row = false;
    var saw_live_row = false;
    for (session.file_tree_rows.items) |row| switch (row) {
        .recent_file => |recent| {
            if (std.mem.eql(u8, recent.path, closed_path)) {
                saw_closed_row = true;
                try std.testing.expect(!recent.open);
            } else if (std.mem.eql(u8, recent.path, live_path)) {
                saw_live_row = true;
                try std.testing.expect(recent.open and recent.active);
            }
        },
        else => {},
    };
    try std.testing.expect(saw_closed_row and saw_live_row);

    var saw_selected_root = false;
    var saw_live_safety_root = false;
    var saw_closed_safety_root = false;
    while (session.file_tree.takeWatchRequest()) |watch| {
        defer allocator.free(watch);
        saw_selected_root = saw_selected_root or std.mem.eql(u8, watch, selected_root);
        saw_live_safety_root = saw_live_safety_root or std.mem.eql(u8, watch, live_parent);
        saw_closed_safety_root = saw_closed_safety_root or std.mem.eql(u8, watch, closed_parent);
    }
    try std.testing.expect(saw_selected_root);
    try std.testing.expect(saw_live_safety_root);
    try std.testing.expect(!saw_closed_safety_root);
}

test "file tree는 retained 첫 scan을 게시하고 stale namespace 행 activation을 거부한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    try tmp.dir.createDir(session.io, "selected", .default_dir);
    try tmp.dir.writeFile(session.io, .{ .sub_path = "selected/same.md", .data = "# original" });
    var tmp_buf: [std.fs.max_path_bytes]u8 = undefined;
    const tmp_root = tmp_buf[0..try tmp.dir.realPath(session.io, &tmp_buf)];
    const selected = try std.fs.path.join(allocator, &.{ tmp_root, "selected" });
    defer allocator.free(selected);

    file_panel_ops.requestFileTreeRootPick(session, .replace);
    try std.testing.expectEqual(FileTreeRootOperation.replace, session.takeFileTreeRootPickRequest());
    file_panel_ops.provideFileTreeRootPick(session, selected);

    var attempts: usize = 0;
    while ((session.file_tree_root_validation == null or session.file_tree_root_validation.?.round == 0) and attempts < 2_000) : (attempts += 1) {
        try file_panel_ops.updateFileTree(session);
        std.Io.sleep(session.io, std.Io.Duration.fromMilliseconds(1), .awake) catch {};
    }
    try std.testing.expect(session.file_tree_root_validation != null);
    try std.testing.expectEqual(@as(u8, 1), session.file_tree_root_validation.?.round);
    attempts = 0;
    while (session.file_tree_backend.resultCountForTest() == 0 and attempts < 2_000) : (attempts += 1) {
        std.Io.sleep(session.io, std.Io.Duration.fromMilliseconds(1), .awake) catch {};
    }
    try std.testing.expect(session.file_tree_backend.resultCountForTest() > 0);

    // Round 2 has captured selected's descriptor. Replace the same pathname before AppSession consumes it.
    try tmp.dir.rename("selected", tmp.dir, "moved", session.io);
    try tmp.dir.createDir(session.io, "selected", .default_dir);
    try tmp.dir.writeFile(session.io, .{ .sub_path = "selected/same.md", .data = "# replacement" });
    // **탐색기의 "활성 터미널 따라가기"를 이 구간에서 끈다.** root pick commit이 도크를 펴고
    // (`file_panel.zig`의 committed 갈래가 `dock.presented = true`), **같은 `updateFileTree` 호출** 꼬리에서
    // `followActiveTerminalCwd`가 돈다. 터미널 cwd는 이 임시 root가 **아니라** 테스트 프로세스의 저장소라
    // `followRootSwitch`가 root를 갈아끼우고, 그러면 `same.md`가 영영 안 나와 폴링이 소진된다. 그건 제품이
    // 맞게 동작한 것이지(docs/file-explorer.md §1) 이 테스트의 주제가 아니다.
    //
    // **`dock.collapsed`로는 못 막는다** — 그 commit 갈래가 `collapsed = false`를 함께 쓰므로 미리 세워도
    // 지워지고, commit 뒤에 세우면 이미 같은 호출에서 전환이 끝난 뒤다(첫 시도가 정확히 이래서 CI에서
    // 계속 실패했다). `chrome_minimal`은 그 갈래가 건드리지 않으면서 `dockVisible`을 끄므로 commit을
    // 가로질러 살아남는다. `updateFileTree`는 이 플래그를 보지 않아 결과 소비·행 빌드·감시는 그대로 돈다.
    session.chrome_minimal = true;
    try file_panel_ops.updateFileTree(session);
    try std.testing.expectEqual(FileTreeRootOutcome.committed_replace, file_panel_ops.fileTreeRootOutcome(session));

    var row_index: ?usize = null;
    attempts = 0;
    while (row_index == null and attempts < 2_000) : (attempts += 1) {
        try file_panel_ops.updateFileTree(session);
        for (session.file_tree_rows.items, 0..) |row, index| switch (row) {
            .file => |file| if (std.mem.eql(u8, file.label, "same.md")) {
                row_index = index;
            },
            else => {},
        };
        if (row_index == null) std.Io.sleep(session.io, std.Io.Duration.fromMilliseconds(1), .awake) catch {};
    }
    // **억제가 실제로 걸렸는지 확인한다.** 이게 없으면 "레이스가 이번엔 안 터졌다"와 "전환이 불가능하다"를
    // 구별할 수 없다 — 첫 시도(`dock.collapsed`)가 로컬 5회 통과로 고쳐진 줄 알았다가 CI에서 다시 실패한
    // 이유가 정확히 그것이다. root가 바뀌면 아래 `row_index`가 null인 채로 폴링만 소진돼 **원인이 안 보이는**
    // 실패가 되므로, 원인을 직접 말하는 단언을 먼저 둔다.
    {
        var still_selected = false;
        for (session.file_tree.roots.items) |root| {
            if (std.mem.eql(u8, root.path, selected)) still_selected = true;
        }
        try std.testing.expect(still_selected);
    }
    // 완료 queue의 첫 항목이 validated scan이라는 가정 없이, retained descriptor 결과가 실제 행으로
    // 게시될 때까지 frame 소비를 진행한다. 느린 CI에서 무관한 초기 scan이 먼저 끝나도 같은 계약이다.
    try std.testing.expect(row_index != null);
    file_panel_ops.activateFileTreeRow(session, row_index.?);
    try std.testing.expectEqual(@as(usize, 0), file_panel_ops.fileEntryCount(session));
    try std.testing.expect(session.peekFileTreeExternalOpen() == null);
}

test "file tree markdown activation pins first hydration identity across leaf replacement" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    try tmp.dir.createDir(session.io, "root", .default_dir);
    try tmp.dir.writeFile(session.io, .{ .sub_path = "root/doc.md", .data = "# original" });
    var tmp_buf: [std.fs.max_path_bytes]u8 = undefined;
    const tmp_root = tmp_buf[0..try tmp.dir.realPath(session.io, &tmp_buf)];
    const root = try std.fs.path.join(allocator, &.{ tmp_root, "root" });
    defer allocator.free(root);
    const doc = try std.fs.path.join(allocator, &.{ root, "doc.md" });
    defer allocator.free(doc);
    const root_identity = try testFileTreeIdentity(root);
    const doc_identity = try testFileTreeIdentity(doc);

    try session.file_tree.replaceExplicitRoots(&.{root});
    _ = session.file_tree.pinRootIdentity(root, root_identity);
    const scan = session.file_tree.takeScanRequest().?;
    allocator.free(scan);
    try session.file_tree.applySnapshotWithIdentity(root, .{ .value = root_identity }, &.{.{
        .name = "doc.md",
        .kind = .file,
        .identity = doc_identity,
    }});
    session.file_tree_rows_dirty = true;
    try file_panel_ops.updateFileTree(session);
    const row = file_tree.findIdentity(session.file_tree_rows.items, .{ .kind = .file, .path = doc }).?;
    file_panel_ops.activateFileTreeRow(session, row);
    const entry = file_panel_ops.fileEntryForPath(session, doc).?;
    try std.testing.expect(entry.initial_file_identity_pending);

    try tmp.dir.rename("root/doc.md", tmp.dir, "root/moved.md", session.io);
    try tmp.dir.writeFile(session.io, .{ .sub_path = "root/doc.md", .data = "# replacement" });
    const epoch = try file_panel_ops.beginFilePanelDocument(session, entry.surface_id, 1);
    try std.testing.expectError(error.NotFound, file_panel_ops.readFilePanel(session, allocator, entry.surface_id, epoch));
    try std.testing.expect(entry.initial_file_identity_pending);
}

test "pending file tree root validation rejects merge and workspace restore before either session mutates" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const src = try initSmokeSessionSized(allocator);
    defer allocator.destroy(src);
    defer src.deinit();
    const dst = try initSmokeSessionSized(allocator);
    defer allocator.destroy(dst);
    defer dst.deinit();
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    try tmp.dir.createDir(src.io, "selected-root", .default_dir);
    var tmp_buf: [std.fs.max_path_bytes]u8 = undefined;
    const tmp_root = tmp_buf[0..try tmp.dir.realPath(src.io, &tmp_buf)];
    const selected_root = try std.fs.path.join(allocator, &.{ tmp_root, "selected-root" });
    defer allocator.free(selected_root);

    _ = try pane_ops.openFileTermInActivePane(src, "/tmp/root-pending-src.html", .html);
    _ = try pane_ops.openFileTermInActivePane(dst, "/tmp/root-pending-dst.html", .html);
    file_panel_ops.assignDockSurfaceIds(src);
    file_panel_ops.assignDockSurfaceIds(dst);
    try src.file_tree.replaceExplicitRoots(&.{"/source-before"});
    try dst.file_tree.replaceExplicitRoots(&.{"/destination-before"});

    var arena = std.heap.ArenaAllocator.init(allocator);
    defer arena.deinit();
    var replacement = try workspace_ops.captureWorkspaceWindow(dst, arena.allocator(), false, null);
    const replacement_entries = [_]dock_panel.PersistedEntry{.{
        .path = "/tmp/root-pending-replacement.html",
        .kind = .html,
        .active = true,
    }};
    replacement.dock = .{ .presented = true, .entries = &replacement_entries };

    const src_tab = src.tabs.items[0];
    const dst_tab = dst.tabs.items[0];
    const src_tabs = src.tabs.items.len;
    const dst_tabs = dst.tabs.items.len;
    const src_entries = file_panel_ops.fileEntryCount(src);
    const dst_entries = file_panel_ops.fileEntryCount(dst);
    const src_generation = src.file_tree.rootGeneration();
    const dst_generation = dst.file_tree.rootGeneration();

    file_panel_ops.requestFileTreeRootPick(src, .replace);
    try std.testing.expectEqual(FileTreeRootOperation.replace, src.takeFileTreeRootPickRequest());
    file_panel_ops.provideFileTreeRootPick(src, selected_root);
    try std.testing.expect(src.file_tree_root_validation != null);

    var moved_buf: [16]u64 = undefined;
    try std.testing.expectError(error.UnsupportedMove, src.mergeSessionInto(dst, &moved_buf));
    try std.testing.expectError(error.UnsupportedMove, workspace_ops.applyWorkspaceWindow(src, replacement));

    try std.testing.expect(src.file_tree_root_validation != null);
    try std.testing.expectEqual(src_tabs, src.tabs.items.len);
    try std.testing.expectEqual(dst_tabs, dst.tabs.items.len);
    try std.testing.expectEqual(src_tab, src.tabs.items[0]);
    try std.testing.expectEqual(dst_tab, dst.tabs.items[0]);
    try std.testing.expectEqual(src_entries, file_panel_ops.fileEntryCount(src));
    try std.testing.expectEqual(dst_entries, file_panel_ops.fileEntryCount(dst));
    try std.testing.expectEqual(src_generation, src.file_tree.rootGeneration());
    try std.testing.expectEqual(dst_generation, dst.file_tree.rootGeneration());
    try std.testing.expectEqualStrings("/source-before", src.file_tree.rootAt(0).?);
    try std.testing.expectEqualStrings("/destination-before", dst.file_tree.rootAt(0).?);
    try std.testing.expect(file_panel_ops.fileEntryForPath(src, "/tmp/root-pending-src.html") != null);
    try std.testing.expect(file_panel_ops.fileEntryForPath(dst, "/tmp/root-pending-dst.html") != null);
    try std.testing.expect(file_panel_ops.fileEntryForPath(src, "/tmp/root-pending-replacement.html") == null);
}

test "file tree header and populated blank left click are inert while right click exposes root actions" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    _ = try session.resize(1400, 900, 1000);
    file_panel_ops.activateFilePanelDockControl(session);
    try session.file_tree.replaceExplicitRoots(&.{"/project"});
    session.file_tree_rows_dirty = true;
    try file_panel_ops.updateFileTree(session);
    const content = dock_ops.dockGeometry(session).tree_content;
    try std.testing.expect(session.file_tree_rows.items.len >= 2);

    const header_x: f64 = @floatFromInt(content.x + 2);
    const header_y: f64 = @floatFromInt(content.y + file_tree_dock_ops.fileTreeRowHeightPx(session) + 2);
    session.mouse(1, header_x, header_y, 0, 0);
    try std.testing.expect(!session.takeFilePanelPickRequest());

    const blank_y_px = content.y + @as(u32, @intCast(session.file_tree_rows.items.len)) * file_tree_dock_ops.fileTreeRowHeightPx(session) + 2;
    try std.testing.expect(blank_y_px < content.y + content.h);
    const blank_y: f64 = @floatFromInt(blank_y_px);
    session.mouse(1, header_x, blank_y, 0, 0);
    try std.testing.expect(!session.takeFilePanelPickRequest());

    session.mouse(1, header_x, header_y, 2, 0);
    try std.testing.expect(session.file_tree_background_menu);
    try std.testing.expectEqual(@as(usize, 3), settings_ops.contextMenuItems(session).len);
    session.chrome_host.context_menu.selected = 1;
    settings_ops.acceptContextMenu(session);
    try std.testing.expectEqual(FileTreeRootOperation.replace, session.takeFileTreeRootPickRequest());
    file_panel_ops.provideFileTreeRootPick(session, &.{});

    session.mouse(1, header_x, blank_y, 2, 0);
    try std.testing.expect(session.file_tree_background_menu);
    try std.testing.expectEqualStrings(maru.i18n.t(.ctx_add_folder_to_workspace), settings_ops.contextMenuItems(session)[2]);
    settings_ops.closeContextMenu(session);
}

test "wheel·track click·keyboard가 하나의 스크롤 상태를 이어받고 발행이 그 값을 따른다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    _ = try session.resize(1400, 900, 1000);
    file_panel_ops.activateFilePanelDockControl(session);
    session.file_tree_rows.clearRetainingCapacity();
    try session.file_tree_rows.ensureTotalCapacity(allocator, 512);
    for (0..512) |_| session.file_tree_rows.appendAssumeCapacity(.empty);
    file_panel_ops.refreshDockListScrollbar(session);
    const geometry = dock_ops.dockListScrollbarGeometry(session) orelse return error.SkipZigTest;
    if (geometry.max_offset_px == 0) return error.SkipZigTest;
    const content = dock_ops.dockGeometry(session).tree_content;
    const inside_x: f64 = @floatFromInt(content.x + content.w / 2);
    const inside_y: f64 = @floatFromInt(content.y + content.h / 2);

    // ① wheel — 트리 위에서 굴리면 스크롤 상태가 움직인다. 이 셋은 서로 다른 입구지만 **같은
    //    상태**를 움직여야 한다. 각자 자기 스크롤 위치를 들면 thumb과 내용이 어긋난다.
    try std.testing.expectEqual(@as(u32, 0), file_panel_ops.fileTreeEffectiveScrollPx(session));
    scroll_ops.scrollWheel(session, -5, 0, false, inside_x, inside_y);
    const after_wheel = file_panel_ops.fileTreeEffectiveScrollPx(session);
    try std.testing.expect(after_wheel > 0);

    // ② track click — thumb **밖**을 누르면 그 지점으로 점프한다(드래그가 아니다).
    const track_bottom = geometry.track_y + geometry.track_h - 1;
    try std.testing.expect(dock_ops.beginDockListScrollbarGesture(
        session,
        geometry.track_x + geometry.track_w / 2,
        track_bottom,
    ));
    const after_track = file_panel_ops.fileTreeEffectiveScrollPx(session);
    try std.testing.expect(after_track > after_wheel);
    scroll_ops.endScrollbarCapture(session);

    // ③ **상태 공유** — 앞 두 입구가 올려놓은 값을 keyboard anchor가 이어받는가. 단조 증가만
    //    보면 각 입구가 자기 변수를 들고 있어도 통과한다(마지막에 쓴 쪽이 게터에 반영되므로).
    //    그래서 "이미 온전히 보이는 행을 겨냥하면 아무 것도 움직이지 않는다"를 본다 — anchor가 현재
    //    스크롤을 실제로 읽고 있어야만 성립하는 성질이다. 픽셀 스크롤이라 창의 첫 행은 반쯤 걸쳐
    //    있을 수 있으므로, 그 다음 행부터가 "온전히 보이는" 첫 행이다.
    const first_full_row = (after_track + file_tree_dock_ops.fileTreeRowHeightPx(session) - 1) / file_tree_dock_ops.fileTreeRowHeightPx(session);
    const visible_index = first_full_row + file_panel_ops.fileTreeVisibleRows(session) / 2;
    _ = file_panel_ops.scrollFileTreeRowIntoView(session, visible_index);
    try std.testing.expectEqual(after_track, file_panel_ops.fileTreeEffectiveScrollPx(session));

    // ④ keyboard — 선택이 화면 밖으로 나가면 anchor가 그것을 따라 들어온다.
    _ = file_panel_ops.scrollFileTreeRowIntoView(session, 0);
    try std.testing.expectEqual(@as(u32, 0), file_panel_ops.fileTreeEffectiveScrollPx(session));
    _ = file_panel_ops.scrollFileTreeRowIntoView(session, 500);
    const after_anchor = file_panel_ops.fileTreeEffectiveScrollPx(session);
    try std.testing.expect(after_anchor > 0);

    // ⑤ 그리고 그 상태가 곧 thumb 위치다 — **발행된 tree**가 같은 값에서 나온다(SV2b: 기하를 다시
    //    계산하지 않고 track/thumb entry를 되읽는다).
    file_panel_ops.refreshDockListScrollbar(session);
    const moved = dock_ops.dockListScrollbarGeometry(session).?;
    // scrollArea가 track과 thumb을 자기 preorder 안에서 낸다 — 컨테이너까지 셋이다.
    try std.testing.expectEqual(@as(usize, 3), session.dock_list_scroll_entry_count);
    // thumb이 track 시작보다 아래에 있다 — 스크롤 상태가 발행에 반영됐다는 뜻이다.
    try std.testing.expect(moved.thumb_y > moved.track_y);
    // 그리고 그 위치는 offset의 함수다: 맨 위로 되돌리면 thumb도 track 상단으로 붙는다.
    file_panel_ops.setFileTreeScrollOffsetPx(session, 0);
    const at_top = dock_ops.dockListScrollbarGeometry(session).?;
    try std.testing.expectApproxEqAbs(at_top.track_y, at_top.thumb_y, 0.01);
}

test "두 세대가 그대로여도 track/thumb 기하가 바뀌면 스크롤 드래그를 놓는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    _ = try session.resize(1400, 900, 1000);
    file_panel_ops.activateFilePanelDockControl(session);
    session.file_tree_rows.clearRetainingCapacity();
    try session.file_tree_rows.ensureTotalCapacity(allocator, 512);
    for (0..512) |_| session.file_tree_rows.appendAssumeCapacity(.empty);
    file_panel_ops.refreshDockListScrollbar(session);
    const geometry = dock_ops.dockListScrollbarGeometry(session) orelse return error.SkipZigTest;
    if (geometry.max_offset_px == 0) return error.SkipZigTest;

    try std.testing.expect(dock_ops.beginDockListScrollbarGesture(session, geometry.track_x, geometry.thumb_y));
    try std.testing.expect(scroll_ops.scrollbarCaptureActive(session));

    // 세대는 둘 다 그대로 두고 기하만 바꾼다. carry key는 host가 주입한 값의 동등성만 보므로
    // 이 축은 key로 표현되지 않는다 — down 시점 기하로 계산한 스크롤이 손가락과 어긋나기 전에
    // domain 검증이 놓아야 한다.
    const root_before = session.file_tree.rootGeneration();
    const projection_before = session.file_tree_projection_generation;
    session.dock_list_scroll_drag.geometry.track_h += 40;
    session.dock_list_scroll_drag.geometry.thumb_h += 8;
    try std.testing.expectEqual(root_before, session.file_tree.rootGeneration());
    try std.testing.expectEqual(projection_before, session.file_tree_projection_generation);

    _ = scroll_ops.routeScrollbarCapture(session, 2, geometry.track_y + geometry.track_h - 1);
    try std.testing.expect(!scroll_ops.scrollbarCaptureActive(session));
}

// 계약 §4.3의 coalescing은 "move를 모아 **tick이** 적용한다"이지 "up에서 한 번 적용한다"가 아니다.
// `tick`이 scrollbar coalescer를 소비하지 않아, thumb을 끄는 동안에는 화면이 그대로이고 손을 떼야
// 한 번에 움직였다(제보) — 같은 패턴을 쓰는 divider는 매 tick 반영되는데 스크롤만 달랐다.
// 이 fixture는 `applyPendingScrollbarScroll`을 **손으로 부르지 않는다**. 그 호출이 기존 테스트를
// 통과시키면서 제품 경로의 누락을 가리고 있었다 — tick만 돌려 제품이 실제로 소비하는지를 본다.
test "파일 트리 스크롤바 드래그는 손을 떼기 전에 tick이 적용한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    _ = try session.resize(1400, 900, 1000);
    file_panel_ops.activateFilePanelDockControl(session);

    session.file_tree_rows.clearRetainingCapacity();
    try session.file_tree_rows.ensureTotalCapacity(allocator, 512);
    for (0..512) |_| session.file_tree_rows.appendAssumeCapacity(.empty);
    file_panel_ops.refreshDockListScrollbar(session);
    const top = dock_ops.dockListScrollbarGeometry(session).?;

    // 트랙 하단을 눌러 아래로 스크롤한 상태에서 드래그를 시작한다(down 자체는 즉시 적용).
    try std.testing.expect(dock_ops.beginDockListScrollbarGesture(
        session,
        top.track_x + top.track_w / 2,
        top.track_y + top.track_h - 1,
    ));
    try std.testing.expect(scroll_ops.scrollbarCaptureActive(session));
    try std.testing.expect(file_panel_ops.fileTreeEffectiveScrollPx(session) > 0);

    // thumb을 맨 위로 끈다. move는 좌표만 모으므로 이 시점엔 아직 그대로다.
    _ = scroll_ops.routeScrollbarCapture(session, 2, top.track_y);
    try std.testing.expect(file_panel_ops.fileTreeEffectiveScrollPx(session) > 0);

    // **손을 떼지 않은 채**(up=kind 3을 보내지 않고) tick 한 번 — 여기서 적용돼야 한다. 이 fixture의 축은
    // "up 없이도 적용되는가"이지 capture 수명이 아니다(그쪽은 stale-snapshot cancel 테스트가 소유한다).
    _ = try session.tick();
    try std.testing.expectEqual(@as(u32, 0), file_panel_ops.fileTreeEffectiveScrollPx(session));
    scroll_ops.endScrollbarCapture(session);
}

// SV2b — 탐색기 스크롤바가 공용 ScrollArea 경로로 넘어간 것을 고정한다. 옛 구조는 **별도 tree**
// (`file_tree_scrollbar.publish`)가 hit을 내고 host가 quad를 손으로 만들었다. 그 둘이 갈리면 "보이는
// 곳과 눌리는 곳이 다른" 결함이 되고, 그것이 이 이관의 이유다.
test "file tree scrollbar publishes one tree that paint and hit-test both read" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    _ = try session.resize(1400, 900, 1000);
    file_panel_ops.activateFilePanelDockControl(session);
    session.file_tree_rows.clearRetainingCapacity();
    try session.file_tree_rows.ensureTotalCapacity(allocator, 512);
    for (0..512) |_| session.file_tree_rows.appendAssumeCapacity(.empty);
    file_panel_ops.refreshDockListScrollbar(session);

    // ① 발행은 `scrollArea` 하나에서 나온다 — 컨테이너 + track + thumb.
    try std.testing.expectEqual(@as(usize, 3), session.dock_list_scroll_entry_count);
    const geometry = dock_ops.dockListScrollbarGeometry(session) orelse return error.FileTreeFixtureHasNoScrollbar;

    // ② **track이 thumb보다 먼저다.** `interaction.hitAction`이 reverse z-order라, 뒤집히면 thumb 위
    //    down이 track click으로 판정돼 드래그 대신 점프가 일어난다.
    var track_index: ?usize = null;
    var thumb_index: ?usize = null;
    for (session.dock_list_scroll_entries[0..session.dock_list_scroll_entry_count], 0..) |entry, i| {
        if (entry.id == dock_list_scroll_ids.track) track_index = i;
        if (entry.id == dock_list_scroll_ids.thumb) thumb_index = i;
    }
    try std.testing.expect(track_index.? < thumb_index.?);

    // ③ 그 rect가 **backing 좌표**다 — 컨테이너 로컬로 두면 hit이 도크 왼쪽 위로 밀린다.
    const content = dock_ops.dockGeometry(session).tree_content;
    try std.testing.expect(geometry.track_x >= @as(f32, @floatFromInt(content.x)));
    try std.testing.expectApproxEqAbs(@as(f32, @floatFromInt(content.y)), geometry.track_y, 0.01);

    // ④ gutter가 트랙을 **자기 폭 안에** 담는다: 트랙 오른쪽 변이 컨테이너를 넘지 않는다.
    try std.testing.expect(geometry.track_x + geometry.track_w <= @as(f32, @floatFromInt(content.x + content.w)));
    // 그리고 텍스트 폭은 gutter만큼 줄어 있다 — 그 둘이 겹치지 않는다는 뜻이다.
    try std.testing.expectEqual(content.w - dock_ops.dockListScrollGutterPx(session), dock_ops.dockListTextWidthPx(session));
    try std.testing.expect(@as(f32, @floatFromInt(content.x + dock_ops.dockListTextWidthPx(session))) <= geometry.track_x);

    // ⑤ **paint가 그 tree에서 나온다.** host가 기하를 다시 만들면 이 단언은 통과하면서 화면만 어긋난다.
    session.gpu_quads.clearRetainingCapacity();
    dock_ops.appendDockListScrollbar(session);
    try std.testing.expectEqual(@as(usize, 2), session.gpu_quads.items.len); // track + thumb
    var saw_thumb = false;
    for (session.gpu_quads.items) |quad| {
        // 스크롤바는 밴드와 같은 버킷(layer 2)이다 — 이 값이 바뀌면 z 규칙이 통째로 달라진다.
        try std.testing.expectEqual(@as(u32, 2), quad.layer);
        // `ui_paint`가 rect를 정수 픽셀로 스냅하므로 1px 안쪽에서 만난다(원본 track_x는 gutter 중앙이라 .5).
        try std.testing.expectApproxEqAbs(geometry.track_x, quad.x, 1.0);
        // 스냅 오차 1px 안에서 thumb을 알아본다 — track은 뷰포트 전체 높이라 두 quad가 섞이지 않는다.
        if (@abs(quad.y - geometry.thumb_y) <= 1.0 and @abs(quad.h - geometry.thumb_h) <= 1.0) saw_thumb = true;
    }
    try std.testing.expect(saw_thumb);
}

// 스크롤바가 layer 2로 내려오면서 행 하이라이트 밴드와 **같은 버킷**이 됐다. 그 안에서는 배열 순서가
// painter 순서이므로, 밴드가 뒤에 오면 밴드가 thumb을 덮는다. 폭을 gutter 앞에서 끊은 것과 순서를
// 뒤로 둔 것 둘 다 필요하다 — 하나만으로는 나중에 다른 쪽이 바뀔 때 조용히 가려진다.
test "file tree scrollbar is painted after the row band and never under it" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    _ = try session.resize(1400, 900, 1000);
    file_panel_ops.activateFilePanelDockControl(session);
    session.file_tree_rows.clearRetainingCapacity();
    for (0..512) |_| try session.file_tree_rows.append(allocator, .{ .file = .{
        .path = "/repo/src/main.zig",
        .label = "main.zig",
        .depth = 1,
        .supported = true,
        .open = false,
        .active = false,
        .dirty = false,
        .external_change = false,
        .symlink = false,
    } });
    _ = file_panel_ops.setFileTreeSelection(session, 0); // 밴드가 나오도록 한 행을 선택한다
    file_panel_ops.refreshDockListScrollbar(session);
    const geometry = dock_ops.dockListScrollbarGeometry(session) orelse return error.FileTreeFixtureHasNoScrollbar;
    const content = dock_ops.dockGeometry(session).tree_content;

    // 밴드는 gutter **앞에서** 끝난다 — 트랙 위로 넘어오지 않는다.
    session.gpu_quads.clearRetainingCapacity();
    session.appendClippedBarBgQuad(.{
        .x = content.x,
        .y = content.y,
        .w = dock_ops.dockListTextWidthPx(session),
        .h = session.cell_height_px,
    }, 0xFF00FF00, content);
    const band_end = session.gpu_quads.items[0].x + session.gpu_quads.items[0].w;
    try std.testing.expect(band_end <= geometry.track_x);

    // 그리고 스크롤바가 **그 뒤에** 온다(같은 버킷에서 나중이 위다).
    dock_ops.appendDockListScrollbar(session);
    try std.testing.expect(session.gpu_quads.items.len > 1);
    for (session.gpu_quads.items[1..]) |quad| try std.testing.expectEqual(@as(u32, 2), quad.layer);
}

test "file tree scrollbar is overflow-only and stale drag snapshots cancel" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    _ = try session.resize(1400, 900, 1000);
    file_panel_ops.activateFilePanelDockControl(session);

    session.file_tree_rows.clearRetainingCapacity();
    try session.file_tree_rows.ensureTotalCapacity(allocator, 512);
    for (0..512) |_| session.file_tree_rows.appendAssumeCapacity(.empty);
    file_panel_ops.refreshDockListScrollbar(session);
    const top = dock_ops.dockListScrollbarGeometry(session).?;
    try std.testing.expectApproxEqAbs(top.track_y, top.thumb_y, 0.01); // 맨 위
    const tree_content = dock_ops.dockGeometry(session).tree_content;
    // gutter가 트랙 자리를 상시 비워 둔다(SV2b) — 마지막 텍스트 칸의 오른쪽 끝이 트랙 왼쪽 변을
    // 넘지 않는다. 예전에는 `reservedColumns`가 **셀 단위로** 빼서 셀 폭에 따라 예약량이 달라졌다.
    const content_cols = dock_ops.dockListTextWidthPx(session) / session.cell_width_px;
    const last_content_right = tree_content.x + content_cols * session.cell_width_px;
    try std.testing.expect(@as(f32, @floatFromInt(last_content_right)) <= top.track_x);
    try std.testing.expect(dock_ops.beginDockListScrollbarGesture(
        session,
        top.track_x + top.track_w / 2,
        top.track_y + top.track_h - 1,
    ));
    try std.testing.expect(scroll_ops.scrollbarCaptureActive(session));
    try std.testing.expect(file_panel_ops.fileTreeEffectiveScrollPx(session) > 0);
    // move는 좌표만 모으고 tick이 적용한다(계약 §4.3) — 옛 경로는 move가 곧 재투영이었다.
    _ = scroll_ops.routeScrollbarCapture(session, 2, top.track_y);
    scroll_ops.applyPendingScrollbarScroll(session);
    try std.testing.expectEqual(@as(u32, 0), file_panel_ops.fileTreeEffectiveScrollPx(session));
    _ = scroll_ops.routeScrollbarCapture(session, 2, std.math.nan(f64));
    scroll_ops.applyPendingScrollbarScroll(session);
    try std.testing.expectEqual(@as(u32, 0), file_panel_ops.fileTreeEffectiveScrollPx(session));

    // Root authority is part of the drag snapshot. A late move after replacement must not commit.
    const restarted = dock_ops.dockListScrollbarGeometry(session).?;
    try std.testing.expect(dock_ops.beginDockListScrollbarGesture(session, restarted.track_x, restarted.thumb_y));
    try session.file_tree.replaceExplicitRoots(&.{"/different"});
    _ = scroll_ops.routeScrollbarCapture(session, 2, top.track_y + top.track_h);
    try std.testing.expect(!scroll_ops.scrollbarCaptureActive(session));
    try std.testing.expectEqual(@as(u32, 0), file_panel_ops.fileTreeEffectiveScrollPx(session));

    file_panel_ops.refreshDockListScrollbar(session);
    const current = dock_ops.dockListScrollbarGeometry(session).?;
    try std.testing.expect(dock_ops.beginDockListScrollbarGesture(session, current.track_x, current.thumb_y));
    file_panel_ops.advanceFileTreeProjectionGeneration(session);
    try std.testing.expect(session.pointerGestureIs(.none));

    session.file_tree_rows.clearRetainingCapacity();
    session.file_tree_rows.appendAssumeCapacity(.empty);
    file_panel_ops.refreshDockListScrollbar(session);
    try std.testing.expect(dock_ops.dockListScrollbarGeometry(session) == null);
}

/// 창이 뷰포트를 **덮되 최소한**임을 본다 — 이것이 `fileTreeDrawWindow`의 올림 계약이다. 개수를
/// 산술로 다시 적는 대신 성질로 판정한다: 복제한 산술은 그것이 판정해야 할 호출부와 함께 틀린다.
fn expectWindowCoversViewport(count: u16, shift_px: u32, cell_h: u32, viewport_h: u32) !void {
    const covered = @as(u32, count) * cell_h;
    try std.testing.expect(covered >= viewport_h + shift_px); // 바닥에 빈 띠가 남지 않는다
    try std.testing.expect((covered -| cell_h) < viewport_h + shift_px); // 안 보이는 행을 그리지 않는다
}

// SV2a — 탐색기 스크롤의 판정자. SV2-0이 세운 계약을 픽셀 좌표로 옮긴 것이고, **뒤집힌 항이 있다**:
// 예전에는 "바닥 부분 행은 그려지지 않는다"가 계약이었다(행 index 스크롤의 결과였다). 이제는 그
// 부분 행을 그리고 pane clip이 자르는 것이 계약이며, 아래 ②가 그 반전을 명시적으로 박는다.
test "file tree pixel window is one arithmetic shared by follow, clamp, hit-test, and render" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    file_panel_ops.activateFilePanelDockControl(session);

    // **뷰포트가 셀 높이의 배수면 이 테스트는 아무것도 판정하지 못한다** — 부분 행 단언이 통째로
    // 무의미해진다(§10.1 "단언이 판정할 수 있는 상태인지 본다"). 나머지가 0이 아닌 창 높이를 찾고,
    // 못 찾으면 통과시키지 않는다.
    var picked_remainder: u32 = 0;
    for (0..64) |bump| {
        _ = try session.resize(1400, 900 + @as(u32, @intCast(bump)), 1000);
        // **행 높이는 셀이 아니라 컴포넌트가 소유한다**(FT1). 여기서 셀 높이로 나머지를 고르면
        // 부분 행 전제가 실제 행 높이와 무관해져, 이 테스트가 판정한다고 믿는 상태에 도달하지 못한다.
        if (file_tree_dock_ops.fileTreeRowHeightPx(session) == 0) continue;
        const h = dock_ops.dockGeometry(session).tree_content.h;
        picked_remainder = h % file_tree_dock_ops.fileTreeRowHeightPx(session);
        if (picked_remainder != 0) break;
    }
    if (picked_remainder == 0) return error.FileTreeFixtureCannotJudgePartialRow;

    const tree = dock_ops.dockGeometry(session).tree_content;
    const cell_h = file_tree_dock_ops.fileTreeRowHeightPx(session);
    const visible = file_panel_ops.fileTreeVisibleRows(session);
    const remainder = picked_remainder;

    // ① `fileTreeVisibleRows`는 여전히 내림이다 — 그것이 Page 키의 단위다(온전히 보이는 행).
    try std.testing.expectEqual(tree.h / cell_h, visible);
    try std.testing.expect(visible * cell_h < tree.h);
    try std.testing.expect(tree.h - visible * cell_h == remainder);

    // 창의 **세 배**를 채운다. 창 하나를 겨우 넘기면 아래 ⑨의 "위로 따라가기"가 상한에 먼저 눌려
    // 아무것도 판정하지 못한다(그 상태로도 통과하던 단언이 실제로 있었다).
    session.file_tree_rows.clearRetainingCapacity();
    for (0..visible * 3) |_| try session.file_tree_rows.append(allocator, .{ .file = .{
        .path = "/repo/src/main.zig",
        .label = "main.zig",
        .depth = 1,
        .supported = true,
        .open = false,
        .active = false,
        .dirty = false,
        .external_change = false,
        .symlink = false,
    } });
    session.file_tree_scroll.reset();
    file_panel_ops.refreshDockListScrollbar(session);

    // ② **바닥 부분 행을 그린다**(SV2-0에서 뒤집힌 계약). 창은 뷰포트를 덮을 만큼 올림이고, 그
    //    부분 행은 hit-test에서도 살아 있다 — 보이는 것을 클릭할 수 있어야 한다.
    const window_top = file_panel_ops.fileTreeDrawWindow(session);
    try std.testing.expectEqual(@as(usize, 0), window_top.start);
    try std.testing.expectEqual(@as(u32, 0), window_top.origin_shift_px);
    // 창은 뷰포트를 **덮되 최소한**이다. 이 두 성질이 곧 "올림"이며, 개수를 산술로 다시 적으면
    // 호출부의 산술을 복제할 뿐 판정하지 못한다. 행 index 시절의 창(내림)보다 하나 크다는 것이
    // 뒤집힌 계약의 표시다.
    try expectWindowCoversViewport(window_top.count, window_top.origin_shift_px, cell_h, tree.h);
    try std.testing.expect(window_top.count > visible);

    const x: f64 = @floatFromInt(tree.x + 1);
    const inside_y: f64 = @floatFromInt(tree.y + (visible - 1) * cell_h + cell_h / 2);
    try std.testing.expectEqual(@as(?usize, visible - 1), file_panel_ops.fileTreeRowAt(session, x, inside_y));
    const partial_y: f64 = @floatFromInt(tree.y + visible * cell_h + remainder / 2);
    try std.testing.expectEqual(@as(?usize, visible), file_panel_ops.fileTreeRowAt(session, x, partial_y));

    // ③ 스크롤은 **content 바닥이 뷰포트 바닥에 붙는 지점**까지 간다. 행 index 시절에는 마지막 행
    //    아래에 나머지 픽셀만큼 배경이 남았다 — 그 상한이 픽셀로 바뀐 것이 이 슬라이스의 본체다.
    const rows_len = session.file_tree_rows.items.len;
    session.file_tree_scroll.offset_y_px = std.math.maxInt(u32);
    try std.testing.expectEqual(
        @as(u32, @intCast(rows_len)) * cell_h - tree.h,
        file_panel_ops.fileTreeEffectiveScrollPx(session),
    );
    // 바닥에 닿았으면 뷰포트 마지막 픽셀이 **마지막 행**이다(행 index 시절엔 그 자리가 배경이었다).
    const bottom_y: f64 = @floatFromInt(tree.y + tree.h - 1);
    try std.testing.expectEqual(@as(?usize, rows_len - 1), file_panel_ops.fileTreeRowAt(session, x, bottom_y));

    // ④ 창의 세 값이 서로 맞물린다. 부분 offset(행 경계가 아닌 자리)에서 봐야 판정이 된다.
    const half = cell_h / 2;
    if (half == 0) return error.FileTreeFixtureCannotJudgePartialRow;
    session.file_tree_scroll.offset_y_px = 3 * cell_h + half;
    {
        const window = file_panel_ops.fileTreeDrawWindow(session);
        try std.testing.expectEqual(@as(usize, 3), window.start);
        try std.testing.expectEqual(half, window.origin_shift_px);
        // 위로 half만큼 밀렸어도 창은 여전히 뷰포트를 덮되 최소한이다.
        try expectWindowCoversViewport(window.count, window.origin_shift_px, cell_h, tree.h);

        // hit-test가 **같은 창**을 본다: 뷰포트 첫 픽셀은 반쯤 잘린 그 행(index 3)이다.
        try std.testing.expectEqual(@as(?usize, 3), file_panel_ops.fileTreeRowAt(session, x, @floatFromInt(tree.y)));
        // 그 행이 끝나는 지점 바로 아래는 다음 행이다.
        const next_row_y: f64 = @floatFromInt(tree.y + (cell_h - half));
        try std.testing.expectEqual(@as(?usize, 4), file_panel_ops.fileTreeRowAt(session, x, next_row_y));
    }

    // ⑤ 나눗셈으로 만든 이 창이 `scroll_area.project`의 walk와 **같은 답**이어야 한다. 탐색기는 행
    //    높이가 균일해 나눗셈을 쓰지만(수천 행 × 매 프레임), 그것이 공용 좌표계의 특수화라는 것은
    //    말이 아니라 판정으로 고정한다 — 갈라지면 도크와 탐색기가 다른 스크롤 의미를 갖게 된다.
    {
        const Uniform = struct {
            h: u32,
            fn heightPx(self: @This(), _: usize) u32 {
                return self.h;
            }
        };
        const window = file_panel_ops.fileTreeDrawWindow(session);
        const projected = chrome.ui.scroll_area.project(
            Uniform{ .h = cell_h },
            Uniform.heightPx,
            .{ .count = rows_len, .gap_px = 0, .viewport_h_px = tree.h },
            file_panel_ops.fileTreeEffectiveScrollPx(session),
        );
        try std.testing.expectEqual(projected.first_index, window.start);
        try std.testing.expectEqual(@as(u16, @intCast(projected.end_exclusive - projected.first_index)), window.count);
        // project의 원점 편향은 음수 local y이고, 창의 shift는 그 절댓값이다.
        try std.testing.expectEqual(@as(i32, -@as(i32, @intCast(window.origin_shift_px))), projected.first_origin_y_px);
        try std.testing.expectEqual(file_panel_ops.fileTreeEffectiveScrollPx(session), projected.offset_y_px);
        try std.testing.expectEqual(file_panel_ops.fileTreeScrollExtent(session).max_offset_px, projected.max_offset_px);
    }

    // ⑥ **렌더가 그 창을 실제로 쓴다.** 위의 것들은 host 산술이라, 렌더가 다른 수를 쓰면 전부 통과하면서
    //    화면만 어긋난다.
    //
    //    **이 단언은 한 번 죽은 적이 있다(적대적 검증).** FT1 이 행 렌더를 컴포넌트로 옮긴 뒤에도 여기는
    //    옛 셀 draw list(`buildFileTreeDrawList`)를 계속 만들어 검사했다 — 제품이 더 이상 안 쓰는 경로다.
    //    이름은 "렌더"라고 적혀 있는데 실제 렌더는 아무도 안 보는 상태였고, 그런 테스트는 초록인 채로
    //    거짓이다. 그래서 **제품이 그리는 그 컴포넌트**로 바꾼다.
    // **행 높이의 정확한 배수로 굴리면 이 블록이 아무것도 판정하지 못한다** — `origin_shift_px`가 0이 되어
    // 아래 "위로 밀린 만큼 올라간다" 단언이 `0 == 0`이 된다(뮤테이션으로 확인: 컴포넌트에서 평행이동을
    // 통째로 지워도 통과했다). 배수가 **아닌** 자리로 굴리고, 그 전제를 먼저 단언한다.
    session.file_tree_scroll.offset_y_px = 3 * cell_h + cell_h / 3;
    {
        // 행마다 라벨을 다르게 준다 — 같으면 "어느 행을 그렸는지"를 판정할 수 없고 개수만 보게 된다.
        var labels: std.ArrayList([]u8) = .empty;
        defer {
            for (labels.items) |owned| allocator.free(owned);
            labels.deinit(allocator);
        }
        for (session.file_tree_rows.items, 0..) |*row, index| {
            const owned = try std.fmt.allocPrint(allocator, "row{d}.zig", .{index});
            try labels.append(allocator, owned);
            row.file.label = owned;
        }

        const window = file_panel_ops.fileTreeDrawWindow(session);
        try std.testing.expectEqual(file_panel_ops.fileTreeEffectiveScrollPx(session) / cell_h, window.start);
        // 전제: 부분 행이 실제로 생겼다. 이게 0이면 아래 단언들이 조용히 무의미해진다.
        try std.testing.expect(window.origin_shift_px > 0);

        const component = chrome.components.file_tree;
        var rows_buf: [64]component.types.Row = undefined;
        if (window.count > rows_buf.len) return error.FileTreeFixtureWindowTooLarge;
        for (0..window.count) |offset| {
            rows_buf[offset] = .{
                .kind = .file,
                .label = session.file_tree_rows.items[window.start + offset].file.label,
                .icon_kind = @intFromEnum(chrome.file_tree_icon.IconKind.code),
            };
        }
        const props = component.types.Props{
            .viewport_px = .{ .width = @floatFromInt(dock_ops.dockListTextWidthPx(session)), .height = @floatFromInt(tree.h) },
            .scale_milli = file_tree_dock_ops.fileTreeScaleMilli(session),
            .rows = rows_buf[0..window.count],
            .origin_shift_px = window.origin_shift_px,
        };
        var nodes: [96]chrome.ui.tree.UiNode = undefined;
        var entries: [96]chrome.ui.tree.RectEntry = undefined;
        var items: [96]chrome.ui.layout.Item = undefined;
        var flex: [96]chrome.ui.layout.FlexScratch = undefined;
        var child_rects: [96]chrome.ui.layout.UiRect = undefined;
        var actions: [96]component.ids.Entry = undefined;
        const frame = try component.build.build(props, .{
            .nodes = &nodes,
            .entries = &entries,
            .layout_items = &items,
            .flex_scratch = &flex,
            .child_rects = &child_rects,
            .actions = &actions,
        });

        // 창의 첫 행은 뷰포트 위로 **정확히 밀린 만큼** 올라가 있다. 이 값이 0이면 부분 행이 사라지고
        // 목록이 셀 경계로 스냅한다(옛 행 좌표 시절의 모습).
        const first = frame.tree.entries[frame.tree.find(component.build.NodeIds.row(0)).?];
        try std.testing.expectEqual(-@as(f32, @floatFromInt(window.origin_shift_px)), first.rect.y);

        // **행 배치 법칙**: i번째 행의 top은 정확히 `-shift + i*row_h`다. 컴포넌트가 평행이동을 빠뜨리거나
        // 행 높이를 다른 값으로 잡으면 여기서 죽는다.
        const row_h_px = file_tree_dock_ops.fileTreeRowHeightPx(session);
        for (0..window.count) |i| {
            const entry = frame.tree.entries[frame.tree.find(component.build.NodeIds.row(i)).?];
            const want_y = -@as(f32, @floatFromInt(window.origin_shift_px)) + @as(f32, @floatFromInt(i * row_h_px));
            try std.testing.expectEqual(want_y, entry.rect.y);
            try std.testing.expectEqual(@as(f32, @floatFromInt(row_h_px)), entry.rect.height);
        }
        // 그리고 그 창이 뷰포트를 **덮는다**(host 산술 — 하나 덜 그리면 바닥에 빈 띠가 남는다).
        try std.testing.expect(window.count * row_h_px >= tree.h + window.origin_shift_px);

        // 그리고 **그 창의 첫 행 라벨**이 실제로 그려진다. 개수만 맞고 다른 행을 그리면 여기서 죽는다.
        var ops: [1024]chrome.draw.Op = undefined;
        var runs: [256]chrome.draw.Run = undefined;
        var text_bytes: [8192]u8 = undefined;
        const tk = session.buildChromeTokens();
        const draws = try component.view.view(props, frame, .{}, &tk, .{ .ops = &ops, .runs = &runs, .text_bytes = &text_bytes });
        var expect_label: [32]u8 = undefined;
        const want = try std.fmt.bufPrint(&expect_label, "row{d}.zig", .{window.start});
        var saw_first_row_label = false;
        for (draws.ops) |op| {
            if (op != .text or op.text.placement != .origin) continue;
            if (@as(f32, @floatFromInt(op.text.origin.y)) < first.rect.y) continue;
            if (@as(f32, @floatFromInt(op.text.origin.y)) >= first.rect.y + first.rect.height) continue;
            for (op.text.runs) |run| {
                if (std.mem.eql(u8, run.text, want)) saw_first_row_label = true;
            }
        }
        try std.testing.expect(saw_first_row_label);
    }

    // ⑦ hit-test의 **경계**도 본다. 위 ②는 창 안쪽만 찍어 봐서, rect 밖·스크롤바 트랙 위·셀 높이 0을
    //    아무도 판정하지 않았다(적대적 검증에서 셋 다 살아남았다). 셋 다 "행이 아닌 곳을 클릭했는데
    //    행이 선택된다"는 같은 결함으로 이어진다.
    session.file_tree_scroll.reset();
    {
        // rect 위쪽 밖.
        try std.testing.expect(file_panel_ops.fileTreeRowAt(session, x, @floatFromInt(tree.y -| 2)) == null);
        // rect 왼쪽 밖.
        try std.testing.expect(file_panel_ops.fileTreeRowAt(session, @floatFromInt(tree.x -| 2), inside_y) == null);
        // rect 오른쪽/아래 밖. 위·왼쪽만 보면 `pointInRect`를 반쪽만 써도 통과한다(적대적 검증).
        try std.testing.expect(file_panel_ops.fileTreeRowAt(session, @floatFromInt(tree.x + tree.w + 2), inside_y) == null);
        try std.testing.expect(file_panel_ops.fileTreeRowAt(session, x, @floatFromInt(tree.y + tree.h + 2)) == null);
        // 스크롤바 트랙 위 — 목록이 넘치므로 트랙이 있다.
        const bar = dock_ops.dockListScrollbarGeometry(session) orelse return error.FileTreeFixtureHasNoScrollbar;
        const track_x: f64 = bar.track_x + bar.track_w / 2;
        const track_y: f64 = bar.track_y + bar.track_h / 2;
        try std.testing.expect(bar.trackContains(track_x, track_y));
        try std.testing.expect(file_panel_ops.fileTreeRowAt(session, track_x, track_y) == null);
    }

    // ⑧ **렌더 메트릭이 없으면 창도 0이다.** 행 높이 자체는 이제 셀과 무관하지만(FT1 — 컴포넌트
    //    `Metrics`), "아직 그릴 수 없다"는 게이트는 `fileTreeRowHeightPx` 한 곳이 소유하고 0을 낸다.
    //    그 게이트가 없으면 폰트가 없는 첫 스냅샷에서 없는 행을 그리려 든다.
    {
        const saved = session.cell_height_px;
        session.cell_height_px = 0;
        try std.testing.expectEqual(@as(usize, 0), file_panel_ops.fileTreeVisibleRows(session));
        try std.testing.expectEqual(@as(u16, 0), file_panel_ops.fileTreeDrawWindow(session).count);
        try std.testing.expect(file_panel_ops.fileTreeRowAt(session, x, inside_y) == null);
        session.cell_height_px = saved;
    }

    // ⑨ **follow가 같은 좌표계를 본다.** 창 아래에 있는 행을 따라가면 그 행이 뷰포트 바닥에 **정확히**
    //    붙어야 한다 — 행 index 시절에는 그 아래 나머지 픽셀만큼 어긋났다.
    session.file_tree_scroll.reset();
    {
        const target_index = visible + 3;
        // fixture의 행 경로가 전부 같으면 follow가 **첫 행**을 찾아 스크롤이 안 일어난다 — 그러면 이
        // 단언이 무엇도 고정하지 못한다. 대상 행만 고유 경로로 만든다.
        const followed = try allocator.dupe(u8, "/repo/src/follow-target.zig");
        defer allocator.free(followed);
        session.file_tree_rows.items[target_index].file.path = followed;
        session.file_tree_followed_cwd = followed;
        session.file_tree_follow_scroll_pending = true;
        file_panel_ops.scrollFileTreeToFollowedCwd(session);
        try std.testing.expectEqual(
            @as(u32, @intCast(target_index + 1)) * cell_h - tree.h,
            file_panel_ops.fileTreeEffectiveScrollPx(session),
        );

        // **위로도 따라간다.** 아래로 가는 분기만 보면 위 분기를 통째로 지워도 통과한다(적대적 검증).
        // 창 **위**에 있는 행을 따라가면 그 행의 top이 뷰포트 top에 온다.
        session.file_tree_scroll.offset_y_px = @as(u32, @intCast(target_index + 5)) * cell_h;
        session.file_tree_follow_scroll_pending = true;
        file_panel_ops.scrollFileTreeToFollowedCwd(session);
        try std.testing.expectEqual(@as(u32, @intCast(target_index)) * cell_h, file_panel_ops.fileTreeEffectiveScrollPx(session));

        // **이미 온전히 보이면 스크롤을 뺏지 않는다**(file-explorer §1 정책 4). 이 항이 없으면 위
        //  두 분기를 "항상 top으로"로 바꿔도 통과한다.
        const settled = file_panel_ops.fileTreeEffectiveScrollPx(session);
        session.file_tree_follow_scroll_pending = true;
        file_panel_ops.scrollFileTreeToFollowedCwd(session);
        try std.testing.expectEqual(settled, file_panel_ops.fileTreeEffectiveScrollPx(session));

        session.file_tree_followed_cwd = null;
    }

    // ⑩ **clamp가 같은 상한을 본다.** 목록이 줄어 창보다 짧아지면 offset이 그만큼 당겨져야 한다. 상한을
    //    안 보면 끝까지 스크롤된 상태에서 목록이 빈 채로 남는다.
    {
        session.file_tree_scroll.offset_y_px = 12 * cell_h;
        const shrunk = visible + 2;
        session.file_tree_rows.shrinkRetainingCapacity(shrunk);
        file_panel_ops.clampFileTreeScroll(session);
        try std.testing.expectEqual(
            @as(u32, @intCast(shrunk)) * cell_h - tree.h,
            session.file_tree_scroll.offset_y_px,
        );
    }

    // ⑪ **빈 목록에서는 어떤 좌표도 행이 아니다.** 창 안이라는 이유만으로 index를 내면 없는 행을
    //    선택해 뒤에서 범위 밖 접근이 된다.
    {
        session.file_tree_rows.clearRetainingCapacity();
        session.file_tree_scroll.reset();
        try std.testing.expect(file_panel_ops.fileTreeRowAt(session, x, inside_y) == null);
        // 아래 ⑫가 판정하려면 행이 다시 있어야 한다 — 빈 채로 두면 그 단언이 무의미해진다.
        for (0..visible) |_| try session.file_tree_rows.append(allocator, .{ .file = .{
            .path = "/repo/src/main.zig",
            .label = "main.zig",
            .depth = 1,
            .supported = true,
            .open = false,
            .active = false,
            .dirty = false,
            .external_change = false,
            .symlink = false,
        } });
    }

    // ⑫ 행 전체가 뷰포트 안에 들어가면 스크롤이 없다.
    session.file_tree_rows.shrinkRetainingCapacity(@min(visible, session.file_tree_rows.items.len));
    session.file_tree_scroll.offset_y_px = std.math.maxInt(u32);
    try std.testing.expectEqual(@as(u32, 0), file_panel_ops.fileTreeEffectiveScrollPx(session));
}

// 재투영은 **선택이 실제로 옮겨갔을 때만** 스크롤을 뺏는다(file-explorer.md §1 정책 4).
//
// 그 가드가 없으면 백그라운드 재투영(FSEvents·스캔 완료·git ignore 결과)이 도는 매 tick마다
// `reconcileFileTreeSelection` 이 선택 행으로 `scrollFileTreeRowIntoView` 를 걸어, 사용자가 내려
// 둔 목록이 선택 행 자리로 되감긴다 — 2026-08-28 사용자 보고 "선택한 것보다 밑으로 내려가면
// 스크롤이 원복된다". `Selection.reconcile` 이 **제자리 exact match 에서도** 인덱스를 돌려주므로
// 반환값만으로는 "복원할 것이 없었다"와 "복원했다"가 구분되지 않는 것이 루트커즈다.
test "file tree reprojection keeps the user's scroll unless the selection actually moved" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    file_panel_ops.activateFilePanelDockControl(session);
    _ = try session.resize(1400, 900, 1000);

    const cell_h = file_tree_dock_ops.fileTreeRowHeightPx(session);
    if (cell_h == 0) return error.FileTreeFixtureCannotJudgePartialRow;
    const visible = file_panel_ops.fileTreeVisibleRows(session);
    if (visible == 0) return error.FileTreeFixtureCannotJudgePartialRow;

    // **행 경로가 겹치면 이 테스트는 아무것도 판정하지 못한다** — identity 가 같아 `reconcile` 이
    // 늘 첫 행을 찾고, 아래 대조군이 "선택이 옮겨갔다"는 상태에 도달하지 못한다.
    var paths: std.ArrayList([]u8) = .empty;
    defer {
        for (paths.items) |p| allocator.free(p);
        paths.deinit(allocator);
    }
    session.file_tree_rows.clearRetainingCapacity();
    for (0..visible * 3) |i| {
        const path = try std.fmt.allocPrint(allocator, "/repo/src/f{d}.zig", .{i});
        try paths.append(allocator, path);
        try session.file_tree_rows.append(allocator, .{ .file = .{
            .path = path,
            .label = path,
            .depth = 1,
            .supported = true,
            .open = false,
            .active = false,
            .dirty = false,
            .external_change = false,
            .symlink = false,
        } });
    }
    session.file_tree_scroll.reset();

    // 첫 행을 고르고 — 사용자가 목록을 그보다 아래로 내린다.
    try std.testing.expect(file_panel_ops.setFileTreeSelection(session, 0));
    const user_scroll = 5 * cell_h;
    session.file_tree_scroll.offset_y_px = user_scroll;
    try std.testing.expectEqual(user_scroll, file_panel_ops.fileTreeEffectiveScrollPx(session));

    // ① 재투영이 돌아도 선택이 제자리면 스크롤은 사용자 것이다.
    file_panel_ops.reconcileFileTreeSelection(session);
    try std.testing.expectEqual(user_scroll, file_panel_ops.fileTreeEffectiveScrollPx(session));

    // ② **행이 재정렬돼 선택 인덱스만 바뀌어도** 같다. 같은 항목이 다른 자리로 옮겨 간 것은
    //    사용자가 보던 곳을 바꿀 이유가 아니다(스캔 완료가 형제를 끼워 넣는 흔한 경로다).
    const moved = paths.items[0];
    session.file_tree_rows.items[0].file.path = paths.items[1];
    session.file_tree_rows.items[1].file.path = moved;
    file_panel_ops.reconcileFileTreeSelection(session);
    try std.testing.expectEqual(user_scroll, file_panel_ops.fileTreeEffectiveScrollPx(session));
    try std.testing.expectEqual(@as(?usize, 1), session.file_tree_selection.index(session.file_tree_rows.items));

    // ③ **대조군** — 선택 행이 사라지면 옮겨간 선택을 따라간다. 이 항이 없으면 ①②는
    //    `scrollFileTreeRowIntoView` 호출을 통째로 지워도 통과한다.
    _ = session.file_tree_rows.orderedRemove(1);
    file_panel_ops.reconcileFileTreeSelection(session);
    try std.testing.expect(file_panel_ops.fileTreeEffectiveScrollPx(session) != user_scroll);

    // ④ **두 번째 대조군: 아직 보여 준 적 없는 선택은 따라간다.** 생성·이름변경은 행이 투영되기
    //    **전에** `Selection.setIdentity` 로 선택을 예약하므로 generation 은 그 시점에 이미 올라가
    //    있다. 재투영에서 "generation 이 안 바뀌었다"만 보고 넘기면 방금 만든 파일이 뷰포트 밖에
    //    조용히 남는다 — 그래서 축이 `Selection.generation` 이 아니라 **보여 준 신원**이다.
    session.file_tree_scroll.reset();
    const last_index = session.file_tree_rows.items.len - 1;
    // **판정할 수 있는 상태인지 먼저 본다**(§10.1). 아래 두 항은 목록이 뷰포트보다 두 행 이상 길
    // 때만 무엇을 판정한다 — 짧으면 예약이 "이미 보이는 행"이 돼 reveal 이 no-op 이 되고, 기대값의
    // u32 뺄셈이 음수로 감겨 패닉한다. 픽스처가 그 상태를 못 만들면 통과시키지 않는다.
    const tree_h = dock_ops.dockGeometry(session).tree_content.h;
    if (last_index < 1 or @as(u32, @intCast(last_index)) * cell_h <= tree_h)
        return error.FileTreeFixtureTooShortToJudgeReveal;
    try std.testing.expect(session.file_tree_selection.setIdentity(
        .file,
        session.file_tree_rows.items[last_index].file.path,
        0,
    ));
    file_panel_ops.reconcileFileTreeSelection(session);
    const revealed_scroll = file_panel_ops.fileTreeEffectiveScrollPx(session);
    try std.testing.expectEqual(
        @as(u32, @intCast(last_index + 1)) * cell_h - tree_h,
        revealed_scroll,
    );

    // ⑤ 보여 준 뒤로는 다시 사용자 것이다 — 그 행을 화면 밖으로 밀어 두어도 재투영이 되감지 않는다.
    //    ④가 매 재투영마다 걸리면 이 항이 잡는다(그것이 원래 버그의 형태다).
    const nudged = revealed_scroll -| cell_h;
    try std.testing.expect(nudged != revealed_scroll); // 판정할 수 있는 상태인지 먼저 본다
    session.file_tree_scroll.offset_y_px = nudged;
    file_panel_ops.reconcileFileTreeSelection(session);
    try std.testing.expectEqual(nudged, file_panel_ops.fileTreeEffectiveScrollPx(session));

    // ⑥ **보여 주지 못한 것을 보여 줬다고 기록하지 않는다.** 도크가 접혀 뷰포트가 0이면
    //    `scrollFileTreeRowIntoView` 는 아무것도 못 한다. 그때 "보여 줬다"고 표시하면 도크를 다시
    //    열어도 그 선택은 영영 뷰포트 밖에 남는다 — 재투영이 매 tick 도는 동안 도크를 접어 두기만
    //    해도 예약이 통째로 삼켜지는 자리다.
    session.file_tree_scroll.reset();
    // **④와 다른 행이어야 한다** — 같은 신원을 다시 예약하면 generation 이 안 움직여 이 항이
    // 판정할 상태(아직 못 보여 준 예약)에 도달하지 못한다.
    const pending_index = last_index - 1;
    try std.testing.expect(pending_index != last_index);
    try std.testing.expect(session.file_tree_selection.setIdentity(
        .file,
        session.file_tree_rows.items[pending_index].file.path,
        0,
    ));
    // 렌더 메트릭이 아직 없는 상태를 만든다(⑧과 같은 패턴 — 첫 프레임이 그렇다). 창 높이를 줄여
    // 뷰포트를 0으로 만드는 길은 "낮은 도크 규칙"에 걸려 본문이 **오히려 커진다**(⑨의 주석).
    const saved_cell_h = session.cell_height_px;
    session.cell_height_px = 0;
    try std.testing.expectEqual(@as(u32, 0), file_tree_dock_ops.fileTreeRowHeightPx(session));
    file_panel_ops.reconcileFileTreeSelection(session);
    session.cell_height_px = saved_cell_h;
    try std.testing.expect(file_tree_dock_ops.fileTreeRowHeightPx(session) > 0);
    file_panel_ops.reconcileFileTreeSelection(session); // 이제야 보여 준다
    try std.testing.expectEqual(
        @as(u32, @intCast(pending_index + 1)) * cell_h - tree_h,
        file_panel_ops.fileTreeEffectiveScrollPx(session),
    );
}

// FT2 의 세 계약을 한 세션에서 본다. 셋 다 **화면으로는 안 보이는** 종류라 캡처로는 못 잡는다.
//
//  ⑴ 발행된 rect 와 창 산술이 **같은 답**을 낸다. 클릭 경로는 published rect 를 보고 Windows chrome
//     낮추기는 `rowAtLocalY` 를 쓰는데, 둘이 갈리면 플랫폼마다 다른 행이 열린다.
//  ⑵ **down 은 열지 않는다** — 여는 것은 up 이고 그 up 은 action 표(세대 검증)를 지난다. 밖에서 떼도
//     발화하는 것은 공용 interaction 계약이며, 그 사실도 함께 못 박는다(우리 선택이 아님을 남긴다).
//  ⑶ tree 가 실제로 바뀌면 **잡고 있던 손가락을 놓는다**(CIM §9 의 capture cancel 증거).
test "file tree pointer: published rect 와 창 산술이 같고, 여는 것은 up 이며, tree 교체는 capture 를 취소한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    _ = try session.resize(1400, 900, 1000);
    file_panel_ops.activateFilePanelDockControl(session);

    session.file_tree_rows.clearRetainingCapacity();
    for (0..40) |index| {
        const path = try std.fmt.allocPrint(allocator, "/repo/f{d}.zig", .{index});
        errdefer allocator.free(path);
        try session.file_tree_rows.append(allocator, .{ .file = .{
            .path = path,
            .label = path[6..],
            .depth = 1,
            .supported = true,
            .open = false,
            .active = false,
            .dirty = false,
            .external_change = false,
            .symlink = false,
        } });
    }
    defer for (session.file_tree_rows.items) |row| allocator.free(row.file.path);
    file_panel_ops.classifyFileTreeRows(session.file_tree_rows.items);
    file_tree_dock_ops.publishFileTreeHitTree(session);

    const tree = dock_ops.dockGeometry(session).tree_content;
    const x: f64 = @floatFromInt(tree.x + tree.w / 2);

    // ⑴ 두 축이 같은 답을 낸다 — 창 전체를 훑어 본다(한 점만 보면 상수를 반환해도 통과한다).
    var y: u32 = 0;
    var compared: usize = 0;
    while (y < tree.h) : (y += 3) {
        const at: f64 = @floatFromInt(tree.y + y);
        const arithmetic = file_panel_ops.fileTreeRowAt(session, x, at);
        const published = file_tree_dock_ops.fileTreeRowAtPublished(session, x, at);
        try std.testing.expectEqual(arithmetic, published);
        if (arithmetic != null) compared += 1;
    }
    try std.testing.expect(compared > 8); // 실제로 행 위를 여러 번 지났다

    // **도크 밖은 행이 아니다.** 옛 산술 경로는 `pointInRect(tree_rect)` 로 먼저 걸렀는데, 발행 경로는
    // 그 가드를 published clip 에 맡긴다 — 둘이 같은 답인지 네 방향에서 본다(한 방향만 보면 반쪽
    // 판정도 통과한다).
    const outside = [_][2]f64{
        .{ x, @floatFromInt(tree.y -| 8) }, // 위
        .{ x, @floatFromInt(tree.y + tree.h + 8) }, // 아래
        .{ @floatFromInt(tree.x -| 8), @floatFromInt(tree.y + 4) }, // 왼쪽(터미널 쪽)
        .{ @floatFromInt(tree.x + tree.w + 8), @floatFromInt(tree.y + 4) }, // 오른쪽
    };
    for (outside) |point| {
        try std.testing.expect(file_panel_ops.fileTreeRowAt(session, point[0], point[1]) == null);
        try std.testing.expect(file_tree_dock_ops.fileTreeRowAtPublished(session, point[0], point[1]) == null);
    }

    // ⑵ **down 은 열지 않는다.** 여는 것은 up 이고, 그 up 은 action 표(세대 검증)를 지난다.
    const row_y: f64 = @floatFromInt(tree.y + file_tree_dock_ops.fileTreeRowHeightPx(session) * 3 + 2);
    const before_selection = file_panel_ops.selectedFileTreeRow(session);
    _ = file_tree_dock_ops.fileTreeDockPointer(session, .down, x, row_y);
    try std.testing.expectEqual(before_selection, file_panel_ops.selectedFileTreeRow(session));
    const intent = file_tree_dock_ops.fileTreeDockPointer(session, .up, x, row_y) orelse
        return error.FileTreePointerProducedNoIntent;
    switch (intent) {
        .activate_row => |index| try std.testing.expectEqual(
            file_panel_ops.fileTreeRowAt(session, x, row_y).?,
            index,
        ),
    }

    // ⑵b **밖에서 떼도 발화한다** — 이것은 이 위젯의 선택이 아니라 공용 `chrome.ui.interaction` 계약이다
    //     (`dispatch` 의 `.up`: 잡은 노드가 여전히 같은 action 을 들고 있으면 좌표와 무관하게 발화).
    //     macOS 버튼 관례(밖에서 떼면 취소)와 다르므로 **여기에 값으로 적어 둔다** — 바꾸려면 이 위젯이
    //     아니라 CIM 계약을 바꿔야 하고, 그러면 탭·도크·세팅이 함께 움직인다.
    _ = file_tree_dock_ops.fileTreeDockPointer(session, .down, x, row_y);
    _ = file_tree_dock_ops.fileTreeDockPointer(session, .move, 10, row_y);
    try std.testing.expect(file_tree_dock_ops.fileTreeDockPointer(session, .up, 10, row_y) != null);

    // ⑵c **같은 tree 를 다시 발행해도 capture 는 산다.** 제품에서는 down 과 up 사이에 paint 가 끼고
    //     그 paint 가 발행을 다시 낸다. 그 발행이 "교체"로 판정되면 mouse-up 이 intent 를 못 내
    //     **좌클릭이 영영 안 열린다** — 호버·우클릭·키보드는 capture 를 안 쓰므로 멀쩡하고 좌클릭만
    //     죽는다(2026-08-26 사용자 제보, 계측 실측: `entries 25->25 actions 23->23 rows 23->23
    //     gen 2464->2464` 인데 `replaced=true`).
    //
    //     **위 ⑵·⑵b 가 이것을 못 잡았다** — 둘 다 down 과 up 을 연달아 부르고 그 사이에 발행이 없다.
    //     빠져 있던 것은 판정이 아니라 **제품의 순서**였다.
    _ = file_tree_dock_ops.fileTreeDockPointer(session, .down, x, row_y);
    try std.testing.expect(session.file_tree_interaction.capture != null);
    file_tree_dock_ops.publishFileTreeHitTree(session); // 내용이 같은 재발행 = 그 사이에 낀 paint
    try std.testing.expect(session.file_tree_interaction.capture != null);
    try std.testing.expect(file_tree_dock_ops.fileTreeDockPointer(session, .up, x, row_y) != null);

    // ⑵d **자리는 같은데 그 자리의 파일이 바뀌면 열지 않는다.** 위 ⑵c 가 지키는 "같은 tree 면 capture 를
    //     잇는다" 는 곧 `frameEql` 이 id·rect·`model_index` 만 본다는 뜻이기도 하다 — 그 줄이 **어느
    //     파일인가**는 안 본다. 그래서 A 를 누른 손이 뗄 때 B 가 열릴 수 있었다(2026-08-27 적대적 검증
    //     4회차에서 프로브로 재현: `capture=true up_intent=true`). down 이 굳힌 신원이 그 구멍을 막는다.
    //
    //     capture 는 **살아 있어야** 한다 — 그것이 이 판정의 전제다. capture 가 죽어서 안 열리는 것이면
    //     ⑵c 의 회귀이지 신원 대조가 아니다.
    _ = file_tree_dock_ops.fileTreeDockPointer(session, .down, x, row_y);
    {
        const swapped_at = file_tree_dock_ops.fileTreeRowAtPublished(session, x, row_y).?;
        const swapped = try std.fmt.allocPrint(allocator, "/repo/SWAPPED.zig", .{});
        allocator.free(session.file_tree_rows.items[swapped_at].file.path);
        session.file_tree_rows.items[swapped_at] = .{ .file = .{
            .path = swapped,
            .label = swapped[6..],
            .depth = 1,
            .supported = true,
            .open = false,
            .active = false,
            .dirty = false,
            .external_change = false,
            .symlink = false,
        } };
        file_panel_ops.classifyFileTreeRows(session.file_tree_rows.items);
        file_tree_dock_ops.publishFileTreeHitTree(session);
        try std.testing.expect(session.file_tree_interaction.capture != null);
        try std.testing.expect(file_tree_dock_ops.fileTreeDockPointer(session, .up, x, row_y) == null);
    }

    // ⑶ 누르고 있는 동안 tree 가 **실제로 바뀌면** capture 를 놓는다(늦은 up 이 새 행을 열지 않게).
    //
    //     **보이는 행 수 자체를 줄인다.** 예전에는 `pop()` 으로 마지막 행을 뗐는데, 40 행 중 뷰포트에
    //     들어오는 것은 앞쪽 일부라 그 행은 **발행되는 tree 에 없다** — tree 가 안 바뀌니 capture 를 놓지
    //     않는 것이 옳고, 이 판정은 그 시나리오를 만들지 못했다. 그런데도 초록이었던 이유는 `frameEql`
    //     이 좌표계를 섞어 **모든** 발행을 교체로 판정했기 때문이다(2026-08-26 수정). 그 버그를 고치자
    //     이 자리가 빨개져 가짜였음이 드러났다.
    //
    //     행 하나를 앞에서 빼는 것으로도 부족하다: node id 도 `model_index` 도 **창 기준**이라 창이
    //     그대로면 셋 다 같은 값이 다시 나온다(`frameEql` 의 몫은 기하와 action 이지 어느 파일인가가
    //     아니다). 창이 실제로 줄어드는 크기까지 내려야 발행이 달라진다.
    _ = file_tree_dock_ops.fileTreeDockPointer(session, .down, x, row_y);
    try std.testing.expect(session.file_tree_interaction.capture != null);
    // 뗀 행의 경로도 우리 것이다 — `defer` 는 **남아 있는** 행만 훑으므로 여기서 놓아준다.
    while (session.file_tree_rows.items.len > 3) allocator.free(session.file_tree_rows.pop().?.file.path);
    file_tree_dock_ops.publishFileTreeHitTree(session);
    try std.testing.expect(session.file_tree_interaction.capture == null);
    try std.testing.expect(file_tree_dock_ops.fileTreeDockPointer(session, .up, x, row_y) == null);
}

// **발행된 tree 는 행 목록보다 오래 살 수 있다.** 행이 줄어든 뒤 다음 프레임을 그리기 전에 포인터가
// 오면(watcher 갱신·스캔 완료·폴더 접기 — 전부 렌더와 다른 시점에 일어난다) 발행된 action 표는 없는
// 인덱스를 가리킨다.
//
// 그 인덱스를 그대로 `file_tree_rows.items[i]` 에 쓰면 **범위를 넘어 죽는다**. 실제로 우클릭 경로가
// 그 상태였고(적대적 검증), activate 경로만 경계 검사를 갖고 있었다 — 같은 값의 소비자가 둘인데
// 방어가 한쪽에만 있으면 그 비대칭이 곧 결함이다. 그래서 **질의 자체가** 지금 없는 행을 안 준다.
test "file tree: 발행된 인덱스가 낡아도 범위를 넘지 않는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    _ = try session.resize(1400, 900, 1000);
    file_panel_ops.activateFilePanelDockControl(session);

    session.file_tree_rows.clearRetainingCapacity();
    for (0..40) |index| {
        const path = try std.fmt.allocPrint(allocator, "/repo/g{d}.zig", .{index});
        errdefer allocator.free(path);
        try session.file_tree_rows.append(allocator, .{ .file = .{
            .path = path,
            .label = path[6..],
            .depth = 1,
            .supported = true,
            .open = false,
            .active = false,
            .dirty = false,
            .external_change = false,
            .symlink = false,
        } });
    }
    defer for (session.file_tree_rows.items) |row| allocator.free(row.file.path);
    file_panel_ops.classifyFileTreeRows(session.file_tree_rows.items);
    file_tree_dock_ops.publishFileTreeHitTree(session);

    const tree = dock_ops.dockGeometry(session).tree_content;
    const x: f64 = @floatFromInt(tree.x + tree.w / 2);
    const deep_y: f64 = @floatFromInt(tree.y + file_tree_dock_ops.fileTreeRowHeightPx(session) * 20 + 2);
    // 전제: 그 자리는 지금 행이다(아니면 이 테스트가 아무것도 판정하지 않는다).
    try std.testing.expect(file_tree_dock_ops.fileTreeRowAtPublished(session, x, deep_y) != null);

    // 행이 줄어든다 — **다시 발행하지 않는다**(렌더 전에 이벤트가 오는 상황 그대로).
    while (session.file_tree_rows.items.len > 3) {
        if (session.file_tree_rows.pop()) |removed| allocator.free(removed.file.path);
    }

    // ⑴ 질의가 없는 행을 주지 않는다.
    try std.testing.expect(file_tree_dock_ops.fileTreeRowAtPublished(session, x, deep_y) == null);
    // ⑵ 그래서 우클릭이 죽지 않고 메뉴도 안 뜬다(옛 상태에서는 여기서 배열 범위를 넘었다).
    session.file_tree_context_target = null;
    session.mouse(1, x, deep_y, 2, 0);
    try std.testing.expect(session.file_tree_context_target == null);
    // ⑶ 늦게 도착한 up 도 아무것도 열지 않는다.
    _ = file_tree_dock_ops.fileTreeDockPointer(session, .down, x, deep_y);
    try std.testing.expect(file_tree_dock_ops.fileTreeDockPointer(session, .up, x, deep_y) == null);
}

// **스크롤과 그리기 사이에 온 포인터가 보이는 행을 가리킨다.**
//
// 발행은 그리기 경로가 하므로 프레임 사이에 낡는다. 휠 이벤트와 클릭이 같은 run loop 패스에 들어오면
// 그 사이에 paint 가 없고, 그러면 커서 밑에 **보이는** 행과 발행이 말하는 행이 달라진다 — 실측으로
// 휠 10행 뒤 발행이 2행을 가리켰다(적대적 검증 3라운드). 세대 검사는 이것을 못 잡는다: 스크롤은
// 목록을 바꾸지 않으므로 투영 세대가 그대로다.
//
// 증상이 "아무 일도 안 일어남" 이 아니라 **다른 파일이 열림** 이라 조용하지 않다.
test "file tree: 스크롤 직후의 포인터도 보이는 행을 가리킨다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    _ = try session.resize(1400, 900, 1000);
    file_panel_ops.activateFilePanelDockControl(session);

    session.file_tree_rows.clearRetainingCapacity();
    for (0..80) |index| {
        const path = try std.fmt.allocPrint(allocator, "/repo/p{d}.zig", .{index});
        errdefer allocator.free(path);
        try session.file_tree_rows.append(allocator, .{ .file = .{
            .path = path,
            .label = path[6..],
            .depth = 1,
            .supported = true,
            .open = false,
            .active = false,
            .dirty = false,
            .external_change = false,
            .symlink = false,
        } });
    }
    defer for (session.file_tree_rows.items) |row| allocator.free(row.file.path);
    file_panel_ops.classifyFileTreeRows(session.file_tree_rows.items);
    file_tree_dock_ops.publishFileTreeHitTree(session);

    const tree = dock_ops.dockGeometry(session).tree_content;
    const x: f64 = @floatFromInt(tree.x + tree.w / 2);
    const y: f64 = @floatFromInt(tree.y + file_tree_dock_ops.fileTreeRowHeightPx(session) * 2 + 4);
    const before_pub = file_tree_dock_ops.fileTreeRowAtPublished(session, x, y);
    const before_arith = file_panel_ops.fileTreeRowAt(session, x, y);
    try std.testing.expectEqual(before_arith, before_pub);

    // **스크롤만 하고 다시 그리지 않는다** — 이벤트 두 개가 같은 run loop 패스에 들어오는 상황.
    file_panel_ops.setFileTreeScrollOffsetPx(session, file_tree_dock_ops.fileTreeRowHeightPx(session) * 10);
    const after_pub = file_tree_dock_ops.fileTreeRowAtPublished(session, x, y);
    const after_arith = file_panel_ops.fileTreeRowAt(session, x, y);
    // 전제: 스크롤이 실제로 답을 바꿨다(안 바뀌면 이 테스트가 아무것도 판정하지 않는다).
    try std.testing.expect(after_arith != null and after_arith.? != before_arith.?);
    try std.testing.expectEqual(after_arith, after_pub);

    // 그리고 그 자리를 누르면 **보이는 그 행**이 열린다(질의만 맞고 intent 가 낡으면 소용없다).
    _ = file_tree_dock_ops.fileTreeDockPointer(session, .down, x, y);
    const intent = file_tree_dock_ops.fileTreeDockPointer(session, .up, x, y) orelse
        return error.FileTreeScrolledPointerProducedNoIntent;
    switch (intent) {
        .activate_row => |index| try std.testing.expectEqual(after_arith.?, index),
    }
}

// CIM §9 조건 ①·② 의 증거 — 파일 트리 소비자.
//
// ①은 "window deactivate 에서 capture 가 놓인다", ②는 "draw·hit-test 가 **같은 발행 세대**를 쓴다"다.
// 세대는 이미 intent 표가 검증하지만(`table.resolve`) 그것은 **행을 여는 순간**만 본다. 낡은 발행 위에서
// capture·호버가 서고 우클릭이 행을 집는 것은 그 게이트 밖이었다.
test "file tree: 발행이 낡으면 다시 내고, 다시 낼 수 없으면 짚지 않는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    _ = try session.resize(1400, 900, 1000);
    file_panel_ops.activateFilePanelDockControl(session);

    session.file_tree_rows.clearRetainingCapacity();
    for (0..12) |index| {
        const path = try std.fmt.allocPrint(allocator, "/repo/g{d}.zig", .{index});
        errdefer allocator.free(path);
        try session.file_tree_rows.append(allocator, .{ .file = .{
            .path = path,
            .label = path[6..],
            .depth = 1,
            .supported = true,
            .open = false,
            .active = false,
            .dirty = false,
            .external_change = false,
            .symlink = false,
        } });
    }
    defer for (session.file_tree_rows.items) |row| allocator.free(row.file.path);
    file_panel_ops.classifyFileTreeRows(session.file_tree_rows.items);
    file_tree_dock_ops.publishFileTreeHitTree(session);
    // 발행은 자기가 본 세대를 남긴다 — 이게 0 이면 아래 게이트 전체가 조용히 꺼진다.
    try std.testing.expectEqual(session.file_tree_projection_generation, session.file_tree_published_generation);
    try std.testing.expect(session.file_tree_published_generation != 0);

    const tree = dock_ops.dockGeometry(session).tree_content;
    const x: f64 = @floatFromInt(tree.x + tree.w / 2);
    const y: f64 = @floatFromInt(tree.y + file_tree_dock_ops.fileTreeRowHeightPx(session) * 3 + 4);
    const target = file_tree_dock_ops.fileTreeRowAtPublished(session, x, y) orelse
        return error.FileTreeGenerationFixtureMissedRow;

    // 행 **수는 그대로** 두고 세대만 올린다(watcher 가 이름을 갈거나 한 폴더를 접고 다른 하나를 편 모양).
    // 스크롤·행 수 비교만 하던 신선도 판정은 이 변화를 못 보고 낡은 발행을 그대로 썼다.
    file_panel_ops.advanceFileTreeProjectionGeneration(session);
    try std.testing.expect(session.file_tree_published_generation != session.file_tree_projection_generation);
    // 그릴 수 있는 상태라면 **다시 내서** 맞춘다 — 클릭을 잃지 않는다.
    try std.testing.expectEqual(target, file_tree_dock_ops.fileTreeRowAtPublished(session, x, y));
    try std.testing.expectEqual(session.file_tree_projection_generation, session.file_tree_published_generation);
    // 질의가 아니라 **클릭 경로**로도 고정한다. 다시 내지 않으면 발행된 액션이 옛 세대를 들고 있어
    // `table.resolve` 가 전부 거른다 — 즉 재투영과 다음 paint 사이에 온 클릭이 조용히 죽는다.
    // 그 상태는 사용자에게 "가끔 클릭이 안 먹는" 것으로 보인다.
    _ = file_tree_dock_ops.fileTreeDockPointer(session, .down, x, y);
    const revived = file_tree_dock_ops.fileTreeDockPointer(session, .up, x, y) orelse
        return error.FileTreeClickDiedAfterProjectionBump;
    switch (revived) {
        .activate_row => |index| try std.testing.expectEqual(target, index),
    }

    // 이제 **다시 낼 수 없는** 프레임: 기하가 아직 0 이면 `prepare` 가 null 을 주고 옛 entries 가 남는다.
    // 그 발행은 사라진 행을 가리킬 수 있으므로 좌표 판정이 아무것도 주지 않아야 한다.
    file_panel_ops.advanceFileTreeProjectionGeneration(session);
    const saved_cell_w = session.cell_width_px;
    session.cell_width_px = 0;
    defer session.cell_width_px = saved_cell_w;
    try std.testing.expectEqual(@as(?usize, null), file_tree_dock_ops.fileTreeRowAtPublished(session, x, y));
    // 누르는 경로도 같은 답이다 — 그리고 낡은 스냅샷에는 **capture 를 세우지 않는다**.
    try std.testing.expectEqual(@as(?chrome.components.file_tree.ids.Intent, null), file_tree_dock_ops.fileTreeDockPointer(session, .down, x, y));
    try std.testing.expect(session.file_tree_interaction.capture == null);
    try std.testing.expectEqual(@as(?chrome.components.file_tree.ids.Intent, null), file_tree_dock_ops.fileTreeDockPointer(session, .up, x, y));
}

// **크기가 바뀐 뒤 그리기 전에 온 포인터도 보이는 행을 가리키는가.**
//
// 발행은 그리기 경로가 하므로 resize 와 다음 paint 사이에는 **바뀌기 전 기하**가 남는다. 스크롤·행
// 수·투영 세대 어느 것도 이 축을 보지 않는다 — 목록은 그대로이고 사각형만 움직이기 때문이다. AI 세션
// 도크는 같은 이유로 그 자리에서 capture 를 놓는다("published rect tree still describes pre-resize
// geometry until the next paint"). 트리는 놓는 대신 다시 발행해서 클릭을 잃지 않는다.
test "file tree: 창 크기가 바뀌어도 포인터는 지금 기하로 행을 고른다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    _ = try session.resize(1400, 900, 1000);
    file_panel_ops.activateFilePanelDockControl(session);

    session.file_tree_rows.clearRetainingCapacity();
    for (0..10) |index| {
        const path = try std.fmt.allocPrint(allocator, "/repo/r{d}.zig", .{index});
        errdefer allocator.free(path);
        try session.file_tree_rows.append(allocator, .{ .file = .{
            .path = path,
            .label = path[6..],
            .depth = 1,
            .supported = true,
            .open = false,
            .active = false,
            .dirty = false,
            .external_change = false,
            .symlink = false,
        } });
    }
    defer for (session.file_tree_rows.items) |row| allocator.free(row.file.path);
    file_panel_ops.classifyFileTreeRows(session.file_tree_rows.items);
    file_tree_dock_ops.publishFileTreeHitTree(session);

    const before = dock_ops.dockGeometry(session).tree_content;
    // **다시 그리지 않고** 창만 줄인다 — 도크는 오른쪽에 붙어 있으므로 트리 사각형이 통째로 움직인다.
    _ = try session.resize(1100, 900, 1000);
    const after = dock_ops.dockGeometry(session).tree_content;
    // 전제: 기하가 실제로 움직였다(안 움직이면 이 테스트가 아무것도 판정하지 않는다).
    try std.testing.expect(after.x != before.x or after.w != before.w);

    // 지금 기하 기준으로 두 번째 행을 짚는다.
    const x: f64 = @floatFromInt(after.x + after.w / 2);
    const y: f64 = @floatFromInt(after.y + file_tree_dock_ops.fileTreeRowHeightPx(session) + 4);
    const arith = file_panel_ops.fileTreeRowAt(session, x, y);
    try std.testing.expect(arith != null);
    try std.testing.expectEqual(arith, file_tree_dock_ops.fileTreeRowAtPublished(session, x, y));

    // 누르는 경로도 같은 답이어야 한다 — 질의만 맞고 intent 가 옛 rect 를 보면 다른 파일이 열린다.
    _ = file_tree_dock_ops.fileTreeDockPointer(session, .down, x, y);
    const intent = file_tree_dock_ops.fileTreeDockPointer(session, .up, x, y) orelse
        return error.FileTreeResizedPointerProducedNoIntent;
    switch (intent) {
        .activate_row => |index| try std.testing.expectEqual(arith.?, index),
    }
}

test "file tree: 창이 비활성되면 누르고 있던 행을 놓는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
