    const new_root = try std.fs.path.join(allocator, &.{ tmp_root, "new-root" });
    defer allocator.free(new_root);
    const old_path = try std.fs.path.join(allocator, &.{ tmp_root, "old.md" });
    defer allocator.free(old_path);
    const new_path = try std.fs.path.join(allocator, &.{ tmp_root, "new.md" });
    defer allocator.free(new_path);

    // Durable tombstone도 complete stage/build/capacity/swap path를 탄다. 이 후보는 build 중 notice 회계를 올리므로
    // fail-index가 모델뿐 아니라 새 counter transaction rollback까지 검증한다.
    const surfaces = [_]maru.session.workspace.Surface{
        .{
            .cwd = tmp_root,
            .runtime_host_id = "abcdef1234567890abcdef1234567890",
            .runtime_id = "0123456789abcdef0123456789abcdef",
            .runtime_state = .ended,
            .cols = 40,
            .rows = 24,
        },
        .{ .cwd = tmp_root, .cols = 40, .rows = 24 },
    };
    const panes = [_]maru.session.workspace.Pane{.{ .surfaces = &surfaces }};
    const tree = [_]maru.session.workspace.TreeNode{.{ .leaf = 0 }};
    const tabs = [_]maru.session.workspace.Tab{.{
        .custom_name = "replacement",
        .tree = &tree,
        .panes = &panes,
    }};
    const entries = [_]dock_panel.PersistedEntry{.{
        .path = new_path,
        .kind = .markdown,
        .mode = .read,
        .active = true,
    }};
    const roots = [_][]const u8{new_root};
    const replacement: maru.session.workspace.Window = .{
        .tabs = &tabs,
        .dock = .{ .presented = true, .entries = &entries },
        .explorer = .{ .roots = &roots },
    };

    const Harness = struct {
        fn prepare(session: *AppSession, backing_allocator: std.mem.Allocator, before_root: []const u8, before_path: []const u8) !void {
            const opened = try pane_ops.openFileTermInActivePane(session, before_path, .markdown);
            const entry = opened.term.file_entry.?;
            entry.mode = .read;
            try session.file_tree.replaceExplicitRoots(&.{before_root});
            var staged: [1]dock_panel.Entry = .{entry.*};
            try file_panel_ops.buildFileTreeRowsForEntries(
                backing_allocator,
                staged[0..],
                0,
                &session.file_tree,
                &session.file_tree_open_states,
                &session.file_tree_rows,
            );
            session.file_tree_rows_dirty = false;
            try session.file_tree.resetWatchRequests(&.{std.fs.path.dirname(before_path).?});
            std.debug.assert(entry.surface_id != 0);
        }

        fn expectPreserved(
            session: *AppSession,
            before_tab: *Tab,
            before_surface: *maru.session.Surface,
            before_entry_id: u64,
            before_root: []const u8,
            before_watch: []const u8,
            before_generation: u64,
            before_rows_ptr: [*]file_tree.Row,
            before_rows_len: usize,
        ) !void {
            try std.testing.expectEqual(@as(usize, 1), session.tabs.items.len);
            try std.testing.expect(session.tabs.items[0] == before_tab);
            try std.testing.expect(term_ops.activeSurface(session) == before_surface);
            _ = before_entry_id;
            try std.testing.expectEqualStrings(before_root, session.file_tree.rootAt(0).?);
            try std.testing.expectEqual(before_generation, session.file_tree.rootGeneration());
            try std.testing.expectEqual(file_tree.RootMode.explicit, session.file_tree.rootMode());
            try std.testing.expectEqual(@as(usize, 1), file_panel_ops.fileEntryCount(session));
            _ = 0; // FP16: Harness가 만든 location 대신 창구가 소유(위 fileEntryCount로 검증)
            try std.testing.expectEqual(before_rows_len, session.file_tree_rows.items.len);
            try std.testing.expect(session.file_tree_rows.items.ptr == before_rows_ptr);
            try std.testing.expectEqualStrings(before_root, session.file_tree_rows.items[0].root.path);
            try std.testing.expectEqualStrings(before_watch, session.file_tree.peekWatchRequest().?);
        }
    };

    // Reuse the same live session after every rejected candidate. This keeps the test exhaustive up to
    // the no-fail commit boundary without paying full AppSession/PTY startup for every allocation index.
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    var session_live = true;
    defer if (session_live) session.deinit();
    try Harness.prepare(session, allocator, old_root, old_path);
    const before_tab = session.tabs.items[0];
    const before_surface = term_ops.activeSurface(session);
    const before_entry_id = session.fileEntryAt(0).?.id;
    const before_generation = session.file_tree.rootGeneration();
    const before_rows_ptr = session.file_tree_rows.items.ptr;
    const before_rows_len = session.file_tree_rows.items.len;
    session.ended_placeholder_notice_pending = 7;
    session.ended_placeholder_dropped_pending = 11;
    var saw_rollback = false;
    var saw_commit = false;
    for (0..512) |fail_index| {
        var failing = std.testing.FailingAllocator.init(allocator, .{ .fail_index = fail_index });
        session.allocator = failing.allocator();
        var apply_error: ?anyerror = null;
        workspace_ops.applyWorkspaceWindow(session, replacement) catch |err| {
            apply_error = err;
        };
        if (apply_error) |err| {
            try std.testing.expectEqual(error.OutOfMemory, err);
            try std.testing.expect(failing.has_induced_failure);
            try Harness.expectPreserved(
                session,
                before_tab,
                before_surface,
                before_entry_id,
                old_root,
                tmp_root,
                before_generation,
                before_rows_ptr,
                before_rows_len,
            );
            try std.testing.expectEqual(@as(u32, 7), session.ended_placeholder_notice_pending);
            try std.testing.expectEqual(@as(u32, 11), session.ended_placeholder_dropped_pending);
            saw_rollback = true;
            session.allocator = allocator; // rejected candidate retained no object backed by `failing`.
        } else {
            // Post-commit best-effort projection work may intentionally catch OOM. In that case apply has
            // already completed the no-fail swap, so it must be wholly new rather than a mixed half-state.
            try std.testing.expectEqualStrings(new_root, session.file_tree.rootAt(0).?);
            try std.testing.expectEqualStrings("replacement", session.tabs.items[0].custom_name.?);
            try std.testing.expect(file_panel_ops.fileEntryForPath(session, new_path) != null);
            // plain live + already-ended 후보가 publish돼 notice가 실제 mutate된다. newly-Gone의 notice+dropped 동시
            // rollback은 RestoreAccountingSnapshot/recordEndedPlaceholder production helper 회귀가 별도로 고정한다.
            try std.testing.expectEqual(@as(u32, 11), session.ended_placeholder_dropped_pending);
            try std.testing.expectEqual(@as(u32, 8), session.ended_placeholder_notice_pending);
            failing.fail_index = std.math.maxInt(usize);
            session.deinit(); // committed backends/terms retain failing.allocator(); tear down before it leaves scope.
            session_live = false;
            saw_commit = true;
            break;
        }
    }
    try std.testing.expect(saw_rollback);
    try std.testing.expect(saw_commit);
}

test "file header mode selector reports a click cursor and tracks hover per slot" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    _ = try session.resize(1400, 900, 1000);
    _ = try pane_ops.openFileTermInActivePane(session, "/tmp/hover.md", .markdown);
    file_panel_ops.assignDockSurfaceIds(session);
    const entry = session.fileEntryAt(0).?;

    const band = pane_ops.fileHeaderBandForPaneLookup(session, pane_ops.activePane(session)).?;
    const read_rect = dock_layout.headerModeRect(band.band, session.cell_width_px, .markdown, .read, false, false).?;
    const rich_rect = dock_layout.headerModeRect(band.band, session.cell_width_px, .markdown, .rich, false, false).?;
    const read_x: f64 = @floatFromInt(read_rect.x + 1);
    const rich_x: f64 = @floatFromInt(rich_rect.x + 1);
    const band_y: f64 = @floatFromInt(band.band.y + 1);

    // 클릭 가능한 chrome이므로 pointingHand를 준다 — 다른 chrome 버튼(탭·nav)과 같은 affordance다.
    try std.testing.expectEqual(CursorKind.link, session.hoverCursor(read_x, band_y, 0));
    try std.testing.expectEqual(@as(?u64, entry.surface_id), if (session.hovered_file_header_mode) |h| h.surface_id else null);
    try std.testing.expectEqual(@as(?dock_panel.Mode, .read), if (session.hovered_file_header_mode) |h| h.mode else null);

    // 슬롯을 옮기면 강조 대상도 옮겨간다(같은 밴드 안에서 슬롯별로 구분된다).
    _ = session.hoverCursor(rich_x, band_y, 0);
    try std.testing.expectEqual(@as(?dock_panel.Mode, .rich), if (session.hovered_file_header_mode) |h| h.mode else null);

    // 밴드 밖(breadcrumb 자리)에서는 호버가 풀린다 — stale 강조가 남으면 안 된다.
    _ = session.hoverCursor(@floatFromInt(band.band.x + 1), band_y, 0);
    try std.testing.expect(session.hovered_file_header_mode == null);

    // 헤더가 없는 자리로 나가도 정리된다.
    _ = session.hoverCursor(0, 0, 0);
    try std.testing.expect(session.hovered_file_header_mode == null);
}

test "file panel mode toggle: keyboard action walks the same modes the header offers" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    _ = try session.resize(1400, 900, 1000);

    // 파일이 아닌 Term에서는 안내만 하고 아무 것도 바꾸지 않는다.
    session.dispatchAppAction(.toggle_file_panel_mode);
    try std.testing.expect(session.chrome_host.notice.open);
    session.chrome_host.notice.dismiss();

    // markdown은 읽기로 시작한다(라이브 프리뷰 폐기 — docs/file-panel.md §1). 키보드 경로가 없으면 편집에
    // 들어가는 유일한 길이 헤더 mode 선택기 마우스 클릭뿐이므로, 이 왕복이 제품 계약이다.
    _ = try pane_ops.openFileTermInActivePane(session, "/tmp/mode-toggle.md", .markdown);
    file_panel_ops.assignDockSurfaceIds(session);
    const entry = session.fileEntryAt(0).?;
    try std.testing.expectEqual(dock_panel.Mode.read, entry.mode);

    // 헤더가 보여 주는 순서 그대로 순환한다: 읽기 → 리치 → 소스 → 읽기.
    session.dispatchAppAction(.toggle_file_panel_mode);
    try std.testing.expectEqual(dock_panel.Mode.rich, entry.mode);
    // 헤더 클릭과 같은 경로라 Swift가 drain할 pending action도 똑같이 선다.
    const action = session.takeFilePanelModeAction().?;
    try std.testing.expectEqual(entry.surface_id, action.surface_id);
    try std.testing.expectEqual(dock_panel.Mode.rich, action.mode);

    session.dispatchAppAction(.toggle_file_panel_mode);
    try std.testing.expectEqual(dock_panel.Mode.source_edit, entry.mode);
    session.dispatchAppAction(.toggle_file_panel_mode);
    try std.testing.expectEqual(dock_panel.Mode.read, entry.mode);

    // 모드가 하나뿐인 kind(text)는 무동작이고 알림도 띄우지 않는다 — 토글할 선택지 자체가 없다.
    _ = try pane_ops.openFileTermInActivePane(session, "/tmp/mode-toggle.py", .text);
    file_panel_ops.assignDockSurfaceIds(session);
    const text_entry = session.fileEntryAt(1).?;
    try std.testing.expectEqual(dock_panel.Mode.source_edit, text_entry.mode);
    session.dispatchAppAction(.toggle_file_panel_mode);
    try std.testing.expectEqual(dock_panel.Mode.source_edit, text_entry.mode);
    try std.testing.expect(!session.chrome_host.notice.open);
}

test "FP9 focus toggle: empty notice and workspace-dock round trip use one configurable action" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    _ = try session.resize(1400, 900, 1000);

    try std.testing.expect(session.focus_owner == .workspace);
    session.dispatchAppAction(.toggle_file_panel_focus);
    try std.testing.expect(session.focus_owner == .workspace);
    try std.testing.expect(session.chrome_host.notice.open);
    session.chrome_host.notice.dismiss();
    _ = try pane_ops.openFileTermInActivePane(session, "/tmp/focus-toggle.md", .markdown);
    file_panel_ops.assignDockSurfaceIds(session);
    const sid = session.fileEntryAt(0).?.surface_id;
    // FP16: 파일을 열면 그 파일이 publish 대기 barrier를 갖는다(requestDockEntryFocus). 이 테스트의
    // 주제는 toggle 왕복이므로 workspace baseline에서 시작한다.
    workspace_ops.focusWorkspaceInput(session);
    try std.testing.expectEqual(@as(usize, 1), web_ops.webSurfaceTransitionsCount(session)); // baseline dock create
    try std.testing.expectEqual(@as(usize, 0), web_ops.webSurfaceTransitionsCount(session));
    session.dispatchAppAction(.toggle_file_panel_focus);
    try std.testing.expect(session.focus_owner == .file_tree);
    try std.testing.expect(session.takeFileTreeFocusAction());
    try std.testing.expectEqual(@as(usize, 0), web_ops.webSurfaceTransitionsCount(session)); // focus 왕복은 WebView reframe 0
    session.dispatchAppAction(.toggle_file_panel_focus);
    try std.testing.expect(session.focus_owner == .workspace);
    try std.testing.expect(session.workspace_focus_pending);
    try std.testing.expectEqual(@as(usize, 0), web_ops.webSurfaceTransitionsCount(session));

    // FP16 §3.4: 파일 focus가 곧 `.workspace`(활성 Term이 그 파일)다 — 토글은 workspace ↔ tree 왕복이 된다.
    _ = session.focusFilePanelSurface(sid);
    try std.testing.expectEqual(@as(?u64, sid), term_ops.focusedDockSurface(session));
    session.workspace_focus_pending = false;
    session.dispatchAppAction(.toggle_file_panel_focus);
    try std.testing.expect(session.focus_owner == .file_tree);
    // one-way compatibility action remains available but no longer owns the default chord.
    session.dispatchAppAction(.focus_file_tree);
    try std.testing.expect(session.focus_owner == .file_tree);
}

test "FP9 publish 대기 barrier가 typed ack 전까지 PTY·paste·drop을 fail-close한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    const b_open = try pane_ops.openFileTermInActivePane(session, "/tmp/fp9-surface-less-successor-b.md", .markdown);
    const b_id = b_open.term.file_entry.?.id;
    const a_open = try pane_ops.openFileTermInActivePane(session, "/tmp/fp9-live-active-a.md", .markdown);
    file_panel_ops.assignDockSurfaceIds(session);
    const a_surface = a_open.term.file_entry.?.surface_id;
    try std.testing.expect(a_surface != 0);
    try std.testing.expect(session.focusFilePanelSurface(a_surface));

    const terminal_inputs = session.total_terminal_input_events;
    const workspace_count = session.tabs.items.len;
    try std.testing.expect(file_panel_ops.closeFilePanelSurfaceNow(session, a_surface));
    // A를 닫으면 pane의 활성 Term이 승계되므로 baseline은 close **뒤**에 잡는다.
    const terminal_surface = term_ops.activeSurface(session).id;
    const terms_before_blocked_close = pane_ops.activePane(session).terms.items.len;
    // FP16: 파일이 pane 탭이라 close는 pane의 active_term 승계로 끝나고 입력은 workspace로 간다.
    // publish 대기 barrier는 그 다음 "승계된 파일로 focus" 요청이 만든다.
    const successor = file_panel_ops.fileEntryForId(session, b_id).?;
    dock_ops.requestDockEntryFocus(session, successor);
    try std.testing.expect(session.pending_dock_focus != null);
    try std.testing.expect(session.focus_owner == .dock_pending and session.focus_owner.dock_pending == session.pending_dock_focus.?.entry_id);
    // sid가 있어도 publish를 추측해 dock_surface로 승격하지 않는다 — typed completion만 승격이다.
    try std.testing.expect(term_ops.focusedDockSurface(session) == null);
    try std.testing.expect(session.inputFocus() == .dock_pending);

    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'x' } });
    try std.testing.expectEqual(terminal_inputs, session.total_terminal_input_events);
    const paste_queues = session.pending_pastes.count();
    session.pasteText("danger\n", false);
    try std.testing.expectEqual(paste_queues, session.pending_pastes.count());
    try std.testing.expectEqual(@as(usize, 0), session.pending_paste_confirm.items.len);
    session.handleDroppedFiles("/tmp/private.txt\x00");
    try std.testing.expectEqual(paste_queues, session.pending_pastes.count());
    const upload_counter = session.upload_counter;
    try std.testing.expect(session.handleDroppedImage("/tmp/private-image.png", "private-image"));
    try std.testing.expectEqual(upload_counter, session.upload_counter);
    // **닫기는 barrier를 통과한다**(2026-08-21). barrier가 지목한 entry는 활성 pane의 활성 Term이라
    // 대상이 확정돼 있고, 여기서 삼키면 "파일 탭을 닫았더니 승계된 파일 탭에서 ⌘W가 안 먹는다"가 된다.
    // 다만 그 판정을 이 테스트의 주제(PTY·paste·drop fail-close)와 섞지 않으려고, 여기서는 barrier가
    // **여전히 살아 있는 동안** 위 세 경로가 막혀 있다는 사실만 확인하고 close는 아래 전용 테스트가 본다.
    try std.testing.expect(dock_ops.pendingDockEntryOwnsInput(session));
    try std.testing.expectEqual(workspace_count, session.tabs.items.len);
    try std.testing.expectEqual(terms_before_blocked_close, pane_ops.activePane(session).terms.items.len);
    try std.testing.expectEqual(terminal_surface, term_ops.activeSurface(session).id);
    try std.testing.expect(session.pending_file_panel_close == null);
    try std.testing.expect(file_panel_ops.fileEntryForId(session, b_id) != null);

    try std.testing.expect(session.completePendingDockFocus(successor.surface_id));
    try std.testing.expect(term_ops.focusedDockSurface(session) == successor.surface_id);
    try std.testing.expectEqual(successor.surface_id, term_ops.focusedDockSurface(session).?);
}

