test "promotePaneToNewWorkspace: 그룹이 있으면 새 워크스페이스를 첫 그룹 마커 앞(최상위)에 넣어 그룹 흡수를 막는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // splitActivePane = 실 PTY/CoreText
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.backing_width_px = session.sidebar_width_px + 800;
    session.backing_height_px = 600;
    session.window_padding_px = .{};

    // 탭 3개 [t0, t1, t2]. t1을 그룹 시작 마커로 → 그룹(t1,t2), t0은 최상위(첫 마커 이전, §2.1 연속 파티션).
    inline for (0..2) |_| _ = try tab_ops.newTab(session); // [t0, t1, t2], 활성 t2
    tab_ops.createGroupAbsorbForTab(session, session.tabs.items[1]); // 마커=t1 → [t0(top), (t1 grp, t2)]
    try std.testing.expectEqual(@as(?usize, 1), session.firstGroupStartIndex());

    // 활성 t0으로 전환 후 split → t0 pane 2개([a,b]), 활성 b.
    try std.testing.expect(tab_ops.switchTab(session, 0));
    const pane_a = pane_ops.activePane(session);
    try pane_ops.splitActivePane(session, .horizontal);
    const pane_b = pane_ops.activePane(session);
    try std.testing.expect(pane_b != pane_a);
    try std.testing.expectEqual(@as(usize, 3), session.tabs.items.len);

    // pane b를 새 워크스페이스로 분리 → 끝 append가 아니라 첫 그룹 마커(현재 idx1) **직전**(idx1)에 삽입.
    pane_ops.promotePaneToNewWorkspace(session, pane_b);

    // 탭 4개, 새 탭은 idx1(활성), 최상위(group_start==null 마커 아님), 그룹 마커는 idx2로 밀림.
    try std.testing.expectEqual(@as(usize, 4), session.tabs.items.len);
    try std.testing.expectEqual(@as(usize, 1), session.app_window.active_tab);
    const new_tab = session.tabs.items[1];
    try std.testing.expectEqual(@as(usize, 1), new_tab.panes.items.len);
    try std.testing.expectEqual(pane_b, new_tab.panes.items[0]);
    try std.testing.expect(new_tab.group_start == null); // 마커 아님 = 단독 최상위(흡수 안 됨)
    try std.testing.expect(session.tabs.items[2].group_start != null); // 그룹 마커가 idx2로 이동(그룹 유지)
    try std.testing.expectEqual(@as(?usize, 2), session.firstGroupStartIndex());
    // 병렬 배열 정합: 새 탭 surface가 tabs와 같은 인덱스, app_window.tabs가 surface_ptrs.items로 재바인딩.
    try std.testing.expectEqual(pane_b.activeTerm().surface, session.surface_ptrs.items[1]);
    try std.testing.expectEqual(session.surface_ptrs.items.ptr, session.app_window.tabs.ptr);

    // projectRows: 새 카드 depth 0(들여쓰기 없음)이고 첫 그룹 헤더 **앞**에 뜬다(안 사라짐).
    tab_ops.recomputeVisibleTabs(session);
    var new_card_slot: ?usize = null;
    var first_header_slot: ?usize = null;
    for (session.sidebar_rows.items, 0..) |row, slot| switch (row) {
        .agent_toggle, .agent, .recovered_sessions_header, .recovered_session => {},
        .card => |c| if (c.tab == 1) {
            new_card_slot = slot;
            try std.testing.expectEqual(@as(u8, 0), c.depth); // 최상위 = 들여쓰기 0
        },
        .group_header => if (first_header_slot == null) {
            first_header_slot = slot;
        },
    };
    try std.testing.expect(new_card_slot != null); // 사이드바에서 안 사라짐
    try std.testing.expect(first_header_slot != null);
    try std.testing.expect(new_card_slot.? < first_header_slot.?); // 첫 그룹 헤더 앞(최상위 구간)

    // 하이라이트 정합: new_workspace 드롭 하이라이트가 첫 그룹 헤더 슬롯(= 삽입 위치)을 가리킨다.
    try std.testing.expectEqual(first_header_slot.?, pane_ops.newWorkspaceHighlightSlot(session));
}

test "promotePaneToNewWorkspace: 마지막 그룹이 접혀 있어도 새 워크스페이스가 사이드바에 보인다(그룹 흡수 안 됨)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.backing_width_px = session.sidebar_width_px + 800;
    session.backing_height_px = 600;
    session.window_padding_px = .{};

    // [t0(top), (t1 grp, t2)] — 마지막(유일) 그룹을 접는다. 끝 append면 새 탭이 이 접힌 그룹에 흡수돼 숨겨졌을 것.
    inline for (0..2) |_| _ = try tab_ops.newTab(session); // [t0, t1, t2]
    tab_ops.createGroupAbsorbForTab(session, session.tabs.items[1]);
    session.tabs.items[1].group_collapsed = true;

    try std.testing.expect(tab_ops.switchTab(session, 0));
    try pane_ops.splitActivePane(session, .horizontal);
    const pane_b = pane_ops.activePane(session);
    pane_ops.promotePaneToNewWorkspace(session, pane_b); // 첫 마커 앞(idx1)에 삽입 → 최상위

    // 새 탭 = idx1, 접힌 그룹 마커는 idx2. projectRows에서 새 카드는 보이고(흡수 안 됨) depth 0.
    tab_ops.recomputeVisibleTabs(session);
    var saw_new_card = false;
    var saw_header = false;
    var saw_grouped_member = false;
    for (session.sidebar_rows.items) |row| switch (row) {
        .agent_toggle, .agent, .recovered_sessions_header, .recovered_session => {},
        .card => |c| {
            if (c.tab == 1) {
                saw_new_card = true;
                try std.testing.expectEqual(@as(u8, 0), c.depth);
            }
            if (c.tab == 3) saw_grouped_member = true; // 접힌 그룹의 멤버(원 t2, 현재 idx3)
        },
        .group_header => saw_header = true,
    };
    try std.testing.expect(saw_new_card); // 접힌 그룹에 흡수됐다면 여기서 숨겨져 실패했을 버그
    try std.testing.expect(saw_header); // 그룹은 유지(헤더 존재)
    try std.testing.expect(!saw_grouped_member); // 접힘 → 멤버 카드는 숨김(접기 정상 동작 보존)
}

test "mergePaneIntoWorkspace: 활성 pane을 다른 워크스페이스에 합친다(target 활성 pane 좌우 split, 우측·활성)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.backing_width_px = session.sidebar_width_px + 800;
    session.backing_height_px = 600;
    session.window_padding_px = .{};

    // ws0: split → pane 2개([a,b]), 활성 b. ws1: newTab(활성이 ws1로). 다시 ws0으로 전환.
    const pane_a = pane_ops.activePane(session);
    try pane_ops.splitActivePane(session, .horizontal);
    const pane_b = pane_ops.activePane(session);
    _ = try tab_ops.newTab(session);
    try std.testing.expectEqual(@as(usize, 2), session.tabs.items.len);
    const ws1 = session.tabs.items[1];
    const ws1_pane0 = ws1.panes.items[0];
    try std.testing.expect(tab_ops.switchTab(session, 0));
    try std.testing.expectEqual(@as(usize, 0), session.app_window.active_tab);

    pane_ops.mergePaneIntoWorkspace(session, pane_b, 1); // 활성(ws0)의 pane b를 ws1에 합침

    // ws0은 a 하나, ws1은 [원래 pane0, b] 2개, 활성은 ws1, ws1 활성 pane = b(우측).
    try std.testing.expectEqual(@as(usize, 2), session.tabs.items.len);
    try std.testing.expectEqual(@as(usize, 1), session.app_window.active_tab);
    try std.testing.expectEqual(@as(usize, 1), session.tabs.items[0].panes.items.len);
    try std.testing.expectEqual(pane_a, session.tabs.items[0].panes.items[0]);
    try std.testing.expectEqual(@as(usize, 2), ws1.panes.items.len);
    try std.testing.expectEqual(pane_b, ws1.activePane());
    try std.testing.expectEqual(@as(usize, 2), PaneTree.leafCount(ws1.tree));
    switch (ws1.tree) { // split{a: 원래 pane0, b: pane_b}, 좌우(horizontal)
        .split => |sp| {
            try std.testing.expect(sp.direction == .horizontal);
            switch (sp.a) {
                .leaf => |l| try std.testing.expectEqual(ws1_pane0, l),
                .split => return error.TestExpectedLeaf,
            }
            switch (sp.b) {
                .leaf => |l| try std.testing.expectEqual(pane_b, l),
                .split => return error.TestExpectedLeaf,
            }
        },
        .leaf => return error.TestExpectedSplit,
    }
    // 대표 surface: ws0 = a, ws1 = b(새 활성 pane).
    try std.testing.expectEqual(pane_a.activeTerm().surface, session.surface_ptrs.items[0]);
    try std.testing.expectEqual(pane_b.activeTerm().surface, session.surface_ptrs.items[1]);
}

test "mergePaneIntoWorkspace: 단독 pane도 대상에 합치고 빈 소스 워크스페이스를 제거한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.backing_width_px = session.sidebar_width_px + 800;
    session.backing_height_px = 600;
    session.window_padding_px = .{};

    _ = try tab_ops.newTab(session); // tabs [ws0, ws1], 활성 ws1(단독 pane)
    const target_tab = session.tabs.items[1];
    const target_original_pane = target_tab.activePane();
    try std.testing.expect(tab_ops.switchTab(session, 0));
    const moved_pane = pane_ops.activePane(session);
    const moved_surface = moved_pane.activeTerm().surface;
    pane_ops.mergePaneIntoWorkspace(session, moved_pane, 1);

    // 소스 workspace는 사라지고 target이 index 0으로 당겨진다. Pane/Surface 포인터는 그대로라 PTY 재시작이 없다.
    try std.testing.expectEqual(@as(usize, 1), session.tabs.items.len);
    try std.testing.expectEqual(@as(usize, 0), session.app_window.active_tab);
    try std.testing.expectEqual(target_tab, session.tabs.items[0]);
    try std.testing.expectEqual(@as(usize, 2), target_tab.panes.items.len);
    try std.testing.expectEqual(moved_pane, target_tab.activePane());
    try std.testing.expectEqual(moved_surface, target_tab.activeTerm().surface);
    try std.testing.expectEqual(moved_surface, session.surface_ptrs.items[0]);
    switch (target_tab.tree) {
        .split => |sp| {
            try std.testing.expect(sp.direction == .horizontal);
            switch (sp.a) {
                .leaf => |l| try std.testing.expectEqual(target_original_pane, l),
                .split => return error.TestExpectedLeaf,
            }
            switch (sp.b) {
                .leaf => |l| try std.testing.expectEqual(moved_pane, l),
                .split => return error.TestExpectedLeaf,
            }
        },
        .leaf => return error.TestExpectedSplit,
    }
}

