        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{}; // 레이아웃 기하만 격리 — window padding(기본 8/4) inset은 gridFromBacking·loader 전용 테스트가 커버
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    // ⌘T → Term 2개, 활성 = 1.
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 't' }, .modifiers = .{ .command = true } });
    try std.testing.expectEqual(@as(usize, 2), pane_ops.activePane(session).terms.items.len);
    try std.testing.expectEqual(@as(usize, 1), pane_ops.activePane(session).active_term);

    // 탭 바는 단일 panel이라 터미널 영역(상단 타이틀바 띠 아래) 전체 폭의 상단 strip. 탭 0 = 바 좌단, 탭 1 = 바 우반.
    const bar_y: f64 = @as(f64, @floatFromInt(session.titlebar_strip_px)) + 1; // 띠 아래 바 안(y in [띠, 띠+바높이))
    const left_tab_x: f64 = @floatFromInt(session.sidebar_width_px + 30); // 탭 0 세그먼트(사이드바 우측 리사이즈 밴드보다 안쪽)
    session.mouse(1, left_tab_x, bar_y, 0, 0);
    try std.testing.expectEqual(@as(usize, 0), pane_ops.activePane(session).active_term); // 탭 0으로 전환

    // 탭 1(바 우반, 2탭이라 폭의 절반 이후) 클릭 → 다시 Term 1.
    const right_tab_x: f64 = @floatFromInt(session.sidebar_width_px + 600); // 바 폭(800)의 우반
    session.mouse(1, right_tab_x, bar_y, 0, 0);
    try std.testing.expectEqual(@as(usize, 1), pane_ops.activePane(session).active_term);

    // 탭 바 클릭은 터미널 선택을 시작하지 않는다(소비). 선택 드래그 플래그가 안 켜진다.
    try std.testing.expect(!session.mouse_drag_selecting);
}

// 탭에 호버하면 ✕가 뜨고(hovered_tab 설정), 그 ✕ zone을 클릭하면 그 Term이 닫히는지(PR-D2) — 실 init/spawn/
// teardown이라 macOS 게이트. ⌘T로 Term 3개를 만들고, 탭 1의 ✕ zone에 호버 후 클릭해 Term이 2개로 준다.
test "hovering a tab shows a close X; clicking it closes that Term" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{}; // 레이아웃 기하만 격리 — window padding(기본 8/4) inset은 gridFromBacking·loader 전용 테스트가 커버
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    // ⌘T 두 번 → Term 3개. 단일 panel이라 바 폭 = 터미널 폭(800/cw cols), 3탭 등폭.
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 't' }, .modifiers = .{ .command = true } });
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 't' }, .modifiers = .{ .command = true } });
    try std.testing.expectEqual(@as(usize, 3), pane_ops.activePane(session).terms.items.len);
    markAllTermsAtPrompt(session); // idle 셸 흉내 — ✕ 닫기가 확인 모달 없이 즉시 진행되게

    // 활성 pane의 바 rect를 구해 탭 1의 ✕ zone x를 계산한다.
    var lr: std.ArrayList(PaneTree.LeafRect) = .empty;
    defer lr.deinit(allocator);
    try tab_ops.activeTabLeafRects(session, allocator, session.termRect(), &lr);
    // **hit-test 와 같은 인자로** metrics 를 만든다: `updateHoveredTab` 은 `pb.tabs`(grip 제외)와 실제
    // `tab_width_cols` 로 만든다. 전체 바 rect 로 만들면 세그먼트가 어긋나 테스트가 엉뚱한 자리를 짚는다.
    const pb = pane_ops.paneBar(session, lr.items[0].rect, lr.items[0].leaf).?;
    const bar = pb.tabs;
    const m = barMetrics(bar, session.cell_width_px, 3, session.buildChromeTokens().space.tab_width_cols, 0).?;
    // ✕ 자리도 **세그먼트에서 직접** 뽑는다(칸 산수는 탭 폭·패딩이 바뀌면 조용히 다른 칸을 짚는다).
    const seg1_close = m.segOf(1);
    const close_x: f64 = seg1_close.close_start_px + 1;
    const bar_y: f64 = @floatFromInt(bar.y + 1);

    // 호버 → hovered_tab이 (활성 pane, 탭 1)로 설정된다(✕가 그려질 대상).
    _ = session.hoverCursor(close_x, bar_y, 0);
    try std.testing.expect(session.hovered_tab != null);
    try std.testing.expectEqual(@as(usize, 1), session.hovered_tab.?.tab);
    try std.testing.expect(m.inCloseZone(1, close_x)); // ✕ zone 안
    // ✕ **존 위**라는 것도 따로 선다 — 렌더가 그 자리에만 호버 배경을 얹는다(‹/› 와 같은 신호,
    // 사용자 요청 2026-08-18). 탭 위이되 ✕ 밖이면 이 값은 비어 있어야 한다.
    try std.testing.expect(session.hovered_tab_close != null);
    try std.testing.expectEqual(@as(usize, 1), session.hovered_tab_close.?.tab);
    // 제목 자리는 **세그먼트에서 직접** 뽑는다 — 칸 산수로 짚으면 탭 폭에 따라 ✕ 존과 겹칠 수 있다.
    const seg1 = m.segOf(1);
    const tab1_title_x: f64 = seg1.start_px + 1;
    try std.testing.expect(seg1.has_close and tab1_title_x < seg1.close_start_px); // 이 좌표가 ✕ 밖임을 먼저 못박는다
    _ = session.hoverCursor(tab1_title_x, bar_y, 0);
    try std.testing.expect(session.hovered_tab != null); // 여전히 그 탭 호버
    try std.testing.expect(session.hovered_tab_close == null); // 그러나 ✕ 존은 아니다
    // "+" 버튼 위: 탭 호버는 풀리고 plus 호버가 선다(마지막 탭에 ✕ 오표시 방지 규칙과 짝).
    const plus_x: f64 = @floatFromInt(bar.x + (m.plusZoneStart() + chrome.components.tabbar.Metrics.plus_button_cols / 2) * session.cell_width_px);
    _ = session.hoverCursor(plus_x, bar_y, 0);
    try std.testing.expect(session.hovered_plus != null);
    try std.testing.expect(session.hovered_tab == null);
    try std.testing.expect(session.hovered_tab_close == null);
    // 다시 ✕ 위로 돌아와 아래 클릭이 그 자리를 누르게 한다.
    _ = session.hoverCursor(close_x, bar_y, 0);

    // ✕ 클릭 → 탭 1 Term 닫힘 → 2개. 닫은 뒤 호버는 비워진다(stale 방지).
    session.mouse(1, close_x, bar_y, 0, 0);
    try std.testing.expectEqual(@as(usize, 2), pane_ops.activePane(session).terms.items.len);
    try std.testing.expect(session.hovered_tab == null);
    try std.testing.expect(!session.ended_seen); // 아직 Term 남음 — 세션 유지
}

// 닫기 확인(실행 중 명령 보호)의 트리거 판정은 코어의 cursorIsAtPrompt(셸 통합 OSC 133 + alt 화면)로 결정된다.
// 아래 테스트들은 활성 Term 코어의 semantic_state/alt_active를 직접 세팅해 각 경우를 **결정론적**으로 증명한다
// (controlled_smoke는 `/bin/sh -c "printf; read"`라 OSC 133·alt를 안 쏘므로 코어 상태는 세팅한 값 그대로 유지).
// 프로세스/pgid를 안 쓰므로 job-control 셸이 필요 없다.
fn initSmokeSessionTwoTerms(allocator: std.mem.Allocator) !*AppSession {
    const session = try allocator.create(AppSession);
    errdefer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    errdefer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);
    // ⌘T → Term 2개(활성 pane). .term_or_pane 닫기는 활성 Term 하나만 teardown한다.
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 't' }, .modifiers = .{ .command = true } });
    try std.testing.expectEqual(@as(usize, 2), pane_ops.activePane(session).terms.items.len);
    return session;
}

test "관측 tail 상한은 여러 행 composer의 프롬프트 마커를 계속 실어 준다" {
    // 상수 하나가 결함의 두 번째 원인이었다. 실측(codex 0.146.0)에서 composer는 사용자 입력 행 수만큼 자라므로,
    // tail 상한이 짧으면 프롬프트 마커가 tail 밖으로 밀려 **유일한 idle 근거가 사라지고** PTY activity 폴백이 타이핑을
    // running으로 단정한다. 실제 상수 + 실제 코어 직렬화 + 순수 observer를 함께 통과시켜 제품 경로를 못박는다
    // (PTY·GUI 없이 검증 가능한 구간이다).
    // **넓은 창까지 확인한다.** `dumpRecentTextUtf8`이 `max_bytes / (cols*4 + 1)`로 행 수를 다시 계산하므로, byte 상한이
    // 작으면 행 상수가 조용히 무력화된다 — 32KiB일 때 640칸에서 12행으로 되돌아갔다(코드 리뷰에서 재현).
    const allocator = std.testing.allocator;
    const observer = maru.session.agent_observer;
    inline for (.{ 80, 320, 640 }) |cols| {
        var core = try terminal.TerminalCore.init(allocator, .{ .cols = cols, .rows = 30 });
        defer core.deinit();

        try core.write("› line1\r\n");
        var row: usize = 2;
        while (row <= 14) : (row += 1) {
            var buf: [32]u8 = undefined;
            try core.write(try std.fmt.bufPrint(&buf, "  line{d}\r\n", .{row}));
        }
        try core.write("\r\n  Context 4% used · weekly 67% left · gpt-5.6-sol low");

        const tail = try core.dumpRecentTextUtf8(allocator, agent_ops.agent_screen_tail_rows, agent_ops.agent_screen_tail_bytes);
        defer allocator.free(tail);
        try std.testing.expect(std.mem.indexOf(u8, tail, "›") != null);
        try std.testing.expectEqual(observer.State.idle, observer.detect(.codex, .{ .screen = tail, .output_active = true }).state);

        // non-vacuous: 옛 12행 상한으로 같은 화면을 읽으면 마커가 빠지고 폴백이 running을 세운다.
        const short_tail = try core.dumpRecentTextUtf8(allocator, 12, agent_ops.agent_screen_tail_bytes);
        defer allocator.free(short_tail);
        try std.testing.expect(std.mem.indexOf(u8, short_tail, "›") == null);
        try std.testing.expectEqual(observer.State.running, observer.detect(.codex, .{ .screen = short_tail, .output_active = true }).state);
    }
}

test "agent representative prioritizes blocked over running over active idle" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionTwoTerms(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    // 기대값이 한국어 상태 문구다 — 재는 것은 **어느 상태로 분류하는가**이고 그 판정은 문장으로 봐야
    // 드러난다. `init` 이 언어를 세우므로 **그 뒤**에 고정한다.
    const lang_before = maru.i18n.lang();
    defer maru.i18n.setLang(lang_before);
    maru.i18n.setLang(.ko);

    const tab = tab_ops.activeTab(session);
    const background = tab.activePane().terms.items[0];
    const active = tab.activeTerm();
    active.agent_kind = .claude;
    active.agent_state = .idle;
    background.agent_kind = .codex;
    background.agent_state = .running;
    try std.testing.expectEqual(AgentKind.codex, tab_ops.tabAgentKind(tab));
    {
        const line = try sidebar_ops.workspaceStatusLine(session, tab);
        defer allocator.free(line);
        try std.testing.expect(std.mem.endsWith(u8, line, "진행중"));
    }

    background.agent_state = .blocked;
    try std.testing.expectEqual(AgentKind.codex, tab_ops.tabAgentKind(tab));
    {
        const line = try sidebar_ops.workspaceStatusLine(session, tab);
        defer allocator.free(line);
        try std.testing.expectEqualStrings("? 입력 대기", line);
    }
}

/// 테스트 유틸 — 세션의 모든 Term 코어를 "프롬프트에 idle"(OSC 133 input) 상태로 표시한다. controlled_smoke는
/// OSC 133을 안 쏘므로 코어가 unknown이라 닫기 확인이 보수적으로 뜬다(cursorIsAtPrompt=false). 닫기를 **메커니즘**
/// 으로만 쓰는(닫기 확인 자체가 검증 대상이 아닌) 탭/pane/Term 수명 테스트가, 프로덕션의 통합 셸 idle 상태를 흉내 내
/// 즉시 닫히게 한다. 새 Term을 만든 뒤 닫기 직전에 부른다.
fn markAllTermsAtPrompt(session: *AppSession) void {
    for (session.tabs.items) |tab| {
        for (tab.panes.items) |pane| {
            for (pane.terms.items) |t| t.surface.core.semantic_state = .input;
        }
    }
}

test "close-confirm: 셸이 프롬프트(OSC 133 input)면 확인 모달 없이 즉시 닫는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionTwoTerms(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    // 정착한 idle 프롬프트 = 셸 통합이 입력 대기(B)를 마킹한 상태 → 실행 중 명령 없음.
    pane_ops.activePane(session).activeTerm().surface.core.semantic_state = .input;
    try std.testing.expect(!session.closeTargetHasRunningJob(.term_or_pane));

    // requestClose → 즉시 닫힘(모달 안 뜸, 보류 없음).
    session.requestClose(.term_or_pane);
    try std.testing.expectEqual(@as(usize, 1), pane_ops.activePane(session).terms.items.len);
    try std.testing.expect(!session.chrome_host.confirm.open);
    try std.testing.expect(session.pending_confirm == .none);
}

test "close-confirm: 명령 실행 중(OSC 133 command)이면 확인 모달을 띄우고 닫기를 보류한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionTwoTerms(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    // 셸이 명령 출력 시작(C)을 마킹 = 포그라운드 명령 실행 중.
    pane_ops.activePane(session).activeTerm().surface.core.semantic_state = .command;
    try std.testing.expect(session.closeTargetHasRunningJob(.term_or_pane));

    // requestClose → 모달 열고 보류(안 닫음).
    session.requestClose(.term_or_pane);
    try std.testing.expectEqual(@as(usize, 2), pane_ops.activePane(session).terms.items.len);
    try std.testing.expect(session.chrome_host.confirm.open);
    try std.testing.expect(session.pending_confirm == .close);
}

// Phase 7f/4g: 브라우저 web term은 셸 명령이 없어(rt.live_initialized=false → termHasRunningJob 즉시 false) running-job
// 게이트를 안 타 조용히 닫히던 것을, 열린 웹 페이지=잃을 수 있는 상태라 "닫을까요?" 확인 모달로 게이트한다(제보). 실행 중
// 명령이 전혀 없어도 scopeHasWebBrowser 분기가 모달을 띄우는 걸 requestClose 진입점부터 증명한다(14차 리뷰 [4]).
test "close-confirm: 브라우저 web term은 실행 중 명령 없이도 확인 모달을 띄운다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    // 활성 pane에 browser web Term을 추가·활성화 → pane이 [terminal, browser]라 .term_or_pane이 .term으로 해석되고
    // 활성 term=browser. web term은 live_initialized=false라 running job이 아니다(이게 조용히 닫히던 버그의 핵).
    const w1 = try web_ops.createWebTerm(session, .browser);
    const pane = pane_ops.activePane(session);
    try pane.terms.append(allocator, w1);
    term_ops.focusTerm(session, pane.terms.items.len - 1);
    try std.testing.expectEqual(web_panel_layout.PanelKind.browser, pane.activeTerm().web_panel_kind);
    try std.testing.expect(!session.closeTargetHasRunningJob(.term_or_pane)); // 셸 명령 없음
    try std.testing.expect(web_ops.scopeHasWebBrowser(session, .term)); // 하지만 브라우저는 있음

    // requestClose → 실행 중 명령이 없어도 웹 브라우저라 확인 모달을 띄우고 닫기를 보류(안 닫음).
    const terms_before = pane.terms.items.len;
    session.requestClose(.term_or_pane);
    try std.testing.expect(session.chrome_host.confirm.open);
    try std.testing.expect(session.pending_confirm == .close);
    try std.testing.expectEqual(terms_before, pane.terms.items.len); // 아직 안 닫음(확정 대기)
}

// 마지막(유일) 창에서 세션 전체를 닫는 인앱 제스처(⌘W cascade 끝)는 창 하나 닫기가 아니라 앱 종료다 — Cmd+Q와 동일한
// "maru를 종료할까요?" 종료 확인을 실행 중 명령 유무와 무관하게 띄우고, ended_seen을 미리 latch하지 않아(취소 가능)
// 사용자가 종료를 물릴 수 있게 한다. is_last_window는 host(Swift)가 매 tick 주입하는 값이라 테스트가 직접 세팅한다.
test "close-confirm: 마지막 창(is_last_window)에서 세션 닫기는 Cmd+Q와 동일한 종료 확인을 띄운다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionTwoTerms(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    // 두 Term을 하나로 줄여 이제 단일 Term·단일 pane·단일 탭 = requestClose(.term_or_pane)가 .session으로 해석되게.
    markAllTermsAtPrompt(session);
    term_ops.closeActiveTerm(session); // 2→1 Term(닫기 확인 없이 메커니즘만)
    try std.testing.expectEqual(@as(usize, 1), pane_ops.activePane(session).terms.items.len);
    try std.testing.expectEqual(@as(usize, 1), session.tabs.items.len);

    // 마지막 창 → 세션(창) 닫기는 앱 종료라 requestAppQuit 경로: pending_quit을 세우고 ended_seen은 latch하지 않는다.
    // 셸이 프롬프트(실행 중 명령 없음)여도 항상 뜬다(Cmd+Q 모델 — 종료는 창 하나 닫기보다 파괴적).
    session.is_last_window = true;
    session.requestClose(.term_or_pane);
    try std.testing.expect(session.pending_confirm == .quit);
    try std.testing.expect(session.chrome_host.confirm.open);
    try std.testing.expect(!session.ended_seen); // 아직 안 닫음 — 확정 대기
    try std.testing.expect(session.pending_confirm == .quit); // 닫기 보류가 아니라 종료 보류
    try std.testing.expectEqual(QuitDecision.none, session.quit_decision); // 결정 전

    // 모달 확정(Enter) → quit_decision=.accepted (host가 다음 tick summary로 받아 NSApp.terminate).
    session.dispatchChromeAction(.confirm_accept);
    try std.testing.expectEqual(QuitDecision.accepted, session.quit_decision);
    try std.testing.expect(session.pending_confirm == .none);
}

// 비-마지막 창(멀티 창의 한 창·is_last_window=false, 기본값)에서 세션 닫기는 앱 종료가 아니라 그 창만 닫기다 —
// 종료 확인 없이 세션 종료를 latch(ended_seen)해 tick의 closeWindowOrQuit이 그 창만 닫는다(앱은 계속).
test "close-confirm: 비-마지막 창(is_last_window=false)에서 세션 닫기는 종료 확인 없이 세션 종료를 latch한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionTwoTerms(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    markAllTermsAtPrompt(session);
    term_ops.closeActiveTerm(session); // 2→1 Term
    try std.testing.expectEqual(@as(usize, 1), pane_ops.activePane(session).terms.items.len);

    // is_last_window=false(멀티 창의 비-마지막 창·기본값) → 이 창만 닫기: 종료 확인 안 뜨고 세션 종료 latch.
    session.is_last_window = false;
    session.requestClose(.term_or_pane);
    try std.testing.expect(session.pending_confirm != .quit);
    try std.testing.expect(!session.chrome_host.confirm.open);
    try std.testing.expect(session.ended_seen); // 이 창(세션) 종료 latch — Swift가 이 창만 닫음
}

test "close-confirm: 풀스크린 TUI(alt 화면)면 셸 통합 없이도 확인 모달을 띄운다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionTwoTerms(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    // semantic_state가 프롬프트여도 alt 화면(vim·claude 등)이면 실행 중으로 본다.
    const t = pane_ops.activePane(session).activeTerm();
    t.surface.core.semantic_state = .input;
    t.surface.core.alt_active = true;
    try std.testing.expect(session.closeTargetHasRunningJob(.term_or_pane));
}

test "close-confirm: 셸 통합 없음(unknown, primary 화면)이면 보수적으로 확인 모달" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionTwoTerms(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    // OSC 133을 안 쏘는 셸(semantic_state=unknown) + primary 화면 → 프롬프트인지 모름 → 보수적으로 확인(Ghostty
    // 정책). 데이터 손실 방지 우선. maru 기본 zsh는 통합을 주입하므로 대부분 세션은 이 경로가 아님.
    pane_ops.activePane(session).activeTerm().surface.core.semantic_state = .unknown;
    try std.testing.expect(session.closeTargetHasRunningJob(.term_or_pane));
}

// ══ 컨트롤 플레인 collector (Track C A1) 테스트 ═══════════════════════════════════════════════════════════
// docs/control-plane.md §2(전역 레지스트리 부재 → Swift가 창 순회, Zig는 한 세션 tabs→panes→terms 트리를 중립
// DTO로 평탄화)·§3(엔티티: 좌표·focused·cwd·git_branch·agent·at_prompt 3상)·§5(코어 read는 core_mutex 아래 복사만)·
// §16(collector L4 = 이 파일). 순수 매핑 두 개(atPromptWire·agentInfoWire)는 헤드리스, 트리 평탄화(collectSession)는
// 실 AppSession(controlled_smoke — OSC 133/alt를 안 쏘므로 코어 상태를 세팅한 값 그대로 결정론)으로 검증한다.

// ── 순수 매핑 1) at_prompt 3상(§3): alt 오버라이드 + prompt/input=true, command=false, unknown=null(false로 안 접음) ──
test "collector atPromptWire: semantic_state(+alt) → at_prompt 3상(unknown≠not_at_prompt)" {
    // alt-screen이면 semantic_state 무관 not_at_prompt(§3 alt 오버라이드).
    for ([_]terminal.SemanticPrompt{ .unknown, .prompt, .input, .command }) |s| {
        try std.testing.expectEqual(control_surface.AtPrompt.not_at_prompt, atPromptWire(s, true));
    }
    // primary 화면: OSC 133 분류대로.
    try std.testing.expectEqual(control_surface.AtPrompt.at_prompt, atPromptWire(.prompt, false));
    try std.testing.expectEqual(control_surface.AtPrompt.at_prompt, atPromptWire(.input, false));
    try std.testing.expectEqual(control_surface.AtPrompt.not_at_prompt, atPromptWire(.command, false));
    // 핵심 불변식: unknown(OSC 133 미통합 셸, 대다수)은 unknown이지 not_at_prompt가 아니다(§3 — false로 접지 않음).
    try std.testing.expectEqual(control_surface.AtPrompt.unknown, atPromptWire(.unknown, false));
}

// ── 순수 매핑 2) agent 내부→wire(§3): none=null(생략), kind/state 조합 ──
test "collector agentInfoWire: blocked는 별도 wire 값" {
    const i = agentInfoWire(.claude, .blocked).?;
    try std.testing.expectEqual(control_surface.AgentState.blocked, i.state);
    const j = agentInfoWire(.codex, .blocked).?;
    try std.testing.expectEqual(control_surface.AgentState.blocked, j.state);
    try std.testing.expect(agentInfoWire(.none, .blocked) == null);
}

test "collector agentInfoWire: none→null, claude/codex × running/idle/unknown 매핑(내부→wire 격리)" {
    // 실 세션 하네스(initSmokeSessionSized)는 PTY·macOS 경로를 쓴다 — 비-macOS에서는 건너뛴다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    try std.testing.expect(agentInfoWire(.none, .running) == null); // none이면 state 무관 null(wire 생략)
    try std.testing.expect(agentInfoWire(.none, .idle) == null);

    const a = agentInfoWire(.claude, .running).?;
    try std.testing.expectEqual(control_surface.AgentKind.claude, a.kind);
    try std.testing.expectEqual(control_surface.AgentState.running, a.state);

    const b = agentInfoWire(.codex, .idle).?;
    try std.testing.expectEqual(control_surface.AgentKind.codex, b.kind);
    try std.testing.expectEqual(control_surface.AgentState.idle, b.state);

    const c = agentInfoWire(.claude, .unknown).?; // running/idle 아닌 3상 나머지 보존
    try std.testing.expectEqual(control_surface.AgentState.unknown, c.state);
}

// 실 AppSession(controlled_smoke) 단일 term + 창 사이즈 세팅(split/newTab 선행). initSmokeSessionTwoTerms와 같은
// 하니스 패턴(§ 위 close-confirm 테스트) — collector는 이 실 트리를 평탄화한다.
fn initSmokeSessionSized(allocator: std.mem.Allocator) !*AppSession {
    const session = try allocator.create(AppSession);
    errdefer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    errdefer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);
    return session;
}

test "automatic agent sessions dock width reflows the live pane without persisting a view width" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    _ = try session.resize(1600, 900, 1000);

    // The titlebar launcher additionally opens a native file-picker in an empty workspace; set
    // the already-initialized shared dock directly so this test isolates the layout contract.
    session.dock.presented = true;
    session.dock.collapsed = false;
    session.dock.side = .right;
    session.dock.size = 0;
    session.dock.view = .explorer;
    for (session.tabs.items) |tab| pane_ops.resizeTabPanes(session, tab);
    pane_ops.recomputeActivePaneRect(session);
    const explorer_dock = dock_ops.dockGeometry(session);
    const explorer_pane = session.active_pane_rect;

    // This is a synchronous geometry test.  The real archive scanner is covered by its
    // own isolated AppKit fixture; starting its detached worker here would make this test
    // depend on a filesystem job that outlives the layout assertion and test allocator.
    session.agent_session_archive_initialized = false;
    dock_ops.setDockView(session, .agent_sessions);
    session.agent_session_archive_initialized = true;
    const archive_dock = dock_ops.dockGeometry(session);
    const archive_pane = session.active_pane_rect;
    try std.testing.expectEqual(@as(u32, 0), session.dock.size); // view width must not leak into persistence
    try std.testing.expectEqual(dock_layout.default_agent_sessions_right_pt, archive_dock.dock.w);
    try std.testing.expectEqual(dock_layout.default_right_pt, explorer_dock.dock.w);
    try std.testing.expect(archive_pane.w < explorer_pane.w);
    try std.testing.expectEqual(
        layout_math.gridFromRectPx(session.cell_width_px, session.cell_height_px, archive_pane.w, archive_pane.h),
        term_ops.activeSurface(session).core.size,
    );

    dock_ops.setDockView(session, .explorer);
    try std.testing.expectEqual(@as(u32, 0), session.dock.size);
    try std.testing.expectEqual(explorer_pane.w, session.active_pane_rect.w);
    try std.testing.expectEqual(
        layout_math.gridFromRectPx(session.cell_width_px, session.cell_height_px, session.active_pane_rect.w, session.active_pane_rect.h),
        term_ops.activeSurface(session).core.size,
    );
}

// ── 3) 단일 term: 좌표·id·generation·kind·focused·membership + 없는 cwd/agent 생략(§2·§3) ──
test "collector: 단일 term 세션 — 좌표·id·focused·membership·terminal 메타" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    const term = pane_ops.activePane(session).activeTerm();
    term.surface.core.semantic_state = .input; // 프롬프트 idle → at_prompt=true
    const active_id = term_ops.activeSurface(session).id;

    // **커널 조회 결과를 심는다.** 스모크 세션은 OSC 7을 안 보내므로 축은 2단째(커널)로 내려간다. 실제
    // 커널 값은 테스트 프로세스의 cwd라 환경마다 달라 값 비교를 못 하므로, 폴 주기 안에 있는 것처럼
    // `proc_cwd_polled_ns`를 지금으로 맞춰 다시 묻지 않게 하고 고정 표본을 넣는다.
    const seeded_cwd = "/private/var/empty/maru-collector-fixture";
    term.rt.proc_cwd_polled_ns = std.Io.Clock.awake.now(session.io).nanoseconds;
    @memcpy(term.rt.proc_cwd_buf[0..seeded_cwd.len], seeded_cwd);
    term.rt.proc_cwd_len = seeded_cwd.len;
    try std.testing.expectEqual(@as(usize, 0), term.rt.observation.cwd.items.len); // 전제: OSC 7 없음

    const c = try session.collectSession(allocator, 42, .normal);
    defer c.deinit();

    try std.testing.expectEqual(@as(usize, 1), c.snapshot.surfaces.len);
    const dto = c.snapshot.surfaces[0];
    try std.testing.expectEqual(active_id, dto.surface_id); // id = surface.id(M0a)
    try std.testing.expectEqual(@as(u64, 0), dto.generation); // generation 0(§3 defense-in-depth 보조, M1 respawn 전)
    try std.testing.expectEqual(control_surface.SurfaceKind.terminal, dto.kind()); // web는 Phase 4
    try std.testing.expectEqual(@as(u64, 42), dto.window); // window_id 주입
    try std.testing.expectEqual(@as(u32, 0), dto.tab); // 0-based
    try std.testing.expectEqual(@as(u32, 0), dto.pane);
    try std.testing.expect(dto.focused); // key 창(window_focused 기본 true)의 활성 surface
    try std.testing.expectEqual(control_surface.AtPrompt.at_prompt, dto.detail.terminal.at_prompt);
    try std.testing.expect(dto.detail.terminal.agent == null); // controlled_smoke는 에이전트 없음

    // **cwd는 GUI와 같은 답이어야 한다.** OSC 7이 없어도 축이 커널 조회로 답한다
    // (docs/editor-surface-dock.md §3.5의 2단 규칙 — 사이드바·소스 컨트롤·탐색기·상태바와 같은 지점).
    // 예전에는 collector만 관측을 직독해 이 필드가 **항상** null이었고, 그래서 화면에는 폴더가 보이는데
    // `maru sessions list`는 생략하는 상태가 셸 통합 없는 셸·재개 Term에서 상시였다.
    try std.testing.expectEqualStrings(seeded_cwd, dto.detail.terminal.cwd orelse return error.CollectorCwdMissing);
    // 브랜치는 그 cwd에서 파생된다 — 심은 경로는 어떤 조상에도 `.git`이 없으므로 없는 것이 맞다.
    try std.testing.expect(dto.detail.terminal.git_branch == null);

    try std.testing.expectEqual(@as(usize, 1), c.snapshot.windows.len);
    const w = c.snapshot.windows[0];
    try std.testing.expectEqual(@as(u64, 42), w.window_id);
    try std.testing.expectEqual(maru.session.WindowKind.normal, w.window_kind);
    try std.testing.expectEqualSlices(u64, &.{active_id}, w.surface_ids);
}

// 원격 두 형태에서 wire `cwd`/`git_branch` — GUI 폴더줄·브랜치줄과 같은 답이어야 한다.
//
// 두 경우를 가르는 것이 OSC 7 authority(`cwd_host`, §9.2)다. 원격 authority가 보고한 경로는 곧 "이 터미널이
// 서 있는 곳"이므로 그대로 싣는다. 반면 maru ssh 세션(OSC 5379 `ssh;<dest>`)인데 원격 셸이 OSC 7을 안
// 보내면 관측에 남은 것은 **ssh 이전의 로컬 경로**다. 그 낡은 값을 원격 세션의 cwd인 양 실으면 안 된다.
//
// 브랜치는 두 경우 다 없다. 원격 경로로 로컬 `.git`을 읽으면 같은 프로젝트를 양쪽에 둔 흔한 배치에서
// 원격 세션에 로컬 브랜치가 붙는다.
test "collector: 원격 cwd는 그대로 싣고 maru ssh 세션은 낡은 로컬 경로를 싣지 않는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;

    {
        // 원격이 보고한 경로와 **같은 경로가 로컬에도 저장소로 존재**하는 배치를 만든다. 이게 브랜치 누출의
        // 실제 조건이다 — 같은 프로젝트를 로컬과 원격에 두면 흔히 경로까지 같다.
        // `std.testing.tmpDir`는 0.16에서 realpath를 안 주므로 경로를 직접 만든다(git_backend.zig와 같은 관용구).
        var cwd_buf: [std.fs.max_path_bytes]u8 = undefined;
        const cwd_ptr = std.c.getcwd(&cwd_buf, cwd_buf.len) orelse return error.NoCwd;
        const cwd = std.mem.span(@as([*:0]u8, @ptrCast(cwd_ptr)));
        var repo_buf: [std.fs.max_path_bytes]u8 = undefined;
        const repo = try std.fmt.bufPrint(&repo_buf, "{s}/.zig-cache/tmp-collector-remote-repo", .{cwd});
        const io = std.testing.io;
        const here = std.Io.Dir.cwd();
        here.deleteTree(io, ".zig-cache/tmp-collector-remote-repo") catch {};
        defer here.deleteTree(io, ".zig-cache/tmp-collector-remote-repo") catch {};
        try here.createDirPath(io, ".zig-cache/tmp-collector-remote-repo/.git");
        try here.writeFile(io, .{
            .sub_path = ".zig-cache/tmp-collector-remote-repo/.git/HEAD",
            .data = "ref: refs/heads/local-branch-must-not-leak\n",
        });

        const session = try initSmokeSessionSized(allocator);
        defer allocator.destroy(session);
        defer session.deinit();
        const term = pane_ops.activePane(session).activeTerm();
        var osc7_buf: [std.fs.max_path_bytes + 64]u8 = undefined;
        try term.surface.core.write(try std.fmt.bufPrint(&osc7_buf, "\x1b]7;file://build-box.example.com{s}\x07", .{repo}));

        const c = try session.collectSession(allocator, 42, .normal);
        defer c.deinit();
        const t = c.snapshot.surfaces[0].detail.terminal;
        // host 접두는 붙이지 않는다 — `TerminalMeta`에 host 필드가 없고 접두는 GUI 폴더줄의 표기 규약이다.
        try std.testing.expectEqualStrings(repo, t.cwd orelse return error.RemoteCwdMissing);
        // **원격 경로로 로컬 `.git`을 읽지 않는다.** 읽었다면 여기서 `local-branch-must-not-leak`이 나온다.
        // 이 단언은 회귀 포획이 아니라 **계약 고정**이다 — 지금은 두 겹이 막고 있어(collector가 저장소 판정용
        // 축을 쓰고, 파생 함수도 원격을 한 번 더 끊는다) 어느 한 겹을 빼도 통과한다. 픽스처를 실제 저장소로
        // 만든 이유는 두 겹이 **동시에** 사라지면 그때는 잡히게 하려는 것이다.
        try std.testing.expect(t.git_branch == null);
    }

    {
        const session = try initSmokeSessionSized(allocator);
        defer allocator.destroy(session);
        defer session.deinit();
        const term = pane_ops.activePane(session).activeTerm();
        // ssh 이전 로컬 셸이 보고한 cwd(authority 비어 있음 = 로컬) + maru ssh 목적지.
        try term.surface.core.write("\x1b]7;file:///Users/me/local-before-ssh\x07");
        try term.surface.core.write("\x1b]5379;ssh;build-box.example.com:22\x07");
        // 커널이 대신 답하는 것과 구별한다 — 폴 주기 안으로 맞춰 두고 빈 값을 심는다.
        term.rt.proc_cwd_polled_ns = std.Io.Clock.awake.now(session.io).nanoseconds;
        term.rt.proc_cwd_len = 0;

        const c = try session.collectSession(allocator, 42, .normal);
        defer c.deinit();
        const t = c.snapshot.surfaces[0].detail.terminal;
        try std.testing.expect(t.cwd == null);
        try std.testing.expect(t.git_branch == null);
    }
}

// ── 4) 다중 term(한 pane 가로 탭): 같은 좌표·구별 id, focused는 활성 term만 ──
test "collector: 다중 term(가로 탭) — 같은 tab/pane 좌표·구별 id, focused 하나" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionTwoTerms(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    try std.testing.expectEqual(@as(usize, 2), pane_ops.activePane(session).terms.items.len);
    const active_id = term_ops.activeSurface(session).id;

    const c = try session.collectSession(allocator, 7, .normal);
    defer c.deinit();

    try std.testing.expectEqual(@as(usize, 2), c.snapshot.surfaces.len);
    var focused_count: usize = 0;
    for (c.snapshot.surfaces) |dto| {
        try std.testing.expectEqual(@as(u64, 7), dto.window);
        try std.testing.expectEqual(@as(u32, 0), dto.tab);
        try std.testing.expectEqual(@as(u32, 0), dto.pane); // 가로 탭은 같은 pane 좌표
        if (dto.focused) focused_count += 1;
    }
    try std.testing.expectEqual(@as(usize, 1), focused_count);
    try std.testing.expect(c.snapshot.find(active_id).?.focused); // 활성 term이 그 하나
    try std.testing.expectEqual(@as(usize, 2), c.snapshot.windows[0].surface_ids.len);
}

// ── 5) split pane: pane 인덱스 0/1로 좌표 구분 ──
test "collector: split pane — pane 0/1 좌표, 같은 tab" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    try pane_ops.splitActivePane(session, .horizontal); // pane [0,1]
    try std.testing.expectEqual(@as(usize, 2), tab_ops.activeTab(session).panes.items.len);

    const c = try session.collectSession(allocator, 1, .normal);
    defer c.deinit();
    try std.testing.expectEqual(@as(usize, 2), c.snapshot.surfaces.len);
    var seen0 = false;
    var seen1 = false;
    for (c.snapshot.surfaces) |dto| {
        try std.testing.expectEqual(@as(u32, 0), dto.tab);
        if (dto.pane == 0) seen0 = true;
        if (dto.pane == 1) seen1 = true;
    }
    try std.testing.expect(seen0 and seen1);
}

