test "settings keybind recorder: 입력 섹션 행 녹음→캡처→rebind + 영속 예약, Esc 취소 (CS-4-3)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // 입력 섹션 선택.
    var scratch = std.heap.ArenaAllocator.init(allocator);
    defer scratch.deinit();
    const sections = try settings_ops.buildSectionList(session, scratch.allocator());
    var input_idx: usize = 0;
    for (sections, 0..) |s, i| if (s.section == .input) {
        input_idx = i;
    };
    session.chrome_host.settings.show();
    session.chrome_host.settings.section = input_idx;
    const cf = try settings_ops.currentSectionFields(session, scratch.allocator());
    try std.testing.expect(cf.keybind_entries.len == command_catalog.entries.len); // 쿼리 없으면 전부
    const ks = cf.keybindRowStart().?;

    // new_term은 command_catalog.entries[0] — 그 keybind 행 선택 → Enter(toggle) = 녹음 시작.
    session.chrome_host.settings.selected = ks; // entries[0]=new_term
    settings_ops.toggleSelectedSetting(session);
    try std.testing.expect(session.chrome_host.settings.recording);

    // Cmd+E 캡처 → new_term이 Cmd+E로 rebind + dirty 예약 + 녹음 종료.
    session.config_keybind_rebinds.clearRetainingCapacity();
    input_ops.captureKeybindRecording(session, .{ .key = .{ .char = 'E' }, .modifiers = .{ .command = true } });
    try std.testing.expect(!session.chrome_host.settings.recording);
    const resolver = session.loaded_config.keyBindingResolver();
    const chord = command_catalog.chordForAction(resolver, .new_term).?;
    try std.testing.expect((try config_mod.KeyChord.parse("Cmd+E")).eql(chord)); // resolver가 새 chord 반영
    try std.testing.expect(settings_ops.takeConfigDirty(session)); // write-back 예약됨
    var saw = false;
    for (session.config_keybind_rebinds.items) |rb| if (std.mem.eql(u8, rb.action, "new_term") and std.mem.eql(u8, rb.chord, "Cmd+E")) {
        saw = true;
    };
    try std.testing.expect(saw);

    // 평범한 Esc 캡처 → 취소(rebind 안 함, dirty 변화 없음).
    session.chrome_host.settings.selected = ks;
    session.chrome_host.settings.recording = true;
    const before = session.config_keybind_rebinds.items.len;
    input_ops.captureKeybindRecording(session, .{ .key = .escape, .modifiers = .{} });
    try std.testing.expect(!session.chrome_host.settings.recording);
    try std.testing.expectEqual(before, session.config_keybind_rebinds.items.len); // 변화 없음
}

test "settings global hotkey: .global_hotkey 섹션 3행 노출 + rebind가 global_bindings 교체·큐 적재, descriptorFor null 거부, Backspace 해제 (PR1)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // .global_hotkey 섹션은 schema 필드가 없어도 좌측 네비에 강제로 들어간다.
    var scratch = std.heap.ArenaAllocator.init(allocator);
    defer scratch.deinit();
    const sections = try settings_ops.buildSectionList(session, scratch.allocator());
    var gh_idx: ?usize = null;
    for (sections, 0..) |s, i| if (s.section == .global_hotkey) {
        gh_idx = i;
    };
    try std.testing.expect(gh_idx != null);

    session.chrome_host.settings.show();
    session.chrome_host.settings.section = gh_idx.?;
    const cf = try settings_ops.currentSectionFields(session, scratch.allocator());
    // 전역 행 3개(toggle_window/show_window/toggle_quick_terminal), schema·keybind 행 없음.
    try std.testing.expectEqual(@as(usize, 3), cf.global_entries.len);
    try std.testing.expectEqual(@as(usize, 0), cf.keybind_entries.len);
    const gs = cf.globalKeybindRowStart().?;
    try std.testing.expectEqual(gs, cf.total() - 3); // 맨 끝 3행

    // global_entries[0]=toggle_window 행 선택 → Enter(toggle) = 녹음 시작.
    session.chrome_host.settings.selected = gs;
    settings_ops.toggleSelectedSetting(session);
    try std.testing.expect(session.chrome_host.settings.recording);

    // Cmd+Alt+Space 캡처 → toggle_window가 그 chord로 rebind + global_bindings 교체 + 큐 적재 + 녹음 종료.
    input_ops.captureKeybindRecording(session, .{ .key = .{ .char = ' ' }, .modifiers = .{ .command = true, .option = true } });
    try std.testing.expect(!session.chrome_host.settings.recording);
    const chord = command_catalog.chordForGlobalAction(session.loaded_config.global_bindings, .toggle_window).?;
    try std.testing.expect((try config_mod.KeyChord.parse("Cmd+Alt+Space")).eql(chord)); // global_bindings 교체 반영
    try std.testing.expect(settings_ops.takeConfigDirty(session));
    var saw = false;
    for (session.config_global_rebinds.items) |rb| if (std.mem.eql(u8, rb.action, "toggle_window") and std.mem.eql(u8, rb.chord, "Cmd+Alt+Space")) {
        saw = true;
    };
    try std.testing.expect(saw); // write-back 큐 적재

    // descriptorFor가 null인 chord(Cmd+Plus — 가상 키코드 매핑 없음)는 거부(global_bindings·큐 불변).
    const before_len = session.loaded_config.global_bindings.len;
    const before_q = session.config_global_rebinds.items.len;
    session.chrome_host.settings.selected = gs;
    session.chrome_host.settings.recording = true;
    input_ops.captureKeybindRecording(session, .{ .key = .{ .char = '+' }, .modifiers = .{ .command = true } });
    try std.testing.expectEqual(before_len, session.loaded_config.global_bindings.len); // 거부 — 불변
    try std.testing.expectEqual(before_q, session.config_global_rebinds.items.len);
    // 거부돼도 toggle_window는 여전히 Cmd+Alt+Space.
    try std.testing.expect((try config_mod.KeyChord.parse("Cmd+Alt+Space")).eql(command_catalog.chordForGlobalAction(session.loaded_config.global_bindings, .toggle_window).?));

    // Backspace로 해제 → global_bindings에서 제거 + 줄 제거 예약 + 펜딩 rebind 취소.
    const cf2 = try settings_ops.currentSectionFields(session, scratch.allocator());
    session.chrome_host.settings.selected = cf2.globalKeybindRowStart().?; // toggle_window 행
    settings_ops.resetSelectedSettingRow(session);
    try std.testing.expect(command_catalog.chordForGlobalAction(session.loaded_config.global_bindings, .toggle_window) == null);
    var saw_removed = false;
    for (session.config_global_removed.items) |k| if (std.mem.eql(u8, k, "toggle_window")) {
        saw_removed = true;
    };
    try std.testing.expect(saw_removed);
    for (session.config_global_rebinds.items) |rb| try std.testing.expect(!std.mem.eql(u8, rb.action, "toggle_window")); // 펜딩 취소
}

test "global hotkey live re-register: rebuildGlobalHotkeys가 descriptor 재생성·매핑 불가 제외, rebind/unbind/reload/reset이 dirty, takeGlobalHotkeysDirty 1회성 (PR2)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // init은 dirty를 세우지 않는다(앱 시작 시 Swift가 어차피 한 번 register). 기본 config엔 전역 바인딩이 없어 목록도 빈다.
    try std.testing.expect(!session.global_hotkeys_dirty);
    try std.testing.expectEqual(@as(usize, 0), input_ops.globalHotkeys(session).len);

    // GUI 녹음으로 toggle_window를 Cmd+Alt+Space에 rebind → rebuildGlobalHotkeys가 descriptor 1개를 만들고 dirty=true.
    var scratch = std.heap.ArenaAllocator.init(allocator);
    defer scratch.deinit();
    const sections = try settings_ops.buildSectionList(session, scratch.allocator());
    var gh_idx: ?usize = null;
    for (sections, 0..) |s, i| if (s.section == .global_hotkey) {
        gh_idx = i;
    };
    session.chrome_host.settings.show();
    session.chrome_host.settings.section = gh_idx.?;
    const cf = try settings_ops.currentSectionFields(session, scratch.allocator());
    const gs = cf.globalKeybindRowStart().?;
    session.chrome_host.settings.selected = gs; // toggle_window 행
    settings_ops.toggleSelectedSetting(session); // 녹음 시작
    input_ops.captureKeybindRecording(session, .{ .key = .{ .char = ' ' }, .modifiers = .{ .command = true, .option = true } });
    try std.testing.expectEqual(@as(usize, 1), input_ops.globalHotkeys(session).len); // descriptor 재생성(매핑 가능 chord)
    try std.testing.expect(session.global_hotkeys_dirty); // rebind가 dirty 세움

    // takeGlobalHotkeysDirty는 1회성 — 첫 호출 true·리셋, 둘째 false.
    try std.testing.expect(session.takeGlobalHotkeysDirty());
    try std.testing.expect(!session.takeGlobalHotkeysDirty());
    try std.testing.expect(!session.global_hotkeys_dirty);

    // 매핑 불가 chord는 descriptor에서 제외된다 — global_bindings에 직접 등록 불가 chord를 넣고 rebuild하면 목록이 빈다.
    var list: std.ArrayList(config_mod.GlobalBinding) = .empty;
    const a = session.loaded_config.arena.allocator();
    try list.append(a, .{ .chord = try config_mod.KeyChord.parse("Cmd+Plus"), .action = .toggle_window }); // 가상 키코드 매핑 없음
    session.loaded_config.global_bindings = try list.toOwnedSlice(a);
    try input_ops.rebuildGlobalHotkeys(session);
    try std.testing.expectEqual(@as(usize, 0), input_ops.globalHotkeys(session).len); // descriptorFor null → 제외

    // GUI unbind(행 Backspace)도 dirty를 세운다 — 매핑 가능 chord로 다시 묶은 뒤 해제.
    session.chrome_host.settings.selected = gs;
    settings_ops.toggleSelectedSetting(session);
    input_ops.captureKeybindRecording(session, .{ .key = .{ .char = ' ' }, .modifiers = .{ .command = true, .option = true } });
    _ = session.takeGlobalHotkeysDirty(); // rebind dirty 소비
    const cf2 = try settings_ops.currentSectionFields(session, scratch.allocator());
    session.chrome_host.settings.selected = cf2.globalKeybindRowStart().?;
    settings_ops.resetSelectedSettingRow(session);
    try std.testing.expect(session.global_hotkeys_dirty); // unbind가 dirty 세움
    try std.testing.expectEqual(@as(usize, 0), input_ops.globalHotkeys(session).len); // 해제 후 빈 목록

    // resetAllSettings도 dirty를 세운다 — 기본값엔 전역 바인딩이 없어 목록을 비우고 라이브 재등록 신호.
    // (reloadConfig도 같은 wiring으로 dirty를 세우지만, 파일 I/O 의존이라 디스크 상태와 무관한 reset으로 검증한다.)
    // 안전 가드: resetAllSettings가 configPath()에 파일을 쓰므로 실 config 대신 tmp로 박는다(실 config 보호).
    var reset_tmp = std.testing.tmpDir(.{});
    defer reset_tmp.cleanup();
    var reset_path_buf: [4096]u8 = undefined;
    const reset_cfg_path = try std.fmt.bufPrint(&reset_path_buf, ".zig-cache/tmp/{s}/config", .{reset_tmp.sub_path});
    if (session.config_path_buffer) |b| allocator.free(b);
    session.config_path_buffer = try allocator.dupe(u8, reset_cfg_path);
    _ = session.takeGlobalHotkeysDirty();
    settings_ops.resetAllSettings(session);
    try std.testing.expect(session.global_hotkeys_dirty);
    try std.testing.expectEqual(@as(usize, 0), input_ops.globalHotkeys(session).len);
}

test "reloadConfig: 옛 arena 문자열을 가리키는 write-back 대기열을 비운다 — use-after-free 방지 (리뷰)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // 옛 loaded_config arena의 문자열을 가리키는 두 큐를 시드한다(이 리뷰가 다룬 UAF 부류):
    //  ① theme_preset_persist — persistThemePreset이 arena에 프리셋 이름을 dupe.
    //  ② config_keybind_unbind_removed — arena dupe한 chord 문자열.
    settings_ops.persistThemePreset(session, .gruvbox_dark);
    try std.testing.expect(session.theme_preset_persist != null);
    const a = session.loaded_config.arena.allocator();
    try session.config_keybind_unbind_removed.append(allocator, try a.dupe(u8, "cmd+shift+x"));
    try std.testing.expect(session.config_keybind_unbind_removed.items.len > 0);

    // reloadConfig는 옛 arena를 deinit한다 — clearConfigDirty로 위 큐를 비우지 않으면 두 슬라이스가 dangling이 되고
    // 다음 serializeConfig가 freed 메모리를 읽는다. 비우면 null·빈 목록이라 안전.
    settings_ops.reloadConfig(session);
    try std.testing.expect(session.theme_preset_persist == null);
    try std.testing.expectEqual(@as(usize, 0), session.config_keybind_unbind_removed.items.len);
    try std.testing.expectEqual(@as(usize, 0), session.config_dirty_keys.items.len);
    try std.testing.expectEqual(@as(usize, 0), session.config_removed_keys.items.len);
}

test "settings keybind unbind: keybind 행 Backspace → 사용자 바인딩 해제 + 줄 제거 예약, 펜딩 rebind 취소 (keybind unbind)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    var scratch = std.heap.ArenaAllocator.init(allocator);
    defer scratch.deinit();
    const sections = try settings_ops.buildSectionList(session, scratch.allocator());
    var input_idx: usize = 0;
    for (sections, 0..) |s, i| if (s.section == .input) {
        input_idx = i;
    };
    session.chrome_host.settings.show();
    session.chrome_host.settings.section = input_idx;
    const cf = try settings_ops.currentSectionFields(session, scratch.allocator());
    const ks = cf.keybindRowStart().?;
    session.chrome_host.settings.selected = ks; // entries[0]=new_term

    // 먼저 new_term을 Cmd+E로 rebind(사용자 바인딩 생성 + 펜딩).
    session.chrome_host.settings.recording = true;
    input_ops.captureKeybindRecording(session, .{ .key = .{ .char = 'E' }, .modifiers = .{ .command = true } });
    var has_user_bind = false;
    for (session.loaded_config.keybindings) |b| if (std.meta.activeTag(b.action) == .new_term) {
        has_user_bind = true;
    };
    try std.testing.expect(has_user_bind);

    // 이제 Backspace로 unbind → 사용자 바인딩 제거 + 빌트인 chord(Cmd+T) unbind 지시어 예약 + 줄 제거 + 펜딩 rebind 취소.
    settings_ops.resetSelectedSettingRow(session);
    for (session.loaded_config.keybindings) |b| try std.testing.expect(std.meta.activeTag(b.action) != .new_term); // 사용자 바인딩 사라짐
    // 완전 해제 — chordForAction(new_term)이 null(사용자 Cmd+E 제거 + 빌트인 Cmd+T unbinds로 죽음).
    try std.testing.expect(command_catalog.chordForAction(session.loaded_config.keyBindingResolver(), .new_term) == null);
    var saw_removed = false;
    for (session.config_keybind_removed.items) |k| if (std.mem.eql(u8, k, "new_term")) {
        saw_removed = true;
    };
    try std.testing.expect(saw_removed); // 사용자 줄 제거 예약
    var saw_unbind = false; // 빌트인 Cmd+T unbind 지시어 예약
    for (session.config_keybind_unbinds.items) |c| if (std.mem.eql(u8, c, "Cmd+T")) {
        saw_unbind = true;
    };
    try std.testing.expect(saw_unbind);
    for (session.config_keybind_rebinds.items) |rb| try std.testing.expect(!std.mem.eql(u8, rb.action, "new_term")); // 펜딩 rebind 취소
    try std.testing.expect(settings_ops.takeConfigDirty(session));

    // 이미 해제된 액션을 다시 unbind 시도 → notice 경로(무동작, keybindings 불변).
    const cf2 = try settings_ops.currentSectionFields(session, scratch.allocator());
    session.chrome_host.settings.selected = cf2.keybindRowStart().?;
    const len_before = session.loaded_config.keybindings.len;
    settings_ops.resetSelectedSettingRow(session);
    try std.testing.expectEqual(len_before, session.loaded_config.keybindings.len); // 불변(이미 미지정)
}

test "settings keybind 충돌: 이미 다른 액션에 묶인 chord로 rebind → 폼 상단 배너(세팅 유지, rebind는 진행)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    var scratch = std.heap.ArenaAllocator.init(allocator);
    defer scratch.deinit();
    const sections = try settings_ops.buildSectionList(session, scratch.allocator());
    var input_idx: usize = 0;
    for (sections, 0..) |s, i| if (s.section == .input) {
        input_idx = i;
    };
    session.chrome_host.settings.show();
    session.chrome_host.settings.section = input_idx;
    const cf = try settings_ops.currentSectionFields(session, scratch.allocator());
    session.chrome_host.settings.selected = cf.keybindRowStart().?; // entries[0]=new_term

    // new_term을 close_term의 빌트인 Cmd+W로 rebind → 충돌(다른 액션에 이미 묶임) → 폼 상단 배너 경고(세팅 유지).
    session.chrome_host.settings.recording = true;
    input_ops.captureKeybindRecording(session, .{ .key = .{ .char = 'W' }, .modifiers = .{ .command = true } });
    try std.testing.expect(session.chrome_host.settings.message().len > 0); // 배너 경고 표시(세팅 자체 그리드)
    try std.testing.expect(!session.chrome_host.notice.open); // notice 토스트가 아님(세팅을 안 닫는다)
    try std.testing.expect(session.chrome_host.settings.open); // 세팅 모달 유지(회귀 가드 — 예전엔 showNotice가 닫았다)
    // rebind는 진행됨 — new_term이 Cmd+W로(사용자 바인딩 우선, last-wins).
    const chord = command_catalog.chordForAction(session.loaded_config.keyBindingResolver(), .new_term).?;
    try std.testing.expect((try config_mod.KeyChord.parse("Cmd+W")).eql(chord));
}

test "settings 전역 단축키 등록 불가 키: 폼 상단 배너(세팅 유지) — 사용자 제보 '설정창이 꺼짐' 회귀 가드" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 6,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    var scratch = std.heap.ArenaAllocator.init(allocator);
    defer scratch.deinit();
    const sections = try settings_ops.buildSectionList(session, scratch.allocator());
    var global_idx: usize = 0;
    for (sections, 0..) |s, i| if (s.section == .global_hotkey) {
        global_idx = i;
    };
    session.chrome_host.settings.show();
    session.chrome_host.settings.section = global_idx;
    const cf = try settings_ops.currentSectionFields(session, scratch.allocator());
    session.chrome_host.settings.selected = cf.globalKeybindRowStart().?; // 첫 전역 액션 행

    // Cmd+Plus는 가상 키코드 매핑이 없어 전역 등록 불가(global_hotkey.descriptorFor=null) → 폼 상단 배너 거부(세팅 유지).
    session.chrome_host.settings.recording = true;
    input_ops.captureKeybindRecording(session, .{ .key = .{ .char = '+' }, .modifiers = .{ .command = true } });
    try std.testing.expect(session.chrome_host.settings.message().len > 0); // "등록할 수 없습니다" 배너
    try std.testing.expect(!session.chrome_host.notice.open); // notice 토스트가 아님
    try std.testing.expect(session.chrome_host.settings.open); // 세팅 모달 유지(핵심 — 예전엔 showNotice가 닫아 '설정창이 꺼짐')

    // 새 녹음 시도(등록 가능 키)는 배너를 정리하고 진행한다.
    session.chrome_host.settings.recording = true;
    input_ops.captureKeybindRecording(session, .{ .key = .{ .char = 'K' }, .modifiers = .{ .command = true, .option = true } });
    try std.testing.expectEqual(@as(usize, 0), session.chrome_host.settings.message().len); // 배너 정리됨
    try std.testing.expect(session.chrome_host.settings.open);
}

test "settings keybind unbind 다중-chord: 빌트인 chord가 2개인 액션도 모두 해제 (리뷰 #840)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    var scratch = std.heap.ArenaAllocator.init(allocator);
    defer scratch.deinit();
    const sections = try settings_ops.buildSectionList(session, scratch.allocator());
    var input_idx: usize = 0;
    for (sections, 0..) |s, i| if (s.section == .input) {
        input_idx = i;
    };
    session.chrome_host.settings.show();
    session.chrome_host.settings.section = input_idx;
    const cf = try settings_ops.currentSectionFields(session, scratch.allocator());
    const ks = cf.keybindRowStart().?;
    // next_tab은 빌트인 chord가 2개(⇧⌘] 와 ⇧⌘}) — 그 행을 찾아 Backspace.
    var nt_sel: ?usize = null;
    for (cf.keybind_entries, 0..) |e, i| if (std.mem.eql(u8, e.key, "next_tab")) {
        nt_sel = ks + i;
    };
    session.chrome_host.settings.selected = nt_sel.?;
    session.config_keybind_unbinds.clearRetainingCapacity();
    settings_ops.resetSelectedSettingRow(session);
    // 두 빌트인 chord가 모두 죽어 next_tab이 **완전히** 미지정(하나만 죽이는 회귀면 첫 chord가 남아 non-null).
    try std.testing.expect(command_catalog.chordForAction(session.loaded_config.keyBindingResolver(), .next_tab) == null);
    try std.testing.expect(session.config_keybind_unbinds.items.len >= 2); // chord 2개 다 unbind 지시어 예약
}

test "settings keybind 완전 교체: rebind하면 그 액션 빌트인 chord가 죽는다 — 옛 키+새 키가 아니라 새 키만 (키바인드 완전 교체)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // next_tab 엔트리를 새 chord(Cmd+E — next_tab 빌트인 ⇧⌘]/⇧⌘}와 다른 자유 chord)로 rebind.
    const new_chord = try config_mod.KeyChord.parse("Cmd+E");
    var entry: ?command_catalog.Entry = null;
    for (command_catalog.entries) |e| if (std.mem.eql(u8, e.key, "next_tab")) {
        entry = e;
    };
    try std.testing.expect(entry != null);
    session.config_keybind_unbinds.clearRetainingCapacity();
    input_ops.rebindActionEntry(session, entry.?, new_chord);

    const resolver = session.loaded_config.keyBindingResolver();
    // (1) next_tab의 effective chord = 새 Cmd+E(사용자 바인딩).
    try std.testing.expect(command_catalog.chordForAction(resolver, .next_tab).?.eql(new_chord));
    // (2) **핵심**: next_tab의 빌트인 chord(새 chord 아님)는 전부 unbinds에 들어가 죽었다 — 옛 키가 더는 next_tab을 안 함.
    //     (add-only 회귀면 빌트인이 unbinds에 없어 옛 키가 살아 있다.)
    var had_builtin = false;
    for (config_mod.keybinding.default_app_bindings) |db| if (std.meta.eql(db.action, .next_tab) and !db.chord.eql(new_chord)) {
        had_builtin = true;
        var found = false;
        for (session.loaded_config.unbinds) |u| if (u.eql(db.chord)) {
            found = true;
        };
        try std.testing.expect(found); // 빌트인 chord가 unbind됨(라이브)
    };
    try std.testing.expect(had_builtin); // next_tab엔 죽일 빌트인이 있었다(테스트 전제)
    // (3) 영속: 빌트인 unbind 지시어가 예약됐다(파일에 keybind = chord = unbind).
    try std.testing.expect(session.config_keybind_unbinds.items.len >= 1);
}

test "settings keybind stale unbind 정리: unbind한 chord를 다시 바인딩하면 unbinds에서 빠지고 옛 줄 제거 예약 (stale unbind)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // (1) next_tab을 unbind → 빌트인 chord(들)가 loaded_config.unbinds + 펜딩 unbind-append에 들어간다.
    var nt: ?command_catalog.Entry = null;
    for (command_catalog.entries) |e| if (std.mem.eql(u8, e.key, "next_tab")) {
        nt = e;
    };
    settings_ops.unbindActionEntry(session, nt.?);
    var target: ?config_mod.KeyChord = null;
    for (config_mod.keybinding.default_app_bindings) |db| if (std.meta.eql(db.action, .next_tab)) {
        target = db.chord;
    };
    try std.testing.expect(target != null);
    var was_unbound = false;
    for (session.loaded_config.unbinds) |u| if (u.eql(target.?)) {
        was_unbound = true;
    };
    try std.testing.expect(was_unbound); // 그 chord가 지금 죽어 있다

    // (2) 다른 액션(previous_tab)을 그 죽은 chord로 rebind → stale unbind 정리.
    var pt: ?command_catalog.Entry = null;
    for (command_catalog.entries) |e| if (std.mem.eql(u8, e.key, "previous_tab")) {
        pt = e;
    };
    session.config_keybind_unbind_removed.clearRetainingCapacity();
    input_ops.rebindActionEntry(session, pt.?, target.?);

    // (3) 그 chord가 loaded_config.unbinds에서 빠졌다(부활) + previous_tab의 effective chord가 됐다.
    var still = false;
    for (session.loaded_config.unbinds) |u| if (u.eql(target.?)) {
        still = true;
    };
    try std.testing.expect(!still);
    try std.testing.expect(command_catalog.chordForAction(session.loaded_config.keyBindingResolver(), .previous_tab).?.eql(target.?));
    // (4) 옛 `keybind = chord = unbind` 줄 제거가 예약됐다(파일 위생).
    var chord_buf: [command_catalog.max_chord_display_len]u8 = undefined;
    const cs = target.?.toConfigString(&chord_buf);
    var reserved = false;
    for (session.config_keybind_unbind_removed.items) |c| if (std.mem.eql(u8, c, cs)) {
        reserved = true;
    };
    try std.testing.expect(reserved);
}

// 도크를 열면 아카이브 스캔이 요청되는가. 예전에는 `setDockView` 하나가 "전환"과 "진입"을 겸해서,
// `dock.view`가 이미 `agent_sessions`인 채로 도크를 열면 맨 앞 조기 반환(`if (self.dock.view == view) return`)에
// 걸려 스캔 요청이 아예 나가지 않았다 — 목록도 스피너도 없이 비었고 새로 고침을 눌러야 나타났다.
// 도크를 떠날 때 진행 중 스캔이 취소되므로(agent_dock.cancelAgentSessionArchive) 닫았다 여는 흐름에서 특히 잘 드러났다.
//
// 실제 스캔은 사용자 홈 전체를 읽는 워커라 단위 테스트에서 돌릴 수 없다. 그래서 진입 판정을 순수 함수로
// 분리해 그 규칙을 고정하고, 호출 경로는 `enterDockView` 하나로 모았다.
test "도크 진입 판정: 보이는 도크의 agent_sessions에서만 아카이브 스캔을 요청한다" {
    // 보이고 + agent_sessions → 요청.
    try std.testing.expect(agent_dock.shouldRefreshArchiveOnPresent(true, .agent_sessions));
    // 같은 뷰로 다시 들어와도 판정은 같다. "전환이 없었다"는 이유로 스캔을 건너뛰면 안 된다 — 이 회귀가
    // 첫 진입에 목록이 비어 있던 원인이다.
    try std.testing.expect(agent_dock.shouldRefreshArchiveOnPresent(true, .agent_sessions));
    // 도크가 안 보이면 요청하지 않는다. setDockView는 workspace restore처럼 도크가 닫힌 상태에서도
    // 불리므로, 이 가드가 없으면 보이지도 않는 도크가 사용자 이력 전체를 스캔한다.
    try std.testing.expect(!agent_dock.shouldRefreshArchiveOnPresent(false, .agent_sessions));
    // 다른 뷰는 아카이브와 무관하다.
    try std.testing.expect(!agent_dock.shouldRefreshArchiveOnPresent(true, .explorer));
    try std.testing.expect(!agent_dock.shouldRefreshArchiveOnPresent(true, .source_control));
    try std.testing.expect(!agent_dock.shouldRefreshArchiveOnPresent(false, .explorer));
}

test "settings 검색 필터: 쿼리로 keybind/schema 행 필터 + 필터 후 인덱스가 올바른 액션에 매핑 (CS-4-4 검색)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    var scratch = std.heap.ArenaAllocator.init(allocator);
    defer scratch.deinit();
    const sections = try settings_ops.buildSectionList(session, scratch.allocator());
    var input_idx: usize = 0;
    for (sections, 0..) |s, i| if (s.section == .input) {
        input_idx = i;
    };
    session.chrome_host.settings.show();
    session.chrome_host.settings.section = input_idx;

    // **교차 섹션** 검색 "split"(현재 섹션=input이지만 쿼리가 있으면 전 섹션) → workspace.split-inherit-cwd(bool, 키에
    // "split") + Split Right/Down keybind 2개. enum은 "split" 미매칭(0).
    // FP16: 도크 group split 액션 2개가 사라져 keybind 매칭은 pane split 2개뿐이다.
    session.chrome_host.settings.startSearch();
    for ("split") |c| session.chrome_host.settings.appendSearchCp(c);
    const cf = try settings_ops.currentSectionFields(session, scratch.allocator());
    try std.testing.expectEqual(@as(usize, 0), cf.enums.len); // "split" 미매칭
    try std.testing.expect(cf.bools.len >= 1); // 교차 섹션: workspace.split-inherit-cwd(다른 섹션) 매칭
    try std.testing.expectEqual(@as(usize, 2), cf.keybind_entries.len); // pane split 2개
    for (cf.keybind_entries) |e| try std.testing.expect(std.ascii.indexOfIgnoreCase(e.title, "split") != null);

    // keybindRowStart는 앞선 schema 행(여기선 split bool 등) 다음. 그 행 녹음→캡처가 **필터된 첫 keybind 엔트리**(Split Right)를
    // rebind해야 한다(교차 섹션 필터 후에도 인덱스 정합 — keybindRowStart가 정확히 keybind_entries[0]을 가리킨다).
    const ks = cf.keybindRowStart().?;
    session.chrome_host.settings.selected = ks;
    session.chrome_host.settings.recording = true;
    session.config_keybind_rebinds.clearRetainingCapacity();
    input_ops.captureKeybindRecording(session, .{ .key = .{ .char = 'J' }, .modifiers = .{ .command = true } });
    try std.testing.expectEqual(@as(usize, 1), session.config_keybind_rebinds.items.len);
    // 재바인딩된 action 키 = 필터된 목록의 첫 엔트리 키(엉뚱한 액션이 아니라).
    try std.testing.expectEqualStrings(cf.keybind_entries[0].key, session.config_keybind_rebinds.items[0].action);

    // 빈 쿼리(검색 종료)면 현재 섹션(input)만 복귀 — keybind 전부 + input enum.
    session.chrome_host.settings.endSearch();
    const cf2 = try settings_ops.currentSectionFields(session, scratch.allocator());
    try std.testing.expectEqual(command_catalog.entries.len, cf2.keybind_entries.len);
    try std.testing.expect(cf2.enums.len > 0); // input dropdown 복귀
    try std.testing.expectEqual(@as(usize, 6), cf2.bools.len); // input 섹션 bool = mouse-hide-while-typing(F1-6) + option-as-meta(F2-2) + keyhint.enabled(KH-3) + paste-protection + bracketed-paste-is-safe + selection-clear-on-typing 6개(split bool은 workspace라 검색 끝나 사라짐)
}

test "mouse-hide-while-typing: IME 확정(글자) 입력 시 takeMouseHide 신호(1회성), 한글·meta chord·config off 구분 (F1-6)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.loaded_config.config.input.mouse_hide_while_typing = true;

    // 평범한 글자 'a' 입력은 macOS에서 IME(NSTextInputClient) 확정으로 routeCommittedText를 탄다(handleKeyEvent 우회).
    // 터미널 focus라 숨김 신호. takeMouseHide는 1회성(다음 호출 false).
    input_ops.routeCommittedText(session, "a");
    try std.testing.expect(session.takeMouseHide());
    try std.testing.expect(!session.takeMouseHide()); // drain됨

    // 한글/CJK도 같은 IME 확정 경로 → 숨김(옛 구현은 handleKeyEvent .char만 봐서 CJK를 놓쳤다 — code-review max).
    input_ops.routeCommittedText(session, "한");
    try std.testing.expect(session.takeMouseHide());

    // Option+글자 같은 meta chord는 handleKeyEvent .terminal_input로 오지만 타이핑이 아닌 nav chord라 안 숨김
    // (mouse_hide 판정을 그 경로에서 뺐다 — 옛 구현은 여기서 숨겨 의도가 역전됐었다).
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'b' }, .modifiers = .{ .option = true } });
    try std.testing.expect(!session.takeMouseHide());

    // config off면 글자여도 안 숨김(기본 false = 현행).
    session.loaded_config.config.input.mouse_hide_while_typing = false;
    input_ops.routeCommittedText(session, "c");
    try std.testing.expect(!session.takeMouseHide());
}

test "settings env 삭제: Backspace로 env.<KEY> 행 삭제 → config.env에서 제거 + 줄 삭제 예약 (env delete)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    var scratch = std.heap.ArenaAllocator.init(allocator);
    defer scratch.deinit();
    const sections = try settings_ops.buildSectionList(session, scratch.allocator());
    var term_idx: usize = 0;
    for (sections, 0..) |s, i| if (s.section == .terminal) {
        term_idx = i;
    };
    session.chrome_host.settings.show();
    session.chrome_host.settings.section = term_idx;

    // env 두 개 추가(setEnvVar 경유).
    session.setEnvVar("FOO", "bar");
    session.setEnvVar("BAZ", "qux");
    try std.testing.expectEqual(@as(usize, 2), session.loaded_config.config.env.len);

    // env.FOO 행을 selected로(text 구간에서 key=="env.FOO" 찾기).
    const cf = try settings_ops.currentSectionFields(session, scratch.allocator());
    const after_enums = cf.bools.len + cf.nums.len + cf.enums.len;
    var foo_sel: ?usize = null;
    for (cf.texts, 0..) |t, i| if (std.mem.eql(u8, t.key, "env.FOO")) {
        foo_sel = after_enums + i;
    };
    session.chrome_host.settings.selected = foo_sel.?;

    // Backspace 삭제 → FOO 제거, BAZ 유지 + dirty 제거 키.
    session.config_removed_keys.clearRetainingCapacity();
    settings_ops.resetSelectedSettingRow(session);
    try std.testing.expectEqual(@as(usize, 1), session.loaded_config.config.env.len);
    try std.testing.expectEqualStrings("BAZ=qux", session.loaded_config.config.env[0]);
    try std.testing.expect(settings_ops.takeConfigDirty(session));
    var saw = false;
    for (session.config_removed_keys.items) |k| if (std.mem.eql(u8, k, "env.FOO")) {
        saw = true;
    };
    try std.testing.expect(saw);

    // 추가 sentinel 행("env.")이나 shell.args 행에서 삭제 시도 → 무동작(env 변화 없음).
    const cf2 = try settings_ops.currentSectionFields(session, scratch.allocator());
    const after_enums2 = cf2.bools.len + cf2.nums.len + cf2.enums.len;
    var sa_sel: ?usize = null;
    for (cf2.texts, 0..) |t, i| if (std.mem.eql(u8, t.key, "shell.args")) {
        sa_sel = after_enums2 + i;
    };
    session.chrome_host.settings.selected = sa_sel.?;
    settings_ops.resetSelectedSettingRow(session);
    try std.testing.expectEqual(@as(usize, 1), session.loaded_config.config.env.len); // 그대로
}

test "settings env/shell.args: terminal 섹션 synthetic text 행 — shell.args 분리·env upsert·추가 행 파싱 (CS-4-5)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // terminal 섹션 선택.
    var scratch = std.heap.ArenaAllocator.init(allocator);
    defer scratch.deinit();
    const sections = try settings_ops.buildSectionList(session, scratch.allocator());
    var term_idx: usize = 0;
    for (sections, 0..) |s, i| if (s.section == .terminal) {
        term_idx = i;
    };
    session.chrome_host.settings.show();
    session.chrome_host.settings.section = term_idx;

    // text 행 key로 selected 인덱스를 찾는 헬퍼(인라인): selected = bools+nums+enums + (cf.texts 안 인덱스).
    const selForTextKey = struct {
        fn f(s: *AppSession, a: std.mem.Allocator, key: []const u8) ?usize {
            const c = settings_ops.currentSectionFields(s, a) catch return null;
            const base = c.bools.len + c.nums.len + c.enums.len;
            for (c.texts, 0..) |t, i| if (std.mem.eql(u8, t.key, key)) return base + i;
            return null;
        }
    }.f;

    // shell.args 행 편집 "-i -l" → 공백 분리 토큰 2개 + dirty "shell.args".
    session.chrome_host.settings.selected = selForTextKey(session, scratch.allocator(), "shell.args").?;
    session.chrome_host.settings.enterEdit("-i -l");
    session.config_dirty_keys.clearRetainingCapacity();
    settings_ops.commitSelectedText(session);
    try std.testing.expectEqual(@as(usize, 2), session.loaded_config.config.shell.args.len);
    try std.testing.expectEqualStrings("-i", session.loaded_config.config.shell.args[0]);
    try std.testing.expectEqualStrings("-l", session.loaded_config.config.shell.args[1]);
    var saw_sa = false;
    for (session.config_dirty_keys.items) |k| if (std.mem.eql(u8, k, "shell.args")) {
        saw_sa = true;
    };
    try std.testing.expect(saw_sa);

    // env 추가 행("env." sentinel) 편집 "FOO=bar" → config.env에 "FOO=bar" + dirty "env.FOO".
    session.chrome_host.settings.selected = selForTextKey(session, scratch.allocator(), "env.").?;
    session.chrome_host.settings.enterEdit("FOO=bar");
    session.config_dirty_keys.clearRetainingCapacity();
    settings_ops.commitSelectedText(session);
    try std.testing.expectEqual(@as(usize, 1), session.loaded_config.config.env.len);
    try std.testing.expectEqualStrings("FOO=bar", session.loaded_config.config.env[0]);
    var saw_foo = false;
    for (session.config_dirty_keys.items) |k| if (std.mem.eql(u8, k, "env.FOO")) {
        saw_foo = true;
    };
    try std.testing.expect(saw_foo);

    // 이제 "env.FOO" 행이 생겼다 — 값만 "baz"로 편집 → upsert(교체, 추가 아님).
    session.chrome_host.settings.selected = selForTextKey(session, scratch.allocator(), "env.FOO").?;
    session.chrome_host.settings.enterEdit("baz");
    settings_ops.commitSelectedText(session);
    try std.testing.expectEqual(@as(usize, 1), session.loaded_config.config.env.len); // 교체 — 개수 그대로
    try std.testing.expectEqualStrings("FOO=baz", session.loaded_config.config.env[0]);

    // 추가 행에 '=' 없는 입력 → 무시(env 변화 없음).
    session.chrome_host.settings.selected = selForTextKey(session, scratch.allocator(), "env.").?;
    session.chrome_host.settings.enterEdit("INVALID");
    settings_ops.commitSelectedText(session);
    try std.testing.expectEqual(@as(usize, 1), session.loaded_config.config.env.len); // 그대로
}

test "detectThemePreset / applyThemePreset / resetAllSettings: 테마 프리셋·통합 리셋" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // detectThemePreset: 프리셋 색 세트는 그 프리셋으로 식별, 임의 색은 null.
    session.loaded_config.config.theme = config_mod.theme.presetColors(.dracula);
    try std.testing.expectEqual(config_mod.theme.ThemePreset.dracula, AppSession.detectThemePreset(session.loaded_config.config.theme).?);
    session.loaded_config.config.theme.background = "#123456";
    try std.testing.expect(AppSession.detectThemePreset(session.loaded_config.config.theme) == null); // 사용자 지정

    // applyThemePreset: dir=+1 적용 → config.theme가 그 프리셋 색 + **theme.preset 영속 예약**(개별 색·palette는 제거
    // 예약 — 4색만 쓰던 옛 한계 해소, 팔레트 영속 리뷰). theme.preset 한 줄이 로더에서 16색 팔레트까지 통째로 펼쳐진다.
    session.loaded_config.config.theme = config_mod.theme.presetColors(.maru);
    settings_ops.applyThemePreset(session, 1); // maru → 다음(ghostty)
    try std.testing.expectEqualStrings(config_mod.theme.presetColors(.ghostty).background, session.loaded_config.config.theme.background);
    try std.testing.expectEqual(config_mod.theme.ThemePreset.ghostty, AppSession.detectThemePreset(session.loaded_config.config.theme).?);
    try std.testing.expect(session.theme_preset_persist != null);
    try std.testing.expectEqualStrings("ghostty", session.theme_preset_persist.?); // dashed 이름(파일에 theme.preset = ghostty)
    var saw_bg_removed = false;
    for (session.config_removed_keys.items) |k| if (std.mem.eql(u8, k, "theme.background")) {
        saw_bg_removed = true; // 개별 색은 제거 예약(theme.preset이 base를 깔므로 충돌 방지)
    };
    try std.testing.expect(saw_bg_removed);

    // resetAllSettings: 모든 config를 기본값으로 + **config 파일을 기본 상태로 덮어쓰기**(삭제 아님 — 파일·경로 보존) +
    // dirty 비움(부분 write-back 안 함). 안전: 실제 사용자 config가 아니라 tmp 파일을 덮어쓰도록 config_path_buffer를 박는다.
    const io = std.testing.io;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    try tmp.dir.writeFile(io, .{ .sub_path = "config", .data = "font.size = 99\n" });
    var path_buf: [4096]u8 = undefined;
    const cfg_path = try std.fmt.bufPrint(&path_buf, ".zig-cache/tmp/{s}/config", .{tmp.sub_path});
    if (session.config_path_buffer) |b| allocator.free(b);
    session.config_path_buffer = try allocator.dupe(u8, cfg_path); // 세션 소유 — deinit이 해제

    session.config_dirty_keys.clearRetainingCapacity();
    session.loaded_config.config.font.size = 99;
    session.loaded_config.config.cursor.blink = !(config_mod.Config{}).cursor.blink;
    // 리셋 직전 예약된 변경이 config_dirty_keys 외 컬렉션에 있어도 reset이 전부 폐기하는지(리뷰 #844-followup) —
    // 안 비우면 다음 tick serializeConfig가 takeConfigDirty()=true로 방금 리셋한 파일에 되살린다. 대표로 두 컬렉션에 더미.
    try session.config_removed_keys.append(allocator, "env.STALE");
    try session.config_keybind_unbinds.append(allocator, "cmd+k");
    settings_ops.resetAllSettings(session);
    try std.testing.expectEqual((config_mod.Config{}).font.size, session.loaded_config.config.font.size); // 라이브 기본값
    try std.testing.expectEqual((config_mod.Config{}).cursor.blink, session.loaded_config.config.cursor.blink);
    try std.testing.expect(!settings_ops.takeConfigDirty(session)); // 5개 dirty 컬렉션 전부 비워짐(부분 write-back 예약 없음)
    // config 파일이 기본 상태로 덮어써졌는지(삭제 아님 — 파일 존재 + 안내 주석, 옛 override 사라짐).
    const after = try tmp.dir.readFileAlloc(io, "config", allocator, .limited(4096));
    defer allocator.free(after);
    try std.testing.expect(std.mem.indexOf(u8, after, "Reset to Defaults") != null); // 안내 주석 헤더
    try std.testing.expect(std.mem.indexOf(u8, after, "font.size = 99") == null); // 옛 override 사라짐

    // make_path + replace 계약(리뷰 #844-followup): config 경로의 부모 디렉터리가 없어도(신규 사용자 ~/.config[/maru] 부재)
    // reset이 부모를 재귀 생성하고 헤더를 쓴다. 존재하지 않는 nested/dir 하위로 경로를 바꿔 검증.
    const nested = try std.fmt.bufPrint(&path_buf, ".zig-cache/tmp/{s}/nested/dir/config", .{tmp.sub_path});
    allocator.free(session.config_path_buffer.?);
    session.config_path_buffer = try allocator.dupe(u8, nested);
    settings_ops.resetAllSettings(session);
    const nested_after = tmp.dir.readFileAlloc(io, "nested/dir/config", allocator, .limited(4096)) catch null;
    defer if (nested_after) |na| allocator.free(na);
    try std.testing.expect(nested_after != null); // make_path가 nested/dir를 생성하고 헤더를 씀
    try std.testing.expect(std.mem.indexOf(u8, nested_after.?, "Reset to Defaults") != null);
}

// resetAllSettings의 **초기화 예외 하나**를 못박는다: `session.keep-alive-after-quit`은 취향 설정이 아니라 살아 있는
// PTY의 소유권 모드다(true=host 소유라 Quit은 detach, false=앱 소유라 Quit이 terminate — persistent-session-host.md
// 토글 의미론 표). 리셋이 이 값을 기본값으로 되돌리면 그 자리에서 live 정책이 뒤집혀 **다음 평범한 `Quit Maru`가
// 사용자가 켜 둔 host-backed runtime을 전부 종료**한다. 실측 사고에서 이 경로로 runtime 12개가 소멸하고 workspace의
// `host_id:runtime_id` 12개가 dangling이 됐다. 터미널에서 중요한 이유: 세션 유지는 사용자가 며칠 띄워 둔 셸·빌드·SSH의
// 생사를 결정하므로, 파괴는 `Quit and End All Sessions` 같은 명시적 경로만 해야 한다. 값·live 정책·config 파일 override
// 셋이 함께 보존돼야 재실행까지 유지되므로(하나만 빠지면 파일과 정책이 갈려 다음 실행이 조용히 in-process로 떨어진다)
// 셋 다 검증한다.
test "resetAllSettings: session.keep-alive-after-quit은 초기화 예외로 보존한다(값·live 정책·파일 override)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // 안전 가드: resetAllSettings가 configPath()에 파일을 쓰므로 실 config(~/.config/maru/config) 대신 tmp로 박는다.
    const io = std.testing.io;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var path_buf: [4096]u8 = undefined;
    const cfg_path = try std.fmt.bufPrint(&path_buf, ".zig-cache/tmp/{s}/config", .{tmp.sub_path});
    if (session.config_path_buffer) |b| allocator.free(b);
    session.config_path_buffer = try allocator.dupe(u8, cfg_path); // 세션 소유 — deinit이 해제

    const default_keep_alive = (config_mod.Config{}).session.keep_alive_after_quit;

    // absent profile에서 전체 Reset은 미래 기본값 전환을 거부한 것으로 오인될 explicit false를 만들지 않는다.
    settings_ops.resetAllSettings(session);
    const absent_after = try tmp.dir.readFileAlloc(io, "config", allocator, .limited(4096));
    defer allocator.free(absent_after);
    try std.testing.expect(std.mem.indexOf(u8, absent_after, "session.keep-alive-after-quit") == null);
    try std.testing.expectEqual(config_mod.SessionKeepAliveProvenance.absent, session.loaded_config.session_keep_alive_provenance);

    // 기본값 뒤집기로 표현한다(리터럴 false 금지) — 문서가 기능 완성 뒤 기본값을 true로 전환한다고 예고했고,
    // 그때도 "사용자가 명시적으로 정한 값"을 리셋이 되돌리지 않아야 이 테스트가 계속 옳다.
    session.loaded_config.config.session.keep_alive_after_quit = !default_keep_alive;
    setAppKeepAlivePolicy(!default_keep_alive);
    session.loaded_config.config.font.size = 99; // 함께 갈려야 하는 대조군(보통 설정은 초기화된다)

    settings_ops.resetAllSettings(session);

    // 1) 값 보존 — 대조군은 기본값으로 갔는데 이 키만 사용자 값으로 남는다.
    try std.testing.expectEqual(!default_keep_alive, session.loaded_config.config.session.keep_alive_after_quit);
    try std.testing.expectEqual((config_mod.Config{}).font.size, session.loaded_config.config.font.size);
    // 2) live 정책 보존 — 이 래치가 뒤집히는 것이 사고의 직접 원인이었다(다음 Quit이 detach 대신 terminate).
    try std.testing.expectEqual(!default_keep_alive, app_keep_alive_after_quit);
    // 3) 파일 override 보존 — 리셋이 덮어쓰는 파일에 같은 값이 남아야 재실행 뒤에도 정책이 이어진다.
    const after = try tmp.dir.readFileAlloc(io, "config", allocator, .limited(4096));
    defer allocator.free(after);
    try std.testing.expect(std.mem.indexOf(u8, after, "Reset to Defaults") != null); // 안내 주석 헤더는 그대로
    try std.testing.expect(std.mem.indexOf(u8, after, "session.keep-alive-after-quit") != null);
    try std.testing.expect(std.mem.indexOf(u8, after, "font.size = 99") == null); // 다른 override는 사라진다

    // G2부터는 사용자가 명시적으로 기본값과 같은 값을 골라도 intent다. 값 비교로 줄을 빼면 release B→A rollback에서
    // explicit false/true가 absent로 무너진다. 토글 setter가 provenance를 explicit으로 만든 뒤 Reset은 반드시 emit한다.
    session.loaded_config.config.session.keep_alive_after_quit = default_keep_alive;
    setAppKeepAlivePolicy(default_keep_alive);
    settings_ops.resetAllSettings(session);
    const plain = try tmp.dir.readFileAlloc(io, "config", allocator, .limited(4096));
    defer allocator.free(plain);
    try std.testing.expect(std.mem.indexOf(u8, plain, "session.keep-alive-after-quit") != null);
}

test "G2 keep-alive row Reset과 Backspace는 live snapshot과 write-back queue를 바꾸지 않는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    settings_ops.toggleSettings(session);
    var scratch = std.heap.ArenaAllocator.init(allocator);
    defer scratch.deinit();
    const sections = try settings_ops.buildSectionList(session, scratch.allocator());
    for (sections, 0..) |section, i| if (section.section == .workspace) {
        session.chrome_host.settings.section = i;
        break;
    };
    const fields = try settings_ops.currentSectionFields(session, scratch.allocator());
    var keep_index: ?usize = null;
    for (fields.bools, 0..) |field, i| if (std.mem.eql(u8, field.key, "session.keep-alive-after-quit")) {
        keep_index = i;
        break;
    };
    session.chrome_host.settings.selected = keep_index orelse return error.TestUnexpectedResult;

    const explicit_value = (config_mod.Config{}).session.keep_alive_after_quit;
    session.loaded_config.config.session.keep_alive_after_quit = explicit_value;
    setAppKeepAlivePolicy(explicit_value);
    const before = appKeepAliveSnapshot();
    const dirty_before = session.config_dirty_keys.items.len;
    const removed_before = session.config_removed_keys.items.len;

    settings_ops.resetSelectedSettingRow(session);
    try std.testing.expectEqual(before, appKeepAliveSnapshot());
    try std.testing.expectEqual(explicit_value, session.loaded_config.config.session.keep_alive_after_quit);
    try std.testing.expectEqual(dirty_before, session.config_dirty_keys.items.len);
    try std.testing.expectEqual(removed_before, session.config_removed_keys.items.len);

    settings_ops.resetSelectedSettingRow(session); // Backspace와 같은 dispatch를 반복해도 exact no-op이다.
    try std.testing.expectEqual(before, appKeepAliveSnapshot());
    try std.testing.expectEqual(dirty_before, session.config_dirty_keys.items.len);
    try std.testing.expectEqual(removed_before, session.config_removed_keys.items.len);
}

test "G2 stale Window 전체 Reset은 app-global keep-alive snapshot과 같은 override를 쓴다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    const io = std.testing.io;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var path_buf: [4096]u8 = undefined;
    const cfg_path = try std.fmt.bufPrint(&path_buf, ".zig-cache/tmp/{s}/config", .{tmp.sub_path});
    if (session.config_path_buffer) |b| allocator.free(b);
    session.config_path_buffer = try allocator.dupe(u8, cfg_path);

    const stale = session.loaded_config.config.session.keep_alive_after_quit;
    const current = !stale;
    setAppKeepAlivePolicy(current); // 다른 Window가 바꿨고 이 Window mirror는 아직 stale인 상황.
    try std.testing.expectEqual(stale, session.loaded_config.config.session.keep_alive_after_quit);

    settings_ops.resetAllSettings(session);
    try std.testing.expectEqual(current, appKeepAliveSnapshot().value);
    try std.testing.expectEqual(current, session.loaded_config.config.session.keep_alive_after_quit);
    const after = try tmp.dir.readFileAlloc(io, "config", allocator, .limited(4096));
    defer allocator.free(after);
    const expected = if (current)
        "session.keep-alive-after-quit = true"
    else
        "session.keep-alive-after-quit = false";
    try std.testing.expect(std.mem.indexOf(u8, after, expected) != null);
}

test "G2 전체 Reset atomic replace 실패는 keep-alive provenance와 기존 대상에 mutation 0이다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    const io = std.testing.io;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    try tmp.dir.createDir(io, "config-target", .default_dir);
    try tmp.dir.writeFile(io, .{ .sub_path = "config-target/sentinel", .data = "unchanged\n" });
    var path_buf: [4096]u8 = undefined;
    const cfg_path = try std.fmt.bufPrint(&path_buf, ".zig-cache/tmp/{s}/config-target", .{tmp.sub_path});
    if (session.config_path_buffer) |b| allocator.free(b);
    session.config_path_buffer = try allocator.dupe(u8, cfg_path);

    const before: config_mod.SessionKeepAliveSnapshot = .{
        .value = true,
        .provenance = .explicit_invalid,
        .file_provenance = .readable,
    };
    try app_keep_alive_bootstrap_owner.replaceFromReload(before);
    app_keep_alive_after_quit = before.value;
    try std.testing.expectEqual(before, appKeepAliveSnapshot());

    settings_ops.resetAllSettings(session);
    try std.testing.expectEqual(before, appKeepAliveSnapshot());
    const sentinel = try tmp.dir.readFileAlloc(io, "config-target/sentinel", allocator, .limited(64));
    defer allocator.free(sentinel);
    try std.testing.expectEqualStrings("unchanged\n", sentinel);
}

test "테마 프리셋 잠금: 사용자 지정 순환 + 프리셋 활성 시 색·팔레트 잠금 + 프리셋 행 최상단" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    const Preset = config_mod.theme.ThemePreset;
    const n = @typeInfo(Preset).@"enum".fields.len;

    // 프리셋 색 + 사용자 미전환 → 활성(잠금).
    session.loaded_config.config.theme = config_mod.theme.presetColors(.maru);
    session.theme_user_custom = false;
    try std.testing.expect(session.themePresetActive());

    // 마지막 프리셋에서 +1 → "사용자 지정": 색 보존 + theme_user_custom=true + 잠금 해제(색을 안 바꾼다).
    const last: Preset = @enumFromInt(n - 1);
    session.loaded_config.config.theme = config_mod.theme.presetColors(last);
    session.theme_user_custom = false;
    const last_bg = session.loaded_config.config.theme.background;
    settings_ops.applyThemePreset(session, 1);
    try std.testing.expect(session.theme_user_custom);
    try std.testing.expectEqualStrings(last_bg, session.loaded_config.config.theme.background);
    try std.testing.expect(!session.themePresetActive());

    // "사용자 지정"에서 +1 → 첫 프리셋(maru) 적용 + 잠금 복귀.
    settings_ops.applyThemePreset(session, 1);
    try std.testing.expect(!session.theme_user_custom);
    try std.testing.expectEqual(Preset.maru, AppSession.detectThemePreset(session.loaded_config.config.theme).?);
    try std.testing.expect(session.themePresetActive());

    // 세팅 폼(테마 섹션): 프리셋이 첫 dropdown(최상단)이고, 활성이라 색 행은 전부 disabled.
    var arena = std.heap.ArenaAllocator.init(allocator);
    defer arena.deinit();
    const secs = try settings_ops.buildSectionList(session, arena.allocator());
    for (secs, 0..) |s, idx| if (s.section == .theme) {
        session.chrome_host.settings.section = idx;
    };
    const rows = try settings_ops.buildSettingsFields(session, arena.allocator());
    var first_dropdown: ?[]const u8 = null;
    var any_color = false;
    var any_color_enabled = false;
    for (rows) |r| switch (r.kind) {
        .dropdown => if (first_dropdown == null) {
            first_dropdown = r.label;
        },
        .color => {
            any_color = true;
            if (!r.disabled) any_color_enabled = true;
        },
        else => {},
    };
    try std.testing.expectEqualStrings(maru.i18n.t(.set_theme_preset), first_dropdown.?); // 프리셋이 최상단 enum
    try std.testing.expect(any_color and !any_color_enabled); // 색 행 존재 + 전부 잠금

    // "사용자 지정"으로 풀면 색 행 활성(편집 가능).
    session.theme_user_custom = true;
    const rows2 = try settings_ops.buildSettingsFields(session, arena.allocator());
    var any_color_enabled2 = false;
    for (rows2) |r| if (r.kind == .color) {
        if (!r.disabled) any_color_enabled2 = true;
    };
    try std.testing.expect(any_color_enabled2);
}

// isWindowDragRegion: 헤더 '빈' 영역(아이콘·검색 아님)만 창 드래그/확대 영역(Swift performDrag·zoom). 아이콘·검색·
// 카드·접힘은 아니다 — 터미널 본문 드래그로 창이 끌려가던 것을 막고(mouseDownCanMoveWindow=false) 헤더만 타이틀바화.
test "isWindowDragRegion: only empty header area drags the window (not icons/search/cards/collapsed)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    const cw: f64 = @floatFromInt(session.cell_width_px);
    const icon_y: f64 = @as(f64, @floatFromInt(session.cell_height_px)) * 0.5; // 아이콘 줄(row 0)
    // 헤더 빈 영역(줄0 좌측 = 신호등 영역 옆 빈 공간) → 드래그 영역.
    try std.testing.expect(workspace_ops.isWindowDragRegion(session, 2 * cw, icon_y));
    // 우측 아이콘(◧/⚙/+) → 드래그 아님(클릭 대상).
    const gear_x: f64 = @as(f64, @floatFromInt(session.sidebar_width_px)) - 3 * cw;
    try std.testing.expect(!workspace_ops.isWindowDragRegion(session, gear_x, icon_y));
    // 검색 줄 → 드래그 아님.
    const search_y: f64 = @as(f64, @floatFromInt(session.sidebar_header_height_px)) * 0.85;
    try std.testing.expect(!workspace_ops.isWindowDragRegion(session, 2 * cw, search_y));
    // 헤더 아래 카드 영역 → 드래그 아님.
    const card_y: f64 = @as(f64, @floatFromInt(session.sidebar_header_height_px)) + 5;
    try std.testing.expect(!workspace_ops.isWindowDragRegion(session, 2 * cw, card_y));
    // 터미널 위 타이틀바 띠(y<strip) → 드래그 영역(② cmux식 상단 띠).
    const term_x: f64 = @floatFromInt(session.active_pane_rect.x + 50);
    try std.testing.expect(workspace_ops.isWindowDragRegion(session, term_x, @as(f64, @floatFromInt(session.titlebar_strip_px)) * 0.5));
    // 터미널 '본문'(띠 아래 y≥strip) → 드래그 아님(셀 선택).
    try std.testing.expect(!workspace_ops.isWindowDragRegion(session, term_x, @as(f64, @floatFromInt(session.titlebar_strip_px)) + 5));
    // 접힘: 전체 폭 타이틀바 띠가 드래그, 단 ◧ 펼치기 버튼 위는 아님(클릭).
    sidebar_ops.toggleSidebarCollapsed(session);
    const strip_y: f64 = @as(f64, @floatFromInt(session.titlebar_strip_px)) * 0.5;
    try std.testing.expect(workspace_ops.isWindowDragRegion(session, 2 * cw, strip_y)); // 띠 빈 곳
    const btn = session.collapsedToggleRect().?;
    try std.testing.expect(!workspace_ops.isWindowDragRegion(session, @as(f64, @floatFromInt(btn.x)) + 1, strip_y)); // ◧ 버튼 위
    sidebar_ops.toggleSidebarCollapsed(session); // 원복
}

// 사이드바 접기 토글: ◧ 클릭/토글 → 폭 0(완전 숨김) + pt 보존, 좌상단 펼치기 버튼 클릭 → 폭 복원. macOS 게이트.
test "sidebar collapse toggle: hides (width 0, pt preserved) and the top-left button expands it" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    const w0 = session.sidebar_width_px;
    const pt0 = session.sidebar_width_pt;
    try std.testing.expect(w0 > 0);
    try std.testing.expect(!session.sidebar_collapsed);
    try std.testing.expect(session.collapsedToggleRect() == null); // 펼침일 땐 버튼 없음

    // 접기(토글) → 폭 0, pt는 보존(복원용), 좌상단 버튼 등장. 검색이 활성이었으면 비활성화(키 갇힘 방지, code-review #3).
    session.sidebar_search_active = true; // 접기 직전 검색 활성 상태 가정
    sidebar_ops.toggleSidebarCollapsed(session);
    try std.testing.expect(session.sidebar_collapsed);
    try std.testing.expect(!session.sidebar_search_active); // 접으면 검색 비활성(보이지 않는 검색에 키 안 갇힘)
    try std.testing.expectEqual(@as(u32, 0), session.sidebar_width_px);
    try std.testing.expectEqual(pt0, session.sidebar_width_pt); // pt 보존
    try std.testing.expect(session.collapsedToggleRect() != null);
    // 펼치기 버튼 rect 높이 = 타이틀바 띠 전체(cell_h가 아님) — 1.7× 버튼이 띠 하단으로 삐져나간 데드존 방지(code-review #1).
    try std.testing.expectEqual(session.titlebar_strip_px, session.collapsedToggleRect().?.h);

    // 좌상단 펼치기 버튼 안 클릭 → 펼침(폭 복원). 사이드바 폭 0이라 inSidebar=false인데도 별도 경로로 잡힌다.
    const r = session.collapsedToggleRect().?;
    const bx: f64 = @floatFromInt(r.x);
    session.mouse(1, bx + 1, 1, 0, 0);
    try std.testing.expect(!session.sidebar_collapsed);
    try std.testing.expectEqual(w0, session.sidebar_width_px); // 폭 복원

    // 헤더 ◧(toggle_sidebar) 영역 클릭으로도 접힌다(폭이 충분해 헤더가 그려질 때).
    const cw: f64 = @floatFromInt(session.cell_width_px);
    const cols = session.sidebar_width_px / session.cell_width_px;
    if (cols >= 10) {
        const toggle_x: f64 = @as(f64, @floatFromInt(cols - 7)) * cw; // ◧ zone [cols-9, cols-6)
        const toggle_y: f64 = @as(f64, @floatFromInt(session.cell_height_px)) * 0.5;
        try std.testing.expectEqual(chrome.components.sidebar.HeaderRegion.toggle_sidebar, chrome.components.sidebar.headerHit(toggle_x, toggle_y, session.sidebar_width_px, session.cell_width_px, session.cell_height_px, session.sidebar_header_height_px, sidebar_ops.sidebarSearchBandTopPx(session)));
        session.mouse(1, toggle_x, toggle_y, 0, 0);
        try std.testing.expect(session.sidebar_collapsed);
    }
}

// chrome 기하는 **투영 시점에 스탬프**돼 셀과 한 프레임이어야 한다. host는 generation이 그대로여도 다시 그릴 수
// 있으므로(drawableSize·backing-scale 변경 등 metalNeedsRedraw 경로), draw 시점의 live 값을 덮어쓰면 메트릭이 바뀌고
// 아직 재투영되지 않은 프레임에서 **옛 pitch로 만든 셀 + 새 헤더/슬롯 높이**가 섞인다(⌘+ 직후 사이드바 글자와 밴드가
// 어긋나던 부류). 폰트 크기를 바꾼 뒤 tick 없이 frame을 읽어 그 분리를 확인한다.
test "metalFrame chrome 기하는 투영 스탬프다 — live 메트릭이 셀과 섞이지 않는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1000, 700, 1000);

    // 첫 투영 전엔 셀이 비어 정합 상대가 없다 — live 기하를 그대로 내보내야 한다. 스탬프 기본값 0을
    // 내보내면 기동 첫 draw가 사이드바 폭 0으로 그려 배경 띠가 한 프레임 빠진다.
    try std.testing.expect(!session.metal_buffer.chrome_geometry_stamped);
    try std.testing.expect(session.sidebar_width_px > 0);
    try std.testing.expectEqual(session.sidebar_width_px, session.metalFrame().terminal_origin_x_px);
    try std.testing.expectEqual(session.titlebar_strip_px, session.metalFrame().titlebar_strip_px);

    // 폴백 술어는 **스탬프 유무**여야 한다(generation 아님). `setCursorFadeMilli`는 셀도 기하도 안 바꾸면서
    // generation을 올리므로, 첫 투영 전 blink tick 하나가 generation을 1로 만든다 — 그때도 폴백은 살아야 한다.
    session.metal_buffer.setCursorFadeMilli(500);
    try std.testing.expect(session.metalFrame().generation != 0);
    try std.testing.expect(!session.metal_buffer.chrome_geometry_stamped);
    try std.testing.expectEqual(session.sidebar_width_px, session.metalFrame().terminal_origin_x_px);

    _ = try session.tick(); // 첫 투영 — 셀과 기하가 함께 확정된다

    const stamped_slot = session.metalFrame().sidebar_slot_height_px;
    const stamped_strip = session.metalFrame().titlebar_strip_px;
    try std.testing.expectEqual(session.sidebar_slot_height_px, stamped_slot);

    // 폰트를 키우면 live 메트릭이 즉시 바뀐다(슬롯/띠는 cell 높이 파생). 아직 재투영 전이므로 frame은 **옛 값**을
    // 유지해야 한다 — 그래야 그 프레임의 셀과 정합한다.
    session.dispatchAppAction(.increase_font_size);
    try std.testing.expect(session.sidebar_slot_height_px != stamped_slot or session.titlebar_strip_px != stamped_strip);
    try std.testing.expectEqual(stamped_slot, session.metalFrame().sidebar_slot_height_px);
    try std.testing.expectEqual(stamped_strip, session.metalFrame().titlebar_strip_px);

    // 재투영되면 둘이 함께 새 값으로 간다.
    _ = try session.tick();
    try std.testing.expectEqual(session.sidebar_slot_height_px, session.metalFrame().sidebar_slot_height_px);
    try std.testing.expectEqual(session.titlebar_strip_px, session.metalFrame().titlebar_strip_px);
}

// quad 수명·순서 계약(S0): `dropQuadsByLayer`는 **자기 레이어만** 지우고 **나머지 순서를 보존**해야 하며,
// `rebuildSidebar`는 **layer 0만** 비워야 한다. 둘 다 화면에 안 보이는 계약이라 눈으로는 못 잡는다 —
// 어기면 (a) 사이드바 이벤트(hover·드래그·탭 전환) 직후 tick이 full 투영이 아닐 때 탭 밴드·스크롤바·배지가
// 한 프레임 사라지고, (b) 레이어 안 painter 순서(카드 tint 위에 accent 막대)가 뒤집힌다.
test "gpu quad 수명: drop은 자기 레이어만·순서 보존, rebuildSidebar는 layer 0만 비운다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1000, 700, 1000);

    // 레이어를 섞어 넣고, 같은 레이어 안에서 순서를 구분할 수 있게 x를 다르게 준다.
    session.gpu_quads.clearRetainingCapacity();
    const mk = struct {
        fn q(x: f32, layer: u32) metal_frame.GpuQuad {
            return .{
                .x = x,
                .y = 0,
                .w = 1,
                .h = 1,
                .corner_radii = .{ 0, 0, 0, 0 },
                .border_widths = .{ 0, 0, 0, 0 },
                .fill_color0 = 0xFF000000,
                .fill_color1 = 0xFF000000,
                .border_color = 0,
                .gradient_kind = 0,
                .layer = layer,
                .clip_x = 0,
                .clip_y = 0,
                .clip_w = 0,
                .clip_h = 0,
            };
        }
    };
    try session.gpu_quads.append(allocator, mk.q(10, 2)); // A: per-frame
    try session.gpu_quads.append(allocator, mk.q(20, 0)); // B: retained(사이드바 tint)
    try session.gpu_quads.append(allocator, mk.q(30, 2)); // C: per-frame
    try session.gpu_quads.append(allocator, mk.q(40, 0)); // D: retained(accent 막대 — B보다 뒤=위)

    session.dropQuadsByLayer(2);
    try std.testing.expectEqual(@as(usize, 2), session.gpu_quads.items.len);
    // 순서 보존: B가 D보다 앞이어야 막대가 tint 위에 그려진다(swapRemove였다면 뒤집힐 수 있다).
    try std.testing.expectEqual(@as(f32, 20), session.gpu_quads.items[0].x);
    try std.testing.expectEqual(@as(f32, 40), session.gpu_quads.items[1].x);

    // rebuildSidebar는 layer 0만 소유한다 — per-frame quad를 남겨야 그 프레임에 안 사라진다.
    try session.gpu_quads.append(allocator, mk.q(50, 2)); // per-frame 탭 밴드
    try session.gpu_quads.append(allocator, mk.q(60, 3)); // per-frame 스크롤바
    try sidebar_ops.rebuildSidebar(session);
    var survived_2: bool = false;
    var survived_3: bool = false;
    for (session.gpu_quads.items) |q| {
        if (q.layer == 2 and q.x == 50) survived_2 = true;
        if (q.layer == 3 and q.x == 60) survived_3 = true;
    }
    try std.testing.expect(survived_2);
    try std.testing.expect(survived_3);
}

// 상태바는 **텍스트 행을 담고 위아래 여백이 남아야** 한다. 고정 높이만 쓰면 (1) 기본 폰트에서 위아래
// 2px밖에 안 남아 빡빡하고(사용자 지적), (2) 폰트를 키워 셀이 바보다 커지면 세로 중앙 계산이 0으로
// 포화돼 **글자가 창 밖으로 넘친다**. 텍스트가 터미널 셀 높이를 쓰는 이상 바가 그걸 담아야 한다.
test "SB1: 상태바 높이는 텍스트 행 + 여백을 담고, 하한은 폰트 독립이다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1000, 700, 1000);

    const pad2 = 2 * layout_math.ptToPx(status_bar_v_pad_pt, session.scale_milli);
    try std.testing.expect(session.statusBarHeightPx() >= session.cell_height_px + pad2);
    try std.testing.expect(session.statusBarHeightPx() >= layout_math.ptToPx(status_bar_height_pt, session.scale_milli));

    // 폰트를 키워 셀이 하한을 넘겨도 바가 따라 커진다 — 안 그러면 글자가 바 아래로 넘친다.
    var i: usize = 0;
    while (i < 12) : (i += 1) session.dispatchAppAction(.increase_font_size);
    try std.testing.expect(session.cell_height_px > layout_math.ptToPx(status_bar_height_pt, session.scale_milli));
    try std.testing.expect(session.statusBarHeightPx() >= session.cell_height_px + pad2);
}

// SB1-S3d: **상태바 배경은 터미널 레이어(bottom)여야 한다.** 항목 텍스트가 `pane_frames`를 타고 터미널
// 레이어 셀 패스로 그려지므로, 배경을 over 버킷에 두면 별도 오버레이 CAMetalLayer가 터미널 레이어 전체
// 위에 합성돼 **자기 텍스트를 덮는다**(실제로 S3b·S3c가 그 상태로 머지됐고, 알림 항목을 헤드리스로 찍어
// 처음 드러났다). 눈에 안 보이는 계약이라 값으로 못박는다 — `.m` 버킷팅이 2=bottom·0=under·4=header·그 밖=over다.
test "SB1-S3d: 상태바 배경은 bottom 버킷이어야 텍스트를 안 덮는다" {
    try std.testing.expectEqual(@as(u32, 2), AppSession.status_bar_layer);
    // over 버킷(그 밖)이나 header/under면 텍스트가 가려지거나 순서가 뒤집힌다.
    try std.testing.expect(AppSession.status_bar_layer != 0);
    try std.testing.expect(AppSession.status_bar_layer != 4);
    try std.testing.expect(AppSession.status_bar_layer != 1 and AppSession.status_bar_layer != 3 and AppSession.status_bar_layer != 5);
}

// SB1-S2b: 상태바가 **실제로 그려지는지**를 quad 수준에서 못박는다. 도크 골든은 Chrome Lab 경로라
// `status_bar_height_px=0`을 직접 넘겨 이 표면을 전혀 덮지 않는다 — 그래서 여기서 본다.
// 레이어가 특히 중요하다: layer 4(header)는 사이드바 셀보다 **먼저** 그려져 카드가 상태바를 덮는다.
// over 버킷(`.m`이 2/0/4 외를 전부 over로 보낸다)만이 사이드바 셀 뒤에 온다.
// SB1 §5.3: 사이드바 셀 scissor. 이 계약은 `.m` 산술이라 **자동 가드가 없었다** — 문서 커버리지 표의
// 마지막 ❌였다. 산술을 Zig로 옮겼으니 이제 순수 함수로 전부 덮인다.
// 위 순수 함수는 처음부터 옳았다. **틀린 것은 호출처가 넘긴 값**이었고, 그래서 산술만 보는 단위
// 테스트가 통과하는 동안 제품 화면에서는 스크롤한 카드 제목이 검색바 위로 샜다. 제품 경로에서
// "그 값이 실제로 무엇이 되는가"를 본다 — 기본 테마(rich)로 돌린다는 점이 핵심이다.
test "sidebar scissor engages on the product path even when bands are quads (rich)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    // 기본이 rich다 — 밴드가 GPU quad라 `sidebar_cells`(tui 밴드 배열)가 빈다. 옛 게이트는 그것을 보고
    // "자를 셀이 없다"고 판정했지만, 카드 **제목**은 별도 프레임으로 실려 실제로는 그려지고 있었다.
    try std.testing.expect(session.sidebar_width_px > 0);
    try std.testing.expect(session.sidebar_header_height_px > 0);

    // 스크롤 전에는 자를 이유가 없다(헤더 위로 샌 것이 없다).
    session.sidebar_scroll_offset_px = 0;
    {
        const geo = session.chromeGeometrySnapshot();
        try std.testing.expectEqual(@as(u32, 0), geo.sidebar_scissor_top_px);
    }

    // 스크롤하면 **헤더 아래부터** 자른다. 옛 코드는 여기서 0을 내 렌더러가 scissor에 진입하지 못했다.
    session.sidebar_scroll_offset_px = 10;
    const geo = session.chromeGeometrySnapshot();
    try std.testing.expectEqual(session.sidebar_header_height_px, geo.sidebar_scissor_top_px);
    try std.testing.expect(geo.sidebar_scissor_bottom_px > geo.sidebar_scissor_top_px);

    // 사이드바가 접히면(폭 0) 자를 대상이 없다 — 게이트를 넓히면서 이 축까지 잃으면 안 된다.
    session.sidebar_width_px = 0;
    const collapsed = session.chromeGeometrySnapshot();
    try std.testing.expectEqual(@as(u32, 0), collapsed.sidebar_scissor_top_px);
    try std.testing.expectEqual(@as(u32, 0), collapsed.sidebar_scissor_bottom_px);
}

test "SB1: 사이드바 scissor는 스크롤과 상태바 각각을 이유로 자르고, 아니면 안 자른다" {
    const S = sidebar_ops.sidebarScissorPx;

    // 아무 이유도 없으면 안 자른다(bottom <= top). 자를 이유가 없는데 scissor를 걸면 뒤 패스가 영향을 받는다.
    const idle = S(960, true, 40, 0, 0);
    try std.testing.expectEqual(@as(u32, 0), idle.top);
    try std.testing.expectEqual(@as(u32, 0), idle.bottom);

    // 셀이 없으면 자를 대상이 없다.
    const no_cells = S(960, false, 40, 10, 22);
    try std.testing.expectEqual(@as(u32, 0), no_cells.bottom);

    // 스크롤만 — 위(헤더)만 자른다. 아래는 창 바닥까지.
    const scrolled = S(960, true, 40, 10, 0);
    try std.testing.expectEqual(@as(u32, 40), scrolled.top);
    try std.testing.expectEqual(@as(u32, 960), scrolled.bottom);

    // 상태바만 — **스크롤이 0이어도 아래를 자른다**(`sidebar_ops.sidebarBandCell`이 세로 경계를 안 보므로 맨 아래
    // 카드가 띠 안까지 발행된다). 위는 안 자른다: 스크롤이 0이면 헤더 위로 샐 것이 없다(기존 동작 보존).
    const bar_only = S(960, true, 40, 0, 22);
    try std.testing.expectEqual(@as(u32, 0), bar_only.top);
    try std.testing.expectEqual(@as(u32, 938), bar_only.bottom);

    // 둘 다 — 위아래를 함께 자른다.
    const both = S(960, true, 40, 10, 22);
    try std.testing.expectEqual(@as(u32, 40), both.top);
    try std.testing.expectEqual(@as(u32, 938), both.bottom);
}

// degenerate 창에서 **뒤집힌 rect를 내지 않는다.** MTLScissorRect에 top > bottom을 넣으면 정의되지 않은
// 영역이 되고, 그리려던 것이 통째로 사라지거나 엉뚱한 데가 남는다.
test "SB1: 사이드바 scissor는 겹치거나 뒤집힌 구간을 내느니 안 자른다" {
    const S = sidebar_ops.sidebarScissorPx;

    // 상태바가 창을 다 먹으면 bottom이 0 → top 이하라 안 자른다.
    const swallowed = S(20, true, 0, 0, 20);
    try std.testing.expectEqual(@as(u32, 0), swallowed.bottom);

    // 헤더가 남은 구간보다 아래면(헤더 40 + 상태바 22 > 창 50) top >= bottom이라 안 자른다.
    const squeezed = S(50, true, 40, 10, 22);
    try std.testing.expectEqual(@as(u32, 0), squeezed.top);
    try std.testing.expectEqual(@as(u32, 0), squeezed.bottom);

    // 창 높이 0.
    const zero = S(0, true, 0, 5, 5);
    try std.testing.expectEqual(@as(u32, 0), zero.bottom);

    // 어떤 입력에서도 top < bottom이거나 둘 다 0이다(그 사이 상태는 없다).
    for ([_]u32{ 0, 1, 20, 50, 960 }) |h| {
        for ([_]u32{ 0, 40, 1000 }) |header| {
            for ([_]u32{ 0, 10 }) |scroll| {
                for ([_]u32{ 0, 22, 2000 }) |bar| {
                    const r = S(h, true, header, scroll, bar);
                    try std.testing.expect(r.bottom > r.top or (r.top == 0 and r.bottom == 0));
                }
            }
        }
    }
}

// SB1: **긴 경로는 잎이 남아야 한다.** 순수 함수(`text_layout.elidePathMiddle`)만 통과하고 배선이 빠지면
// 화면은 그대로 끝이 잘린다 — 그래서 실제 항목 DrawList에 잎(마지막 디렉터리)이 실렸는지로 본다.
test "SB1: 편집기 pane이 활성일 때만 편집기 항목이 뜨고, 순서가 버려지는 순서다" {
    // §2.2: 상태바는 창 전폭 띠라 늘 떠 있으면 터미널을 쓰는 동안에도 기존 항목을 밀어낸다 —
    // 그래서 편집기 항목은 **조건부**다. 그리고 배열 순서 = 버려지는 순서라, "축소가 일어났다"는
    // 사실이 가장 오래 남아야 한다(저하 → 읽기 전용 → 줄바꿈).
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    var collected: std.ArrayList(AppSession.CollectedPane) = .empty;
    defer {
        for (collected.items) |*c| c.deinit(allocator);
        collected.deinit(allocator);
    }
    const builder = pane_ops.paneFrameBuilder(session);
    const colors: metal_frame.CellColors = .{ .default_fg = session.appearance.theme.foreground };

    // ① 터미널이 활성이면 **하나도** 안 나온다.
    session.collectStatusBarItems(&collected, builder, colors);
    for (session.statusBarTree().entries) |e| {
        const id: chrome.components.status_bar.ItemId = @enumFromInt(e.id);
        try std.testing.expect(id != .editor_readonly and id != .editor_eol and id != .editor_degraded);
    }

    // ② 편집기 pane을 연다 — 이 저장소의 실제 파일을 그대로 쓴다(줄바꿈이 LF인 파일).
    const editor_term = editor_ops.openPathInActivePane(session, "src/session/editor/selection.zig") catch return error.SkipZigTest;
    for (collected.items) |*c| c.deinit(allocator);
    collected.clearRetainingCapacity();
    session.collectStatusBarItems(&collected, builder, colors);

    var readonly_at: ?usize = null;
    var eol_at: ?usize = null;
    for (session.statusBarTree().entries, 0..) |e, i| {
        switch (@as(chrome.components.status_bar.ItemId, @enumFromInt(e.id))) {
            .editor_readonly => readonly_at = i,
            .editor_eol => eol_at = i,
            else => {},
        }
    }
    // **읽기 전용은 상시 자리다**(편집이 막혀 있음을 알리는 유일한 표시).
    try std.testing.expect(readonly_at != null);
    // 줄바꿈은 그 **왼쪽**이다 = 먼저 버려진다. 트리 순서가 곧 화면 좌우이므로 x로 본다.
    if (eol_at) |eol_i| {
        const entries = session.statusBarTree().entries;
        try std.testing.expect(entries[eol_i].rect.x < entries[readonly_at.?].rect.x);
    }

    // ③ **커서 위치는 편집기 묶음에서 가장 오른쪽 = 가장 오래 산다**(§2.2 표의 첫 항목).
    //    이것이 커밋 전체의 논거인데 재는 자리가 없어, 코드에서 자리를 정반대(묶음 맨 뒤)로 옮겨도
    //    스위트가 전부 초록이었다. 화면 x로 본다 — "더하는 순서"는 구현이고, 계약은 좌우다.
    editor_term.rt.editor_selection = .{ .anchor_start = 0, .anchor_end = 0, .focus = 0 };
    for (collected.items) |*c| c.deinit(allocator);
    collected.clearRetainingCapacity();
    session.collectStatusBarItems(&collected, builder, colors);

    var cursor_at: ?usize = null;
    var group_x: ?f32 = null; // 커서를 뺀 편집기 항목들의 가장 오른쪽 x
    for (session.statusBarTree().entries, 0..) |e, i| {
        switch (@as(chrome.components.status_bar.ItemId, @enumFromInt(e.id))) {
            .editor_cursor => cursor_at = i,
            .editor_degraded, .editor_readonly, .editor_eol => {
                if (group_x == null or e.rect.x > group_x.?) group_x = e.rect.x;
            },
            else => {},
        }
    }
    try std.testing.expect(cursor_at != null);
    const entries = session.statusBarTree().entries;
    try std.testing.expect(entries[cursor_at.?].rect.x > group_x.?);
}

// **상한이 후보보다 작으면 마지막 후보가 폭과 무관하게 사라진다.** 실제로 커서 위치를 더했을 때
// 리소스가 폭 2,500px를 남긴 채로 빠졌고, 화면만 봐서는 폭 부족과 구분되지 않는다.
//
// 상한은 `right_candidates.len`에서 파생되고 그 원장은 다시 `ItemId`에서 파생되므로, "항목만 더하고
// 상한을 잊는" 경로는 **구조적으로 막혀 있다**. 남는 위험은 조립부가 원장 밖 id를 싣는 것이라,
// 그건 **조립 결과로** 잰다 — comptime 단언은 `X >= X`가 되어 항진명제다(적대적 검증 2026-08-21).
test "SB1: 조립된 우측 항목은 전부 우측 후보 원장 안에 있다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    var collected: std.ArrayList(AppSession.CollectedPane) = .empty;
    defer {
        for (collected.items) |*c| c.deinit(allocator);
        collected.deinit(allocator);
    }
    const builder = pane_ops.paneFrameBuilder(session);
    const colors: metal_frame.CellColors = .{ .default_fg = session.appearance.theme.foreground };
    _ = editor_ops.openPathInActivePane(session, "src/session/editor/selection.zig") catch return error.SkipZigTest;
    session.collectStatusBarItems(&collected, builder, colors);

    const sb = chrome.components.status_bar;
    const bar_mid = session.statusBarTree().entries.len;
    try std.testing.expect(bar_mid > 0); // 아무것도 안 실렸으면 아래가 항진명제다
    for (session.statusBarTree().entries) |e| {
        const id: sb.ItemId = @enumFromInt(e.id);
        if (id == .git_branch or id == .cwd) continue; // 좌측 전용
        var found = false;
        for (sb.right_candidates) |c| {
            if (c == id) found = true;
        }
        try std.testing.expect(found);
    }
}

test "SB1: 상태바 경로 항목은 끝이 아니라 중간을 생략한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1000, 700, 1000);
    _ = try session.tick();

    const long_path = "/tmp/aaaaaaaaaaaaaaaa/bbbbbbbbbbbbbbbb/cccccccccccccccc/dddddddddddddddd/leafdir";
    const black: terminal.Color = .{ .rgb = .{ .r = 0, .g = 0, .b = 0 } };
    const term = pane_ops.activePane(session).activeTerm();
    term.rt.observation.availability = .current;
    term.rt.observation.cwd.clearRetainingCapacity();
    try term.rt.observation.cwd.appendSlice(allocator, long_path);
    session.metal_dirty = true;
    _ = try session.tick();

    // 경로가 실제로 바까지 흐른다(항목이 tree에 선다).
    var cwd_entry: ?chrome.ui.tree.RectEntry = null;
    for (session.statusBarTree().entries) |e| {
        if (e.id == @intFromEnum(chrome.components.status_bar.ItemId.cwd)) cwd_entry = e;
    }
    const entry = cwd_entry orelse return error.CwdItemMissing;

    const bar_cols: u16 = @intCast(session.backing_width_px / session.cell_width_px);
    // 전제: 이 경로는 항목 예산(bar_cols/3)을 넘는다. 안 넘으면 생략이 안 일어나 검증이 비어 버린다.
    try std.testing.expect(chrome.text_layout.displayCols(long_path, null) > @max(1, bar_cols / 3));

    var dl = session.buildStatusBarItem(icons.codepoint(.folder), long_path, bar_cols, black, black, .path) orelse return error.ItemMissing;
    defer dl.deinit(allocator);

    // 셀 codepoint를 이어 붙여 실제로 그려질 글자를 읽는다.
    var text: std.ArrayList(u8) = .empty;
    defer text.deinit(allocator);
    for (dl.cells) |c| {
        if (c.codepoint == 0) continue;
        var b: [4]u8 = undefined;
        const len = std.unicode.utf8Encode(@intCast(c.codepoint), &b) catch continue;
        try text.appendSlice(allocator, b[0..len]);
    }

    try std.testing.expect(std.mem.indexOf(u8, text.items, "leafdir") != null); // 잎이 살아 있다
    try std.testing.expect(std.mem.indexOf(u8, text.items, "…") != null); // 생략 표시가 있다

    // **호출부가 실제로 .path를 넘기는지**까지 본다. 위 단언은 `.path`로 직접 부른 결과라, 호출부가
    // `.plain`으로 되돌아가도 안 죽는다(뮤테이션으로 확인했다). 발행된 rect 폭으로 대조한다 —
    // 끝을 자르면 예산을 꽉 채우고, 컴포넌트로 줄이면 경계에서 끊겨 그보다 좁다.
    var plain = session.buildStatusBarItem(icons.codepoint(.folder), long_path, bar_cols, black, black, .plain) orelse return error.ItemMissing;
    defer plain.deinit(allocator);
    const plain_w: u32 = @as(u32, plain.size.cols) * session.cell_width_px;
    const pad = layout_math.ptToPx(status_bar_item_pad_pt, session.scale_milli);
    const published_w: u32 = @as(u32, @intFromFloat(entry.rect.width)) -| (2 * pad);
    try std.testing.expect(published_w < plain_w);
}

// SB1: **reload로 껐을 때 pane까지 새 높이로 다시 재야 한다.** `statusBarHeightPx`를 읽는 것은 그리기만이
// 아니다 — `gridPadding`을 타고 pane/PTY 크기 계산에도 들어간다. 그래서 reload가 pane을 **옛 config로 재고**
// 새 config로 그리면, 바는 사라졌는데 셸은 늘어난 행을 못 받는다(빈 띠가 남는 것과 같은 부류의 반쪽 적용).
test "SB1: reload로 status-bar.show를 끄면 pane 크기도 새 값으로 다시 잰다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;

    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    try tmp.dir.writeFile(std.testing.io, .{ .sub_path = "config", .data = "status-bar.show = false\n" });
    var cfg_path_buf: [256]u8 = undefined;
    const cfg_path = try std.fmt.bufPrintZ(&cfg_path_buf, ".zig-cache/tmp/{s}/config", .{tmp.sub_path});

    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1000, 700, 1000);
    _ = try session.tick();

    const bar_on = session.statusBarHeightPx();
    try std.testing.expect(bar_on > 0); // 전제: 기본은 켜짐
    const pad_on = session.gridPadding().bottom;

    // env는 프로세스 전역이라 **원래 값을 되돌린다** — 그냥 unset하면 MARU_CONFIG를 이미 쓰던 실행에서
    // 뒤에 오는 테스트의 config 출처가 조용히 바뀐다(원인 찾기 어려운 교차 오염).
    // getenv가 준 포인터는 environ 안을 가리키고 **setenv가 그 메모리를 덮을 수 있다** — 값을 먼저 복사한다.
    var prev_buf: [1024]u8 = undefined;
    const prev_cfg: ?[:0]const u8 = if (std.c.getenv("MARU_CONFIG")) |v| blk: {
        const span = std.mem.span(v);
        if (span.len >= prev_buf.len) break :blk null; // 너무 길면 복원 포기(테스트 환경에선 없다)
        @memcpy(prev_buf[0..span.len], span);
        prev_buf[span.len] = 0;
        break :blk prev_buf[0..span.len :0];
    } else null;
    _ = setenv("MARU_CONFIG", cfg_path.ptr, 1);
    defer if (prev_cfg) |v| {
        _ = setenv("MARU_CONFIG", v.ptr, 1);
    } else {
        _ = unsetenv("MARU_CONFIG");
    };
    settings_ops.reloadConfig(session);
    _ = try session.tick();

    try std.testing.expectEqual(@as(u32, 0), session.statusBarHeightPx()); // 껐다
    // pane 재측정이 **새** 값을 썼는지: bottom padding이 바 높이만큼 줄었어야 한다.
    try std.testing.expectEqual(pad_on - bar_on, session.gridPadding().bottom);
    // 그리고 grid도 그만큼 늘었다(셸이 실제로 행을 받는다).
    const grid = layout_math.gridFromBacking(session.backing_width_px, session.backing_height_px, session.cell_width_px, session.cell_height_px, session.sidebar_width_px, session.gridPadding());
    try std.testing.expectEqual(grid.rows, session.last_resize_size.?.rows);
}

// SB1: **브랜치 메뉴가 상태바를 덮으면 안 된다.** 앵커가 창 맨 아래(바 항목)라, 클램프가 상태바를 모르면
// 메뉴가 바 위로 깔려 브랜치·경로를 가린다. 컨텍스트 메뉴의 "하단 넘으면 위로"가 기준으로 쓰는
// `workspaceRect`가 실제로 바를 뺀 값인지를 **좌표로** 확인한다(단언을 기하로 하지 산술을 다시 쓰지 않는다).
test "SB1: 브랜치 메뉴는 상태바를 덮지 않는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 80,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1000, 700, 1000);
    _ = try session.tick();

    // 이 테스트는 **앵커가 실제로 있을 때의 기하**를 보므로 상태바에 브랜치 항목을 세운다.
    // 실행 디렉터리의 저장소 형태에 기대지 않고 cache를 직접 구성한다. linked worktree의 `.git`은
    // 디렉터리가 아닌 gitdir 파일이라 `git_ops.readGitBranch`의 best-effort 범위 밖이고, 그 차이는 메뉴 기하와 무관하다.
    const term = pane_ops.activePane(session).activeTerm();
    term.rt.observation.availability = .current;
    term.rt.observation.cwd.clearRetainingCapacity();
    var cwd_buf: [std.fs.max_path_bytes]u8 = undefined;
    const cwd_ptr = std.c.getcwd(&cwd_buf, cwd_buf.len) orelse return error.SkipZigTest;
    try term.rt.observation.cwd.appendSlice(allocator, std.mem.span(@as([*:0]u8, @ptrCast(cwd_ptr))));
    if (term.git_branch) |branch| allocator.free(branch);
    term.git_branch = null;
    if (term.git_branch_cwd) |branch_cwd| allocator.free(branch_cwd);
    term.git_branch_cwd = null;
    term.git_branch = try allocator.dupe(u8, "fixture");
    term.git_branch_cwd = try allocator.dupe(u8, term.rt.observation.cwd.items);
    session.metal_dirty = true;
    _ = try session.tick();

    session.branch_menu_text = try allocator.dupe(u8, "main\nfeat/a\nfix/b\n");
    session.branch_menu_len = git_command.collectBranches(session.branch_menu_text, &session.branch_menu_names);
    settings_ops.openBranchMenu(session);
    try std.testing.expect(session.chrome_host.context_menu.open);

    // 메뉴 x를 추정하지 않고 **훑는다** — 앵커는 브랜치 항목 유무·사이드바 클램프에 따라 달라진다.
    // (처음엔 화면 한가운데를 찔렀는데 가로로 빗나가 아무 데서도 안 잡히는 헛 테스트였다. vacuity 가드가 잡았다.)
    const h = session.statusBarHeightPx();
    try std.testing.expect(h > 0);
    const bar_top = session.backing_height_px -| h;
    const props = session.buildChromeProps();
    const items = settings_ops.contextMenuItems(session);

    // ① 바 안에서는 어디를 찔러도 메뉴가 잡히면 안 된다(덮지 않는다).
    var x: u32 = 0;
    while (x < session.backing_width_px) : (x += 16) {
        const hit = chrome.components.context_menu.itemAt(
            &session.chrome_host.context_menu,
            items,
            props,
            @floatFromInt(x),
            @floatFromInt(bar_top + h / 2),
        );
        try std.testing.expect(hit == null);
    }

    // ② 바 바로 위에는 메뉴가 실제로 있어야 한다 — 없으면 ①이 헛돈 것이다.
    var found = false;
    var probe_y: u32 = bar_top -| 4;
    outer: while (probe_y + 200 > bar_top and probe_y > 0) : (probe_y -|= 8) {
        var px: u32 = 0;
        while (px < session.backing_width_px) : (px += 16) {
            if (chrome.components.context_menu.itemAt(
                &session.chrome_host.context_menu,
                items,
                props,
                @floatFromInt(px),
                @floatFromInt(probe_y),
            ) != null) {
                found = true;
                break :outer;
            }
        }
    }
    try std.testing.expect(found);
}

// WP-F1 적대적 5R: **불변식이 과잉 차단하면 안 된다.** 매 tick 도는 코드라 두 가지를 확인한다 —
// ⑴ 웹 탭을 **거쳐 갔다가** 터미널로 돌아오면 다시 열 수 있어야 하고(닫힌 게 영구 상태로 굳으면 안 된다),
// ⑵ 웹이 활성이 **아닌** 동안에는 매 tick 돌아도 열린 find를 건드리지 않아야 한다(깜빡임·검색어 유실).
test "WP-F1: 불변식이 터미널 활성 시 find를 건드리지 않고, 돌아오면 다시 열린다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 80,
        .rows = 24,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    const pane = pane_ops.activePane(session);
    const md = try web_ops.createWebTerm(session, .markdown);
    try pane.terms.append(allocator, md);

    // ⑵ 터미널 활성 — 여러 tick을 돌려도 find가 살아 있고 검색어도 남는다.
    session.dispatchAppAction(.toggle_find);
    try session.chrome_host.find.input.appendChar(allocator, 'x');
    _ = try session.tick();
    _ = try session.tick();
    try std.testing.expect(session.chrome_host.find.open);
    try std.testing.expectEqualStrings("x", session.chrome_host.find.input.query.items);

    // 웹 탭에 갔다 와도 오버레이와 검색어가 살아 있다(대상만 갈린다).
    term_ops.focusTerm(session, pane.terms.items.len - 1);
    _ = try session.tick();
    try std.testing.expect(session.chrome_host.find.open);
    try std.testing.expectEqualStrings("x", session.chrome_host.find.input.query.items);

    // ⑴ 터미널로 돌아와도 그대로 쓸 수 있다(영구 차단이 아니다).
    term_ops.focusTerm(session, 0);
    _ = try session.tick();
    try std.testing.expect(session.chrome_host.find.open);
}

// WP-F1 적대적 4R: **탭 전환만 막으면 새는 곳이 남는다.** 활성 서페이스는 pane 전환·탭(창) 전환으로도
// 바뀐다. `focusTerm` 한 곳만 닫으면 그 경로들로 오버레이가 웹 위에 남는다 — 3라운드와 같은 결함이
// 다른 문으로 들어오는 것이다. 그래서 **경로마다 막지 않고 tick 불변식으로** 잡는지 확인한다.
test "WP-F1: pane 전환으로 웹이 활성이 돼도 스크롤백 매치가 남지 않는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 80,
        .rows = 24,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    // 두 번째 pane을 만들고 거기에 웹 탭을 둔다.
    session.dispatchAppAction(.split_vertical);
    const panes = session.tabs.items[session.app_window.active_tab].panes.items;
    if (panes.len < 2) return error.SkipZigTest; // split 불가 환경
    const web_pane = panes[1];
    const md = try web_ops.createWebTerm(session, .markdown);
    try web_pane.terms.append(allocator, md);
    web_pane.active_term = web_pane.terms.items.len - 1;

    // 첫 pane(터미널)에서 find를 연다.
    _ = pane_ops.focusPaneByPtr(session, panes[0]);
    session.dispatchAppAction(.toggle_find);
    try std.testing.expect(session.chrome_host.find.open);

    // pane을 웹 쪽으로 옮긴다 — 여기서도 닫혀야 한다.
    _ = pane_ops.focusPaneByPtr(session, web_pane);
    _ = try session.tick();
    // 경로가 달라도 결론은 같다 — 열린 채, 터미널 매치는 버린다.
    try std.testing.expect(session.chrome_host.find.open);
    try std.testing.expectEqual(@as(usize, 0), session.find_matches.items.len);
}

// WP-F1 적대적: **열어 둔 채 웹 탭으로 옮기면?** 게이트는 "여는 순간"만 본다. 터미널에서 find를 연 뒤
// 웹 탭으로 전환하면 오버레이가 **웹 콘텐츠 위에 뜬 채 남고**, 그 상태로 타이핑하면 보이지도 않는
// 터미널 스크롤백을 검색한다 — 처음 제보와 같은 혼란이다.
test "WP-F1: find를 연 채 웹 탭으로 전환하면 대상이 페이지로 바뀐다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 80,
        .rows = 24,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    session.dispatchAppAction(.toggle_find);
    try std.testing.expect(session.chrome_host.find.open); // 터미널에서 열었다

    const pane = pane_ops.activePane(session);
    const md = try web_ops.createWebTerm(session, .markdown);
    try pane.terms.append(allocator, md);
    term_ops.focusTerm(session, pane.terms.items.len - 1); // 웹 탭으로 전환
    _ = try session.tick(); // 불변식은 렌더 전에 돈다

    // 슬라이스 ② 이후: 오버레이는 **열린 채로 두고 대상만 페이지로 바꾼다**(닫지 않는다).
    // 지켜야 하는 것은 "보이지도 않는 스크롤백을 검색하지 않는다"이지 "오버레이를 없앤다"가 아니다.
    try std.testing.expect(session.chrome_host.find.open);
    try std.testing.expectEqual(@as(usize, 0), session.find_matches.items.len); // 터미널 매치는 버린다
}

// WP-F1 적대적 R9: **찾음/없음이 draw op에서 끝나지 않고 셀까지 도착하는지** 확인한다(R1은 op 수준까지만 본다).
// 긴 검색어로 패널을 꽉 채운 상태에서 본다 — 표시기와 검색어 꼬리가 함께 살아 있어야 한다.
//
// 원래는 "한글 예약 폭이 틀리면 잘리거나 덮인다"를 겨눴는데 **그 가설은 뮤테이션으로 반증됐다**: 폭을
// 코드포인트 수(2칸)로 재도 이 레이아웃은 깨지지 않는다(우측 클리핑이 없고 예약이 1칸 여유를 둔다). 그래서
// 이 테스트가 실제로 지키는 계약만 남겼다 — 표시기가 셀에 도달한다(표시기를 없애는 뮤테이션이 죽인다).
test "WP-F1 R9: found/none 표시기가 셀까지 도달한다(긴 검색어와 공존)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 80,
        .rows = 24,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    const pane = pane_ops.activePane(session);
    const md = try web_ops.createWebTerm(session, .markdown);
    try pane.terms.append(allocator, md);
    term_ops.focusTerm(session, pane.terms.items.len - 1);

    session.dispatchAppAction(.toggle_find);
    _ = try session.tick(); // 실사용 순서 — 여는 프레임의 tick이 대상을 페이지로 정한다
    // 패널을 꽉 채우는 긴 검색어 — 꼬리가 오른쪽 끝(카운터 자리)까지 밀려온다. 마지막 글자는 유니크 'Z'로
    // 둬서, 예약이 모자라 카운터가 그 위에 겹쳐 그려지면 셀에서 사라지게 한다.
    for (0..200) |_| _ = chrome.components.find.handle(allocator, .{ .key = .char, .codepoint = 'a' }, &session.chrome_host.find);
    _ = chrome.components.find.handle(allocator, .{ .key = .char, .codepoint = 'Z' }, &session.chrome_host.find);
    session.dispatchChromeAction(.find_query_changed);
    const req = web_ops.takeWebFindQuery(session) orelse return error.TestExpectedWebFindRequest;
    web_ops.provideWebFindResult(session, req.seq, true);
    try std.testing.expectEqual(chrome.components.find.Target.page, session.chrome_host.find.target); // 전제

    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();
    const tk = session.buildChromeTokens();
    const props = session.buildChromeProps();
    var draws: std.ArrayList(chrome.ChromeDraw) = .empty;
    try session.chrome_host.collectDraws(props, &tk, arena, &draws);

    var raster = try AppSession.rasterizeOverlayCells(allocator, draws.items, &tk, session.cell_width_px, session.cell_height_px, false);
    defer {
        raster.cells.deinit(allocator);
        raster.gpu_quads.deinit(allocator);
        raster.gpu_shadows.deinit(allocator);
    }

    // vacuity 가드부터: 오버레이 자체가 그려졌는지(프롬프트 'F') 먼저 본다.
    var has_prompt = false;
    for (raster.cells.items) |c| {
        if (c.codepoint == 'F') has_prompt = true;
    }
    try std.testing.expect(has_prompt);
    // 카운터("found")도, 방금 친 마지막 글자('Z')도 살아 있어야 한다 — 예약이 맞으면 둘은 겹치지 않는다.
    // find 오버레이는 **영어 고정**이라(계약 §2.1) 여기 글자도 영어다.
    var it = (std.unicode.Utf8View.init("foundZ") catch unreachable).iterator();
    while (it.nextCodepoint()) |cp| {
        var found = false;
        for (raster.cells.items) |c| {
            if (c.codepoint == cp) {
                found = true;
                break;
            }
        }
        if (!found) {
            std.debug.print("\n코드포인트 U+{X}가 셀에 없다(표시기·검색어 꼬리 중 하나가 유실 — 총 {d}칸)\n", .{ cp, raster.cells.items.len });
            return error.TestUnexpectedResult;
        }
    }
}

// WP-F1 적대적 R8 프로브: **오버레이의 Enter/Shift+Enter가 웹 탭에서도 다음/이전 매치로 가야 한다.** ⌘G만
// 라우팅하고 Enter를 두면, 검색창 안에서 가장 흔한 조작이 웹 탭에서만 죽는다(터미널 스크롤만 시도하고 끝난다).
test "WP-F1 R8 프로브: 웹 탭에서 Enter/Shift+Enter가 페이지 다음·이전으로 나간다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 80,
        .rows = 24,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    const pane = pane_ops.activePane(session);
    const md = try web_ops.createWebTerm(session, .markdown);
    try pane.terms.append(allocator, md);
    term_ops.focusTerm(session, pane.terms.items.len - 1);

    session.dispatchAppAction(.toggle_find);
    for ("ab") |c| _ = try session.handleKeyEvent(.{ .key = .{ .char = c }, .modifiers = .{} });
    _ = web_ops.takeWebFindQuery(session); // 타이핑이 낸 질의는 걷어 낸다

    // Enter = 다음 매치.
    _ = try session.handleKeyEvent(.{ .key = .enter, .modifiers = .{} });
    const next = web_ops.takeWebFindQuery(session) orelse return error.TestExpectedWebFindRequest;
    try std.testing.expectEqualStrings("ab", next.query);
    try std.testing.expect(!next.backwards);

    // Shift+Enter = 이전 매치.
    _ = try session.handleKeyEvent(.{ .key = .enter, .modifiers = .{ .shift = true } });
    const prev = web_ops.takeWebFindQuery(session) orelse return error.TestExpectedWebFindRequest;
    try std.testing.expect(prev.backwards);
}

// WP-F1 적대적 R7 프로브: **닫아 둔 find가 화면을 움직이면 안 된다.** 대상 동기화를 열림 게이트 밖으로 뺀 뒤
// (R6), 터미널 복귀 재검색이 닫힌 상태에서도 돌면 `recomputeFind`가 `scrollToCurrentMatch`까지 부른다 — 사용자는
// 검색창을 닫아 놨는데 탭만 돌아와도 화면이 첫 매치로 점프한다.
test "WP-F1 R7 프로브: 닫아 둔 find는 탭 복귀로 화면을 스크롤하지 않는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 80,
        .rows = 6,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    // 스크롤백을 만들고(뷰포트보다 길게) 맨 위쪽에 검색어를 둔다 — 스크롤이 일어나면 view_offset이 변한다.
    try term_ops.activeSurface(session).core.write("MARUFIND top\r\n");
    for (0..60) |_| try term_ops.activeSurface(session).core.write("filler line\r\n");

    session.dispatchAppAction(.toggle_find);
    for ("MARUFIND") |c| _ = try session.handleKeyEvent(.{ .key = .{ .char = c }, .modifiers = .{} });
    session.dispatchAppAction(.toggle_find); // 닫는다
    try std.testing.expect(!session.chrome_host.find.open);

    // 닫은 뒤 사용자가 스크롤 위치를 정해 둔다(맨 아래).
    term_ops.activeSurface(session).core.scrollToBottom();
    const offset_before = term_ops.activeSurface(session).core.viewOffset();

    // 마크다운 탭에 들렀다 돌아온다 — 닫혀 있으므로 화면은 그대로여야 한다.
    const pane = pane_ops.activePane(session);
    const md = try web_ops.createWebTerm(session, .markdown);
    try pane.terms.append(allocator, md);
    term_ops.focusTerm(session, pane.terms.items.len - 1);
    _ = try session.tick();
    term_ops.focusTerm(session, 0);
    _ = try session.tick();

    try std.testing.expectEqual(offset_before, term_ops.activeSurface(session).core.viewOffset());
}

// WP-F1 적대적 R6 프로브: **닫힌 동안 탭이 바뀌어도 대상이 굳으면 안 된다.** 대상 동기화가 "열려 있을 때"에만
// 돌면, 웹 탭에서 닫고 터미널로 옮긴 뒤 다시 열었을 때 첫 프레임이 페이지 모드로 그려진다(카운터가 통째로 빈다).
test "WP-F1 R6 프로브: 닫힌 동안 탭이 바뀌어도 대상이 따라온다" {
