// WP-F1 적대적 R4 프로브: (a) 늦은 결과가 **남의 탭 카운터**에 붙으면 안 된다. (b) ⌘⇧G의 역방향이 실제로 나가야 한다.
test "WP-F1 R4 프로브: 결과는 제출한 탭에만 붙고, 역방향이 전달된다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 80,
        .rows = 24,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    const pane = pane_ops.activePane(session);
    const a = try web_ops.createWebTerm(session, .markdown);
    try pane.terms.append(allocator, a);
    const a_idx = pane.terms.items.len - 1;
    const b = try web_ops.createWebTerm(session, .markdown);
    try pane.terms.append(allocator, b);
    const b_idx = pane.terms.items.len - 1;

    // (b) 역방향: ⌘⇧G가 backwards=true로 나간다.
    term_ops.focusTerm(session, a_idx);
    session.dispatchAppAction(.toggle_find);
    _ = chrome.components.find.handle(allocator, .{ .key = .char, .codepoint = 'a' }, &session.chrome_host.find);
    session.dispatchChromeAction(.find_query_changed);
    const fwd = web_ops.takeWebFindQuery(session) orelse return error.TestExpectedWebFindRequest;
    try std.testing.expect(!fwd.backwards);
    session.dispatchAppAction(.find_previous);
    const back = web_ops.takeWebFindQuery(session) orelse return error.TestExpectedWebFindRequest;
    try std.testing.expect(back.backwards);

    // (a) A의 결과가 오기 전에 B로 전환한다. 그 뒤 도착한 **A의 답**을 B 화면에 붙이면 안 된다.
    term_ops.focusTerm(session, b_idx);
    web_ops.provideWebFindResult(session, back.seq, true); // seq는 아직 유효(B 재제출 전) — 그래도 A의 답이다
    try std.testing.expect(session.chrome_host.find.page_found == null);
}

// WP-F1 적대적 R3: **Swift가 전달하지 못한 질의는 되살아나야 한다.** 방금 만든 웹 탭은 WKWebView가 아직
// 없어 drain이 질의를 걸지 못한다. 그때 그냥 버리면 Zig의 제출 마커가 "보냈다"로 남아 tick이 재시도하지
// 않고, 그 탭의 검색은 **영영 나가지 않는다**(조용한 죽음). 미전달 신고가 마커를 지워 다음 tick이 다시 낸다.
test "WP-F1: 전달 실패를 신고하면 다음 tick이 다시 낸다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 80,
        .rows = 24,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    const pane = pane_ops.activePane(session);
    const md = try web_ops.createWebTerm(session, .markdown);
    try pane.terms.append(allocator, md);
    term_ops.focusTerm(session, pane.terms.items.len - 1);

    session.dispatchAppAction(.toggle_find);
    _ = chrome.components.find.handle(allocator, .{ .key = .char, .codepoint = 'a' }, &session.chrome_host.find);
    session.dispatchChromeAction(.find_query_changed);
    const first = web_ops.takeWebFindQuery(session) orelse return error.TestExpectedWebFindRequest;

    // Swift가 못 걸었다 — 신고 없이는 다음 tick이 조용하다(이 대비가 이 테스트의 요점이다).
    _ = try session.tick();
    try std.testing.expect(web_ops.takeWebFindQuery(session) == null);

    web_ops.reportWebFindUndeliverable(session, first.seq);
    _ = try session.tick();
    const again = web_ops.takeWebFindQuery(session) orelse return error.TestExpectedWebFindRequest;
    try std.testing.expectEqualStrings("a", again.query);
    try std.testing.expectEqual(first.surface_id, again.surface_id);

    // 늦은 신고(그 사이 새 질의가 나갔다)는 무시한다 — 아니면 이미 유효한 제출을 되돌려 무한 재제출이 된다.
    web_ops.reportWebFindUndeliverable(session, first.seq);
    _ = try session.tick();
    try std.testing.expect(web_ops.takeWebFindQuery(session) == null);
}

// WP-F1 적대적 R2 프로브: 웹 탭 A에서 찾은 뒤 **웹 탭 B로 옮기면** B도 검색돼야 한다.
test "WP-F1 R2 프로브: 다른 웹 탭으로 옮기면 그 탭에도 질의가 나간다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 80,
        .rows = 24,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    const pane = pane_ops.activePane(session);
    const a = try web_ops.createWebTerm(session, .markdown);
    try pane.terms.append(allocator, a);
    const a_idx = pane.terms.items.len - 1;
    const b = try web_ops.createWebTerm(session, .markdown);
    try pane.terms.append(allocator, b);
    const b_idx = pane.terms.items.len - 1;

    term_ops.focusTerm(session, a_idx);
    session.dispatchAppAction(.toggle_find);
    _ = chrome.components.find.handle(allocator, .{ .key = .char, .codepoint = 'a' }, &session.chrome_host.find);
    session.dispatchChromeAction(.find_query_changed);
    const ra = web_ops.takeWebFindQuery(session) orelse return error.TestExpectedWebFindRequest;
    const sid_a = ra.surface_id;
    web_ops.provideWebFindResult(session, ra.seq, true); // A는 찾음

    // B로 전환. 같은 검색어를 그 탭에서도 찾아야 한다.
    term_ops.focusTerm(session, b_idx);
    _ = try session.tick();
    const rb = web_ops.takeWebFindQuery(session) orelse return error.TestExpectedWebFindRequest;
    try std.testing.expect(rb.surface_id != sid_a); // A가 아니라 B로 간다
    try std.testing.expectEqualStrings("a", rb.query);

    // 반대편도 지켜야 한다: **같은 탭·같은 검색어면 다시 보내지 않는다.** 매 tick 재제출하면 WebKit
    // 하이라이트가 프레임마다 첫 매치로 튄다(조건을 없애는 것은 고침이 아니다).
    web_ops.provideWebFindResult(session, rb.seq, true);
    _ = try session.tick();
    _ = try session.tick();
    try std.testing.expect(web_ops.takeWebFindQuery(session) == null);

    // 그리고 검색어가 바뀌면 같은 탭이라도 다시 보낸다.
    _ = chrome.components.find.handle(allocator, .{ .key = .char, .codepoint = 'b' }, &session.chrome_host.find);
    _ = try session.tick();
    const rc = web_ops.takeWebFindQuery(session) orelse return error.TestExpectedWebFindRequest;
    try std.testing.expectEqualStrings("ab", rc.query);
}

// WP-F1 적대적 R1: **오버레이가 거짓말을 하면 안 된다.** WebKit이 페이지를 노랗게 하이라이트했는데 카운터가
// "0/0"이면 사용자는 "못 찾았다"로 읽는다 — 화면과 정면으로 모순된다. `WKFindResult`는 개수를 안 주므로
// (§8) 그 자리에 **찾음/없음**을 낸다. 결과가 오기 전에는 아무것도 안 낸다(빈 자리 < 틀린 숫자).
test "WP-F1: 웹 탭 카운터는 0/0이 아니라 found/none이다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 80,
        .rows = 24,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    const pane = pane_ops.activePane(session);
    const md = try web_ops.createWebTerm(session, .markdown);
    try pane.terms.append(allocator, md);
    term_ops.focusTerm(session, pane.terms.items.len - 1);

    session.dispatchAppAction(.toggle_find);
    _ = try session.tick();
    try std.testing.expectEqual(chrome.components.find.Target.page, session.chrome_host.find.target);

    // 결과 전 — 그릴 것이 없다(빈 자리). 그림 자체로 확인한다: 카운터 op가 없어야 한다.
    try std.testing.expect(session.chrome_host.find.page_found == null);
    try std.testing.expect(!(try findOverlayHasText(allocator, session, "0/0")));

    // 찾음/없음이 실제로 **그려진다**(상태만 보면 view가 무시해도 통과한다).
    _ = chrome.components.find.handle(allocator, .{ .key = .char, .codepoint = 'a' }, &session.chrome_host.find);
    session.dispatchChromeAction(.find_query_changed);
    const req = web_ops.takeWebFindQuery(session) orelse return error.TestExpectedWebFindRequest;
    web_ops.provideWebFindResult(session, req.seq, true);
    try std.testing.expect(try findOverlayHasText(allocator, session, "found")); // find 오버레이는 영어 고정(계약 §2.1)
    try std.testing.expect(!(try findOverlayHasText(allocator, session, "0/0")));

    web_ops.provideWebFindResult(session, req.seq, false);
    try std.testing.expect(try findOverlayHasText(allocator, session, "none")); // find 오버레이는 영어 고정(계약 §2.1)

    // 터미널로 돌아오면 다시 숫자 카운터다(페이지 답이 남지 않는다).
    term_ops.focusTerm(session, 0);
    _ = try session.tick();
    try std.testing.expectEqual(chrome.components.find.Target.scrollback, session.chrome_host.find.target);
    try std.testing.expect(session.chrome_host.find.page_found == null);
    // 숫자 카운터로 돌아온다("/"는 이 오버레이에서 카운터에만 나온다 — 프롬프트는 "Find: ", 검색어는 "a").
    // 정확한 숫자는 단언하지 않는다: 돌아오면서 **실제로 재검색**하므로(R5) 셸 출력에 'a'가 있으면 0이 아니다.
    try std.testing.expect(try findOverlayHasText(allocator, session, "/"));
    try std.testing.expect(!(try findOverlayHasText(allocator, session, "found")));
    try std.testing.expect(!(try findOverlayHasText(allocator, session, "none")));
}

/// 오버레이를 **실제 렌더 경로**(buildChromeOverlayFrame과 같은 collectDraws)로 그려 `needle` 텍스트가 나오는지
/// 본다 — 상태만 단언하면 view가 그 상태를 무시해도 통과하므로(그리는 것이 계약이다) 그림을 본다.
fn findOverlayHasText(allocator: std.mem.Allocator, session: *AppSession, needle: []const u8) !bool {
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();
    const tk = session.buildChromeTokens();
    const props = session.buildChromeProps();
    var draws: std.ArrayList(chrome.ChromeDraw) = .empty;
    try session.chrome_host.collectDraws(props, &tk, arena, &draws);
    for (draws.items) |d| {
        for (d.ops) |op| {
            const t = switch (op) {
                .text => |tx| tx,
                else => continue,
            };
            for (t.runs) |run| {
                if (std.mem.indexOf(u8, run.text, needle) != null) return true;
            }
        }
    }
    return false;
}

// WP-F1 적대적: **게이트가 종류를 빠뜨리거나 남의 탭을 보면 안 된다.** 판정이 `activeWebSurfaceIdAnyKind`라
// browser도 막혀야 하고(제보는 마크다운이었지만 같은 문제다), **웹 탭이 열려 있어도 활성이 터미널이면**
// 평소처럼 열려야 한다 — 후자를 놓치면 "웹 탭 하나 열어 두면 터미널에서 ⌘F가 죽는" 더 나쁜 회귀가 된다.
// N1: 편집기 Term은 **문서·줄 슬라이스·경로 셋**을 소유한다. 셋 중 하나라도 `destroyTerm`이 놓지
// 않으면 파일을 열 때마다 샌다 — `std.testing.allocator`가 그것을 잡는다.
//
// **`destroyTerm`을 직접 부르지 않는다.** 그러면 "release가 있으면 통과"만 보게 되고, 실제 teardown
// 경로(세션 deinit → pane → term)가 편집기를 빠뜨려도 초록이 된다. 세션을 그냥 닫아 그 경로를 태운다.
test "N1: 편집기 Term을 열고 세션을 닫으면 문서·줄·경로가 전부 해제된다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const io = std.Io.Threaded.global_single_threaded.io();

    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    try tmp.dir.writeFile(io, .{ .sub_path = "s.txt", .data = "one\ntwo\nthree\n" });
    var root_buf: [std.fs.max_path_bytes]u8 = undefined;
    const root = root_buf[0..try tmp.dir.realPath(io, &root_buf)];
    const path = try std.fs.path.join(allocator, &.{ root, "s.txt" });
    defer allocator.free(path);

    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(io, allocator, .{
        .abi_version = abi_version,
        .cols = 80,
        .rows = 24,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    const term = try editor_ops.openPathInActivePane(session, path);
    try std.testing.expectEqual(control_surface.SurfaceKind.editor, term.kind);
    try std.testing.expectEqual(@as(usize, 4), term.rt.editor_lines.len); // 끝 개행이 만든 빈 줄까지
    try std.testing.expect(term.rt.editor_doc != null);
    try std.testing.expectEqualStrings(path, term.rt.editor_path.?);
    // 누수 판정은 `defer session.deinit()`과 testing.allocator가 한다.
}

// 편집기 Term은 sentinel core라 cwd/git/at_prompt를 읽으면 안 되고, wire에 `kind: "editor"`로 나가야
// 한다. 이 단언이 없으면 collector가 편집기를 terminal 경로로 흘려도(실제로 그랬다) 아무도 모른다.
test "N1: 컨트롤 플레인이 편집기를 editor detail로 낸다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const io = std.Io.Threaded.global_single_threaded.io();

    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    try tmp.dir.writeFile(io, .{ .sub_path = "w.txt", .data = "x\n" });
    var root_buf: [std.fs.max_path_bytes]u8 = undefined;
    const root = root_buf[0..try tmp.dir.realPath(io, &root_buf)];
    const path = try std.fs.path.join(allocator, &.{ root, "w.txt" });
    defer allocator.free(path);

    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(io, allocator, .{
        .abi_version = abi_version,
        .cols = 80,
        .rows = 24,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);
    _ = try editor_ops.openPathInActivePane(session, path);

    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    // **리스트도 arena가 회수한다** — collector가 arena로 append하므로 여기서 testing.allocator로
    // 놓으면 남의 메모리를 free한다(적대적 검증에서 `Invalid free`로 잡혔다).
    var surfaces: std.ArrayList(control_surface.SurfaceDto) = .empty;
    var windows: std.ArrayList(maru.session.WindowMembershipSnapshot) = .empty;
    try session.collectSessionInto(arena_state.allocator(), 0, .normal, &surfaces, &windows);

    var seen: usize = 0;
    for (surfaces.items) |dto| {
        if (dto.detail != .editor) continue;
        seen += 1;
        try std.testing.expectEqualStrings(path, dto.detail.editor.path.?);
        try std.testing.expect(!dto.detail.editor.read_only);
    }
    try std.testing.expectEqual(@as(usize, 1), seen);
}

test "WP-F1: browser도 페이지 검색으로 가고, 활성이 터미널이면 스크롤백 검색이다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 80,
        .rows = 24,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    const pane = pane_ops.activePane(session);
    const br = try web_ops.createWebTerm(session, .browser);
    try pane.terms.append(allocator, br);
    term_ops.focusTerm(session, pane.terms.items.len - 1);

    session.dispatchAppAction(.toggle_find);
    // 슬라이스 ② 이후: browser에서도 **열린다** — 다만 대상이 페이지다. 열린 뒤 tick이 돌면
    // 터미널 매치는 비고 질의는 Swift로 넘어간다.
    try std.testing.expect(session.chrome_host.find.open);
    _ = try session.tick();
    try std.testing.expectEqual(@as(usize, 0), session.find_matches.items.len);

    // 웹 탭은 그대로 두고 활성만 터미널(0번)로 되돌린다.
    term_ops.focusTerm(session, 0);
    try std.testing.expectEqual(@as(u64, 0), web_ops.activeWebSurfaceIdAnyKind(session)); // 전제

    // 전환만으로 닫히지 않는다 — 같은 오버레이가 이제 스크롤백을 본다.
    try std.testing.expect(session.chrome_host.find.open);
    session.dispatchAppAction(.toggle_find);
    try std.testing.expect(!session.chrome_host.find.open); // 토글은 여전히 토글이다
    session.dispatchAppAction(.toggle_find);
    try std.testing.expect(session.chrome_host.find.open); // 터미널에서는 평소대로 열린다
    try std.testing.expect(web_ops.takeWebFindQuery(session) == null); // 터미널 활성이면 페이지로 안 나간다
}

// WP-F1 적대적: **⌘G(find_next)는 게이트가 없다.** ⌘F만 막고 ⌘G를 두면, 터미널에서 검색어를 남긴 뒤
// 웹 탭으로 옮겨 ⌘G를 누르는 경로가 남는다 — 그때 `findNavigate`가 **웹 term의 core**를 검색한다.
// 잘못된 UI를 열지는 않지만(무동작), 그 경로가 안전한지(크래시·엉뚱한 스크롤 없음)는 밟아 봐야 안다.
test "WP-F1: 웹 탭에서 ⌘G는 터미널 검색어로 엉뚱한 동작을 하지 않는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 80,
        .rows = 24,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    // 터미널에서 검색어를 남긴다(⌘G가 보존 검색어로 재검색하는 경로).
    session.dispatchAppAction(.toggle_find);
    try session.chrome_host.find.input.appendChar(allocator, 'a');
    session.dispatchAppAction(.toggle_find); // 닫아도 검색어는 남는다

    const pane = pane_ops.activePane(session);
    const md = try web_ops.createWebTerm(session, .markdown);
    try pane.terms.append(allocator, md);
    term_ops.focusTerm(session, pane.terms.items.len - 1);

    // 크래시하지 않고, find 오버레이가 열리지도 않는다.
    session.dispatchAppAction(.find_next);
    session.dispatchAppAction(.find_previous);
    try std.testing.expect(!session.chrome_host.find.open);
}

// WP-F1: **웹 탭에서 ⌘F가 스크롤백 find를 열면 안 된다.** 그 오버레이는 터미널 스크롤백만 검색하므로,
// 마크다운 뷰어에서 열리면 우상단에 검색창이 뜨는데 페이지는 검색되지 않는다(사용자 제보).
// 판정 기준이 `activeWebSurfaceIdAnyKind`인 것이 핵심이다 — browser 전용 함수를 쓰면 **마크다운이 빠져**
// 제보된 그 버그가 그대로 남는다(docs/web-panel-features.md §8).
test "WP-F1: 마크다운 웹 탭에서 ⌘F 검색어가 그 탭의 페이지로 나간다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 80,
        .rows = 24,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    // 터미널 탭에서는 그대로 열린다(회귀 방지 — 이 수정이 기존 동작을 깨면 안 된다).
    session.dispatchAppAction(.toggle_find);
    try std.testing.expect(session.chrome_host.find.open);
    session.dispatchAppAction(.toggle_find);
    try std.testing.expect(!session.chrome_host.find.open);

    // 마크다운 웹 탭으로 옮기면 **열리고, 검색어가 페이지로 나간다**(제보된 버그의 회귀 테스트).
    const pane = pane_ops.activePane(session);
    const md = try web_ops.createWebTerm(session, .markdown);
    try pane.terms.append(allocator, md);
    term_ops.focusTerm(session, pane.terms.items.len - 1);
    const sid = web_ops.activeWebSurfaceIdAnyKind(session);
    try std.testing.expect(sid != 0); // 전제

    session.dispatchAppAction(.toggle_find);
    try std.testing.expect(session.chrome_host.find.open);

    // 타이핑 한 글자 = find_query_changed → 페이지 질의 제출.
    _ = chrome.components.find.handle(allocator, .{ .key = .char, .codepoint = 'a' }, &session.chrome_host.find);
    session.dispatchChromeAction(.find_query_changed);

    // peek은 **소비하지 않는다** — ABI 래퍼가 out 용량을 소비 전에 검사할 때 쓰는 계약이다(용량이 모자라
    // 0으로 빠져도 질의는 살아 있어야 한다. 삼키면 그 검색은 영영 안 나간다).
    try std.testing.expectEqual(@as(usize, 1), web_ops.peekWebFindQueryLen(session).?);
    try std.testing.expectEqual(@as(usize, 1), web_ops.peekWebFindQueryLen(session).?);

    const req = web_ops.takeWebFindQuery(session) orelse return error.TestExpectedWebFindRequest;
    try std.testing.expectEqualStrings("a", req.query);
    try std.testing.expectEqual(sid, req.surface_id); // 활성 웹 탭으로 간다
    try std.testing.expect(!req.backwards);
    try std.testing.expect(web_ops.takeWebFindQuery(session) == null); // 1회성
    // 스크롤백은 검색하지 않는다.
    try std.testing.expectEqual(@as(usize, 0), session.find_matches.items.len);
}

// SB1: **요청 중에 상태바가 사라지면 메뉴를 띄우면 안 된다.** 목록 읽기는 비동기라, 그 사이 사용자가
// `status-bar.show`를 끄거나 quick terminal로 바뀌면 **클릭한 대상이 화면에서 없어진다.** 그때 결과가
// 도착해 메뉴를 열면 앵커가 없어 창 바닥에 붙고, 사용자는 누른 적 없는 메뉴를 보게 된다.
// SB-R: 리소스 항목은 **두 번째 표본부터** 뜬다. 첫 표본엔 CPU%를 낼 수 없고(차분이라 기준선이 없다),
// 메모리만 먼저 그리면 폭이 변해 좌측 경로가 매초 흔들린다(docs/status-bar.md §6 "표시 폭은 고정한다").
test "SB-R: 리소스 항목은 첫 표본에 안 뜨고 두 번째 표본부터 뜬다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 80,
        .rows = 24,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    try std.testing.expect(session.resourceText() == null); // 아직 아무 표본도 없다

    // 실 프로세스 표본은 시각마다 다르므로 **Meter를 직접** 태운다(순수 계약을 여기서 다시 검증하지 않고,
    // 세션이 그 결과를 문자열·재렌더로 이어 붙이는지만 본다).
    const ru = maru.session.resource_usage;
    try std.testing.expect(session.resource_meter.update(allocator, &.{
        .{ .pid = 1, .footprint_bytes = 512 * 1024 * 1024, .cpu_ns = 0 },
    }, 1_000) == null); // 첫 표본 — 값 없음

    const reading = session.resource_meter.update(allocator, &.{
        .{ .pid = 1, .footprint_bytes = 512 * 1024 * 1024, .cpu_ns = 100_000_000 },
    }, 2_000) orelse return error.TestExpectedReading;
    try std.testing.expectEqual(@as(u64, 100), reading.cpu_permille);

    // 세션이 그 값을 표시 문자열로 들고 있게 한다(pollResourceUsage의 뒷부분과 같은 계약).
    var buf: [ru.text_max_bytes]u8 = undefined;
    const text = ru.format(&buf, reading);
    @memcpy(session.resource_text_buf[0..text.len], text);
    session.resource_text_len = text.len;
    const shown = session.resourceText() orelse return error.TestExpectedText;
    try std.testing.expectEqualStrings("  512 MB ·   10%", shown);

    // 상태바가 실제로 그 항목을 **그린다**(상태만 보면 렌더가 무시해도 통과한다).
    try std.testing.expect(try statusBarHasText(allocator, session, "512 MB"));
}

// SB-A: 앱 자신 표본이 **실제 폴링 경로**에서 합계에 들어가고 자기 행을 갖는다. 위 SB-A가 팝오버 배치를
// 봤다면 이건 **값의 출처**를 본다 — 행만 있고 합계에 안 들어가면 "왜 활성 모니터와 다른가"에 여전히 못 답한다.
test "SB-A: 폴링이 앱 자신을 표본에 넣고 합계에 반영한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 80,
        .rows = 24,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);
    try std.testing.expect(session.statusBarHeightPx() > 0); // 전제: 게이트가 열려 있다

    // 두 번 재야 CPU 차분이 나온다(첫 표본은 값 없음). 주기 도달을 강제한다.
    // **사이를 띄운다** — 두 폴링이 같은 밀리초에 들어가면 `gap_ms == 0`이라 Meter가 나눌 수 없어
    // null을 돌려주고, 이 테스트는 기능이 멀쩡해도 실패한다(첫 작성에서 실제로 그렇게 실패했다).
    session.resource_poll_ticks = std.math.maxInt(u32) / 2;
    session.pollResourceUsage();
    const start_ms = monotonicMs();
    while (monotonicMs() -| start_ms < 5) _ = usleep(1_000); // 파일 상단 extern 선언 재사용(std에 Thread.sleep 없음)
    session.resource_poll_ticks = std.math.maxInt(u32) / 2;
    session.pollResourceUsage();

    // 앱 행이 **자기 그룹**으로 서 있다. 이 스모크 세션에는 산 터미널이 없으므로 앱이 유일한 행이다 —
    // 즉 예전 규칙("터미널이 없으면 항목 없음")이 뒤집혔다는 것도 함께 고정한다(§4.1).
    var app_row: ?maru.session.resource_usage.GroupReading = null;
    for (session.resource_rows[0..session.resource_rows_len]) |row| {
        if (row.key == resource_app_key) app_row = row;
    }
    const row = app_row orelse return error.TestExpectedAppRow;
    const app_reading = row.reading orelse return error.TestExpectedAppReading;
    try std.testing.expect(app_reading.footprint_bytes > 0); // 우리 프로세스는 메모리를 쓴다

    // 그리고 그 값이 **합계에 들어간다** — 합계가 앱 행보다 작을 수 없다.
    const total = session.resource_reading orelse return error.TestExpectedTotal;
    try std.testing.expect(total.footprint_bytes >= app_reading.footprint_bytes);
}

// SB-R 적대적: **표시가 그대로면 다시 그리지 않는다.** 원값은 매초 흔들리지만 표시 문자열이 같으면
// 재렌더할 이유가 없다 — 초당 전체 프레임을 다시 그리는 비용은 배터리에 그대로 실린다.
test "SB-R: 같은 표시가 나오면 metal_dirty를 세우지 않는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 80,
        .rows = 24,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    // 기준선 + 값 하나를 만든다.
    session.resource_poll_ticks = std.math.maxInt(u32) / 2;
    session.pollResourceUsage();
    var spin: u64 = monotonicMs();
    while (monotonicMs() == spin) spin = monotonicMs();
    session.resource_poll_ticks = std.math.maxInt(u32) / 2;
    session.pollResourceUsage();
    const first = session.resourceText() orelse return error.TestExpectedResourceText;

    // 같은 표시가 다시 나오는 상황을 만든다 — 표시 문자열을 그대로 두고 폴링을 한 번 더 돌린다.
    // (실 표본이 조금 달라도 반올림 뒤 같은 글자면 재렌더가 없어야 한다.)
    var kept: [maru.session.resource_usage.text_max_bytes]u8 = undefined;
    @memcpy(kept[0..first.len], first);
    const kept_len = first.len;

    session.metal_dirty = false;
    spin = monotonicMs();
    while (monotonicMs() == spin) spin = monotonicMs();
    session.resource_poll_ticks = std.math.maxInt(u32) / 2;
    session.pollResourceUsage();

    const now = session.resourceText() orelse return error.TestExpectedResourceText;
    if (now.len == kept_len and std.mem.eql(u8, now, kept[0..kept_len])) {
        // 글자가 같다 → 재렌더 없음이 계약이다.
        try std.testing.expect(!session.metal_dirty);
    } else {
        // 글자가 바뀌었다면 재렌더가 **있어야** 한다(반대 방향도 계약이다).
        try std.testing.expect(session.metal_dirty);
    }
}

// SB-A: 앱 자신은 **합계에 들어가고**, 팝오버에서는 정렬 밖 **맨 아래 고정 행**이며 **고를 수 없다**(§4.1).
// 세 성질이 함께 있어야 의미가 있다 — 합계에만 넣고 행을 안 보이면 "왜 커졌나"에 답하지 못하고, 행을
// 정렬에 섞으면 값에 따라 떠다니다 상한에 잘려 사라진다.
test "SB-A: 앱 행은 무거운 순 정렬 밖에서 맨 아래 고정이고 선택 대상이 아니다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 80,
        .rows = 24,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // 기대값이 한국어 문장이라 언어를 고정한다. **`init` 뒤**여야 한다 — init 이 `ui.language` 를 읽어
    // 언어를 세우므로 앞에 걸면 조용히 지워진다.
    const lang_before = maru.i18n.lang();
    defer maru.i18n.setLang(lang_before);
    maru.i18n.setLang(.ko);
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    // 앱 행을 **가장 무겁게** 심는다. 정렬에 섞였다면 맨 위로 올라올 값이다 — 그런데 맨 아래여야 한다.
    session.resource_rows[0] = .{ .key = resource_app_key, .reading = .{ .footprint_bytes = 9_000_000, .cpu_permille = 5 } };
    session.resource_rows[1] = .{ .key = 111, .reading = .{ .footprint_bytes = 10, .cpu_permille = 0 } };
    session.resource_rows[2] = .{ .key = 222, .reading = .{ .footprint_bytes = 900, .cpu_permille = 0 } };
    session.resource_rows_len = 3;

    const text = "  512 MB ·   10%";
    @memcpy(session.resource_text_buf[0..text.len], text);
    session.resource_text_len = text.len;
    try std.testing.expect(try statusBarHasText(allocator, session, "512"));

    session.openResourceMenu();
    try std.testing.expect(session.resource_menu_open);
    try std.testing.expectEqual(@as(usize, 3), session.resource_menu_len);
    // 탭은 무거운 순(222 → 111), 앱은 **그 뒤**다.
    try std.testing.expectEqual(@as(u64, 222), session.resource_menu_keys[0]);
    try std.testing.expectEqual(@as(u64, 111), session.resource_menu_keys[1]);
    try std.testing.expectEqual(resource_app_key, session.resource_menu_keys[2]);

    // 컴포넌트가 꼬리를 **고를 수 없는 줄**로 안다. 꼬리 수는 **실제로 선 고정 행 수**이지 버퍼 상수가
    // 아니다 — 이 픽스처에는 앱 행만 있으므로 1이다. 상수(2)를 넘기면 살아 있는 탭 행 하나가 통째로
    // 선택 불가가 되고, 화면에서는 "그 줄만 안 눌린다"로만 보여 원인을 못 찾는다.
    const menu = &session.chrome_host.context_menu;
    try std.testing.expectEqual(@as(usize, 1), menu.footer_count);
    const last = resource_header_rows + session.resource_menu_len - 1;
    try std.testing.expect(!menu.selectable(last)); // 앱 행
    try std.testing.expect(menu.selectable(last - 1)); // 그 위 탭 행은 고를 수 있다
    // 키보드로도 못 내려간다 — 아무리 눌러도 마지막 **고를 수 있는** 줄에서 멈춘다.
    menu.moveSelection(99);
    try std.testing.expect(menu.selectable(menu.selected));
    try std.testing.expectEqual(last - 1, menu.selected);

    // 행 문자열에 "모든 창 공유"가 박혀 있다 — 창이 여럿일 때 더하면 안 된다는 사실이 화면에 있어야 한다.
    try std.testing.expect(std.mem.indexOf(u8, session.context_menu_items_buf[last], "모든 창 공유") != null);
    // 그리고 그 행은 제목 버퍼를 침범하지 않는다(행 슬롯과 머리글 슬롯이 갈려 있다).
    try std.testing.expect(std.mem.indexOf(u8, session.context_menu_items_buf[0], maru.i18n.t(.col_resource)) != null);
}

// SB-T: 팝오버 **머리글의 합계**와 상태바 띠의 합계는 **같은 값**이어야 한다(§4.2). 두 숫자를 두 곳에
// 두면 어느 쪽이 맞는지 물어야 하기 때문이다. 옛 순서는 행을 먼저 다시 그리고 표시 문자열을 나중에
// 갱신해서 머리글만 한 tick 뒤처졌고, 총합이 느리게 움직이는 동안에는 대개 같아 보여 안 드러났다 —
// 세션 호스트가 합계에 들어오면서 실측 캡처에서 **머리글 516 MB vs 띠 532 MB**로 벌어졌다.
test "SB-T: 팝오버 머리글 합계는 상태바 띠와 같은 tick의 값이다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 80,
        .rows = 24,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);
    try std.testing.expect(session.statusBarHeightPx() > 0);

    // 두 번 재야 CPU 차분이 나온다(첫 표본은 값 없음). 사이를 띄우지 않으면 `gap_ms == 0`이라
    // Meter가 나눌 수 없어 기능이 멀쩡해도 실패한다(SB-A가 같은 이유로 그렇게 적혀 있다).
    session.resource_poll_ticks = std.math.maxInt(u32) / 2;
    session.pollResourceUsage();
    const start_ms = monotonicMs();
    while (monotonicMs() -| start_ms < 5) _ = usleep(1_000);
    session.resource_poll_ticks = std.math.maxInt(u32) / 2;
    session.pollResourceUsage();
    try std.testing.expect(session.resource_text_len > 0);

    // **앵커는 렌더 경로가 발행한다** — `statusBarTree()`는 읽기만 하므로 한 번 그려야 rect 가 생기고,
    // 그래야 `openResourceMenu`가 연다(SB-H 가 같은 이유로 먼저 그린다). 값이 실측이라 문자열을 미리
    // 알 수 없으니 리소스 항목이 반드시 갖는 `%` 로 확인한다.
    try std.testing.expect(try statusBarHasText(allocator, session, "%"));

    session.openResourceMenu();
    try std.testing.expect(session.resource_menu_open);

    // **표시 문자열을 일부러 낡게 만든다.** 다음 폴링이 머리글을 이 낡은 값으로 그리면(옛 순서) 아래
    // 단언이 죽는다. 값 자체는 그 tick의 실제 합계로 다시 계산되므로 무엇이 들어오든 낡은 것과는 다르다.
    const stale = "  1.0 GB ·   99%";
    @memcpy(session.resource_text_buf[0..stale.len], stale);
    session.resource_text_len = stale.len;

    while (monotonicMs() -| start_ms < 15) _ = usleep(1_000);
    session.resource_poll_ticks = std.math.maxInt(u32) / 2;
    session.pollResourceUsage();

    // 띠가 그리는 문자열과 머리글이 **같은 값**을 담는다.
    const shown = session.resourceText() orelse return error.TestExpectedText;
    try std.testing.expect(!std.mem.eql(u8, shown, stale)); // 폴링이 실제로 갱신했다(전제)
    try std.testing.expect(std.mem.indexOf(u8, session.context_menu_items_buf[0], shown) != null);
}

// SB-H: 공유 행이 **둘**일 때 — 세션 호스트 + 앱. 둘 다 정렬 밖 고정이고, 꼬리 수가 2가 되며,
// **순서는 `resource_pinned_keys`가 정한다**(표본을 얻은 순서가 아니다). 위 SB-A가 "하나만 설 때"를
// 덮으므로 둘을 함께 두면 상수/실제 개수가 갈리는 두 방향이 모두 잡힌다(§4.2).
test "SB-H: 세션 호스트 행도 정렬 밖 고정이고 꼬리 수는 실제 개수다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 80,
        .rows = 24,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    const lang_before = maru.i18n.lang();
    defer maru.i18n.setLang(lang_before);
    maru.i18n.setLang(.ko);
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    // 호스트 행을 **가장 무겁게**, 앱 행을 **가장 가볍게** 심는다. 정렬에 섞였다면 호스트가 맨 위·앱이
    // 맨 아래로 갈라질 값인데, 둘 다 정렬 밖이라 붙어서 맨 아래에 와야 한다.
    session.resource_rows[0] = .{ .key = resource_app_key, .reading = .{ .footprint_bytes = 1, .cpu_permille = 0 } };
    session.resource_rows[1] = .{ .key = 111, .reading = .{ .footprint_bytes = 10, .cpu_permille = 0 } };
    session.resource_rows[2] = .{ .key = resource_host_key, .reading = .{ .footprint_bytes = 9_000_000, .cpu_permille = 5 } };
    session.resource_rows[3] = .{ .key = 222, .reading = .{ .footprint_bytes = 900, .cpu_permille = 0 } };
    session.resource_rows_len = 4;

    const text = "  512 MB ·   10%";
    @memcpy(session.resource_text_buf[0..text.len], text);
    session.resource_text_len = text.len;
    try std.testing.expect(try statusBarHasText(allocator, session, "512"));

    session.openResourceMenu();
    try std.testing.expect(session.resource_menu_open);
    try std.testing.expectEqual(@as(usize, 4), session.resource_menu_len);
    // 탭은 무거운 순(222 → 111), 그 뒤가 고정 행 **둘**이고 순서는 키 배열대로(호스트 → 앱)다.
    try std.testing.expectEqual(@as(u64, 222), session.resource_menu_keys[0]);
    try std.testing.expectEqual(@as(u64, 111), session.resource_menu_keys[1]);
    try std.testing.expectEqual(resource_host_key, session.resource_menu_keys[2]);
    try std.testing.expectEqual(resource_app_key, session.resource_menu_keys[3]);

    const menu = &session.chrome_host.context_menu;
    try std.testing.expectEqual(@as(usize, 2), menu.footer_count);
    const last = resource_header_rows + session.resource_menu_len - 1;
    try std.testing.expect(!menu.selectable(last)); // 앱 행
    try std.testing.expect(!menu.selectable(last - 1)); // 세션 호스트 행
    try std.testing.expect(menu.selectable(last - 2)); // 그 위 탭 행은 고를 수 있다
    menu.moveSelection(99);
    try std.testing.expect(menu.selectable(menu.selected));
    try std.testing.expectEqual(last - 2, menu.selected);

    // 라벨이 "세션 호스트"라고 말한다 — 앱 행과 구별되지 않으면 두 숫자가 무엇인지 알 수 없다.
    try std.testing.expect(std.mem.indexOf(u8, session.context_menu_items_buf[last - 1], "세션 호스트") != null);
    try std.testing.expect(std.mem.indexOf(u8, session.context_menu_items_buf[last], "모든 창 공유") != null);
}

// SB-P: 팝오버는 **열 때 순서·개수를 얼리고 값만 갱신한다.** 무거운 순 정렬이라 갱신마다 다시 정렬하면
// 누르려던 줄이 손가락 밑에서 다른 탭이 되고, `show()`를 다시 부르면 선택도 0으로 튕긴다(§6).
test "SB-P: 열린 뒤 값이 바뀌어도 행 순서와 개수가 그대로다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 80,
        .rows = 24,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    // 행 두 개를 심는다(가벼운 것이 먼저 — 정렬이 실제로 도는지 보려고).
    session.resource_rows[0] = .{ .key = 111, .reading = .{ .footprint_bytes = 10, .cpu_permille = 0 } };
    session.resource_rows[1] = .{ .key = 222, .reading = .{ .footprint_bytes = 900, .cpu_permille = 0 } };
    session.resource_rows_len = 2;

    // 상태바 항목이 서야 앵커가 생긴다 — 표시 문자열을 심고 tree를 세운다.
    const text = "  512 MB ·   10%";
    @memcpy(session.resource_text_buf[0..text.len], text);
    session.resource_text_len = text.len;
    // **앵커는 렌더 경로가 발행한다** — `statusBarTree()`는 읽기만 한다. 실제로 한 번 그려야 rect가 생긴다.
    try std.testing.expect(try statusBarHasText(allocator, session, "512"));

    session.openResourceMenu();
    try std.testing.expect(session.resource_menu_open);
    try std.testing.expectEqual(@as(usize, 2), session.resource_menu_len);
    // 머리글 2줄(제목·열 이름)이 앞에 붙는다 — 행 인덱스는 그만큼 밀린다.
    try std.testing.expectEqual(resource_header_rows + 2, session.context_menu_items_len);
    try std.testing.expectEqual(resource_header_rows, session.chrome_host.context_menu.header_count);
    try std.testing.expect(std.mem.indexOf(u8, session.context_menu_items_buf[0], maru.i18n.t(.col_resource)) != null);
    try std.testing.expect(std.mem.indexOf(u8, session.context_menu_items_buf[1], maru.i18n.t(.res_memory)) != null);
    // 무거운 순 — 900이 먼저다.
    try std.testing.expectEqual(@as(u64, 222), session.resource_menu_keys[0]);
    try std.testing.expectEqual(@as(u64, 111), session.resource_menu_keys[1]);

    // 값이 뒤집혀도(111이 무거워져도) **순서는 그대로**여야 한다.
    session.resource_rows[0] = .{ .key = 111, .reading = .{ .footprint_bytes = 9_000, .cpu_permille = 0 } };
    session.refreshResourceMenuRows();
    try std.testing.expectEqual(@as(u64, 222), session.resource_menu_keys[0]);
    try std.testing.expectEqual(@as(usize, 2), session.resource_menu_len);
    try std.testing.expectEqual(resource_header_rows + 2, session.context_menu_items_len);
}

// SB-P 적대적: **팝오버가 열린 채 상태바가 사라지면** 어떻게 되나. 앵커가 없어졌는데 목록이 남으면
// 사용자는 누른 적 없는 자리에 뜬 유령 목록을 보게 된다(브랜치 메뉴가 "앵커 없으면 열지 않는다"로
// 막은 것과 같은 문제의 **열린 뒤** 판이다).
test "SB-P: 열린 채 상태바가 숨으면 팝오버도 닫힌다" {
