// SB-P 적대적: **한글 탭 이름에서 열이 어긋나면 안 된다.** 패딩을 글자 수로 하면 한글 한 자가 2칸이라
// 숫자 열이 밀린다. EAW 기준이어야 모든 행의 숫자가 같은 칸에서 시작한다.
test "SB-P: 한글 탭 이름이 섞여도 숫자 열이 같은 칸에서 시작한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 80,
        .rows = 24,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    const ru = maru.session.resource_usage;
    const reading: ru.Reading = .{ .footprint_bytes = 100 * 1024 * 1024, .cpu_permille = 50 };
    // 라벨을 직접 조립해 폭만 본다(실 Term 없이 — 이름 출처는 다른 테스트가 덮는다).
    var ascii_buf: [resource_row_max_bytes]u8 = undefined;
    var cjk_buf: [resource_row_max_bytes]u8 = undefined;
    const ascii_row = buildResourceRowForTest(&ascii_buf, "work", reading);
    const cjk_row = buildResourceRowForTest(&cjk_buf, "작업공간", reading); // 4자 = 8칸

    // 숫자가 시작하는 **칸**이 같아야 한다.
    const a_at = std.mem.indexOf(u8, ascii_row, "100 MB") orelse return error.TestUnexpectedResult;
    const c_at = std.mem.indexOf(u8, cjk_row, "100 MB") orelse return error.TestUnexpectedResult;
    const a_cols = chrome.components.overlay_input.displayCols(ascii_row[0..a_at]);
    const c_cols = chrome.components.overlay_input.displayCols(cjk_row[0..c_at]);
    try std.testing.expectEqual(a_cols, c_cols);
    // 바이트로 재면 다르다 — 그래서 칸으로 재야 한다는 것이 이 테스트의 요점이다.
    try std.testing.expect(a_at != c_at);
}

/// 테스트용 행 조립 — `formatResourceRow`의 폭 계산 부분만 떼어 같은 규칙으로 만든다(실 Term 불요).
fn buildResourceRowForTest(out: []u8, label: []const u8, reading: maru.session.resource_usage.Reading) []const u8 {
    const ru = maru.session.resource_usage;
    var value_buf: [ru.text_max_bytes]u8 = undefined;
    const value = ru.format(&value_buf, reading);
    var name_buf: [resource_row_max_bytes]u8 = undefined;
    const shown = truncateColsInto(&name_buf, label, resource_row_name_cols);
    const name_cols = chrome.components.overlay_input.displayCols(shown);
    var used: usize = 0;
    used += copyClamped(out[used..], shown);
    var pad = resource_row_name_cols -| name_cols;
    while (pad > 0 and used < out.len) : (pad -= 1) {
        out[used] = ' ';
        used += 1;
    }
    used += copyClamped(out[used..], "  ");
    used += copyClamped(out[used..], value);
    return out[0..used];
}

// SB-R 적대적: **조각이 아니라 이어 붙인 경로를 본다.** 위 테스트들은 Meter를 직접 태워 계약을 검증하지만,
// backend → 표본 → Meter → 문자열이 실제로 이어졌는지는 증명하지 않는다. 여기서 `pollResourceUsage`를
// 두 번 돌려(첫 표본은 기준선) 표시가 생기는지 본다 — 배선이 끊겨 있으면 영영 null이다.
test "SB-R: 폴링 두 번이면 실제 backend 표본으로 표시가 생긴다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 80,
        .rows = 24,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    // **tick이 실제로 폴링을 부르는지** 여기서 고정한다 — 아래 직접 호출만 있으면 배선이 끊겨도 통과한다.
    // 이 tick이 곧 **첫 표본(기준선)**이다.
    session.resource_poll_ticks = std.math.maxInt(u32) / 2;
    _ = try session.tick();
    try std.testing.expectEqual(@as(u32, 0), session.resource_poll_ticks); // 주기 도달 → 폴링이 카운터를 리셋했다
    try std.testing.expect(session.resourceText() == null); // 첫 표본은 기준선이라 표시가 없다

    // 두 번째 표본은 벽시계가 흘러야 값이 된다 — Meter가 gap>0을 요구하므로 1ms라도 지나게 한다.
    var spin: u64 = monotonicMs();
    while (monotonicMs() == spin) spin = monotonicMs();

    session.resource_poll_ticks = std.math.maxInt(u32) / 2;
    session.pollResourceUsage();

    // **표시가 반드시 생겨야 한다.** 처음엔 "못 잡으면 null도 정상"이라는 예외를 뒀는데, 그러면 seam을
    // 끊어 표본을 0으로 만들어도 테스트가 통과한다(뮤테이션으로 확인했다) — 배선을 못 지키는 테스트다.
    // 스모크 세션은 실제로 PTY 자식을 띄우므로 표본이 잡힌다. 언젠가 그 전제가 깨지면 여기서 시끄럽게
    // 실패하는 편이 조용히 눈감는 것보다 낫다.
    const text = session.resourceText() orelse return error.TestExpectedResourceText;
    try std.testing.expectEqual(maru.session.resource_usage.text_cols, try std.unicode.utf8CountCodepoints(text));
    try std.testing.expect(session.resource_reading != null);
}

// SB-C 적대적: **커서 위치도 같은 가드를 갖는다 — 그리고 버린 DrawList를 푼다.**
//
// 이 분기는 좁은 창 + 편집기 pane + 선택이 **동시에** 있어야 열린다. 기존 좁은 창 테스트(SB-R)는
// 터미널 pane이라 `cursorPosition`에 닿지 않아, 가드를 통째로 지워도 스위트가 전부 초록이었다
// (적대적 검증 2026-08-21). 누수는 `testing.allocator`가 잡는다 — `defer`가 도는 대상은 배열에
// 실린 것뿐이라, 버린 항목을 안 풀면 상태바가 **프레임마다** 샌다.
test "SB-C: 커서 위치도 폭이 모자라면 내리고, 버린 DrawList를 푼다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    // 열이 커야 텍스트가 길어진다(`1:14097+` = 10칸). 짧으면 좁은 창에서도 들어가 가드가 안 열린다.
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const io = std.Io.Threaded.global_single_threaded.io();
    const wide = editor_ops.max_status_column + 500;
    var long: std.ArrayList(u8) = .empty;
    defer long.deinit(allocator);
    try long.appendNTimes(allocator, 'x', wide);
    try long.append(allocator, '\n');
    try tmp.dir.writeFile(io, .{ .sub_path = "wide.txt", .data = long.items });
    var rb: [std.fs.max_path_bytes]u8 = undefined;
    const root = rb[0..try tmp.dir.realPath(io, &rb)];
    const path = try std.fs.path.join(allocator, &.{ root, "wide.txt" });
    defer allocator.free(path);

    const term = editor_ops.openPathInActivePane(session, path) catch return error.SkipZigTest;
    term.rt.editor_selection = maru.session.editor.selection.Selection.at(wide);

    const colors: metal_frame.CellColors = .{ .default_fg = session.appearance.theme.foreground };

    // ① 넓은 창: 온전히 뜬다 — 아래 ②가 항진명제가 아니다.
    _ = try session.resize(session.sidebar_width_px + 900, 600, session.scale_milli);
    try std.testing.expect(cursorItemPublished(session, allocator, colors));

    // ② 좁은 창: 예산(바 폭/3)이 모자라 통째로 내려간다. 잘린 `1:140…`은 다른 값으로 읽힌다.
    //
    // **폭 전제를 손으로 세지 않는다** — 표시 텍스트를 실제로 만들어 그 길이로 잰다. 처음에 `1:14097+`를
    // 10칸으로 어림했다가(실제 8칸) 예산 9칸에 그대로 들어가 테스트가 거짓 실패했다.
    const pos = editor_ops.cursorPosition(term) orelse return error.NoCursorPos;
    var want_buf: [48]u8 = undefined;
    const want = try std.fmt.bufPrint(&want_buf, "{d}:{d}{s}", .{
        pos.line,
        pos.column,
        if (pos.truncated) "+" else "",
    });

    _ = try session.resize(180, 600, session.scale_milli);
    const bar_cols = session.backing_width_px / session.cell_width_px;
    try std.testing.expect(@max(1, bar_cols / 3) < want.len); // 전제: 예산이 그 텍스트에 못 미친다
    try std.testing.expect(!cursorItemPublished(session, allocator, colors));
}

fn cursorItemPublished(
    session: *AppSession,
    allocator: std.mem.Allocator,
    colors: metal_frame.CellColors,
) bool {
    var collected: std.ArrayList(AppSession.CollectedPane) = .empty;
    defer {
        for (collected.items) |*c| c.deinit(allocator);
        collected.deinit(allocator);
    }
    session.collectStatusBarItems(&collected, pane_ops.paneFrameBuilder(session), colors);
    for (session.status_bar_entry_scratch[0..session.status_bar_entry_count]) |entry| {
        if (entry.id == @intFromEnum(chrome.components.status_bar.ItemId.editor_cursor)) return true;
    }
    return false;
}

// SB-R 적대적: **좁은 창에서 숫자가 잘리면 안 된다.** 텍스트 예산은 바 폭의 1/3이라 창이 좁으면 리소스
// 문자열(16칸)이 안 들어간다. 이름이라면 앞부분만 보여도 식별되지만 **숫자는 잘리면 다른 값으로 읽힌다**
// ("512 MB ·…"). 그때는 항목을 통째로 내려야 한다.
test "SB-R: 폭이 모자라면 잘린 숫자 대신 항목을 내린다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 80,
        .rows = 24,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    const ru = maru.session.resource_usage;
    const text = "  512 MB ·   10%";
    @memcpy(session.resource_text_buf[0..text.len], text);
    session.resource_text_len = text.len;
    try std.testing.expectEqual(ru.text_cols, text.len - 1); // `·`가 2바이트라 칸 수는 하나 적다(전제)

    // 넓은 창: 예산이 넉넉해 온전히 뜬다.
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);
    {
        var collected: std.ArrayList(AppSession.CollectedPane) = .empty;
        defer {
            for (collected.items) |*c| c.deinit(allocator);
            collected.deinit(allocator);
        }
        const colors: metal_frame.CellColors = .{ .default_fg = session.appearance.theme.foreground };
        session.collectStatusBarItems(&collected, pane_ops.paneFrameBuilder(session), colors);
        var resource_published = false;
        for (session.status_bar_entry_scratch[0..session.status_bar_entry_count]) |entry| {
            if (entry.id == @intFromEnum(chrome.components.status_bar.ItemId.resource)) {
                resource_published = true;
                break;
            }
        }
        try std.testing.expect(resource_published);
    }

    // 좁은 창: 예산(바 폭/3)이 16칸에 못 미쳐 말줄임될 상황 — 숫자가 보이면 안 된다.
    _ = try session.resize(260, 600, session.scale_milli);
    const bar_cols = session.backing_width_px / session.cell_width_px;
    try std.testing.expect(bar_cols / 3 < ru.text_cols); // 전제: 예산이 실제로 모자란다
    {
        var collected: std.ArrayList(AppSession.CollectedPane) = .empty;
        defer {
            for (collected.items) |*c| c.deinit(allocator);
            collected.deinit(allocator);
        }
        const colors: metal_frame.CellColors = .{ .default_fg = session.appearance.theme.foreground };
        session.collectStatusBarItems(&collected, pane_ops.paneFrameBuilder(session), colors);
        var resource_published = false;
        for (session.status_bar_entry_scratch[0..session.status_bar_entry_count]) |entry| {
            if (entry.id == @intFromEnum(chrome.components.status_bar.ItemId.resource)) {
                resource_published = true;
                break;
            }
        }
        try std.testing.expect(!resource_published);
    }
}

// SB-R: **상태바가 안 보이면 재지 않는다.** 안 보이는 UI에 syscall을 쓰지 않는다 —
// 설정 off와 quick terminal 둘 다 `statusBarHeightPx() == 0`이라 게이트가 그 단일 판정에 걸려야 한다.
test "SB-R: 상태바가 숨겨져 있으면 표본을 재지 않고 표시도 지운다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 80,
        .rows = 24,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    // 표시가 있는 상태를 만든다.
    session.resource_text_len = 3;
    @memcpy(session.resource_text_buf[0..3], "abc");
    session.resource_reading = .{ .footprint_bytes = 1, .cpu_permille = 1 };
    try std.testing.expect(session.resourceText() != null);

    // 상태바를 끈다 → 다음 폴링이 표시를 지운다(0을 그리지 않고 항목을 내린다).
    session.chrome_minimal = true;
    try std.testing.expectEqual(@as(u32, 0), session.statusBarHeightPx()); // 전제
    session.resource_poll_ticks = std.math.maxInt(u32) / 2; // 주기 도달을 강제
    session.pollResourceUsage();
    try std.testing.expect(session.resourceText() == null);
}

/// 상태바를 **실제 렌더 경로**(`collectStatusBarItems`)로 그려 `needle`의 코드포인트가 모두 셀에 있는지 본다.
/// 상태만 단언하면 렌더가 그 상태를 무시해도 통과하므로(그리는 것이 계약이다) 그림을 본다.
fn statusBarHasText(allocator: std.mem.Allocator, session: *AppSession, needle: []const u8) !bool {
    var collected: std.ArrayList(AppSession.CollectedPane) = .empty;
    defer {
        for (collected.items) |*c| c.deinit(allocator);
        collected.deinit(allocator);
    }
    const colors: metal_frame.CellColors = .{ .default_fg = session.appearance.theme.foreground };
    session.collectStatusBarItems(&collected, pane_ops.paneFrameBuilder(session), colors);

    var it = (std.unicode.Utf8View.init(needle) catch return false).iterator();
    while (it.nextCodepoint()) |cp| {
        if (cp == ' ') continue; // 공백은 셀에 안 실릴 수 있다(패딩)
        var found = false;
        outer: for (collected.items) |c| {
            for (c.pane.owned_list.cells) |cell| {
                if (cell.codepoint == cp) {
                    found = true;
                    break :outer;
                }
            }
        }
        if (!found) return false;
    }
    return true;
}

test "SB1: 브랜치 목록 요청 중 상태바가 사라지면 메뉴를 열지 않는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 80,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1000, 700, 1000);
    _ = try session.tick();

    // 목록은 도착했는데 그 사이 바가 꺼졌다.
    session.branch_menu_text = try allocator.dupe(u8, "main\nfeat/a\n");
    session.branch_menu_len = git_command.collectBranches(session.branch_menu_text, &session.branch_menu_names);
    session.loaded_config.config.status_bar.show = false;
    session.metal_dirty = true;
    _ = try session.tick();
    try std.testing.expectEqual(@as(u32, 0), session.statusBarHeightPx()); // 전제: 바가 사라졌다

    settings_ops.openBranchMenu(session);
    try std.testing.expect(!session.branch_menu_open);
    try std.testing.expect(!session.chrome_host.context_menu.open);
}

// SB1: **목록 버퍼를 해제하면 그것을 가리키던 메뉴도 닫아야 한다.** 메뉴 항목(`context_menu_items_buf`)은
// `branch_menu_text`를 빌린다 — 해제하고 메뉴를 열어 두면 다음 draw가 해제된 메모리를 읽는다(UAF).
// 재발행이 항상 뒤따르는 것도 아니다: 새 목록이 0개면 `openBranchMenu`가 알림만 띄우고 돌아온다.
test "SB1: 브랜치 목록 버퍼를 비우면 열린 메뉴도 닫힌다(dangling 항목 방지)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 80,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1000, 700, 1000);
    _ = try session.tick();

    session.branch_menu_text = try allocator.dupe(u8, "main\nfeat/a\n");
    session.branch_menu_len = git_command.collectBranches(session.branch_menu_text, &session.branch_menu_names);
    // 메뉴가 열린 상태를 만든다. `openBranchMenu`를 쓰지 않는 이유는 그 함수가 **앵커(상태바 브랜치 항목)를
    // 요구**하기 때문이다 — 이 테스트의 계약은 "해제하면 닫힌다"이지 "무엇이 열 수 있나"가 아니다.
    for (session.branch_menu_names[0..session.branch_menu_len], 0..) |name, i| session.context_menu_items_buf[i] = name;
    session.context_menu_items_len = session.branch_menu_len;
    session.branch_menu_open = true;
    session.chrome_host.context_menu.show(0, 0, session.branch_menu_len);
    try std.testing.expect(session.chrome_host.context_menu.open);

    // 버퍼를 비운다 — 이 시점에 메뉴가 열린 채면 항목 포인터가 해제된 메모리를 가리킨다.
    settings_ops.clearBranchMenuText(session);
    try std.testing.expect(!session.branch_menu_open);
    try std.testing.expect(!session.chrome_host.context_menu.open);

    // **기준 목록도 같은 버퍼를 빌린다**(§3.5). 플래그가 다르다는 이유로 이 가드 밖에 두면 같은 UAF다 —
    // 실제로 그렇게 냈다가 적대적 검증에서 잡았다(2026-08-19).
    session.branch_menu_text = try allocator.dupe(u8, "main\nfeat/a\n");
    session.branch_menu_len = git_command.collectBranches(session.branch_menu_text, &session.branch_menu_names);
    for (session.branch_menu_names[0..session.branch_menu_len], 0..) |name, i| session.context_menu_items_buf[i] = name;
    session.context_menu_items_len = session.branch_menu_len;
    session.scm_base_menu_open = true;
    session.chrome_host.context_menu.show(0, 0, session.branch_menu_len);
    try std.testing.expect(session.chrome_host.context_menu.open);

    settings_ops.clearBranchMenuText(session);
    try std.testing.expect(!session.scm_base_menu_open);
    try std.testing.expect(!session.chrome_host.context_menu.open);
}

// SB1: **브랜치를 고르면 우리가 checkout하지 않고 터미널에 명령을 넣는다.** 읽기 전용 계약
// (docs/editor-surface-tooling.md §6)이 write git을 우리 손으로 돌리는 것을 막는다 — 실행 주체가 셸이어야
// hook·dirty tree·충돌이 평소처럼 사용자에게 보인다. 그래서 "무엇이 PTY로 나갔는가"를 단언한다.
test "SB1: 브랜치 선택은 git switch를 터미널에 넣기만 한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 80,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1000, 700, 1000);
    _ = try session.tick();

    // 백엔드가 준 것과 같은 형태의 출력을 심는다(실제 git 실행 없이 파서·배선만 본다).
    session.branch_menu_text = try allocator.dupe(u8, "main\nfeat/status-bar\nfix/reload\n");
    session.branch_menu_len = git_command.collectBranches(session.branch_menu_text, &session.branch_menu_names);
    try std.testing.expectEqual(@as(usize, 3), session.branch_menu_len);

    // 범위 밖은 조용히 무동작 — 메뉴와 목록이 어긋나도 엉뚱한 브랜치로 가지 않고, 오류 표시도 띄우지 않는다.
    settings_ops.applyBranchMenuSelection(session, 99);
    try std.testing.expect(!session.chrome_host.notice.open);

    // 정상 선택은 오류 없이 지나간다(무엇이 나가는지는 아래 순수 계약이 잠근다).
    settings_ops.applyBranchMenuSelection(session, 1);
    try std.testing.expect(!session.chrome_host.notice.open);

    var cmd_buf: [128]u8 = undefined;
    const cmd = git_command.branchSwitchCommand(session.branch_menu_names[1], &cmd_buf).?;
    try std.testing.expectEqualStrings("git switch feat/status-bar", cmd); // 개행 없음 = 실행하지 않음

    // 손상된 이름은 **조용히 넘기지 않고** 알린다 — 셸에 이상한 것을 넣지 않는다.
    session.branch_menu_names[0] = "bad name";
    settings_ops.applyBranchMenuSelection(session, 0);
    try std.testing.expect(session.chrome_host.notice.open);
}

// SB1: **끄면 바가 사라지고 먹었던 높이가 되돌아온다.** 바는 창 높이를 실제로 깎으므로(§1), 끄는 것이
// "안 그린다"에 그치면 행은 여전히 잃은 채 빈 띠만 남는다. 그래서 높이가 0이 되는 것과 **작업영역이
// 그만큼 늘어나는 것**을 함께 본다 — 게이트가 `statusBarHeightPx` 하나뿐이라는 설계가 성립하는지의 검증이다.
test "SB1: status-bar.show=false면 바가 사라지고 작업영역이 그만큼 돌아온다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1000, 700, 1000);
    _ = notification_ops.pushNotificationHistory(session, "MARU", "t", 0);
    _ = try session.tick();

    const bar_h = session.statusBarHeightPx();
    try std.testing.expect(bar_h > 0); // 전제: 기본값은 켜짐이다
    const term_h_on = session.termRect().h;
    try std.testing.expect(session.statusBarTree().entries.len > 0);

    session.loaded_config.config.status_bar.show = false;
    session.metal_dirty = true;
    _ = try session.tick();

    try std.testing.expectEqual(@as(u32, 0), session.statusBarHeightPx());
    try std.testing.expectEqual(@as(usize, 0), session.statusBarTree().entries.len); // 안 보이면 눌리지도 않는다
    try std.testing.expectEqual(term_h_on + bar_h, session.termRect().h); // 먹었던 높이가 그대로 돌아온다
}

test "P4 C3c checkpoint 실패 상태표시줄은 프레임 사이 유지되고 commit 성공 신호로 사라진다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    // 사용자 config와 무관하게 이 테스트가 소유하는 status-bar 전제를 고정한다.
    session.loaded_config.config.status_bar.show = true;
    _ = try session.resize(1200, 700, 1000);

    session.setWorkspaceCheckpointFailure(2);
    _ = try session.tick();
    const failure_id = @intFromEnum(chrome.components.status_bar.ItemId.workspace_checkpoint_failure);
    var seen = false;
    for (session.statusBarTree().entries) |entry| if (entry.id == failure_id) {
        seen = true;
        break;
    };
    try std.testing.expect(seen);

    // 별도 frame에서도 host가 상태를 다시 주입하지 않아도 유지된다.
    session.chrome_dirty = true;
    _ = try session.tick();
    seen = false;
    for (session.statusBarTree().entries) |entry| if (entry.id == failure_id) {
        seen = true;
        break;
    };
    try std.testing.expect(seen);

    session.setWorkspaceCheckpointFailure(0);
    _ = try session.tick();
    for (session.statusBarTree().entries) |entry| try std.testing.expect(entry.id != failure_id);
}

