}

// SB1: **상태바 높이는 spawn grid에 그대로 흡수돼야 한다.** 흡수는 `gridPadding()`의 bottom 한 곳에서만
// 하게 돼 있다 — 호출부 셋(spawn config·메트릭 재계산·resize)이 그 함수를 공유하므로, 여기서 빠지면
// PTY가 실제 pane보다 많은 행으로 떠 spawn-크기 레이스가 난다. 그런데 **그 줄을 지우는 뮤테이션에
// 죽는 테스트가 하나도 없었다**(검증 공백). 바 높이는 셀 높이 파생이라 폰트를 키우면 같이 두꺼워지는데,
// **그 증가분이 그대로 padding 증가분**이어야 한다는 것으로 못박는다.
test "SB1: 상태바 높이 변화가 spawn grid padding에 그대로 흡수된다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1000, 700, 1000);
    _ = try session.tick();

    const bar0 = session.statusBarHeightPx();
    const bottom0 = session.gridPadding().bottom;
    try std.testing.expect(bottom0 >= bar0); // 애초에 흡수돼 있다

    var i: usize = 0;
    while (i < 8) : (i += 1) session.adjustFontSize(font_size_step);
    _ = try session.tick();

    const bar1 = session.statusBarHeightPx();
    const bottom1 = session.gridPadding().bottom;
    try std.testing.expect(bar1 > bar0); // 전제: 폰트를 키우면 바가 실제로 두꺼워진다
    try std.testing.expectEqual(bar1 - bar0, bottom1 - bottom0); // 증가분이 그대로 흡수된다
}

// SB1: **창 크기가 바뀌면 상태바 호버는 비워야 한다.** 우측 항목은 오른쪽 끝에 붙어 있어 폭이 바뀌면
// 포인터 아래에서 빠져나간다. 그런데 호버는 id로 기억하므로 강조가 **항목을 따라 이동**해, 포인터가
// 없는 자리에 하이라이트가 남는다. 포인터가 가만히 있으면 mouseMoved도 안 와서 영구히 남는다.
// 저장소 규율(hovered_nav_button "stale 하이라이트 방지 — 보수적으로 비운다, 다음 이동이 재설정")을 따른다.
test "SB1: 실제 크기 변화가 있는 resize는 상태바 호버를 비운다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1200, 700, 1000);
    _ = notification_ops.pushNotificationHistory(session, "MARU", "t", 0);
    _ = try session.tick();

    var target: ?chrome.ui.tree.RectEntry = null;
    for (session.statusBarTree().entries) |e| {
        if (e.id == @intFromEnum(chrome.components.status_bar.ItemId.notifications)) target = e;
    }
    const item = target orelse return error.NotificationItemMissing;
    const cx: f64 = @floatCast(item.rect.x + item.rect.width / 2);
    const cy: f64 = @floatCast(item.rect.y + item.rect.height / 2);
    _ = session.hoverCursor(cx, cy, 0);
    try std.testing.expectEqual(@as(?chrome.components.status_bar.ItemId, .notifications), session.status_bar_hovered);

    // dedup되는 resize(같은 크기)는 제스처를 유지해야 하므로 호버도 그대로다.
    _ = try session.resize(1200, 700, 1000);
    try std.testing.expectEqual(@as(?chrome.components.status_bar.ItemId, .notifications), session.status_bar_hovered);

    // 실제 폭 변화 — 우측 항목이 포인터 밑에서 빠져나간다.
    _ = try session.resize(700, 700, 1000);
    try std.testing.expectEqual(@as(?chrome.components.status_bar.ItemId, null), session.status_bar_hovered);
}

// SB1: **빈 바 위에서 텍스트 커서(iBeam)가 뜨면 안 된다.** 상태바는 chrome이지 터미널이 아니다 —
// iBeam은 "여기서 글자를 고를 수 있다"는 신호라, 클릭이 삼켜지는 자리에서 뜨면 거짓말이 된다.
// 항목 위(손 모양)는 따로 보고, 여기서는 **항목이 없는 구간**을 본다.
test "SB1: 항목이 없는 상태바 구간은 텍스트 커서를 주지 않는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1000, 700, 1000);
    _ = try session.tick();

    const h = session.statusBarHeightPx();
    const cy: f64 = @floatFromInt(session.backing_height_px - h / 2);

    // **빈 x를 가정하지 않고 찾는다.** 예전에는 "바 한가운데는 비어 있다"고 가정했는데, 그 가정은 스모크
    // 세션이 cwd를 몰라 좌측 항목(브랜치·경로)이 **아예 안 만들어지던** 시절의 우연에 기대고 있었다. 커널 cwd
    // 폴백이 들어오며 그 세션에도 두 항목이 생기고, 그것이 x축으로 어디까지 뻗는지는 저장소 경로 길이와
    // 브랜치 이름에 달렸다 — 이 테스트가 볼 값이 아니다.
    //
    // 게다가 그 가정은 **부하에 따라 결과가 갈렸다**: 전체 스위트를 병렬로 돌리면 자식이 아직 foreground
    // process group을 못 잡아 커널 조회가 실패해 항목이 없고(통과), 이 바이너리만 단독으로 돌리면 답이 나와
    // 항목이 생겨 실패했다. 실측으로 단독 3/3 실패·전체 실행 통과였다. 이 테스트가 보려는 것은 "빈 구간에서
    // 텍스트 커서가 안 나온다"이지 "항목이 있느냐"가 아니므로, 항목 유무와 무관하게 성립하도록 고친다.
    const empty_x: f64 = blk: {
        const step: u32 = @max(session.cell_width_px, 1);
        var x: u32 = 0;
        while (x < session.backing_width_px) : (x += step) {
            const fx: f64 = @floatFromInt(x);
            if (session.statusBarItemAt(fx, cy) == null) break :blk fx;
        }
        // 바가 항목으로 완전히 덮이면 이 테스트가 볼 것이 없다 — 조용히 통과시키지 않고 실패로 말한다.
        return error.StatusBarHasNoEmptyRegion;
    };

    const cursor = session.hoverCursor(empty_x, cy, 0);
    try std.testing.expect(cursor != .text);
}

// SB-AG: 에이전트 개수 항목은 **그 에이전트로 간다**(§4). 옛 동작(기록 도크 열기)은 누른 것과 다른 것을
// 가리켰다 — 숫자는 "지금 이 창에서 도는 Term 수"인데 도크는 "로컬에 남은 과거 세션 목록"이다.
test "SB-AG: 에이전트가 하나면 메뉴 없이 그 Term으로 점프한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    _ = try tab_ops.newTab(session); // [t0, t1] — 다른 탭으로 가야 점프가 관찰된다

    // 첫 탭의 Term을 running으로 세우고, 활성은 두 번째 탭에 둔다.
    const target = session.tabs.items[0].panes.items[0].terms.items[0];
    target.agent_state = .running;
    const target_id = target.surfaceId();
    _ = tab_ops.switchTab(session, 1);
    try std.testing.expect(term_ops.activeSurfaceConst(session).id != target_id);

    session.activateStatusBarItem(.running_agents);

    // 메뉴를 띄우지 않고 바로 갔다 — 하나뿐인데 목록을 한 번 더 띄우면 클릭만 는다.
    try std.testing.expect(!session.agent_menu_open);
    try std.testing.expect(!session.chrome_host.context_menu.open);
    try std.testing.expectEqual(target_id, term_ops.activeSurfaceConst(session).id);
    // 도크는 열리지 않는다(옛 동작이 남아 있지 않다).
    try std.testing.expect(!session.dock.presented);
}

// SB-AG: 팝오버의 **오른쪽 열이 한 줄로 맞아야** 목록으로 읽힌다(사용자 지적). 제목의 개수·열 이름·값이
// 모두 같은 칸에서 끝난다 — 값 열 폭을 머리글 폭에서 파생시키기 때문이다. 상수를 따로 박으면 머리글이
// 더 넓어져 어긋난다(실제로 그랬다: 폭 8 vs 머리글 11칸).
test "SB-AG: 제목·열 이름·값이 같은 칸에서 끝난다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    _ = try tab_ops.newTab(session);

    const t0 = session.tabs.items[0].panes.items[0].terms.items[0];
    const t1 = session.tabs.items[1].panes.items[0].terms.items[0];
    for ([_]*Term{ t0, t1 }) |t| {
        t.agent_state = .running;
        t.agent_last_output_ms = session.awakeMs();
    }
    try std.testing.expect(try statusBarHasText(allocator, session, "2"));
    session.activateStatusBarItem(.running_agents);
    try std.testing.expect(session.agent_menu_open);

    // 네 줄(제목·열 이름·행 2개)의 **표시 칸 폭**이 모두 같아야 한다 — 끝이 맞는다는 뜻이다.
    const cols = chrome.components.overlay_input.displayCols;
    const want = cols(session.context_menu_items_buf[0]);
    try std.testing.expect(want > 0);
    for (session.context_menu_items_buf[0..session.context_menu_items_len]) |line| {
        try std.testing.expectEqual(want, cols(line));
    }
    // 값 열 폭이 머리글에서 나왔다 — 상수를 박으면 이 단언이 깨진다.
    try std.testing.expectEqual(cols(agentAgeHeader()), agentAgeCols());
}

// SB-AG: 정렬 규칙이 두 항목에서 **다르다**(§4). 막힌 것은 처리 대기열이라 오래 기다린 순, 실행 중은 훑는
// 목록이라 탭 순서다. 한 테스트에서 둘 다 본다 — 규칙이 갈린다는 것 자체가 계약이라 따로 두면 짝이 흐려진다.
test "SB-AG: 막힘은 오래 기다린 순, 실행 중은 탭 순서로 목록을 낸다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    inline for (0..2) |_| _ = try tab_ops.newTab(session); // [t0, t1, t2]

    const t0 = session.tabs.items[0].panes.items[0].terms.items[0];
    const t1 = session.tabs.items[1].panes.items[0].terms.items[0];
    const t2 = session.tabs.items[2].panes.items[0].terms.items[0];
    // 활동 시각은 **탭 순서와 반대로** 심는다 — 정렬이 실제로 도는지(또는 안 도는지) 갈리게 하려는 값이다.
    t0.agent_last_output_ms = 30_000; // 가장 최근
    t1.agent_last_output_ms = 20_000;
    t2.agent_last_output_ms = 10_000; // 가장 오래 기다림

    // 상태바 항목이 서야 앵커가 생긴다 — 실제로 한 번 그린다.
    for ([_]*Term{ t0, t1, t2 }) |t| t.agent_state = .blocked;
    try std.testing.expect(try statusBarHasText(allocator, session, "3"));
    session.activateStatusBarItem(.blocked_agents);
    try std.testing.expect(session.agent_menu_open);
    try std.testing.expectEqual(@as(usize, 3), session.agent_menu_len);
    // 오래 기다린 순 — t2(10s) → t1(20s) → t0(30s). 맨 위가 Enter 한 번의 대상이다.
    try std.testing.expectEqual(t2.surfaceId(), session.agent_menu_keys[0]);
    try std.testing.expectEqual(t1.surfaceId(), session.agent_menu_keys[1]);
    try std.testing.expectEqual(t0.surfaceId(), session.agent_menu_keys[2]);
    settings_ops.closeContextMenu(session);

    // 같은 값인데 실행 중이면 **탭 순서**다 — 시간이 아니라 위치가 기준이다.
    for ([_]*Term{ t0, t1, t2 }) |t| t.agent_state = .running;
    try std.testing.expect(try statusBarHasText(allocator, session, "3"));
    session.activateStatusBarItem(.running_agents);
    try std.testing.expect(session.agent_menu_open);
    try std.testing.expectEqual(t0.surfaceId(), session.agent_menu_keys[0]);
    try std.testing.expectEqual(t1.surfaceId(), session.agent_menu_keys[1]);
    try std.testing.expectEqual(t2.surfaceId(), session.agent_menu_keys[2]);

    // 머리글 두 줄이 앞에 붙고, 고르면 그 Term으로 간다(리소스 팝오버와 같은 규율 — 인덱스에서 머리글을 뺀다).
    try std.testing.expectEqual(agent_header_rows, session.chrome_host.context_menu.header_count);
    try std.testing.expectEqual(agent_header_rows + 3, session.context_menu_items_len);
    session.chrome_host.context_menu.selected = agent_header_rows + 2; // 세 번째 행 = t2
    settings_ops.acceptContextMenu(session);
    try std.testing.expect(!session.agent_menu_open);
    try std.testing.expectEqual(t2.surfaceId(), term_ops.activeSurfaceConst(session).id);
}

// SB1: **도크를 여는 클릭은 레이아웃 후속까지 해야 한다.** 필드(`presented`·`collapsed`)만 세우면 도크는
// 나타나는데 pane rect가 옛 폭 그대로라 다음 resize 전까지 어긋난다. 특히 **이미 그 뷰였으면**
// `setDockView`가 조기 반환하므로 그쪽 resize 경로도 안 탄다 — 그때가 가장 잘 드러난다.
test "SB1: 상태바로 도크를 열면 pane 레이아웃도 함께 갱신된다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1000, 700, 1000);

    // 도크는 닫혀 있고 **뷰는 이미 목적지**다 — `setDockView`가 조기 반환하는 최악의 경우.
    //
    // **대상이 `.cwd`인 이유**: 에이전트 개수 항목은 더 이상 도크를 열지 않는다(§4 — 그 에이전트로 점프한다).
    // 이 테스트가 못박는 것은 "에이전트"가 아니라 **도크를 여는 클릭의 레이아웃 후속**이므로, 지금도 도크를
    // 여는 항목으로 옮긴다. 계약을 지우는 대신 살아 있는 소비자에게 붙인다.
    session.dock.presented = false;
    session.dock.view = .explorer;
    session.last_resize_size = .{ .cols = 1, .rows = 1 };
    const before = session.active_pane_rect;

    session.activateStatusBarItem(.cwd);

    try std.testing.expect(session.dock.presented);
    try std.testing.expect(!session.dock.collapsed);
    // 레이아웃 후속이 돌았다 — pane rect가 도크만큼 좁아지고 resize 캐시가 무효화된다.
    try std.testing.expectEqual(@as(?terminal.Size, null), session.last_resize_size);
    try std.testing.expect(session.active_pane_rect.w < before.w);
}

// SB1: **상태바 휠 가드가 notice 해제를 가로채면 안 된다.** notice 토스트는 "아무 입력으로나 닫힘"
// 규율이라 휠도 닫아야 하고, 그 처리는 상태바 가드 **뒤에** 있다. 앞에서 삼키면 토스트가 뜬 채로
// 스크롤도 막히고 닫히지도 않는다 — 코드 주석이 옛 회귀로 적어 둔 바로 그 상태다.
test "SB1: notice가 떠 있으면 상태바 휠이 그것을 닫는 처리를 가로채지 않는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1000, 700, 1000);
    _ = try session.tick();

    // 바 한가운데 좌표(항목이 없어도 바 안이면 가드 대상이다).
    const h = session.statusBarHeightPx();
    const cx: f64 = @floatFromInt(session.backing_width_px / 2);
    const cy: f64 = @floatFromInt(session.backing_height_px - h / 2);

    session.showNotice("test");
    try std.testing.expect(session.chrome_host.notice.open);
    scroll_ops.scrollWheel(session, -1, 0, false, cx, cy);
    try std.testing.expect(!session.chrome_host.notice.open); // 휠이 토스트를 닫았다
}

// SB1: **상태바 hover가 다른 hover의 해제를 가로채면 안 된다.** `hoverCursor`에는 "어느 zone이든 early
// return 전에 항상" 돌아야 하는 갱신이 셋 있다(스크롤바·탐색기 스크롤바·주소창 nav 버튼) — 그 주석들이
// 그렇게 적어 둔 이유가 stale 하이라이트다. 상태바 hover 블록이 그보다 앞에서 `return`하면, 스크롤바를
// 가리키다 상태바로 들어오는 순간 스크롤바 강조가 **남는다**.
test "SB1: 상태바로 들어와도 다른 영역의 hover 해제가 먼저 돈다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1000, 700, 1000);

    _ = notification_ops.pushNotificationHistory(session, "MARU", "t", 0);
    _ = try session.tick();
    var target: ?chrome.ui.tree.RectEntry = null;
    for (session.statusBarTree().entries) |e| {
        if (e.id == @intFromEnum(chrome.components.status_bar.ItemId.notifications)) target = e;
    }
    const item = target orelse return error.NotificationItemMissing;
    const cx: f64 = @floatCast(item.rect.x + item.rect.width / 2);
    const cy: f64 = @floatCast(item.rect.y + item.rect.height / 2);

    // 스크롤바를 가리키고 있었다고 두고, 상태바 항목으로 옮긴다.
    session.scrollbar_hovered = true;
    const cursor = session.hoverCursor(cx, cy, 0);

    try std.testing.expect(!session.scrollbar_hovered); // 옛 강조가 해제됐다
    try std.testing.expectEqual(CursorKind.link, cursor); // 그러고도 상태바 커서는 손 모양이다
    try std.testing.expectEqual(@as(?chrome.components.status_bar.ItemId, .notifications), session.status_bar_hovered);
}

// SB1: **모달이 떠 있으면 상태바 클릭이 먹으면 안 된다.** 모달은 결정 게이트다 — 그 뒤에서 도크·패널이
// 열리면 단일-오버레이 불변식이 깨지고, 사용자는 자기가 답하던 질문 뒤에 뭔가 열린 것을 나중에 발견한다.
// 상태바 가드가 `mouse()`의 **맨 앞**에 있어(터미널 선택을 막으려면 그래야 한다) 기존 모달 처리보다
// 먼저 돌기 때문에, 여기서 직접 비켜 주지 않으면 그 처리에 닿지도 않는다.
test "SB1: 확인 모달이 열려 있으면 상태바 클릭이 항목을 실행하지 않는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1000, 700, 1000);

    // 알림 항목을 세우고 그 위 좌표를 잡는다.
    _ = notification_ops.pushNotificationHistory(session, "MARU", "t", 0);
    _ = try session.tick();
    var target: ?chrome.ui.tree.RectEntry = null;
    for (session.statusBarTree().entries) |e| {
        if (e.id == @intFromEnum(chrome.components.status_bar.ItemId.notifications)) target = e;
    }
    const item = target orelse return error.NotificationItemMissing;
    const cx: f64 = @floatCast(item.rect.x + item.rect.width / 2);
    const cy: f64 = @floatCast(item.rect.y + item.rect.height / 2);

    // 모달이 열린 상태에서 그 자리를 눌러도 알림 패널이 열리면 안 된다.
    session.chrome_host.confirm.open = true;
    session.mouse(1, cx, cy, 0, 0);
    try std.testing.expect(!session.chrome_host.notifications.open);

    // 모달을 닫으면 같은 클릭이 먹는다 — 가드가 항목을 영영 죽인 게 아니라 모달일 때만 비켜 준다.
    session.chrome_host.confirm.open = false;
    session.mouse(1, cx, cy, 0, 0);
    try std.testing.expect(session.chrome_host.notifications.open);
}

// SB1: **사라진 항목의 호버는 남으면 안 된다.** 알림을 다 읽어 항목이 없어졌다가 새 알림이 와서 다시
// 나타나면, 포인터가 그 자리에 없는데도 호버가 칠해진다(포인터가 창 밖으로 나가 `hoverCursor`가 더는
// 안 불리는 경우도 같다). `chrome/ui/interaction.zig`의 `reconcile`이 tree 재발행 때 하는 일을 그대로
// 한다 — 손으로 만든 호버라 그 정리를 빠뜨리기 쉬웠고, 실제로 빠뜨렸었다.
test "SB1: 항목이 tree에서 사라지면 호버도 지워진다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1000, 700, 1000);

    // 알림 항목이 있는 tree를 만들고 그 위에 호버가 있다고 둔다.
    _ = notification_ops.pushNotificationHistory(session, "MARU", "t", 0);
    _ = try session.tick();
    session.status_bar_hovered = .notifications;

    // 알림이 0이 되면 항목이 사라진다 — 다음 **발행**에서 호버도 함께 지워져야 한다. 실제 경로에서는
    // 알림 변화가 dirty를 세우지만 여기선 필드를 직접 바꾸므로 재투영을 명시로 요구한다(안 그러면 수집기
    // 자체가 안 돌아 tree가 그대로다 — 그건 이 테스트가 볼 대상이 아니다).
    session.notification_unread = 0;
    session.metal_dirty = true;
    _ = try session.tick();
    try std.testing.expectEqual(@as(?chrome.components.status_bar.ItemId, null), session.status_bar_hovered);
}

// SB1: 이 기능의 **요점은 "안 보이는 곳"**이다 — 한 번에 터미널 하나만 보이므로, 다른 워크스페이스에서
// 막힌 에이전트를 상태바가 알려 주는 것이 값어치다. 활성 Term만 세면 이미 화면에 보이는 것을 한 번 더
// 말하는 셈이라 기능이 사실상 없는 것과 같다. 그 경로를 캡처로는 못 찍어(탭을 여럿 만들어야 한다) 여기서 본다.
test "SB1: 에이전트 집계는 비활성 탭까지 센다(안 보이는 곳이 요점이다)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1000, 700, 1000);

    // 첫 탭의 Term을 blocked로 세우고, **다른 탭으로 옮긴다**.
    const first = pane_ops.activePane(session).activeTerm();
    first.agent_state = .blocked;
    first.agent_kind = .claude;
    session.dispatchAppAction(.new_tab);
    try std.testing.expect(session.tabs.items.len >= 2);
    try std.testing.expect(pane_ops.activePane(session).activeTerm() != first); // 이제 다른 Term을 보고 있다

    // 활성이 아닌데도 잡힌다 — 이게 없으면 기능이 요점을 잃는다.
    const away = agent_ops.tallyAgents(session);
    try std.testing.expectEqual(@as(usize, 1), away.blocked);
    try std.testing.expectEqual(@as(usize, 0), away.running);

    // running도 같은 방식으로 합산되고, 대표 kind는 running 쪽에서 온다(blocked가 kind를 가로채지 않는다).
    pane_ops.activePane(session).activeTerm().agent_state = .running;
    pane_ops.activePane(session).activeTerm().agent_kind = .codex;
    const both = agent_ops.tallyAgents(session);
    try std.testing.expectEqual(@as(usize, 1), both.blocked);
    try std.testing.expectEqual(@as(usize, 1), both.running);
    try std.testing.expectEqual(AgentKind.codex, both.running_kind);
}

// SB1 §5.5: **눌리는 자리와 보이는 자리가 같아야 한다.** `pointInStatusBar`(휠·클릭을 삼키는 판정)와
// `appendStatusBarBackground`(그리는 rect)가 각자 산술을 갖고 있어, 한쪽만 고치면 바가 보이는데 클릭이
// 통과하거나(터미널이 선택을 시작) 반대로 바 밖이 먹히는 어긋남이 난다. 지금까지 주석으로만 묶여 있었다.
//
// 그래서 **그려진 quad에서 rect를 읽어** 판정을 대조한다 — 판정식을 테스트에 다시 쓰면 같은 실수를 두 번
// 적는 것일 뿐이라 드리프트를 못 잡는다.
test "SB1: 상태바 hit-test는 그려진 rect와 같은 자리를 가리킨다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1000, 700, 1000);

    // 폰트를 바꿔 바 높이가 달라져도 둘이 함께 가는지 본다 — 한쪽만 갱신되는 드리프트가 여기서 잡힌다.
    var round: usize = 0;
    while (round < 3) : (round += 1) {
        if (round > 0) session.dispatchAppAction(.increase_font_size);
        _ = try session.tick();

        // 그려진 바 quad를 기하로 찾는다(bottom 버킷은 탭 밴드와 공유하므로 레이어로는 특정 못 한다).
        const full_w: f32 = @floatFromInt(session.backing_width_px);
        var bar: ?metal_frame.GpuQuad = null;
        for (session.gpu_quads.items) |q| {
            if (q.w == full_w and q.h == @as(f32, @floatFromInt(session.statusBarHeightPx()))) bar = q;
        }
        const q = bar orelse return error.StatusBarQuadMissing;

        const left: f64 = @floatCast(q.x);
        const top: f64 = @floatCast(q.y);
        const right: f64 = left + @as(f64, @floatCast(q.w));
        const bottom: f64 = top + @as(f64, @floatCast(q.h));

        // 안쪽 — 위/아래 경계 행과 좌/우 끝까지 전부 바로 친다.
        try std.testing.expect(session.pointInStatusBar(left, top));
        try std.testing.expect(session.pointInStatusBar(right - 1, bottom - 1));
        try std.testing.expect(session.pointInStatusBar((left + right) / 2, (top + bottom) / 2));
        // **사이드바 아래 구간도 바다**(전폭) — 휠 가드를 사이드바 판정보다 먼저 둔 이유가 이것이다.
        if (session.sidebar_width_px > 2) {
            try std.testing.expect(session.pointInStatusBar(@floatFromInt(session.sidebar_width_px / 2), top + 1));
        }

        // 바깥 — 바로 위 한 행과 우측 밖. 여기까지 삼키면 터미널·사이드바 입력을 먹는다.
        try std.testing.expect(!session.pointInStatusBar((left + right) / 2, top - 1));
        try std.testing.expect(!session.pointInStatusBar(right, top + 1));
    }
}

test "SB1-S2b: 상태바 배경이 창 전폭으로 매 프레임 선다(bottom 버킷)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1000, 700, 1000);
    _ = try session.tick();

    const h = session.statusBarHeightPx();
    try std.testing.expect(h > 0);

    // **기하로 찾는다.** bottom 버킷은 값 2 하나뿐이라 탭 밴드와 레이어를 공유한다 — 레이어만으로는
    // 상태바를 특정할 수 없다(옛 테스트가 탭 밴드 quad를 잡아 오해를 낳았다).
    const bar_y: f32 = @floatFromInt(session.backing_height_px - h);
    // 높이까지 본다 — 같은 y·전폭에 **상단 경계선**도 있어서(§4.0) 높이를 안 보면 선을 배경으로 오인한다.
    var found: ?metal_frame.GpuQuad = null;
    for (session.gpu_quads.items) |q| {
        if (q.y == bar_y and q.w == @as(f32, @floatFromInt(session.backing_width_px)) and
            q.h == @as(f32, @floatFromInt(h))) found = q;
    }
    const bar = found orelse return error.StatusBarQuadMissing;
    try std.testing.expectEqual(@as(f32, 0), bar.x); // 창 전폭 — 사이드바 아래까지 지나간다
    try std.testing.expectEqual(@as(f32, @floatFromInt(session.backing_width_px)), bar.w);
    try std.testing.expectEqual(@as(f32, @floatFromInt(session.backing_height_px - h)), bar.y);
    try std.testing.expectEqual(@as(f32, @floatFromInt(h)), bar.h);
    // 버킷 판정: `.m`의 버킷팅은 2=bottom·0=under·4=header·그 밖=over다. **bottom이어야 한다** —
    // S2b는 over로 잡았는데(사이드바 셀 뒤에 오는 유일한 버킷이라는 이유로) 그러면 별도 오버레이 레이어가
    // 터미널 레이어 위에 합성돼 **상태바 자신의 항목 텍스트를 덮는다**(S3d에서 헤드리스 캡처로 드러났다).
    try std.testing.expectEqual(@as(u32, 2), bar.layer);

    // **조건 없이 매 프레임 선다** — 도크를 접거나 사이드바를 접어도 사라지면 dock_layout이 깎아 둔 자리에
    // 아무것도 없는 프레임이 나온다.
    sidebar_ops.toggleSidebarCollapsed(session);
    _ = try session.tick();
    var still = false;
    const bar_y2: f32 = @floatFromInt(session.backing_height_px - h);
    for (session.gpu_quads.items) |q| {
        if (q.y == bar_y2 and q.w == @as(f32, @floatFromInt(session.backing_width_px)) and
            q.h == @as(f32, @floatFromInt(h))) still = true;
    }
    try std.testing.expect(still);
}

// 상태바 상단 경계선(§4.0). 배경과 **같은 자리**라 기하만으로는 안 갈린다 — 높이·색·순서 셋으로 못박는다.
test "SB1-S2b: 상태바 상단에 경계선이 서고 배경보다 뒤에 그려진다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1000, 700, 1000);
    _ = try session.tick();

    const h = session.statusBarHeightPx();
    try std.testing.expect(h > 0);
    const border_h = layout_math.ptToPx(status_bar_border_pt, session.scale_milli);
    try std.testing.expect(border_h > 0 and border_h < h);

    const bar_y: f32 = @floatFromInt(session.backing_height_px - h);
    const full_w: f32 = @floatFromInt(session.backing_width_px);
    var bg_i: ?usize = null;
    var line_i: ?usize = null;
    for (session.gpu_quads.items, 0..) |q, i| {
        if (q.y != bar_y or q.w != full_w) continue;
        if (q.h == @as(f32, @floatFromInt(h))) bg_i = i;
        if (q.h == @as(f32, @floatFromInt(border_h))) line_i = i;
    }
    const bi = bg_i orelse return error.StatusBarQuadMissing;
    const li = line_i orelse return error.StatusBarBorderMissing;
    try std.testing.expect(li > bi);
    try std.testing.expectEqual(@as(u32, 2), session.gpu_quads.items[li].layer);
    // 색: 배경과 달라야 선이 보인다(같으면 그린 게 없는 것과 같다).
    try std.testing.expect(session.gpu_quads.items[li].fill_color0 != session.gpu_quads.items[bi].fill_color0);
    // 선은 바 **안**에 있다 — 밖으로 새면 터미널 마지막 행을 덮는다.
    try std.testing.expect(session.gpu_quads.items[li].y + session.gpu_quads.items[li].h <=
        @as(f32, @floatFromInt(session.backing_height_px)));

    // **순서 계약을 호버로 실증한다.** 호버 배경은 슬롯이 바 전체 높이라 선과 같은 자리를 칠한다 — 선이
    // 호버보다 앞에 나가면 호버한 항목 위에서만 선이 끊긴다. 배경보다 뒤라는 것만으로는 이걸 못 잡는다.
    // 이 스모크 세션은 표시할 항목이 없어 tree가 빈다 — 리소스 표시 문자열을 직접 세워 **실제 항목**을
    // 하나 만들고(다른 상태바 테스트와 같은 주입 경로) 그 위에 호버를 건다.
    const ru = maru.session.resource_usage;
    var text_buf: [ru.text_max_bytes]u8 = undefined;
    const text = ru.format(&text_buf, .{ .footprint_bytes = 512 * 1024 * 1024, .cpu_permille = 100 });
    @memcpy(session.resource_text_buf[0..text.len], text);
    session.resource_text_len = text.len;
    // tree 발행은 `collectStatusBarItems`가 한다 — 다른 상태바 렌더 테스트와 같은 직접 호출 경로다.
    var collected: std.ArrayList(AppSession.CollectedPane) = .empty;
    defer {
        for (collected.items) |*c| c.deinit(allocator);
        collected.deinit(allocator);
    }
    session.collectStatusBarItems(&collected, pane_ops.paneFrameBuilder(session), .{ .default_fg = session.appearance.theme.foreground });
    const tree = session.statusBarTree();
    if (tree.entries.len == 0) return error.StatusBarTreeEmpty;
    session.status_bar_hovered = @enumFromInt(tree.entries[0].id);
    session.metal_dirty = true; // chrome을 다시 짓게 한다(안 그러면 앞 프레임 quad가 그대로 남는다)
    _ = try session.tick();

    var hover_i: ?usize = null;
    var line_i2: ?usize = null;
    for (session.gpu_quads.items, 0..) |q, i| {
        if (q.y != bar_y) continue;
        if (q.w == full_w and q.h == @as(f32, @floatFromInt(border_h))) line_i2 = i;
        // 호버는 항목 슬롯 폭(전폭보다 좁다) × 바 전체 높이다.
        if (q.w < full_w and q.h == @as(f32, @floatFromInt(h))) hover_i = i;
    }
    const hi = hover_i orelse return error.StatusBarHoverQuadMissing;
    const li2 = line_i2 orelse return error.StatusBarBorderMissing;
    try std.testing.expect(li2 > hi);
}

// SB1-S2a: 상태바 높이의 **단일 권위는 `dock_layout`**이다. ABI로 나가는 값(사이드바 strip을 자르는 값)과
// 작업영역을 깎은 값이 갈리면 strip이 상태바를 덮거나 그 위에 틈이 생긴다 — 그래서 스탬프가 `dockGeometry()`
// 에서 직접 가져온다. 이 조각은 입력이 0이라 결과도 0이지만, 계약은 지금 고정해 둔다.
test "SB1-S2a: metalFrame의 상태바 높이는 dock_layout 권위와 같다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1000, 700, 1000);
    _ = try session.tick(); // 기하는 투영 스탬프라 한 번 돌려 확정한다

    try std.testing.expectEqual(dock_ops.dockGeometry(session).status_bar.h, session.metalFrame().status_bar_height_px);
    // S2b가 높이를 세웠다 — 이제 실제 값이 나가고, 위 단언이 그 값이 `dock_layout` 권위와 같음을 보장한다.
    try std.testing.expectEqual(session.statusBarHeightPx(), session.metalFrame().status_bar_height_px);
    try std.testing.expect(session.metalFrame().status_bar_height_px > 0);
}

// `placement_failed`는 **이번 배치의 결과만** 뜻해야 한다. 부분 투영(chrome-only) 경로도 `placeAndDistribute`를
// 부르는데 그 분기는 플래그를 읽지도 지우지도 않는다 — 진입에서 지우지 않으면 그때의 실패가 다음 full tick까지
// 살아남아 **멀쩡한 프레임을 한 번 버린다**(가드가 "배치 실패"로 오판). 실제 할당 실패는 주입 경로가 없어
// 자동 재현이 안 되므로, 계약의 절반인 "진입 clear"를 여기서 못박는다.
test "placement_failed: 배치 진입에서 지워진다 — 부분 투영의 옛 실패가 다음 프레임을 죽이지 않는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    var collected: std.ArrayList(AppSession.CollectedPane) = .empty;
    defer collected.deinit(allocator);
    var pane_frames: std.ArrayList(metal_frame.PaneFrame) = .empty;
    defer pane_frames.deinit(allocator);
    var built_frames: std.ArrayList(renderer.RenderFrame) = .empty;
    defer built_frames.deinit(allocator);
    var sidebar_frame: ?renderer.RenderFrame = null;
    var sidebar_header_frame: ?renderer.RenderFrame = null;
    var overlay_frame: ?metal_frame.PaneFrame = null;
    var floating_pf: ?metal_frame.PaneFrame = null;
    var sticky_pf: ?metal_frame.PaneFrame = null;
    var active_result: ?AppSession.ActiveResult = null;

    // 직전(부분 투영) 배치가 실패했다고 가정 — 그 신호가 다음 배치까지 살아남으면 안 된다.
    session.placement_failed = true;
    session.placeAndDistribute(&collected, &pane_frames, &built_frames, &sidebar_frame, &sidebar_header_frame, &overlay_frame, &floating_pf, &sticky_pf, &active_result);
    try std.testing.expect(!session.placement_failed);
}

// 접힘 펼치기 토글(◧) 폴리시: (1) hoverCursor가 토글 위에서 호버 배경 quad를 켜고 밖에서 끈다(접힘 시 사이드바
// 폭 0이라 헤더 호버 경로가 안 타므로 별도 추적), (2) metalFrame이 titlebar_strip_px를 실어 렌더러가 ◧를 띠 안
// 세로 중앙에 정렬(신호등 정렬)할 수 있게 한다. 호버 quad는 distinctive한 fg-반투명 색(packRgbAlpha 0x40)으로 식별.
test "collapsed toggle: hover emits a highlight quad and metalFrame carries titlebar_strip_px" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    sidebar_ops.toggleSidebarCollapsed(session);
    try std.testing.expect(session.sidebar_collapsed);

    // metalFrame이 띠 높이를 실어 렌더러가 ◧를 띠 안 세로 중앙에 정렬할 수 있다(접힘 띠 = max(cell_h, 30pt) > 0).
    // chrome 기하는 **투영 시점 스탬프**라(셀과 한 프레임) tick을 한 번 돌려 확정한 뒤 읽는다 — draw 시점의 live
    // 값을 덮어쓰면 메트릭이 바뀐 프레임에서 옛 셀과 새 기하가 섞인다.
    try std.testing.expect(session.titlebar_strip_px > 0);
    _ = try session.tick();
    try std.testing.expectEqual(session.titlebar_strip_px, session.metalFrame().titlebar_strip_px);

    // 호버 quad를 식별하는 distinctive 색 — 헤더 아이콘 호버와 같은 밝은 fg 반투명(straight-alpha).
    const hover_fill = packRgbAlpha(session.appearance.theme.sidebar_foreground, 0x40);
    const hasHoverQuad = struct {
        fn run(s: *const AppSession, fill: u32) bool {
            for (s.gpu_quads.items) |q| if (q.fill_color0 == fill) return true;
            return false;
        }
    }.run;

    // 클릭 rect는 글리프와 동심이어야 한다 — .m이 ◧를 셀 중심 (col+0.5)·cw 기준 1.7×로 그리므로(maru_fill_cell_quad
    // 중심 확대), rect를 col·cw부터 잡으면 0.5칸 우측으로 치우쳐 글리프 좌측이 안 눌린다(code-review). rect 중심 ==
    // col·cw + cw/2(글리프 중심)인지 고정한다.
    const r = session.collapsedToggleRect().?;
    {
        const cw_i: i32 = @intCast(session.cell_width_px);
        const glyph_center = @as(i32, session.collapsedToggleCol()) * cw_i + @divTrunc(cw_i, 2);
        try std.testing.expectEqual(glyph_center, r.x + @as(i32, @intCast(r.w / 2)));
    }
    // 토글 밖(띠 빈 곳) 호버 → 호버 off, 호버 quad 없음.
    const far_x: f64 = @floatFromInt(r.x + @as(i32, @intCast(r.w)) + 100);
    _ = session.hoverCursor(far_x, 1, 0);
    try std.testing.expect(!session.hovered_collapsed_toggle);
    try std.testing.expect(!hasHoverQuad(session, hover_fill));

    // 토글 중심 호버 → pointingHand(.link) + 호버 on + 호버 quad 방출.
    const cx: f64 = @floatFromInt(r.x + @as(i32, @intCast(r.w / 2)));
    const cy: f64 = @floatFromInt(@as(i32, @intCast(r.h / 2)));
    try std.testing.expectEqual(CursorKind.link, session.hoverCursor(cx, cy, 0));
    try std.testing.expect(session.hovered_collapsed_toggle);
    try std.testing.expect(hasHoverQuad(session, hover_fill));

    // 다시 밖으로 → 호버 off, quad 제거(rebuildSidebar가 다시 비움).
    _ = session.hoverCursor(far_x, 1, 0);
    try std.testing.expect(!session.hovered_collapsed_toggle);
    try std.testing.expect(!hasHoverQuad(session, hover_fill));
}

// 알림 배지 원(GPU quad, layer 4)은 그 위에 올라가는 흰 숫자(헤더 frame 셀)를 **가로·세로 모두** 감싸야 한다.
// 가로는 notificationBadgeCol이 단일 출처라 원래 맞았지만, 세로는 오래 어긋나 있었다: 원은 `ch*0.46`으로 "헤더
// 아이콘 줄이 y=0에서 시작한다"를 가정했는데 렌더러는 그 줄만 신호등 띠 안 세로 중앙에 놓는다
// (maru_metal_renderer.m `py_top = (strip - ch) * 0.5`). 띠가 셀보다 높은 실제 창에서 원만 위로 떠 숫자가
// 원 밖으로 빠져나갔고, 좌표 계측은 origin 0인 실행에서만 돌아 다섯 번을 통과했다.
//
// 그래서 이 판정자는 헬퍼를 호출하지 않고 **렌더러 공식을 그대로 다시 푼다** — 소비되는 ABI 값
// (metalFrame().titlebar_strip_px)에서 셀 줄 y를 재구성해 원이 그 줄을 덮는지 본다. 헬퍼를 부르면
// 두 쪽이 같이 틀려도 통과하므로 판정자가 아니게 된다.
test "notification badge circle vertically contains the header icon row the renderer draws the digit on" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    _ = notification_ops.pushNotificationHistory(session, "t", "b", 0); // 안읽음 1 → 펼침 헤더에 배지
    try std.testing.expect(!session.sidebar_collapsed);
    _ = try session.tick(); // chrome 기하는 투영 시점 스탬프 — 한 프레임 확정 후 읽는다

    const ch = session.cell_height_px;
    const strip = session.metalFrame().titlebar_strip_px;
    // 띠 > 셀이어야 이 판정자가 의미를 갖는다(둘이 같으면 py_top이 0이라 옛 코드도 통과한다).
    try std.testing.expect(strip > ch);
    // 렌더러가 헤더 아이콘 줄 셀에 쓰는 py_top — 공식을 여기서 다시 푼다.
    const row_top: f32 = @floatFromInt((strip - ch) / 2);
    try std.testing.expect(row_top > 0); // 0이면 옛 코드(원점 무시)와 구분이 안 돼 판정자가 아니게 된다

    // 제품이 낸 배지 원을 찾는다: layer 4 + 정사각(w==h) + 반지름 = w/2.
    var circle: ?metal_frame.GpuQuad = null;
    for (session.gpu_quads.items) |q| {
        if (q.layer != 4 or q.w != q.h or q.corner_radii[0] != q.w / 2.0) continue;
        circle = q;
    }
    const c = circle orelse return error.BadgeCircleMissing;

    // 원 중심 == 렌더러 줄 원점 + 셀 안 nudge. **포함(원이 숫자를 삼키는가)으로는 부족하다** — 원 지름이
    // 셀 높이의 0.82배라 원점을 통째로 빠뜨려도 숫자가 원 안에 남아 통과한다(실제로 통과시켜 봤다).
    // 고정해야 하는 것은 "원과 셀이 같은 원점을 쓰는가"이므로 등식으로 잡는다.
    const digit_center_y: f32 = row_top + @as(f32, @floatFromInt(ch)) * notification_ops.notification_badge_center_in_cell;
    const circle_center_y: f32 = c.y + c.h / 2.0;
    try std.testing.expectApproxEqAbs(digit_center_y, circle_center_y, 0.01);

    // 가로는 notificationBadgeCol 단일 출처 — 원 중심 == 그 셀의 중심.
    const cols: u16 = @intCast(session.sidebar_width_px / session.cell_width_px);
    const badge_col = notification_ops.notificationBadgeCol(cols - 12);
    const cell_center_x: f32 = (@as(f32, @floatFromInt(badge_col)) + 0.5) * @as(f32, @floatFromInt(session.cell_width_px));
    try std.testing.expectApproxEqAbs(cell_center_x, c.x + c.w / 2.0, 0.01);
}

// 접힘에도 알림 종 유지: 좌상단 띠에 ◧ 오른쪽 종(collapsedBellCol=collapsedToggleCol+3)을 그리고, 그 클릭 rect는
// 종 글리프와 동심·◧ rect와 비겹침이며, 클릭하면 알림 패널이 열린다(접힘 분기 anchor). 드러난-것=클릭되는-것 단일 출처.
test "collapsed notification bell: hit-test rect is concentric with the glyph, clears the ◧ toggle, and opens the panel" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    try std.testing.expect(notification_ops.collapsedNotificationRect(session) == null); // 펼침일 땐 종 rect 없음(접힘 전제)
    _ = notification_ops.pushNotificationHistory(session, "t", "b", 0); // 안읽음 1 → 배지 표시(종 좌측)
    sidebar_ops.toggleSidebarCollapsed(session);
    try std.testing.expect(session.sidebar_collapsed);

    // 종이 ◧ '왼쪽'(펼침과 같은 순서) — collapsedToggleCol = collapsedBellCol + 3(아이콘 간격 단일 출처). 토글↔펼침 swap 방지.
    try std.testing.expectEqual(notification_ops.collapsedBellCol(session) + @as(u16, 3), session.collapsedToggleCol());

    const cw_i: i32 = @intCast(session.cell_width_px);
    const r = notification_ops.collapsedNotificationRect(session).?;
    // rect 높이 = 타이틀바 띠 전체(데드존 방지 — collapsedToggleRect와 같은 규약).
    try std.testing.expectEqual(session.titlebar_strip_px, r.h);
    // 클릭 rect 중심 == 종 글리프 시각 중심 (bell_col+0.5)·cw(렌더러 −0.5칸 px_nudge 반영; (3cw)/2 == cw + cw/2라 홀/짝 cw 무관).
    const bell_center = @as(i32, notification_ops.collapsedBellCol(session)) * cw_i + @divTrunc(cw_i, 2);
    try std.testing.expectEqual(bell_center, r.x + @as(i32, @intCast(r.w / 2)));
    // 종 rect(왼쪽)와 ◧ 토글 rect(오른쪽)는 안 겹친다(클릭 모호성 없음) — 종 우단 ≤ 토글 좌단.
    const t = session.collapsedToggleRect().?;
    try std.testing.expect(t.x >= r.x + @as(i32, @intCast(r.w)));

    // 종 클릭 → 알림 패널 열림(접힘 분기 anchor). 종은 ◧와 별개라 펼치지 않는다(폭 0 유지).
    const cx: f64 = @floatFromInt(r.x + @as(i32, @intCast(r.w / 2)));
    const cy: f64 = @floatFromInt(@as(i32, @intCast(r.h / 2)));
    session.mouse(1, cx, cy, 0, 0);
    try std.testing.expect(session.chrome_host.notifications.open);
    try std.testing.expect(session.sidebar_collapsed); // 종 클릭은 펼치지 않는다(◧와 별개 영역)
}

// window.opacity(F1-1): ResolvedAppearance.window_opacity가 metalFrame.window_opacity_milli(×1000, 0~1000)로 실린다.
// 렌더러가 이 값/1000을 화면 clear color alpha에 곱해 default 배경만 투명해진다(명시적 배경색 셀은 셀 quad라 불변).
test "window.opacity → metalFrame.window_opacity_milli ×1000 (F1-1)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // 기본(불투명) → 1000.
    try std.testing.expectEqual(@as(u32, 1000), session.metalFrame().window_opacity_milli);

    // 0.6 → 600(반올림).
    session.appearance.window_opacity = 0.6;
    try std.testing.expectEqual(@as(u32, 600), session.metalFrame().window_opacity_milli);

    // 0.0(완전 투명) → 0.
    session.appearance.window_opacity = 0.0;
    try std.testing.expectEqual(@as(u32, 0), session.metalFrame().window_opacity_milli);
}

// 멀티-탭 핵심 계약: 두 번째 탭을 만들면 자기 셸 PTY가 spawn되고, tick이 '모든' 탭을 drain하므로
// 그 탭 surface가 자기 출력을 받는다(백그라운드여도). 실 PTY라 macOS 게이트 — 약속한 "탭 2개 동시
// 출력" 반-E2E를 결정적으로 고정한다. switchTab이 활성 라우팅을 바꾸는 것도 함께 검증.
test "two tabs: createTab spawns a second shell and tick drains both (multi-tab)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    try std.testing.expectEqual(@as(usize, 1), session.tabs.items.len);

    // 2번째 탭: 알려진 마커를 출력하고 cat으로 stdin을 읽으며 살아 있는 controlled 셸. createTab이 Tab을
    // heap-pin하고 같은 runtime에 별개 surface_id로 attach한다. 새 탭이 활성이 된다. (printf만 쓰면 셸이 즉시
    // exit해 PR5b reap이 탭을 닫으므로, 멀티-탭 drain을 관측하려면 탭이 살아 있어야 한다 — cat으로 유지.)
    _ = try tab_ops.createTab(
        session,
        .{ .command = "/bin/sh", .args = &.{ "-c", "printf 'TAB_TWO_MARK\\n'; cat" }, .size = .{ .cols = 20, .rows = 5 } },
        .{ .cols = 20, .rows = 5 },
        16,
        "tab 2",
        "sh",
    );
    try std.testing.expectEqual(@as(usize, 2), session.tabs.items.len);
    try std.testing.expectEqual(@as(usize, 1), session.app_window.active_tab);

    // tick이 모든 탭을 drain → 2번째 탭 surface가 자기 셸 출력을 받는다(멀티-탭 drain).
    var saw = false;
    var i: usize = 0;
    while (i < 400 and !saw) : (i += 1) {
        _ = try session.tick();
        const dump = try session.tabs.items[1].activePane().activeTerm().surface.core.dumpUtf8(allocator);
        defer allocator.free(dump);
        if (std.mem.indexOf(u8, dump, "TAB_TWO_MARK") != null) saw = true;
    }
    try std.testing.expect(saw);

    // switchTab으로 활성 탭을 0으로 — activeSurface가 탭 0 surface를 가리킨다(라우팅 전환).
    try std.testing.expect(tab_ops.switchTab(session, 0));
    try std.testing.expectEqual(session.tabs.items[0].activePane().activeTerm().surface.id, term_ops.activeSurface(session).id);
    try std.testing.expect(!tab_ops.switchTab(session, 5)); // 범위 밖이면 false, 활성 불변
    try std.testing.expectEqual(@as(usize, 0), session.app_window.active_tab);
}

// Cmd+T가 키 경로(handleKeyEvent → resolver → app_action)로 '활성 pane에 새 Term(가로 탭)'을 열고,
// Cmd+Shift+T가 '새 워크스페이스'를 여는지 — 탭 풀 모델. native 최소(Swift는 키만, 판정·실행은 Zig).
// 실 PTY라 macOS 게이트.
test "Cmd+T opens a new Term in the active pane; Cmd+Shift+T opens a workspace" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    try std.testing.expectEqual(@as(usize, 1), session.tabs.items.len);
    try std.testing.expectEqual(@as(usize, 1), pane_ops.activePane(session).terms.items.len);

    // Cmd+T → new_term → 활성 pane에 Term 추가(워크스페이스 수 불변), 새 Term이 활성.
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 't' }, .modifiers = .{ .command = true } });
    try std.testing.expectEqual(@as(usize, 1), session.tabs.items.len);
    try std.testing.expectEqual(@as(usize, 2), pane_ops.activePane(session).terms.items.len);
    try std.testing.expectEqual(@as(usize, 1), pane_ops.activePane(session).active_term);
    try std.testing.expect(session.total_app_key_events >= 1); // 앱 액션으로 회계(PTY로 안 샘)

    // Cmd+Shift+T → new_tab → 새 워크스페이스(활성), 그 워크스페이스는 Term 1개로 시작.
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'T' }, .modifiers = .{ .command = true, .shift = true } });
    try std.testing.expectEqual(@as(usize, 2), session.tabs.items.len);
    try std.testing.expectEqual(@as(usize, 1), session.app_window.active_tab);
    try std.testing.expectEqual(@as(usize, 1), pane_ops.activePane(session).terms.items.len);

    // 안 묶인 Cmd 조합(Cmd+S)은 아무것도 안 만들고 무시(ignored).
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 's' }, .modifiers = .{ .command = true } });
    try std.testing.expectEqual(@as(usize, 2), session.tabs.items.len);
}

// Cmd+1~9가 N번째 워크스페이스(사이드바 탭)로 전환하는지(select_tab) — 사용자 요청. 범위 밖(탭보다 큰 번호)은
// no-op. 실 init/spawn이라 macOS 게이트.
test "Cmd+1..9 switches to the Nth workspace (out-of-range is a no-op)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // 워크스페이스 3개(⌘⇧T 두 번). 활성 = 마지막(2).
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'T' }, .modifiers = .{ .command = true, .shift = true } });
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'T' }, .modifiers = .{ .command = true, .shift = true } });
    try std.testing.expectEqual(@as(usize, 3), session.tabs.items.len);
    try std.testing.expectEqual(@as(usize, 2), session.app_window.active_tab);

    // Cmd+1 → 워크스페이스 0.
    _ = try session.handleKeyEvent(.{ .key = .{ .char = '1' }, .modifiers = .{ .command = true } });
    try std.testing.expectEqual(@as(usize, 0), session.app_window.active_tab);
    // Cmd+3 → 워크스페이스 2.
    _ = try session.handleKeyEvent(.{ .key = .{ .char = '3' }, .modifiers = .{ .command = true } });
    try std.testing.expectEqual(@as(usize, 2), session.app_window.active_tab);
    // Cmd+2 → 워크스페이스 1.
    _ = try session.handleKeyEvent(.{ .key = .{ .char = '2' }, .modifiers = .{ .command = true } });
    try std.testing.expectEqual(@as(usize, 1), session.app_window.active_tab);
    // Cmd+9 → 9번째 없음(3개뿐) → no-op(활성 불변).
    _ = try session.handleKeyEvent(.{ .key = .{ .char = '9' }, .modifiers = .{ .command = true } });
    try std.testing.expectEqual(@as(usize, 1), session.app_window.active_tab);
}

// handleKeyEvent가 사용자 config의 keybind를 적용하는지(빈 resolver가 아니라 loaded_config.keyBindingResolver())
// — 기본엔 없는 조합(Cmd+E)을 사용자 바인딩으로 new_term에 묶어 실제로 디스패치되는지 본다. 실 PTY라 macOS 게이트.
test "handleKeyEvent applies user config keybindings (resolver wired from loaded_config)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // 사용자 keybind 주입: Cmd+E = new_term(기본 바인딩엔 없는 조합). keybindings 슬라이스만 바꾼다(arena·appearance
    // 빌림은 그대로) — handleKeyEvent가 loaded_config.keyBindingResolver()를 읽으므로 이게 곧 사용자 config 효과다.
    var user_binds = [_]config_mod.AppBinding{
        .{ .chord = try config_mod.KeyChord.parse("Cmd+E"), .action = .new_term },
    };
    session.loaded_config.keybindings = &user_binds;

    // Cmd+E는 빈 resolver였다면 ignored지만, 사용자 바인딩이 먹어 활성 pane에 Term이 추가된다.
    try std.testing.expectEqual(@as(usize, 1), pane_ops.activePane(session).terms.items.len);
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'e' }, .modifiers = .{ .command = true } });
    try std.testing.expectEqual(@as(usize, 2), pane_ops.activePane(session).terms.items.len);

    // 사용자 바인딩에 없는 기본 조합(Cmd+T)도 여전히 동작한다(resolver가 default_app_bindings로 폴백).
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 't' }, .modifiers = .{ .command = true } });
    try std.testing.expectEqual(@as(usize, 3), pane_ops.activePane(session).terms.items.len);
}

test "web app action dispatch bypasses terminal preprocessing and rejects a stale route" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    var user_binds = [_]config_mod.AppBinding{
        .{ .chord = try config_mod.KeyChord.parse("Cmd+C"), .action = .new_tab },
        .{ .chord = try config_mod.KeyChord.parse("Cmd+V"), .action = .new_term },
        .{ .chord = try config_mod.KeyChord.parse("Cmd+Backspace"), .action = .new_term },
    };
    session.loaded_config.keybindings = &user_binds;
    const browser_sid = try pane_ops.appendWebTermInActivePane(session, .browser);
    const copy: terminal.KeyEvent = .{ .key = .{ .char = 'c' }, .modifiers = .{ .command = true } };
    try std.testing.expectEqual(config_mod.keybinding.WebKeyRoute.app_action, web_ops.webKeyRoute(session, 0, copy));
    try std.testing.expect(!web_ops.dispatchWebAppAction(session, 0, copy)); // invalid sentinel은 action provenance가 아니다.
    const tabs_before = session.tabs.items.len;
    try std.testing.expect(web_ops.dispatchWebAppAction(session, browser_sid, copy));
    try std.testing.expectEqual(tabs_before + 1, session.tabs.items.len);
    try std.testing.expect(tab_ops.switchTab(session, 0)); // browser가 active인 원래 workspace로 복귀한다.

    // route 조회 뒤 config가 reload됐다고 가정한다. Swift는 이미 이벤트를 consume하지만 현재 resolver가 더는 app
    // action을 내지 않으므로 stale Action을 실행하지 않는다.
    const paste: terminal.KeyEvent = .{ .key = .{ .char = 'v' }, .modifiers = .{ .command = true } };
    try std.testing.expectEqual(config_mod.keybinding.WebKeyRoute.app_action, web_ops.webKeyRoute(session, browser_sid, paste));
    session.loaded_config.keybindings = &.{};
    const terms_before_stale = pane_ops.activePane(session).terms.items.len;
    try std.testing.expect(!web_ops.dispatchWebAppAction(session, browser_sid, paste));
    try std.testing.expectEqual(terms_before_stale, pane_ops.activePane(session).terms.items.len);

    session.loaded_config.keybindings = &user_binds;
    try std.testing.expect(web_ops.dispatchWebAppAction(session, browser_sid, paste));
    const line_edit: terminal.KeyEvent = .{ .key = .backspace, .modifiers = .{ .command = true } };
    try std.testing.expectEqual(config_mod.keybinding.WebKeyRoute.app_action, web_ops.webKeyRoute(session, browser_sid, line_edit));
    try std.testing.expect(!web_ops.dispatchWebAppAction(session, browser_sid, line_edit)); // browser는 이제 background Term이다.
    try std.testing.expectEqual(terms_before_stale + 1, pane_ops.activePane(session).terms.items.len);
    term_ops.focusTerm(session, 1);
    try std.testing.expect(web_ops.dispatchWebAppAction(session, browser_sid, line_edit));
    try std.testing.expectEqual(terms_before_stale + 2, pane_ops.activePane(session).terms.items.len);
    try std.testing.expectEqual(@as(u64, 3), session.total_app_key_events);
    try std.testing.expectEqual(@as(u64, 0), session.total_terminal_input_events);
}

// Term 생명주기: ⌘T가 활성 pane에 Term을 쌓고, ⌘]/⌘[가 Term을 wrap 순환하고, ⌘W가 Term →(마지막이면)
// pane →(마지막이면) 워크스페이스 순으로 cascade close하는지 — 실 PTY teardown이라 macOS 게이트. 키 경로 전체.
test "Term lifecycle: Cmd+T adds, Cmd+Opt+]/[ cycle, Cmd+W cascades Term to workspace" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    const cmd: terminal.ModifierSet = .{ .command = true };

    // ⌘T 두 번 → 활성 pane Term 3개(0,1,2), 활성 Term 2(마지막). 워크스페이스/ pane 수는 불변.
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 't' }, .modifiers = cmd });
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 't' }, .modifiers = cmd });
    try std.testing.expectEqual(@as(usize, 1), session.tabs.items.len);
    try std.testing.expectEqual(@as(usize, 1), tab_ops.activeTab(session).panes.items.len);
    try std.testing.expectEqual(@as(usize, 3), pane_ops.activePane(session).terms.items.len);
    try std.testing.expectEqual(@as(usize, 2), pane_ops.activePane(session).active_term);
    markAllTermsAtPrompt(session); // idle 셸 흉내 — 이후 ⌘W cascade가 확인 모달 없이 즉시 진행되게(닫힌 뒤 남는 Term도 유지)

    // ⌘⌥] → 다음(wrap): 2→0. ⌘⌥[ → 이전(wrap): 0→2. (⌘[]는 이제 split 순환이라 Term 순환은 ⌘⌥[]로 옮겼다.)
    const cmd_opt: terminal.ModifierSet = .{ .command = true, .option = true };
    _ = try session.handleKeyEvent(.{ .key = .{ .char = ']' }, .modifiers = cmd_opt });
    try std.testing.expectEqual(@as(usize, 0), pane_ops.activePane(session).active_term);
    _ = try session.handleKeyEvent(.{ .key = .{ .char = '[' }, .modifiers = cmd_opt });
    try std.testing.expectEqual(@as(usize, 2), pane_ops.activePane(session).active_term);

    // ⌘W → 활성 Term(2) 닫힘 → Term 2개, 활성 1(보정). pane/워크스페이스 수 불변.
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'w' }, .modifiers = cmd });
    try std.testing.expectEqual(@as(usize, 2), pane_ops.activePane(session).terms.items.len);
    try std.testing.expectEqual(@as(usize, 1), pane_ops.activePane(session).active_term);
    try std.testing.expectEqual(@as(usize, 1), tab_ops.activeTab(session).panes.items.len);

    // ⌘W → Term(1) 닫힘 → Term 1개. 아직 pane/워크스페이스 그대로(세션 유지).
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'w' }, .modifiers = cmd });
    try std.testing.expectEqual(@as(usize, 1), pane_ops.activePane(session).terms.items.len);
    try std.testing.expect(!session.ended_seen);

    // ⌘W → 이제 Term 1·pane 1·워크스페이스 1 → 마지막 워크스페이스 close = 세션 종료 latch(cascade 끝).
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'w' }, .modifiers = cmd });
    try std.testing.expect(session.ended_seen);
}

// Cmd+]/[ 가 키 경로(handleKeyEvent → resolver → app_action)로 split(pane)을 순환하는지 — 실 PTY라 macOS
// 게이트. ⌘D로 pane 2개 만든 뒤 ⌘]는 활성 pane을 다음으로, ⌘[는 이전(wrap)으로 옮긴다. (⌘[]는 Term이 아니라
// split 순환 — Term은 ⌘⌥[]로 옮겼다, 사용자 요청 배치.)
test "Cmd bracket keys cycle split panes through the key path" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    const cmd: terminal.ModifierSet = .{ .command = true };
    // ⌘D=좌우 split → 활성 워크스페이스에 pane 2개(splitActivePane이 새 pane으로 포커스).
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'd' }, .modifiers = cmd });
    try std.testing.expectEqual(@as(usize, 2), tab_ops.activeTab(session).panes.items.len);
    const start = tab_ops.activeTab(session).active_pane;
    // ⌘] → 다음 pane(wrap, 2개라 토글), ⌘[ → 다시 원래.
    _ = try session.handleKeyEvent(.{ .key = .{ .char = ']' }, .modifiers = cmd });
    try std.testing.expectEqual((start + 1) % 2, tab_ops.activeTab(session).active_pane);
    _ = try session.handleKeyEvent(.{ .key = .{ .char = '[' }, .modifiers = cmd });
    try std.testing.expectEqual(start, tab_ops.activeTab(session).active_pane);
}

// Cmd+Shift+]/[ 가 키 경로(handleKeyEvent → resolver → app_action)로 다음/이전 탭을 순환하는지 — 실
// PTY라 macOS 게이트. 2탭에서 ]는 활성을 1→0, [는 0→1(wrap)으로 옮긴다.
test "Cmd+Shift bracket keys cycle tabs through the key path" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'T' }, .modifiers = .{ .command = true, .shift = true } }); // ⌘⇧T=새 워크스페이스 → 2탭, 활성 1
    try std.testing.expectEqual(@as(usize, 2), session.tabs.items.len);
    try std.testing.expectEqual(@as(usize, 1), session.app_window.active_tab);

    // Cmd+Shift+] → next_tab → (1+1)%2 = 0.
    _ = try session.handleKeyEvent(.{ .key = .{ .char = ']' }, .modifiers = .{ .command = true, .shift = true } });
    try std.testing.expectEqual(@as(usize, 0), session.app_window.active_tab);
    // Cmd+Shift+[ → previous_tab → (0+2-1)%2 = 1(wrap).
    _ = try session.handleKeyEvent(.{ .key = .{ .char = '[' }, .modifiers = .{ .command = true, .shift = true } });
    try std.testing.expectEqual(@as(usize, 1), session.app_window.active_tab);
    // 닫는 중괄호 변형(}/{)도 같은 액션(OS가 Shift를 적용해 줄 수 있음).
    _ = try session.handleKeyEvent(.{ .key = .{ .char = '}' }, .modifiers = .{ .command = true, .shift = true } });
    try std.testing.expectEqual(@as(usize, 0), session.app_window.active_tab);
}

// closeTab이 탭을 teardown하고 active_tab을 재선택하며, 마지막 탭은 창(세션) 종료로 latch하는지 — 실
// PTY teardown(detach + reader join)이라 macOS 게이트. cat는 PTY가 닫힐 때까지 살아 있어 live 탭 teardown을 본다.
test "closeTab tears down a tab and reselects, last tab closes the session" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // 살아있는 탭 2개 더(cat은 PTY 닫힐 때까지 stdin을 읽으며 대기). 활성=2.
    inline for (.{ "tab 2", "tab 3" }) |title| {
        _ = try tab_ops.createTab(
            session,
            .{ .command = "/bin/sh", .args = &.{ "-c", "cat" }, .size = .{ .cols = 20, .rows = 5 } },
            .{ .cols = 20, .rows = 5 },
            16,
            title,
            "sh",
        );
    }
    try std.testing.expectEqual(@as(usize, 3), session.tabs.items.len);
    try std.testing.expectEqual(@as(usize, 2), session.app_window.active_tab);

    // 백그라운드 탭 0 닫기 → 2탭, 인덱스 밀림으로 active 2→1.
    tab_ops.closeTab(session, 0);
    try std.testing.expectEqual(@as(usize, 2), session.tabs.items.len);
    try std.testing.expectEqual(@as(usize, 1), session.app_window.active_tab);

    // 활성 탭(=마지막 인덱스 1) 닫기 → 1탭, active clamp 0.
    tab_ops.closeTab(session, 1);
    try std.testing.expectEqual(@as(usize, 1), session.tabs.items.len);
    try std.testing.expectEqual(@as(usize, 0), session.app_window.active_tab);
    try std.testing.expect(!session.ended_seen);

    // 마지막 탭 닫기 → 창 닫힘(종료 latch). 탭은 헐지 않고(빈 리스트 패닉 회피) deinit이 정리한다.
    tab_ops.closeTab(session, 0);
    try std.testing.expectEqual(@as(usize, 1), session.tabs.items.len);
    try std.testing.expect(session.ended_seen);
}

test "C3-3b5 AppSession은 in-process multi-Term complete 뒤에만 topology를 갱신한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionTwoTerms(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    markAllTermsAtPrompt(session);
    const pane = pane_ops.activePane(session);
    const before = pane.terms.items.len;
    term_ops.closeTermAt(session, session.app_window.active_tab, pane, pane.active_term);
    try std.testing.expectEqual(before - 1, pane.terms.items.len);
}

test "C3-3b4 async close parity는 실제 AppSession tab topology를 pending 동안 보존한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionTwoTerms(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    defer app.term_runtime_backend.testing.clear();
    markAllTermsAtPrompt(session);
    const pane = pane_ops.activePane(session);
    const target = pane.activeTerm();
    const terms_before = pane.terms.items.len;
    const active_before = pane.active_term;

    app.term_runtime_backend.testing.armCloseSequence(&.{.event_pending});
    term_ops.closeTermAt(session, session.app_window.active_tab, pane, pane.active_term);
    try std.testing.expectEqual(terms_before, pane.terms.items.len);
    try std.testing.expectEqual(active_before, pane.active_term);
