test "FP16 파일 패널은 eviction하지 않는다 — 열린 entry는 surface를 잃지 않는다" {
    // FP16 §1 불변식: LRU를 제거했으므로 non-dirty·비활성 entry도 surface_id를 유지한다. 옛 FP6 테스트는
    // "non-dirty가 회수된다"를 고정했는데, 그 정책 자체가 사라져 반대 방향으로 다시 쓴다(docs/file-panel.md §1).
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const io = std.Io.Threaded.global_single_threaded.io();
    var root_buf: [std.fs.max_path_bytes]u8 = undefined;
    const root = root_buf[0..try tmp.dir.realPath(io, &root_buf)];
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(io, allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1400, 900, 1000);

    // 파일 여러 개를 연다 — 옛 상한(기본 8)을 넘겨도 아무도 회수되지 않아야 한다.
    var paths: [12][]u8 = undefined;
    var opened: usize = 0;
    defer for (paths[0..opened]) |p| allocator.free(p);
    while (opened < paths.len) : (opened += 1) {
        var name_buf: [32]u8 = undefined;
        const name = try std.fmt.bufPrint(&name_buf, "lru-{d}.md", .{opened});
        try tmp.dir.writeFile(io, .{ .sub_path = name, .data = "# x" });
        paths[opened] = try std.fs.path.join(allocator, &.{ root, name });
        try std.testing.expectEqual(AppSession.FilePanelOpenPathResult.opened, file_panel_ops.openFilePanelPath(session, paths[opened]));
    }

    // 전 entry가 surface_id를 갖고 있고 서로 다르다(비재사용).
    var seen: [12]u64 = undefined;
    var n: usize = 0;
    var it = file_panel_ops.fileEntries(session);
    while (it.next()) |entry| {
        try std.testing.expect(entry.surface_id != 0); // 회수 0
        for (seen[0..n]) |prior| try std.testing.expect(prior != entry.surface_id);
        seen[n] = entry.surface_id;
        n += 1;
    }
    try std.testing.expectEqual(paths.len, n);
}

test "FP6 merge transfers dirty file state and live surface ownership before source teardown" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const src = try initSmokeSessionSized(allocator);
    defer allocator.destroy(src);
    defer src.deinit();
    const dst = try initSmokeSessionSized(allocator);
    defer allocator.destroy(dst);
    defer dst.deinit();

    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    try tmp.dir.writeFile(std.testing.io, .{ .sub_path = "src.md", .data = "src" });
    try tmp.dir.writeFile(std.testing.io, .{ .sub_path = "dst.md", .data = "dst" });
    var root_buf: [std.fs.max_path_bytes]u8 = undefined;
    const root = root_buf[0..try tmp.dir.realPath(std.testing.io, &root_buf)];
    const src_path = try std.fmt.allocPrint(allocator, "{s}/src.md", .{root});
    defer allocator.free(src_path);
    const dst_path = try std.fmt.allocPrint(allocator, "{s}/dst.md", .{root});
    defer allocator.free(dst_path);
    try std.testing.expectEqual(AppSession.FilePanelOpenPathResult.opened, file_panel_ops.openFilePanelPath(src, src_path));
    try std.testing.expectEqual(AppSession.FilePanelOpenPathResult.opened, file_panel_ops.openFilePanelPath(dst, dst_path));
    try src.file_tree.replaceExplicitRoots(&.{"/source-workspace"});
    try dst.file_tree.replaceExplicitRoots(&.{"/destination-workspace"});
    try std.testing.expect(src.completePendingDockFocus(src.fileEntryAt(0).?.surface_id));
    try std.testing.expect(dst.completePendingDockFocus(dst.fileEntryAt(0).?.surface_id));
    const moved_sid = file_panel_ops.fileEntryForPath(src, src_path).?.surface_id;
    try file_panel_ops.setFilePanelDirty(src, moved_sid, true);
    const source_entry = file_panel_ops.fileEntryForPath(src, src_path).?;
    source_entry.mode = .source_edit;
    const moved_entry_id = source_entry.id;
    dock_ops.requestDockEntryFocus(src, source_entry);
    const src_epoch_before = src.dock_async_epoch;
    const dst_epoch_before = dst.dock_async_epoch;

    var moved_buf: [16]u64 = undefined;
    const outcome = try src.mergeSessionInto(dst, &moved_buf);
    try std.testing.expect(outcome.source_window_closed);
    try std.testing.expectEqual(@as(usize, 0), file_panel_ops.fileEntryCount(src));
    try std.testing.expect(!web_ops.hasWebSurface(src, moved_sid));
    try std.testing.expect(web_ops.hasWebSurface(dst, moved_sid));
    try std.testing.expectEqual(file_tree.RootMode.explicit, dst.file_tree.rootMode());
    try std.testing.expectEqualStrings("/destination-workspace", dst.file_tree.rootAt(0).?);
    try std.testing.expectEqualStrings("/source-workspace", src.file_tree.rootAt(0).?);
    const moved_entry = file_panel_ops.fileEntryForSurfaceId(dst, moved_sid).?;
    try std.testing.expect(moved_entry.dirty);
    try std.testing.expectEqual(dock_panel.Mode.source_edit, moved_entry.mode);
    try std.testing.expect(std.mem.indexOfScalar(u64, outcome.moved_surfaces, moved_sid) != null);
    try std.testing.expect(src.pending_dock_focus == null);
    try std.testing.expect(src.dock_async_epoch > src_epoch_before);
    try std.testing.expect(dst.dock_async_epoch > dst_epoch_before);
    // FP16: merge는 destination이 **보던** 워크스페이스를 유지하므로 옮겨온 파일은 배경 워크스페이스에 앉는다.
    // 보이지 않는 파일에 publish 대기 barrier를 재발급하면 화면에 있는 워크스페이스의 입력을 그 파일이
    // 삼킨다 — 그래서 token을 재발급하지 않고 입력은 workspace가 갖는다.
    try std.testing.expect(dst.pending_dock_focus == null);
    // dst가 보던 자기 파일이 계속 입력 소유다 — 배경으로 온 파일이 그것을 빼앗지 않는다.
    try std.testing.expect(dst.focus_owner != .dock_pending);
    // 옮겨온 파일과 그 dirty 상태·live surface는 그대로 살아 있다(배경일 뿐 사라지지 않는다).
    try std.testing.expect(file_panel_ops.fileEntryForId(dst, moved_entry_id) != null);
    try std.testing.expect(file_panel_ops.fileEntryForId(dst, moved_entry_id).?.dirty);
    try std.testing.expect(web_ops.hasWebSurface(dst, moved_sid));
    // 그 워크스페이스로 전환하면 다시 보이고, 그때 barrier를 새로 걸 수 있다.
    for (dst.tabs.items, 0..) |t, ti| {
        for (t.panes.items) |pane| {
            for (pane.terms.items) |term| {
                const e = term.file_entry orelse continue;
                if (e.id != moved_entry_id) continue;
                _ = tab_ops.switchTab(dst, ti);
            }
        }
    }
    dock_ops.requestDockEntryFocus(dst, file_panel_ops.fileEntryForId(dst, moved_entry_id).?);
    try std.testing.expect(dock_ops.pendingDockEntryOwnsInput(dst));
    try std.testing.expect(dst.completePendingDockFocus(moved_sid));
}

