    try std.testing.expect(notification_ops.takeBell(dst));
    try std.testing.expectEqual(@as(u64, 12), runtime.event_cursor.bell_count);
}

// browser 전용 chrome(주소창 밴드)이 파일/markdown web Term에 걸리지 않는다는 것을 `isBrowserTerm` 한 곳으로
// 고정한다. FP16이 파일 entry를 Term으로 옮기면 `.html`/`.pdf` 파일 Term이 격리 config 때문에
// `web_panel_kind == .browser`를 갖게 되는데, 그때 이 술어에 조건 하나만 더하면 모든 소비처가 함께 고쳐진다
// (docs/file-panel.md §8). 인라인 비교가 흩어져 있으면 그 확장에서 반드시 한 곳을 놓친다.
test "browser 전용 판정은 isBrowserTerm 하나가 소유한다 — markdown web Term은 주소창 밴드가 없다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1400, 900, 1000);

    const pane = pane_ops.activePane(session);
    try pane_ops.newWebTermInActivePane(session, .markdown);
    const md = pane.activeTerm();
    try std.testing.expect(md.kind == .web and md.web_panel_kind == .markdown);
    try std.testing.expect(!web_ops.isBrowserTerm(md)); // 술어가 갈라낸다

    try pane_ops.newWebTermInActivePane(session, .browser);
    const browser = pane.activeTerm();
    try std.testing.expect(web_ops.isBrowserTerm(browser));

    // 소비처 검증: 주소창 밴드는 browser에만 top inset을 더한다(bar_h vs 2*bar_h).
    const bar_h = pane_ops.paneBarHeightPx(session);
    try std.testing.expect(bar_h > 0);

    var surfaces: std.ArrayList(web_panel_layout.SurfaceLayout) = .empty;
    defer surfaces.deinit(allocator);
    try web_ops.collectWebSurfaces(session, &surfaces);

    var md_rect: ?web_panel_layout.Rect = null;
    var browser_rect: ?web_panel_layout.Rect = null;
    for (surfaces.items) |s| {
        if (s.surface_id == md.surfaceId()) md_rect = s.content_rect;
        if (s.surface_id == browser.surfaceId()) browser_rect = s.content_rect;
    }
    try std.testing.expect(md_rect != null and browser_rect != null);
    // 같은 pane·같은 leaf라 밴드 유무만 차이 → browser 본문이 정확히 bar_h만큼 더 내려간다.
    try std.testing.expectEqual(md_rect.?.y + bar_h, browser_rect.?.y);
    try std.testing.expectEqual(md_rect.?.h - bar_h, browser_rect.?.h);

    // 활성 browser 판정도 같은 술어를 공유한다(nav 단축키 게이트).
    try std.testing.expectEqual(browser.surfaceId(), web_ops.activeWebSurfaceId(session));
    term_ops.focusTerm(session, 1); // markdown을 활성으로
    try std.testing.expectEqual(@as(u64, 0), web_ops.activeWebSurfaceId(session));
}

// FP16b 선행(§10 B-1): 파일 entry 조회 창구가 저장 구조(그룹 트리)를 감추는지 고정한다. FP16b가 소유를 `Term`으로
// 옮길 때 이 테스트는 **그대로 통과해야 한다** — 통과하지 못하면 API가 저장 위치를 새고 있다는 뜻이다.
// 다중 그룹으로 세팅하는 이유: 이터레이터가 그룹 경계를 넘는지(한 그룹만 보고 끝내지 않는지) 잡기 위해서다.
test "FP16b B-1: 파일 entry 조회 API가 그룹 구조를 감춘다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1400, 900, 1000);

    const a = try pane_ops.openFileTermInActivePane(session, "/tmp/b1-a.md", .markdown);
    const a_id = a.term.file_entry.?.id;
    _ = try pane_ops.openFileTermInActivePane(session, "/tmp/b1-b.md", .markdown);
    // 두 번째 워크스페이스에 열어 이터레이터가 **탭 경계**를 넘는지 검증한다(FP16에서 그룹 경계를 대신한다).
    _ = try tab_ops.newTab(session);
    const c = try pane_ops.openFileTermInActivePane(session, "/tmp/b1-c.md", .markdown);
    const c_id = c.term.file_entry.?.id;

    // ① 이터레이터는 그룹과 무관하게 창의 전 entry를 준다.
    var seen_a = false;
    var seen_b = false;
    var seen_c = false;
    var count: usize = 0;
    var it = file_panel_ops.fileEntries(session);
    while (it.next()) |entry| {
        count += 1;
        if (std.mem.eql(u8, entry.path, "/tmp/b1-a.md")) seen_a = true;
        if (std.mem.eql(u8, entry.path, "/tmp/b1-b.md")) seen_b = true;
        if (std.mem.eql(u8, entry.path, "/tmp/b1-c.md")) seen_c = true;
    }
    try std.testing.expectEqual(file_panel_ops.fileEntryCount(session), count);
    try std.testing.expect(seen_a and seen_b and seen_c);

    // ② const 변형도 같은 집합을 본다(순수 술어용).
    var const_count: usize = 0;
    var cit = file_panel_ops.fileEntriesConst(session);
    while (cit.next()) |_| const_count += 1;
    try std.testing.expectEqual(count, const_count);

    // ③ 경로·EntryId 조회는 배치를 몰라도 정확한 entry를 준다 — 다른 워크스페이스에 있는 c까지.
    const by_path = file_panel_ops.fileEntryForPath(session, "/tmp/b1-c.md").?;
    try std.testing.expectEqualStrings("/tmp/b1-c.md", by_path.path);
    const by_id = file_panel_ops.fileEntryForId(session, c_id).?;
    try std.testing.expectEqual(by_path, by_id); // 같은 주소
    const a_entry = file_panel_ops.fileEntryForId(session, a_id).?;
    try std.testing.expectEqualStrings("/tmp/b1-a.md", a_entry.path);

    // ④ 없는 키는 null(창 전체를 뒤진 뒤).
    try std.testing.expect(file_panel_ops.fileEntryForPath(session, "/tmp/b1-missing.md") == null);
    try std.testing.expect(file_panel_ops.fileEntryForId(session, 0) == null);

    // ⑤ 반환은 포인터라 호출처가 그룹 인덱싱 없이 바로 변경할 수 있다(mutation 예약 경로가 이 형태를 쓴다).
    // 검증도 그룹 인덱싱이 아니라 **같은 API 재조회**로 한다 — 내부 배치를 단언하면 이 테스트가 감추려는 바로 그
    // 구조에 다시 의존하게 되고, FP16b가 소유를 Term으로 옮길 때 통과하지 못한다.
    by_path.mutation_pending_id = 42;
    try std.testing.expectEqual(@as(u64, 42), file_panel_ops.fileEntryForPath(session, "/tmp/b1-c.md").?.mutation_pending_id);
}

// FP16 §5.0 왕복 게이트: 파일 Term이 `pane` 줄의 `file-term` 필드로 나갔다가 **같은 자리**로 돌아온다.
// 브라우저가 섞인 pane에서 persisted 인덱스가 런타임 인덱스와 갈리는 것이 이 포맷의 핵심 제약이라, 그
// 조합을 실제 세션으로 왕복시킨다.
test "FP16 영속: 파일 Term이 pane file-term으로 왕복하고 브라우저는 자리를 비운다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    // pane: [terminal, browser, alpha.md, beta.html] — persisted 시퀀스는 [terminal, alpha, beta]다.
    _ = try pane_ops.newWebTermInActivePane(session, .browser);
    _ = try pane_ops.openFileTermInActivePane(session, "/tmp/fp16-persist-alpha.md", .markdown);
    _ = try pane_ops.openFileTermInActivePane(session, "/tmp/fp16-persist-beta.html", .html);
    file_panel_ops.assignDockSurfaceIds(session);
    file_panel_ops.fileEntryForPath(session, "/tmp/fp16-persist-alpha.md").?.mode = .source_edit;

    var arena = std.heap.ArenaAllocator.init(allocator);
    defer arena.deinit();
    const win = try workspace_ops.captureWorkspaceWindow(session, arena.allocator(), false, null);
    const pane_model = win.tabs[0].panes[0];
    try std.testing.expectEqual(@as(usize, 2), pane_model.file_terms.len);
    try std.testing.expectEqual(@as(usize, 1), pane_model.surfaces.len); // 터미널 하나만 PTY surface
    // 브라우저는 미영속이라 자리를 차지하지 않는다 — alpha가 1, beta가 2다.
    try std.testing.expectEqual(@as(usize, 1), pane_model.file_terms[0].index);
    try std.testing.expectEqual(@as(usize, 2), pane_model.file_terms[1].index);
    try std.testing.expectEqual(dock_panel.Mode.source_edit, pane_model.file_terms[0].mode);
    // 활성(beta, 런타임 3)은 persisted 2로 remap된다.
    try std.testing.expectEqual(@as(usize, 2), pane_model.active_term);

    // 텍스트 왕복까지 태운다 — 필드 문법·self-delimiting 경로가 실제로 되돌아오는지가 요점이다.
    const windows = [_]maru.session.workspace.Window{win};
    const text = try maru.session.workspace.serialize(allocator, .{ .windows = &windows });
    defer allocator.free(text);
    try std.testing.expectEqual(@as(usize, 2), std.mem.count(u8, text, "file-term=\""));
    try std.testing.expect(std.mem.indexOf(u8, text, "dock-entry=\"") == null);
    var parsed = try maru.session.workspace.parse(allocator, text);
    defer parsed.deinit();
    const round = parsed.workspace.windows[0].tabs[0].panes[0];
    try std.testing.expectEqual(@as(usize, 2), round.file_terms.len);
    try std.testing.expectEqualStrings("/tmp/fp16-persist-alpha.md", round.file_terms[0].path);
    try std.testing.expectEqualStrings("/tmp/fp16-persist-beta.html", round.file_terms[1].path);

    // 복원: 파일 Term이 persisted 자리대로 되살아난다(터미널 0, alpha 1, beta 2).
    // 라이브 편집 mode는 복원을 fail-close하므로(§3.2 종료 보호) 적용 전에 읽기로 되돌린다 — 텍스트에는
    // 이미 source_edit이 실려 있어 왕복 검증에는 영향이 없다.
    file_panel_ops.fileEntryForPath(session, "/tmp/fp16-persist-alpha.md").?.mode = .read;
    try workspace_ops.applyWorkspaceWindow(session, parsed.workspace.windows[0]);
    const pane = pane_ops.activePane(session);
    try std.testing.expectEqual(@as(usize, 3), pane.terms.items.len);
    try std.testing.expect(pane.terms.items[0].file_entry == null); // 터미널
    try std.testing.expectEqualStrings("/tmp/fp16-persist-alpha.md", pane.terms.items[1].file_entry.?.path);
    try std.testing.expectEqualStrings("/tmp/fp16-persist-beta.html", pane.terms.items[2].file_entry.?.path);
    try std.testing.expectEqual(dock_panel.Mode.source_edit, pane.terms.items[1].file_entry.?.mode);
    try std.testing.expectEqual(@as(usize, 2), pane.active_term);
    try std.testing.expectEqual(@as(usize, 2), file_panel_ops.fileEntryCount(session));
}

// ── FP16 닫기 계약 회귀 가드 ────────────────────────────────────────────────────────────────────
// 이 세 테스트는 5·6차 code-review max가 잡은 **크래시·영구 차단** 계열의 재발 가드다. 셋 다 그 리뷰
// 전에는 통과했을 코드가 없다(각각 UAF·무한루프·못 닫는 pane을 냈다).

test "FP16 닫기: 창의 마지막 Term인 파일 탭은 구조를 파괴하지 않고 종료 latch만 건다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    // pane을 [파일] 하나로 만든다(터미널을 닫아).
    const opened = try pane_ops.openFileTermInActivePane(session, "/tmp/fp16-last-term.md", .markdown);
    file_panel_ops.assignDockSurfaceIds(session);
    const sid = opened.term.file_entry.?.surface_id;
    const pane = pane_ops.activePane(session);
    while (pane.terms.items.len > 1) {
        const victim = for (pane.terms.items, 0..) |t, i| {
            if (t.file_entry == null) break i;
        } else break;
        term_ops.closeTermAt(session, 0, pane, victim);
    }
    try std.testing.expectEqual(@as(usize, 1), pane.terms.items.len);

    try std.testing.expect(file_panel_ops.closeFilePanelSurfaceNow(session, sid));
    // **구조는 그대로다** — Term을 빼면 pane이 Term 0개가 되어 모델 불변식이 깨지고, latch가 그 직후
    // 해제된 대표 surface에 쓴다(5차 리뷰가 잡은 UAF). 정리는 deinit이 한다.
    try std.testing.expectEqual(@as(usize, 1), pane_ops.activePane(session).terms.items.len);
    try std.testing.expect(session.ended_seen); // 창이 닫힌다
}

test "FP16 닫기: 다른 파일이 종료를 막으면 마지막 Term close는 아무것도 안 바꾸고 거부한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    // 워크스페이스 둘: 0번에 지킬 파일(dirty), 1번에 닫을 파일.
    const guarded = try pane_ops.openFileTermInActivePane(session, "/tmp/fp16-guard.md", .markdown);
    file_panel_ops.assignDockSurfaceIds(session);
    guarded.term.file_entry.?.dirty = true;
    _ = try tab_ops.newTab(session);
    const victim = try pane_ops.openFileTermInActivePane(session, "/tmp/fp16-victim.md", .markdown);
    file_panel_ops.assignDockSurfaceIds(session);
    const victim_sid = victim.term.file_entry.?.surface_id;

    // 창 전체에 Term이 둘 이상이라 마지막-Term 분기는 안 탄다 — 정상 close.
    try std.testing.expect(file_panel_ops.closeFilePanelSurfaceNow(session, victim_sid));
    try std.testing.expect(!session.ended_seen);
    try std.testing.expect(file_panel_ops.fileEntryForPath(session, "/tmp/fp16-guard.md") != null);
}

test "FP16 닫기: 파괴 전 스냅샷은 한 번만 요청하고, 답이 없어도 두 번째 시도를 막지 않는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    // `.text`의 기본 mode는 source_edit이다 — 손도 안 댄 이 탭 하나가 그 pane을 영영 못 닫게 하면 안 된다.
    const opened = try pane_ops.openFileTermInActivePane(session, "/tmp/fp16-clean.py", .text);
    file_panel_ops.assignDockSurfaceIds(session);
    const entry = opened.term.file_entry.?;
    try std.testing.expectEqual(dock_panel.Mode.source_edit, entry.mode);
    try std.testing.expect(!entry.close_snapshot_requested);

    // 1차: 스냅샷을 실제로 요청하고 close를 보류한다(§3.2 two-phase의 scope판).
    try std.testing.expect(session.syncDirtyBeforeScopeClose(.term_or_pane, .pane));
    try std.testing.expect(entry.close_snapshot_requested);
    try std.testing.expect(entry.dirty_sync_pending);

    // 2차: once-only 래치 때문에 다시 요청하지 않는다.
    try std.testing.expect(!session.syncDirtyBeforeScopeClose(.term_or_pane, .pane));

    // 그리고 답이 안 왔어도 그 파일이 close를 막지 않는다 — 여기서 막으면 브릿지가 죽은 순간
    // 그 pane·워크스페이스가 영원히 안 닫힌다(code-review max).
    try std.testing.expect(!file_panel_ops.termHasProtectedFilePanel(opened.term));

    // 스냅샷이 **돌아와** dirty가 서면 다시 정상적으로 막는다.
    entry.dirty = true;
    try std.testing.expect(file_panel_ops.termHasProtectedFilePanel(opened.term));
}

// §6c host-backed 검색 회귀 가드. 원격에서만 증분 검색(타이핑)이 매치로 스크롤되지 않던 결함 — find.zig의
// recomputeFind가 그룹 내부에서 free 함수 scrollToCurrentMatch를 직접 불러, app_session facade에만 있던 원격
// 분기를 우회했다. 분기를 find.zig 단일 출처로 옮겼으므로 두 경로(타이핑·Enter) 모두 host 스크롤을 요청해야 한다.
test "host-backed find: 증분 검색과 네비가 둘 다 host 스크롤을 요청한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 6,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000);

    var fake = FakeLinkScreen{ .snap = .{ .size = .{ .cols = 40, .rows = 6 } } };
    const surface = term_ops.activeSurface(session);
    surface.remote = .{ .ctx = &fake, .vtable = &FakeLinkScreen.vtable };
    defer surface.remote = null;

    session.dispatchAppAction(.toggle_find);
    for ("MARUFIND") |c| _ = try session.handleKeyEvent(.{ .key = .{ .char = c }, .modifiers = .{} });

    // 타이핑(증분 검색): 재검색과 "첫 매치로 스크롤"이 둘 다 host에 요청된다 — in-process와 같은 동작.
    try std.testing.expect(session.remote_find_dirty);
    try std.testing.expect(session.remote_find_scroll_pending);

    // Enter(네비)도 같은 단일 출처를 거친다.
    session.remote_find_scroll_pending = false;
    _ = try session.handleKeyEvent(.{ .key = .enter, .modifiers = .{} });
    try std.testing.expect(session.remote_find_scroll_pending);
}

// host 응답 span을 언제 그려도 되는지의 정책. host는 scroll 직후 **스크롤된 화면 기준**으로 span을 계산해
// 응답하는데(runtime_manager.findOp), client는 그 스크롤 delta를 아직 못 받았을 수 있다. 두 좌표계를 합성하면
// 엉뚱한 줄이 하이라이트된다 — 사용자가 본 "이전 하이라이트가 남는" 증상의 정체다.
test "host-backed find: span은 client 화면과 view_offset이 맞을 때만 적용한다" {
    // 정합 — 적용한다.
    try std.testing.expect(remoteFindSpansApplicable(120, 120));
    // 어긋남(host가 스크롤했고 그 delta가 아직 client에 없다) — 적용하지 않는다(이전 하이라이트 유지).
    try std.testing.expect(!remoteFindSpansApplicable(120, 0));
    try std.testing.expect(!remoteFindSpansApplicable(0, 120));
    // 구 host 데몬은 이 값을 안 보낸다 — 대조 근거가 없으므로 종전대로 즉시 적용한다.
    try std.testing.expect(remoteFindSpansApplicable(null, 120));
}

// 손 확인에서 나온 결함: 소스 컨트롤 뷰에서 행을 클릭하면 **폴더 선택 다이얼로그**가 떴다. 탐색기 전용 클릭 처리가
// `dockVisible()`로만 막혀 있어 좌표가 같은 rect 안이라는 이유로 그대로 탔기 때문이다(뷰가 달라 트리 행은 화면에
// 없는데도). 트리 포커스도 같이 뺏겼는데, 이는 setDockView가 뷰 전환 시 그 포커스를 놓는 것과 모순이다.
test "도크 뷰: 탐색기 아닌 뷰의 클릭은 폴더 선택·트리 포커스로 새지 않는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1400, 900, 1000);

    const launcher = file_panel_ops.filePanelDockControlRect(session) orelse return error.MissingDockLauncher;
    session.mouse(1, @floatFromInt(launcher.x + 1), @floatFromInt(launcher.y + 1), 0, 0);
    try std.testing.expect(dock_ops.dockVisible(session));
    _ = session.takeFilePanelPickRequest();

    const tree_content = dock_ops.dockGeometry(session).tree_content;
    const x: f64 = @floatFromInt(tree_content.x + tree_content.w / 2); // 좌측 divider grab band 밖
    const y: f64 = @floatFromInt(tree_content.y + 1);

    dock_ops.setDockView(session, .source_control);
    session.mouse(1, x, y, 0, 0);
    try std.testing.expect(!session.takeFilePanelPickRequest()); // 폴더 다이얼로그 금지
    try std.testing.expect(!file_panel_ops.fileTreeFocused(session)); // 트리 포커스도 안 뺏는다
    session.mouse(1, x, y, 0, 2); // 우클릭 배경 메뉴(새 폴더 등)도 탐색기 조작이라 안 뜬다
    try std.testing.expect(!session.chrome_host.context_menu.open);
    try std.testing.expect(!session.file_tree_background_menu);

    // 휠은 탐색기 스크롤 상태를 건드리지 않는다(안 보이는 목록이 움직이면 돌아왔을 때 위치가 어긋난다).
    session.file_tree_scroll.reset();
    scroll_ops.scrollWheel(session, -600, 0, false, x, y);
    try std.testing.expectEqual(@as(u32, 0), session.file_tree_scroll.offset_y_px);
    // 탐색기 행 수로 만든 스크롤바도 다른 뷰에는 없다(그리기·드래그 양쪽).
    try std.testing.expect(dock_ops.dockListScrollbarGeometry(session) == null);

    // 같은 좌표라도 탐색기로 돌아오면 원래 동작이 그대로다(게이트가 기능을 죽인 게 아니라 뷰로 가른 것).
    dock_ops.setDockView(session, .explorer);
    session.mouse(1, x, y, 0, 0);
    try std.testing.expect(session.takeFilePanelPickRequest());
}

// 도크 안에서 시작한 클릭은 **끝까지 도크 것**이다. 그런데 down은 `dg.dock`(도크 전체)을 보고 up·move는
// `dg.tree_content`(도크에서 view_bar를 뺀 본문)만 봐서, 도크 상단 아이콘 줄의 빈 자리를 클릭하면 down은
// 도크가 먹고 **up만 터미널에 도달**했다. 그 up은 `select_extend_or_collapse`를 코어에 넣어 살아 있던
// 선택을 움직인다(사용자 제보 2026-08-17 — "도크의 클릭 이벤트가 안 되는 영역을 누르면 터미널 블록
// 이벤트가 잡힌다").
//
// 계약을 좌표가 아니라 **결과**로 고정한다: 도크 안 어디서 up이 나도 터미널 선택은 손대지 않는다.
test "도크 포인터: 도크 위의 더블·트리플 클릭은 터미널 선택을 만들지 않는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 900, 600, session.scale_milli);
    const surface = term_ops.activeSurface(session);
    // 화면을 **꽉 채운다** — 중앙이 빈 줄이면 마지막 단언(터미널 본문 더블클릭은 정상)이 "단어가 없어서"
    // 실패해 게이트를 잘못 의심하게 된다.
    try surface.core.write("hello world\r\n" ** 80);

    const launcher = file_panel_ops.filePanelDockControlRect(session) orelse return error.MissingDockLauncher;
    session.mouse(1, @floatFromInt(launcher.x + 1), @floatFromInt(launcher.y + 1), 0, 0);
    try std.testing.expect(dock_ops.dockVisible(session));
    _ = session.takeFilePanelPickRequest();
    dock_ops.setDockView(session, .agent_sessions);

    const dg = dock_ops.dockGeometry(session);
    if (dg.view_bar.h == 0) return error.SkipZigTest; // 도크가 낮아 바가 접힌 형상은 이 계약의 대상이 아니다
    // 아이콘 슬롯이 **없는** 자리를 고른다 — 슬롯 위라면 클릭이 뷰를 바꾸는 정상 동작이라 이 결함이 안 보인다.
    const bar_x: f64 = @floatFromInt(dg.view_bar.x + dg.view_bar.w - 3);
    const bar_y: f64 = @floatFromInt(dg.view_bar.y + dg.view_bar.h / 2);
    try std.testing.expect(dock_ops.dockViewSlotAt(session, bar_x, bar_y) == null);
    try std.testing.expect(layout_math.pointInRect(bar_x, bar_y, dg.dock)); // 도크 안이다
    try std.testing.expect(!layout_math.pointInRect(bar_x, bar_y, dg.tree_content)); // 그러나 본문 밖이다

    // 도크 **본문** 좌표도 함께 본다 — 결함은 view_bar 여백에 한정되지 않는다.
    const content_x: f64 = @floatFromInt(dg.tree_content.x + dg.tree_content.w / 2);
    const content_y: f64 = @floatFromInt(dg.tree_content.y + dg.tree_content.h / 2);

    // 단일 클릭은 예전에도 도크가 먹었다. 새던 것은 **더블·트리플 클릭**이다: 도크 라우팅 블록이
    // `kind == 1`에만 걸려 있고 `pxToCell`이 도크 좌표를 grid 안으로 clamp해, 터미널 `select_word`/
    // `select_line`이 그대로 실행됐다.
    for ([_]i32{ 4, 5 }) |kind| {
        for ([_][2]f64{ .{ bar_x, bar_y }, .{ content_x, content_y } }) |pt| {
            try std.testing.expect(surface.core.selection_anchor == null);
            session.mouse(kind, pt[0], pt[1], 0, 0);
            // 터미널에 단어/줄 선택이 생기면 실패다 — 그 선택이 사용자가 본 "블록"이다.
            try std.testing.expect(surface.core.selection_anchor == null);
            try std.testing.expect(surface.core.selection_head == null);
        }
    }

    // 같은 좌표라도 **터미널 본문**에서는 더블클릭이 정상 동작한다(게이트가 기능을 죽인 게 아니라 영역으로 가른다).
    const body = pane_ops.paneTermRect(session, session.active_pane_rect);
    session.mouse(4, @floatFromInt(body.x + body.w / 4), @floatFromInt(body.y + body.h / 2), 0, 0);
    try std.testing.expect(surface.core.selection_anchor != null);
}

// [code-review max] diff Term은 persisted 시퀀스에 **자리를 만들지 않는다**. writer에서만 빼면 이미 부여된 index가
// 줄어든 총계와 어긋나 복원 시 `index >= total`로 그 창 전체가 fail-close된다(터미널·파일 탭이 통째로 사라진다).
test "captureWorkspaceTab: diff Term은 index를 차지하지 않는다(복원 fail-close 방지)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    var arena = std.heap.ArenaAllocator.init(allocator);
    defer arena.deinit();

    // [term0, diff, markdown] — diff가 가운데라 뒤 파일 Term의 index가 밀린다(그게 결함의 조건이었다).
    _ = try pane_ops.openFileTermInActivePane(session, "/tmp/diff-capture.zig", .diff);
    _ = try pane_ops.openFileTermInActivePane(session, "/tmp/diff-capture.md", .markdown);
    const pane = pane_ops.activePane(session);
    try std.testing.expectEqual(@as(usize, 3), pane.terms.items.len);

    const wtab = try tab_ops.captureWorkspaceTab(session, arena.allocator(), tab_ops.activeTab(session));
    const wpane = wtab.panes[0];
    // diff는 빠지고 markdown만 남는다.
    try std.testing.expectEqual(@as(usize, 1), wpane.file_terms.len);
    try std.testing.expectEqualStrings("/tmp/diff-capture.md", wpane.file_terms[0].path);
    // **핵심**: 남은 index와 active_term이 줄어든 총계 안에 든다(reader의 validatePaneFileTerms 조건).
    const total = wpane.surfaces.len + wpane.file_terms.len;
    try std.testing.expect(wpane.file_terms[0].index < total);
    try std.testing.expect(wpane.active_term < total);
}

// [code-review max] 유일성 키는 `(경로, kind, base)`다(docs/editor-surface-dock.md §3.5). 경로만으로 조회하면 소스 컨트롤
// 행 클릭이 이미 열린 markdown Term을 재사용해 **diff가 영영 안 열리고**, 반대로 탐색기에서 그 파일을 열면 diff Term이
// 활성화된다. 둘 다 사용자가 누른 것과 다른 것을 보여 준다.
test "diff Term과 파일 Term은 같은 경로로 공존한다(유일성 키에 kind가 든다)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    const path = "/tmp/same-path.md";
    const md = try pane_ops.openFileTermInActivePane(session, path, .markdown);
    const diff = try pane_ops.openFileTermInActivePane(session, path, .diff);
    try std.testing.expect(md.term != diff.term); // 서로를 빼앗지 않는다

    // 탐색기 경로 조회는 diff를 건너뛴다 — 그러지 않으면 파일을 열 때 diff Term이 활성화된다.
    try std.testing.expectEqual(md.term, file_panel_ops.fileTermForPath(session, path).?);
    // 반대로 diff 조회는 base까지 본다: 같은 경로의 다른 base는 다른 Term이다.
    diff.term.file_entry.?.diff_base = .staged;
    try std.testing.expectEqual(diff.term, git_ops.diffTermFor(session, path, .staged).?);
    try std.testing.expect(git_ops.diffTermFor(session, path, .unstaged) == null);
}

// [손 확인] 목록이 뷰를 껐다 켜야만 갱신되던 것을 감시로 바꿨다. 폴링이 아니라 `.git` 감시인 이유: `git add`는
// 작업트리를 안 건드리고 index만 바꿔 작업트리 감시로는 안 잡힌다. 그 경로가 감시 목록에 실제로 실리는지,
// `.git` 이벤트가 목록 갱신 신호로만 쓰이는지를 못박는다.
test "소스 컨트롤: 저장소의 .git을 감시 목록에 올리고 그 이벤트로 목록을 다시 읽는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    git_ops.ensureGitWatch(session, "/repo/one");
    try std.testing.expectEqualStrings("/repo/one/.git", session.peekFileTreeWatchRoot().?);
    const taken = session.takeFileTreeWatchRoot().?;
    defer allocator.free(taken);
    try std.testing.expectEqualStrings("/repo/one/.git", taken);
    // 같은 저장소는 다시 요청하지 않는다(이벤트마다 stream을 재구성하지 않게).
    git_ops.ensureGitWatch(session, "/repo/one");
    try std.testing.expect(session.peekFileTreeWatchRoot() == null);
    // 저장소가 바뀌면 새로 요청한다.
    git_ops.ensureGitWatch(session, "/repo/two");
    try std.testing.expectEqualStrings("/repo/two/.git", session.peekFileTreeWatchRoot().?);

    // `.git` 안쪽 경로만 git 신호다 — 이름이 비슷한 작업트리 파일(.gitignore)을 신호로 오인하면 안 된다.
    try std.testing.expect(git_ops.isGitInternalPath("/repo/one/.git/index"));
    try std.testing.expect(git_ops.isGitInternalPath("/repo/one/.git"));
    try std.testing.expect(!git_ops.isGitInternalPath("/repo/one/.gitignore"));
    try std.testing.expect(!git_ops.isGitInternalPath("/repo/one/src/main.zig"));
}

// [사용자 보고 2026-08-10] "깃 히스토리 추적이 제대로 안 된다 / 활성 터미널 폴더 기준으로 추론되어야 한다".
// 원인은 `gitRepoRoot`가 **탐색기 root를 먼저** 훑고 터미널을 폴백으로만 봤다는 것 — 탐색기에 다른 저장소를
// 열어 두면 터미널을 아무리 옮겨도 목록이 안 따라왔다. 아래 둘이 그 순서와 재읽기 트리거를 고정한다.
test "소스 컨트롤: 대상 저장소는 활성 터미널 cwd가 먼저다(직전 저장소보다 우선)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    // 이 테스트 프로세스의 cwd는 maru 저장소이고, 활성 Term은 실제 PTY라 그 자식의 cwd도 같은 곳이다.
    // 셸 통합이 없는 테스트 PTY라 **OSC 7이 한 번도 안 온다** — 그래도 커널 폴백으로 잡혀야 한다(그게 이
    // 슬라이스의 핵심이다: bash/fish나 claude·codex가 떠 있어도 감지되어야 한다).
    var buf: [std.fs.max_path_bytes]u8 = undefined;
    const from_terminal = git_ops.gitRepoRoot(session, &buf) orelse return error.SkipZigTest; // 저장소 밖에서 돌면 건너뛴다
    var expect_buf: [std.fs.max_path_bytes]u8 = undefined;
    @memcpy(expect_buf[0..from_terminal.len], from_terminal);
    const expected = expect_buf[0..from_terminal.len];

    // 실재하는 **다른** 저장소를 직전 값으로 기억시켜도 터미널이 이긴다(존재하지 않는 경로를 쓰면 어차피
    // 해석에 실패해 우선순위를 증명하지 못한다 — 그래서 진짜 저장소를 하나 만든다).
    var exe_buf: [std.fs.max_path_bytes]u8 = undefined;
    const exe = git_backend_mod.locate(&exe_buf) orelse return error.SkipZigTest;
    var other_buf: [std.fs.max_path_bytes]u8 = undefined;
    const other = std.fmt.bufPrint(&other_buf, "{s}/.zig-cache/tmp-scm-priority", .{expected}) catch return error.SkipZigTest;
    var rm_buf: [std.fs.max_path_bytes]u8 = undefined;
    const rm_path = std.fmt.bufPrintZ(&rm_buf, "{s}", .{other}) catch return error.SkipZigTest;
    _ = git_backend_mod.testRunQuiet(&.{ "/bin/rm", "-rf", rm_path });
    defer _ = git_backend_mod.testRunQuiet(&.{ "/bin/rm", "-rf", rm_path });
    if (!git_backend_mod.testRunQuiet(&.{ exe, "init", "-q", "-b", "main", other })) return error.SkipZigTest;

    git_ops.rememberGitRepo(session, other);
    const still = git_ops.gitRepoRoot(session, &buf) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings(expected, still); // 터미널 > 직전 저장소

    // **사용자가 실제로 보고한 상황이 이것이다**: 탐색기에 다른 저장소를 열어 둔 채 터미널을 옮겼는데 목록이
    // 안 따라왔다. 옛 구현은 `file_tree.roots`를 **먼저** 훑어 탐색기가 이겼다. 터미널이 이겨야 한다.
    var opened_buf: [std.fs.max_path_bytes]u8 = undefined;
    const opened = try std.fmt.bufPrint(&opened_buf, "{s}/README.md", .{other});
    try session.file_tree.recordOpened(opened, other);
    try std.testing.expect(session.file_tree.rootCount() > 0); // 탐색기 root가 실제로 섰는지 먼저 확인한다
    try std.testing.expectEqualStrings(other, session.file_tree.rootAt(0).?);
    const with_root = git_ops.gitRepoRoot(session, &buf) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings(expected, with_root); // 터미널 > 탐색기 root

    // 반대로 **터미널이 답을 못 줄 때만** 아래 순위가 산다. 활성 Term을 파일 Term으로 바꾸면(= diff를 연 상태)
    // 터미널 기준이 사라지고 2순위(직전 저장소)가 대상을 잡는다 — 이게 없으면 diff를 여는 순간 목록이 튄다.
    git_ops.openDiffTerm(session, other, opened, "README.md", null, .unstaged);
    const after_diff = git_ops.gitRepoRoot(session, &buf) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings(other, after_diff);
}

test "소스 컨트롤: 원격 세션 터미널은 로컬 저장소를 가리키지 않는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    // OSC 7은 host authority를 버리고 경로만 남기고, 커널 조회는 로컬 `ssh` 클라이언트의 cwd를 답한다. 둘 다
    // 원격 경로를 **로컬 파일시스템에 대고** 해석하게 만들어, 로컬에 같은 경로가 있으면 남의 저장소를 원격인 척
    // 보여 준다 — 거기서 stage/discard 하면 보고 있지도 않은 로컬 파일이 바뀐다(링크 감지가 겪은 같은 함정).
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    var buf: [std.fs.max_path_bytes]u8 = undefined;
    // 로컬 상태에서는 터미널이 답을 준다(이게 성립해야 아래 단언이 의미를 갖는다).
    _ = git_ops.activeTerminalCwd(session, &buf) orelse return error.SkipZigTest;

    // **관측 캐시를 손으로 조작하지 않고 실제 이스케이프로 몬다.** 직접 필드를 쓰면 다음 `refreshTermObservation`이
    // 코어에서 다시 읽어 덮을 수 있어, 통과해도 그 이유를 믿을 수 없다(그 갱신이 안 도는 순간에만 통과한다).
    const term = pane_ops.activePane(session).activeTerm();

    // maru ssh 진입 통지 → 터미널은 더 이상 답하지 않는다(커널 폴백도 막힌다 — ssh 클라이언트의 로컬 cwd다).
    try term.surface.core.write("\x1b]5379;ssh;user@build-box\x07");
    try std.testing.expect(git_ops.activeTerminalCwd(session, &buf) == null);

    // **끝나면 다시 답한다.** 이 flag가 sticky면 그 터미널에서 소스 컨트롤이 영영 죽는다.
    try term.surface.core.write("\x1b]5379;ssh-end\x07");
    _ = git_ops.activeTerminalCwd(session, &buf) orelse return error.TestUnexpectedResult;

    // 원격 host가 보고한 OSC 7도 마찬가지다 — authority가 로컬이 아니면 그 경로는 원격 것이다.
    try term.surface.core.write("\x1b]7;file://build-box.example.com/srv/app\x07");
    try std.testing.expect(git_ops.activeTerminalCwd(session, &buf) == null);
}

// ── 원격 SCM 가드 (RS2) ───────────────────────────────────────────────────────
//
// [계획](../../../docs/plans/remote-scm.md) §2.1 — 원격 목록을 보는 동안 **로컬에 손이 가면 안 된다.**
// 적대적 검증 3 회에서 실제로 새던 자리를 그대로 고정한다: ⑴ 자동 읽기(히스토리·파일 목록·턴 스냅샷)가
// `git_repo` 의 원격 경로로 **로컬 git** 을 불렀고 ⑵ 쓰기는 인텐트 밖(키 입력 커밋·base 메뉴)으로도
// 들어왔으며 ⑶ 호스트만 바뀌는 전환(로컬 `/srv/app` → 원격 `/srv/app`)을 경로 비교가 못 봤다.
//
// **경로를 로컬에도 있을 법한 값으로 둔다** — 이 계약이 막으려는 상황이 정확히 그것이다.
// **원격 pane 인데 목록을 아직 못 읽은 구간**도 로컬로 새면 안 된다.
//
// RS2 의 가드는 `scmTargetIsRemote`(= `git_repo_dest != null`) 하나였다. 그런데 그 값은 원격 읽기가
// **성공한 뒤에야** 선다(`submitGitRead`). 그래서 이런 구간이 열려 있었다:
//
//   ⑴ control socket 이 죽었을 때(`ControlPersist` 만료·네트워크 끊김)
//   ⑵ ssh 진입 직후, 첫 원격 읽기가 돌아오기 전
//
// 그때 3 순위(`file_tree.roots`)가 **로컬 저장소**를 답했고, 화면 어디에도 그 사실이 없었다 — 브랜치
// 줄의 `user@host` 는 목록이 원격일 때만 붙으므로 함께 사라진다. 그 상태에서 누른 스테이지는 보고
// 있지도 않은 **로컬 파일**을 바꾼다.
//
// **RS2 판정자는 이것을 못 잡았다** — `rememberGitRepoDest` 를 먼저 불러 놓고 검사해서, 옛 가드만으로도
// 통과했기 때문이다. 여기서는 그 값을 **세우지 않는다.**
//
// 제품 렌더 캡처로 재현하고 고쳤다(2026-09-02): 소켓만 지운 대조군에서 도크가 로컬 `maru5` 와
// 그 워크트리 전부를 보여 줬고, 고친 뒤에는 「저장소를 확인할 수 없습니다」가 뜬다.
test "원격 pane 은 목록을 못 읽어도 로컬 저장소로 안 떨어진다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    _ = try session.resize(1400, 900, 1000);
    session.git_backend = try git_backend_mod.Backend.init(session.io);
    session.git_backend.?.state.?.shutting_down = true;

    // 로컬 순위가 **답을 줄 수 있는** 상태를 만든다 — 그래야 「안 내려간다」가 뜻을 갖는다.
    //
    // 2 순위(직전 저장소)를 쓴다. `file_tree` 에 직접 심으면 안 된다 — 스모크 세션은 그 트리를
    // 초기화하지 않아 `deinit` 이 건너뛰고, 심은 경로가 **샌다**(CI 의 DebugAllocator 가 잡았다).
    // `rememberGitRepo` 는 제품 함수라 그 문자열의 수명을 세션이 진다.
    var cwd_buf: [std.fs.max_path_bytes]u8 = undefined;
    const here_len = try std.process.currentPath(session.io, &cwd_buf);
    git_ops.rememberGitRepo(session, cwd_buf[0..here_len]);

    var probe: [std.fs.max_path_bytes]u8 = undefined;
    // 전제: pane 이 로컬이면 로컬 순위가 답한다(이 판정자가 뒤집는 것이 그 답이라는 확인).
    try std.testing.expect(git_ops.gitRepoTarget(session, &probe) == .repo);

    // 활성 Term 을 원격으로 몬다 — **`git_repo_dest` 는 세우지 않는다**(읽기가 성공한 적이 없다).
    const term = pane_ops.activePane(session).activeTerm();
    try term.surface.core.write("\x1b]5379;ssh;user@build-box\x07");
    try std.testing.expect(!git_ops.scmTargetIsRemote(session)); // 옛 가드는 여기서 안 걸린다

    // 그래도 **로컬로 안 떨어진다.**
    try std.testing.expectEqual(
        git_ops.RepoTarget.unknown,
        std.meta.activeTag(git_ops.gitRepoTarget(session, &probe)),
    );

    // ssh 를 빠져나오면 다시 로컬이 답한다 — 무조건 막는 것이 아니다(래치가 아니다).
    try term.surface.core.write("\x1b]5379;ssh-end\x07");
    try std.testing.expect(git_ops.gitRepoTarget(session, &probe) == .repo);
}

test "원격 목록을 보는 동안 로컬 저장소에 손이 가지 않는다 (RS2)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    _ = try session.resize(1400, 900, 1000);

    session.git_backend = try git_backend_mod.Backend.init(session.io);
    session.git_backend.?.state.?.shutting_down = true; // 실제 git 을 안 띄운다(판정 대상은 라우팅이다)
    const launcher = file_panel_ops.filePanelDockControlRect(session) orelse return error.MissingDockLauncher;
    session.mouse(1, @floatFromInt(launcher.x + 1), @floatFromInt(launcher.y + 1), 0, 0);
    dock_ops.setDockView(session, .source_control);

    git_ops.rememberGitRepo(session, "/srv/app");
    git_ops.rememberGitRepoDest(session, "user@build-box");
    try std.testing.expect(git_ops.scmTargetIsRemote(session));

    // ⑴ **저장소 판정이 로컬 순위로 안 내려간다.** 내려가면 원격 경로를 로컬에 대고 walk-up 해,
    //    로컬에 같은 경로가 있으면 남의 저장소를 원격인 척 답한다.
    //
    // **활성 Term 을 실제로 원격으로 몬다**(관측 캐시를 손으로 쓰지 않고 maru ssh 진입 통지로).
    // 판정자를 처음 썼을 때 이 단계가 없어 빨갛게 났는데, 그 실패가 가드의 전제를 정확히 드러냈다:
    // 활성 Term 이 로컬이면 **1 순위가 답하는 것이 맞고**(그때는 `followActiveTerminalRepo` 가 곧
    // 로컬로 갈아탄다), 가드가 필요한 상태는 **1 순위가 비는 원격 Term** 하나뿐이다.
    const term = pane_ops.activePane(session).activeTerm();
    try term.surface.core.write("\x1b]5379;ssh;user@build-box\x07");
    var probe: [std.fs.max_path_bytes]u8 = undefined;
    try std.testing.expectEqual(
        git_ops.RepoTarget.unknown,
        std.meta.activeTag(git_ops.gitRepoTarget(session, &probe)),
    );

    // ⑵ **인텐트가 늘면 여기서 컴파일이 깨진다**(exhaustive switch). RS2 는 진입점 가드가 그 역할을
    //    했는데, RS4a~c 가 모든 동작을 원격으로 보내면서 그 가드는 **아무것도 안 막게 됐고** 그래서
    //    지웠다 — 안 막는 게이트는 「여기서 지킨다」고 거짓말한다. 강제력만 이리로 옮겼다.
    //
    //    새 인텐트를 더하는 사람은 **그것이 원격에서 무엇을 하는지** 여기 적어야 한다.
    const Intent = maru.chrome.components.scm_dock.ids.Intent;
    const classify = struct {
        fn call(intent: Intent) void {
            switch (intent) {
                // 원격으로 **보낸다**(대상은 `writeTargetFor` 가 그 행의 저장소로 정한다).
                .row_action, .section_action, .stage_all_repo => {}, // RS4a — 원격 index
                .commit, .commit_focus => {}, //                        RS4b — 메시지는 stdin
                // 우리가 **실행하지 않고** 활성 pane 에 넣는다 — 우리 ssh 에는 agent 도 tty 도 없다.
                .fetch_remote, .open_remote_menu => {}, //               RS4c
                // 원격에서 **읽는다**(RS2·RS3).
                .open_row, .open_turn_file, .open_commit_file, .refresh_repo => {},
                // 화면 상태만 바꾼다 — 호스트와 무관하다.
                .toggle_section, .expand_section, .toggle_repo => {},
                .select_commit, .select_turn, .load_more_commits, .select_tab => {},
                .scroll_thumb, .scroll_track => {},
            }
        }
    }.call;
    classify(.{ .commit = 0 });

    // ⑵-b **RS4a 4회차 — 비활성 «로컬» 저장소 행이 원격으로 날아가지 않는다.**
    //
    // 목록은 저장소를 여럿 싣고(§3.5.1c) 비활성 행도 동작 버튼을 낸다. 활성 목적지를 무조건 붙이면
    // **로컬 저장소 행의 스테이지가 원격으로** 간다 — 원격에 우연히 같은 경로가 있으면 **남의 index 를
    // 바꾼다.** RS3 8회차가 diff 에서 잡은 함정이고, 쓰기는 보여 주는 것이 아니라 **바꾼다.**
    {
        var ctl_probe: [std.fs.max_path_bytes]u8 = undefined;
        // 활성 저장소(원격)와 **다른** 경로 → 로컬이어야 한다.
        try std.testing.expect(git_ops.writeTargetFor(session, "/other/local-repo", &ctl_probe) == .local);
        // 활성 저장소와 같은 경로인데 control socket 이 없다 → **보내지 않는다**(로컬로 떨어뜨리지 않는다).
        try std.testing.expect(git_ops.writeTargetFor(session, "/srv/app", &ctl_probe) == .unavailable);
    }

    // **거절은 이제 «소켓이 없다» 하나뿐이다**(RS4a·RS4b 가 나머지를 열었다). 이 세션에는 control
    // socket 이 없으므로 원격 쓰기는 **보내지 않고 이유를 말한다** — 조용한 무동작이 아니다.
    scm_dock_ops.clearScmWriteError(session);
    // 이 세션에는 control socket 이 없다 → `.unavailable` → **보내지 않고 이유를 말한다.**
    // (인텐트로 못 몬다 — 이 스모크 세션에는 저장소 행이 없어 인텐트가 그 문까지 못 간다.)
    try std.testing.expect(!scm_dock_ops.submitWriteForTest(session, "/srv/app", .stage));
    try std.testing.expect(session.scm_write_error != null);
    try std.testing.expectEqualStrings(maru.i18n.t(.scm_remote_read_only), session.scm_write_error.?);

    // ⑶ **자동 경로도 안 돈다.** 인텐트를 안 거치고 tick 이 굴리는 셋이다.
    scm_dock_ops.pumpScmLog(session);
    scm_dock_ops.pumpCommitFiles(session);
    try std.testing.expect(session.scm_log_repo == null); // 로컬 히스토리를 읽지 않았다
    try std.testing.expect(session.scm_commit_files_inflight == 0);

    // ⑷ **로컬로 돌아오면 원격 안내를 치운다.** 남기면 로컬 목록 위에 「원격 세션이라…」가 뜬다.
    git_ops.rememberGitRepoDest(session, null);
    try std.testing.expect(!git_ops.scmTargetIsRemote(session));
    try std.testing.expect(session.scm_write_error == null);
}

test "원격 pane 의 «돌고 있나» 는 낡은 관측을 믿지 않는다 (RS4c 적대적 검증 2회차)" {
    const busy = term_ops.observationKnownBusy;
    const Sem = maru.terminal.SemanticPrompt;

    // ⑴ **`.current` 일 때만 판단한다.**
    try std.testing.expect(busy(.current, false, Sem.command)); //  돌고 있다 — 넣지 않는다
    try std.testing.expect(!busy(.current, false, Sem.prompt));
    try std.testing.expect(!busy(.current, false, Sem.input));
    // **모르면 넣는다** — OSC 133 을 내는 원격 셸은 소수라, 모름을 막음으로 접으면 흔한 경우를 통째로
    // 막고 사용자는 왜 안 되는지도 모른다(닫기 확인과 기본값이 **반대**인 이유다).
    try std.testing.expect(!busy(.current, false, Sem.unknown));

    // ⑵ ⚠️ **낡은 관측은 「모른다」다.** 거기 남은 `.command` 로 막으면 화면이 **거짓말한다** —
    //    사용자는 프롬프트를 보고 있는데 「명령이 돌고 있습니다」가 뜬다.
    try std.testing.expect(!busy(.stale, false, Sem.command));
    try std.testing.expect(!busy(.stale, true, Sem.command));
    try std.testing.expect(!busy(.unavailable, true, Sem.command));

    // ⑶ **alt 화면은 semantic 과 무관하게 돈다** — 거기 넣으면 편집 중인 파일에 글자로 박힌다.
    try std.testing.expect(busy(.current, true, Sem.prompt));
    try std.testing.expect(busy(.current, true, Sem.unknown));
}

// **도크 뷰는 저마다 «활성 pane 을 어떻게 따라가는가» 를 답해야 한다.**
//
// 사용자가 이 축을 처음 신고한 이유가 그것이다(2026-08-31): 이미지 갤러리에는 그 답이 **없어서**,
// pane 을 옮겨도 그리드가 옛 pane 의 것으로 남았다. 나머지 셋은 각자 답을 갖고 있었는데 **함수 이름도
// 파일도 서로 달라**, 뷰를 더하는 사람이 「여기도 필요하다」를 알 길이 없었다.
//
// 그래서 분류를 **컴파일 오류로** 강제한다. `dock_panel.View` 에 값이 늘면 아래 switch 가 깨지고,
// 더한 사람은 그 자리를 **찾아 읽게** 된다 — 런타임 판정자는 그 사람이 안 돌리면 그만이다.
// (RS4c 에서 죽은 인텐트 가드를 지우며 강제력을 판정자로 옮긴 것과 같은 모양이다.)
test "도크 뷰는 전부 활성 pane 을 따라간다 — 새 뷰는 여기서 컴파일이 깨진다" {
    const allocator = std.testing.allocator;

    // 각 뷰의 **추종 진입점**. 값이 빈 문자열인 뷰는 없다 — 「이 뷰는 pane 과 무관하다」를 주장하려면
    // 그 이유를 여기 적고 판정을 바꿔야 하고, 그것 자체가 리뷰거리다.
    // ⚠️ **함수가 있는 것만으로는 부족하다**(적대적 검증 1회차). tick 호출만 지우면 그 뷰는 추종을
    // **멈추는데** 컴파일은 통과한다 — 사용자가 처음 신고한 상태가 정확히 그것이다. 그래서 «어디서
    // 부르는가»도 함께 센다.
    // ⚠️ **호출 문자열을 리터럴로 두면 판정자가 자기 자신을 매치한다**(적대적 검증 2회차). 두 뷰의
    // tick 호출부는 `app_session.zig` — **이 판정자가 사는 바로 그 파일**이라, needle 이 판정자 자신의
    // 리터럴에 걸려 제품에서 호출을 지워도 초록이었다. 그래서 **런타임에 이어 붙인다** — 완성된
    // 문자열은 이 소스 어디에도 리터럴로 없다.
    const Entry = struct {
        file: []const u8,
        follow: []const u8,
        call_file: []const u8,
        call_mod: []const u8,
        call_fn: []const u8,
    };
    const View = maru.session.dock_panel.View;
    var seen: usize = 0;
    inline for (@typeInfo(View).@"enum".fields) |field| {
        const view: View = @enumFromInt(field.value);
        const entry: Entry = switch (view) {
            // 탐색기 root 는 활성 pane 터미널의 cwd 를 따라간다(ET-CWD).
            .explorer => .{
                .file = "src/platform/macos/app_session/file_panel.zig",
                .follow = "pub fn followActiveTerminalCwd(self: *AppSession) void {",
                .call_file = "src/platform/macos/app_session/file_panel.zig",
                .call_mod = "    ",
                .call_fn = "followActiveTerminalCwd(self);",
            },
            // 목록의 저장소는 활성 pane 의 (경로, 호스트)를 따라간다(RS2).
            .source_control => .{
                .file = "src/platform/macos/app_session/git.zig",
                .follow = "pub fn followActiveTerminalRepo(self: *AppSession) void {",
                .call_file = "src/platform/macos/app_session/git.zig",
                .call_mod = "    ",
                .call_fn = "followActiveTerminalRepo(self);",
            },
            // scope root 스냅샷이 활성 surface 를 따라간다.
            .agent_sessions => .{
                .file = "src/platform/macos/app_session/agent_dock.zig",
                .follow = "pub fn refreshAgentSessionArchiveProjectScopeForFocus(self: *AppSession) void {",
                .call_file = "src/platform/macos/app_session.zig",
                .call_mod = "agent_dock.",
                .call_fn = "refreshAgentSessionArchiveProjectScopeForFocus(self);",
            },
            // 격자의 소스 세션 목록이 활성 pane 을 따라간다(IG1 §2.1).
            .image_gallery => .{
                .file = "src/platform/macos/app_session/image_gallery.zig",
                .follow = "pub fn refreshForFocus(self: *AppSession) void {",
                .call_file = "src/platform/macos/app_session.zig",
                .call_mod = "image_gallery_ops.",
                .call_fn = "refreshForFocus(self);",
            },
        };
        const raw = try std.Io.Dir.cwd().readFileAlloc(
            std.Io.Threaded.global_single_threaded.io(),
            entry.file,
            allocator,
            .limited(8 * 1024 * 1024),
        );
        defer allocator.free(raw);
        const src = raw;
        var needle_buf: [160]u8 = undefined;
        const needle = try std.fmt.bufPrint(&needle_buf, "{s}{s}", .{ entry.call_mod, entry.call_fn });
        // **그 함수가 실제로 있는가.** 이름만 적어 두고 지워지면 이 판정자가 잡는다.
        try std.testing.expect(std.mem.indexOf(u8, src, entry.follow) != null);
        // **그리고 실제로 불리는가.** 이것이 없으면 「함수는 남았는데 아무도 안 부른다」가 초록으로
        // 지나간다 — 뷰가 옛 pane 에 멈춘 채로.
        if (std.mem.eql(u8, entry.call_file, entry.file)) {
            try std.testing.expect(std.mem.indexOf(u8, src, needle) != null);
        } else {
            const caller_raw = try std.Io.Dir.cwd().readFileAlloc(
                std.Io.Threaded.global_single_threaded.io(),
                entry.call_file,
                allocator,
                .limited(8 * 1024 * 1024),
            );
            defer allocator.free(caller_raw);
            try std.testing.expect(std.mem.indexOf(u8, caller_raw, needle) != null);
        }
        seen += 1;
    }
    // 뷰가 늘었는데 위 switch 만 채우고 이 숫자를 안 고치는 일은 없다 — switch 가 exhaustive 라
    // 컴파일이 먼저 깨진다. 이 단언은 **분류가 통째로 비는** 경우(필드 0개)를 막는다.
    try std.testing.expectEqual(@typeInfo(View).@"enum".fields.len, seen);
    try std.testing.expect(seen >= 4);

    // **넷이 같은 자리에서 돈다**(적대적 검증 3회차). `runFramePreHousekeeping` 이 매 프레임 넷을 굴리므로,
    // 도크를 접은 채 pane 을 옮겼다가 다시 열어도 **다음 프레임에 스스로 낫는다** — 뷰 진입 갱신이 없는
    // `explorer` 가 뒤처지지 않는 근거가 그것이다.
    //
    // 그 자리가 갈리면(누가 한 뷰만 다른 주기로 옮기면) 그 뷰만 조용히 늦는다 — 화면에서 「가끔 안
    // 바뀐다」로 보이고, 그것이 이 축에서 사용자가 처음 신고한 증상이다.
    {
        const app_src = try std.Io.Dir.cwd().readFileAlloc(
            std.Io.Threaded.global_single_threaded.io(),
            "src/platform/macos/app_session.zig",
            allocator,
            .limited(8 * 1024 * 1024),
        );
        defer allocator.free(app_src);
        const at = std.mem.indexOf(u8, app_src, "fn runFramePreHousekeeping") orelse
            return error.HousekeepingMissing;
        const end = std.mem.indexOfPos(u8, app_src, at, "\n    }\n") orelse app_src.len;
        const body = app_src[at..end];
        // 넷 중 둘은 이 파일에서 직접, 둘은 각자 모듈의 pump 함수 안에서 불린다.
        for ([_][]const u8{
            "updateFileTree", //     → followActiveTerminalCwd
            "drainGitStatus", //     → followActiveTerminalRepo
            "ProjectScopeForFocus", //  agent_sessions
            "refreshForFocus", //       image_gallery
        }) |needle_frag| {
            try std.testing.expect(std.mem.indexOf(u8, body, needle_frag) != null);
        }
    }
}

test "원격 목록은 로컬 git 이 없어도 읽는다 (적대적 검증 5회차)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    _ = try session.resize(1400, 900, 1000);
    session.git_backend = try git_backend_mod.Backend.init(session.io);
    session.git_backend.?.state.?.shutting_down = true;

    // ⚠️ **`buildRemote` 는 `argv[0]` 을 버린다**(RS4a). 그러니 원격 읽기에 로컬 git 경로는 안 실린다 —
    //    그런데 제출부가 `locate()` 를 요구하면, 로컬에 git 이 없는 사용자는 **원격 SCM 을 통째로** 못
    //    쓰고 화면은 「git 이 설치되어 있지 않습니다」로 **엉뚱한 기계**를 가리킨다.
    //
    //    소스에서 그 규율을 못박는다 — 이 세션에 로컬 git 이 있어 런타임으로는 그 상태를 못 만든다.
    const src = try std.Io.Dir.cwd().readFileAlloc(
        std.Io.Threaded.global_single_threaded.io(),
        "src/platform/macos/app_session/git.zig",
        allocator,
        .limited(4 * 1024 * 1024),
    );
    defer allocator.free(src);
    try std.testing.expect(std.mem.indexOf(
        u8,
        src,
        "if (remote != null) git_command.remote_git_exe else git_backend_mod.locate(&exe_buf)",
    ) != null);

    // 그리고 **원격 목록을 보는 동안 그 안내가 첫 줄을 차지하지 않는다.** 제출부가 그 깃발을 지우지만
    // **첫 제출 전 창**이 남으므로, 안내 자체가 원격을 안다.
    session.git_missing = true;
    git_ops.rememberGitRepo(session, "/srv/app");
    git_ops.rememberGitRepoDest(session, "user@build-box");
    var probe: [std.fs.max_path_bytes]u8 = undefined;
    try std.testing.expect(!std.mem.eql(
        u8,
        git_ops.scmEmptyNotice(session, &probe),
        maru.i18n.t(.git_not_installed),
    ));
    // 로컬 목록에서는 그 안내가 **그대로 첫 줄이다** — 무조건 지우는 것이 아니다.
    git_ops.rememberGitRepoDest(session, null);
    try std.testing.expectEqualStrings(
        maru.i18n.t(.git_not_installed),
        git_ops.scmEmptyNotice(session, &probe),
    );
}

test "원격 읽기 실패 사유는 호스트를 넘지 않는다 (RS4 §2.2 ⑺ 적대적 검증 3회차)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    _ = try session.resize(1400, 900, 1000);
    session.git_backend = try git_backend_mod.Backend.init(session.io);
    session.git_backend.?.state.?.shutting_down = true;

    git_ops.rememberGitRepo(session, "/srv/app");
    git_ops.rememberGitRepoDest(session, "user@build-box");
    // 원격 읽기가 「그 기계에 git 이 없다」로 실패했다.
    session.git_failed = true;
    session.git_failure = .remote_git_missing;

    // ⚠️ **경로가 같고 호스트만 바뀌는 전환.** `rememberGitRepo` 는 경로로만 판정해 이것을 못 본다 —
    //    그대로 두면 「원격에 git 이 없습니다」가 **로컬 목록 위에** 남는다(RS2 2회차와 같은 뿌리).
    git_ops.rememberGitRepoDest(session, null);
    try std.testing.expect(!session.git_failed);
    try std.testing.expectEqual(git_backend_mod.ReadFailure.generic, session.git_failure);

    // 반대 방향도 같다 — 로컬 실패를 원격 목록 위에 물려주지 않는다.
    session.git_failed = true;
    session.git_failure = .generic;
    git_ops.rememberGitRepoDest(session, "user@build-box");
    try std.testing.expect(!session.git_failed);

    // 다른 호스트로 갈아탈 때도 마찬가지다.
    session.git_failed = true;
    session.git_failure = .remote_transport;
    git_ops.rememberGitRepoDest(session, "user@other-box");
    try std.testing.expect(!session.git_failed);
    try std.testing.expectEqual(git_backend_mod.ReadFailure.generic, session.git_failure);
}

test "원격 fetch: 우리가 실행하지 않고 활성 pane 에 넣는다 (RS4c)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    _ = try session.resize(1400, 900, 1000);
    session.git_backend = try git_backend_mod.Backend.init(session.io);
    session.git_backend.?.state.?.shutting_down = true;
    const launcher = file_panel_ops.filePanelDockControlRect(session) orelse return error.MissingDockLauncher;
    session.mouse(1, @floatFromInt(launcher.x + 1), @floatFromInt(launcher.y + 1), 0, 0);
    dock_ops.setDockView(session, .source_control);

    // ⑴ **분류가 «막는다»에서 «보낸다»로 넘어왔다.** 우리 ssh 명령에는 agent 도 tty 도 없어 인증이
    //    필요한 원격에서 **항상** 실패하는데, 그것을 「막힘」으로 두면 원격에서는 영영 못 가져온다.
    // (분류의 강제력은 「원격 목록을 보는 동안…」 판정자의 exhaustive switch 가 진다.)

    // ⑵ **원격이면 백엔드로 안 간다.** 갔다면 `SSH_AUTH_SOCK` 없이 도는 fetch 가 되고, 인증이 필요한
    //    원격에서는 그것이 곧 「늘 실패」다.
    git_ops.rememberGitRepo(session, "/srv/app");
    git_ops.rememberGitRepoDest(session, "user@build-box");
    // **활성 Term 을 실제로 그 원격으로 몬다**(관측 캐시를 손으로 쓰지 않고 `maru ssh` 진입 통지로).
    // 이게 없으면 pane 은 로컬이라 주입이 늘 거절되고, 그러면 ⑵·⑶ 이 아무것도 안 본다.
    const term = pane_ops.activePane(session).activeTerm();
    try term.surface.core.write("\x1b]5379;ssh;user@build-box\x07");
    // **원격이 있다는 것을 이미 안다**(그 전에는 「모른다」라서 아무 말도 하지 않는 것이 맞다 —
    // 그 규율은 로컬과 원격이 같다).
    session.git_result = .{
        .status = try git_backend_mod.worker_allocator.dupe(u8, "# branch.head main\n"),
        .remotes = try git_backend_mod.worker_allocator.dupe(u8, "origin\n"),
        .ok = true,
    };
    scm_dock_ops.clearScmWriteError(session);
    const before = session.scm_fetch_seq;
    scm_dock_ops.submitFetchForTest(session);
    try std.testing.expectEqual(before, session.scm_fetch_seq); // 백엔드 요청이 안 늘었다
    try std.testing.expectEqual(@as(u64, 0), session.scm_fetch_inflight);

    // ⑶ **조용한 무동작이 아니다.** 결과를 우리가 모르므로 그 사실을 말한다 — 안 그러면 사용자는
    //    목록이 곧 갱신될 것으로 읽는다.
    try std.testing.expect(session.scm_write_error != null);
    try std.testing.expectEqualStrings(
        maru.i18n.t(.scm_remote_fetch_injected),
        session.scm_write_error.?,
    );

    // ⑷ **엉뚱한 기계에 넣지 않는다**(적대적 검증 2회차). 목록의 호스트가 활성 pane 의 호스트와
    //    다르면, 거기 넣은 `git fetch` 는 **다른 저장소**를 가져오고 `git push` 는 **다른 저장소에 쓴다.**
    //    (`followActiveTerminalRepo` 가 도크가 보일 때만 도는 탓에 그 어긋남이 실제로 생길 수 있다.)
    git_ops.rememberGitRepoDest(session, "user@other-box"); // 목록만 다른 기계로
    scm_dock_ops.clearScmWriteError(session);
    scm_dock_ops.submitFetchForTest(session);
    try std.testing.expectEqualStrings(
        maru.i18n.t(.scm_inject_host_mismatch),
        session.scm_write_error.?,
    );
    // **넣지 못했으면 넣었다고 말하지 않는다** — 거절 사유가 그대로 남아 있다(덮어쓰면 화면이 거짓말한다).
    try std.testing.expect(!std.mem.eql(
        u8,
        session.scm_write_error.?,
        maru.i18n.t(.scm_remote_fetch_injected),
    ));

    // ⑸ **돌고 있는 것을 알면 안 넣는다 — 그러나 모르면 넣는다.**
    //
    //    이 기본값이 닫기 확인(`termHasRunningJob`)과 **반대**인 것이 요점이다: OSC 133 을 내는 원격
    //    셸은 소수라, 모름을 막음으로 접으면 흔한 경우를 통째로 막고 사용자는 왜 안 되는지도 모른다.
    git_ops.rememberGitRepoDest(session, "user@build-box"); // 다시 같은 기계로
    {
        const t = pane_ops.activePane(session).activeTerm();
        // ⓐ **모른다**(OSC 133 없음) → 넣는다.
        t.surface.core.semantic_state = .unknown;
        t.surface.core.alt_active = false;
        try std.testing.expect(!term_ops.activeTermKnownBusy(session, session.io));
        scm_dock_ops.clearScmWriteError(session);
        scm_dock_ops.submitFetchForTest(session);
        try std.testing.expectEqualStrings(
            maru.i18n.t(.scm_remote_fetch_injected),
            session.scm_write_error.?,
        );
        // ⓑ **돈다**(OSC 133 C) → 안 넣는다.
        t.surface.core.semantic_state = .command;
        try std.testing.expect(term_ops.activeTermKnownBusy(session, session.io));
        scm_dock_ops.clearScmWriteError(session);
        scm_dock_ops.submitFetchForTest(session);
        try std.testing.expectEqualStrings(maru.i18n.t(.scm_terminal_busy), session.scm_write_error.?);
        // ⓒ **alt 화면**(vim·less)은 semantic 과 무관하게 돈다 — 거기 넣으면 편집 중인 파일에 박힌다.
        t.surface.core.semantic_state = .prompt;
        t.surface.core.alt_active = true;
        try std.testing.expect(term_ops.activeTermKnownBusy(session, session.io));
        // ⓓ **프롬프트로 돌아오면** 다시 넣는다.
        t.surface.core.alt_active = false;
        try std.testing.expect(!term_ops.activeTermKnownBusy(session, session.io));
        scm_dock_ops.clearScmWriteError(session);
        scm_dock_ops.submitFetchForTest(session);
        try std.testing.expectEqualStrings(
            maru.i18n.t(.scm_remote_fetch_injected),
            session.scm_write_error.?,
        );
    }

    // ⑹ **주입 자리는 하나다.** `push`·`pull` 과 `fetch` 가 같은 함수를 지나야 「push 는 그 pane 에,
    //    fetch 는 다른 pane 에」가 원리적으로 불가능해진다(§6.4 — 주입 시점에 활성 pane 을 다시 묻는다).
    const src = try std.Io.Dir.cwd().readFileAlloc(
        std.Io.Threaded.global_single_threaded.io(),
        "src/platform/macos/app_session/scm_dock.zig",
        allocator,
        .limited(4 * 1024 * 1024),
    );
    defer allocator.free(src);
    try std.testing.expectEqual(
        @as(usize, 1),
        std.mem.count(u8, src, "term_ops.submitPaste(self, command"),
    );
    try std.testing.expect(std.mem.count(u8, src, "injectIntoActiveTerminal(self,") >= 2);
}

test "원격 쓰기 뒤 갱신: 경로가 같아도 호스트가 다르면 다른 저장소다 (RS4a 8회차)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    _ = try session.resize(1400, 900, 1000);
    session.git_backend = try git_backend_mod.Backend.init(session.io);
    session.git_backend.?.state.?.shutting_down = true;
    const launcher = file_panel_ops.filePanelDockControlRect(session) orelse return error.MissingDockLauncher;
    session.mouse(1, @floatFromInt(launcher.x + 1), @floatFromInt(launcher.y + 1), 0, 0);
    dock_ops.setDockView(session, .source_control);

    // 원격 `/srv/app` 에 쓰기를 걸었다.
    git_ops.rememberGitRepo(session, "/srv/app");
    git_ops.rememberGitRepoDest(session, "user@build-box");
    scm_dock_ops.rememberWriteRepoForTest(session, "/srv/app", "user@build-box");
    try std.testing.expect(scm_dock_ops.activeIsWriteTargetForTest(session, "/srv/app"));

    // ⚠️ 그 쓰기가 도는 동안 pane 이 **로컬** `/srv/app` 으로 바뀌었다. 경로는 같다.
    git_ops.rememberGitRepoDest(session, null);
    try std.testing.expect(!scm_dock_ops.activeIsWriteTargetForTest(session, "/srv/app"));

    // 반대 방향도 같다 — 로컬에 쓰고 원격을 보고 있으면 그것도 다른 기계다.
    scm_dock_ops.rememberWriteRepoForTest(session, "/srv/app", null);
    try std.testing.expect(scm_dock_ops.activeIsWriteTargetForTest(session, "/srv/app"));
    git_ops.rememberGitRepoDest(session, "user@build-box");
    try std.testing.expect(!scm_dock_ops.activeIsWriteTargetForTest(session, "/srv/app"));

    // 다른 호스트끼리도 갈린다(둘 다 원격인데 기계가 다르다).
    scm_dock_ops.rememberWriteRepoForTest(session, "/srv/app", "user@other-box");
    try std.testing.expect(!scm_dock_ops.activeIsWriteTargetForTest(session, "/srv/app"));
}

test "소스 컨트롤: 활성 터미널이 다른 저장소로 옮겨 가면 목록·감시를 그쪽으로 옮긴다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    _ = try session.resize(1400, 900, 1000);

    // 실제 git을 띄우지 않는다(검증 대상은 "무효화·감시 이동"이지 목록 내용이 아니다). 뷰를 켜기 전에 세워야
    // `refreshGitStatus`가 워커를 띄우지 않는다.
    session.git_backend = try git_backend_mod.Backend.init(session.io);
    session.git_backend.?.state.?.shutting_down = true;

    const launcher = file_panel_ops.filePanelDockControlRect(session) orelse return error.MissingDockLauncher;
    session.mouse(1, @floatFromInt(launcher.x + 1), @floatFromInt(launcher.y + 1), 0, 0);
    dock_ops.setDockView(session, .source_control);

    var buf: [std.fs.max_path_bytes]u8 = undefined;
    const repo = git_ops.gitRepoRoot(session, &buf) orelse return error.SkipZigTest;

    // 옛 저장소의 목록이 실려 있는 상태를 만든다(다른 저장소에서 읽어 온 결과).
    git_ops.rememberGitRepo(session, "/somewhere/else");
    git_ops.ensureGitWatch(session, "/somewhere/else");
    if (session.takeFileTreeWatchRoot()) |taken| allocator.free(taken);
    session.git_result = .{ .status = try git_backend_mod.worker_allocator.dupe(u8, "# branch.head main\n"), .ok = true };
    session.git_failed = true;
    session.scm_selected_row = 3;

    git_ops.followActiveTerminalRepo(session);

    // 남의 저장소 상태가 화면에 남으면 안 된다 — 결과·실패·선택을 전부 버리고 새 저장소로 갈아탄다.
    try std.testing.expect(session.git_result == null);
    try std.testing.expect(!session.git_failed);
    try std.testing.expect(session.scm_selected_row == null);
    try std.testing.expectEqualStrings(repo, session.git_repo.?);
    var want_watch: [std.fs.max_path_bytes]u8 = undefined;
    const watch = try std.fmt.bufPrint(&want_watch, "{s}/.git", .{repo});
    try std.testing.expectEqualStrings(watch, session.peekFileTreeWatchRoot().?);

    // **같은 저장소면 아무것도 하지 않는다.** 매 tick 도는 경로라 여기서 무효화가 반복되면 목록이 영영 안 뜬다.
    if (session.takeFileTreeWatchRoot()) |taken| allocator.free(taken);
    session.git_result = .{ .status = try git_backend_mod.worker_allocator.dupe(u8, "# branch.head main\n"), .ok = true };
    git_ops.followActiveTerminalRepo(session);
    try std.testing.expect(session.git_result != null);
    try std.testing.expect(session.peekFileTreeWatchRoot() == null);
}

// [사용자 보고 2026-08-12] "원격 ssh나 깃 연결 안 된 터미널이 활성될 때 이전 깃 이력이 나온다".
//
// 둘은 원인이 다르고, 하나만 결함이다. **원격은 §3.5가 규정한 동작이다** — OSC 7·커널 조회가 둘 다 원격 경로를
// 로컬에 대고 해석하게 만들어 1순위를 비우므로, 2순위(직전에 읽은 저장소)가 대상을 잡는다. 반면 **저장소 아닌
// 로컬 폴더**는 같은 문서가 "터미널이 답했으면 결론은 저장소 없음"이라고 못 박은 쪽인데도 옛 목록이 남았다:
// `gitRepoRoot`가 "모른다"(파일 Term·원격)와 "없다"(비저장소)를 같은 `null`로 뭉개서 호출자가 구별할 수 없었고,
// `followActiveTerminalRepo`는 안전한 쪽(직전 판단 유지)으로만 읽을 수밖에 없었다. 3-상태 `gitRepoTarget`이 그
// 구별을 만든다 — 이 테스트가 **두 방향을 같은 자리에서** 고정해, 무효화를 넓혀 원격까지 지우는 회귀도 막는다.
test "소스 컨트롤: 저장소 아닌 폴더로 옮기면 옛 목록을 버리고, 원격에서는 직전 판단을 유지한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    _ = try session.resize(1400, 900, 1000);

    // 실제 git을 띄우지 않는다(검증 대상은 "무효화 판정"이지 목록 내용이 아니다 — 위 테스트와 같은 규율).
    session.git_backend = try git_backend_mod.Backend.init(session.io);
    session.git_backend.?.state.?.shutting_down = true;

    const launcher = file_panel_ops.filePanelDockControlRect(session) orelse return error.MissingDockLauncher;
    session.mouse(1, @floatFromInt(launcher.x + 1), @floatFromInt(launcher.y + 1), 0, 0);
    dock_ops.setDockView(session, .source_control);

    var buf: [std.fs.max_path_bytes]u8 = undefined;
    const repo = git_ops.gitRepoRoot(session, &buf) orelse return error.SkipZigTest; // 저장소 밖에서 돌면 건너뛴다
    git_ops.rememberGitRepo(session, repo);

    // ⑴ **저장소 아닌 폴더로 옮긴다.** 관측 캐시를 손으로 쓰지 않고 실제 OSC 7으로 몬다(직접 필드를 쓰면 다음
    // `refreshTermObservation`이 코어에서 다시 읽어 덮을 수 있어, 통과해도 이유를 믿을 수 없다).
    const term = pane_ops.activePane(session).activeTerm();
    try term.surface.core.write("\x1b]7;file:///tmp\x07");
    // walk-up이 상위에서 `.git`을 만나면(예: `/`가 저장소인 특이 머신) 이 단언은 의미를 잃는다 — 건너뛴다.
    var probe_buf: [std.fs.max_path_bytes]u8 = undefined;
    if (git_ops.gitRepoRoot(session, &probe_buf) != null) return error.SkipZigTest;
    // **타는 분기를 못 박는다.** `.unknown`(OSC 7이 안 먹어 아무도 답을 못 한 상태)이어도 위 skip 조건은 똑같이
    // 통과하는데, 그때 아래 단언들은 전혀 다른 경로를 검증하게 된다 — ⑵에서 실제로 그 착오가 있었다.
    // 이 단언이 `null`의 정체를 "저장소 없음 확정"으로 고정하고, 그 값이 곧 뷰가 "git 저장소가 아닙니다"를
    // 고르는 조건이다(`git_missing`이 아니고 판정이 `.none`).
    try std.testing.expectEqual(
        git_ops.RepoTarget.none,
        std.meta.activeTag(git_ops.gitRepoTarget(session, &probe_buf)),
    );
    // 판정과 **문구가 같은 자리에서** 갈리는지도 함께 고정한다 — 판정만 검증하면 뷰가 다른 조건으로 문구를
    // 고르는 회귀(실제로 있었다: `.unknown`까지 이 문구로 뭉갠 것)를 못 잡는다.
    try std.testing.expectEqualStrings(maru.i18n.t(.git_not_a_repo), git_ops.scmEmptyNotice(session, &probe_buf));

    session.git_result = .{ .status = try git_backend_mod.worker_allocator.dupe(u8, "# branch.head main\n"), .ok = true };
    session.git_failed = true;
    session.scm_selected_row = 3;
    git_ops.followActiveTerminalRepo(session);

    // 옛 저장소의 목록·실패·선택이 전부 사라져야 뷰가 "git 저장소가 아닙니다" 안내를 낸다(그 안내는
    // `git_result == null`일 때만 그려지므로, 목록을 안 버리면 안내가 나올 자리 자체가 없다).
    try std.testing.expect(session.git_result == null);
    try std.testing.expect(!session.git_failed);
    try std.testing.expect(session.scm_selected_row == null);
    try std.testing.expect(session.git_inflight == 0);

    // **두 번째 호출은 아무것도 하지 않는다.** 매 tick 도는 경로라 무효화가 반복되면 프레임마다 렌더를 깨운다.
    session.metal_dirty = false;
    git_ops.followActiveTerminalRepo(session);
    try std.testing.expect(!session.metal_dirty);

    // ⑵ **원격은 지우지 않는다.** maru ssh 진입 통지로 1순위를 비우면 2순위가 직전 저장소를 답하므로 목록이
    // 그대로 남는 것이 §3.5의 규정이다 — 여기서 지우면 SSH 터미널로 옮길 때마다 목록이 깜빡인다.
    // **이 단계가 타는 분기는 `.repo`(2순위)다**, `.unknown`이 아니다 — 적대적 검증에서 `.unknown`을 무효화로
    // 바꿔도 이 단언이 통과해 그 사실이 드러났다. 그래서 ⑶이 그 분기를 따로 고정한다.
    try term.surface.core.write("\x1b]5379;ssh;user@build-box\x07");
    session.git_result = .{ .status = try git_backend_mod.worker_allocator.dupe(u8, "# branch.head main\n"), .ok = true };
    git_ops.followActiveTerminalRepo(session);
    try std.testing.expect(session.git_result != null);

    // ⑶ **`.unknown`(아무도 답을 못 줌)도 유지다.** 2순위마저 해석에 실패하는 상태를 만든다 — 목록을 읽은
    // 저장소가 그 사이 사라진 경우다. 여기서 지우면 "모르면 직전 판단을 유지한다"(§3.5 ⑶)가 깨져, 저장소를
    // 잠시 못 읽는 순간마다 목록이 사라진다.
    git_ops.rememberGitRepo(session, "/maru-nonexistent-scm-probe");
    // 전제를 **단언으로** 고정한다 — 하네스가 탐색기 root를 갖게 되면 3순위가 답해 `.repo`로 빠지고, 이 단계는
    // 조용히 다른 분기를 검증하게 된다(⑵에서 실제로 그런 착오가 있었다).
    try std.testing.expect(session.file_tree.rootCount() == 0);
    var target_buf: [std.fs.max_path_bytes]u8 = undefined;
    try std.testing.expectEqual(
        git_ops.RepoTarget.unknown,
        std.meta.activeTag(git_ops.gitRepoTarget(session, &target_buf)),
    );
    // **`.unknown`은 "저장소가 아니다"와 다른 사실이고 문구도 달라야 한다.** 둘을 한 문구로 뭉개면, 저장소 안에
    // 서 있는데 물어볼 곳만 없는 상태(원격 세션·diff 열람 중)에서 뷰가 없는 사실을 단정한다 — 2026-08-13에
    // 로컬 세션이 원격으로 오판됐을 때 이 문구가 진짜 원인을 가린 그 결함이다.
    try std.testing.expectEqualStrings(maru.i18n.t(.git_repo_unknown), git_ops.scmEmptyNotice(session, &target_buf));
    git_ops.followActiveTerminalRepo(session);
    try std.testing.expect(session.git_result != null);
}

// [사용자 보고 2026-08-13] 로컬 저장소에 서 있는 터미널인데 소스 컨트롤 뷰가 "git 저장소가 아닙니다"를 냈다.
// 같은 화면의 사이드바·상태바에는 `<host>:<절대경로>`가 `~` 축약 없이 찍혀 있었는데, **그 형식은 원격 판정일 때만**
// 나온다(`sidebarCwdPath`). 즉 로컬 세션이 통째로 원격으로 읽히고 있었다.
//
// 셸이 실제로 무엇을 보내는지 pty로 캡처해 보니 `file://<그 머신의 hostname>/…`였고, 화면의 host 접두와 **같은
// 문자열**이었다. 같은 문자열끼리는 `hostIsLocal`이 반드시 로컬을 내므로, 앱이 대조한 로컬 이름은 그 시점의 것이
// 아니었다 — `localHostname()`이 앱 시작 때 한 번 읽은 값을 수명 내내 굳혔기 때문이다(macOS는 DHCP 도메인·Wi-Fi
// 전환·슬립 복귀로 hostname 접미를 바꾸고, 구성 전에는 `localhost`나 실패를 답한다).
//
// 앱 입장에서 "낡은 로컬 이름"과 "어긋난 authority가 실린 OSC 7"은 **구별할 수 없는 같은 상태**다(둘 다 비교가
// 어긋난다). 그래서 재현은 후자로 만들고, 그 상태가 화면 표시부터 저장소 판정·안내 문구까지 어떻게 한 줄기로
// 무너지는지를 고정한다. 대조군은 **빈 authority** — maru의 로컬 셸 통합이 보내는 형식이고(shell_integration.zig),
// 로컬 이름이 어떤 상태든 로컬로 읽혀 같은 경로가 정상으로 돌아온다. 그 대조가 곧 이 수정의 효과다.
// **원격 경로를 화면에 적는 자리는 전부 `<host>:` 를 붙인다.**
//
// 폴더줄이 그 규율을 세우고 이유까지 적어 두었다: host 가 없으면 사용자가 그 경로를 **로컬에서 열려다
// 실패한다**(`host:path` 는 scp/rsync 관례라 원격임이 즉시 읽힌다). 그런데 종료 placeholder 안내는
// 그 규율에서 **빠져 있었다** — 같은 원격 경로가 한 화면에서 두 가지로 보였고, 틀린 쪽이 그쪽이었다.
//
// 이 판정자는 「원격 pane 인데 로컬 것처럼 보여 준다」는 **같은 뿌리**를 센다. 이 저장소에서 그 뿌리가
// 반복해 나왔다(목록 안내 · diff 표식 · 쓰기 대상 · 갱신 대상 · 읽기 실패 사유 · 갤러리 대화).
test "원격 경로를 적는 자리는 전부 host 를 붙인다" {
    const allocator = std.testing.allocator;
    const src = try std.Io.Dir.cwd().readFileAlloc(
        std.Io.Threaded.global_single_threaded.io(),
        "src/platform/macos/app_session.zig",
        allocator,
        .limited(8 * 1024 * 1024),
    );
    defer allocator.free(src);

    // 폴더줄: 원격이면 `<host>:<path>`.
    const sidebar_at = std.mem.indexOf(u8, src, "pub fn sidebarCwdPath") orelse return error.SidebarMissing;
    const sidebar_end = std.mem.indexOfPos(u8, src, sidebar_at, "\n}\n") orelse src.len;
    try std.testing.expect(std.mem.indexOf(u8, src[sidebar_at..sidebar_end], "termCwdIsRemote(term)") != null);

    // 종료 안내: **같은 규율**을 지난다. 이것이 없으면 그 줄이 원격 경로를 로컬처럼 적는다.
    const ended_at = std.mem.indexOf(u8, src, "pub fn writeEndedPlaceholderGuidance") orelse
        return error.EndedGuidanceMissing;
    const ended_end = std.mem.indexOfPos(u8, src, ended_at, "\n    }\n") orelse src.len;
    const ended = src[ended_at..ended_end];
    try std.testing.expect(std.mem.indexOf(u8, ended, "termCwdIsRemote(term)") != null);
    try std.testing.expect(std.mem.indexOf(u8, ended, "termDisplayHost(term)") != null);
    // 그리고 **그 값을 실제로 쓰는 자리**는 원격이면 cwd 를 안 쓴다 — 안내가 「돌아갈 자리」로 읽히므로.
    const respawn_at = std.mem.indexOf(u8, src, "fn respawnEndedPlaceholder") orelse return error.RespawnMissing;
    const respawn_end = std.mem.indexOfPos(u8, src, respawn_at, "\n    }\n") orelse src.len;
    try std.testing.expect(std.mem.indexOf(u8, src[respawn_at..respawn_end], "if (!termCwdIsRemote(tomb))") != null);
}

test "OSC 7 authority가 로컬 이름과 어긋나면 로컬 저장소가 통째로 원격 취급된다(2026-08-13 재현)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    var exe_buf: [std.fs.max_path_bytes]u8 = undefined;
    const exe = git_backend_mod.locate(&exe_buf) orelse return error.SkipZigTest;
    // 격리된 저장소를 쓴다 — maru 저장소 안에서 돌면 하네스의 cwd가 walk-up으로 같은 답을 줘서, 판정이 바뀐 것인지
    // 원래 그랬던 것인지 구별되지 않는다.
    // **경로에 pid를 붙인다**(이 파일의 `/tmp/maru-e3-app-{d}` 관행). 고정 이름이면 같은 머신에서 두 test
    // 바이너리가 겹칠 때 서로의 저장소를 `rm -rf`로 지워, skip이 아니라 엉뚱한 실패가 난다.
    var repo_path_buf: [64]u8 = undefined;
    const repo = std.fmt.bufPrint(&repo_path_buf, "/tmp/maru-stale-host-{d}", .{std.c.getpid()}) catch return error.SkipZigTest;
    _ = git_backend_mod.testRunQuiet(&.{ "/bin/rm", "-rf", repo });
    defer _ = git_backend_mod.testRunQuiet(&.{ "/bin/rm", "-rf", repo });
    if (!git_backend_mod.testRunQuiet(&.{ exe, "init", "-q", "-b", "main", repo })) return error.SkipZigTest;
    {
        // `/tmp`나 `/`가 저장소인 특이 머신에서는 아래 대조가 의미를 잃는다.
        var probe: [std.fs.max_path_bytes]u8 = undefined;
        if (AppSession.repoRootFor("/tmp", &probe) != null) return error.SkipZigTest;
    }
    // 2·3순위가 답을 주면 `.unknown` 단언이 조용히 다른 분기를 검증한다 — 전제를 단언으로 못 박는다.
    try std.testing.expect(session.git_repo == null);
    try std.testing.expect(session.file_tree.rootCount() == 0);

    const term = pane_ops.activePane(session).activeTerm();
    var osc_buf: [std.fs.max_path_bytes + 64]u8 = undefined;

    // ⑴ **재현**: 저장소 경로는 그대로 보고하고 authority만 로컬 이름과 어긋나게 싣는다.
    try term.surface.core.write(try std.fmt.bufPrint(&osc_buf, "\x1b]7;file://stale-name.example{s}\x07", .{repo}));
    term_ops.refreshTermObservation(session, term, false, false);
    try std.testing.expect(termCwdIsRemote(term));
    // 화면은 사용자가 본 그대로가 된다 — host 접두가 붙고 `~` 축약이 사라진다.
    const shown = try sidebarCwdPath(session, term);
    defer allocator.free(shown);
    var expect_buf: [std.fs.max_path_bytes]u8 = undefined;
    try std.testing.expectEqualStrings(try std.fmt.bufPrint(&expect_buf, "stale-name.example:{s}", .{repo}), shown);
    // 판정은 1순위를 통째로 잃는다 — **저장소 안에 서 있는데도** 아무도 답하지 못한다.
    var target_buf: [std.fs.max_path_bytes]u8 = undefined;
    try std.testing.expectEqual(
        git_ops.RepoTarget.unknown,
        std.meta.activeTag(git_ops.gitRepoTarget(session, &target_buf)),
    );
    // 그리고 안내는 "모른다"여야 한다 — "저장소가 아니다"라는 단정이 이 사건에서 진짜 원인을 가렸다.
    try std.testing.expectEqualStrings(maru.i18n.t(.git_repo_unknown), git_ops.scmEmptyNotice(session, &target_buf));

    // ⑵ **대조군(= 수정)**: 로컬 셸 통합이 보내는 빈 authority면 같은 경로가 로컬로 읽혀 저장소가 잡힌다.
    try term.surface.core.write(try std.fmt.bufPrint(&osc_buf, "\x1b]7;file://{s}\x07", .{repo}));
    term_ops.refreshTermObservation(session, term, false, false);
    try std.testing.expect(!termCwdIsRemote(term));
    const local_shown = try sidebarCwdPath(session, term);
    defer allocator.free(local_shown);
    try std.testing.expectEqualStrings(repo, local_shown);
    try std.testing.expectEqual(
        git_ops.RepoTarget.repo,
        std.meta.activeTag(git_ops.gitRepoTarget(session, &target_buf)),
    );
}

// 안내를 내는 소비처는 **전수로** 같은 3-상태 구분을 써야 한다. 저장소 판정을 쓰는 자리는 다섯인데 넷
// (`refreshGitStatus`·`followActiveTerminalRepo`·`openDiffForScmRow`·`captureTurnSnapshot`)은 문구를 내지 않고,
// 사용자에게 말하는 것은 도크의 빈 안내와 **브랜치 메뉴** 둘뿐이다(전수 표: editor-surface-dock.md "빈 상태").
// 도크만 고치고 브랜치 메뉴를 놓쳤던 것을 적대적 검증에서 잡았고, 그때 적은 목록이 `followActiveTerminalRepo`를
// 빠뜨려 "전수"가 아니었던 것도 같은 방식으로 잡았다.
//
// **위 재현 테스트와 분리해 둔다.** 한 함수에 담으면 앞 단계가 깨질 때 이 소비처는 실행조차 되지 않아 서로
// 다른 소비처의 회귀가 한 신호로 뭉개진다 — mutation 검증에서 실제로 그 일이 일어났다(도크 문구를 되돌리자
// 브랜치 메뉴 단언이 도달 불가가 됐다).
test "브랜치 메뉴도 `.unknown`을 저장소 없음으로 단정하지 않는다(안내 소비처 전수)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    var exe_buf: [std.fs.max_path_bytes]u8 = undefined;
    const exe = git_backend_mod.locate(&exe_buf) orelse return error.SkipZigTest;
    var repo_path_buf: [64]u8 = undefined; // pid 접미 — 위 재현 테스트와 같은 이유(동시 실행 시 서로를 지운다)
    const repo = std.fmt.bufPrint(&repo_path_buf, "/tmp/maru-branch-unknown-{d}", .{std.c.getpid()}) catch return error.SkipZigTest;
    _ = git_backend_mod.testRunQuiet(&.{ "/bin/rm", "-rf", repo });
    defer _ = git_backend_mod.testRunQuiet(&.{ "/bin/rm", "-rf", repo });
    if (!git_backend_mod.testRunQuiet(&.{ exe, "init", "-q", "-b", "main", repo })) return error.SkipZigTest;
    {
        var probe: [std.fs.max_path_bytes]u8 = undefined;
        if (AppSession.repoRootFor("/tmp", &probe) != null) return error.SkipZigTest;
    }
    // 전제를 단언으로 못 박는다 — 2·3순위가 답하면 `.repo`로 빠져 이 테스트가 조용히 다른 분기를 검증한다.
    try std.testing.expect(session.git_repo == null);
    try std.testing.expect(session.file_tree.rootCount() == 0);

    // 백엔드를 미리 만들어 둔다 — `requestBranchMenu`가 지연 생성하는 경로에서 스레드를 새로 띄우지 않게.
    session.git_backend = try git_backend_mod.Backend.init(session.io);
    session.git_backend.?.state.?.shutting_down = true;

    const term = pane_ops.activePane(session).activeTerm();
    var osc_buf: [std.fs.max_path_bytes + 64]u8 = undefined;
    try term.surface.core.write(try std.fmt.bufPrint(&osc_buf, "\x1b]7;file://stale-name.example{s}\x07", .{repo}));
    term_ops.refreshTermObservation(session, term, false, false);
    var target_buf: [std.fs.max_path_bytes]u8 = undefined;
    try std.testing.expectEqual( // 이 테스트가 검증하려는 상태가 맞는지 먼저 고정한다
        git_ops.RepoTarget.unknown,
        std.meta.activeTag(git_ops.gitRepoTarget(session, &target_buf)),
    );

    settings_ops.requestBranchMenu(session, .switch_branch);
    try std.testing.expect(session.chrome_host.notice.open); // 조용히 무시하지 않고 사용자에게 말한다
    try std.testing.expect(std.mem.startsWith(u8, &session.notice_message_buf, git_ops.noticeRepoUnknown()));
    // **`branch_menu_pending`은 일부러 단언하지 않는다.** 위에서 백엔드를 `shutting_down`으로 두었으므로
    // `submitBranches`는 어느 분기에서도 false를 돌려준다(git_backend.zig) — 그 상태에서 "요청이 안 걸렸다"를
    // 단언하면 `.unknown` 분기가 사라져도 통과하는 공허한 검사가 된다(코드 리뷰에서 지적). 이 테스트가
    // 고정하는 것은 **어느 안내를 내는가**이고, 그 판정이 도크와 갈리지 않는지다.
}

// [GUI 확인 2026-08-12] 저장소를 지웠더니 **도크는 "git 저장소가 아닙니다"인데 상태바·사이드바는 옛 브랜치를
// 계속 표시**했다. 원인은 `term.git_branch` 캐시의 키가 cwd 하나이고 무효화 경로가 **어디에도 없었다**는 것 —
// 같은 폴더에서 `git checkout`·`git init`·저장소 삭제가 일어나면 답이 바뀌는데 cwd는 그대로라 영구 캐시가 된다.
// 소스 컨트롤의 walk-up 캐시와 같은 주기로 만료시켜 고쳤고, 이 테스트가 **절약(주기 안 적중)과 갱신(만료 뒤
// 재계산)을 함께** 고정한다 — 만료만 검증하면 매 프레임 fs를 읽는 회귀가 통과하고, 적중만 검증하면 stale이
// 통과한다.
test "상태바 브랜치: `.git` 이벤트가 갱신을 앞당기고, 하한과 백스톱이 fs 읽기를 묶는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    var exe_buf: [std.fs.max_path_bytes]u8 = undefined;
    const exe = git_backend_mod.locate(&exe_buf) orelse return error.SkipZigTest;
    // 임시 저장소를 만든다 — 브랜치를 실제로 바꿔야 "같은 cwd, 다른 답"이 재현된다.
    //
    // **저장소 밖에 만든다.** `.zig-cache` 아래에 두면 ⑶에서 `.git`을 지운 뒤 walk-up이 상위로 올라가 maru
    // 저장소의 `.git`을 찾아, "표시가 사라진다"가 아니라 "maru 브랜치가 보인다"가 된다(그 단언이 조용히 다른
    // 것을 검증하게 된다).
    const repo = "/tmp/maru-branch-cache-test";
    _ = git_backend_mod.testRunQuiet(&.{ "/bin/rm", "-rf", repo });
    defer _ = git_backend_mod.testRunQuiet(&.{ "/bin/rm", "-rf", repo });
    if (!git_backend_mod.testRunQuiet(&.{ exe, "init", "-q", "-b", "main", repo })) return error.SkipZigTest;

    const term = pane_ops.activePane(session).activeTerm();
    // `/tmp`나 `/`가 저장소인 특이 머신에서는 ⑶이 성립하지 않는다 — 먼저 확인하고 건너뛴다.
    {
        var probe: [std.fs.max_path_bytes]u8 = undefined;
        if (AppSession.repoRootFor("/tmp", &probe) != null) return error.SkipZigTest;
    }
    // 첫 호출: 캐시가 비어 있으니 읽는다.
    try std.testing.expectEqualStrings("main", git_ops.termGitBranchForCwd(session, term, repo).?);

    // 같은 cwd에서 브랜치를 바꾼다(체크아웃은 cwd를 건드리지 않는다 — 그게 이 결함의 핵심이었다).
    if (!git_backend_mod.testRunQuiet(&.{ exe, "-C", repo, "checkout", "-q", "-b", "other" })) return error.SkipZigTest;

    // ⑴ **주기 안에는 캐시를 쓴다.** 사이드바는 매 프레임 빌드되므로 이 절약이 사라지면 fs 읽기가 프레임마다 돈다.
    try std.testing.expectEqualStrings("main", git_ops.termGitBranchForCwd(session, term, repo).?);

    // ⑵ **`.git` 변경 이벤트가 갱신의 1차 경로다.** checkout은 cwd를 안 바꿔 OSC 7으로 감지되지 않으므로, 이
    // 신호가 없으면 백스톱 주기까지(초 단위) 옛 브랜치가 남는다. 이벤트는 만료를 **앞당기기만** 하고 하한
    // (`git_branch_event_floor_ns`)을 지키므로, 직후 호출은 아직 캐시를 쓰는 것이 정상이다.
    var head_buf: [std.fs.max_path_bytes]u8 = undefined;
    const head_path = try std.fmt.bufPrint(&head_buf, "{s}/.git/HEAD", .{repo});
    const before_event = term.git_branch_polled_ns;
    session.fileTreeChanged(head_path);
    try std.testing.expect(term.git_branch_polled_ns < before_event); // 만료를 앞당겼다
    try std.testing.expectEqualStrings("main", git_ops.termGitBranchForCwd(session, term, repo).?); // 하한 안: 아직 캐시

    // **이벤트 폭주에도 하한이 유지된다.** rebase는 `.git`을 수백 번 건드린다 — 이벤트마다 즉시 재계산하면
    // 프레임마다 term 수만큼 fs를 읽어 폴링보다 나빠진다. 100번 보내도 "즉시 만료"로 떨어지지 않아야 한다.
    for (0..100) |_| session.fileTreeChanged(head_path);
    const now_ns = std.Io.Clock.awake.now(session.io).nanoseconds;
    try std.testing.expect(now_ns - term.git_branch_polled_ns < git_ops.git_branch_backstop_interval_ns);

    // ⑶ 하한이 지난 뒤에는 읽는다. 시계를 기다리지 않고 마지막 계산 시각을 과거로 밀어 만료를 만든다.
    term.git_branch_polled_ns = 0;
    try std.testing.expectEqualStrings("other", git_ops.termGitBranchForCwd(session, term, repo).?);

    // ⑷ **저장소가 사라지면 표시도 사라진다**(GUI에서 실제로 stale하던 그 경로).
    var git_dir_buf: [std.fs.max_path_bytes]u8 = undefined;
    const git_dir = std.fmt.bufPrintZ(&git_dir_buf, "{s}/.git", .{repo}) catch return error.SkipZigTest;
    _ = git_backend_mod.testRunQuiet(&.{ "/bin/rm", "-rf", git_dir });
    term.git_branch_polled_ns = 0;
    try std.testing.expect(git_ops.termGitBranchForCwd(session, term, repo) == null);
}

// **무효화의 대칭**: 저장소 아닌 폴더에서 돌아왔을 때 목록이 되살아나는가. `.none` 정리는 새 읽기를 걸지 않고
// (읽을 저장소가 없다) `git_inflight`를 0으로 놓기만 하므로, 같은 저장소로 복귀하면 `followActiveTerminalRepo`의
// "바뀔 때만"이 no-op이 되어 **복구가 전적으로 tick의 "결과가 없으면 한 번 건다"에 달려 있다**. 그 가드 조건이
// 바뀌면(플래그 추가 등) 목록이 영영 빈 채로 남는데 무효화 테스트는 그대로 통과한다 — 그 공백을 여기서 막는다.
test "소스 컨트롤: 저장소 아닌 폴더에서 돌아오면 같은 저장소를 다시 읽는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    _ = try session.resize(1400, 900, 1000);

    session.git_backend = try git_backend_mod.Backend.init(session.io);
    session.git_backend.?.state.?.shutting_down = true; // 워커를 띄우지 않는다(검증 대상은 "읽기를 걸었나")

    const launcher = file_panel_ops.filePanelDockControlRect(session) orelse return error.MissingDockLauncher;
    session.mouse(1, @floatFromInt(launcher.x + 1), @floatFromInt(launcher.y + 1), 0, 0);
    dock_ops.setDockView(session, .source_control);

    var buf: [std.fs.max_path_bytes]u8 = undefined;
    const repo = git_ops.gitRepoRoot(session, &buf) orelse return error.SkipZigTest;
    var repo_copy: [std.fs.max_path_bytes]u8 = undefined;
    @memcpy(repo_copy[0..repo.len], repo);
    const home_repo = repo_copy[0..repo.len];
    // git이 없는 머신에서는 `submitGitRead`가 미설치로 표시하고 seq를 올리지 않는다 — 그 경우 이 판정은 성립하지 않는다.
    var exe_buf: [std.fs.max_path_bytes]u8 = undefined;
    if (git_backend_mod.locate(&exe_buf) == null) return error.SkipZigTest;
    git_ops.rememberGitRepo(session, home_repo);

    // 저장소 아닌 폴더로 나간다(위 테스트가 고정한 경로).
    const term = pane_ops.activePane(session).activeTerm();
    try term.surface.core.write("\x1b]7;file:///tmp\x07");
    var probe_buf: [std.fs.max_path_bytes]u8 = undefined;
    if (git_ops.gitRepoRoot(session, &probe_buf) != null) return error.SkipZigTest; // `/` 가 저장소인 머신
    session.git_result = .{ .status = try git_backend_mod.worker_allocator.dupe(u8, "# branch.head main\n"), .ok = true };
    git_ops.followActiveTerminalRepo(session);
    try std.testing.expect(session.git_result == null); // 여기까지는 위 테스트와 같다

    // **돌아온다.** `git_repo`가 그대로여서 `followActiveTerminalRepo`는 no-op이고, 읽기를 다시 거는 것은 tick이다.
    var back_buf: [std.fs.max_path_bytes]u8 = undefined;
    const osc = try std.fmt.bufPrint(&back_buf, "\x1b]7;file://{s}\x07", .{home_repo});
    try term.surface.core.write(osc);
    const seq_before = session.git_request_seq;
    git_ops.drainGitStatus(session);
    // seq가 올랐다 = `submitGitRead`가 그 저장소로 읽기를 걸었다(백엔드가 닫혀 있어 in-flight까지는 가지 않는다).
    try std.testing.expect(session.git_request_seq > seq_before);
    try std.testing.expectEqualStrings(home_repo, session.git_repo.?);
}

// [손 확인] "첫 파일은 열리는데 두 번째가 안 열린다". **좌표 클릭부터** 그대로 태워 재현한다 — 세션 API를 직접
// 부르는 것으로는 히트테스트·라우팅 결함이 안 잡힌다.
// SV3a·SV3b — 소스 컨트롤 목록의 스크롤 좌표가 픽셀이 되고(SV3a) 없던 스크롤바가 생겼다(SV3b).
// 탐색기(SV2)와 같은 계약이되 **브랜치 헤더 한 줄이 그 좌표 밖**이라는 점이 다르다: 헤더는 스크롤에서
// 고정이고 목록만 움직이며, 뷰포트가 헤더 아래에서 시작하므로 track도 그 아래에 놓인다. 그 한 줄을
// 어디서 빼는지가 갈리면 클릭한 행과 보이는 행이 정확히 한 줄씩 어긋난다.
//
// 두 뷰가 발행 저장소·드래그·interaction을 **공유**하므로(도크 뷰는 한 번에 하나만 보인다) 라우팅이
// 갈리면 보이지 않는 목록이 스크롤된다 — ⑨가 그 축이다.
// 도크 목록은 상태표시줄을 **침범하지 않는다.** 둘은 겹치는 층이 아니라 맞닿은 띠다 —
// `dock_layout.compute`가 창 높이에서 상태바를 **먼저** 깎고(`usable_h`) 나머지 기하가 전부 거기서
// 파생되기 때문이다. SV2a가 바닥 부분 행을 그리기 시작하면서 "목록이 상태바까지 내려온 것 아니냐"는
// 의심이 실제로 나왔고(2026-08-07 사용자 보고), 실측은 정확히 맞닿은 상태였다. 이 단언이 그 경계를
// 고정한다 — 어긋나면 목록 마지막 행이 상태바 글자와 겹쳐 보인다.
test "dock list viewport ends exactly where the status bar begins" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    file_panel_ops.activateFilePanelDockControl(session);

    // 창 높이를 여러 개로 바꿔 본다 — 한 크기에서만 맞는 것은 우연일 수 있다.
    for ([_]u32{ 700, 813, 900, 1041 }) |h| {
        _ = try session.resize(1400, h, 1000);
        const g = dock_ops.dockGeometry(session);
        if (g.tree_content.h == 0) continue;
        try std.testing.expect(session.statusBarHeightPx() > 0);
        // 목록 바닥이 상태바 시작과 같다: 겹치지도, 사이에 빈 띠를 남기지도 않는다.
        try std.testing.expectEqual(g.status_bar.y, g.tree_content.y + g.tree_content.h);
        // 그리고 상태바는 창 바닥까지다.
        try std.testing.expectEqual(h, g.status_bar.y + g.status_bar.h);
    }
}

test "소스 컨트롤 스크롤 상한은 그린 목록에서 나온다" {
    // P1b: 예전에는 여기서 셀 높이를 다시 곱했다. 그 산술이 렌더와 갈리면 목록 아래에 빈 곳이 생기거나
    // 마지막 행이 잘린다 — 이제 상한과 그린 자리가 같은 `DockMetrics`를 지난다.
    //
    // 그다음 판(이 테스트가 고정하는 것)은 **누가 세는가**이다. 상한을 별도 함수가 모델에서 다시 세던
    // 동안에는 그 값이 목록과 두 군데서 갈렸다 — 저장소 머리 줄·커밋 상자가 빠져 실제보다 짧았고,
    // 히스토리·에이전트 탭에서는 아예 다른 목록의 길이가 걸렸다. 이제 **투영이 낸 값 하나**다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    session.git_backend = try git_backend_mod.Backend.init(session.io);
    session.git_backend.?.state.?.shutting_down = true;
    dock_ops.setDockView(session, .source_control);

    var status: std.ArrayList(u8) = .empty;
    defer status.deinit(allocator);
    try status.appendSlice(allocator, "# branch.head main\n");
    for (0..80) |i| {
        var line: [64]u8 = undefined;
        try status.appendSlice(allocator, try std.fmt.bufPrint(&line, "1 .M N... 1 2 3 a b f{d}.txt\n", .{i}));
    }
    session.git_result = .{
        .status = try git_backend_mod.worker_allocator.dupe(u8, status.items),
        .ok = true,
    };
    session.scm_expanded[@intFromEnum(scm_view.Section.changes)] = true;

    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    const projection = scm_dock_ops.project(session, arena) orelse return error.MissingProjection;
    const extent = scroll_ops.scmScrollExtent(session);
    // **투영이 센 값 그대로다** — 여기서 다시 세지 않는다(두 벌이 되는 순간 그린 목록과 상한이 갈린다).
    try std.testing.expectEqual(projection.scroll.content_height_px, extent.content_h_px);
    try std.testing.expectEqual(projection.scroll.max_offset_px, extent.max_offset_px);
    // 파일 80개는 이 창에서 넘친다 — 안 넘치면 아래 단언들이 아무것도 증명하지 않는다.
    try std.testing.expect(extent.max_offset_px > 0);
    // 목록에는 파일 줄만 있는 것이 아니다(저장소 머리 줄·커밋 상자도 든다). 파일 줄만 세던 옛 상한은
    // 실제보다 짧아 목록 끝에 닿지 못했다.
    const m = chrome.components.scm_dock.types.DockMetrics.resolve(scm_dock_ops.scmDockScaleMilli(session));
    try std.testing.expect(extent.content_h_px > m.section_h + m.row_h * 80);

    // 상한을 넘겨 요청해도 그 값에서 멈춘다.
    session.scm_scroll.offset_y_px = std.math.maxInt(u32);
    scroll_ops.clampScmScroll(session);
    try std.testing.expectEqual(extent.max_offset_px, session.scm_scroll.offset_y_px);

    // **파일 줄이 사라져도 목록이 비지는 않는다** — 저장소 머리 줄과 커밋 상자는 남는다(②b). 옛 상한은
    // 파일 줄만 세어 이 경우를 "넘치지 않는다"고 말했고, 그래서 창이 짧으면 상자가 잘린 채 내려가지지
    // 않았다. 지금은 남은 줄의 높이가 그대로 상한이 된다 — 파일 80개가 빠진 만큼 줄어들 뿐이다.
    if (session.git_result) |*result| result.deinit(git_backend_mod.worker_allocator);
    session.git_result = .{ .status = try git_backend_mod.worker_allocator.dupe(u8, "# branch.head main\n"), .ok = true };
    const empty = scm_dock_ops.project(session, arena) orelse return error.MissingProjection;
    try std.testing.expectEqual(empty.scroll.max_offset_px, scroll_ops.scmScrollExtent(session).max_offset_px);
    try std.testing.expect(scroll_ops.scmScrollExtent(session).max_offset_px < extent.max_offset_px);

    // **투영이 아예 없으면 상한도 버린다.** 그리지 못한 화면에 옛 상한이 남으면 스크롤바가 서고 휠이
    // 먹는다 — 그 상한은 이미 사라진 목록의 것이다.
    if (session.git_result) |*result| result.deinit(git_backend_mod.worker_allocator);
    session.git_result = null;
    try std.testing.expect(scm_dock_ops.project(session, arena) == null);
    try std.testing.expectEqual(@as(u32, 0), scroll_ops.scmScrollExtent(session).max_offset_px);
    try std.testing.expect(!session.scm_list_overflows); // 목록이 없으면 스크롤바 자리도 없다
}

test "소스 컨트롤: published tree의 행을 눌러 diff를 연다(component 경로)" {
    // P1b: 좌표 → 행 판정을 published component tree가 소유한다. 이 테스트는 그 tree를 실제로 발행한 뒤
    // 그 안의 행 rect를 눌러, **그린 자리가 곧 눌리는 자리**임을 고정한다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    session.git_backend = try git_backend_mod.Backend.init(session.io);
    session.git_backend.?.state.?.shutting_down = true;
    try pinTermsOutsideRepo(session, allocator); // 목록은 터미널 cwd에서 나온다 — 환경이 새지 않게 고정
    const launcher = file_panel_ops.filePanelDockControlRect(session) orelse return error.MissingDockLauncher;
    session.mouse(1, @floatFromInt(launcher.x + 1), @floatFromInt(launcher.y + 1), 0, 0);
    dock_ops.setDockView(session, .source_control);

    session.git_result = .{
        .status = try git_backend_mod.worker_allocator.dupe(u8, "# branch.head main\n1 .M N... 1 2 3 a b one.txt\n1 .M N... 1 2 3 a b two.txt\n"),
        .numstat_head = try git_backend_mod.worker_allocator.dupe(u8, "1\t0\tone.txt\n2\t0\ttwo.txt\n"),
        .ok = true,
    };
    git_ops.rememberGitRepo(session, "/repo");

    // 렌더 없이 tree만 발행한다(스크린샷 하니스 없이 클릭 경로를 그대로 태우기 위해).
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();
    const projection = scm_dock_ops.project(session, arena) orelse return error.MissingProjection;
    const props = scm_dock_ops.testProps(session, projection);
    const sizes = chrome.components.scm_dock.build.bufferSizes(props.items);
    const frame = try chrome.components.scm_dock.build.build(props, .{
        .nodes = try arena.alloc(chrome.ui.tree.UiNode, sizes.nodes),
        .entries = try arena.alloc(chrome.ui.tree.RectEntry, sizes.entries),
        .layout_items = try arena.alloc(chrome.ui.layout.Item, sizes.layout_items),
        .flex_scratch = try arena.alloc(chrome.ui.layout.FlexScratch, sizes.flex_scratch),
        .child_rects = try arena.alloc(chrome.ui.layout.UiRect, sizes.child_rects),
        .actions = try arena.alloc(chrome.components.scm_dock.ids.Entry, sizes.actions),
    });
    scm_dock_ops.publishScmDockFrame(session, frame, props.items);

    const content = dock_ops.dockGeometry(session).tree_content;
    const rowCenter = struct {
        fn at(s: *AppSession, index: usize, origin_x: u32, origin_y: u32) struct { x: f64, y: f64 } {
            const entries = s.scm_dock_entries.items;
            for (entries) |entry| {
                if (entry.id != chrome.components.scm_dock.build.NodeIds.item(index)) continue;
                return .{
                    .x = @as(f64, @floatFromInt(origin_x)) + entry.rect.x + entry.rect.width / 2,
                    .y = @as(f64, @floatFromInt(origin_y)) + entry.rect.y + entry.rect.height / 2,
                };
            }
            return .{ .x = -1, .y = -1 };
        }
    }.at;

    // 0=머리 줄 · 1=커밋 입력 · 2=커밋 버튼(②b) · 3=그룹 헤더 · **4=one.txt · 5=two.txt**
    const first = rowCenter(session, 4, content.x, content.y);
    const second = rowCenter(session, 5, content.x, content.y);
    try std.testing.expect(first.y > 0 and second.y > first.y);

    // **down은 무장, up이 적용**이다 — 실제 클릭과 같은 순서로 보낸다.
    session.mouse(1, first.x, first.y, 0, 0);
    session.mouse(3, first.x, first.y, 0, 0);
    session.mouse(1, second.x, second.y, 0, 0);
    session.mouse(3, second.x, second.y, 0, 0);

    var diffs: usize = 0;
    var it = file_panel_ops.fileEntries(session);
    while (it.next()) |entry| {
        if (entry.kind == .diff) diffs += 1;
    }
    try std.testing.expectEqual(@as(usize, 2), diffs);

    // 그룹 헤더를 누르면 접힌다(열기가 아니다).
    const header = rowCenter(session, 3, content.x, content.y);
    session.mouse(1, header.x, header.y, 0, 0);
    session.mouse(3, header.x, header.y, 0, 0);
    try std.testing.expect(session.scm_collapsed[@intFromEnum(scm_view.Section.changes)]);
}

test "소스 컨트롤: 그룹 헤더는 접기와 일괄 동작이 **서로 클릭을 훔치지 않는다**" {
    // 한 행에 두 동작이 있다: 행 = 접기/펴기, 그 안의 버튼 = 그 그룹 전체 스테이지. 히트테스트가
    // 안쪽을 먼저 잡지 않으면 버튼이 영영 안 눌리고(행이 삼킨다), 반대로 행 전체가 버튼이 되면
    // 접기가 안 된다. **둘 다 각자 자리에서 자기 것만 내는지**를 published tree로 고정한다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    session.git_backend = try git_backend_mod.Backend.init(session.io);
    session.git_backend.?.state.?.shutting_down = true;
    try pinTermsOutsideRepo(session, allocator); // 목록은 터미널 cwd에서 나온다 — 환경이 새지 않게 고정
    const launcher = file_panel_ops.filePanelDockControlRect(session) orelse return error.MissingDockLauncher;
    session.mouse(1, @floatFromInt(launcher.x + 1), @floatFromInt(launcher.y + 1), 0, 0);
    dock_ops.setDockView(session, .source_control);

    session.git_result = .{
        .status = try git_backend_mod.worker_allocator.dupe(u8, "# branch.head main\n1 .M N... 1 2 3 a b one.txt\n"),
        .numstat_head = try git_backend_mod.worker_allocator.dupe(u8, "1\t0\tone.txt\n"),
        .ok = true,
    };
    git_ops.rememberGitRepo(session, "/repo");

    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();
    const projection = scm_dock_ops.project(session, arena) orelse return error.MissingProjection;
    const props = scm_dock_ops.testProps(session, projection);
    const sizes = chrome.components.scm_dock.build.bufferSizes(props.items);
    const frame = try chrome.components.scm_dock.build.build(props, .{
        .nodes = try arena.alloc(chrome.ui.tree.UiNode, sizes.nodes),
        .entries = try arena.alloc(chrome.ui.tree.RectEntry, sizes.entries),
        .layout_items = try arena.alloc(chrome.ui.layout.Item, sizes.layout_items),
        .flex_scratch = try arena.alloc(chrome.ui.layout.FlexScratch, sizes.flex_scratch),
        .child_rects = try arena.alloc(chrome.ui.layout.UiRect, sizes.child_rects),
        .actions = try arena.alloc(chrome.components.scm_dock.ids.Entry, sizes.actions),
    });
    scm_dock_ops.publishScmDockFrame(session, frame, props.items);

    const content = dock_ops.dockGeometry(session).tree_content;
    const rectOf = struct {
        fn at(s: *AppSession, id: chrome.ui.tree.UiId) ?chrome.ui.layout.UiRect {
            for (s.scm_dock_entries.items) |e| if (e.id == id) return e.rect;
            return null;
        }
    }.at;

    // 0=저장소 머리 줄 · 1=커밋 입력 · 2=커밋 버튼(②b) · **3=그룹 헤더**. 동작 버튼은 그 행의 차선이다.
    const header = rectOf(session, chrome.components.scm_dock.build.NodeIds.item(3)) orelse return error.MissingHeader;
    const bulk = rectOf(session, chrome.components.scm_dock.build.NodeIds.itemAction(3)) orelse return error.MissingBulk;

    // ① 버튼 한가운데 — **일괄 동작**이어야 한다(행이 삼키면 접힌다).
    const bx = @as(f64, @floatFromInt(content.x)) + bulk.x + bulk.width / 2;
    const by = @as(f64, @floatFromInt(content.y)) + bulk.y + bulk.height / 2;
    _ = scm_dock_ops.scmDockPointer(session, .down, bx, by);
    switch (scm_dock_ops.scmDockPointer(session, .up, bx, by) orelse return error.NoIntent) {
        .section_action => {},
        else => return error.ButtonStolenByRow,
    }

    // ② 제목 쪽(버튼 왼쪽 바깥) — **접기**여야 한다(버튼이 행을 삼키면 안 된다).
    const tx = @as(f64, @floatFromInt(content.x)) + header.x + 20;
    const ty = @as(f64, @floatFromInt(content.y)) + header.y + header.height / 2;
    _ = scm_dock_ops.scmDockPointer(session, .down, tx, ty);
    switch (scm_dock_ops.scmDockPointer(session, .up, tx, ty) orelse return error.NoIntent) {
        .toggle_section => {},
        else => return error.RowStolenByButton,
    }
}

/// 커밋 상자까지 그려진 소스 컨트롤 도크를 세운다(P3c 입력 테스트 공용). published tree가 있어야
/// 상자 rect를 찾을 수 있고, 그래야 클릭 좌표 → caret 변환이 **그린 것과 같은 기하**를 지난다.
/// 스모크 세션의 모든 Term을 **저장소 아닌 폴더**에 세운다.
///
/// 저장소 목록은 이제 터미널들의 cwd에서 나오는데(P3d §3.5.1c), 스모크 Term은 OSC 7이 없어 커널 cwd로
/// 폴백한다 — 그건 **테스트 프로세스의 cwd**, 즉 이 저장소다. 그대로 두면 테스트가 "어디서 돌았는가"에
/// 따라 목록이 하나 더 생겨 결과가 갈린다(사이드바 테스트가 같은 이유로 `/tmp`를 심는다).
fn pinTermsOutsideRepo(session: *AppSession, allocator: std.mem.Allocator) !void {
    for (session.tabs.items) |tab| {
        for (tab.panes.items) |pane| {
            for (pane.terms.items) |term| {
                term.rt.observation.cwd.clearRetainingCapacity();
                try term.rt.observation.cwd.appendSlice(allocator, "/tmp");
                term.rt.observation.availability = .current;
            }
        }
    }
}

fn openScmDockWithCommitBox(session: *AppSession, allocator: std.mem.Allocator, arena: std.mem.Allocator) !void {
    session.git_backend = try git_backend_mod.Backend.init(session.io);
    session.git_backend.?.state.?.shutting_down = true;
    try pinTermsOutsideRepo(session, allocator);
    const launcher = file_panel_ops.filePanelDockControlRect(session) orelse return error.MissingDockLauncher;
    session.mouse(1, @floatFromInt(launcher.x + 1), @floatFromInt(launcher.y + 1), 0, 0);
    dock_ops.setDockView(session, .source_control);
    session.git_result = .{
        .status = try git_backend_mod.worker_allocator.dupe(u8, "# branch.head main\n1 .M N... 1 2 3 a b one.txt\n"),
        .numstat_head = try git_backend_mod.worker_allocator.dupe(u8, "1\t0\tone.txt\n"),
        .ok = true,
    };
    git_ops.rememberGitRepo(session, "/repo");
    const projection = scm_dock_ops.project(session, arena) orelse return error.MissingProjection;
    const props = scm_dock_ops.testProps(session, projection);
    const sizes = chrome.components.scm_dock.build.bufferSizes(props.items);
    const frame = try chrome.components.scm_dock.build.build(props, .{
        .nodes = try arena.alloc(chrome.ui.tree.UiNode, sizes.nodes),
        .entries = try arena.alloc(chrome.ui.tree.RectEntry, sizes.entries),
        .layout_items = try arena.alloc(chrome.ui.layout.Item, sizes.layout_items),
        .flex_scratch = try arena.alloc(chrome.ui.layout.FlexScratch, sizes.flex_scratch),
        .child_rects = try arena.alloc(chrome.ui.layout.UiRect, sizes.child_rects),
        .actions = try arena.alloc(chrome.components.scm_dock.ids.Entry, sizes.actions),
    });
    scm_dock_ops.publishScmDockFrame(session, frame, props.items);
}

/// 커밋 상자 **바닥 여백** 안의 한 점.
/// 목록을 그 offset으로 옮기고 **같은 경로로 다시 발행한다**(투영 → build → publish). 발행된 rect는
/// 스크롤이 반영된 값이라, 스크롤 뒤의 히트 판정을 보려면 이 순서를 그대로 다시 태워야 한다.
fn republishScmDock(session: *AppSession, arena: std.mem.Allocator, offset_y_px: u32) !void {
    session.scm_scroll.offset_y_px = offset_y_px;
    const projection = scm_dock_ops.project(session, arena) orelse return error.MissingProjection;
    const props = scm_dock_ops.testProps(session, projection);
    const sizes = chrome.components.scm_dock.build.bufferSizes(props.items);
    const frame = try chrome.components.scm_dock.build.build(props, .{
        .nodes = try arena.alloc(chrome.ui.tree.UiNode, sizes.nodes),
        .entries = try arena.alloc(chrome.ui.tree.RectEntry, sizes.entries),
        .layout_items = try arena.alloc(chrome.ui.layout.Item, sizes.layout_items),
        .flex_scratch = try arena.alloc(chrome.ui.layout.FlexScratch, sizes.flex_scratch),
        .child_rects = try arena.alloc(chrome.ui.layout.UiRect, sizes.child_rects),
        .actions = try arena.alloc(chrome.components.scm_dock.ids.Entry, sizes.actions),
    });
    scm_dock_ops.publishScmDockFrame(session, frame, props.items);
}

fn commitBoxPointBottom(session: *AppSession) !struct { x: f64, y: f64 } {
    const content = dock_ops.dockGeometry(session).tree_content;
    const rect = scm_dock_ops.commitBoxRect(session) orelse return error.MissingCommitBox;
    return .{
        .x = @as(f64, @floatFromInt(content.x)) + rect.x + 12,
        .y = @as(f64, @floatFromInt(content.y)) + rect.y + rect.height - 1,
    };
}

/// 커밋 상자 rect의 한 점(도크 content 원점을 더한 창 좌표).
fn commitBoxPoint(session: *AppSession, dx: f64, dy: f64) !struct { x: f64, y: f64 } {
    const content = dock_ops.dockGeometry(session).tree_content;
    // **편집 중인 상자**를 쓴다 — 상자가 저장소마다 하나씩이라 고정 id가 없다(②b).
    const rect = scm_dock_ops.commitBoxRect(session) orelse return error.MissingCommitBox;
    return .{
        .x = @as(f64, @floatFromInt(content.x)) + rect.x + dx,
        .y = @as(f64, @floatFromInt(content.y)) + rect.y + dy,
    };
}

test "소스 컨트롤: 커서가 자리를 말한다(상자=I-beam·저장소 줄=손)" {
    // 도크 전체가 화살표였다 — 탐색기 행 판정을 그대로 썼는데 이 뷰에는 그런 행이 없어 늘 "행 아님"
    // 이었다(사용자 지적 2026-08-17). 판정은 component가 하고(published `cursor`) host는 옮기기만 한다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    try openScmDockWithCommitBox(session, allocator, arena_state.allocator());

    // 상자 위 — 여기서 마우스는 "caret을 놓는다"고 말한다.
    const inside = try commitBoxPoint(session, 12, 6);
    try std.testing.expectEqual(CursorKind.text, session.hoverCursor(inside.x, inside.y, 0));

    // 저장소 머리 줄 위 — 누를 수 있는 줄이므로 손이다(상자 **위쪽**이 그 줄이다).
    const content = dock_ops.dockGeometry(session).tree_content;
    const box = scm_dock_ops.commitBoxRect(session) orelse return error.MissingCommitBox;
    const header_y = @as(f64, @floatFromInt(content.y)) + box.y - 4;
    try std.testing.expectEqual(CursorKind.link, session.hoverCursor(inside.x, header_y, 0));
}

test "소스 컨트롤 도크가 열려 있어도 탭 바 클릭은 탭을 바꾼다" {
    // **도크 밖 클릭까지 소비하던 자리다**(사용자 보고 2026-08-17: "오른쪽 워크트리 나왔을 땐 탭 전환이
    // 안 된다"). 다운 경로의 소스 컨트롤 분기가 좌표를 안 보고 `return` 해서, 도크가 열려 있는 동안
    // 창의 **모든** primary down이 거기서 끝났다 — 에이전트 뷰는 처음부터 `dg.dock`으로 감싸 있었다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    // Term 둘(활성 = 1).
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 't' }, .modifiers = .{ .command = true } });
    try std.testing.expectEqual(@as(usize, 2), pane_ops.activePane(session).terms.items.len);
    try std.testing.expectEqual(@as(usize, 1), pane_ops.activePane(session).active_term);

    // 소스 컨트롤 도크를 연다.
    const launcher = file_panel_ops.filePanelDockControlRect(session) orelse return error.MissingDockLauncher;
    session.mouse(1, @floatFromInt(launcher.x + 1), @floatFromInt(launcher.y + 1), 0, 0);
    dock_ops.setDockView(session, .source_control);
    try std.testing.expect(dock_ops.dockVisible(session));

    // 도크 **밖**(탭 바)을 누르면 그 클릭은 탭이 받는다.
    const bar_y: f64 = @as(f64, @floatFromInt(session.titlebar_strip_px)) + 1;
    const left_tab_x: f64 = @floatFromInt(session.sidebar_width_px + 30);
    session.mouse(1, left_tab_x, bar_y, 0, 0);
    try std.testing.expectEqual(@as(usize, 0), pane_ops.activePane(session).active_term);
}

test "소스 컨트롤: 커밋 상자를 누르면 키가 그리로 간다 (P3c)" {
    // 상자를 눌렀는데 키가 터미널로 가면 사용자가 친 커밋 메시지가 셸 명령이 된다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    try openScmDockWithCommitBox(session, allocator, arena_state.allocator());

    try std.testing.expectEqual(AppSession.InputFocus.terminal, session.inputFocus());
    const p = try commitBoxPoint(session, 12, 6);
    session.mouse(1, p.x, p.y, 0, 0); // down = 무장
    session.mouse(3, p.x, p.y, 0, 0); // up = 적용(같은 규율: 실제 동작은 up 한 곳)
    try std.testing.expectEqual(AppSession.InputFocus.scm_commit, session.inputFocus());
    // **터미널이 first responder를 도로 가져가면 안 된다** — `InputFocus`에만 넣고 이 축을 빼면
    // Zig는 키를 상자로 보내는데 focus-sync가 매 tick 웹뷰/터미널로 되돌린다(Session Dock의 교훈).
    try std.testing.expect(session.terminalOwnsInput());
}

test "소스 컨트롤: 글자는 상자에 쌓이고 Enter는 줄을 바꾼다(⌘Enter는 아니다)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    try openScmDockWithCommitBox(session, allocator, arena_state.allocator());
    scm_dock_ops.focusCommitRepo(session, "/repo");

    for ("fix") |c| _ = scm_dock_ops.handleCommitKey(session, .{ .key = .{ .key = .char, .codepoint = c, .mods = .{} } });
    try std.testing.expectEqualStrings("fix", session.scm_commit_field.text.items);

    _ = scm_dock_ops.handleCommitKey(session, .{ .key = .{ .key = .enter, .mods = .{} } });
    _ = scm_dock_ops.handleCommitKey(session, .{ .key = .{ .key = .char, .codepoint = 'a', .mods = .{} } });
    try std.testing.expectEqualStrings("fix\na", session.scm_commit_field.text.items);

    // ⌘Enter는 **커밋**이라 줄을 바꾸지 않는다(§12.2). 실행 배선은 P3c-2이고, 여기서는 글자가 안
    // 늘어난다는 사실만 고정한다 — 그게 깨지면 커밋하려던 사용자가 빈 줄을 하나 얻는다.
    _ = scm_dock_ops.handleCommitKey(session, .{ .key = .{ .key = .enter, .mods = .{ .command = true } } });
    try std.testing.expectEqualStrings("fix\na", session.scm_commit_field.text.items);
}

test "소스 컨트롤: 앱 단축키는 상자가 삼키지 않는다(편집도 취소하지 않는다)" {
    // 편집기가 모든 조합을 먹으면 사용자는 상자를 벗어나야만 앱을 쓸 수 있다. 반대로 주소창처럼
    // 편집을 **취소**하면 여기서는 URL 한 줄이 아니라 쓴 커밋 메시지가 사라진다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    try openScmDockWithCommitBox(session, allocator, arena_state.allocator());
    scm_dock_ops.focusCommitRepo(session, "/repo");
    for ("wip") |c| _ = scm_dock_ops.handleCommitKey(session, .{ .key = .{ .key = .char, .codepoint = c, .mods = .{} } });

    const consumed = scm_dock_ops.handleCommitKey(session, .{ .key = .{ .key = .char, .codepoint = 's', .mods = .{ .command = true } } });
    try std.testing.expect(!consumed); // ⌘S는 아래 keybinding 경로로 흘러야 한다
    try std.testing.expectEqualStrings("wip", session.scm_commit_field.text.items); // 글자는 그대로다
}

