test "소스 컨트롤: 커밋 상자 caret도 깜빡임 게이트에 든다" {
    // 게이트를 빠뜨리면 위상은 도는데 dirty가 안 서 재투영이 없어 **안 깜빡이고**, `cursor.blink=false`
    // 에서는 early-return 때문에 아예 굳는다 — 도크 검색 caret이 정확히 그렇게 새 있었다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    try openScmDockWithCommitBox(session, allocator, arena_state.allocator());
    scm_dock_ops.focusCommitRepo(session, "/repo");

    // 반주기가 **정확히 한 번** 지난 상태를 만든다(경과를 어림하면 소비한 반주기 수의 홀짝이
    // 달라져 위상 뒤집힘이 그때그때 갈린다 — 첫 판이 그래서 흔들렸다).
    session.appearance.cursor.blink_interval_ms = 10;
    const interval_ns: i128 = 10 * std.time.ns_per_ms;
    const now_ns = std.Io.Clock.awake.now(session.io).nanoseconds;

    // ① 상자가 입력을 가진 동안에는 위상이 돌고 **재투영을 요구한다**.
    session.blink_phase_ns = now_ns - interval_ns;
    session.metal_dirty = false;
    const before = session.blink_visible;
    // 커서·텍스트 blink가 전부 꺼진 **중립 스냅샷**을 준다 — 그래야 위상이 도는 유일한 근거가
    // 커밋 상자 게이트임이 분명해진다(터미널 커서가 깜빡여서 통과하는 것이 아니다).
    session.updateCursorBlink(.{});
    try std.testing.expect(session.blink_visible != before); // 위상이 뒤집혔다
    try std.testing.expect(session.metal_dirty); // 그리고 다시 그려야 한다고 말한다

    // ② 상자가 놓으면 그 근거도 사라진다 — 깜빡일 것이 없으면 **보이는 위상으로 고정**하고(그 함수의
    // 조기 반환이 `resetCursorBlink`를 부른다) 재투영을 요구하지 않는다.
    scm_dock_ops.blurCommit(session);
    session.blink_phase_ns = std.Io.Clock.awake.now(session.io).nanoseconds - interval_ns;
    session.metal_dirty = false;
    session.updateCursorBlink(.{});
    try std.testing.expect(session.blink_visible); // 고정된 위상은 "보임"이다
    try std.testing.expect(!session.metal_dirty); // 깜빡일 것이 없으니 다시 그릴 이유도 없다

    // props가 그 위상을 그대로 싣는다(component가 시간을 모르므로).
    scm_dock_ops.focusCommitRepo(session, "/repo");
    const projection = scm_dock_ops.project(session, arena_state.allocator()) orelse return error.MissingProjection;
    const props = scm_dock_ops.testProps(session, projection);
    try std.testing.expectEqual(session.blink_visible, props.commit_edit.caret_visible);
}

test "히스토리 탭: 커밋 원문이 행이 되고 상대 시각은 **우리가** 만든다 (P4)" {
    // 기대값이 보간 결과(상대 시각)라 키 비교가 동어반복이 된다 — 언어를 고정한다.
    const lang_before = maru.i18n.lang();
    defer maru.i18n.setLang(lang_before);
    // `%ar`를 쓰지 않는 이유가 여기 있다 — git의 로케일·문구를 타면 같은 화면의 다른 상대시각 표기와
    // 규칙이 갈린다. 시각이 0이면 자리를 비운다(1970년으로 그리지 않는다).
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    maru.i18n.setLang(.ko);
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();
    try openScmDockWithCommitBox(session, allocator, arena);

    const now_s: i64 = @intCast(@divFloor(std.Io.Clock.real.now(session.io).nanoseconds, std.time.ns_per_s));
    var text_buf: [512]u8 = undefined;
    const text = try std.fmt.bufPrint(&text_buf, "abcdef1234567\x1fparent0\x1f홍길동\x1f{d}\x1fHEAD -> main\x1f첫 커밋\x1e" ++
        "9876543210abc\x1f\x1fJane\x1f0\x1f\x1f시각 없는 커밋\x1e", .{now_s - 7200});
    session.scm_log_text = try allocator.dupe(u8, text);
    session.scm_log_repo = try allocator.dupe(u8, "/repo");
    scm_dock_ops.selectScmTab(session, .history);

    const projection = scm_dock_ops.project(session, arena) orelse return error.MissingProjection;
    try std.testing.expectEqual(@as(usize, 2), projection.items.len);
    const first = projection.items[0].commit;
    try std.testing.expectEqualStrings("첫 커밋", first.subject);
    try std.testing.expectEqualStrings("홍길동", first.author);
    try std.testing.expectEqualStrings("abcdef1", first.short_oid); // 7자 고정
    try std.testing.expectEqualStrings("2시간 전", first.when);
    try std.testing.expectEqualStrings("main", first.ref);
    try std.testing.expect(first.ref_is_head); // `HEAD -> main`은 칩 하나다
    // 시각을 못 읽은 커밋은 **자리를 비운다**.
    try std.testing.expectEqualStrings("", projection.items[1].commit.when);
}

test "히스토리: ref가 여럿이면 그리지 않은 나머지를 센다(`+N`의 N)" {
    // §3.5.3은 "칩이 많으면 `+N`으로 접는다"고 정했는데, 그전까지는 첫 칩만 그리고 나머지를 **조용히
    // 버렸다** — 화면은 그 커밋에 태그가 하나뿐이라고 말하고 있었다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();
    try openScmDockWithCommitBox(session, allocator, arena);

    // 실측 `%D` 형식: `HEAD -> main, origin/main, tag: v1.2.0`. **`HEAD -> main`은 칩 하나**다.
    session.scm_log_text = try allocator.dupe(u8, "aaaaaaa1111\x1fp\x1fA\x1f1\x1fHEAD -> main, origin/main, tag: v1.2.0\x1f셋\x1e" ++
        "bbbbbbb2222\x1fp\x1fA\x1f1\x1fmain\x1f하나\x1e" ++
        "ccccccc3333\x1fp\x1fA\x1f1\x1f\x1f없음\x1e");
    session.scm_log_repo = try allocator.dupe(u8, "/repo");
    scm_dock_ops.selectScmTab(session, .history);

    const projection = scm_dock_ops.project(session, arena) orelse return error.MissingProjection;
    try std.testing.expectEqual(@as(usize, 3), projection.items.len);
    // 셋 중 첫 칩만 그리므로 나머지는 둘이다.
    try std.testing.expectEqualStrings("main", projection.items[0].commit.ref);
    try std.testing.expect(projection.items[0].commit.ref_is_head);
    try std.testing.expectEqual(@as(u32, 2), projection.items[0].commit.ref_more);
    // 하나뿐이면 접을 것이 없다(`+0`은 아무 말도 하지 않는다).
    try std.testing.expectEqual(@as(u32, 0), projection.items[1].commit.ref_more);
    // ref가 없으면 칩도 접힘도 없다.
    try std.testing.expectEqualStrings("", projection.items[2].commit.ref);
    try std.testing.expectEqual(@as(u32, 0), projection.items[2].commit.ref_more);
}

test "히스토리 탭에서는 커밋 상자가 키를 먹지 않는다 (P4 적대적 검증)" {
    // 그 탭에는 상자가 **그려지지 않는다**. 플래그만 보면 키가 계속 그 상자로 가고, 사용자는 자기가
    // 친 글자가 어디로 갔는지 알 수 없다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    try openScmDockWithCommitBox(session, allocator, arena_state.allocator());

    scm_dock_ops.focusCommitRepo(session, "/repo");
    try std.testing.expect(session.scmCommitOwnsInput()); // 변경 사항 탭에서는 먹는다
    scm_dock_ops.selectScmTab(session, .history);
    try std.testing.expect(!session.scmCommitOwnsInput());
    // 그리고 쓰던 글은 **살아 있다** — 탭을 옮긴 것이 글을 버리는 동작은 아니다.
    scm_dock_ops.selectScmTab(session, .changes);
    try std.testing.expect(session.scmCommitOwnsInput());
}

/// 테스트에서 **활성 세션의 링**을 얻는다(AT0 — 링의 키가 provider 세션 신원이다).
///
/// 예전에는 `session.turn_ring` 하나였지만 이제 키가 필요하다. 캡처 하니스와 같은 이유로 활성 Term 에
/// 데모 신원을 붙이고 그 키로 링을 만든다 — 신원이 없으면 링도 없다는 계약(§6.1)이 테스트에도 그대로 산다.
const test_turn_session = "test-turn-session";

fn testTurnRing(session: *AppSession) *maru.session.turn_snapshot.Ring {
    if (session.surface_initialized) {
        const active_id = term_ops.activeSurface(session).id;
        outer: for (session.tabs.items) |tab| {
            for (tab.panes.items) |pane| {
                for (pane.terms.items) |term| {
                    if (term.surface.id != active_id) continue;
                    term.agent_transcript.setIdentity(test_turn_session);
                    break :outer;
                }
            }
        }
    }
    return session.turn_rings.ringFor(test_turn_session, "") orelse unreachable;
}

/// 통합 테스트가 «캡처가 링에 들어왔나» 를 볼 때 쓴다. **신원을 심지 않는다** — 제품 경로가 붙인
/// 신원으로 찾으므로, 신원이 없으면 null 이고 그 자체가 계약(§6.1)의 관측이다.
fn turnRingForTest(session: *AppSession) ?*const maru.session.turn_snapshot.Ring {
    if (!session.surface_initialized) return null;
    const identity = git_ops.sessionIdentityFor(session, term_ops.activeSurface(session).id);
    if (identity.len == 0) return null;
    return session.turn_rings.find(identity);
}

fn turnRingLenForTest(session: *AppSession) usize {
    const ring = turnRingForTest(session) orelse return 0;
    return ring.len;
}

/// 그 surface 에 테스트용 세션 신원을 심는다. **링의 키가 신원**이므로(AT0), 신원 없이 캡처를 부르면
/// 제품이 «관측 모드» 로 보고 아무것도 찍지 않는다 — 그 자체가 계약(§6.1)이고 아래 전용 테스트가 본다.
fn seedTurnIdentity(session: *AppSession, surface_id: u64) void {
    for (session.tabs.items) |tab| {
        for (tab.panes.items) |pane| {
            for (pane.terms.items) |term| {
                if (term.surface.id == surface_id) term.agent_transcript.setIdentity(test_turn_session);
            }
        }
    }
}

/// 심어 둔 키로 링을 **직접** 본다. 활성 Term 이 diff·파일 Term 인 테스트에서는 «활성 세션» 조회가
/// 성립하지 않기 때문이다(그 Term 에는 에이전트가 없다).
fn seededTurnRing(session: *AppSession) ?*const maru.session.turn_snapshot.Ring {
    return session.turn_rings.find(test_turn_session);
}

fn seededTurnRingLen(session: *AppSession) usize {
    const ring = seededTurnRing(session) orelse return 0;
    return ring.len;
}

test "에이전트 탭: 턴 타임라인이 서고 진행 중이 맨 위다 (P5)" {
    // 지금 결함(§2)을 구조로 고친다: 턴 K를 **스냅샷 두 개 사이**로 잡으면 작업트리가 어떻게 바뀌든
    // 그 항목이 고정된다. 진행 중만 오른쪽이 작업트리다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();
    try openScmDockWithCommitBox(session, allocator, arena);
    scm_dock_ops.selectScmTab(session, .agent);

    // 링이 비면 **오류가 아니라** "이번 실행에서 관측한 턴이 없다"이다.
    {
        const projection = scm_dock_ops.project(session, arena) orelse return error.MissingProjection;
        try std.testing.expectEqualStrings(maru.i18n.t(.scm_no_turns), projection.items[0].notice);
    }

    const now_s: i64 = @intCast(@divFloor(std.Io.Clock.real.now(session.io).nanoseconds, std.time.ns_per_s));
    testTurnRing(session).push(.{ .tree = "aaaaaaa1111", .surface_id = 1, .captured_s = now_s - 7200, .agent_kind = 1 }); // claude
    testTurnRing(session).push(.{ .tree = "bbbbbbb2222", .surface_id = 1, .captured_s = now_s - 10, .agent_kind = 2 }); // codex — 방금 끝난 턴이라 오늘 시각이다

    const projection = scm_dock_ops.project(session, arena) orelse return error.MissingProjection;
    try std.testing.expectEqual(@as(usize, 2), projection.items.len); // 진행 중 + 턴 하나
    const live = projection.items[0].turn;
    try std.testing.expectEqualStrings(maru.i18n.t(.scm_turn_live), live.title);
    try std.testing.expect(live.live);
    try std.testing.expectEqualStrings("", live.when); // 아직 끝나지 않았다
    const last = projection.items[1].turn;
    try std.testing.expectEqualStrings(maru.i18n.t(.scm_turn_last), last.title);
    try std.testing.expect(!last.live);
    try std.testing.expectEqualStrings("codex", last.agent); // "누가"는 오른쪽 스냅샷이 든다
    // **턴은 절대 시각이다**(상대 표기는 커밋 히스토리 탭이 계속 쓴다 — `relativeTime`). 방금 끝난
    // 턴이라 오늘이고, 그래서 `HH:MM` 다섯 자다. 실행 시각에 따라 값이 달라지므로 **모양**을 본다.
    try std.testing.expectEqual(@as(usize, 5), last.when.len);
    try std.testing.expectEqual(@as(u8, ':'), last.when[2]);
    // 세션이 하나면 에이전트 자리에 번호가 붙지 않는다(구분할 것이 없다).
}

test "에이전트 탭: 밀려난 세션은 «관측한 턴이 없다» 가 아니라 «밀려났다» 고 말한다" {
    // 맵 상한을 넘겨 버려진 세션에 「이번 실행에서 관측한 턴이 없다」고 하면, **있었던 기록을 없었던
    // 것처럼** 만든다(적대적 검증 5회차). `/clear` 가 새 신원을 발급하므로 흔한 상태다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();
    try openScmDockWithCommitBox(session, allocator, arena);
    scm_dock_ops.selectScmTab(session, .agent);
    testTurnRing(session).push(.{ .tree = "aaaaaaa1111", .surface_id = 1, .captured_s = 100, .agent_kind = 1 }); // 활성 Term 에 신원을 심고 턴 하나

    // 다른 세션 신원으로 맵을 채워 활성 세션을 밀어낸다.
    var i: usize = 0;
    while (i < maru.session.turn_snapshot.max_sessions) : (i += 1) {
        var buf: [16]u8 = undefined;
        _ = session.turn_rings.ringFor(std.fmt.bufPrint(&buf, "other-{d}", .{i}) catch unreachable, "").?;
    }
    try std.testing.expect(session.turn_rings.find(test_turn_session) == null);

    {
        const projection = scm_dock_ops.project(session, arena) orelse return error.MissingProjection;
        try std.testing.expectEqualStrings(maru.i18n.t(.scm_turns_evicted), projection.items[0].notice);
    }

    // **돌아온 뒤에도 말한다.** 새 턴이 목록을 채우면 그 몇 개가 전부인 것처럼 보이기 때문이다
    // (`Ring.history_evicted` — `missed` 와 같은 규율).
    testTurnRing(session).push(.{ .tree = "bbbbbbb2222", .surface_id = 1, .captured_s = 200, .agent_kind = 1 });
    {
        const projection = scm_dock_ops.project(session, arena) orelse return error.MissingProjection;
        try std.testing.expectEqualStrings(maru.i18n.t(.scm_turns_evicted), projection.items[0].notice);
        try std.testing.expect(projection.items.len > 1); // 고지가 목록을 **대신하지 않는다**
        try std.testing.expectEqualStrings(maru.i18n.t(.scm_turn_live), projection.items[1].turn.title);
    }
}

test "에이전트 탭: 턴을 펼치면 그 턴이 바꾼 파일이 아래에 온다 (P5)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();
    try openScmDockWithCommitBox(session, allocator, arena);
    scm_dock_ops.selectScmTab(session, .agent);
    testTurnRing(session).push(.{ .tree = "aaaaaaa1111", .surface_id = 1, .captured_s = 100, .agent_kind = 1 });
    testTurnRing(session).push(.{ .tree = "bbbbbbb2222", .surface_id = 1, .captured_s = 200, .agent_kind = 1 });

    // 완료된 턴(자리 1)을 펼친다.
    scm_dock_ops.applyScmDockIntent(session, .{ .select_turn = 1 });
    // **자리가 아니라 두 tree 키**를 든다 — 새 턴이 들어오면 자리가 밀린다.
    try std.testing.expectEqualStrings("aaaaaaa1111 bbbbbbb2222", session.scm_expanded_turn.?);
    session.scm_commit_files_oid = try allocator.dupe(u8, "aaaaaaa1111 bbbbbbb2222");
    session.scm_commit_files_text = try allocator.dupe(u8, "M\tsrc/a.zig\n");
    {
        const projection = scm_dock_ops.project(session, arena) orelse return error.MissingProjection;
        try std.testing.expectEqualStrings("a.zig", projection.items[2].commit_file.name);
    }

    // 같은 줄을 다시 누르면 접힌다.
    scm_dock_ops.applyScmDockIntent(session, .{ .select_turn = 1 });
    try std.testing.expect(session.scm_expanded_turn == null);
}

test "에이전트 탭: 새 턴이 들어와도 펼친 줄이 바뀌지 않는다 (P5 적대적 검증)" {
    // 자리로 들면 새 턴이 push될 때마다 아래로 밀려 **같은 번호가 다른 턴**을 가리킨다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();
    try openScmDockWithCommitBox(session, allocator, arena);
    scm_dock_ops.selectScmTab(session, .agent);
    testTurnRing(session).push(.{ .tree = "aaaaaaa1111", .surface_id = 1, .captured_s = 100, .agent_kind = 1 });
    testTurnRing(session).push(.{ .tree = "bbbbbbb2222", .surface_id = 1, .captured_s = 200, .agent_kind = 1 });
    scm_dock_ops.applyScmDockIntent(session, .{ .select_turn = 1 }); // 마지막 턴

    // 새 턴이 들어온다 — 그 줄은 이제 자리 2다.
    testTurnRing(session).push(.{ .tree = "ccccccc3333", .surface_id = 1, .captured_s = 300, .agent_kind = 2 });
    const projection = scm_dock_ops.project(session, arena) orelse return error.MissingProjection;
    var expanded_count: usize = 0;
    for (projection.items) |item| switch (item) {
        .turn => |turn| if (turn.expanded) {
            expanded_count += 1;
            // 펼친 것은 여전히 **그 턴**이다(제목이 한 칸 밀렸다).
            var title_buf: [32]u8 = undefined;
            const want = try std.fmt.bufPrint(&title_buf, "2{s}", .{maru.i18n.t(.scm_turn_back_suffix)});
            try std.testing.expectEqualStrings(want, turn.title);
        },
        else => {},
    };
    try std.testing.expectEqual(@as(usize, 1), expanded_count);
}

test "히스토리: 새 커밋이 생겨도 강조가 옮겨 가지 않는다 (적대적 검증)" {
    // 자리로 들면 목록이 한 칸 밀릴 때 **같은 번호가 다른 커밋**을 가리킨다 — 강조가 조용히 옮겨 간다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();
    try openScmDockWithCommitBox(session, allocator, arena);
    scm_dock_ops.selectScmTab(session, .history);

    session.scm_log_repo = try allocator.dupe(u8, "/repo");
    session.scm_log_text = try allocator.dupe(u8, "aaaaaaa1111\x1fp\x1fA\x1f1\x1f\x1f첫째\x1e");
    scm_dock_ops.applyScmDockIntent(session, .{ .select_commit = 0 });

    // 새 커밋이 목록 맨 위에 들어온다 — 앞서 고른 커밋은 이제 자리 1이다.
    allocator.free(session.scm_log_text);
    session.scm_log_text = try allocator.dupe(u8, "bbbbbbb2222\x1fp\x1fA\x1f2\x1f\x1f새것\x1eaaaaaaa1111\x1fp\x1fA\x1f1\x1f\x1f첫째\x1e");
    const projection = scm_dock_ops.project(session, arena) orelse return error.MissingProjection;
    var selected_subject: []const u8 = "";
    for (projection.items) |item| switch (item) {
        .commit => |commit| if (commit.selected) {
            selected_subject = commit.subject;
        },
        else => {},
    };
    // 고른 것은 여전히 **그 커밋**이다(자리는 밀렸다).
    try std.testing.expectEqualStrings("첫째", selected_subject);
}

test "펼친 항목의 파일만 그린다 — 탭을 오가도 남의 파일이 서지 않는다 (P5 적대적 검증)" {
    // 읽기 슬롯을 두 탭이 공유한다. 키를 확인하지 않으면 앞서 펼친 커밋의 파일이 **턴 아래**에 그려진다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();
    try openScmDockWithCommitBox(session, allocator, arena);
    testTurnRing(session).push(.{ .tree = "aaaaaaa1111", .surface_id = 1, .captured_s = 100, .agent_kind = 1 });
    testTurnRing(session).push(.{ .tree = "bbbbbbb2222", .surface_id = 1, .captured_s = 200, .agent_kind = 1 });

    // 턴을 펼쳐 두고,
    scm_dock_ops.selectScmTab(session, .agent);
    scm_dock_ops.applyScmDockIntent(session, .{ .select_turn = 1 });
    // **커밋 쪽 파일**이 실려 있다고 하자(앞서 히스토리에서 펼쳤던 것).
    session.scm_commit_files_oid = try allocator.dupe(u8, "abcdef1234567");
    session.scm_commit_files_text = try allocator.dupe(u8, "M\t남의파일.zig\n");

    const projection = scm_dock_ops.project(session, arena) orelse return error.MissingProjection;
    for (projection.items) |item| switch (item) {
        .commit_file => return error.ForeignFilesDrawn, // 그 목록은 이 턴의 것이 아니다
        else => {},
    };
    // 대신 "읽는 중"이라고 말한다(그 턴의 답은 아직 없다).
    try std.testing.expectEqualStrings(maru.i18n.t(.scm_loading), projection.items[2].notice);
}

// [AT4 §5] **고지가 투영에 실제로 들어가는지**를 잰다. `shellNoticeFor` 만 보는 테스트는 그 줄이 항목
// 예산에서 잘려도 통과한다 — 그리고 파일이 많은 턴이야말로 그 고지가 필요한 자리다.
test "셸 고지가 펼친 턴의 파일 줄 뒤에 실제로 실린다 (AT4)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();
    try openScmDockWithCommitBox(session, allocator, arena);

    // 셸을 쓴 턴을 봉인해 링에 싣는다.
    const gpa = session.allocator;
    session.turn_captures.noteShellCall(test_turn_session);
    session.turn_captures.noteShellCall(test_turn_session);
    const cap = session.turn_captures.seal(gpa, test_turn_session);
    try std.testing.expect(cap != 0);

    testTurnRing(session).push(.{ .tree = "aaaaaaa1111", .surface_id = 1, .captured_s = 100, .agent_kind = 1 });
    testTurnRing(session).push(.{ .tree = "bbbbbbb2222", .surface_id = 1, .captured_s = 200, .agent_kind = 1, .capture_id = cap });

    scm_dock_ops.selectScmTab(session, .agent);
    // `select_turn` 이 그 줄을 고르고 **펼치기까지** 한다(`toggleTurnExpanded`).
    scm_dock_ops.applyScmDockIntent(session, .{ .select_turn = 1 });
    try std.testing.expect(session.scm_expanded_turn != null);
    // 그 턴의 파일 목록이 실려 있다고 하자.
    session.scm_commit_files_oid = try allocator.dupe(u8, "aaaaaaa1111 bbbbbbb2222");
    session.scm_commit_files_text = try allocator.dupe(u8, "M\tsrc/a.zig\nM\tsrc/b.zig\n");

    const projection = scm_dock_ops.project(session, arena) orelse return error.MissingProjection;
    var files: usize = 0;
    var notice_after_files = false;
    for (projection.items) |item| switch (item) {
        .commit_file => files += 1,
        .notice => |text| {
            // **파일 뒤에** 와야 한다 — 앞에 오면 그 줄들이 왜 `·` 인지를 설명하기 전에 말하는 것이다.
            if (std.mem.indexOfScalar(u8, text, '2') != null and files == 2) notice_after_files = true;
        },
        else => {},
    };
    try std.testing.expectEqual(@as(usize, 2), files);
    try std.testing.expect(notice_after_files);
}

test "커밋을 펼치면 턴 펼침이 접힌다(슬롯이 하나다) (P5 적대적 검증)" {
