test "에이전트 탭: 진행 중인 턴은 tree 둘로 읽지 않는다 (P5)" {
    // 오른쪽이 작업트리라 tree 비교가 성립하지 않는다 — 그 줄의 파일은 변경 사항 탭이 이미 보여 준다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    try openScmDockWithCommitBox(session, allocator, arena_state.allocator());
    scm_dock_ops.selectScmTab(session, .agent);
    testTurnRing(session).push(.{ .tree = "aaaaaaa1111", .surface_id = 1, .captured_s = 100, .agent_kind = 1 });

    // **진행 중 줄은 변경 사항 탭으로 보낸다** — tree 둘로 읽을 수 없어 펼칠 것이 없는데, 아무 일도
    // 안 하면 죽은 컨트롤이 된다. 그 줄이 가리키는 목록은 실제로 그 탭이 보여 준다.
    scm_dock_ops.applyScmDockIntent(session, .{ .select_turn = 0 });
    try std.testing.expectEqual(chrome.components.scm_dock.types.Tab.changes, session.scm_tab);
    try std.testing.expect(session.scm_expanded_turn == null);
    // 읽기도 걸지 않는다(키를 만들 수 없다).
    scm_dock_ops.pumpCommitFiles(session);
    try std.testing.expectEqual(@as(u64, 0), session.scm_commit_files_inflight);
}

test "히스토리 탭: 커밋을 펼치면 그 커밋이 바꾼 파일이 아래에 온다 (P4b)" {
    // 고르기와 펼치기는 **같은 클릭**이다 — 커밋을 눌렀을 때 사용자가 보려는 것은 "무엇을 바꿨나"이고,
    // 그것을 따로 여는 두 번째 컨트롤을 만들 이유가 없다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();
    try openScmDockWithCommitBox(session, allocator, arena);
    scm_dock_ops.selectScmTab(session, .history);

    session.scm_log_repo = try allocator.dupe(u8, "/repo");
    session.scm_log_text = try allocator.dupe(u8, "abcdef1234567\x1fp\x1fA\x1f1\x1f\x1f제목\x1e");
    scm_dock_ops.applyScmDockIntent(session, .{ .select_commit = 0 });
    try std.testing.expect(session.scm_expanded_commit != null);
    try std.testing.expectEqualStrings("abcdef1234567", session.scm_expanded_commit.?);

    // 아직 못 읽었으면 **그 사실**을 한 줄로 말한다(빈 자리는 "바꾼 것이 없다"로 읽힌다).
    {
        const projection = scm_dock_ops.project(session, arena) orelse return error.MissingProjection;
        try std.testing.expectEqualStrings(maru.i18n.t(.scm_loading), projection.items[1].notice);
    }

    session.scm_commit_files_oid = try allocator.dupe(u8, "abcdef1234567");
    session.scm_commit_files_text = try allocator.dupe(u8, "M\tsrc/main.zig\nA\tnew.txt\n");
    {
        const projection = scm_dock_ops.project(session, arena) orelse return error.MissingProjection;
        try std.testing.expectEqualStrings("main.zig", projection.items[1].commit_file.name);
        try std.testing.expectEqualStrings("src/", projection.items[1].commit_file.dir);
        try std.testing.expectEqual(@as(u8, 'M'), projection.items[1].commit_file.letter);
        try std.testing.expectEqualStrings("new.txt", projection.items[2].commit_file.name);
        // 상태 색은 목록 파일 행과 **같은 표**를 쓴다.
        try std.testing.expectEqual(
            chrome.components.scm_dock.types.StatusKind.added,
            projection.items[2].commit_file.status,
        );
    }

    // 같은 커밋을 다시 누르면 접힌다 — 자리를 돌려받는 길이 그 줄 자신이어야 한다.
    scm_dock_ops.applyScmDockIntent(session, .{ .select_commit = 0 });
    try std.testing.expect(session.scm_expanded_commit == null);
}

test "소스 컨트롤 도크는 **backing 스케일**로 그린다(Retina에서 절반이 되지 않게)" {
    // 사용자 보고 2026-08-18: Retina에서 이 도크만 글자가 뭉개지고 줄이 얇았다. 원인은 스케일 함수를
    // 잘못 고른 것 — `DockMetrics`가 받는 값은 **backing × zoom**인데 zoom만 줬다(1x 화면에서는 두
    // 값이 같아 캡처로도 안 잡혔다). 에이전트 도크는 처음부터 같은 값을 쓰고 있었다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    session.scale_milli = 2000; // Retina
    try std.testing.expectEqual(
        agent_dock.agentSessionDockScaleMilli(session),
        scm_dock_ops.scmDockScaleMilli(session),
    );
    // 그 값이 실제로 치수를 두 배로 만든다(1x와 같은 수가 나오면 그게 이 결함이다).
    const retina = chrome.components.scm_dock.types.DockMetrics.resolve(scm_dock_ops.scmDockScaleMilli(session));
    session.scale_milli = 1000;
    const plain = chrome.components.scm_dock.types.DockMetrics.resolve(scm_dock_ops.scmDockScaleMilli(session));
    try std.testing.expect(retina.row_h > plain.row_h);
}

test "히스토리: 출력이 잘리면 그 사실을 적는다 (P4b 적대적 검증)" {
    // "더 없다"와 "더 못 읽었다"는 다른 사실이다 — 조용히 자르면 사용자는 앞의 것으로 읽는다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();
    try openScmDockWithCommitBox(session, allocator, arena);
    scm_dock_ops.selectScmTab(session, .history);

    session.scm_log_repo = try allocator.dupe(u8, "/repo");
    session.scm_log_text = try allocator.dupe(u8, "abcdef1234567\x1fp\x1fA\x1f1\x1f\x1f제목\x1e");
    session.scm_log_truncated = true;
    {
        const projection = scm_dock_ops.project(session, arena) orelse return error.MissingProjection;
        var saw = false;
        for (projection.items) |item| switch (item) {
            .notice => |text| if (std.mem.eql(u8, text, maru.i18n.t(.scm_list_truncated))) {
                saw = true;
            },
            else => {},
        };
        try std.testing.expect(saw);
    }

    // 커밋 파일 목록도 같은 규율이다.
    scm_dock_ops.applyScmDockIntent(session, .{ .select_commit = 0 });
    session.scm_commit_files_oid = try allocator.dupe(u8, "abcdef1234567");
    session.scm_commit_files_text = try allocator.dupe(u8, "M\ta.txt\n");
    session.scm_commit_files_truncated = true;
    {
        const projection = scm_dock_ops.project(session, arena) orelse return error.MissingProjection;
        var saw_files = false;
        for (projection.items) |item| switch (item) {
            .notice => |text| if (std.mem.eql(u8, text, maru.i18n.t(.scm_commit_files_truncated))) {
                saw_files = true;
            },
            else => {},
        };
        try std.testing.expect(saw_files);
    }
}

test "히스토리: 다른 커밋의 같은 파일은 **다른 탭**이다 (P4b 적대적 검증)" {
    // 유일성 키가 `(경로, kind, base)`뿐이면 방금 누른 커밋을 눌렀는데 앞서 본 커밋의 내용이 보인다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    const repo = "/repo";
    const abs = "/repo/src/main.zig";
    git_ops.openCommitDiffTerm(session, repo, abs, "src/main.zig", null, "aaaaaaa1111");
    git_ops.openCommitDiffTerm(session, repo, abs, "src/main.zig", null, "bbbbbbb2222");
    var commit_terms: usize = 0;
    var saw_a = false;
    var saw_b = false;
    for (session.tabs.items) |tab| for (tab.panes.items) |pane| for (pane.terms.items) |term| {
        const entry = term.file_entry orelse continue;
        if (entry.kind != .diff or entry.diff_base != .commit) continue;
        commit_terms += 1;
        if (std.mem.eql(u8, entry.diff_commit_oid, "aaaaaaa1111")) saw_a = true;
        if (std.mem.eql(u8, entry.diff_commit_oid, "bbbbbbb2222")) saw_b = true;
    };
    try std.testing.expectEqual(@as(usize, 2), commit_terms);
    try std.testing.expect(saw_a and saw_b);

    // 같은 커밋을 다시 열면 **그 탭을 다시 쓴다**(같은 것이 두 자리에 있으면 안 된다).
    git_ops.openCommitDiffTerm(session, repo, abs, "src/main.zig", null, "aaaaaaa1111");
    var again: usize = 0;
    for (session.tabs.items) |tab| for (tab.panes.items) |pane| for (pane.terms.items) |term| {
        const entry = term.file_entry orelse continue;
        if (entry.kind == .diff and entry.diff_base == .commit) again += 1;
    };
    try std.testing.expectEqual(@as(usize, 2), again);
}

