test "히스토리 탭: 커밋이 없는 것과 못 읽은 것을 구별한다 (P4)" {
    // 기대값이 보간 결과(상대 시각)라 키 비교가 동어반복이 된다 — 언어를 고정한다.
    const lang_before = maru.i18n.lang();
    defer maru.i18n.setLang(lang_before);
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    maru.i18n.setLang(.ko);
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();
    try openScmDockWithCommitBox(session, allocator, arena);
    scm_dock_ops.selectScmTab(session, .history);

    // ① 아직 못 읽었다.
    {
        const projection = scm_dock_ops.project(session, arena) orelse return error.MissingProjection;
        try std.testing.expectEqualStrings(maru.i18n.t(.scm_loading), projection.items[0].notice);
    }
    // ② 읽었는데 커밋이 없다(첫 커밋 전 저장소).
    session.scm_log_repo = try allocator.dupe(u8, "/repo");
    {
        const projection = scm_dock_ops.project(session, arena) orelse return error.MissingProjection;
        try std.testing.expectEqualStrings(maru.i18n.t(.scm_no_commits), projection.items[0].notice);
    }
    // ③ 읽기가 실패했다 — 위 둘과 **다른 사실**이다.
    session.scm_log_failed = true;
    {
        const projection = scm_dock_ops.project(session, arena) orelse return error.MissingProjection;
        try std.testing.expectEqualStrings(maru.i18n.t(.scm_log_read_failed), projection.items[0].notice);
    }
}

test "소스 컨트롤: 목록의 뿌리는 **활성 터미널 하나**다 (사용자 결정 2026-08-17)" {
    // 열린 터미널을 전부 세면 탭을 여럿 띄운 사용자에게 여덟 줄이 서고, 그중 무엇이 지금 보고 있는
    // 것인지가 사라진다(사용자 화면 제시). 워크트리는 그 저장소의 것만 아래에 펼친다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    try openScmDockWithCommitBox(session, allocator, arena_state.allocator());

    // 터미널을 하나 더 열고 **그 Term만** 다른 저장소에 세운다(비활성 탭이 목록에 새지 않아야 한다).
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 't' }, .modifiers = .{ .command = true } });
    const pane = pane_ops.activePane(session);
    try std.testing.expect(pane.terms.items.len >= 2);
    for (pane.terms.items, 0..) |term, index| {
        term.rt.observation.cwd.clearRetainingCapacity();
        // 활성이 아닌 Term에 **실재하는** 저장소 경로를 준다 — 목록에 새면 여기서 잡힌다.
        try term.rt.observation.cwd.appendSlice(allocator, if (index == pane.active_term) "/tmp" else "/repo");
        term.rt.observation.availability = .current;
    }
    scm_dock_ops.invalidateRepoList(session);

    const repos = scm_dock_ops.repoEntries(session);
    // 활성 Term은 `/tmp`(저장소 아님)라 뿌리가 없고, 그때 목록은 **마지막으로 읽은 저장소**만 든다.
    try std.testing.expectEqual(@as(usize, 1), repos.entries.len);
    try std.testing.expectEqualStrings("/repo", repos.entries[0].path);
}

test "소스 컨트롤: 비활성 저장소는 머리 줄 요약이 오면 `읽는 중…`을 벗는다 (P3d-③)" {
    // 읽기는 하나씩 돈다 — 그래서 "아직 안 읽은 저장소"가 실제로 생긴다. 그 줄은 0건이 아니라
    // **모르는 것**이고, 답이 오면 브랜치와 개수를 얻는다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    try openScmDockWithCommitBox(session, allocator, arena_state.allocator());

    // 목록에 저장소 둘: 읽은 것(/repo)과 아직 안 읽은 것(/other).
    session.git_result.?.worktrees = try git_backend_mod.worker_allocator.dupe(
        u8,
        "worktree /repo\nbranch refs/heads/main\n\nworktree /other\nbranch refs/heads/side\n",
    );
    // 읽기 결과가 바뀌면 목록 캐시가 무효화된다(제품은 결과를 싣는 그 자리에서 한다) — 테스트는
    // 결과를 손으로 심으므로 같은 문을 직접 연다.
    scm_dock_ops.invalidateRepoList(session);

    {
        const projection = scm_dock_ops.project(session, arena_state.allocator()) orelse return error.MissingProjection;
        try std.testing.expect(projection.items[0] == .repo);
        // 두 번째 머리 줄은 아직 답이 없다 — **읽는 중**이지 0건이 아니다.
        var pending_seen = false;
        for (projection.items) |item| switch (item) {
            .repo => |repo| if (repo.index == 1) {
                try std.testing.expect(repo.pending);
                pending_seen = true;
            },
            else => {},
        };
        try std.testing.expect(pending_seen);
    }

    // 그 저장소의 요약이 도착했다(백엔드가 주는 것과 같은 모양 — `status` 하나).
    session.scm_repo_status_inflight = 7;
    session.git_backend.?.state.?.repo_status_result = .{
        .request_id = 7,
        .ok = true,
        .repo = try git_backend_mod.worker_allocator.dupe(u8, "/other"),
        .text = try git_backend_mod.worker_allocator.dupe(u8, "# branch.head side\n1 .M N... 1 2 3 a b x.txt\n? y.txt\n"),
    };
    scm_dock_ops.drainRepoStatus(session);
    // 캐시에 실렸는가부터 본다 — 아니면 화면 판정을 볼 이유가 없다.
    try std.testing.expectEqual(@as(usize, 1), session.scm_repo_status.items.len);
    try std.testing.expectEqualStrings("/other", session.scm_repo_status.items[0].path);

    const projection = scm_dock_ops.project(session, arena_state.allocator()) orelse return error.MissingProjection;
    var checked = false;
    for (projection.items) |item| switch (item) {
        .repo => |repo| if (repo.index == 1) {
            try std.testing.expect(!repo.pending);
            try std.testing.expectEqualStrings("side", repo.branch);
            try std.testing.expectEqual(@as(u32, 2), repo.count); // 추적되지 않은 것도 센다
            checked = true;
        },
        else => {},
    };
    try std.testing.expect(checked);
}

test "소스 컨트롤: 목록에서 사라진 저장소의 요약은 버린다(상한이 막히지 않게)" {
    // 요약 캐시 상한은 목록 상한과 같다. 저장소를 여닫으며 옛 항목이 쌓여 그 자리가 차면 **새 저장소가
    // 영영 `읽는 중…`으로 남는다** — 게다가 그 값들은 이미 화면에 없는 저장소의 것이다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    try openScmDockWithCommitBox(session, allocator, arena_state.allocator());

    // 목록에 없는 저장소의 요약을 하나 심는다(이전에 열려 있던 것).
    try session.scm_repo_status.append(allocator, .{
        .path = try allocator.dupe(u8, "/gone"),
        .branch = try allocator.dupe(u8, "old"),
        .detached = false,
        .count = 3,
        .ahead = 0,
        .behind = 0,
        .has_ab = false,
    });
    try std.testing.expectEqual(@as(usize, 1), session.scm_repo_status.items.len);

    // 목록을 다시 걸으면 그 항목은 사라진다.
    scm_dock_ops.invalidateRepoList(session);
    _ = scm_dock_ops.repoEntries(session);
    try std.testing.expectEqual(@as(usize, 0), session.scm_repo_status.items.len);
}

test "소스 컨트롤: 비활성 저장소를 펼치면 파일 줄이 서고 **숫자는 빈다** (P3d-②d)" {
    // 파일 줄의 실체(경로·그룹·상태 문자·동작)는 `status` 하나에서 나온다 — 그래서 머리 줄 읽기에
    // 실려 온 그 출력으로 **추가 프로세스 없이** 목록을 세운다. `numstat`이 없으니 증감 숫자만 빈다
    // (0으로 그리면 "안 바뀐 파일"이라고 거짓말을 한다 — 추적되지 않은 파일이 쓰는 길과 같다).
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();
    try openScmDockWithCommitBox(session, allocator, arena);

    session.git_result.?.worktrees = try git_backend_mod.worker_allocator.dupe(
        u8,
        "worktree /repo\nbranch refs/heads/main\n\nworktree /other\nbranch refs/heads/side\n",
    );
    scm_dock_ops.invalidateRepoList(session);
    // 그 저장소의 머리 줄 읽기 결과(= status 출력)를 심는다.
    try session.scm_repo_status.append(allocator, .{
        .path = try allocator.dupe(u8, "/other"),
        .branch = try allocator.dupe(u8, "side"),
        .detached = false,
        .count = 1,
        .ahead = 0,
        .behind = 0,
        .has_ab = false,
        .status_text = try allocator.dupe(u8, "# branch.head side\n1 M. N... 100644 100644 100644 aaa bbb other.zig\n"),
    });

    const projection = scm_dock_ops.project(session, arena) orelse return error.MissingProjection;
    var file_row: ?chrome.components.scm_dock.types.FileItem = null;
    for (projection.items) |item| switch (item) {
        .file => |file| if (file.repo_index == 1) {
            file_row = file;
        },
        else => {},
    };
    const row = file_row orelse return error.MissingInactiveFileRow;
    try std.testing.expectEqualStrings("other.zig", row.name);
    // **증감 자리는 비어 있다** — 모르는 것을 0으로 적지 않는다.
    try std.testing.expect(!row.has_delta);
    // 그리고 그 줄은 **자기 저장소를 싣는다**(같은 번호의 남의 파일이 열리지 않게).
    try std.testing.expectEqual(@as(u32, 1), row.repo_index);
}

test "소스 컨트롤: 머리 줄 새로고침은 **그 저장소**를 다시 읽게 한다 (P3d-②c)" {
    // 읽기라 언제나 실행한다. 다만 활성 저장소면 목록 읽기를, 아니면 그 머리 줄 읽기를 다시 건다 —
    // 둘이 같은 사실을 각자 들지 않는다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
