test "소스 컨트롤: 실제 입력 경로로 글자가 상자에 들어간다(라우팅까지)" {
    // 앞의 편집 테스트들은 `handleCommitKey`를 직접 부른다 — 그것만으로는 **키가 거기까지 오는지**를
    // 증명하지 못한다. macOS에서 평범한 타이핑은 IME 확정 텍스트로 들어와
    // `routeCommittedText → sendTextAsKeys → handleKeyEvent`를 지나므로, 그 경로를 그대로 태운다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    try openScmDockWithCommitBox(session, allocator, arena_state.allocator());

    const p = try commitBoxPoint(session, 12, 6);
    session.mouse(1, p.x, p.y, 0, 0);
    session.mouse(3, p.x, p.y, 0, 0);
    input_ops.routeCommittedText(session, "가");
    input_ops.routeCommittedText(session, "b");
    try std.testing.expectEqualStrings("가b", session.scm_commit_field.text.items);

    // 그리고 **터미널로는 한 글자도 안 간다** — 상자가 소유했으면 뒤 PTY는 아무것도 못 받는다.
    try std.testing.expect(session.scmCommitOwnsInput());
}

test "소스 컨트롤: 커밋 상자 폭은 도크 content 폭과 같다(랩 입력이 갈리지 않게)" {
    // 상자 높이는 host가, 글자 자리는 view가 랩해서 정한다. 두 랩이 같은 답을 내는 근거는 **입력이
    // 하나**라는 것뿐이다 — 열 수는 `commitViewCols`가 단일 출처이고, 그 입력인 폭이 갈리면 host가
    // 2줄이라 믿는 상자에 view가 5줄을 그리고 caret이 안 보이는 줄에 선다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    try openScmDockWithCommitBox(session, allocator, arena_state.allocator());

    const content = dock_ops.dockGeometry(session).tree_content;
    const rect = scm_dock_ops.commitBoxRectAt(session, 0) orelse return error.MissingCommitBox;
    try std.testing.expectEqual(@as(f32, 0), rect.x);
    // **공식이 아니라 계약을 단언한다**(2026-08-20). 상자는 목록 줄이라 스크롤바 자리만큼 좁아지는데,
    // 그 자리는 이제 **넘칠 때만** 생긴다 — 폭을 여기서 다시 계산하면 이 테스트가 자리 규칙의 사본이
    // 되고, 규칙이 바뀔 때 함께 낡는다(실제로 그렇게 낡아 한 번 빨갛게 났다).
    //
    // 지켜야 하는 것은 하나다: **발행된 상자 폭에서 나온 열 수 = host가 랩에 쓰는 열 수.** 그 둘이
    // 갈리면 host가 2줄이라 믿는 상자에 view가 3줄을 그리고 caret이 안 보이는 줄에 선다.
    const m = chrome.components.scm_dock.types.DockMetrics.resolve(scm_dock_ops.scmDockScaleMilli(session));
    try std.testing.expect(rect.width > 0);
    try std.testing.expect(rect.width <= @as(f32, @floatFromInt(content.w)));
    try std.testing.expectEqual(
        m.commitViewCols(rect.width, session.cell_width_px),
        scm_dock_ops.commitViewColsForTest(session),
    );
}

test "소스 컨트롤: 붙여넣기는 개행·탭을 남기고 CR·제어문자·손상 바이트를 버린다" {
    // 커밋 메시지는 여러 줄이 정상이라 개행을 지우면 안 되고(주소창과 다른 점), 반대로 CR이 섞이면
    // **저장되는 것과 보이는 것이 달라진다** — 화면에서는 폭 0이라 아무 표시가 없다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    try openScmDockWithCommitBox(session, allocator, arena_state.allocator());
    scm_dock_ops.focusCommitRepo(session, "/repo");

    // CRLF 클립보드 + ESC + DEL + 손상 UTF-8 lead 바이트.
    scm_dock_ops.insertCommitText(session, "fix: 제목\r\n\n\tbody\x1b\x7f\xff!");
    try std.testing.expectEqualStrings("fix: 제목\n\n\tbody!", session.scm_commit_field.text.items);
}

test "소스 컨트롤: 도크 **밖**을 눌러도 편집이 풀린다" {
    // 도크 안에서만 클릭-어웨이를 보면, 터미널을 눌러 놓고 친 글자가 커밋 메시지로 들어간다 —
    // 사용자에게는 셸이 먹통이 된 것으로 보인다(적대적 검증 2026-08-16).
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    try openScmDockWithCommitBox(session, allocator, arena_state.allocator());

    const inside = try commitBoxPoint(session, 12, 6);
    session.mouse(1, inside.x, inside.y, 0, 0);
    session.mouse(3, inside.x, inside.y, 0, 0);
    try std.testing.expect(session.scm_commit_focus_repo != null);

    // 터미널 본문(도크 왼쪽)을 누른다.
    const term_rect = dock_ops.dockGeometry(session).terminal;
    session.mouse(1, @as(f64, @floatFromInt(term_rect.x + term_rect.w / 2)), @as(f64, @floatFromInt(term_rect.y + term_rect.h / 2)), 0, 0);
    try std.testing.expect(session.scm_commit_focus_repo == null);
    try std.testing.expectEqual(AppSession.InputFocus.terminal, session.inputFocus());
}

test "소스 컨트롤: 읽기에 실패한 저장소는 쉬었다 다시 읽는다" {
    // 실패를 기록하지 않으면 그 저장소는 계속 "아직 안 읽은 것"이라 **매 tick git을 다시 띄우고**,
    // 읽기가 하나씩 도는 규율 때문에 뒤의 저장소는 차례가 영영 오지 않는다(적대적 5회차).
    const second: i128 = std.time.ns_per_s;
    const fresh_failure: RepoStatusEntry = .{
        .path = @constCast("/gone"),
        .branch = @constCast(""),
        .detached = false,
        .count = 0,
        .ahead = 0,
        .behind = 0,
        .has_ab = false,
        .failed = true,
        .read_ns = 100 * second,
    };
    try std.testing.expect(!scm_dock_ops.shouldReadRepoStatus(fresh_failure, 101 * second));
    try std.testing.expect(scm_dock_ops.shouldReadRepoStatus(fresh_failure, 110 * second));
    // 한 번도 못 읽은 저장소는 곧바로 읽는다 — 그것이 "읽는 중…"이 곧 끝난다는 약속이다.
    try std.testing.expect(scm_dock_ops.shouldReadRepoStatus(null, 0));
    // 성공해서 실려 있는 값은 낡았다고 표시될 때만 다시 읽는다.
    var ok_entry = fresh_failure;
    ok_entry.failed = false;
    ok_entry.stale = false;
    try std.testing.expect(!scm_dock_ops.shouldReadRepoStatus(ok_entry, 1000 * second));
    ok_entry.stale = true;
    try std.testing.expect(scm_dock_ops.shouldReadRepoStatus(ok_entry, 1000 * second));
}

test "소스 컨트롤: 그룹을 접으면 그 상자의 편집이 풀린다(글은 초안으로 남는다)" {
    // 접힌 그룹에는 상자가 없다. 포커스를 그대로 두면 키가 **화면에 없는 상자**로 들어가 사용자는
    // 자기가 친 글자를 볼 수 없다(적대적 4회차).
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();
    try openScmDockWithCommitBox(session, allocator, arena);

    scm_dock_ops.focusCommitRepo(session, "/repo");
    _ = scm_dock_ops.handleCommitKey(session, .{ .key = .{ .key = .char, .codepoint = 'z', .mods = .{} } });
    scm_dock_ops.toggleRepoCollapsed(session, "/repo");
    try std.testing.expect(session.scm_commit_focus_repo == null);

    // 다시 펴고 상자를 잡으면 쓰던 글이 그대로 있다 — 접기는 글을 버리는 동작이 아니다.
    scm_dock_ops.toggleRepoCollapsed(session, "/repo");
    scm_dock_ops.focusCommitRepo(session, "/repo");
    try std.testing.expectEqualStrings("z", session.scm_commit_field.text.items);
}

test "소스 컨트롤: 창 밖으로 스크롤된 상자는 타이핑하면 창 안으로 돌아온다" {
    // 상자가 목록 줄이 되면서(②b) 스크롤로 창 밖에 놓일 수 있다. 그 상태로 키를 치면 글자는 들어가는데
    // **화면에는 아무 일도 안 일어난다** — 사용자는 자기가 친 글자가 어디로 갔는지 알 수 없다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();
    try openScmDockWithCommitBox(session, allocator, arena);

    scm_dock_ops.focusCommitRepo(session, "/repo");
    // 목록을 아래로 밀어 상자를 창 밖으로 보낸다(상자는 머리 줄 바로 다음 줄이다).
    session.scm_scroll.offset_y_px = 400;
    _ = scm_dock_ops.handleCommitKey(session, .{ .key = .{ .key = .char, .codepoint = 'a', .mods = .{} } });
    _ = scm_dock_ops.project(session, arena) orelse return error.MissingProjection;
    // 상자가 목록 위쪽에 있으므로 창은 그 자리까지 되돌아온다.
    try std.testing.expect(session.scm_scroll.offset_y_px < 400);
    const m = chrome.components.scm_dock.types.DockMetrics.resolve(1000);
    try std.testing.expect(session.scm_scroll.offset_y_px <= m.repo_h);
}

test "소스 컨트롤: 목록 뷰포트는 **컴포넌트가 세우는 창**과 같다(상자는 그 안에 산다)" {
    // 호스트가 세는 창과 `build`가 세우는 창이 갈리면 목록 아래쪽이 **항목이 있는데도 안 그려지고**
    // 스크롤은 끝을 지나 빈 자리로 간다. ②b 전에는 커밋 줄이 고정 chrome이라 상자가 자란 만큼 창이
    // 줄어드는 것이 맞았지만, 지금 상자는 목록 항목이다(적대적 4회차).
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();
    try openScmDockWithCommitBox(session, allocator, arena);

    const before = scm_dock_ops.scrollExtent(session).viewport_h_px;
    scm_dock_ops.focusCommitRepo(session, "/repo");
    _ = scm_dock_ops.handleCommitKey(session, .{ .key = .{ .key = .char, .codepoint = 'a', .mods = .{} } });
    _ = scm_dock_ops.handleCommitKey(session, .{ .key = .{ .key = .enter, .mods = .{} } });
    _ = scm_dock_ops.handleCommitKey(session, .{ .key = .{ .key = .char, .codepoint = 'b', .mods = .{} } });
    const after = scm_dock_ops.scrollExtent(session).viewport_h_px;
    // 상자가 두 줄로 자라도 창은 그대로다 — 자란 만큼은 **목록 내용**이 길어진 것이다.
    try std.testing.expectEqual(before, after);

    // 그리고 그 창은 컴포넌트가 세우는 스크롤 영역 높이와 **같은 수**다.
    const projection = scm_dock_ops.project(session, arena) orelse return error.MissingProjection;
    const props = scm_dock_ops.testProps(session, projection);
    const sizes = chrome.components.scm_dock.build.bufferSizes(props.items);
    const frame = try chrome.components.scm_dock.build.build(props, .{
        .nodes = try arena.alloc(chrome.ui.tree.UiNode, sizes.nodes),
        .entries = try arena.alloc(chrome.ui.tree.RectEntry, sizes.entries),
        .layout_items = try arena.alloc(chrome.ui.layout.Item, sizes.layout_items),
        .flex_scratch = try arena.alloc(chrome.ui.layout.FlexScratch, sizes.flex_scratch),
        .child_rects = try arena.alloc(chrome.ui.layout.UiRect, sizes.child_rects),
        .actions = try arena.alloc(chrome.components.scm_dock.ids.Entry, sizes.actions),
    });
    const content_index = frame.tree.find(chrome.components.scm_dock.build.NodeIds.content) orelse
        return error.MissingContentRect;
    const content = frame.tree.entries[content_index];
    try std.testing.expectEqual(@as(u32, @intFromFloat(content.rect.height)), after);
}

test "소스 컨트롤: 변경이 없으면 빈 목록이 아니라 문장을 낸다" {
    // [GUI 확인 2026-08-16] 깨끗한 저장소에서 목록 자리가 **아무 말도 안 하는 빈 면**이었다. 사용자에게
    // 그 화면은 "아직 못 읽었다"와 구별되지 않는다. 컴포넌트에는 안내 한 줄 계약이 있었지만 제품이
    // `empty_notice`를 채우지 않아 그 계약이 **제품 경로에서만** 죽어 있었다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    // 저장소 목록은 터미널 cwd에서 나온다(P3d) — 테스트 프로세스의 저장소가 새 들어오지 않게 고정한다.
    try pinTermsOutsideRepo(session, allocator);

    session.git_backend = try git_backend_mod.Backend.init(session.io);
    session.git_backend.?.state.?.shutting_down = true;
    // 도크를 **연다**. 열지 않으면 content rect가 0이라 글자가 들어갈 자리가 없고, 이 테스트는
    // "문장이 없다"를 그리기 실패가 아니라 정답으로 읽게 된다.
    const launcher = file_panel_ops.filePanelDockControlRect(session) orelse return error.MissingDockLauncher;
    session.mouse(1, @floatFromInt(launcher.x + 1), @floatFromInt(launcher.y + 1), 0, 0);
    dock_ops.setDockView(session, .source_control);

    // 읽기는 **성공했고** 바뀐 것이 없다(porcelain v2에 파일 줄이 없다). "못 읽었다"(`git_result == null`)와
    // 다른 사실이므로 다른 문장이어야 한다.
    session.git_result = .{
        .status = try git_backend_mod.worker_allocator.dupe(u8, "# branch.head main\n"),
        .ok = true,
    };
    git_ops.rememberGitRepo(session, "/repo");

    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();
    const projection = scm_dock_ops.project(session, arena) orelse return error.MissingProjection;
    // 머리 줄 + 커밋 줄 둘 + **안내 한 줄**이고 파일 줄은 없다(P3d·②b — 목록의 첫 층이 저장소이고
    // 상자는 그 그룹 안에 산다). 변경이 없어도 상자는 선다 — 커밋할 것이 없다는 사실은 버튼 색이 말한다.
    // 안내가 **목록 항목인 것**이 핵심이다: 스크롤 영역 위쪽에 그리면 머리 줄과 글자가 겹친다.
    try std.testing.expectEqual(@as(usize, 4), projection.items.len);
    try std.testing.expect(projection.items[0] == .repo);
    try std.testing.expect(projection.items[1] == .commit_box);
    try std.testing.expect(projection.items[2] == .commit_button);
    try std.testing.expectEqualStrings(git_ops.noticeNoChanges(), projection.items[3].notice);
    const props = scm_dock_ops.testProps(session, projection);

    // 그리고 그 문장이 실제로 **그려진다** — props에만 있고 화면에 없으면 같은 빈 면이다.
    const sizes = chrome.components.scm_dock.build.bufferSizes(props.items);
    const frame = try chrome.components.scm_dock.build.build(props, .{
        .nodes = try arena.alloc(chrome.ui.tree.UiNode, sizes.nodes),
        .entries = try arena.alloc(chrome.ui.tree.RectEntry, sizes.entries),
        .layout_items = try arena.alloc(chrome.ui.layout.Item, sizes.layout_items),
        .flex_scratch = try arena.alloc(chrome.ui.layout.FlexScratch, sizes.flex_scratch),
        .child_rects = try arena.alloc(chrome.ui.layout.UiRect, sizes.child_rects),
        .actions = try arena.alloc(chrome.components.scm_dock.ids.Entry, sizes.actions),
    });
    // **예산은 제품과 같은 것을 쓴다**(`collectScmDock`과 같은 호출). 넉넉한 버퍼로 그리면 예산이 낡아도
    // 이 테스트가 통과하는데, 그 조합이 바로 도크가 통째로 사라진 원인이었다.
    const budget = chrome.components.scm_dock.view.drawBufferSizes(props, frame.tree.entries.len);
    const tokens_v = session.buildChromeTokens();
    const draws = try chrome.components.scm_dock.view.view(props, frame, .{}, &tokens_v, .{
        .ops = try arena.alloc(chrome.draw.Op, budget.ops),
        .runs = try arena.alloc(chrome.draw.Run, budget.runs),
        .text_bytes = try arena.alloc(u8, budget.text_bytes),
    });
    var saw_notice = false;
    for (draws.ops) |op| switch (op) {
        .text => |text| for (text.runs) |run| {
            if (std.mem.indexOf(u8, run.text, git_ops.noticeNoChanges()) != null) saw_notice = true;
        },
        else => {},
    };
    try std.testing.expect(saw_notice);
}

test "소스 컨트롤: `+` 버튼을 누르면 **그 행의** 스테이지 intent가 난다 (P2c)" {
    // 이 뷰가 처음으로 저장소를 바꾸는 경로다. 그래서 "누른 버튼이 **어느 파일을** 대상으로 하는가"를
    // published tree로 그대로 태워 고정한다 — 창 자리와 모델 인덱스가 갈리면 여기서 잡힌다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    // 저장소 목록은 터미널 cwd에서 나온다(P3d) — 테스트 프로세스의 저장소가 새 들어오지 않게 고정한다.
    try pinTermsOutsideRepo(session, allocator);

    session.git_backend = try git_backend_mod.Backend.init(session.io);
    // **실제 git을 띄우지 않는다.** 여기서 보는 것은 클릭 → intent 배선이고, 실행은 git_backend의
    // 실제 저장소 fixture가 따로 검증한다.
    session.git_backend.?.state.?.shutting_down = true;
    const launcher = file_panel_ops.filePanelDockControlRect(session) orelse return error.MissingDockLauncher;
    session.mouse(1, @floatFromInt(launcher.x + 1), @floatFromInt(launcher.y + 1), 0, 0);
    dock_ops.setDockView(session, .source_control);

    session.git_result = .{
        .status = try git_backend_mod.worker_allocator.dupe(u8, "# branch.head main\n1 .M N... 1 2 3 a b one.txt\n1 .M N... 1 2 3 a b two.txt\n"),
        .numstat_head = try git_backend_mod.worker_allocator.dupe(u8, "1\t0\tone.txt\n2\t0\ttwo.txt\n"),
        .ok = true,
    };
    git_ops.rememberGitRepo(session, "/repo");

    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();
    const projection = scm_dock_ops.project(session, arena) orelse return error.MissingProjection;
    const props = scm_dock_ops.testProps(session, projection);
    const sizes = chrome.components.scm_dock.build.bufferSizes(props.items);
    const frame = try chrome.components.scm_dock.build.build(props, .{
        .nodes = try arena.alloc(chrome.ui.tree.UiNode, sizes.nodes),
        .entries = try arena.alloc(chrome.ui.tree.RectEntry, sizes.entries),
        .layout_items = try arena.alloc(chrome.ui.layout.Item, sizes.layout_items),
        .flex_scratch = try arena.alloc(chrome.ui.layout.FlexScratch, sizes.flex_scratch),
        .child_rects = try arena.alloc(chrome.ui.layout.UiRect, sizes.child_rects),
        .actions = try arena.alloc(chrome.components.scm_dock.ids.Entry, sizes.actions),
    });
    scm_dock_ops.publishScmDockFrame(session, frame, props.items);

    const content = dock_ops.dockGeometry(session).tree_content;
    // 2번 행(`two.txt`)의 **동작 버튼** rect를 찾는다. 행 rect가 아니라 버튼 rect여야 `+`를 누른 것이다.
    const button = blk: {
        for (session.scm_dock_entries.items) |entry| {
            // 0=머리 줄 · 1=커밋 입력 · 2=커밋 버튼 · 3=그룹 헤더 · 4=one.txt · **5=two.txt**.
            if (entry.id != chrome.components.scm_dock.build.NodeIds.itemAction(5)) continue;
            break :blk .{
                .x = @as(f64, @floatFromInt(content.x)) + entry.rect.x + entry.rect.width / 2,
                .y = @as(f64, @floatFromInt(content.y)) + entry.rect.y + entry.rect.height / 2,
            };
        }
        return error.MissingActionRect;
    };

    _ = scm_dock_ops.scmDockPointer(session, .down, button.x, button.y);
    const intent = scm_dock_ops.scmDockPointer(session, .up, button.x, button.y) orelse return error.NoIntent;
    switch (intent) {
        // **모델 인덱스 2 = `two.txt`**다. 창 자리를 실었다면 여기가 다른 값이 된다.
        // **어느 저장소의 몇 번째 행인가**(②d).
        .row_action => |ref| try std.testing.expectEqual(@as(u32, 2), ref.model_index),
        else => return error.WrongIntent,
    }

    // 충돌이 아닌 변경 사항 행이므로 방향은 스테이지다(모델이 판정한 값을 host가 그대로 옮긴다).
    // 0=머리 줄 · 1=커밋 입력 · 2=커밋 버튼(②b) · 3=그룹 헤더 · 4=one.txt · **5=two.txt**
    try std.testing.expectEqual(chrome.components.scm_dock.types.RowAction.stage, props.items[5].file.action);
}

// [손 확인] "첫 파일은 열리는데 두 번째가 안 열린다". 클릭 경로(행 → openDiffForScmRow)를 그대로 태워 재현한다.
test "소스 컨트롤: 여러 행을 연달아 눌러도 각각 diff Term이 열린다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    // 위 테스트와 같은 이유로 backend를 `shutting_down` 상태로 미리 만든다 — diff Term을 열면 detach된
    // `diffWorker`가 뜨는데 테스트가 그 완료를 기다릴 수 없어, 반환 시점에 워커의 argv 버퍼가 leak으로 판정된다.
    session.git_backend = try git_backend_mod.Backend.init(session.io);
    session.git_backend.?.state.?.shutting_down = true;

    // gitRepoRoot가 이 저장소를 찾도록 탐색기 root 대신 임시 저장소를 흉내 낼 수는 없으므로, 클릭 경로의
    // 앞단(openDiffTerm)을 직접 부른다 — 검증 대상은 "두 번째 열기가 되는가"이지 저장소 탐색이 아니다.
    git_ops.openDiffTerm(session, "/repo", "/repo/a.txt", "a.txt", null, .unstaged);
    git_ops.openDiffTerm(session, "/repo", "/repo/b.txt", "b.txt", null, .unstaged);

    var diffs: usize = 0;
    var it = file_panel_ops.fileEntries(session);
    while (it.next()) |entry| {
        if (entry.kind == .diff) diffs += 1;
    }
    try std.testing.expectEqual(@as(usize, 2), diffs);
    try std.testing.expect(git_ops.diffTermFor(session, "/repo/a.txt", .unstaged) != null);
    try std.testing.expect(git_ops.diffTermFor(session, "/repo/b.txt", .unstaged) != null);
}

// [적대적 검증 2026-08-14] 같은 파일이 두 그룹에 동시에 있을 수 있으므로(`MM`) 탭 제목이 비교 기준으로 갈려야
// 한다. 잠시 있던 빈 라벨 base가 탭을 `a.txt · `로 끝나게 만들었던 것을 함께 막는다(가드는 남겨 뒀다).
test "diff 탭 라벨: 같은 파일의 두 비교가 탭에서 갈린다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    session.git_backend = try git_backend_mod.Backend.init(session.io);
    session.git_backend.?.state.?.shutting_down = true;

    git_ops.openDiffTerm(session, "/repo", "/repo/a.txt", "a.txt", null, .unstaged);
    const plain = git_ops.diffTermFor(session, "/repo/a.txt", .unstaged) orelse return error.MissingDiffTerm;
    const plain_label = try session.diffAwareLabel(allocator, plain);
    defer allocator.free(plain_label);
    try std.testing.expect(std.mem.indexOf(u8, plain_label, maru.i18n.t(.dock_worktree)) != null);

    // 같은 파일의 다른 비교는 무엇을 보고 있는지 탭에서 갈려야 한다(양쪽 그룹에 동시에 있을 수 있으므로).
    git_ops.openDiffTerm(session, "/repo", "/repo/a.txt", "a.txt", null, .staged);
    const staged = git_ops.diffTermFor(session, "/repo/a.txt", .staged) orelse return error.MissingDiffTerm;
    const staged_label = try session.diffAwareLabel(allocator, staged);
    defer allocator.free(staged_label);
    try std.testing.expect(std.mem.indexOf(u8, staged_label, maru.i18n.t(.dock_staged)) != null);

    // 두 Term은 서로 다른 Term이다 — 유일성 키에 base가 들어 있다는 계약의 반대쪽 확인.
    try std.testing.expect(plain != staged);
}

// [E1 종료 조건] 읽는 중에 그 Term을 닫는 경로. 늦게 도착한 결과가 **사라진 entry를 건드리면** 크래시고, 그냥
// 흘려보내면 누수다. 둘 다 아니어야 한다 — testing.allocator가 누수를, drain의 짝 맞추기가 오배정을 잡는다.
test "diff Term을 읽는 중에 닫아도 결과가 안전하게 버려진다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    git_ops.openDiffTerm(session, "/repo", "/repo/a.txt", "a.txt", null, .unstaged);
    const term = git_ops.diffTermFor(session, "/repo/a.txt", .unstaged) orelse return error.MissingDiffTerm;
    const entry = term.file_entry orelse return error.MissingEntry;
    const request_id = entry.diff_request_id;

    // 그 Term을 닫는다(백엔드가 실제로 돌고 있었다면 결과는 뒤에 온다).
    const pane = pane_ops.activePane(session);
    var index: usize = 0;
    while (index < pane.terms.items.len) : (index += 1) {
        if (pane.terms.items[index] == term) break;
    }
    term_ops.closeTermAt(session, session.app_window.active_tab, pane, index);
    try std.testing.expect(git_ops.diffTermFor(session, "/repo/a.txt", .unstaged) == null);

    // 늦게 온 결과를 흉내 낸다: 그 request_id를 가진 결과가 도착해도 짝이 없어 그냥 버려져야 한다(크래시·누수 없음).
    if (session.git_backend) |*backend| {
        _ = backend;
        var late: git_backend_mod.DiffResult = .{
            .original = try allocator.dupe(u8, "old"),
            .modified = try allocator.dupe(u8, "new"),
            .ok = true,
            .request_id = request_id,
        };
        // drainGitStatus가 하는 일과 같은 절차 — 짝이 없으면 해제한다.
        var matched = false;
        var it = file_panel_ops.fileEntries(session);
        while (it.next()) |candidate| {
            if (candidate.kind == .diff and candidate.diff_request_id == late.request_id) matched = true;
        }
        try std.testing.expect(!matched);
        late.deinit(allocator);
    }

    // 이 테스트는 **워커가 도는 것을 전제**한다("결과는 뒤에 온다"). 그런데 `diffWorker`는 detach라 join할 수
    // 없고, 테스트 함수가 반환할 때 워커가 아직 `git show` 중이면 그 argv 버퍼가 leak으로 판정돼 ABRT로 죽는다
    // (제품 코드는 refcount라 늦게 끝나도 안전하게 회수된다).
    //
    // 그래서 워커가 실제로 끝난 것을 확인하고 반환한다 — 결과가 버려지는 것까지 봐야 "안전하게 버려진다"를
    // 검증한 것이기도 하다. `/repo`는 없는 저장소라 git이 즉시 실패해 대기는 수십 ms 수준이다.
    if (session.git_backend) |*backend| {
        var waited_ms: usize = 0;
        while (waited_ms < 5_000) : (waited_ms += 5) {
            if (backend.takeDiffResult()) |result| {
                var owned = result;
                owned.deinit(allocator);
                break;
            }
            std.Io.sleep(session.io, std.Io.Duration.fromMilliseconds(5), .awake) catch {};
        }
    }
}

// [E1 §6.1] 턴 스냅샷 전 구간을 **실제 git**으로 돌린다: 스냅샷 요청 → 링 적재 → base 가 직전 턴의 키·제목을
// 물려받지 않는지까지. 에이전트 감지 자체는 별도(agent_observer·turn_snapshot 단위 테스트)이고, 여기서는 그 뒤
// 배관을 본다.
//
// **한때 이 뒤에 «목록이 그 기준으로 턴 범위를 읽어 온다» 절반이 더 있었다**(2026-08-25 제거). 그쪽이 재던
// `Result.turn_name_status` 는 상태 갱신 worker 가 채우기만 하고 **화면 소비자가 0** 이라, 그 배관과 함께 걷혔다.
// 펼친 턴의 파일 목록은 그 경로가 아니라 `submitTurnFiles`(`Kind.turn_name_status`)가 답한다 — 이름이 비슷한
// 다른 배관이다.
test "턴 스냅샷이 링에 실리고 base 는 직전 턴의 키·제목을 물려받지 않는다" {
    // **이 테스트는 턴 스냅샷을 실제로 찍겠다고 밝힌다.** 기본은 꺼짐이다 — 그 경로가 `git` 을 띄우고
    // detached worker 에 job 을 넘겨, 곧바로 `deinit` 하는 테스트에서 타이밍 누수를 낸다
    // (`test_allow_turn_snapshot`).
    agent_ops.test_allow_turn_snapshot = true;
    defer agent_ops.test_allow_turn_snapshot = false;
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    var exe_buf: [std.fs.max_path_bytes]u8 = undefined;
    const git_exe = git_backend_mod.locate(&exe_buf) orelse return error.SkipZigTest;

    var cwd_buf: [std.fs.max_path_bytes]u8 = undefined;
    const cwd_ptr = std.c.getcwd(&cwd_buf, cwd_buf.len) orelse return error.SkipZigTest;
    const cwd = std.mem.span(@as([*:0]u8, @ptrCast(cwd_ptr)));
    var repo_buf: [std.fs.max_path_bytes]u8 = undefined;
    const repo = std.fmt.bufPrint(&repo_buf, "{s}/.zig-cache/tmp-session-turn", .{cwd}) catch return error.SkipZigTest;
    if (!git_backend_mod.testRunQuiet(&.{ "/bin/rm", "-rf", repo })) return error.SkipZigTest;
    defer _ = git_backend_mod.testRunQuiet(&.{ "/bin/rm", "-rf", repo });
    if (!git_backend_mod.testRunQuiet(&.{ git_exe, "init", "-q", "-b", "main", repo })) return error.SkipZigTest;
    if (!git_backend_mod.testRunQuiet(&.{ git_exe, "-C", repo, "config", "user.email", "t@t" })) return error.SkipZigTest;
    if (!git_backend_mod.testRunQuiet(&.{ git_exe, "-C", repo, "config", "user.name", "t" })) return error.SkipZigTest;
    git_backend_mod.testWriteFile(repo, "kept.txt", "v1\n") catch return error.SkipZigTest;
    if (!git_backend_mod.testRunQuiet(&.{ git_exe, "-C", repo, "add", "kept.txt" })) return error.SkipZigTest;
    if (!git_backend_mod.testRunQuiet(&.{ git_exe, "-C", repo, "commit", "-qm", "base" })) return error.SkipZigTest;

    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    // 저장소를 목록의 root로 세운다 — 제품에서 파일을 열면 root가 추론되는 그 경로다.
    var opened_buf: [std.fs.max_path_bytes]u8 = undefined;
    const opened = try std.fmt.bufPrint(&opened_buf, "{s}/kept.txt", .{repo});
    try session.file_tree.recordOpened(opened, repo);
    git_ops.rememberGitRepo(session, repo);

    // **대상 저장소는 이제 활성 터미널이 정한다**(docs/editor-surface-dock.md §3.5). 이 테스트 프로세스의 터미널은
    // maru 저장소에 서 있으므로, 그대로 두면 목록이 임시 저장소가 아니라 maru를 읽어 턴 범위가 비어 버린다.
    // 그래서 **diff를 연 상태**를 만든다 — 활성 Term이 파일 Term이 되어 터미널 기준이 사라지고, §3.5의 2순위
    // (직전에 목록을 읽은 저장소)가 대상을 고정한다. 제품에서 목록을 보다 diff를 연 바로 그 상태이고,
    // 이 테스트가 그 2순위 규칙의 회귀 가드도 겸한다.
    git_ops.openDiffTerm(session, repo, opened, "kept.txt", null, .unstaged);

    // 턴이 끝났다 — 그 순간의 작업트리를 굳힌다(에이전트 상태 전이가 부르는 바로 그 함수).
    // **신원을 먼저 심는다**(AT0): 링의 키가 provider 세션 신원이라, 신원 없이 부르면 제품이 아무것도
    // 찍지 않는다(그 계약은 아래 «신원이 없으면 찍지 않는다» 테스트가 따로 본다).
    // **실제 surface id 를 쓴다.** 예전에는 `1` 을 그대로 넘겼는데, 그때는 신원 게이트가 없어 어느 id 든
    // 통했다. 이제 그 id 의 Term 에서 신원을 찾으므로 **없는 id 를 넘기면 조용히 아무것도 안 찍힌다.**
    const turn_sid = tab_ops.activeTab(session).panes.items[0].terms.items[0].surfaceId();
    seedTurnIdentity(session, turn_sid);
    agent_ops.captureTurnSnapshot(session, turn_sid, .{ .key = "p-turn-1", .title = "다 했습니다" }, 0);
    var spins: usize = 0;
    while (spins < 500 and seededTurnRingLen(session) == 0) : (spins += 1) {
        git_ops.drainGitStatus(session);
        var ts: std.c.timespec = .{ .sec = 0, .nsec = 10 * std.time.ns_per_ms };
        _ = std.c.nanosleep(&ts, null);
    }
    try std.testing.expect(seededTurnRingLen(session) == 1);
    try std.testing.expect(seededTurnRing(session).?.latest().?.oid().len >= 40); // tree OID
    // **턴 키가 링까지 왕복한다**(계약 §3.1). 순수 층 test 는 `Ring.push` 만 보고, 이 단언은 그 값이
    // 요청 시점에 붙들려(`turn_snapshot_key`) 백엔드 왕복을 건너 수확 자리까지 살아 오는지를 본다 —
    // 배관에서 끊기면 순수 층은 여전히 green 이라 여기서만 드러난다.
    try std.testing.expectEqualStrings("p-turn-1", seededTurnRing(session).?.latest().?.turnKey());
    // 제목도 같은 붙들기 자리를 지나 링까지 온다(AT2).
    try std.testing.expectEqualStrings("다 했습니다", seededTurnRing(session).?.latest().?.titleText());

    // **세션 base 에는 직전 턴의 키가 붙지 않는다.** `Progress.reset()` 이 턴 키를 일부러 남기므로
    // (같은 턴의 다음 이벤트가 «키가 바뀌었다» 로 읽히면 안 된다) 캡처 자리가 그것을 그대로 넘기면
    // base 에 옛 키가 실린다 — `/clear` 뒤라면 **옛 세션의 키가 새 세션 base 에** 붙는다.
    git_backend_mod.testWriteFile(repo, "base.txt", "b\n") catch return error.SkipZigTest;
    agent_ops.captureTurnSnapshot(session, turn_sid, .{}, 0); // base 가 넘기는 값과 같다
    spins = 0;
    while (spins < 500 and seededTurnRingLen(session) < 2) : (spins += 1) {
        git_ops.drainGitStatus(session);
        var ts2: std.c.timespec = .{ .sec = 0, .nsec = 10 * std.time.ns_per_ms };
        _ = std.c.nanosleep(&ts2, null);
    }
    try std.testing.expectEqual(@as(usize, 2), seededTurnRingLen(session));
    try std.testing.expectEqual(@as(usize, 0), seededTurnRing(session).?.latest().?.turnKey().len);
    // 제목도 마찬가지다 — base 는 턴이 아니므로 직전 턴의 응답을 물려받지 않는다.
    try std.testing.expectEqual(@as(usize, 0), seededTurnRing(session).?.latest().?.titleText().len);

    // **가드를 직접 물어 본다.** 위 두 단언은 `captureTurnSnapshot` 을 빈 값으로 직접 부르므로
    // `turnFactsForCapture` 의 가드를 **지나지 않는다** — 그 가드를 지운 뮤턴트가 통과한다(AT1 에서 같은
    // 실패를 겪었다). `Progress.reset()` 이 턴 키를 일부러 남기므로, base 는 그 값을 **보고도** 빈 값을
    // 내야 한다.
    {
        const term = tab_ops.activeTab(session).panes.items[0].terms.items[0];
        var prompt: maru.session.agent_hook_event.Event = .{ .kind = .user_prompt_submit };
        prompt.turn_key = "p-live";
        _ = maru.session.agent_hook_mode.advance(&term.agent_hook_progress, .unknown, prompt);
        try std.testing.expectEqualStrings("p-live", term.agent_hook_progress.turnKey());
        // 턴 끝이면 그 키를 싣고,
        try std.testing.expectEqualStrings("p-live", agent_ops.turnFactsForCapture(term, true).key);
        // base 면 **같은 진행 상태를 보고도** 비운다.
        try std.testing.expectEqual(@as(usize, 0), agent_ops.turnFactsForCapture(term, false).key.len);
        try std.testing.expectEqual(@as(usize, 0), agent_ops.turnFactsForCapture(term, false).title.len);
    }
}

// [E1 §6.1] **트리거까지** 제품 경로로 몬다: 실제 claude 화면(실행 중 footer → 프롬프트 상자)을 term 코어에 흘려
// `pollAgentState`가 running → idle을 판정하고, 그 순간 스냅샷이 찍히는지 본다. 위 테스트가 "찍힌 뒤"를 보고
// 이 테스트가 "언제 찍는가"를 봐서, 에이전트 없이 §6.1 전 구간이 닫힌다.
test "AW1 훅이 blocked 여도 화면에 승인 chrome 이 없으면 배지가 풀린다 (§1.1 C1 · 제품 경로)" {
    // **순수 판정자로는 못 잡는 사슬을 본다**: 화면 판정 → `screen_visible_blocker` → 중재 → 배지.
    // 사용자가 보고한 「엔터를 눌러도 진행중으로 안 바뀐다」가 바로 이 사슬이다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const a = std.testing.allocator;
    const session = try a.create(AppSession);
    defer a.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), a, .{
        .abi_version = abi_version,
        .cols = 80,
        .rows = 24,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    const term = tab_ops.activeTab(session).activeTerm();
    term.agent_kind = .claude;
    term.rt.observation.availability = .current;
    // 훅 모드로 세운다(계약 §1.2 의 세 입력).
    session.loaded_config.config.sidebar.agent_hooks = true;
    term.agent_hook_log_present = true;
    try std.testing.expectEqual(maru.session.agent_hook_mode.Mode.hook, agent_ops.agentHookMode(session, term));
    const surface = session.term_backend.surfaceFor(term.rt.handle) orelse return error.SkipZigTest;

    // ① 승인 대기 — 훅이 그렇게 말했고 화면에도 그 chrome 이 있다.
    term.agent_hook_state = .blocked;
    try surface.core.write("\x1b[2J\x1b[H  Would you like to proceed?\r\n❯ 1. Yes\r\n  2. No\r\n");
    term.rt.observation.observer_generation +%= 1;
    agent_ops.pollAgentState(session, term, false);
    try std.testing.expect(term.agent_screen_visible_blocker);
    try std.testing.expectEqual(maru.session.agent_observer.State.blocked, term.agent_state);

    // ② 사용자가 승인했다. **훅은 그것을 모른다**(provider 가 해제 이벤트를 안 준다) — 훅 자리는 그대로
    //    `blocked` 다. 화면에서 chrome 이 사라지는 것이 유일한 근거이고, C1 이 그것으로 푼다.
    try surface.core.write("\r\n" ** 60);
    try surface.core.write("● 작업을 시작합니다\r\n  esc to interrupt\r\n");
    term.rt.observation.observer_generation +%= 1;
    agent_ops.pollAgentState(session, term, false);
    try std.testing.expect(!term.agent_screen_visible_blocker);
    try std.testing.expectEqual(maru.session.agent_observer.State.blocked, term.agent_hook_state); // 훅은 여전히
    try std.testing.expectEqual(maru.session.agent_observer.State.running, term.agent_state); // 배지는 풀렸다
    try std.testing.expectEqualStrings("C1", term.agent_state_rule);
    try std.testing.expectEqual(maru.session.agent_state_arbiter.Origin.screen, term.agent_state_origin);
}

test "AW3 훅 소스가 끊기면 훅 자리도 버린다 — 돌아왔을 때 낡은 값이 배지가 되지 않게 (§1.1)" {
    // `.observe` 분기는 진행 중 세부·작업 디렉터리·자식 셈을 버리는데 **훅 상태만 빠져 있었다.**
    // 남기면 훅 소스가 돌아온 순간 낡은 값이 그대로 배지가 된다 — 설정을 껐다 켜거나 로그가 사라졌다
    // 돌아오는 사이 에이전트가 턴을 끝냈어도 배지는 옛 `running` 이다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const a = std.testing.allocator;
    const session = try a.create(AppSession);
    defer a.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), a, .{
        .abi_version = abi_version,
        .cols = 80,
        .rows = 24,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    const term = tab_ops.activeTab(session).activeTerm();
    term.agent_kind = .claude;
    term.rt.observation.availability = .current;
    session.loaded_config.config.sidebar.agent_hooks = true;
    term.agent_hook_log_present = true;
    term.agent_hook_state = .running;
    term.agent_hook_progress.reset();

    // 훅 소스가 끊긴다(사용자가 게이트를 껐다 — 로그가 사라진 경우도 같은 분기다).
    session.loaded_config.config.sidebar.agent_hooks = false;
    agent_ops.pollAgentConsumer(session, term, false, true);
    try std.testing.expectEqual(maru.session.agent_hook_mode.Mode.observe, agent_ops.agentHookMode(session, term));
    try std.testing.expectEqual(maru.session.agent_observer.State.unknown, term.agent_hook_state);

    // 돌아온다. 낡은 `running` 이 살아나면 안 되고, 첫 훅 이벤트가 올 때까지는 화면이 답한다(§1.1 B0).
    session.loaded_config.config.sidebar.agent_hooks = true;
    try std.testing.expectEqual(maru.session.agent_hook_mode.Mode.hook, agent_ops.agentHookMode(session, term));
    const surface = session.term_backend.surfaceFor(term.rt.handle) orelse return error.SkipZigTest;
    try surface.core.write("\x1b[2J\x1b[H  작업이 끝났습니다\r\n\r\n❯ \r\n");
    term.rt.observation.observer_generation +%= 1;
    agent_ops.pollAgentState(session, term, false);
    try std.testing.expectEqual(maru.session.agent_observer.State.idle, term.agent_state);
    try std.testing.expectEqualStrings("B0", term.agent_state_rule);
}

test "AW2 훅이 running 에 멈춰도 화면 idle 이 연속 3회면 턴이 닫힌다 — 출력이 없어도 (§1.1 C2 · 제품 경로)" {
    // **generation 을 올리지 않는 것이 이 판정자의 요점이다.** codex 오류 턴은 훅이 running 에 멈춘 채
    // 화면만 idle 이고 **출력이 끊긴** 상태다. 예전 fast-path 는 정확히 그 상태를 「다시 볼 것 없다」로
    // 읽어 화면 관측을 얼렸고, C2 카운터가 1 에서 멈춰 **영영 안 닫혔다**(§9-10 이 안 닫힌 채였다).
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const a = std.testing.allocator;
    const session = try a.create(AppSession);
    defer a.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), a, .{
        .abi_version = abi_version,
        .cols = 80,
        .rows = 24,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    const term = tab_ops.activeTab(session).activeTerm();
    term.agent_kind = .codex;
    term.rt.observation.availability = .current;
    session.loaded_config.config.sidebar.agent_hooks = true;
    term.agent_hook_log_present = true;
    const surface = session.term_backend.surfaceFor(term.rt.handle) orelse return error.SkipZigTest;

    // 훅은 running 에 멈췄다(codex 오류 턴 — `Stop` 도 `StopFailure` 도 오지 않는다).
    term.agent_hook_state = .running;
    try surface.core.write("\x1b[2J\x1b[H  작업이 끝났습니다\r\n\r\n› \r\n  Context 2% used\r\n");
    term.rt.observation.observer_generation +%= 1;

    // 1회차 — 화면은 idle 이지만 훅을 아직 못 덮는다.
    agent_ops.pollAgentState(session, term, false);
    try std.testing.expect(term.agent_screen_visible_idle);
    try std.testing.expectEqual(maru.session.agent_observer.State.running, term.agent_state);
    try std.testing.expectEqualStrings("C2-pending", term.agent_state_rule);

    // 2회차·3회차 — **출력이 없으므로 generation 을 올리지 않는다.** 그래도 화면을 다시 읽어야 한다.
    agent_ops.pollAgentState(session, term, false);
    try std.testing.expectEqualStrings("C2-pending", term.agent_state_rule);
    agent_ops.pollAgentState(session, term, false);
    try std.testing.expectEqual(maru.session.agent_observer.State.idle, term.agent_state);
    try std.testing.expectEqualStrings("C2", term.agent_state_rule);
    try std.testing.expectEqual(maru.session.agent_observer.State.running, term.agent_hook_state); // 훅은 여전히

    // 닫힌 뒤에는 다시 건너뛴다 — 그 구간에만 더 본다(§1.1 C2 의 대가).
    const seq_after = term.agent_screen_seq;
    agent_ops.pollAgentState(session, term, false);
    try std.testing.expectEqual(seq_after, term.agent_screen_seq);
}

test "에이전트 화면이 running → idle이 되는 순간 작업트리가 굳는다" {
    // **이 테스트도 턴 스냅샷을 실제로 찍겠다고 밝힌다**(`test_allow_turn_snapshot`) — 링이 채워지는지
    // 보는 테스트라 게이트를 켜야 한다. 앞서 하나만 켜고 이 자리를 놓쳐 CI 가 빨개졌다.
    agent_ops.test_allow_turn_snapshot = true;
    defer agent_ops.test_allow_turn_snapshot = false;
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    var exe_buf: [std.fs.max_path_bytes]u8 = undefined;
    const git_exe = git_backend_mod.locate(&exe_buf) orelse return error.SkipZigTest;

    var cwd_buf: [std.fs.max_path_bytes]u8 = undefined;
    const cwd_ptr = std.c.getcwd(&cwd_buf, cwd_buf.len) orelse return error.SkipZigTest;
    const cwd = std.mem.span(@as([*:0]u8, @ptrCast(cwd_ptr)));
    var repo_buf: [std.fs.max_path_bytes]u8 = undefined;
    const repo = std.fmt.bufPrint(&repo_buf, "{s}/.zig-cache/tmp-session-turn-trigger", .{cwd}) catch return error.SkipZigTest;
    if (!git_backend_mod.testRunQuiet(&.{ "/bin/rm", "-rf", repo })) return error.SkipZigTest;
    defer _ = git_backend_mod.testRunQuiet(&.{ "/bin/rm", "-rf", repo });
    if (!git_backend_mod.testRunQuiet(&.{ git_exe, "init", "-q", "-b", "main", repo })) return error.SkipZigTest;
    git_backend_mod.testWriteFile(repo, "a.txt", "v1\n") catch return error.SkipZigTest;

    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 12,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    var opened_buf: [std.fs.max_path_bytes]u8 = undefined;
    try session.file_tree.recordOpened(try std.fmt.bufPrint(&opened_buf, "{s}/a.txt", .{repo}), repo);
    git_ops.rememberGitRepo(session, repo);

    const term = tab_ops.activeTab(session).activeTerm();
    term.agent_kind = .claude;
    // **신원이 있어야 링에 들어간다**(AT0). 제품에서는 훅 payload 가 이 값을 준다 — 관측 모드에서는
    // 대개 비어 있고, 그때 아무것도 안 찍히는 것이 계약이다(바로 아래 테스트가 그쪽을 본다).
    seedTurnIdentity(session, term.surfaceId());
    const surface = session.term_backend.surfaceFor(term.rt.handle) orelse return error.SkipZigTest;
    // 관측은 화면과 별개 경로(폴링)라 테스트에서 현재 상태로 둔다 — 여기서 보려는 것은 화면 판정이다.
    term.rt.observation.availability = .current;

    // ① 실행 중: 실행 footer가 보인다(실측 규칙 `working_footer`).
    try surface.core.write("\x1b[2J\x1b[H● 파일을 고치는 중\r\n  Working... esc to interrupt\r\n");
    term.rt.observation.observer_generation +%= 1;
    agent_ops.pollAgentState(session, term, false);
    try std.testing.expectEqual(maru.session.agent_observer.State.running, term.agent_state);
    try std.testing.expectEqual(@as(usize, 0), turnRingLenForTest(session)); // 아직 턴이 안 끝났다

    // ② 턴 종료: footer가 사라지고 입력 프롬프트만 남는다(실측 규칙 `live_prompt` — 수평선 + `❯ `).
    //    화면 지우기로는 부족하다. 판정은 **스크롤백을 포함한 최근 48행**을 보므로, 실제 에이전트가 그러듯
    //    출력이 흘러 지난 footer가 꼬리 밖으로 밀려나야 한다(안 밀면 지운 화면인데도 옛 footer가 계속 잡힌다).
    try surface.core.write("\r\n" ** 60);
    try surface.core.write("───────────────────────────────────────\r\n❯ \r\n");
    term.rt.observation.observer_generation +%= 1;
    agent_ops.pollAgentState(session, term, false);
    try std.testing.expectEqual(maru.session.agent_observer.State.idle, term.agent_state);

    var spins: usize = 0;
    while (spins < 500 and seededTurnRingLen(session) == 0) : (spins += 1) {
        git_ops.drainGitStatus(session);
        var ts: std.c.timespec = .{ .sec = 0, .nsec = 10 * std.time.ns_per_ms };
        _ = std.c.nanosleep(&ts, null);
    }
    try std.testing.expectEqual(@as(usize, 1), seededTurnRingLen(session));
    try std.testing.expectEqual(term.surfaceId(), seededTurnRing(session).?.latest().?.surface_id);
}

test "턴 스냅샷: 세션 신원이 없으면 링을 만들지 않는다 (AT0 — 관측 모드에는 이 기능이 없다)" {
    // 계약 §6.1: 링의 키가 provider 세션 신원이고, 신원을 확실히 알 수 없으면 **아무것도 말하지 않는다.**
    // 관측 모드에서 목록이 비는 이유가 이것이다 — 자식 프로세스 env 는 도구 실행 중에만 읽히고 폴링은
    // 1초라 짧은 도구를 대부분 놓친다. 추측으로 붙이면 틀린 세션에 남으므로 붙이지 않는다.
    agent_ops.test_allow_turn_snapshot = true;
    defer agent_ops.test_allow_turn_snapshot = false;
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    // **신원을 심지 않는다.** 그 밖의 조건은 앞 테스트와 같다.
    agent_ops.captureTurnSnapshot(session, 1, .{}, 0);

    // 링 자체가 만들어지지 않는다 — 빈 링이 생기는 것도 아니다(키가 없으므로 자리도 없다).
    try std.testing.expect(session.turn_rings.find(test_turn_session) == null);
    try std.testing.expectEqual(@as(usize, 0), session.turn_rings.len());
}

// [§2.6] 본문 우클릭 메뉴가 **native 경로로** 열리고, 항목마다 실행 주인이 갈리는지 본다. 화면 그리기는 이미 있는
// 메뉴 경로(터미널 본문·파일 트리와 공유)가 하므로 여기서는 항목·좌표·동작만 검증한다.
test "파일 본문 우클릭: 대상별 항목이 서고 실행 주인이 native/web으로 갈린다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 12,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    try tmp.dir.writeFile(session.io, .{ .sub_path = "doc.md", .data = "# 제목\n" });
    var tmp_buf: [std.fs.max_path_bytes]u8 = undefined;
    const tmp_root = tmp_buf[0..try tmp.dir.realPath(session.io, &tmp_buf)];
    const doc = try std.fs.path.join(allocator, &.{ tmp_root, "doc.md" });
    defer allocator.free(doc);
    try std.testing.expectEqual(AppSession.FilePanelOpenPathResult.opened, file_panel_ops.openFilePanelPath(session, doc));
    const entry = file_panel_ops.fileEntryForPath(session, doc).?;
    const surface_id = entry.surface_id;

    // 아직 배치된 적 없는 surface는 좌표를 만들 수 없다 — 열지 않는다(추측한 자리에 띄우지 않는다).
    try std.testing.expectError(error.Unsupported, settings_ops.openFileContentMenu(session, surface_id, .{
        .editor_epoch = 1,
        .x = 10,
        .y = 10,
        .target = .text,
        .has_selection = true,
        .href = "",
    }));

    // 지난 tick 레이아웃을 세워 준다(제품에서는 collectWebSurfaces가 채운다).
    try session.web_panel_prev.append(allocator, .{
        .surface_id = surface_id,
        .panel_kind = .markdown,
        .content_rect = .{ .x = 100, .y = 50, .w = 400, .h = 300 },
        .visible = true,
    });

    // 읽기 모드 + 링크: 링크 열기·주소 복사. 좌표는 rect 원점 + CSS px × backing scale이다.
    try settings_ops.openFileContentMenu(session, surface_id, .{
        .editor_epoch = 1,
        .x = 20,
        .y = 30,
        .target = .link,
        .has_selection = false,
        .href = "./other.md",
    });
    try std.testing.expect(session.file_content_menu != null);
    try std.testing.expectEqual(@as(usize, 2), session.context_menu_items_len);
    try std.testing.expectEqualStrings(maru.i18n.t(.ctx_open_link), session.context_menu_items_buf[0]);
    try std.testing.expectEqualStrings(maru.i18n.t(.ctx_copy_link), session.context_menu_items_buf[1]);
    const scale = @max(@as(u32, 1), session.scale_milli);
    try std.testing.expectEqual(@as(i32, @intCast(100 + 20 * scale / 1000)), session.chrome_host.context_menu.anchor_x);
    try std.testing.expectEqual(@as(i32, @intCast(50 + 30 * scale / 1000)), session.chrome_host.context_menu.anchor_y);

    // 주소 복사는 native가 실행한다 — OSC 52 write와 같은 drain 큐에 들어간다(web으로 안 넘어간다).
    session.chrome_host.context_menu.selected = 1;
    settings_ops.acceptContextMenu(session);
    try std.testing.expectEqualStrings("./other.md", session.chrome_clipboard_write);
    try std.testing.expect(session.file_content_menu == null); // 실행 후 메뉴가 닫힌다
    try std.testing.expect(settings_ops.takeFileMenuAction(session) == null);

    // 읽기 모드 + 본문(선택 있음): 복사·전체 선택. 둘 다 선택에 붙어 web이 실행한다.
    try settings_ops.openFileContentMenu(session, surface_id, .{
        .editor_epoch = 1,
        .x = 0,
        .y = 0,
        .target = .text,
        .has_selection = true,
        .href = "",
    });
    try std.testing.expectEqual(@as(usize, 2), session.context_menu_items_len);
    try std.testing.expectEqualStrings(maru.i18n.t(.ctx_copy), session.context_menu_items_buf[0]); // session/content_menu.zig 소유 — I3d 가 옮긴다
    session.chrome_host.context_menu.selected = 0;
    settings_ops.acceptContextMenu(session);
    const action = settings_ops.takeFileMenuAction(session).?;
    try std.testing.expectEqual(surface_id, action.surface_id);
    try std.testing.expectEqual(maru.session.content_menu.Item.copy, action.item);
    try std.testing.expect(settings_ops.takeFileMenuAction(session) == null); // 1회성
    // 포커스를 그 문서로 돌려준다 — 안 그러면 이어지는 ⌘Z·타이핑이 편집기까지 못 간다.
    try std.testing.expectEqual(surface_id, session.takePendingDockFocusAction().?);

    // 읽기 모드 + 여백의 "소스 모드로 열기"는 헤더 선택기와 **같은 경로**로 모드를 옮긴다.
    try settings_ops.openFileContentMenu(session, surface_id, .{
        .editor_epoch = 1,
        .x = 0,
        .y = 0,
        .target = .empty,
        .has_selection = false,
        .href = "",
    });
    try std.testing.expectEqualStrings(maru.i18n.t(.ctx_open_source_mode), session.context_menu_items_buf[1]);
    session.chrome_host.context_menu.selected = 1;
    settings_ops.acceptContextMenu(session);
    try std.testing.expectEqual(dock_panel.Mode.source_edit, session.filePanelMode(surface_id).?);

    // 소스 모드가 되면 같은 여백에서 붙여넣기가 생기고 "소스 모드로 열기"는 사라진다(갈 곳이 자기 자신이다).
    try settings_ops.openFileContentMenu(session, surface_id, .{
        .editor_epoch = 1,
        .x = 0,
        .y = 0,
        .target = .empty,
        .has_selection = false,
        .href = "",
    });
    try std.testing.expectEqual(@as(usize, 2), session.context_menu_items_len);
    try std.testing.expectEqualStrings(maru.i18n.t(.ctx_paste), session.context_menu_items_buf[0]); // session/content_menu.zig 소유 — I3d 가 옮긴다
    try std.testing.expectEqualStrings(maru.i18n.t(.ctx_select_all), session.context_menu_items_buf[1]);
    settings_ops.closeContextMenu(session);

    // 파일 본문이 아닌 surface는 메뉴도 클립보드 쓰기도 못 연다.
    try std.testing.expectError(error.Unsupported, settings_ops.openFileContentMenu(session, surface_id + 999, .{
        .editor_epoch = 1,
        .x = 0,
        .y = 0,
        .target = .text,
        .has_selection = false,
        .href = "",
    }));
}

// [§2.6] 본문 메뉴가 떠 있는 동안 **웹뷰가 포커스를 지킨다**. 안 그러면 WebKit이 선택을 안 그려 사용자가 방금
// 겨냥한 블록이 우클릭하는 순간 사라진다. 다른 모달이 함께 열리면 그쪽이 이겨야 한다(키가 Zig로 가야 동작한다).
test "파일 본문 메뉴는 웹뷰 포커스를 뺏지 않는다(다른 모달은 그대로 뺏는다)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 12,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // 평소 컨텍스트 메뉴(터미널 본문)는 그대로 터미널이 입력을 가져간다.
    session.chrome_host.context_menu.show(10, 10, 2);
    session.terminal_context_menu = true;
    try std.testing.expect(session.terminalOwnsInput());
    settings_ops.closeContextMenu(session);

    // 파일 본문 메뉴는 예외다.
    session.file_content_menu = .{ .surface_id = 7, .editor_epoch = 1, .len = 2 };
    session.chrome_host.context_menu.show(10, 10, 2);
    try std.testing.expect(!session.terminalOwnsInput());

    // 다른 모달이 함께 열리면 그쪽이 이긴다.
    session.chrome_host.palette.open = true;
    try std.testing.expect(session.terminalOwnsInput());
    session.chrome_host.palette.open = false;
    settings_ops.closeContextMenu(session);
    try std.testing.expect(!session.terminalOwnsInput()); // 메뉴가 닫혔고 다른 것도 없다
}

test "SessionDock published tree dispatches hover/down/up once and rejects a reconciled stale up" {
    const entries = [_]chrome.ui.tree.RectEntry{.{
        .id = 0x5344_1000,
        .parent_index = null,
        .kind = .card,
        .rect = .{ .x = 10, .y = 20, .width = 80, .height = 40 },
        .effective_clip = .{ .x = 10, .y = 20, .width = 80, .height = 40 },
        .action = .{ .id = 6 },
        .visual = .{ .card = .{ .variant = .surface, .paint = .{} } },
    }};
    const actions = [_]chrome.components.session_dock.ids.Entry{.{
        .action_id = 6,
        .snapshot_generation = 9,
        .intent = .{ .select_card = 42 },
    }};
    var state = chrome.ui.interaction.InteractionState{};

    const hover = agent_dock.dispatchAgentSessionDockPointer(&state, &entries, &actions, 9, .{
        .phase = .move,
        .x_px = 20,
        .y_px = 30,
        .timestamp_ns = 1,
    }).?;
    try std.testing.expect(hover.intent == null);
    try std.testing.expect(hover.visual_changed);
    try std.testing.expectEqual(@as(?chrome.ui.tree.UiId, entries[0].id), state.hovered);

    const down = agent_dock.dispatchAgentSessionDockPointer(&state, &entries, &actions, 9, .{
        .phase = .down,
        .x_px = 20,
        .y_px = 30,
        .timestamp_ns = 2,
    }).?;
    try std.testing.expect(down.intent == null); // press alone never opens an inline disclosure
    try std.testing.expect(state.capture != null);

    // Capture deliberately owns the matching up even outside the card, while the same published
    // action table still maps it to the original archive identity.
    const up = agent_dock.dispatchAgentSessionDockPointer(&state, &entries, &actions, 9, .{
        .phase = .up,
        .x_px = 900,
        .y_px = 900,
        .timestamp_ns = 3,
    }).?;
    try std.testing.expectEqual(@as(?chrome.components.session_dock.ids.Intent, .{ .select_card = 42 }), up.intent);
    try std.testing.expect(state.capture == null);

    _ = agent_dock.dispatchAgentSessionDockPointer(&state, &entries, &actions, 9, .{
        .phase = .down,
        .x_px = 20,
        .y_px = 30,
        .timestamp_ns = 4,
    }).?;
    _ = try chrome.ui.interaction.reconcile(&state, .{ .entries = &entries }, .{ .entries = &entries });
    const stale_up = agent_dock.dispatchAgentSessionDockPointer(&state, &entries, &actions, 9, .{
        .phase = .up,
        .x_px = 20,
        .y_px = 30,
        .timestamp_ns = 5,
    }).?;
    try std.testing.expect(stale_up.intent == null);

    const changed_actions = [_]chrome.components.session_dock.ids.Entry{.{
        .action_id = 6,
        .snapshot_generation = 9,
        .intent = .{ .select_card = 99 },
    }};
    try std.testing.expect(agent_dock.agentSessionDockFrameEql(&entries, &actions, &entries, &actions));
    try std.testing.expect(!agent_dock.agentSessionDockFrameEql(&entries, &actions, &entries, &changed_actions));
}

test "archive smoke probe returns only the pointer-hittable clipped capability rect" {
    const entry = chrome.ui.tree.RectEntry{
        .id = 1,
        .parent_index = null,
        .kind = .card,
        .rect = .{ .x = 10, .y = 20, .width = 80, .height = 40 },
        .effective_clip = .{ .x = 30, .y = 25, .width = 25, .height = 20 },
        .action = .{ .id = 1 },
        .visual = .{ .card = .{ .variant = .surface, .paint = .{} } },
    };
    try std.testing.expectEqual(chrome.ui.layout.UiRect{ .x = 30, .y = 25, .width = 25, .height = 20 }, AppSession.smokeProbeVisibleRect(entry).?);

    var hidden = entry;
    hidden.effective_clip = .{ .x = 100, .y = 100, .width = 1, .height = 1 };
    try std.testing.expect(AppSession.smokeProbeVisibleRect(hidden) == null);
}

// ── 진행 중 pointer gesture vs 에이전트 세션 도크 분기 ──────────────────────────────────────────
// `mouse()`의 도크 분기는 rect 판정만으로 move/up을 소비하고 return한다. 그 분기가 모든
// `pointerGestureIs(...)` 분기보다 위에 있어, 도크가 열린 채로 divider·탭·pane·사이드바 카드·
// 스크롤바를 끌다 포인터가 도크 content 위로 들어가면 그 gesture가 이벤트를 잃었다(끌던 것이 멈추고,
// up도 도크가 먹어 owner가 armed로 남았다). 아래 5개는 다섯 gesture 각각에서 "도크 위를 지나도
// 소유권이 유지되고 up이 owner를 푼다"를 고정한다 — 옛 동작이면 전부 red다.
// 단일 출처: docs/chrome-interaction-migration.md §2.

/// 아카이브 worker를 띄우지 않고 오른쪽 에이전트 세션 도크만 연다(레이아웃/라우팅 격리 —
/// `automatic agent sessions dock width` 테스트와 같은 규율).
fn openAgentSessionsDockForRouting(session: *AppSession, side: dock_panel.Side) void {
    session.dock.presented = true;
    session.dock.collapsed = false;
    session.dock.side = side;
    session.dock.size = 0;
    session.agent_session_archive_initialized = false;
    dock_ops.setDockView(session, .agent_sessions);
    session.agent_session_archive_initialized = true;
    for (session.tabs.items) |tab| pane_ops.resizeTabPanes(session, tab);
    pane_ops.recomputeActivePaneRect(session);
}

fn initDockedRoutingSession(allocator: std.mem.Allocator, side: dock_panel.Side) !*AppSession {
    const session = try allocator.create(AppSession);
    errdefer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    errdefer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(1600, 900, 1000);
    openAgentSessionsDockForRouting(session, side);
    return session;
}

/// 도크 content 중앙 — 진행 중 gesture가 지나가더라도 도크로 새면 안 되는 좌표.
fn dockContentCenter(session: *AppSession) struct { x: f64, y: f64 } {
    const content = dock_ops.dockGeometry(session).tree_content;
    return .{
        .x = @floatFromInt(content.x + content.w / 2),
        .y = @floatFromInt(content.y + content.h / 2),
    };
}

test "divider capture는 split이 사라지면 carry verdict가 취소한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    // 3 pane: split{P0, split{P1, P2}}. 안쪽 divider를 잡고 그 split을 없앤다.
    try pane_ops.splitActivePane(session, .horizontal);
    try pane_ops.splitActivePane(session, .horizontal);
    var segs: std.ArrayList(PaneTree.DividerSeg) = .empty;
    defer segs.deinit(allocator);
    try pane_ops.layoutActiveTabDividers(session, &segs);
    try std.testing.expectEqual(@as(usize, 2), segs.items.len);

    // 활성 pane(P2)이 속한 안쪽 split의 divider를 찾는다.
    var inner_index: usize = 0;
    for (segs.items, 0..) |seg, i| {
        if (seg.split != switch (tab_ops.activeTab(session).tree) {
            .split => |sp| sp,
            .leaf => return error.TestExpectedSplit,
        }) inner_index = i;
    }
    const inner = segs.items[inner_index];
    const div_x: f64 = @floatFromInt(inner.pos);
    const div_y: f64 = @floatFromInt(inner.bounds.y + inner.bounds.h / 2);

    session.mouse(1, div_x, div_y, 0, 0);
    try std.testing.expect(pane_ops.dividerCaptureActive(session));
    try std.testing.expect(session.divider_capture_split == inner.split);

    // 드래그 중에 그 split이 collapse된다(단축키 close 등 외부 구조 변경).
    pane_ops.closeActivePane(session);
    try std.testing.expect(!pane_ops.dividerCaptureActive(session));

    // 이후 move는 아무 것도 끌지 않는다 — 사라진 대상 위에서 resize가 계속되면 안 된다.
    session.mouse(2, div_x - 100, div_y, 0, 0);
    _ = try session.tick();
    try std.testing.expect(!pane_ops.dividerCaptureActive(session));
}

test "드래그 중 탭이 바뀌면 carry verdict가 divider capture를 끊는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);
    try pane_ops.splitActivePane(session, .horizontal);

    var segs: std.ArrayList(PaneTree.DividerSeg) = .empty;
    defer segs.deinit(allocator);
    try pane_ops.layoutActiveTabDividers(session, &segs);
    const seg = segs.items[0];
    const split = seg.split;
    const div_x: f64 = @floatFromInt(seg.pos);
    const div_y: f64 = @floatFromInt(seg.bounds.y + seg.bounds.h / 2);

    session.mouse(1, div_x, div_y, 0, 0);
    try std.testing.expect(pane_ops.dividerCaptureActive(session));
    const ratio_at_capture = split.ratio;

    // 드래그 도중 키보드로 다른 탭을 연다. split은 그대로 살아 있으므로 구조 무효화 경로는 아무
    // 일도 하지 않는다 — 이 경우를 잡는 것은 §5 carry verdict의 owner epoch뿐이다.
    _ = try tab_ops.newTab(session);
    try std.testing.expect(session.tabs.items.len == 2);

    session.mouse(2, div_x - 200, div_y, 0, 0);
    _ = try session.tick();

    // capture가 끊기고, 보이지도 않는 탭의 split이 조용히 resize되지 않는다.
    try std.testing.expect(!pane_ops.dividerCaptureActive(session));
    try std.testing.expectEqual(ratio_at_capture, split.ratio);
}

test "divider probe는 move 수가 아니라 tick 수만큼 resize했음을 드러낸다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);
    try pane_ops.splitActivePane(session, .horizontal);

    var segs: std.ArrayList(PaneTree.DividerSeg) = .empty;
    defer segs.deinit(allocator);
    try pane_ops.layoutActiveTabDividers(session, &segs);
    const seg = segs.items[0];
    const div_x: f64 = @floatFromInt(seg.pos);
    const div_y: f64 = @floatFromInt(seg.bounds.y + seg.bounds.h / 2);

    // 발행된 밴드는 실제로 잡히는 자리와 같다 — probe가 렌더와 다른 rect를 내면 E2E가 헛좌표를 누른다.
    const before = session.dividerSmokeProbe();
    try std.testing.expect(before.present);
    try std.testing.expect(!before.capture_active);
    try std.testing.expect(div_x >= @as(f64, @floatFromInt(before.x_px)));
    try std.testing.expect(div_x < @as(f64, @floatFromInt(before.x_px)) + @as(f64, @floatFromInt(before.width_px)));

    session.mouse(1, div_x, div_y, 0, 0);
    try std.testing.expect(session.dividerSmokeProbe().capture_active);

    // 한 프레임 안에서 move 다섯 번. tick은 한 번.
    var step: f64 = 0;
    while (step < 5) : (step += 1) session.mouse(2, div_x - 40 - step * 20, div_y, 0, 0);
    _ = try session.tick();

    const after = session.dividerSmokeProbe();
    try std.testing.expectEqual(@as(u64, 5), after.move_events);
    // 계약 §4.3의 상한이 move 수가 아니라는 것을 이 부등식 하나가 증명한다. ratio 값만 보는
    // fixture는 다섯 번 적용됐는지 한 번 적용됐는지 구분하지 못한다.
    try std.testing.expectEqual(@as(u64, 1), after.resize_applications);
    try std.testing.expect(after.ratio_milli != before.ratio_milli);

    session.mouse(3, div_x - 140, div_y, 0, 0);
    try std.testing.expect(!session.dividerSmokeProbe().capture_active);
}

test "divider capture와 PointerGestureOwner는 같은 stream에 공존하지 않는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);
    try pane_ops.splitActivePane(session, .horizontal);

    var segs: std.ArrayList(PaneTree.DividerSeg) = .empty;
    defer segs.deinit(allocator);
    try pane_ops.layoutActiveTabDividers(session, &segs);
    const seg = segs.items[0];
    const div_x: f64 = @floatFromInt(seg.pos);
    const div_y: f64 = @floatFromInt(seg.bounds.y + seg.bounds.h / 2);

    session.mouse(1, div_x, div_y, 0, 0);
    try std.testing.expect(pane_ops.dividerCaptureActive(session));
    // divider가 capture를 들고 있는 동안 owner union은 비어 있어야 한다. 두 권위가 겹치면
    // 어느 쪽이 이 stream을 소유하는지 이벤트마다 달라진다(이관 계약 §4.3).
    try std.testing.expect(session.pointerGestureIs(.none));

    // 반대 방향: 다른 gesture가 시작되면 divider capture가 끝난다.
    session.beginPointerGesture(.{ .scrollbar = .{ .grab = 0 } });
    try std.testing.expect(!pane_ops.dividerCaptureActive(session));
    try std.testing.expect(session.divider_capture_split == null);
}

test "라이브 divider 드래그는 도크 위를 지나도 ratio를 계속 추적하고 up에서 풀린다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initDockedRoutingSession(allocator, .right);
    defer allocator.destroy(session);
    defer session.deinit();
    try std.testing.expect(dock_ops.dockVisible(session));

    try pane_ops.splitActivePane(session, .horizontal);
    var segs: std.ArrayList(PaneTree.DividerSeg) = .empty;
    defer segs.deinit(allocator);
    try pane_ops.layoutActiveTabDividers(session, &segs);
    const seg = segs.items[0];
    const split = seg.split;
    const div_x: f64 = @floatFromInt(seg.pos);
    const div_y: f64 = @floatFromInt(seg.bounds.y + seg.bounds.h / 2);

    session.mouse(1, div_x, div_y, 0, 0);
    try std.testing.expect(pane_ops.dividerCaptureActive(session));
    session.mouse(2, div_x - 200, div_y, 0, 0);
    _ = try session.tick();
    const ratio_outside = split.ratio;

    // 도크 content 위로 이동 — clamp가 아니라 이벤트 미도달로 얼어붙던 자리다. divider bounds가 도크
    // 왼쪽에서 끝나므로 ratio는 상한으로 가야 하고, 직전 값 그대로면 도크가 move를 가로챈 것이다.
    const dock_center = dockContentCenter(session);
    session.mouse(2, dock_center.x, dock_center.y, 0, 0);
    _ = try session.tick();
    try std.testing.expect(split.ratio != ratio_outside);
    try std.testing.expect(pane_ops.dividerCaptureActive(session));
    try std.testing.expect(session.agent_session_dock_interaction.capture == null);

    session.mouse(3, dock_center.x, dock_center.y, 0, 0);
    try std.testing.expect(!pane_ops.dividerCaptureActive(session));
    _ = try session.tick();
}

test "라이브 Term 탭 드래그는 도크 위를 지나도 좌표를 계속 받고 up에서 풀린다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initDockedRoutingSession(allocator, .right);
    defer allocator.destroy(session);
    defer session.deinit();

    try pane_ops.newTermInActivePane(session); // 탭 2개 — 탭 세그먼트가 생긴다
    var lr: std.ArrayList(PaneTree.LeafRect) = .empty;
    defer lr.deinit(allocator);
    try tab_ops.activeTabLeafRects(session, allocator, session.termRect(), &lr);
    const pb = pane_ops.paneBar(session, lr.items[0].rect, lr.items[0].leaf).?;
    const tab_x: f64 = @floatFromInt(pb.tabs.x + 2);
    const tab_y: f64 = @floatFromInt(pb.full.y + 1);

    session.mouse(1, tab_x, tab_y, 0, 0);
    try std.testing.expect(session.pointerGestureIs(.terminal_tab));

    // drag(2)는 owner의 마지막 좌표를 갱신한다. 도크가 가로채면 그 값이 down 좌표에 머문다.
    const dock_center = dockContentCenter(session);
    session.mouse(2, dock_center.x, dock_center.y, 0, 0);
    try std.testing.expect(session.pointerGestureIs(.terminal_tab));
    try std.testing.expectEqual(dock_center.x, session.pointer_gesture_owner.terminal_tab.x);
    try std.testing.expect(session.agent_session_dock_interaction.capture == null);

    session.mouse(3, dock_center.x, dock_center.y, 0, 0);
    try std.testing.expect(!session.pointerGestureIs(.terminal_tab));
    _ = try session.tick();
}

