test "CR0b AppHost incident ABI prerequisite는 active lease timeout을 detached backing으로 보존한다" {
    if (!is_macos) return error.SkipZigTest;
    var directory = try AppSession.incidentBootstrapTestDirectory();
    defer directory.dir.cleanup();
    defer _ = std.c.close(directory.fd);
    try AppSession.beginIncidentBootstrapTest(directory.fd);
    defer AppSession.endIncidentBootstrapTest();
    var session: AppSession = undefined;
    session.ensureRemoteBackend();
    const runtime = app_process_incident_owner.runtime.?;
    var lease: session_host.incident_publisher_registry.IncidentPublisherLease = .{};
    try app_process_incident_owner.registry.acquire(&lease);
    var started_ts: std.c.timespec = undefined;
    try std.testing.expectEqual(@as(c_int, 0), std.c.clock_gettime(.MONOTONIC, &started_ts));
    const started = @as(i128, started_ts.sec) * 1000 + @divFloor(@as(i128, started_ts.nsec), 1_000_000);
    try std.testing.expectEqual(
        IncidentOwnerTerminationOutcome.detached,
        shutdownProcessIncidentOwner(),
    );
    var ended_ts: std.c.timespec = undefined;
    try std.testing.expectEqual(@as(c_int, 0), std.c.clock_gettime(.MONOTONIC, &ended_ts));
    const ended = @as(i128, ended_ts.sec) * 1000 + @divFloor(@as(i128, ended_ts.nsec), 1_000_000);
    const elapsed = ended - started;
    try std.testing.expect(elapsed >= 200 and elapsed < 2_000);
    try std.testing.expect(app_process_incident_owner.runtime == runtime);
    try std.testing.expectEqual(@as(u64, 1), app_process_incident_owner.registry.active_lease_count);
    try std.testing.expectEqual(
        IncidentOwnerTerminationOutcome.inactive,
        shutdownProcessIncidentOwner(),
    );
    // ABI는 one-shot이지만 test process는 계속되므로 preserved backing을 owner API로 명시 정산한다.
    try app_process_incident_owner.registry.release(&lease);
    try std.testing.expectEqual(
        session_host.app_process_incident_owner.TerminationOutcome.joined,
        app_process_incident_owner.shutdownForTermination(),
    );
}

// `ui.language` 가 실제 화면 문자열까지 도달하는지 본다.
//
// **이 테스트가 없어서 회귀를 놓쳤다.** I3a 슬라이스 1~5 가 185 건을 키로 옮기는 동안 화면은 이미
// 영어로 나오고 있었는데(배선이 없어 초기값이 곧 화면 언어였다), 전환 무결성 검증은 "키가 내는 문장 ==
// 원본 리터럴"만 봤지 **그 키를 어느 언어로 푸는지**는 보지 않았다. 폭을 재는 가드레일 하나가 우연히
// 잡았을 뿐이다. 여기서는 설정값 → 표시 문자열까지 이어서 본다.
test "ui.language: 설정값이 확인 모달 문장의 언어를 정한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    const lang_before = maru.i18n.lang();
    defer maru.i18n.setLang(lang_before);

    session.loaded_config.config.ui_language = .ko;
    settings_ops.reapplyUiLanguage(session);
    session.showConfirm(.app_close_running, .active_term);
    try std.testing.expectEqualStrings(
        maru.i18n.tIn(.ko, .app_close_running),
        session.chrome_host.confirm.message,
    );

    session.loaded_config.config.ui_language = .en;
    settings_ops.reapplyUiLanguage(session);
    session.showConfirm(.app_close_running, .active_term);
    try std.testing.expectEqualStrings(
        maru.i18n.tIn(.en, .app_close_running),
        session.chrome_host.confirm.message,
    );

    // 두 언어가 실제로 다른 문장이어야 이 테스트가 무언가를 지킨다 — 같으면 위 두 단언이 동시에
    // 참이라 언어 전환이 죽어 있어도 통과한다.
    try std.testing.expect(!std.mem.eql(
        u8,
        maru.i18n.tIn(.ko, .app_close_running),
        maru.i18n.tIn(.en, .app_close_running),
    ));
}

// `auto` 는 OS 로케일을 따른다 — platform 이 넘긴 문자열을 중립 층이 판정하는 경로 전체를 본다.
test "ui.language=auto: 주입한 로케일이 화면 언어를 정한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    const lang_before = maru.i18n.lang();
    defer maru.i18n.setLang(lang_before);
    // 로케일도 프로세스 전역이라 되돌린다 — 안 비우면 뒤에 도는 테스트가 여기서 넣은 `ko-KR` 을 물려받아
    // **순서에 따라 결과가 달라진다**. 테스트 환경에는 원래 값이 없으므로(Swift 가 안 부른다) 비우면 된다.
    defer maru.i18n.setOsLocale("");

    session.loaded_config.config.ui_language = .auto;

    // Swift 가 `maru_macos_app_set_ui_locale` 로 넣는 것과 같은 값이다(해석은 중립 층이 한다).
    maru.i18n.setOsLocale("ko-KR");
    settings_ops.reapplyUiLanguage(session);
    session.showConfirm(.app_close_running, .active_term);
    try std.testing.expectEqualStrings(
        maru.i18n.tIn(.ko, .app_close_running),
        session.chrome_host.confirm.message,
    );

    maru.i18n.setOsLocale("en-US");
    settings_ops.reapplyUiLanguage(session);
    session.showConfirm(.app_close_running, .active_term);
    try std.testing.expectEqualStrings(
        maru.i18n.tIn(.en, .app_close_running),
        session.chrome_host.confirm.message,
    );
}

// 탐색기 헤더의 동작 버튼(새로 고침·전체 접기). 자리·클릭·결과를 한 테스트가 잇는다 — 셋이 갈라지면
// "보이는데 안 눌리는" 버튼이 되고, 그것은 사용자가 버그로 보고할 때까지 아무 게이트도 못 잡는다.
test "탐색기 헤더 동작: 오른쪽 끝 버튼이 전체 접기·새로 고침을 실제로 돌린다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    const launcher = file_panel_ops.filePanelDockControlRect(session) orelse return error.MissingDockLauncher;
    session.mouse(1, @floatFromInt(launcher.x + 1), @floatFromInt(launcher.y + 1), 0, 0);
    _ = session.takeFilePanelPickRequest();
    dock_ops.setDockView(session, .explorer);
    const dg = dock_ops.dockGeometry(session);
    if (dg.view_bar.h == 0) return error.SkipZigTest; // 바가 접힌 형상은 이 계약의 대상이 아니다

    // 펼친 폴더가 있는 트리를 만든다.
    try session.file_tree.replaceExplicitRoots(&.{"/w"});
    while (session.file_tree.takeScanRequest()) |owned| allocator.free(owned);
    try session.file_tree.applySnapshot("/w", &.{
        .{ .name = "src", .kind = .directory },
        .{ .name = "a.txt", .kind = .file },
    });
    _ = try session.file_tree.toggleDirectory("/w/src");
    while (session.file_tree.takeScanRequest()) |owned| allocator.free(owned);
    // 상태는 **행 투영**으로 본다 — 사용자가 보는 것과 같은 값이고, 내부 노드를 들여다보면 투영이 깨져도
    // 테스트는 통과한다.
    try std.testing.expect(try dirExpandedInRows(session, "/w/src"));

    // 동작 버튼 자리를 chrome 기하에서 얻는다 — 테스트가 좌표를 손으로 만들면 **그린 자리와 다른 곳**을
    // 눌러 놓고 통과할 수 있다(그 어긋남이 정확히 이 기능의 위험이다).
    const actions = dock_ops.dockActions(session);
    try std.testing.expectEqual(@as(usize, 2), actions.len);
    const bar = dock_view_bar.Rect{ .x = dg.view_bar.x, .y = dg.view_bar.y, .w = dg.view_bar.w, .h = dg.view_bar.h };
    const collapse_index = for (actions, 0..) |a, i| {
        if (a == .collapse_all) break i;
    } else return error.MissingCollapseAction;
    const slot = dock_view_bar.actionRect(bar, session.cell_width_px, actions.len, collapse_index) orelse
        return error.SkipZigTest; // 도크가 좁아 동작을 안 그리는 형상
    const cx: f64 = @floatFromInt(slot.x + slot.w / 2);
    const cy: f64 = @floatFromInt(slot.y + slot.h / 2);

    // 그 자리는 **뷰 전환이 아니다** — 두 판정이 같은 좌표를 두고 다투면 누를 때마다 뷰가 바뀐다.
    try std.testing.expect(dock_ops.dockViewSlotAt(session, cx, cy) == null);
    try std.testing.expectEqual(collapse_index, dock_ops.dockActionAt(session, cx, cy).?);

    // 클릭 → 접힌다(뷰는 그대로다).
    session.mouse(1, cx, cy, 0, 0);
    try std.testing.expect(!try dirExpandedInRows(session, "/w/src"));
    try std.testing.expectEqual(dock_panel.View.explorer, session.dock.view);

    // 새로 고침 → 루트 스캔이 예약된다(그 전에는 큐가 비어 있다).
    try std.testing.expect(session.file_tree.takeScanRequest() == null);
    const refresh_index = for (actions, 0..) |a, i| {
        if (a == .refresh) break i;
    } else return error.MissingRefreshAction;
    const rslot = dock_view_bar.actionRect(bar, session.cell_width_px, actions.len, refresh_index).?;
    session.mouse(1, @floatFromInt(rslot.x + rslot.w / 2), @floatFromInt(rslot.y + rslot.h / 2), 0, 0);
    const queued = session.file_tree.takeScanRequest() orelse return error.MissingScanRequest;
    defer allocator.free(queued);
    try std.testing.expectEqualStrings("/w", queued);
}

/// 투영된 행에서 그 디렉터리가 펼쳐져 있는지. 없으면 error 라 "행이 사라져서 통과"하는 경우를 막는다.
fn dirExpandedInRows(session: *AppSession, path: []const u8) !bool {
    session.file_tree_rows_dirty = true;
    try file_panel_ops.updateFileTree(session);
    for (session.file_tree_rows.items) |row| switch (row) {
        .directory => |d| if (std.mem.eql(u8, d.path, path)) return d.expanded,
        else => {},
    };
    return error.MissingDirectoryRow;
}

test "CR5d-2 actual AppSession Window 이동은 stale close를 거부하고 fresh close만 inventory로 보낸다" {
    if (!is_macos) return error.SkipZigTest;

    const Fixture = struct {
        fn appendRemoteTerm(
            session: *AppSession,
            backend: *RemoteSessionBackend,
            handle: u64,
            tab_index: usize,
        ) !*Term {
            const surface = RemoteSessionBackend.testing_api.cr5d2WindowSurface(backend, handle) orelse
                return error.TestUnexpectedResult;
            const term = try session.allocator.create(Term);
            errdefer session.allocator.destroy(term);
            term.* = .{};
            term.surface = surface;
            term.rt.handle = handle;
            term.rt.live_initialized = true;
            try session.tabs.items[tab_index].panes.items[0].terms.append(session.allocator, term);
            return term;
        }

        // The CR5 host fixture owns these RemoteRuntime/Surface values. Sibling AppSession wrappers
        // are removed without touching that owner; the target wrapper is retired by the product
        // abandon suffix and therefore is deliberately absent here.
        fn discardSiblingWrapper(session: *AppSession, handle: u64) !void {
            for (session.tabs.items) |tab| for (tab.panes.items) |pane| {
                for (pane.terms.items, 0..) |term, index| {
                    if (term.rt.handle != handle or term.surface.remote == null) continue;
                    const removed = pane.terms.orderedRemove(index);
                    if (removed.git_branch) |value| session.allocator.free(value);
                    if (removed.git_branch_cwd) |value| session.allocator.free(value);
                    removed.auto_title.deinit(session.allocator);
                    removed.rt.observation.deinit(session.allocator);
                    if (removed.rt.ended_command.len != 0) session.allocator.free(removed.rt.ended_command);
                    if (removed.rt.ended_runtime_host_id.len != 0)
                        session.allocator.free(removed.rt.ended_runtime_host_id);
                    if (removed.rt.ended_runtime_id.len != 0) session.allocator.free(removed.rt.ended_runtime_id);
                    session.allocator.destroy(removed);
                    return;
                }
            };
            return error.TestUnexpectedResult;
        }

        fn closeSnapshot(
            backend: *RemoteSessionBackend,
            handle: u64,
        ) !session_host.remote_runtime.testing_api.CloseSnapshot {
            const runtime = RemoteSessionBackend.testing_api.cr5d2WindowRuntime(backend, handle) orelse
                return error.TestUnexpectedResult;
            return session_host.remote_runtime.testing_api.closeSnapshot(runtime);
        }

        fn appendForeignHostTerm(
            session: *AppSession,
            remote_source: maru.session.surface.ScreenSource,
            handle: u64,
            surface_id: u64,
        ) !*maru.session.Surface {
            const surface = try session.allocator.create(maru.session.Surface);
            errdefer session.allocator.destroy(surface);
            surface.* = try maru.session.Surface.init(session.allocator, surface_id, .{ .cols = 80, .rows = 24 });
            errdefer surface.deinit();
            surface.remote = remote_source;
            const term = try session.allocator.create(Term);
            errdefer session.allocator.destroy(term);
            term.* = .{};
            term.surface = surface;
            term.rt.handle = handle;
            term.rt.live_initialized = true;
            try session.tabs.items[0].panes.items[0].terms.append(session.allocator, term);
            return surface;
        }

        fn run(backend: *RemoteSessionBackend) anyerror!void {
            const allocator = std.testing.allocator;
            const first = try initSmokeSessionSized(allocator);
            defer allocator.destroy(first);
            defer first.deinit();
            const second = try initSmokeSessionSized(allocator);
            defer allocator.destroy(second);
            defer second.deinit();

            try RemoteSessionBackend.testing_api.cr5d2SetWindowSurfaceId(backend, 1, 0xD501);
            try RemoteSessionBackend.testing_api.cr5d2SetWindowSurfaceId(backend, 2, 0xD502);
            try RemoteSessionBackend.testing_api.cr5d2SetWindowSurfaceId(backend, 3, 0xD503);
            _ = try appendRemoteTerm(first, backend, 1, 0);
            const target = try appendRemoteTerm(second, backend, 2, 0);
            _ = try tab_ops.newTab(second);
            _ = try appendRemoteTerm(second, backend, 3, 1);
            // The same Window may contain a Term owned by another host job. Its handle is absent
            // from this backend job's canonical rows and must neither block nor join the action.
            const foreign_handle: u64 = 99;
            const foreign_surface_id: u64 = 0xD5FF;
            const foreign_surface = try appendForeignHostTerm(
                first,
                target.surface.remote.?,
                foreign_handle,
                foreign_surface_id,
            );
            defer {
                discardSiblingWrapper(first, foreign_handle) catch {};
                foreign_surface.deinit();
                allocator.destroy(foreign_surface);
            }
            defer for ([_]*AppSession{ first, second }) |session| for ([_]u64{ 1, 2, 3 }) |handle|
                discardSiblingWrapper(session, handle) catch {};

            try std.testing.expectError(
                error.InvalidAuthority,
                session_host_window_ops.prepareCloseWithBackend(
                    first,
                    second,
                    foreign_surface_id,
                    102,
                    100,
                    backend,
                ),
            );
            try std.testing.expect(term_ops.terminalSurfaceById(first, foreign_surface_id) != null);

            try RemoteSessionBackend.testing_api.cr5d2MakeTerminationUnconfirmed(backend, 2);
            switch ((try closeSnapshot(backend, 2)).state.close) {
                .termination_unconfirmed => {},
                else => return error.TestUnexpectedResult,
            }

            const stale = try session_host_window_ops.prepareCloseWithBackend(
                first,
                second,
                target.surface.id,
                102,
                100,
                backend,
            );
            const stale_generation = stale.action.action_generation;
            const first_generation_before = first.session_host_window_graph_generation;
            const second_generation_before = second.session_host_window_graph_generation;
            var moved_ids: [16]u64 = undefined;
            const moved = try workspace_ops.moveWorkspaceToSession(second, first, 0, &moved_ids);
            try std.testing.expect(moved.cross_window);
            try std.testing.expect(first.session_host_window_graph_generation > first_generation_before);
            try std.testing.expect(second.session_host_window_graph_generation > second_generation_before);
            const first_tabs_after_move = first.tabs.items.len;
            const second_tabs_after_move = second.tabs.items.len;
            try std.testing.expectError(
                error.InvalidWindowBinding,
                session_host_window_ops.commitCloseWithBackend(first, second, stale, 100, backend),
            );
            try std.testing.expectEqual(first_tabs_after_move, first.tabs.items.len);
            try std.testing.expectEqual(second_tabs_after_move, second.tabs.items.len);
            try std.testing.expect(backend.runtimes.contains(2));
            switch ((try closeSnapshot(backend, 2)).state.close) {
                .termination_unconfirmed => {},
                else => return error.TestUnexpectedResult,
            }
            try std.testing.expectError(
                error.InvalidWindowBinding,
                session_host_window_ops.commitCloseWithBackend(first, second, stale, 100, backend),
            );

            const expired = try session_host_window_ops.prepareCloseWithBackend(
                first,
                second,
                target.surface.id,
                101,
                100,
                backend,
            );
            try std.testing.expect(expired.action.action_generation > stale_generation);
            try std.testing.expectError(
                error.Expired,
                session_host_window_ops.commitCloseWithBackend(first, second, expired, 101, backend),
            );
            try std.testing.expect(backend.runtimes.contains(2));
            switch ((try closeSnapshot(backend, 2)).state.close) {
                .termination_unconfirmed => {},
                else => return error.TestUnexpectedResult,
            }

            const expired_generation = expired.action.action_generation;
            const fresh = try session_host_window_ops.prepareCloseWithBackend(
                first,
                second,
                target.surface.id,
                102,
                100,
                backend,
            );
            try std.testing.expect(fresh.action.action_generation > expired_generation);
            const target_id = target.surface.id;
            try session_host_window_ops.commitCloseWithBackend(first, second, fresh, 100, backend);
            try std.testing.expect(!backend.runtimes.contains(2));
            try std.testing.expect(term_ops.terminalSurfaceById(first, target_id) == null);
            try std.testing.expect(term_ops.terminalSurfaceById(second, target_id) == null);
            try std.testing.expect(term_ops.terminalSurfaceById(first, foreign_surface_id) != null);
            try std.testing.expect(backend.runtimes.contains(1));
            try std.testing.expect(backend.runtimes.contains(3));
            try std.testing.expectEqual(@as(u32, 2), backend.host_reconnect_job.?.runtime_row_count);
            try std.testing.expectEqual(@as(u32, 2), backend.host_reconnect_job.?.terminal_summary.?.total);
            try std.testing.expectEqual(@as(u32, 2), backend.host_reconnect_job.?.terminal_summary.?.frozen_unavailable);
            try std.testing.expectError(
                error.InvalidWindowBinding,
                session_host_window_ops.commitCloseWithBackend(first, second, fresh, 100, backend),
            );
        }
    };

    try RemoteSessionBackend.testing_api.runCr5d2WindowFixture(Fixture.run);
}
test "CR6a-1 AppSession은 recovered projection을 app-global primary owner 하나에만 게시한다" {
    if (!is_macos) return error.SkipZigTest;
    app_recovered_sessions_projection.deinit(std.heap.smp_allocator);
    const old_policy = app_keep_alive_after_quit;
    defer {
        app_recovered_sessions_projection.deinit(std.heap.smp_allocator);
        app_keep_alive_after_quit = old_policy;
    }
    app_keep_alive_after_quit = true;

    var primary: AppSession = undefined;
    primary.is_quick = false;
    const runtimes = [_]maru.session.runtime_reconcile.Runtime{.{ .runtime_id = 9 }};
    const hosts = [_]maru.session.runtime_reconcile.HostInventory{.{ .complete = .{
        .authority = .{
            .host_id = 1,
            .adapter_generation = 1,
            .upgrade_epoch = 1,
            .authority_generation = 1,
            .membership_generation = 1,
            .workspace_generation = 1,
        },
        .runtimes = &runtimes,
    } }};
    try primary.replaceRecoveredSessionsProjection(.{ .windows = &.{} }, &hosts, true, 1);
    try std.testing.expectEqual(@as(usize, 1), primary.recoveredSessionsRows(true).len);
    try std.testing.expectEqual(@as(usize, 0), primary.recoveredSessionsRows(false).len);

    var secondary: AppSession = undefined;
    secondary.is_quick = false;
    const before_generation = app_recovered_sessions_projection.generation;
    try secondary.replaceRecoveredSessionsProjection(.{ .windows = &.{} }, &.{}, false, 2);
    try std.testing.expectEqual(before_generation, app_recovered_sessions_projection.generation);
    try std.testing.expectEqual(@as(usize, 1), primary.recoveredSessionsRows(true).len);

    app_keep_alive_after_quit = false;
    try std.testing.expectEqual(@as(usize, 0), primary.recoveredSessionsRows(true).len);
}

test "CR6a-2 primary sidebar는 recovered system header와 inert row만 materialize한다" {
    if (!is_macos) return error.SkipZigTest;
    app_recovered_sessions_projection.deinit(std.heap.smp_allocator);
    const old_policy = app_keep_alive_after_quit;
    defer {
        app_recovered_sessions_projection.deinit(std.heap.smp_allocator);
        app_keep_alive_after_quit = old_policy;
    }
    app_keep_alive_after_quit = true;

    var session: AppSession = .{ .allocator = std.testing.allocator, .io = std.testing.io };
    defer session.sidebar_rows.deinit(std.testing.allocator);
    session.is_primary_window = true;
    const runtimes = [_]maru.session.runtime_reconcile.Runtime{.{ .runtime_id = 0x12 }};
    const hosts = [_]maru.session.runtime_reconcile.HostInventory{.{ .complete = .{
        .authority = .{
            .host_id = 1,
            .adapter_generation = 1,
            .upgrade_epoch = 1,
            .authority_generation = 1,
            .membership_generation = 1,
            .workspace_generation = 1,
        },
        .runtimes = &runtimes,
    } }};
    try session.replaceRecoveredSessionsProjection(.{ .windows = &.{} }, &hosts, true, 1);
    session.projectRowsFrom(&.{}, &.{});
    try std.testing.expectEqual(@as(usize, 2), session.sidebar_rows.items.len);
    try std.testing.expect(session.sidebar_rows.items[0] == .recovered_sessions_header);
    try std.testing.expectEqual(@as(usize, 0), session.sidebar_rows.items[1].recovered_session.projection_index);
    try std.testing.expect(!chrome.components.sidebar.onGroupHeader(session.sidebar_rows.items, 0));
    try std.testing.expect(chrome.components.sidebar.agentAt(session.sidebar_rows.items, 1) == null);
    try std.testing.expect(tab_ops.visibleTab(&session, 0) == null);
    try std.testing.expect(tab_ops.visibleTab(&session, 1) == null);
    session.sidebar_width_px = 200;
    session.sidebar_header_height_px = 40;
    session.sidebar_metrics = chrome.components.sidebar.Metrics.init(20, 24);
    const header_y = sidebar_ops.testSidebarRowCenterY(&session, 0);
    const candidate_y = sidebar_ops.testSidebarRowCenterY(&session, 1);
    try std.testing.expect(settings_ops.renameTargetAt(&session, 10, header_y) == null);
    try std.testing.expect(settings_ops.renameTargetAt(&session, 10, candidate_y) == null);
    try std.testing.expect(pane_ops.computePaneDropDest(&session, 10, candidate_y) == null);
    session.mouse(1, 10, header_y, 0, 0);
    session.mouse(1, 10, candidate_y, 0, 0);
    try std.testing.expect(session.pointer_gesture_owner == .none);
    try std.testing.expectEqual(@as(usize, 0), session.tabs.items.len);

    session.is_primary_window = false;
    session.projectRowsFrom(&.{}, &.{});
    try std.testing.expectEqual(@as(usize, 0), session.sidebar_rows.items.len);
}

test "CR6a-2 primary sidebar는 dead 또는 malformed discovery를 complete empty로 세탁하지 않는다" {
    const entries = [_]session_host.recovery_discovery.Entry{
        .{ .unavailable = .{ .host_id = 3, .reason = .lease_unknown } },
        .{ .unavailable = .{ .host_id = 1, .reason = .lease_free } },
        .{ .unavailable = .{ .host_id = 2, .reason = .invalid_manifest } },
    };
    var inventories: std.ArrayListUnmanaged(maru.session.runtime_reconcile.HostInventory) = .empty;
    defer inventories.deinit(std.testing.allocator);
    try AppSession.mergeDiscoveredInventories(
        std.testing.allocator,
        &entries,
        &.{},
        &.{},
        &inventories,
    );
    try std.testing.expectEqual(@as(usize, 3), inventories.items.len);
    try std.testing.expectEqual(@as(u128, 1), inventories.items[0].hostId());
    try std.testing.expectEqual(maru.session.runtime_reconcile.UnavailableReason.lifecycle, inventories.items[0].unavailable.reason);
    try std.testing.expectEqual(@as(u128, 2), inventories.items[1].hostId());
    try std.testing.expectEqual(maru.session.runtime_reconcile.UnavailableReason.malformed, inventories.items[1].unavailable.reason);
    try std.testing.expectEqual(@as(u128, 3), inventories.items[2].hostId());
    try std.testing.expectEqual(maru.session.runtime_reconcile.UnavailableReason.stale, inventories.items[2].unavailable.reason);
}

const Cr6RecoveredFixtureMode = enum { inert, orphan, notification_orphan, notification_direct, ended_conflict, stale_projection, stale_manifest_slot, missing_runtime, deadline_stall, attach_oom };

fn runCr6RecoveredSessionRealHostFixture(comptime mode: Cr6RecoveredFixtureMode) !void {
    if (!is_macos) return error.SkipZigTest;
    if (std.c.getenv("MARU_SESSION_HOST_CR6A2_REAL_HOST_AGGREGATE_SKIP") != null)
        return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const io = std.Io.Threaded.global_single_threaded.io();
    var base_buf: [128]u8 = undefined;
    const base = std.fmt.bufPrintZ(&base_buf, "/tmp/maru-cr6a2-launch-{d}-{d}", .{
        std.c.getpid(),
        @intFromEnum(mode),
    }) catch
        return error.SkipZigTest;
    std.Io.Dir.cwd().deleteTree(io, base) catch {};
    _ = std.c.mkdir(base.ptr, 0o700);
    var dir_buf: [192]u8 = undefined;
    const dir = session_host.discovery.sessionHostDirPath(&dir_buf, base) catch return error.SkipZigTest;
    const fixture_host_id: u128 = @as(u128, @intCast(std.c.getpid())) + 0xC6A2_0000;
    var socket_buf: [128]u8 = undefined;
    const socket = session_host.short_endpoint.currentSocketPathIn(&socket_buf, fixture_host_id) catch return error.SkipZigTest;

    const child = std.c.fork();
    if (child < 0) return error.SkipZigTest;
    if (child == 0) {
        _ = std.c.setsid();
        session_host.daemon.runSessionHostWithIdentity(std.heap.page_allocator, io, dir, socket, fixture_host_id) catch {};
        std.c._exit(0);
    }
    var child_stopped = false;
    defer {
        if (child_stopped) _ = std.c.kill(child, std.posix.SIG.CONT);
        _ = std.c.kill(child, std.posix.SIG.TERM);
        var status: c_int = undefined;
        var reaped = false;
        var reap_attempt: usize = 0;
        while (reap_attempt < 200) : (reap_attempt += 1) {
            if (std.c.waitpid(child, &status, std.c.W.NOHANG) == child) {
                reaped = true;
                break;
            }
            _ = usleep(5 * 1000);
        }
        if (!reaped) {
            _ = std.c.kill(child, std.posix.SIG.KILL);
            _ = std.c.waitpid(child, &status, 0);
        }
        std.Io.Dir.cwd().deleteTree(io, base) catch {};
    }

    var spawner: ?session_host.client.Client = null;
    var wait_count: usize = 0;
    while (wait_count < 250 and spawner == null) : (wait_count += 1) {
        spawner = session_host.client.Client.connect(allocator, socket, .gui) catch null;
        if (spawner == null) _ = usleep(20 * 1000);
    }
    if (spawner == null) {
        std.debug.print("CR6a-2 fixture: legacy endpoint did not become ready\n", .{});
        return error.TestUnexpectedResult;
    }
    defer spawner.?.deinit();
    const spawn_response = try spawner.?.call("runtime.spawn", "{\"argv\":[\"/bin/cat\"],\"cols\":40,\"rows\":10}");
    defer allocator.free(spawn_response);
    const runtime_id = session_host.client.extractRuntimeId(spawn_response) orelse {
        std.debug.print("CR6a-2 fixture: spawn response omitted runtime id\n", .{});
        return error.TestUnexpectedResult;
    };

    app_recovered_sessions_projection.deinit(std.heap.smp_allocator);
    app_recovered_sessions_workspace_generation = 0;
    app_recovered_sessions_launch_attempted = false;
    const old_policy = app_keep_alive_after_quit;
    defer {
        app_recovered_sessions_projection.deinit(std.heap.smp_allocator);
        app_recovered_sessions_workspace_generation = 0;
        app_recovered_sessions_launch_attempted = false;
        app_keep_alive_after_quit = old_policy;
        host_connect_failed = false;
        if (app_remote_backend) |*backend| backend.deinit();
        app_remote_backend = null;
        if (app_remote_host_pool) |*pool| pool.deinit();
        app_remote_host_pool = null;
        if (app_remote_client) |*client| client.deinit();
        app_remote_client = null;
    }

    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(io, allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
        .defer_initial_surface = 1,
    });
    defer session.deinit();
    try std.testing.expectEqual(@as(usize, 0), session.tabs.items.len);
    app_keep_alive_after_quit = true;
    session.loaded_config.config.session.keep_alive_after_quit = true;
    session.is_primary_window = true;

    // coordinator 전제도 실제 registry에서 독립 확인한다. legacy socket에 붙었다는 사실만으로 secure manifest/lease
    // discovery가 되었다고 간주하면 제품 경로가 빈 projection으로 false-green 될 수 있다.
    var discovered = session_host.recovery_discovery.discover(allocator, dir);
    defer discovered.deinit(allocator);
    const discovered_entries = switch (discovered) {
        .complete => |entries| entries,
        .unavailable => |reason| {
            std.debug.print("CR6a-2 fixture: discovery unavailable {s}\n", .{@tagName(reason)});
            return error.TestUnexpectedResult;
        },
    };
    var discovered_host_id: ?u128 = null;
    for (discovered_entries) |entry| switch (entry) {
        .candidate => |candidate| discovered_host_id = candidate.manifest.host_id,
        .unavailable => {},
    };
    const host_id = discovered_host_id orelse {
        std.debug.print("CR6a-2 fixture: discovery returned no live candidate ({d} entries)\n", .{discovered_entries.len});
        return error.TestUnexpectedResult;
    };
    const adapter_outcome = session.ensureRestoreHostAdapterAtBase(base, host_id);
    if (adapter_outcome != .ready)
        std.debug.print("CR6a-2 fixture: adapter publication returned {s}\n", .{@tagName(adapter_outcome)});
    try std.testing.expectEqual(AppSession.RestoreHostOutcome.ready, adapter_outcome);
    try std.testing.expect(app_remote_host_pool.?.adapterGeneration(host_id) != null);

    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    const outcome = session.prepareRecoveredSessionsAtLaunchFromBase(null, base, arena_state.allocator());
    try std.testing.expectEqual(AppSession.RecoveredSessionsLaunchOutcome.published, outcome);
    try std.testing.expectEqual(@as(usize, 0), session.tabs.items.len);
    try std.testing.expectEqual(@as(usize, 1), session.recoveredSessionsRows(true).len);
    try std.testing.expectEqual(
        try std.fmt.parseInt(u128, &runtime_id, 16),
        session.recoveredSessionsRows(true)[0].runtime_id,
    );
    try std.testing.expectEqual(@as(usize, 2), session.sidebar_rows.items.len);
    try std.testing.expect(tab_ops.visibleTab(session, 0) == null);
    try std.testing.expect(tab_ops.visibleTab(session, 1) == null);

    var ended_target: ?*AppSession = null;
    defer if (ended_target) |target| {
        target.deinit();
        allocator.destroy(target);
    };
    var original_tomb: ?*Term = null;
    if (mode == .ended_conflict or mode == .stale_manifest_slot) {
        const target = try allocator.create(AppSession);
        var target_storage_owned = true;
        errdefer if (target_storage_owned) allocator.destroy(target);
        try target.init(io, allocator, .{
            .abi_version = abi_version,
            .cols = 40,
            .rows = 10,
            .queue_capacity = 16,
            .command_kind = @intFromEnum(CommandKind.controlled_smoke),
            .defer_initial_surface = 1,
        });
        ended_target = target;
        target_storage_owned = false;
        var host_hex: [32]u8 = undefined;
        _ = std.fmt.bufPrint(&host_hex, "{x:0>32}", .{host_id}) catch unreachable;
        const surfaces = [_]maru.session.workspace.Surface{.{
            .title = "Recovered tombstone",
            .runtime_host_id = &host_hex,
            .runtime_id = &runtime_id,
            .runtime_state = .ended,
        }};
        const panes = [_]maru.session.workspace.Pane{.{ .surfaces = &surfaces }};
        const tabs = [_]maru.session.workspace.Tab{.{ .tree = &.{.{ .leaf = 0 }}, .panes = &panes }};
        const preceding_surfaces = [_]maru.session.workspace.Surface{.{
            .runtime_host_id = &host_hex,
            .runtime_id = "0000000000000000000000000000dead",
            .runtime_state = .ended,
        }};
        const preceding_panes = [_]maru.session.workspace.Pane{.{ .surfaces = &preceding_surfaces }};
        const preceding_tabs = [_]maru.session.workspace.Tab{.{ .tree = &.{.{ .leaf = 0 }}, .panes = &preceding_panes }};
        const windows = [_]maru.session.workspace.Window{ .{ .tabs = &preceding_tabs }, .{ .tabs = &tabs } };
        // The action is issued by the primary `session`, but the canonical manifest ordinal 1 is
        // owned by another live AppSession. This exercises the app-global Window registry and
        // exact target-pane resolver instead of merely using a two-Window manifest in one Window.
        try target.applyWorkspaceWindow(windows[1]);
        original_tomb = pane_ops.activePane(target).activeTerm();
        try std.testing.expect(original_tomb.?.rt.ended_placeholder);
        try std.testing.expectEqual(std.math.maxInt(u16), original_tomb.?.rt.ended_manifest_index);
        const authority = app_recovered_sessions_projection.rows[0].authority;
        const runtime_value = try std.fmt.parseInt(u128, &runtime_id, 16);
        const inventory_runtimes = [_]maru.session.runtime_reconcile.Runtime{.{ .runtime_id = runtime_value }};
        const inventories = [_]maru.session.runtime_reconcile.HostInventory{.{ .complete = .{
            .authority = authority,
            .runtimes = &inventory_runtimes,
        } }};
        try session.replaceRecoveredSessionsProjection(.{ .windows = &windows }, &inventories, true, app_recovered_sessions_workspace_generation);
        try std.testing.expectEqual(session_host.recovered_sessions_projection.CandidateKind.ended_present_conflict, app_recovered_sessions_projection.rows[0].kind);
        try std.testing.expectEqual(@as(u16, 1), original_tomb.?.rt.ended_manifest_index);
        try sidebar_ops.rebuildSidebar(session);
    }

    if (mode == .notification_direct) {
        const runtime_value = try std.fmt.parseInt(u128, &runtime_id, 16);
        app_recovered_sessions_projection.deinit(std.heap.smp_allocator);
        app_keep_alive_after_quit = false;
        const backend_count_before = app_remote_backend.?.runtimes.count();
        try std.testing.expectError(
            error.InvalidAuthority,
            session.adoptNotificationRuntimeAtBase(base, host_id + 1, runtime_value),
        );
        try std.testing.expectEqual(@as(usize, 0), session.tabs.items.len);
        try std.testing.expectEqual(backend_count_before, app_remote_backend.?.runtimes.count());
        try session.adoptNotificationRuntimeAtBase(base, host_id, runtime_value);
        try std.testing.expectEqual(backend_count_before + 1, app_remote_backend.?.runtimes.count());
        try std.testing.expectEqual(@as(usize, 1), session.tabs.items.len);
        try std.testing.expect(!session.restore_runtime_force_attach);
        try std.testing.expectEqual(host_id, app_remote_backend.?.runtimeHostId(pane_ops.activePane(session).activeTerm().rt.handle).?);
        try std.testing.expectEqual(runtime_id, app_remote_backend.?.runtimeIdFor(pane_ops.activePane(session).activeTerm().rt.handle).?);
    }
    if (mode != .inert and mode != .notification_direct) {
        const row_before = app_recovered_sessions_projection.rows[0];
        const projection_generation_before = app_recovered_sessions_projection.generation;
        const source_graph_generation_before = session.session_host_window_graph_generation;
        const target_graph_generation_before = if (ended_target) |target|
            target.session_host_window_graph_generation
        else
            null;
        const backend_runtime_count_before = app_remote_backend.?.runtimes.count();
        if (mode == .stale_projection)
            app_recovered_sessions_workspace_generation = std.math.add(
                u64,
                app_recovered_sessions_workspace_generation,
                1,
            ) catch unreachable;
        if (mode == .missing_runtime) {
            var terminate_params_buf: [64]u8 = undefined;
            const terminate_params = std.fmt.bufPrint(
                &terminate_params_buf,
                "{{\"runtime_id\":\"{s}\"}}",
                .{&runtime_id},
            ) catch unreachable;
            const terminate_response = try spawner.?.call("runtime.terminate", terminate_params);
            allocator.free(terminate_response);
        }
        if (mode == .deadline_stall) {
            try std.testing.expectEqual(@as(c_int, 0), std.c.kill(child, std.posix.SIG.STOP));
            child_stopped = true;
        }
        const action_started_ns = std.Io.Clock.awake.now(io).nanoseconds;
        switch (mode) {
            .inert, .notification_direct => unreachable,
            .orphan, .stale_projection, .missing_runtime, .deadline_stall, .attach_oom => {
                session.sidebar_width_px = 200;
                session.sidebar_header_height_px = 40;
                session.sidebar_metrics = chrome.components.sidebar.Metrics.init(20, 24);
                try sidebar_ops.rebuildSidebar(session);
                const click_y = sidebar_ops.testSidebarRowCenterY(session, 1);
                try std.testing.expectEqual(@as(?usize, 1), sidebar_ops.sidebarSlotAt(session, click_y));
                if (mode == .attach_oom) {
                    // Fresh wire evidence has already been obtained inside the action when newTab
                    // reaches its first AppSession-owned allocation. Fail that actual product
                    // construction point, then restore the allocator before any teardown reads
                    // pre-existing allocations.
                    var failing = std.testing.FailingAllocator.init(allocator, .{ .fail_index = 0 });
                    session.allocator = failing.allocator();
                    session.mouse(1, 10, click_y, 0, 0);
                    session.allocator = allocator;
                    try std.testing.expect(failing.has_induced_failure);
                } else {
                    session.mouse(1, 10, click_y, 0, 0);
                }
            },
            .notification_orphan => {
                const runtime_value = try std.fmt.parseInt(u128, &runtime_id, 16);
                const projection_before = app_recovered_sessions_projection.generation;
                const backend_count_before = app_remote_backend.?.runtimes.count();
                try std.testing.expectError(
                    error.InvalidAuthority,
                    session.activateNotificationRuntime(host_id + 1, runtime_value, .adopt_recovered),
                );
                try std.testing.expectEqual(projection_before, app_recovered_sessions_projection.generation);
                try std.testing.expectEqual(backend_count_before, app_remote_backend.?.runtimes.count());
                try std.testing.expect(!(try session.activateNotificationRuntime(host_id, runtime_value, .probe_bound)));
                try std.testing.expect(try session.activateNotificationRuntime(host_id, runtime_value, .adopt_recovered));
                // A repeated response finds the live binding after the projection row is consumed;
                // it must not create a duplicate tab or a second host attachment.
                try std.testing.expect(try session.activateNotificationRuntime(host_id, runtime_value, .probe_bound));
                try std.testing.expect(try session.activateNotificationRuntime(host_id, runtime_value, .activate_bound));
            },
            .ended_conflict, .stale_manifest_slot => {
                if (mode == .stale_manifest_slot)
                    original_tomb.?.rt.ended_manifest_index = 0;
                session.sidebar_search_active = true;
                for (app_recovered_sessions_projection.rows[0].label) |byte|
                    try session.sidebar_search_input.appendChar(session.allocator, byte);
                _ = try session.handleKeyEvent(.{ .key = .enter, .modifiers = .{} });
            },
        }
        if (mode == .deadline_stall) {
            const elapsed_ns = std.Io.Clock.awake.now(io).nanoseconds - action_started_ns;
            try std.testing.expect(elapsed_ns >= session_host.recovered_session_adopt.action_deadline_ns);
            try std.testing.expect(elapsed_ns < session_host.recovered_session_adopt.action_deadline_ns + 3 * std.time.ns_per_s);
            _ = std.c.kill(child, std.posix.SIG.CONT);
            child_stopped = false;
        }
        if (mode == .stale_projection or mode == .stale_manifest_slot or mode == .missing_runtime or mode == .deadline_stall or mode == .attach_oom) {
            try std.testing.expectEqual(@as(usize, 0), session.tabs.items.len);
            try std.testing.expectEqual(@as(usize, 1), session.recoveredSessionsRows(true).len);
            try std.testing.expectEqual(projection_generation_before, app_recovered_sessions_projection.generation);
            try std.testing.expect(std.meta.eql(row_before, app_recovered_sessions_projection.rows[0]));
            try std.testing.expectEqual(source_graph_generation_before, session.session_host_window_graph_generation);
            try std.testing.expect(!session.surface_initialized);
            try std.testing.expectEqual(backend_runtime_count_before, app_remote_backend.?.runtimes.count());
            try std.testing.expect(session.chrome_host.notice.open);
            try std.testing.expectEqualStrings(
                maru.i18n.t(.app_recovered_session_failed),
                session.chrome_host.notice.message,
            );
            if (mode == .stale_manifest_slot) {
                const target = ended_target orelse return error.TestUnexpectedResult;
                try std.testing.expectEqual(@as(usize, 1), target.tabs.items.len);
                try std.testing.expectEqual(target_graph_generation_before.?, target.session_host_window_graph_generation);
                try std.testing.expect(pane_ops.activePane(target).activeTerm() == original_tomb.?);
                try std.testing.expect(original_tomb.?.rt.ended_placeholder);
            }
            if (mode == .attach_oom) {
                var live_params_buf: [64]u8 = undefined;
                const live_params = std.fmt.bufPrint(
                    &live_params_buf,
                    "{{\"runtime_id\":\"{s}\"}}",
                    .{&runtime_id},
                ) catch unreachable;
                const live_response = try spawner.?.call("runtime.get", live_params);
                defer allocator.free(live_response);
                try std.testing.expect(std.mem.indexOf(u8, live_response, &runtime_id) != null);
            }
        } else {
            const adopted_session = ended_target orelse session;
            try std.testing.expectEqual(@as(usize, if (ended_target == null) 1 else 0), session.tabs.items.len);
            try std.testing.expectEqual(@as(usize, 1), adopted_session.tabs.items.len);
            try std.testing.expectEqual(@as(usize, 0), session.recoveredSessionsRows(true).len);
            try std.testing.expect(adopted_session.surface_initialized);
            const adopted = pane_ops.activePane(adopted_session).activeTerm();
            if (original_tomb) |tomb| try std.testing.expect(adopted != tomb);
            try std.testing.expect(!adopted.rt.restored_existing);
            try std.testing.expect(adopted.surface.remote != null);
            try std.testing.expectEqual(host_id, app_remote_backend.?.runtimeHostId(adopted.rt.handle).?);
            try std.testing.expectEqual(runtime_id, app_remote_backend.?.runtimeIdFor(adopted.rt.handle).?);
        }
    }
    try session.finishDeferredInitialSurface();
    try std.testing.expectEqual(@as(usize, switch (mode) {
        // A live recovery row owns the deferred launch surface. Creating a default persistent
        // shell here would add a second runtime to the same host on every app relaunch and hide
        // the row that the user is expected to recover.
        .inert, .stale_projection, .stale_manifest_slot, .missing_runtime, .deadline_stall, .attach_oom => 0,
        .orphan, .notification_orphan, .notification_direct, .ended_conflict => 1,
    }), session.tabs.items.len);
    try std.testing.expectEqual(@as(usize, switch (mode) {
        .inert, .stale_projection, .stale_manifest_slot, .missing_runtime, .deadline_stall, .attach_oom => 2,
        .orphan, .notification_orphan, .notification_direct, .ended_conflict => 1,
    }), session.sidebar_rows.items.len);
    if (mode == .inert) {
        _ = try session.resize(800, 600, 1000);
        try std.testing.expectEqual(@as(usize, 0), session.tabs.items.len);
        try std.testing.expectEqual(@as(usize, 2), session.sidebar_rows.items.len);
        try std.testing.expectEqual(@as(u32, 800), session.backing_width_px);
        try std.testing.expectEqual(@as(u32, 600), session.backing_height_px);
        // Recovered Sessions가 첫 launch surface인 동안 renderer는 chrome을 위해 살아야 하지만
        // terminal pump를 빌리는 AppFrameLoop는 아직 존재하면 안 된다. 첫 placement가 atlas를 grow할
        // 수 있으므로 유계 재시도하고, 실제 retained Metal frame이 1x1 draw guard+sidebar cells를 갖는지 본다.
        try std.testing.expect(!session.renderer_initialized);
        try std.testing.expect(!session.frame_loop_initialized);
        for (0..4) |_| {
            _ = try session.tick();
            if (!session.metal_dirty) break;
        }
        try std.testing.expect(session.renderer_initialized);
        try std.testing.expect(!session.frame_loop_initialized);
        try std.testing.expectEqual(@as(u32, 1), session.metal_buffer.view().cols);
        try std.testing.expectEqual(@as(u32, 1), session.metal_buffer.view().rows);
        try std.testing.expect(session.metal_buffer.sidebar_cells.len > 0);
        try std.testing.expectEqual(@as(u64, 0), session.last_summary.frame_loop_ticks);
    }
}

test "CR6a-2 primary sidebar는 실제 secure discovery와 ephemeral inventory 뒤에만 materialize한다" {
    return runCr6RecoveredSessionRealHostFixture(.inert);
}

test "CR6b orphan row action은 fresh authority 뒤 exact runtime을 새 비고정 탭으로 채택한다" {
    return runCr6RecoveredSessionRealHostFixture(.orphan);
}

test "N3 stable notification route는 actual host exact runtime을 채택하고 재응답에 중복 attach하지 않는다" {
    return runCr6RecoveredSessionRealHostFixture(.notification_orphan);
}

