test "이미지 갤러리: 문맥 줄바꿈이 글자를 흘리지 않는다 (IG13 적대적)" {
    // **적대적 검증이 잡은 결함이다.** 그리기는 `truncateToCols`(`cols-1` 칸 + «…»)를, 진행은 별도
    // 계산(`cols` 칸)을 썼다 — 그 사이 글자가 **안 그려진 채 건너뛰어졌다**. 게다가 그 함수는
    // 안 넘치면 원본 슬라이스를 그대로 돌려주므로 `free` 하면 남의 메모리를 푼다(마지막 줄은 언제나
    // 그 경로였다).
    //
    // 이제 한 함수(`wrapNextBytes`)가 그리기와 진행 둘 다 답한다. 그 불변식을 여기서 짚는다:
    // **줄을 이어 붙이면 원문이 그대로 나온다** — 한 글자도 빠지거나 겹치지 않는다.
    const g = image_gallery_ops;
    const texts = [_][]const u8{
        "사이드바 정렬이 틀어진 것 같아 화면을 보겠습니다",
        "abcdefghijklmnopqrstuvwxyz 0123456789",
        "한글과 ASCII 가 섞인 문장 mixed width text 입니다",
        "짧다",
        "",
    };
    for (texts) |text| {
        var cols: u16 = 1;
        while (cols <= 40) : (cols += 1) {
            var rest: []const u8 = text;
            var joined: std.ArrayList(u8) = .empty;
            defer joined.deinit(std.testing.allocator);
            var guard: usize = 0;
            while (rest.len > 0) {
                guard += 1;
                try std.testing.expect(guard <= text.len + 1); // **반드시 나아간다**
                const take = g.wrapNextBytes(rest, cols);
                try std.testing.expect(take > 0);
                try std.testing.expect(take <= rest.len);
                try joined.appendSlice(std.testing.allocator, rest[0..take]);
                rest = rest[take..];
            }
            // ① 이어 붙이면 원문이다 — 흘린 글자도, 겹친 글자도 없다.
            try std.testing.expectEqualStrings(text, joined.items);
        }
    }
}

test "이미지 갤러리: 문맥 줄바꿈이 UTF-8 을 쪼개지 않는다 (IG13 적대적)" {
    // 바이트로 자르면 한글이 깨진다. 칸이 글자보다 좁아도(1 칸에 2 칸짜리 한글) 한 글자는 통째로 낸다 —
    // 안 그러면 영영 안 나아가서 무한 루프가 된다.
    const g = image_gallery_ops;
    const text: []const u8 = "한글만있는문장입니다";
    var cols: u16 = 1;
    while (cols <= 8) : (cols += 1) {
        var rest: []const u8 = text;
        while (rest.len > 0) {
            const take = g.wrapNextBytes(rest, cols);
            try std.testing.expect(take > 0);
            try std.testing.expect(std.unicode.utf8ValidateSlice(rest[0..take]));
            rest = rest[take..];
        }
    }
}

test "이미지 갤러리: 문맥 줄 나누기가 원문을 잃지 않는다 (IG13 적대적)" {
    // **이 계약을 어긴 것이 방금 고친 결함이었다.** 그리기는 `cols-1` 칸 + «…», 진행은 `cols` 칸을
    // 써서 그 사이 글자가 안 그려진 채 건너뛰어졌다. 그리고 그 결함은 **어떤 test 도 못 봤다** —
    // 그리는 함수가 CoreText 함수 포인터를 요구해 단위 test 로 부를 수 없었기 때문이다.
    //
    // 그래서 「어느 글자를 어느 줄에」를 순수 함수(`layoutContext`)로 갈랐다. 여기서 그 계약을 짚는다:
    // **줄을 이어 붙이면 원문의 앞부분이 그대로 나온다.**
    const g = image_gallery_ops;
    const texts = [_][]const u8{
        "사이드바 정렬이 틀어진 것 같아 화면을 보겠습니다",
        "abcdefghijklmnopqrstuvwxyz 0123456789 the quick brown fox",
        "한글과 ASCII 가 섞인 문장 mixed width text 입니다",
        "짧다",
        "",
        // **이모지·ZWJ·결합 문자**(적대적 9 회차). 대화에는 이런 것이 그대로 들어온다 —
        // 코드포인트 단위로 나아가므로 «반드시 나아간다» 와 «UTF-8 이 온전하다» 가 여기서도 서야 한다.
        "빌드 통과 ✅ 이제 배포합니다 🚀",
        "가족 👨‍👩‍👧‍👦 이모지는 ZWJ 로 이어 붙은 여러 코드포인트다",
        "결합 문자 é(U+0065 U+0301)와 깃발 🇰🇷 도 섞는다",
        "\u{1F600}\u{1F601}\u{1F602}\u{1F603}",
    };
    for (texts) |text| {
        var cols: u16 = 1;
        while (cols <= 40) : (cols += 1) {
            var rows: u32 = 1;
            while (rows <= g.max_context_rows) : (rows += 1) {
                const plan = g.layoutContext(text, cols, rows);
                try std.testing.expect(plan.count <= rows);

                // ① 줄들이 **원문을 앞에서부터 빈틈없이** 덮는다.
                var at: usize = 0;
                for (plan.lines[0..plan.count]) |span| {
                    try std.testing.expectEqual(at, span.start); // 건너뛴 글자가 없다
                    try std.testing.expect(span.len > 0); // 반드시 나아간다
                    at += span.len;
                }
                try std.testing.expect(at <= text.len);

                // ② 「남는 것이 있다」와 «…» 가 일치한다.
                try std.testing.expectEqual(at < text.len, plan.ellipsis);

                // ③ 다 담겼으면 줄이 원문 전체다.
                if (!plan.ellipsis) try std.testing.expectEqual(text.len, at);

                // ④ 각 줄은 UTF-8 이 온전하다 — 바이트로 자르면 한글이 깨진다.
                for (plan.lines[0..plan.count]) |span| {
                    try std.testing.expect(std.unicode.utf8ValidateSlice(text[span.start..][0..span.len]));
                }
            }
        }
    }
}

test "이미지 갤러리: 문맥 줄 나누기가 폭 0·줄 0 에서 멈춘다 (IG13 적대적)" {
    // 좁은 도크에서 `cols` 가 0 이 될 수 있다. 그때 무한 루프나 빈 줄을 만들지 않는다.
    const g = image_gallery_ops;
    try std.testing.expectEqual(@as(u32, 0), g.layoutContext("무엇이든", 0, 3).count);
    try std.testing.expectEqual(@as(u32, 0), g.layoutContext("무엇이든", 10, 0).count);
    try std.testing.expectEqual(@as(u32, 0), g.layoutContext("", 10, 3).count);
    // 칸보다 넓은 글자(1 칸에 2 칸짜리 한글)도 한 글자는 낸다 — 안 그러면 영영 안 나아간다.
    const one = g.layoutContext("한", 1, 3);
    try std.testing.expectEqual(@as(u32, 1), one.count);
    try std.testing.expectEqual(@as(usize, 3), one.lines[0].len);
}

test "이미지 갤러리: 한 틱에 여러 장을 동시에 건다 (IG14)" {
    // 사용자 보고: 「이미지가 많으면 목록에서 느려지는 게 체감된다」.
    //
    // 원인은 디코드 자체가 아니라 **제출이 틱에 묶여 있던 것**이었다. 한 번에 한 장만 걸면
    // 보이는 12 칸을 채우는 데 12 틱(200 ms)이 필요하다 — 실제 디코드 일은 그 4 분의 1이다.
    //
    // 그래서 여기서 재는 것은 시간이 아니라 **동시에 걸린 개수**다. `ensureTiles` 안에서 동기적으로
    // 정해지므로 기계 속도와 무관하다(수확은 다음 틱 첫머리라 이 사이에 끼어들지 않는다).
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const io = std.Io.Threaded.global_single_threaded.io();
    const allocator = std.testing.allocator;

    // 상한이 1 이면 「동시에」가 성립하지 않는다 — 계약을 먼저 못 박는다.
    try std.testing.expect(agent_image_decode_backend.max_inflight > 1);

    const png_b64 = "iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAYAAABytg0kAAAAEklEQVR4nGP4z8DwHwyBNBgAAEnICff5q7YNAAAAAElFTkSuQmCC";

    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var doc: std.ArrayList(u8) = .empty;
    defer doc.deinit(allocator);
    for (0..40) |i| {
        const b = try std.fmt.allocPrint(
            allocator,
            "{{\"type\":\"user\",\"message\":{{\"content\":[{{\"type\":\"text\",\"text\":\"n{d}\"}},{{\"type\":\"image\",\"source\":{{\"type\":\"base64\",\"media_type\":\"image/png\",\"data\":\"{s}\"}}}}]}}}}\n",
            .{ i, png_b64 },
        );
        defer allocator.free(b);
        try doc.appendSlice(allocator, b);
    }
    try tmp.dir.writeFile(io, .{ .sub_path = "s.jsonl", .data = doc.items });

    var root_buf: [std.fs.max_path_bytes]u8 = undefined;
    const root = root_buf[0..try tmp.dir.realPath(io, &root_buf)];
    const path = try std.fmt.allocPrint(allocator, "{s}/s.jsonl", .{root});
    defer allocator.free(path);

    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(io, allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 20,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1400, 900, 1000);

    session.dock_initialized = true;
    session.chrome_minimal = false;
    session.dock.presented = true;
    session.dock.collapsed = false;
    session.dock.side = .right;
    dock_ops.setDockView(session, .image_gallery);

    const term = pane_ops.activePane(session).activeTerm();
    try std.testing.expect(term.agent_image_source.set(path));
    image_gallery_ops.refresh(session, false);
    {
        var spins: usize = 0;
        while (spins < 200_000 and !session.image_gallery.built) : (spins += 1) _ = session.tick() catch {};
    }
    try std.testing.expectEqual(@as(usize, 40), session.image_gallery.count());

    // 빈 칸이 넉넉하다 — 40 장이 한 화면에 다 들어가지 않는다.
    const l = image_gallery_ops.gridLayout(session);
    try std.testing.expect(l.visible >= 2);

    // 한 틱을 돌린다. 「한 번에 한 장」이던 시절에는 이 값이 **1 을 넘을 수 없었다**.
    _ = session.tick() catch {};
    try std.testing.expect(session.image_gallery.pending_len >= 2);
}

test "이미지 갤러리: 취소한 뒤에도 다시 채워진다 (IG14 적대적)" {
    // **여럿으로 늘리며 잃은 자가치유.** 슬롯이 하나였을 때는 취소된 요청이 남아 있어도 다음 제출이
    // 그 자리를 덮어썼다. 집합이 되면서 그 성질이 사라졌다 — 취소된 워커는 결과를 내놓지 않으므로
    // 집합에서 걷히지 않고, 죽은 항목이 자리를 다 차지하면 새 제출이 기록되지 못해 오는 결과마다
    // 「늦게 온 것」으로 버려진다. 증상은 **썸네일이 영영 안 뜨는 것**이고, 원인은 화면에 안 보인다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const io = std.Io.Threaded.global_single_threaded.io();
    const allocator = std.testing.allocator;

    const png_b64 = "iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAYAAABytg0kAAAAEklEQVR4nGP4z8DwHwyBNBgAAEnICff5q7YNAAAAAElFTkSuQmCC";

    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var doc: std.ArrayList(u8) = .empty;
    defer doc.deinit(allocator);
    for (0..40) |i| {
        const b = try std.fmt.allocPrint(
            allocator,
            "{{\"type\":\"user\",\"message\":{{\"content\":[{{\"type\":\"text\",\"text\":\"n{d}\"}},{{\"type\":\"image\",\"source\":{{\"type\":\"base64\",\"media_type\":\"image/png\",\"data\":\"{s}\"}}}}]}}}}\n",
            .{ i, png_b64 },
        );
        defer allocator.free(b);
        try doc.appendSlice(allocator, b);
    }
    try tmp.dir.writeFile(io, .{ .sub_path = "a.jsonl", .data = doc.items });
    try tmp.dir.writeFile(io, .{ .sub_path = "b.jsonl", .data = doc.items });

    var root_buf: [std.fs.max_path_bytes]u8 = undefined;
    const root = root_buf[0..try tmp.dir.realPath(io, &root_buf)];
    const path_a = try std.fmt.allocPrint(allocator, "{s}/a.jsonl", .{root});
    defer allocator.free(path_a);
    const path_b = try std.fmt.allocPrint(allocator, "{s}/b.jsonl", .{root});
    defer allocator.free(path_b);

    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(io, allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 20,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1400, 900, 1000);

    session.dock_initialized = true;
    session.chrome_minimal = false;
    session.dock.presented = true;
    session.dock.collapsed = false;
    session.dock.side = .right;
    dock_ops.setDockView(session, .image_gallery);

    const term = pane_ops.activePane(session).activeTerm();
    try std.testing.expect(term.agent_image_source.set(path_a));
    image_gallery_ops.refresh(session, false);
    {
        var spins: usize = 0;
        while (spins < 200_000 and !session.image_gallery.built) : (spins += 1) _ = session.tick() catch {};
    }

    // ── ① 자리를 **가득** 채운 채로 소스를 바꾼다(그래야 죽은 항목이 전부를 막는다).
    _ = session.tick() catch {};
    try std.testing.expectEqual(
        @as(usize, agent_image_decode_backend.max_inflight),
        session.image_gallery.pending_len,
    );

    // ── ② 다른 세션으로 갈린다 — 도는 디코드는 옛 파일의 오프셋이라 전부 취소된다.
    try std.testing.expect(term.agent_image_source.set(path_b));
    image_gallery_ops.refresh(session, false);
    {
        var spins: usize = 0;
        while (spins < 200_000 and !session.image_gallery.built) : (spins += 1) _ = session.tick() catch {};
    }

    // ── ③ 다시 채워진다. 비우지 않으면 여기서 **한 장도** 안 온다.
    {
        var spins: usize = 0;
        while (spins < 1_500_000 and session.image_gallery.tileFor(0) == null) : (spins += 1) {
            _ = session.tick() catch {};
        }
    }
    try std.testing.expect(session.image_gallery.tileFor(0) != null);
}

test "이미지 갤러리: 검색으로 걸러도 남의 그림이 안 붙는다 (IG14 적대적)" {
    // **인덱스 체계가 바뀌는 곳은 다시 훑기만이 아니다.** 검색어를 한 글자 칠 때마다 `applyFilter`
    // 가 `hits` 를 새로 만드는데, 그때 워커에 걸어 둔 것들은 **옛 인덱스**를 들고 있다. 안 버리면
    // 도는 결과가 엉뚱한 칸에 붙는다 — 게다가 그 칸의 정체까지 그 자리 것으로 적혀 `remapTiles` 가
    // 잘못된 짝을 계속 보존한다. 메타데이터로는 안 보이고 **픽셀에만** 드러나는 종류다.
    //
    // 그래서 정사각(2×2)과 가로로 긴(4×2)을 섞어 둔다. 필터 전 0 번은 정사각, 필터 뒤 0 번은
    // 가로로 긴 것이 되게 배치했으므로, 남의 그림이 붙으면 **비율**로 드러난다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const io = std.Io.Threaded.global_single_threaded.io();
    const allocator = std.testing.allocator;

    const sq_b64 = "iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAYAAABytg0kAAAAEUlEQVR4nGP4z8DwH4QZYAwAR8oH+WdZbrcAAAAASUVORK5CYII=";
    const wide_b64 = "iVBORw0KGgoAAAANSUhEUgAAAAQAAAACCAYAAAB/qH1jAAAAEklEQVR4nGP4z8DwHxkzoAsAAA8hD/EEN8afAAAAAElFTkSuQmCC";

    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var doc: std.ArrayList(u8) = .empty;
    defer doc.deinit(allocator);
    // 파일 순서 0..5. 갤러리는 **최신이 먼저**라 뒤집히므로 필터 전 0 번은 마지막 줄(`sq5`)이고,
    // "wide" 로 거르면 0 번은 `wide4` 가 된다.
    for ([_][2][]const u8{
        .{ "wide0", wide_b64 },
        .{ "sq1", sq_b64 },
        .{ "wide2", wide_b64 },
        .{ "sq3", sq_b64 },
        .{ "wide4", wide_b64 },
        .{ "sq5", sq_b64 },
    }) |entry| {
        const b = try std.fmt.allocPrint(
            allocator,
            "{{\"type\":\"user\",\"message\":{{\"content\":[{{\"type\":\"text\",\"text\":\"{s}\"}},{{\"type\":\"image\",\"source\":{{\"type\":\"base64\",\"media_type\":\"image/png\",\"data\":\"{s}\"}}}}]}}}}\n",
            .{ entry[0], entry[1] },
        );
        defer allocator.free(b);
        try doc.appendSlice(allocator, b);
    }
    try tmp.dir.writeFile(io, .{ .sub_path = "s.jsonl", .data = doc.items });

    var root_buf: [std.fs.max_path_bytes]u8 = undefined;
    const root = root_buf[0..try tmp.dir.realPath(io, &root_buf)];
    const path = try std.fmt.allocPrint(allocator, "{s}/s.jsonl", .{root});
    defer allocator.free(path);

    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(io, allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 20,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1400, 900, 1000);

    session.dock_initialized = true;
    session.chrome_minimal = false;
    session.dock.presented = true;
    session.dock.collapsed = false;
    session.dock.side = .right;
    dock_ops.setDockView(session, .image_gallery);

    const term = pane_ops.activePane(session).activeTerm();
    try std.testing.expect(term.agent_image_source.set(path));
    image_gallery_ops.refresh(session, false);
    {
        var spins: usize = 0;
        while (spins < 200_000 and !session.image_gallery.built) : (spins += 1) _ = session.tick() catch {};
    }
    try std.testing.expectEqual(@as(usize, 6), session.image_gallery.count());
    try std.testing.expectEqualStrings("sq5", session.image_gallery.labels.items[0].text());

    // ── ① 0 번(정사각)을 **걸어 둔 채로** 검색어를 친다. 훑기가 끝난 그 tick 이 이미 앞 칸들을
    //     워커에 걸었고, 디코드는 ms 단위라 아직 안 왔다. 여기서 한 tick 이라도 더 돌리면 그 사이
    //     수확돼 전제가 사라진다.
    try std.testing.expect(session.image_gallery.pendingContains(0));

    session.image_gallery.key_focus = true;
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'f' }, .modifiers = .{ .command = true } });
    try std.testing.expect(session.image_gallery.search_active);
    for ("wide") |c| _ = try session.handleKeyEvent(.{ .key = .{ .char = c }, .modifiers = .{} });
    try std.testing.expectEqual(@as(usize, 3), session.image_gallery.count());
    try std.testing.expectEqualStrings("wide4", session.image_gallery.labels.items[0].text());

    // ── ② 0 번 칸이 차기를 기다린다.
    {
        var spins: usize = 0;
        while (spins < 1_500_000 and session.image_gallery.tileFor(0) == null) : (spins += 1) {
            _ = session.tick() catch {};
        }
    }
    const t0 = session.image_gallery.tileFor(0) orelse return error.TestUnexpectedResult;

    // ── ③ **가로로 긴 것이어야 한다.** 걸어 둔 것을 안 버리면 옛 0 번(정사각 `sq5`)의 픽셀이
    //     여기 붙는다 — 라벨은 `wide4` 인데 그림은 `sq5` 다.
    try std.testing.expect(t0.width > t0.height);
}

test "이미지 갤러리: 크게 보기는 뷰포트만큼만 풀고, 확대하면 원본으로 올린다 (IG15)" {
    // 계약 §5.3 이 후속으로 적어 둔 자리다. 실측 최대 이미지(1440×14771 = 21.3 MP)를 열면
    // **85 MB** 를 상주·업로드해 400 px 도크에 그렸다 — 200 배 낭비다.
    //
    // 픽스처도 그 모양(세로로 긴 것)을 쓴다. 8×1600 이면 뷰포트(장변 772)에 맞춰 풀 때
    // `fitToThumbnail` 이 2 분의 1 을 고른다 — 1600/2 = 800 은 772 이상이고 1600/4 = 400 은 아래다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const io = std.Io.Threaded.global_single_threaded.io();
    const allocator = std.testing.allocator;

    // 8×1600 단색 PNG.
    const tall_b64 = "";

    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    const line = try std.fmt.allocPrint(
        allocator,
        "{{\"type\":\"user\",\"message\":{{\"content\":[{{\"type\":\"text\",\"text\":\"tall\"}},{{\"type\":\"image\",\"source\":{{\"type\":\"base64\",\"media_type\":\"image/png\",\"data\":\"{s}\"}}}}]}}}}\n",
        .{tall_b64},
    );
    defer allocator.free(line);
    try tmp.dir.writeFile(io, .{ .sub_path = "s.jsonl", .data = line });

    var root_buf: [std.fs.max_path_bytes]u8 = undefined;
    const root = root_buf[0..try tmp.dir.realPath(io, &root_buf)];
    const path = try std.fmt.allocPrint(allocator, "{s}/s.jsonl", .{root});
    defer allocator.free(path);

    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(io, allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 20,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1400, 900, 1000);

    session.dock_initialized = true;
    session.chrome_minimal = false;
    session.dock.presented = true;
    session.dock.collapsed = false;
    session.dock.side = .right;
    dock_ops.setDockView(session, .image_gallery);

    const term = pane_ops.activePane(session).activeTerm();
    try std.testing.expect(term.agent_image_source.set(path));
    image_gallery_ops.refresh(session, false);
    {
        var spins: usize = 0;
        while (spins < 200_000 and !session.image_gallery.built) : (spins += 1) _ = session.tick() catch {};
    }
    try std.testing.expectEqual(@as(usize, 1), session.image_gallery.count());

    // ── ① 열면 **뷰포트만큼만** 푼다. 원본(8×1600)이 아니라 절반이다.
    image_gallery_ops.openAt(session, 0);
    {
        var spins: usize = 0;
        while (spins < 1_500_000) : (spins += 1) {
            _ = session.tick() catch {};
            const o = session.image_gallery.open orelse break;
            if (o.pixels.len > 0) break;
        }
    }
    {
        const o = session.image_gallery.open orelse return error.TestUnexpectedResult;
        try std.testing.expectEqual(@as(u32, 4), o.width);
        try std.testing.expectEqual(@as(u32, 800), o.height);
        try std.testing.expectEqual(@as(u8, 2), o.decoded_subsample);
    }

    // ── ② 확대해서 가진 픽셀을 늘려 그리기 시작하면 **원본으로 올린다**.
    //     휠은 제품 진입점이다 — 여기를 안 타면 「그리는 자리와 눌리는 자리」가 갈릴 수 있다.
    const vp = image_gallery_ops.viewportRect(session);
    var guard: usize = 0;
    while (guard < 200) : (guard += 1) {
        const o = session.image_gallery.open orelse return error.TestUnexpectedResult;
        if (o.view.scale > 1.0) break;
        image_gallery_ops.wheelZoom(session, 3.0, false, vp.x + vp.w / 2, vp.y + vp.h / 2);
    }
    {
        const o = session.image_gallery.open orelse return error.TestUnexpectedResult;
        try std.testing.expect(o.view.scale > 1.0);
    }
    {
        var spins: usize = 0;
        while (spins < 1_500_000) : (spins += 1) {
            _ = session.tick() catch {};
            const o = session.image_gallery.open orelse break;
            if (o.decoded_subsample == 1) break;
        }
    }
    const o = session.image_gallery.open orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u32, 8), o.width);
    try std.testing.expectEqual(@as(u32, 1600), o.height);
    try std.testing.expectEqual(@as(u8, 1), o.decoded_subsample);

    // ── ③ **보던 자리를 지킨다.** 같은 그림을 더 선명하게 다시 푼 것이므로 fit 으로 되돌리면
    //     확대해 보던 사람을 처음으로 끌고 간다. 텍스처가 2 배가 됐으니 배율은 절반이 되어야
    //     화면에 그려지는 크기가 같다.
    try std.testing.expect(o.view.scale > 0);
    try std.testing.expect(o.view.scale < 1.0);
}

test "linkScopesForSurfaceId: host-backed 경로도 원격 cwd면 파일 경로 스코프를 끈다" {
    // **§9.4 의 표는 전수여야 한다.** host-backed 링크 경로 둘(`remoteLinkSpanAt` 의 hover 필터와
    // `linkAtFor` 에 넘기는 `packLinkScopes`)이 `linkScopesFromConfig` 를 직접 불러, `cwd_host` wire 가
    // 붙는 순간 그 모드에서만 차단이 빠져 있었다 — 원격 경로가 로컬 파일로 resolve 될 수 있었다
    // (ssh-integration.md §9.6 이 예고한 그대로다). 두 경로는 `Surface` 만 쥐므로 id 로 Term 을 찾는다.
    if (builtin.os.tag != .macos) return error.SkipZigTest; // 실 PTY spawn
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000);
    session.loaded_config.config.input.link_detection = .full;

    const term = pane_ops.activePane(session).activeTerm();
    const sid = term.surfaceId();

    // ── 로컬: surface 판이 Term 판과 **같은 답**을 낸다(대조군 — 이 함수가 그냥 설정을 돌려주면 안 된다).
    try term_ops.activeSurface(session).core.write("\x1b]7;file:///tmp/proj\x07");
    term_ops.refreshTermObservation(session, term, false, false);
    {
        const by_term = linkScopesForTerm(session, term);
        const by_sid = linkScopesForSurfaceId(session, sid);
        try std.testing.expectEqual(by_term, by_sid);
        try std.testing.expect(by_sid.absolute_path and by_sid.home_path);
    }

    // ── 원격: 파일 경로 4종이 꺼지고 웹·스킴은 남는다.
    try term_ops.activeSurface(session).core.write("\x1b]7;file://build-box/srv/app\x07");
    term_ops.refreshTermObservation(session, term, false, false);
    try std.testing.expect(termCwdIsRemote(term));
    {
        const by_sid = linkScopesForSurfaceId(session, sid);
        try std.testing.expect(!by_sid.absolute_path and !by_sid.bare_relative);
        try std.testing.expect(!by_sid.dot_relative and !by_sid.home_path);
        try std.testing.expect(by_sid.web and by_sid.extra_schemes);
    }

    // ── 못 찾는 id 는 설정 그대로다(닫힌 Term 의 늦은 hover 가 여기로 온다).
    {
        const unknown = linkScopesForSurfaceId(session, sid +% 4242);
        const cfg = settings_ops.linkScopesFromConfig(session);
        try std.testing.expectEqual(cfg, unknown);
    }
}

test "linkScopes 경계: 설정 스코프를 날것으로 쓰는 곳은 래퍼 둘뿐이다" {
    // **판정자만으로는 배선을 못 지킨다.** 바로 위 test 는 `linkScopesForSurfaceId` 가 원격에서 파일
    // 경로를 끄는지를 보지만, 호출부가 그 함수를 **쓰는지**는 안 본다 — 누가 `linkScopesFromConfig` 로
    // 되돌려도 그 test 는 통과한다. 실제로 host-backed 경로 둘이 그 상태로 남아 있었고, `cwd_host` wire 가
    // 붙는 순간 §9.4 의 원격 경로 차단이 그 모드에서만 빠졌다(ssh-integration.md §9.6).
    //
    // 그래서 **호출부를 세어 못 박는다.** 날것을 쓰는 자리는 래퍼 둘의 내부뿐이고, 셋째가 생기면 여기서
    // 깨져 「그 자리도 Term 을 봐야 하는가」를 반드시 묻게 된다.
    const src = @embedFile("app_session.zig");

    var raw: usize = 0;
    var i: usize = 0;
    // ⚠️ **바늘을 쪼개 둔다.** 통짜로 쓰면 이 test 의 리터럴 자신이 소스에서 한 번 더 잡혀
    // 개수가 늘 하나 많다(처음에 그렇게 «3» 이 나왔다).
    const needle = "settings_ops.linkScopesFromConfig(" ++ "self)";
    while (std.mem.indexOfPos(u8, src, i, needle)) |at| {
        raw += 1;
        i = at + needle.len;
    }
    // 1) `linkScopesForTerm` 안, 2) `linkScopesForSurfaceId` 의 «못 찾았다» 폴백.
    try std.testing.expectEqual(@as(usize, 2), raw);

    // 두 래퍼가 실제로 있는지도 함께 본다 — 이름이 바뀌면 위 개수만으로는 뜻이 없다.
    try std.testing.expect(std.mem.indexOf(u8, src, "pub fn linkScopesForTerm(") != null);
    try std.testing.expect(std.mem.indexOf(u8, src, "pub fn linkScopesForSurfaceId(") != null);
}

test "원격 커서는 hello 뒤의 줄만 믿는다 — 제한 서버 출력으로 이어읽기를 오염시키지 않는다" {
    // `ForceCommand`·`command=` 서버는 우리 명령을 **갈아치우고** 임의 출력을 낸다(계약 §8.7). 채널은
    // 그래서 `hello` 전 모든 줄을 삼키는데, 커서 기록은 채널을 안 거치고 `parseFrame` 을 직접 부르므로
    // 그 관문 **밖**이었다. 그 출력에서 커서를 믿으면 엉뚱한 offset 으로 이어읽어 진짜 이벤트를
    // 건너뛴다 — 증상은 「배지가 안 뜬다」 하나뿐이라 원인이 화면에 안 나온다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const io = std.Io.Threaded.global_single_threaded.io();
    const a = std.testing.allocator;

    test_config_text = agent_hooks_on_config;
    defer test_config_text = "";

    var session: AppSession = undefined;
    try session.init(io, a, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    const dest = "box";
    const term = pane_ops.activePane(&session).activeTerm();
    term.rt.observation.ssh_remote_dest_present = true;
    try term.rt.observation.ssh_remote_dest.appendSlice(a, dest);
    term.agent_remote_channel = maru.session.remote_agent_stream.Channel.init(0);

    var fds: [2]c_int = undefined;
    try std.testing.expectEqual(@as(c_int, 0), std.c.pipe(&fds));
    const fl = std.c.fcntl(fds[0], std.c.F.GETFL, @as(c_int, 0));
    _ = std.c.fcntl(fds[0], std.c.F.SETFL, fl | @as(c_int, @bitCast(std.posix.O{ .NONBLOCK = true })));
    const key = try a.dupe(u8, dest);
    try session.remote_agent_hosts.put(a, key, .{ .stream = .{ .pid = 0, .out_fd = fds[0] }, .install_done = true, .stream_started = true });
    const host = session.remote_agent_hosts.getPtr(dest).?;

    // ── ① `hello` **전**에 커서 모양의 줄이 와도 안 믿는다(제한 서버가 낼 수 있는 출력이다).
    const before = "{\"cur\":\"t7\",\"at\":999999}\n";
    try std.testing.expect(std.c.write(fds[1], before.ptr, before.len) > 0);
    session.drainRemoteAgentHost(dest, host, 100);
    try std.testing.expectEqual(@as(usize, 0), host.cursors.count());

    // ── ② `hello` 뒤의 같은 모양은 믿는다.
    const after = "{\"hello\":\"maru-agent-events\",\"v\":1}\n" ++ "{\"cur\":\"t7\",\"at\":68}\n";
    try std.testing.expect(std.c.write(fds[1], after.ptr, after.len) > 0);
    session.drainRemoteAgentHost(dest, host, 200);
    try std.testing.expectEqual(@as(usize, 1), host.cursors.count());
    try std.testing.expectEqual(@as(u64, 68), host.cursors.get("t7").?.offset);

    _ = std.c.close(fds[1]);
    session.closeRemoteAgentHost(dest);
}

test "원격 채널을 다시 띄우면 죽은 스트림의 반 줄을 안 물려준다" {
    // `pending` 은 개행 없이 끊긴 조각을 든다. 재기동 때 안 비우면 새 스트림의 첫 줄 앞에 그것이 붙어
    // **`hello` 가 깨진다** — 그러면 커서 관문도 채널도 영영 안 열리고, 침묵 시한 뒤 또 EOF 가 나
    // 결국 포기로 간다. 즉 **재접속이 스스로를 막는다**.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const io = std.Io.Threaded.global_single_threaded.io();
    const a = std.testing.allocator;

    test_config_text = agent_hooks_on_config;
    defer test_config_text = "";

    var session: AppSession = undefined;
    try session.init(io, a, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    const dest = "box";
    const term = pane_ops.activePane(&session).activeTerm();
    term.rt.observation.ssh_remote_dest_present = true;
    try term.rt.observation.ssh_remote_dest.appendSlice(a, dest);
    term.agent_remote_channel = maru.session.remote_agent_stream.Channel.init(0);

    var fds: [2]c_int = undefined;
    try std.testing.expectEqual(@as(c_int, 0), std.c.pipe(&fds));
    const fl = std.c.fcntl(fds[0], std.c.F.GETFL, @as(c_int, 0));
    _ = std.c.fcntl(fds[0], std.c.F.SETFL, fl | @as(c_int, @bitCast(std.posix.O{ .NONBLOCK = true })));
    const key = try a.dupe(u8, dest);
    try session.remote_agent_hosts.put(a, key, .{ .stream = .{ .pid = 0, .out_fd = fds[0] }, .install_done = true, .stream_started = true });
    const host = session.remote_agent_hosts.getPtr(dest).?;

    // ① 개행 없이 끊긴 꼬리를 남긴 채 자식이 죽는다.
    const half = "{\"hello\":\"maru-agent-eve";
    try std.testing.expect(std.c.write(fds[1], half.ptr, half.len) > 0);
    session.drainRemoteAgentHost(dest, host, 100);
    try std.testing.expect(host.pending.items.len > 0); // 꼬리가 남아 있다
    _ = std.c.close(fds[1]);
    session.drainRemoteAgentHost(dest, host, 200); // EOF → 재시도 예약

    // ② 다시 띄운다(제품과 같은 자리를 지나되 ssh 는 안 띄운다 — 파이프로 대신한다).
    var fds2: [2]c_int = undefined;
    try std.testing.expectEqual(@as(c_int, 0), std.c.pipe(&fds2));
    const fl2 = std.c.fcntl(fds2[0], std.c.F.GETFL, @as(c_int, 0));
    _ = std.c.fcntl(fds2[0], std.c.F.SETFL, fl2 | @as(c_int, @bitCast(std.posix.O{ .NONBLOCK = true })));
    host.pending.clearRetainingCapacity(); // `spawnStreamerFor` 가 하는 그 일
    host.saw_hello = false;
    host.stream = .{ .pid = 0, .out_fd = fds2[0] };
    host.stream_started = true;

    // ③ 새 스트림의 `hello` 가 **온전히** 읽힌다 — 꼬리가 남았다면 앞이 붙어 안 읽힌다.
    const fresh = "{\"hello\":\"maru-agent-events\",\"v\":1}\n" ++ "{\"cur\":\"t7\",\"at\":42}\n";
    try std.testing.expect(std.c.write(fds2[1], fresh.ptr, fresh.len) > 0);
    session.drainRemoteAgentHost(dest, host, 300);
    try std.testing.expect(host.saw_hello);
    try std.testing.expectEqual(@as(u64, 42), host.cursors.get("t7").?.offset);

    _ = std.c.close(fds2[1]);
    session.closeRemoteAgentHost(dest);
}

test "원격 폴더줄은 훅이 알려 준 cwd 를 쓴다 — OSC 7 이 멈춘 구간을 메운다" {
    // OSC 7 보고자는 `precmd` 라 **프롬프트가 그려질 때만** 발화한다. `cd proj && claude` 처럼 셸이
    // 곧바로 전면 TUI 에 자리를 내주면 그 뒤로 프롬프트가 없어 값이 접속 직전에서 멈춘다 — 에이전트
    // 세션들이 사이드바에 전부 홈으로 뜨던 모양이 이것이다(ssh-integration.md §9.5). 훅은 그 구간에도
    // 매 턴 오므로 그 값이 이 자리를 메운다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const io = std.Io.Threaded.global_single_threaded.io();
    const a = std.testing.allocator;

    const session = try a.create(AppSession);
    defer a.destroy(session);
    try session.init(io, a, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000);

    const term = pane_ops.activePane(session).activeTerm();

    // ── ① 원격 pane 이고, OSC 7 은 홈에서 멈춰 있다(전면 TUI 가 붙기 직전 값).
    try term_ops.activeSurface(session).core.write("\x1b]7;file://build-box/Users/me\x07");
    term_ops.refreshTermObservation(session, term, false, false);
    try std.testing.expect(termCwdIsRemote(term));
    {
        const shown = try sidebarCwdPath(session, term);
        defer a.free(shown);
        try std.testing.expect(std.mem.indexOf(u8, shown, "/Users/me") != null);
    }

    // ── ② 훅이 진짜 작업 디렉터리를 알려 준다 → 폴더줄이 그것으로 바뀐다.
    term.agent_hook_cwd.set("/srv/app/proj", session.awakeMs());
    {
        const shown = try sidebarCwdPath(session, term);
        defer a.free(shown);
        try std.testing.expect(std.mem.indexOf(u8, shown, "/srv/app/proj") != null);
        // host 접두는 그대로다 — 원격이라는 사실이 사라지면 §9.4 안전장치가 통째로 꺼진다.
        try std.testing.expect(std.mem.indexOf(u8, shown, "build-box:") != null);
    }

    // ── ③ **잘린 경로·상대 경로는 안 담는다.** 담으면 남의 디렉터리를 가리킨다.
    term.agent_hook_cwd.clear();
    term.agent_hook_cwd.set("relative/path", session.awakeMs());
    try std.testing.expect(term.agent_hook_cwd.isEmpty());

    // ── ④ 대조군: 로컬 pane 은 이 값을 안 본다(커널 조회가 이미 정확하다).
    try term_ops.activeSurface(session).core.write("\x1b]7;file:///tmp\x07");
    term_ops.refreshTermObservation(session, term, false, false);
    try std.testing.expect(!termCwdIsRemote(term));
    term.agent_hook_cwd.set("/srv/app/proj", session.awakeMs());
    {
        const shown = try sidebarCwdPath(session, term);
        defer a.free(shown);
        try std.testing.expect(std.mem.indexOf(u8, shown, "/srv/app/proj") == null);
    }
}

test "훅 모드를 벗어나면 그 cwd 를 버린다 — 옛 경로에 붙박이지 않는다" {
    // 안 버리면 에이전트를 끝내고 평범한 셸로 돌아온 뒤에도 폴더줄이 **옛 경로에 붙박인다** —
    // 그때부터는 OSC 7 이 제대로 갱신되는데 그것을 무시하게 되고, 그 모양이 계약 §1 이 금지하는
    // «한 Term 두 소스» 다. `agent_hook_tool` 을 버리는 그 자리에서 함께 버린다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const io = std.Io.Threaded.global_single_threaded.io();
    const a = std.testing.allocator;

    const session = try a.create(AppSession);
    defer a.destroy(session);
    try session.init(io, a, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000);

    const term = pane_ops.activePane(session).activeTerm();
    term.agent_hook_cwd.set("/srv/app/proj", session.awakeMs());
    try std.testing.expect(!term.agent_hook_cwd.isEmpty());

    // 훅 모드가 아니다(로그도 없고 에이전트도 없고 원격 채널도 없다) → 관측 모드로 내려간다.
    try std.testing.expectEqual(maru.session.agent_hook_mode.Mode.observe, agent_ops.agentHookMode(session, term));
    agent_ops.pollAgentConsumer(session, term, true, true);

    // 그 자리에서 훅이 남긴 세부가 버려진다 — cwd 도 그 목록이다.
    try std.testing.expect(term.agent_hook_cwd.isEmpty());
}

test "보고자 없는 원격도 원격으로 판정한다 — 링크가 로컬 파일을 열지 않는다 (A)" {
    // 예전에는 원격 판정의 근거가 OSC 7 authority **하나**였다. 그래서 원격 셸에 보고자를 안 깐
    // 사용자의 pane 이 **로컬로 판정**됐고, 화면의 절대 경로가 로컬 파일로 열렸다(§9.4 가 닫아 둔 길).
    // `maru ssh` 는 OSC 5379 로 목적지를 알려 주므로 그 사실을 이미 알 수 있었다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const io = std.Io.Threaded.global_single_threaded.io();
    const a = std.testing.allocator;

    const session = try a.create(AppSession);
    defer a.destroy(session);
    try session.init(io, a, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000);
    session.loaded_config.config.input.link_detection = .full;

    const term = pane_ops.activePane(session).activeTerm();

    // ── ① 로컬 셸이 보고해 둔 값이 있다(대조군: 지금은 로컬이다).
    try term_ops.activeSurface(session).core.write("\x1b]7;file:///Users/me/local\x07");
    term_ops.refreshTermObservation(session, term, false, false);
    try std.testing.expect(!termCwdIsRemote(term));

    // ── ② `maru ssh` 가 목적지를 알린다. **보고자는 없다** — 그래도 원격이다.
    //     그리고 B 가 stale 로컬 cwd 를 함께 버리므로 「원격인데 경로는 모른다」가 된다.
    try term_ops.activeSurface(session).core.write("\x1b]5379;ssh;me@build-box\x07");
    term_ops.refreshTermObservation(session, term, false, false);
    try std.testing.expect(termCwdIsRemote(term));
    try std.testing.expectEqual(@as(usize, 0), term.rt.observation.cwd.items.len);

    // 파일 경로 스코프가 꺼진다 — 이것이 이 슬라이스의 안전 이득이다.
    const scopes = linkScopesForTerm(session, term);
    try std.testing.expect(!scopes.absolute_path and !scopes.home_path);
    try std.testing.expect(!scopes.dot_relative and !scopes.bare_relative);
    try std.testing.expect(scopes.web and scopes.extra_schemes); // 웹은 남는다

    // 경로를 모르니 폴더줄은 **빈다**(거짓말하지 않는다).
    {
        const shown = try sidebarCwdPath(session, term);
        defer a.free(shown);
        try std.testing.expectEqualStrings("", shown);
    }

    // ── ③ 훅이 작업 디렉터리를 알려 주면 그때 그린다 — host 는 **목적지에서** 뽑는다.
    term.agent_hook_cwd.set("/srv/app/proj", session.awakeMs());
    {
        const shown = try sidebarCwdPath(session, term);
        defer a.free(shown);
        try std.testing.expectEqualStrings("build-box:/srv/app/proj", shown); // `me@` 는 뗀다
    }

    // ── ④ ssh 를 빠져나오면 다시 로컬이다(그 뒤 프롬프트가 cwd 를 채운다).
    try term_ops.activeSurface(session).core.write("\x1b]5379;ssh-end\x07");
    try term_ops.activeSurface(session).core.write("\x1b]7;file:///Users/me/local\x07");
    term_ops.refreshTermObservation(session, term, false, false);
    try std.testing.expect(!termCwdIsRemote(term));
    {
        const shown = try sidebarCwdPath(session, term);
        defer a.free(shown);
        try std.testing.expect(std.mem.indexOf(u8, shown, "build-box") == null);
    }
}
